             ['share' => 'Musik', 'use' => 'no', 'primary' => 'maple', 'secondary' => ''], ['share' => 'Doku', 'use' => 'prefer', 'primary' => 'bt', 'secondary' => '']];
    same('sizes live: ZFS used of <pool>/<share> on awake pools — one look per pool', [['Filme' => [['pool' => 'maple', 'used' => 5000]]], ['maple']],
