        && str_contains($src, "if (in_array(\$mode, ['run', 'measure', 'release'], true)) {") && str_contains($src, 'writeAtomic("$gatherDir/measure.ini"') && str_contains($src, 'jackGatherIniRam($text, $mode)'));

