globalThis.Office = { sections: (o) => ({ spec: o, el: {}, active: () => '', note: () => ({ tile: '' }), places: () => [], mount: () => false, pick() {}, render() {}, clear() {} }), scope: () => T, t: T, el, fmt: { size: (b) => `${b}B`, date: (t) => `D${t}`, relative: (t) => `R${t}`, number: (n) => String(n) }, desk: () => {}, places: () => {},
  placesFrom: () => {}, placesTook: () => {}, storeJson: () => null, agent: { running: true }, keepInPlace: (a, f) => f(), place: (k, n) => n,
  sectionHead: (title, sub, ...x) => el('div', 'section-head', title), fold, filterWords: (t) => fold(t).split(/\s+/).filter(Boolean),
  fits: (w, hay) => { const h = (Array.isArray(hay) ? hay.filter((x) => x != null && x !== '') : [hay]).map(fold).join('\u0001'); return w.every((x) => h.includes(x)); },
  // a stand-in for the bar (core.js Office.filterBar is tested on its own: testFilterBar)
  filterBar: (o) => { const b = { o, words: [], only: false, pick: stored[o.key + '.pick'] || '', el: el('div', 'filterbar'), opts: null, doneArgs: null,
    read() { return { words: this.words, only: this.only, pick: this.pick, tile: '' }; }, done(n, t, d) { this.doneArgs = [n, t, !!(d && d.onlyAvail !== false)]; return this; },
    options(l) { this.opts = l; return this; }, reset() { this.words = []; this.only = false; return this; }, set() { return this; }, tile() { return this; } };
    bars.push(b); return b; } };
globalThis.Office.store = function (k, v) { if (arguments.length > 1) stored[k] = v; return stored[k]; };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const e = OFFICE_DESK_TESTS.jack;
const state = JSON.parse(fs.readFileSync(process.argv[3], 'utf8'));
const g = state.cache.groups;
const W = (s) => Office.filterWords(s);
const names = (v) => v.rows.map((r) => r.title);
const out = {};
let v = e.poolView(g, { lib: '', words: [], shown: 30 });
out.all = [v.libs, v.rows.length, v.shown, names(v).slice(0, 3), names(v).slice(-3)];
v = e.poolView(g, { lib: 'Filme', words: [], shown: 30 });
out.lib = [names(v), v.shown];
out.words = ['amelie', 'film amelie', 'serie 07', 'filme zorro', 'serien disk1 zz'].map((w) => names(e.poolView(g, { lib: '', words: W(w), shown: 30 })));
out.libWords = names(e.poolView(g, { lib: 'Serien', words: W('alien'), shown: 30 }));
out.shown = [e.poolView(g, { lib: '', words: [], shown: 60 }).shown, e.poolView([], { lib: '', words: [], shown: 30 })];
out.since = names(e.poolView(g, { lib: '', words: [], since: 1035, shown: 30 }));
// the section: the library of the old key taken over once; 30 rows, «Show 13 more», the select's options; then the
// words, the library, «only new» (from the last real run's start), more
stored['jack.pool_lib'] = 'Filme';
e.setState(state);
e.bars();
const bar = bars.find((b) => b.o.key === 'jack.pool');
out.migrated = [stored['jack.pool.pick'], stored['jack.pool_lib'], bar.pick];
bar.pick = '';
const all = (n) => (typeof n === 'string' ? [] : [n, ...n.children.flatMap(all)]);
const sec = e.poolSection();
const rows = () => all(sec).filter((n) => n.className === 'row nocheck');
const more = () => all(sec).find((n) => n.tag === 'button');
const texts = (n) => (typeof n === 'string' ? [n] : [n.textContent, ...n.children.flatMap(texts)].filter(Boolean));
out.section = [rows().length, more() && more().textContent, bar.opts, texts(rows()[0]).slice(1), bar.doneArgs, sec.children.includes(bar.el), sec.id];
more().onclick();
out.more = [rows().length, more() ? more().textContent : null];
out.noSize = texts(rows().find((r) => texts(r)[0] === 'Alien') || { textContent: '', children: [] });
const change = (what) => bar.o.onChange(bar.read(), what);
bar.words = W('ZÓRRO');
change('words');
out.search = [rows().length, texts(rows()[0])[0], bar.doneArgs];
bar.words = [];
bar.pick = 'Filme';
change('pick');
out.pick = [rows().length, bar.doneArgs];
bar.pick = '';
bar.only = true;
change('only');
out.only = [rows().length, texts(rows()[0])[0], texts(rows()[rows().length - 1])[0]];
bar.only = false;
bar.words = W('nothing-like-this');
change('words');
out.empty = all(sec).filter((n) => n.className === 'empty').map((n) => n.textContent);
bar.words = [];
state.history = [state.history[0]];               // a report only: no real run — «only new» has nothing to go by
e.setState(state);
e.poolSection();
out.noReal = bar.doneArgs[2];
out.keys = Object.keys(stored).filter((k) => k.startsWith('jack.')).sort();
console.log(JSON.stringify(out));
JS);
    $cmd = implode(' ', array_map('escapeshellarg', [$node, "$tmp/t.js", OFFICE_WEB . '/desks/jack/desk.js', "$tmp/state.json"])) . ' 2>&1';
    $raw = (string) shell_exec($cmd);
    $r = json_decode($raw, true);
    same('pool view: the libraries with counts, newest first, those without a time by name at the end, 30 shown', [[['Filme', 3], ['Serien', 40]], 43, 30,
        ['Serie.40', 'Serie.39', 'Serie.38'], ['Amélie.2001', 'Alien', 'Zorro']], $r['all'] ?? null, $raw);
    same('pool view: one library', [['Amélie.2001', 'Alien', 'Zorro'], 3], $r['lib'] ?? null, $raw);
    same('pool view: the words — a name without accents, a library and a name, a name with dots as spaces, a library and a name, a word that meets nothing',
        [['Amélie.2001'], ['Amélie.2001'], ['Serie.07'], ['Zorro'], []], $r['words'] ?? null, $raw);
    same('pool view: the words within the library', [], $r['libWords'] ?? null, $raw);
    same('pool view: more shown; nothing there', [43, ['libs' => [], 'rows' => [], 'shown' => 0]], $r['shown'] ?? null, $raw);
    same('pool view: «only new» — what came onto the pool from then on', ['Serie.40', 'Serie.39', 'Serie.38', 'Serie.37', 'Serie.36', 'Serie.35'], $r['since'] ?? null, $raw);
    same('pool page: the library of the old key taken over once (the old key gone), the bar starts with it', ['Filme', null, 'Filme'], $r['migrated'] ?? null, $raw);
    same('pool page: 30 rows, «Show 13 more», the select with counts, a row: library, files, size beside them, since when; «43 of 43», the switch there; the bar in the section', [30,
        'pool.more {"n":13}', [['Filme', 'Filme', 3], ['Serien', 'Serien', 40]],
        ['Serien', 'files_n {"n":16}', '40000B', 'pool.since {"date":"D1040"}'], [43, 43, true], true, 'jo-pool'], $r['section'] ?? null, $raw);
    same('pool page: a row of an older agent — no size, no time', ['Alien', 'Filme', 'files_n {"n":2}'], $r['noSize'] ?? null, $raw);
    same('pool page: «Show more» — all 43, no button left', [43, null], $r['more'] ?? null, $raw);
    same('pool page: the words narrow it (accents folded, «1 of 43»)', [1, 'Zorro', [1, 43, true]], $r['search'] ?? null, $raw);
    same('pool page: the library narrows it', [3, [3, 43, true]], $r['pick'] ?? null, $raw);
    same('pool page: «only new» — what the last real run brought (from its start on, a later report doesn\'t count)', [11, 'Serie 40', 'Serie 30'], $r['only'] ?? null, $raw);
    same('pool page: nothing fits', ['pool.empty_filter'], $r['empty'] ?? null, $raw);
    same('pool page: no real run — «only new» goes (onlyAvail false)', false, $r['noReal'] ?? null, $raw);
    same('pool page: only the choices are kept (the pool section open or not, the library) — never words or «only new»', ['jack.pool.pick', 'jack.pool_lib'], $r['keys'] ?? null, $raw);
    hardeningRm($tmp);
}

/**
 * Jack takes over an earlier install of helmi1987's tools (fixtures shaped like EmbyCache 7.2.1
 * and setup_consolidate.sh V11 write them) on a fake server tree: the folder's checks (links,
 * "..", outside, asleep), unknown and new keys, the API key never in an answer to the page, the
 * list and origins merged with Jack's own, bad lines left out, the copies made, the gather's ini.
 */
function testJackImport(): void
{
    $tmp = hardeningTmp('jackimport');
    $fs = "$tmp/fs";                      // the fake server: /mnt and /boot below it
    $pool = "$tmp/pool";                  // EmbyCache's pool (load_config() wants a real folder)
    $key = 'FakeKey0123456789abcdefFAKEKEY99';
    $jackKey = 'JackOwnKey0123456789JACKKEY0000';
    foreach (['mnt/user/system/scripts/embycache', 'mnt/user/system/scripts/consolidate', 'mnt/user/system/scripts/badfile',
              'mnt/user/Filme', 'mnt/cache/appdata/old', 'mnt/hazel/x', 'boot/config/plugins/user.scripts/scripts/old-embycache',
              'mnt/cache/appdata/UnraidSecretaryOffice/data/embycache', 'mnt/cache/appdata/UnraidSecretaryOffice/data/gather', 'pool', 'run'] as $d) {
        @mkdir(str_starts_with($d, 'pool') || $d === 'run' ? "$tmp/$d" : "$fs/$d", 0700, true);
    }
    symlink('../cache/appdata', "$fs/mnt/user/appdata");                         // an exclusive share, Unraid's own link
    symlink('/tmp', "$fs/mnt/user/linked");                                      // any other link
    symlink('embycache', "$fs/mnt/user/system/scripts/lnk");
    symlink('/etc/hostname', "$fs/mnt/user/system/scripts/badfile/mediacache_settings.json");
    file_put_contents("$fs/mnt/user/system/scripts/notes.txt", 'x');
    @mkdir("$fs/mnt/user/system/scripts/hardlink", 0700);
    link("$fs/mnt/user/system/scripts/notes.txt", "$fs/mnt/user/system/scripts/hardlink/consolidate.ini");
    $jack = "$fs/mnt/cache/appdata/UnraidSecretaryOffice/data";
    $ctx = ['jack_dir' => "$jack/embycache", 'gather_dir' => "$jack/gather", 'tmp' => "$tmp/run", 'fs' => $fs,
            'pools' => ['/mnt/cache', '/mnt/hazel', $pool], 'shares' => ['Filme', 'Serien', 'system', 'appdata', 'Sleepy'],
            'asleep' => ['disk1' => false, 'disk2' => true, 'cache' => false, 'hazel' => true],
            'share_cfg' => fn (string $s): array => ['Filme' => ['shareUseCache' => 'yes', 'shareCachePool' => 'cache', 'shareInclude' => 'disk1'],
                                                      'Serien' => ['shareUseCache' => 'yes', 'shareCachePool' => 'cache', 'shareInclude' => 'disk1'],
                                                      'system' => ['shareUseCache' => 'only', 'shareCachePool' => 'cache'],
                                                      'appdata' => ['shareUseCache' => 'only', 'shareCachePool' => 'cache'],
                                                      'linked' => ['shareUseCache' => 'only', 'shareCachePool' => 'cache'],
                                                      'Sleepy' => ['shareUseCache' => 'no', 'shareInclude' => 'disk2']][$s] ?? [],   // no cfg: the array
            'defaults' => null];
    $err = function (callable $f): string {
        try {
            $f();
            return 'none';
        } catch (Problem $p) {
            return $p->key;
        }
    };

    // the folder: absolute, no "..", in the allowed places, awake, real folders only
    $old = '/mnt/user/system/scripts/embycache';
    same('import folder: a share folder', "$fs$old", jackImportFolder("$old/", $ctx));
    same('import folder: through an exclusive share\'s link to its pool', "$fs/mnt/cache/appdata/old", jackImportFolder('/mnt/user/appdata/old', $ctx));
    same('import folder: User Scripts on the flash', "$fs/boot/config/plugins/user.scripts/scripts/old-embycache",
        jackImportFolder('/boot/config/plugins/user.scripts/scripts/old-embycache', $ctx));
    foreach (['relative/embycache' => 'jack_import_folder', '/mnt/user/system/../system/scripts/embycache' => 'jack_import_folder',
              '/mnt/user/system/./scripts' => 'jack_import_folder', "/mnt/user/sys\ntem" => 'jack_import_folder',
              '/etc' => 'jack_import_where', '/mnt/user0/system' => 'jack_import_where', '/mnt/disks/usb' => 'jack_import_where',
              '/mnt/user' => 'jack_import_where', '/boot/config/plugins/user.scripts/scripts' => 'jack_import_where', '/tmp/x' => 'jack_import_where',
              '/mnt/user/linked' => 'jack_import_link', '/mnt/user/linked/x' => 'jack_import_link', '/mnt/user/system/scripts/lnk' => 'jack_import_link',
              '/mnt/user/Sleepy/old' => 'jack_import_asleep', '/mnt/hazel/x' => 'jack_import_asleep', '/mnt/disk2/scripts' => 'jack_import_asleep',
              '/mnt/user/system/nothing' => 'jack_import_missing', '/mnt/user/system/scripts/badfile/mediacache_settings.json' => 'jack_import_link',
              '/mnt/user/Nocfg/old' => 'jack_import_asleep', '/mnt/user/system/scripts/notes.txt' => 'jack_import_missing',
              '/mnt/user/appdata/UnraidSecretaryOffice/data/embycache' => 'jack_import_own'] as $path => $want) {
        same('import folder refused: ' . json_encode($path), $want, $err(fn () => jackImportFolder($path, $ctx)));
    }
    same('import: a file that is a link is refused', 'jack_import_file', $err(fn () => jackImportPlan('/mnt/user/system/scripts/badfile', '', $ctx)));
    same('import: a file with a second hard link is refused', 'jack_import_file', $err(fn () => jackImportPlan('', '/mnt/user/system/scripts/hardlink', $ctx)));
    same('import: an empty folder has nothing', 'jack_import_none', $err(fn () => jackImportPlan('/mnt/user/Filme', '', $ctx)));
    same('import: no folder typed', 'jack_import_nothing', $err(fn () => jackImportFolders(['embycache' => ' ', 'gather' => ''])));

    // the old install: EmbyCache 7.2.1's settings (every key of its DEFAULTS), its list, our origins
    $settings = ['cache_path' => "$pool/", 'array_path' => '/mnt/user0/', 'user_path' => '/mnt/user', 'array_disks_glob' => '/mnt/disk[0-9]*',
        'array_source' => 'user0',
        'instances' => [['servername' => 'HomeServer', 'url' => 'http://192.168.20.10:8096', 'api_key' => $key,
                         'path_mappings' => ['/media/Serien' => '/mnt/user/Serien', '/media/Musik' => '', '/media/bad' => '/mnt/user/../etc',
                                             '/media/Gone' => '/mnt/user/Gone/Filme', '/media/Filme' => '/mnt/user/Filme/']]],
        'path_mappings' => ['/media/Filme' => '/mnt/user/Oops'], 'libraries' => ['Filme', 'Serien'],
        'valid_users' => ['u1' => ['budget' => '300 g'], 'bad id!' => [], 'u2' => [], 'u3' => ['budget' => 'lots']],
        'number_episodes' => 3, 'cache_budget' => '2.5t', 'movie_share_percent' => 50, 'max_episodes_per_series' => 0, 'max_resume_items' => 8,
        'max_favorite_series' => 10, 'use_next_up' => true, 'min_free_percent' => 15, 'movie_mode' => 'folder', 'create_share_root' => false,
        'mover_bin' => '/mnt/user/system/evil.sh', 'mover_debug_level' => 0, 'rsync_args' => ['-aAX', '--numeric-ids', '--rsh=sh -c reboot'],
        'fill_tool' => 'rsync', 'cleanup_tool' => 'mover', 'api_timeout' => 10, 'shares_cfg_dir' => '/boot/config/shares',
        'old_option' => 1, 'emby_token' => $key];
    $dir = "$fs$old";
    file_put_contents("$dir/mediacache_settings.json", json_encode($settings, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
    file_put_contents("$dir/mediacache_exclude.txt", implode("\n", ["$pool/Filme/Alien (1979)/Alien.mkv", "$pool/Serien/X/S01/e1.mkv",
        "$pool/Serien/X/S01/e1.mkv", "/mnt/other/Filme/x.mkv", "$pool/Filme/../../etc/passwd", "$pool/NoShare/x.mkv", 'relative.mkv',
        "$pool/Filme", "$pool/Filme/a\x01b.mkv", '', "  $pool/Filme/Brazil/Brazil.mkv  "]) . "\n");
    file_put_contents("$dir/mediacache_origin.json", json_encode(["$pool/Filme/Alien (1979)/Alien.mkv" => 'disk1', "$pool/Serien/X/S01/e1.mkv" => 'disk2',
        "$pool/Filme/../x.mkv" => 'disk1', "$pool/Filme/y.mkv" => 'cache', "$pool/Filme/z.mkv" => 3], JSON_UNESCAPED_SLASHES));
    // the gather, as setup_consolidate.sh V11 writes it — plus a list over two lines, a key it never had, a command
    file_put_contents("$fs/mnt/user/system/scripts/consolidate/consolidate.ini", implode("\n", [
        '# consolidate.ini – erzeugt von setup_consolidate.sh (V11)',
        "BASE_DIRS=('/mnt/user/Filme' '/mnt/user/Serien/'",
        "  '/mnt/user/Filme/Sub' \"/mnt/user/Gone\" '/data/x') # the shares",
        "LOGFILE='/mnt/user/PlexMedia/consolidate.log'", '', '# Disks', "ARRAY_PATTERN='/mnt/disk[0-9]*'", "CACHE_PATTERN='/mnt/cache /mnt/nvme'", '',
        "EXCLUDE_FILE='/mnt/user/system/my-excludes.txt'", 'DRYRUN=false', 'MIN_FREE_GB=300', '',
        "CACHE_ONLY_TARGET='most-free'", "DUP_CHECK='cmp'", 'FOO=bar', 'echo $(reboot)', 'EVIL="$(reboot)"']) . "\n");
    // what Jack has already: his own settings (another key), a list and origins
    @mkdir("$jack/embycache", 0700, true);
    @mkdir("$jack/gather", 0700, true);
    $mine = ['cache_path' => $pool, 'instances' => [['servername' => 'Emby', 'url' => 'http://192.168.20.10:8096', 'api_key' => $jackKey,
             'path_mappings' => ['/media/Filme' => '/mnt/user/Filme']]], 'min_free_percent' => 20, 'library_types' => ['Filme' => 'movies', 'Musik' => 'music'],
             'cleanup_tool' => 'rsync', 'max_resume_movies' => 1];
    file_put_contents("$jack/embycache/mediacache_settings.json", json_encode($mine, JSON_UNESCAPED_SLASHES));
    file_put_contents("$jack/embycache/mediacache_exclude.txt", "$pool/Filme/Alien (1979)/Alien.mkv\n$pool/Filme/Jack Own/j.mkv\n");
    file_put_contents("$jack/embycache/mediacache_origin.json", json_encode(["$pool/Filme/Jack Own/j.mkv" => 'disk3', "$pool/Filme/Alien (1979)/Alien.mkv" => 'disk4'], JSON_UNESCAPED_SLASHES));
    file_put_contents("$jack/gather/gather.json", json_encode(['shares' => ['Filme'], 'min_free_gb' => 256, 'dup_check' => 'size']));

    $plan = jackImportPlan("$old/", '/mnt/user/system/scripts/consolidate', $ctx);
    $p = $plan['preview'];
    $e = $p['embycache'];
    $json = json_encode($p, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    check('import preview: the old API key never in it', !str_contains($json, $key), $json);
    check('import preview: Jack\'s own API key never in it', !str_contains($json, $jackKey));
    same('import preview: the files found (an old origin list no longer taken over, 1.65.0)', ['settings' => true, 'exclude' => true], $e['found']);
    same('import preview: nothing stops it', [[], []], [$e['blockers'], $p['gather']['blockers']]);
    check('import preview: ready, with a token', $p['ready'] === true && strlen($p['token']) === 40);
    same('import preview: the key found (no value)', 'found', $e['instances'][0]['key']);
    same('import preview: keys this version doesn\'t know — names only', ['old_option', 'emby_token'], $e['dropped']);
    // keys 7.2.1 didn't have: Jack's current value stays; without one, Jack's own default (max_resume_*: the old max_resume_items)
    same('import preview: keys the old install lacks — Jack\'s value stays, else his default',
        [['key' => 'max_resume_movies', 'kept' => true, 'value' => 1], ['key' => 'max_resume_series', 'kept' => false, 'value' => 8],
        ], $e['defaults']);
    $jackSet = array_column($e['jack'], 'new', 'key');
    same('import preview: Jack\'s values for what runs or isn\'t valid', ['mover_bin' => '', 'rsync_args' => ['-aAX', '--numeric-ids']],
        array_intersect_key($jackSet, ['mover_bin' => 1, 'rsync_args' => 1]));
    check('import preview: array_path with a slash is no change', !isset($jackSet['array_path']));
    same('import preview: the old «mover» way back is MediaCache\'s own — no change; rsync filling no change', ['cleanup_tool' => null, 'fill' => false],
        ['cleanup_tool' => $jackSet['cleanup_tool'] ?? null, 'fill' => isset($jackSet['fill_tool'])]);
    $changes = array_column($e['changes'], null, 'key');
    same('import preview: a change, old → new', ['key' => 'min_free_percent', 'old' => 20, 'new' => 15], $changes['min_free_percent'] ?? null);
    same('import preview: a key Jack didn\'t have', ['old' => null, 'new' => '2.5T'], array_intersect_key($changes['cache_budget'] ?? [], ['old' => 1, 'new' => 1]));
    same('import preview: the mappings, the server\'s own over the old global one', [['/media/Filme', '/mnt/user/Filme', true], ['/media/Serien', '/mnt/user/Serien', true],
        ['/media/Musik', '', true], ['/media/Gone', '/mnt/user/Gone/Filme', false]],
        array_map(fn ($m) => [$m['from'], $m['to'], $m['there']], $e['instances'][0]['mappings']));
    same('import preview: a mapping out of the shares left out', ['/media/bad'], $e['instances'][0]['bad_mappings']);
    same('import preview: people', ['n' => 3, 'budgets' => 1, 'bad' => 2], $e['users']);
    same('import preview: the list', ['lines' => 10, 'ok' => 3, 'bad' => 6, 'already' => 1, 'mine' => 2, 'total' => 4],
        array_diff_key($e['exclude'], ['bad_sample' => 1]));
    check('import preview: no origins any more', !array_key_exists('origin', $e));
    $g = $p['gather'];
    same('import preview: the gather\'s shares', ['Filme', 'Serien'], $g['shares']);
    same('import preview: shares left out and why', [['/mnt/user/Filme/Sub', 'not_share'], ['/mnt/user/Gone', 'missing'], ['/data/x', 'outside']],
        array_map(fn ($d) => [$d['path'], $d['why']], $g['dropped_shares']));
    same('import preview: the gather\'s unknown keys', ['FOO'], $g['dropped']);
    same('import preview: lines not understood (a command, a $(…))', 2, $g['strange']);
    same('import preview: the gather\'s changes (a gather.json from before #14 counts as cache off, «leave them»; the old ini has no MOVE_CACHE)',
        [['shares', '["Filme"]', '["Filme","Serien"]'], ['min_free_gb', 256, 300], ['dup_check', 'size', 'cmp'], ['cache_only_target', 'skip', 'most-free']],
        array_map(fn ($c) => [$c['key'], $c['old'], $c['new']], $g['changes']));
    same('import preview: what Jack sets himself', ['LOGFILE', 'EXCLUDE_FILE', 'DRYRUN', 'CACHE_PATTERN'], array_column($g['jack'], 'key'));
    same('import preview: own exclusions of the old gather said', ['gather_exclude'], array_column($g['warnings'], 'key'));

    // the import: something changed since the preview → refused; then done, with copies of Jack's files
    $again = jackImportPlan($old, '/mnt/user/system/scripts/consolidate', $ctx);
    same('import: the same look gives the same token', $p['token'], $again['preview']['token']);
    file_put_contents("$jack/embycache/mediacache_exclude.txt", "$pool/Filme/Jack Own/j.mkv\n$pool/Filme/Alien (1979)/Alien.mkv\n$pool/Filme/New/n.mkv\n");
    check('import: Jack\'s list changed meanwhile — another token', jackImportPlan($old, '/mnt/user/system/scripts/consolidate', $ctx)['preview']['token'] !== $p['token']);
    $plan = jackImportPlan($old, '/mnt/user/system/scripts/consolidate', $ctx);
    $before = ['settings' => file_get_contents("$jack/embycache/mediacache_settings.json"), 'exclude' => file_get_contents("$jack/embycache/mediacache_exclude.txt"),
               'gather' => file_get_contents("$jack/gather/gather.json")];
    $done = jackImportApply($plan['do'], $ctx);
    check('import done: the API key never in the answer', !str_contains(json_encode(jackImportScrub($done, $plan['secrets'])), $key));
    $copies = array_map(fn ($f) => basename($f), $done['backups']);
    same('import done: copies of Jack\'s files', array_map(fn ($n) => "$n.before-import-{$done['stamp']}",
        ['mediacache_settings.json', 'mediacache_exclude.txt', 'gather.json', 'consolidate.ini'])[0], $copies[0] ?? null);
    same('import done: copies of all four (consolidate.ini only if it was there)', 3, count($copies));
    same('import done: the copies hold what Jack had', $before, [
        'settings' => (string) @file_get_contents("$jack/embycache/mediacache_settings.json.before-import-{$done['stamp']}"),
        'exclude' => (string) @file_get_contents("$jack/embycache/mediacache_exclude.txt.before-import-{$done['stamp']}"),
        'gather' => (string) @file_get_contents("$jack/gather/gather.json.before-import-{$done['stamp']}")]);
    same('import done: copies are root\'s only', '600', substr(sprintf('%o', fileperms($done['backups'][0])), -3));
    $s = json_decode((string) file_get_contents("$jack/embycache/mediacache_settings.json"), true);
    same('import done: the old key stays on the server', $key, $s['instances'][0]['api_key'] ?? null);
    same('import done: settings as shown (the way back MediaCache\'s move binary, filling rsync)',
        [$pool, 15, '', ['-aAX', '--numeric-ids'], false, '/mnt/user0', '2.5T', [], 1, 8, 'mover', 'rsync'],
        [$s['cache_path'], $s['min_free_percent'], $s['mover_bin'], $s['rsync_args'], array_key_exists('return_to_origin', $s), $s['array_path'], $s['cache_budget'], $s['path_mappings'],
         $s['max_resume_movies'], $s['max_resume_series'], $s['cleanup_tool'], $s['fill_tool']]);
    check('import done: unknown keys gone', !isset($s['old_option']) && !isset($s['emby_token']));
    same('import done: people with their budget', ['u1' => ['budget' => '300G'], 'u2' => [], 'u3' => []], $s['valid_users']);
    same('import done: library types kept where the name matches', ['Filme' => 'movies'], $s['library_types']);
    same('import done: Jack\'s list and the old one, merged', ["$pool/Filme/Alien (1979)/Alien.mkv", "$pool/Filme/Brazil/Brazil.mkv", "$pool/Filme/Jack Own/j.mkv",
        "$pool/Filme/New/n.mkv", "$pool/Serien/X/S01/e1.mkv"], file("$jack/embycache/mediacache_exclude.txt", FILE_IGNORE_NEW_LINES));
    same('import done: Jack\'s own origin file untouched (no longer used)', ["$pool/Filme/Jack Own/j.mkv" => 'disk3', "$pool/Filme/Alien (1979)/Alien.mkv" => 'disk4'],
        json_decode((string) file_get_contents("$jack/embycache/mediacache_origin.json"), true));
    same('import done: the gather\'s settings', ['shares' => ['Filme', 'Serien'], 'min_free_gb' => 300, 'dup_check' => 'cmp', 'move_cache' => false, 'cache_only_target' => 'most-free'],
        json_decode((string) file_get_contents("$jack/gather/gather.json"), true));
    $ini = (string) file_get_contents("$jack/gather/consolidate.ini");
    check('import done: the gather\'s ini is Jack\'s', str_contains($ini, "BASE_DIRS=('/mnt/user/Filme' '/mnt/user/Serien')\n") && str_contains($ini, "DRYRUN=true\n")
        && str_contains($ini, "MIN_FREE_GB=300\n") && str_contains($ini, "EXCLUDE_FILE='$jack/embycache/mediacache_exclude.txt'\n")
        && str_contains($ini, "MOVE_CACHE=false\n") && str_contains($ini, "CACHE_ONLY_TARGET='most-free'\n"), $ini);
    same('import done: nothing left in the trial folder', [], glob("$tmp/run/*") ?: []);

    // the cache switch (#14): an old ini that has MOVE_CACHE — taken over; one Jack can't read — his value stays, said
    $oldIni = "$fs/mnt/user/system/scripts/consolidate/consolidate.ini";
    $keep = (string) file_get_contents($oldIni);
    $cachePv = function (string $move, string $target) use ($oldIni, $ctx): array {
        file_put_contents($oldIni, "BASE_DIRS=('/mnt/user/Filme')\nMIN_FREE_GB=300\nDUP_CHECK='cmp'\nMOVE_CACHE=$move\nCACHE_ONLY_TARGET='$target'\n");
        $plan = jackImportPlan('', '/mnt/user/system/scripts/consolidate', $ctx);
        return [array_map(fn ($c) => [$c['key'], $c['old'], $c['new']], $plan['preview']['gather']['changes']),
                array_map(fn ($c) => [$c['key'], $c['old'], $c['new']], $plan['preview']['gather']['jack']),
                array_intersect_key($plan['do']['gather'] ?? [], ['move_cache' => 1, 'cache_only_target' => 1])];
    };
    same('import, the cache: MOVE_CACHE=true and «skip» taken over', [[['shares', '["Filme","Serien"]', '["Filme"]'], ['move_cache', false, true],
        ['cache_only_target', 'most-free', 'skip']], [], ['move_cache' => true, 'cache_only_target' => 'skip']], $cachePv('true', 'skip'));
    same('import, the cache: values Jack can\'t read — his own stay, said as his', [[['shares', '["Filme","Serien"]', '["Filme"]']],
        [['MOVE_CACHE', 'yes', false], ['CACHE_ONLY_TARGET', 'disk9', 'most-free']], ['move_cache' => false, 'cache_only_target' => 'most-free']], $cachePv('yes', 'disk9'));
    file_put_contents($oldIni, $keep);

    // an older install without cleanup_tool / mover_debug_level: Jack's choices stay; a Jack without settings gets his own
    // defaults (rsync back, as his setup page), never EmbyCache's original mover default
    $older = $settings;
    unset($older['cleanup_tool'], $older['mover_debug_level']);
    file_put_contents("$dir/mediacache_settings.json", json_encode($older, JSON_UNESCAPED_SLASHES));
    $withJack = ['jack_dir' => "$tmp/jack2/embycache", 'gather_dir' => "$tmp/jack2/gather"] + $ctx;
    @mkdir("$tmp/jack2/embycache", 0700, true);
    file_put_contents("$tmp/jack2/embycache/mediacache_settings.json", json_encode(['cache_path' => $pool, 'cleanup_tool' => 'rsync', 'mover_debug_level' => 1,
        'max_resume_series' => 4, 'max_resume_movies' => null, 'mover_bin' => '/mnt/user/x.sh', 'array_path' => '/mnt/elsewhere'], JSON_UNESCAPED_SLASHES));
    $d = array_column(jackImportPlan($old, '', $withJack)['preview']['embycache']['defaults'], null, 'key');
    same('import, older install: Jack\'s own choices stay (the way back always MediaCache\'s move binary — his, not a choice kept)',
        [['cleanup_tool', false, 'mover'], ['mover_debug_level', true, 1], ['max_resume_series', true, 4]],
        array_map(fn ($k) => [$k, $d[$k]['kept'] ?? null, $d[$k]['value'] ?? null], ['cleanup_tool', 'mover_debug_level', 'max_resume_series']));
    same('import, older install: a null of Jack\'s is no value — his default', [false, 8], [$d['max_resume_movies']['kept'] ?? null, $d['max_resume_movies']['value'] ?? null]);
    $d = array_column(jackImportPlan($old, '', ['jack_dir' => "$tmp/nojack/embycache", 'gather_dir' => "$tmp/nojack/gather"] + $ctx)['preview']['embycache']['defaults'], null, 'key');
    same('import, older install, Jack without settings: his defaults (MediaCache\'s own way back)', [['cleanup_tool', false, 'mover'], ['mover_debug_level', false, 0]],
        array_map(fn ($k) => [$k, $d[$k]['kept'] ?? null, $d[$k]['value'] ?? null], ['cleanup_tool', 'mover_debug_level']));
    unset($older['mover_bin'], $older['array_path']);
    file_put_contents("$dir/mediacache_settings.json", json_encode($older, JSON_UNESCAPED_SLASHES));
    $d = array_column(jackImportPlan($old, '', $withJack)['preview']['embycache']['defaults'], null, 'key');
    same('import, older install: a strange mover_bin or Unraid path of Jack\'s never stays', [[false, ''], [false, '/mnt/user0']],
        [[$d['mover_bin']['kept'] ?? null, $d['mover_bin']['value'] ?? null], [$d['array_path']['kept'] ?? null, $d['array_path']['value'] ?? null]]);

    // what stops it: a pool this server lacks, no key (and none of Jack's for that address), EmbyCache saying no
    $bad = $settings;
    $bad['cache_path'] = '/mnt/nowhere';
    $bad['instances'][0]['api_key'] = 'short';
    $bad['instances'][0]['url'] = 'http://elsewhere:8096';
    file_put_contents("$dir/mediacache_settings.json", json_encode($bad, JSON_UNESCAPED_SLASHES));
    $b = jackImportPlan($old, '', $ctx)['preview'];
    same('import blocked: a strange pool, no key', ['pool', 'no_key'], array_column($b['embycache']['blockers'], 'key'));
    check('import blocked: not ready', $b['ready'] === false);
    check('import blocked: the strange key never in the preview', !str_contains(json_encode($b), 'short'));
    $bad['instances'][0]['url'] = 'http://192.168.20.10:8096';                    // Jack has a key for that address
    $bad['cache_path'] = $pool;
    $bad['movie_mode'] = 'chaos';
    $bad['max_resume_items'] = 'many';                                         // EmbyCache's own check refuses it
    file_put_contents("$dir/mediacache_settings.json", json_encode($bad, JSON_UNESCAPED_SLASHES));
    $b = jackImportPlan($old, '', $ctx)['preview'];
    same('import: no key in the old file — Jack keeps his own', 'jack', $b['embycache']['instances'][0]['key']);
    same('import: a choice EmbyCache doesn\'t know is Jack\'s', 'folder', array_column($b['embycache']['jack'], 'new', 'key')['movie_mode'] ?? null);
    check('import: Jack\'s key never in the preview either', !str_contains(json_encode($b), $jackKey));
    $bad['instances'][0]['path_mappings'] = ['/media/Musik' => ''];            // nothing cached at all: EmbyCache's load_config() says no
    $bad['path_mappings'] = [];
    file_put_contents("$dir/mediacache_settings.json", json_encode($bad, JSON_UNESCAPED_SLASHES));
    $b = jackImportPlan($old, '', $ctx)['preview'];
    same('import blocked: EmbyCache\'s own check says no', ['config'], array_column($b['embycache']['blockers'], 'key'));
    check('import blocked: its reason told', str_contains((string) ($b['embycache']['blockers'][0]['params']['detail'] ?? ''), 'path_mappings'));
    file_put_contents("$dir/mediacache_settings.json", '[1, 2]');
    same('import blocked: settings that aren\'t an object', ['bad_json'], array_column(jackImportPlan($old, '', $ctx)['preview']['embycache']['blockers'], 'key'));

    // the ini is read, never run
    [$vars, $strange] = jackImportIni("A='it'\\''s' # c\nB=\"x \\\"y\\\"\"\nC=( 'a b'\n# a comment\n c )\nD=(a *)\nE=plain\nF=\nG=a b\nH=\"\$HOME\"\nI=( ~/x )\nJ=#x\n");
    same('import ini: values as bash sees them, nothing expanded', ['A' => "it's", 'B' => 'x "y"', 'C' => ['a b', 'c'], 'E' => 'plain', 'F' => '', 'J' => '#x'], $vars);
    same('import ini: globs, commands, variables refused', 4, $strange);
    hardeningRm($tmp);
}

/**
 * Letting Jack Emby go (2026-10-09; agent/desks/jack-letgo.php): both schedules off — always, no tick — his lines
 * only (Mr. Backupsy's stays); the look (what is on the pool, a run going, someone watching — read only; Mover Tuning is
 * never his business any more, 2026-10-12); jack.letgo needs `confirm` and `release` said, is refused for an unhired Jack (the hired gate) and changes
 * nothing then; the tick's release handed to atd as `job embycache release --letgo` — refused while a run is going or
 * someone watches (his list of runs says so); the note for his page when hired again, said once; EmbyCache's own
 * `--release` on a fixture tree (everything on the list back the cleanup's way, a duplicate stays and stays listed,
 * nothing filled); the release's notifications; his dialog part, the done dialog and the page's note under node.
 */
function testJackLetGo(): void
{
    $tmp = hardeningTmp('jackletgo');
    $dir = "$tmp/emby";
    $pool = "$tmp/pool";
    foreach (["$dir", "$pool/Filme/A", "$pool/Filme/B"] as $d) {
        mkdir($d, 0700, true);
    }
    file_put_contents("$pool/Filme/A/a.mkv", str_repeat('a', 3000));
    file_put_contents("$pool/Filme/B/b.mkv", str_repeat('b', 5000));
    file_put_contents("$dir/mediacache_exclude.txt", "$pool/Filme/A/a.mkv\n$pool/Filme/B/b.mkv\n$pool/Filme/gone.mkv\n/elsewhere/x.mkv\n");
    $cron = "$tmp/office.cron";
    officeJobSetSchedule('backup', '0 2 * * *', $cron, false);
    officeJobSetSchedule('embycache', '15 * * * *', $cron, false);
    officeJobSetSchedule('gather', '0 3 * * 0', $cron, false);
    $settings = ['cache_path' => $pool, 'instances' => [['url' => 'http://emby:8096', 'api_key' => 'k']]];
    $W = ['state' => 'watching', 'who' => [['user' => 'anna', 'title' => 'Alien', 'device' => 'iPad', 'client' => 'x', 'paused' => false]]];
    $running = null;
    $look = ['state' => 'free', 'who' => []];
    $launched = [];
    $GLOBALS['jackLetGoHost'] = ['cron' => $cron, 'apply' => false, 'dir' => $dir,
        'settings' => function () use (&$settings) { return $settings; }, 'running' => function () use (&$running) { return $running; },
        'waiting' => fn () => false, 'look' => function () use (&$look) { return $look; }, 'python' => fn () => true,
        'launch' => function (string $job, array $args) use (&$launched) { $launched[] = [$job, $args]; },
        'mover_off' => function () use (&$moverOff) { return $moverOff; }];
    $moverOff = true;

    // the look: his two schedules, what lies on the pool (only what is there, under the pool); nothing of Mover Tuning
    $l = jackLetGoLook();
    same('let Jack go: the look — his schedules, 2 files on the pool (8000 bytes), the release may go, no Mover Tuning',
        [['embycache' => '15 * * * *', 'gather' => '0 3 * * 0'], null, ['files' => 2, 'bytes' => 8000, 'pool' => $pool], ['ok' => true, 'why' => null, 'params' => []], false],
        [$l['schedules'], $l['running'], $l['pool'], $l['release'], array_key_exists('mover_tuning', $l)]);
    $moverOff = false;
    same('let Jack go: the look says whether Unraid\'s mover schedule is off (it stays so — the dialog says where to switch it on)', [true, false],
        [$l['mover_off'], jackLetGoLook()['mover_off']]);
    $moverOff = true;
    $running = 'gather';
    same('let Jack go: a run going — no release now (it finishes; nothing stops it)', 'jack_running', jackLetGoLook()['release']['why']);
    $running = null;
    $look = $W;
    $r = jackLetGoLook()['release'];
    same('let Jack go: someone watches — no release now, who is named', [false, 'jack_release_watching', 'anna'], [$r['ok'], $r['why'], $r['params']['who'][0]['user'] ?? null]);
    $look = ['state' => 'error', 'who' => [], 'why' => 'jack_watch_key', 'url' => 'http://emby:8096'];
    same('let Jack go: Emby answers but not usably — no release (like a real gather)', 'jack_watch_key', jackLetGoLook()['release']['why']);
    $look = ['state' => 'down', 'who' => []];
    same('let Jack go: Emby down — nobody can watch, the release may go', true, jackLetGoLook()['release']['ok']);
    $look = ['state' => 'free', 'who' => []];
    $settings = null;
    same('let Jack go: never set up — nothing to bring back', ['jack_not_configured', 0], [jackLetGoLook()['release']['why'], jackLetGoLook()['pool']['files']]);
    $settings = ['cache_path' => $pool, 'instances' => [['url' => 'http://emby:8096', 'api_key' => 'k']]];

    // through the agent's dispatch: the hired gate, then the request's shape — and nothing changed by a refusal
    $staffBefore = $GLOBALS['agentStaffFile'] ?? null;
    $GLOBALS['agentStaffFile'] = "$tmp/staff.json";
    file_put_contents("$tmp/staff.json", json_encode(['hired' => ['backup' => 1]]));
    $ask = fn (array $r): string => (string) (handle(json_encode($r))['error']['key'] ?? 'ok');
    same('let Jack go: unhired — his look and his let-go refused (the hired gate), his refresh answered', ['not_hired', 'not_hired', 'not_hired', true],
        [$ask(['action' => 'jack.letgo_look']), $ask(['action' => 'jack.letgo', 'confirm' => true, 'release' => false]), $ask(['action' => 'jack.letgo_seen']),
         agentDeskMayAct('jack', 'refresh', "$tmp/staff.json")]);
    file_put_contents("$tmp/staff.json", json_encode(['hired' => ['jack' => 1]]));
    same('let Jack go: hired — without confirm, confirm not true, release not said or not a bool: refused',
        ['bad_request', 'bad_request', 'bad_request', 'bad_request'],
        [$ask(['action' => 'jack.letgo', 'release' => false]), $ask(['action' => 'jack.letgo', 'confirm' => 1, 'release' => false]),
         $ask(['action' => 'jack.letgo', 'confirm' => true]), $ask(['action' => 'jack.letgo', 'confirm' => true, 'release' => 'yes'])]);
    same('let Jack go: … nothing switched off by those', ['15 * * * *', '0 3 * * 0'], array_values(jackLetGoSchedules($cron)));
    same('let Jack go: his look through the dispatch while hired', 'ok', $ask(['action' => 'jack.letgo_look']));
    check('let Jack go: his jobs run without the hired gate (the release runs after he is let go)', isset(desks()['jack']['jobs']['embycache'])
        && !str_contains((string) file_get_contents(OFFICE_DIR . '/agent/agent.php'), "agentDeskMayAct(\$deskId, 'job')"));

    // without the tick: both schedules off, Mr. Backupsy's line stays, nothing launched, the films stay
    $r = handle(json_encode(['action' => 'jack.letgo', 'confirm' => true, 'release' => false]));
    same('let Jack go: both schedules off, what they were, nothing left, no release',
        [true, ['embycache' => '15 * * * *', 'gather' => '0 3 * * 0'], ['embycache', 'gather'], [], null, null],
        [$r['ok'] ?? null, $r['was'] ?? null, $r['off'] ?? null, $r['left'] ?? null, array_key_exists('failed', $r) ? $r['failed'] : 'x', array_key_exists('release', $r) ? $r['release'] : 'x']);
    same('let Jack go: the cron file keeps only Mr. Backupsy\'s line', ['backup' => '0 2 * * *'], officeCronLines($cron));
    check('let Jack go: without the tick nothing is launched and the films stay on the pool', !$launched && is_file("$pool/Filme/A/a.mkv") && is_file("$pool/Filme/B/b.mkv"));
    same('let Jack go: the note for his page — what he switched off', ['off' => ['embycache', 'gather'], 'was' => ['embycache' => '15 * * * *', 'gather' => '0 3 * * 0']],
        array_intersect_key(jackLetGoNote($dir) ?? [], ['off' => 1, 'was' => 1]));
    $r = handle(json_encode(['action' => 'jack.letgo', 'confirm' => true, 'release' => false]));
    same('let Jack go again with nothing on: nothing to switch off, the earlier note not yet shown stays', [[], ['embycache', 'gather']],
        [$r['off'] ?? null, jackLetGoNote($dir)['off'] ?? null]);
    same('let Jack go: hired again, his page said it — said once', [['ok' => true], null], [jackLetGoSeen($dir), jackLetGoNote($dir)]);
    same('let Jack go: the answer says nothing of Mover Tuning', false, array_key_exists('unlist', $r));
    check('let Jack go: a schedule switched on again also ends the note', str_contains((string) file_get_contents(OFFICE_DIR . '/agent/desks/jack.php'),
        "if (\$cron !== null) {\n        jackLetGoSeen();"));

    // with the tick: the release handed to atd as its own job, schedules off all the same
    officeJobSetSchedule('embycache', '15 * * * *', $cron, false);
    $r = handle(json_encode(['action' => 'jack.letgo', 'confirm' => true, 'release' => true]));
    same('let Jack go with the tick: EmbyCache\'s schedule off, the release started — job embycache release --letgo via atd',
        [['embycache'], ['started' => true, 'files' => 2, 'bytes' => 8000], [['jack-embycache', [PHP_BINARY, OFFICE_DIR . '/agent/agent.php', 'job', 'embycache', 'release', '--letgo']]]],
        [$r['off'] ?? null, $r['release'] ?? null, $launched]);
    same('let Jack go: the note says the release started', ['started' => true, 'why' => null], readJson("$dir/office-letgo.json")['release'] ?? null);
    $launched = [];
    officeJobSetSchedule('gather', '0 3 * * 0', $cron, false);
    $look = $W;
    $r = handle(json_encode(['action' => 'jack.letgo', 'confirm' => true, 'release' => true]));
    same('let Jack go with the tick while someone watches: schedules off all the same, the release refused with who, nothing launched',
        [['gather'], false, 'jack_release_watching', 'anna', []],
        [$r['off'] ?? null, $r['release']['started'] ?? null, $r['release']['error']['key'] ?? null, $r['release']['error']['params']['who'][0]['user'] ?? null, $launched]);
    $h = jackHistory($dir)[0] ?? [];
    same('let Jack go: the refusal in his list of runs', ['embycache', 'release', 'letgo', 'refused', 'jack_release_watching', 'anna'],
        [$h['tool'] ?? null, $h['mode'] ?? null, $h['by'] ?? null, $h['result'] ?? null, $h['why'] ?? null, $h['who'][0]['user'] ?? null]);
    $look = ['state' => 'free', 'who' => []];
    $running = 'embycache';
    $r = handle(json_encode(['action' => 'jack.letgo', 'confirm' => true, 'release' => true]));
    same('let Jack go with the tick while a run is going: it finishes, the release refused, said which run', ['embycache', false, 'jack_running', []],
        [$r['running'] ?? null, $r['release']['started'] ?? null, $r['release']['error']['key'] ?? null, $launched]);
    $running = null;
    file_put_contents("$dir/mediacache_exclude.txt", "$pool/Filme/gone.mkv\n");
    $r = handle(json_encode(['action' => 'jack.letgo', 'confirm' => true, 'release' => true]));
    same('let Jack go with the tick, nothing on the pool: nothing to bring back, nothing launched', ['jack_letgo_nothing', []], [$r['release']['error']['key'] ?? null, $launched]);
    $GLOBALS['agentStaffFile'] = $staffBefore;
    unset($GLOBALS['jackLetGoHost']);

    // the job: release is EmbyCache's own mode, never from the page's «Start»; asked about watchers again, under the locks
    same('release: EmbyCache --release, its own mode', ['--release'], JACK_MODES['release'] ?? null);
    try {
        jackStart('embycache', 'release');
        check('release: never started from the page', false);
    } catch (Problem $p) {
        same('release: never started from the page', 'unknown_target', $p->key);
    }
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/jack.php');
    check('release: the job asks Emby again, fully, before any lock, and holds the gather\'s lock like a real run',
        str_contains($src, "if (\$tool === 'embycache' && \$mode === 'release') {\n        \$look = jackWatching();")
        && strpos($src, "if (\$tool === 'embycache' && \$mode === 'release') {\n        \$look = jackWatching();") < strpos($src, "if (in_array(\$mode, ['run', 'measure', 'release'], true)) {")
        && str_contains($src, "in_array('--letgo', \$args, true) ? 'letgo'"));
    same('release: what Unraid hears — a good end too (he is gone), problems, failures; a real run as before',
        ['ok', 'errors', 'busy', 'failed', null, 'errors'],
        [jackNotifyOutcome('release', 'ok', ['errors' => 0]), jackNotifyOutcome('release', 'ok', ['errors' => 2]), jackNotifyOutcome('release', 'busy', []),
         jackNotifyOutcome('release', 'failed', []), jackNotifyOutcome('run', 'ok', ['errors' => 0]), jackNotifyOutcome('run', 'ok', ['errors' => 1])]);
    $bin = "$tmp/notify";
    file_put_contents($bin, "#!/bin/bash\nprintf '%s\\n' \"\$@\" >> " . escapeshellarg("$tmp/notified") . "\n");
    chmod($bin, 0755);
    $envBefore = [getenv('OFFICE_NOTIFY_BIN'), getenv('OFFICE_NOTIFY_STAMP')];
    putenv("OFFICE_NOTIFY_BIN=$bin");
    putenv("OFFICE_NOTIFY_STAMP=$tmp/stamp");
    jackNotify('embycache', 'release', 'ok', ['cleanup' => ['done' => 2, 'planned' => 3], 'protected' => 1, 'errors' => 0], 0);
    $sent = (string) @file_get_contents("$tmp/notified");
    check('release: a good end told as normal — how many came back, how many stay', str_contains($sent, "-i\nnormal") && str_contains($sent, '2 files are back on the array.')
        && str_contains($sent, '1 file stays on the pool'), $sent);
    @unlink("$tmp/notified");
    jackReleaseRefusedTell('jack_release_watching');
    $sent = (string) @file_get_contents("$tmp/notified");
    check('release: refused in the job — told as a warning, what Jack Streamer laid out stays', str_contains($sent, "-i\nwarning") && str_contains($sent, 'not started')
        && str_contains($sent, 'What Jack Streamer laid out stays on the pool.'), $sent);
    putenv($envBefore[0] === false ? 'OFFICE_NOTIFY_BIN' : "OFFICE_NOTIFY_BIN=$envBefore[0]");
    putenv($envBefore[1] === false ? 'OFFICE_NOTIFY_STAMP' : "OFFICE_NOTIFY_STAMP=$envBefore[1]");

    // EmbyCache's own --release on a fixture tree: every file on the list back the cleanup's way (origin disk not mounted
    // → cleanup_tool rsync to the array view), a duplicate already on the array stays on the pool and in the list
    [$exit] = run(['python3', '--version'], 10);
    if ($exit !== 0) {
        check('release: python3 is missing here - skipped', true);
    } else {
        $py = "$tmp/py";
        foreach (["$py/data", "$py/pool/Filme/A", "$py/pool/Filme/B", "$py/pool/Filme/C", "$py/user0/Filme/C", "$py/user/Filme", "$py/shares", "$py/disk1/Filme"] as $d) {
            mkdir($d, 0700, true);
        }
        file_put_contents("$py/pool/Filme/A/a.mkv", str_repeat('a', 3000));
        file_put_contents("$py/pool/Filme/B/b.srt", 'sub');
        file_put_contents("$py/pool/Filme/C/c.mkv", 'dup');
        file_put_contents("$py/user0/Filme/C/c.mkv", 'dup');
        file_put_contents("$py/data/mediacache_exclude.txt", "$py/pool/Filme/A/a.mkv\n$py/pool/Filme/B/b.srt\n$py/pool/Filme/C/c.mkv\n$py/pool/Filme/gone.mkv\n");
        file_put_contents("$py/data/mediacache_origin.json", json_encode(["$py/pool/Filme/A/a.mkv" => 'disk1', "$py/pool/Filme/C/c.mkv" => 'disk1']));
        file_put_contents("$py/data/mediacache_settings.json", json_encode(['cache_path' => "$py/pool", 'array_path' => "$py/user0", 'user_path' => "$py/user",
            'array_disks_glob' => "$py/disk[0-9]*", 'cleanup_tool' => 'rsync', 'return_to_origin' => true, 'shares_cfg_dir' => "$py/shares", 'api_timeout' => 2,
            'instances' => [['servername' => 'Test', 'url' => 'http://127.0.0.1:9', 'api_key' => 'k', 'path_mappings' => ['/media/movies' => "$py/user/Filme"]]]]));
        [$exit, $out, $err] = run(['env', "MEDIACACHE_DIR=$py/data", "MEDIACACHE_RESULT=$py/data/status.json", 'PYTHONDONTWRITEBYTECODE=1',
                                   'python3', OFFICE_DIR . '/mediacache/mediacache_run.py', '--release'], 120);
        $st = readJson("$py/data/status.json") ?? [];
        same('EmbyCache --release: ok, mode release, 2 of 3 back (the duplicate stays), nothing filled, Emby unanswered noted',
            [0, 'release', 'ok', 3, 2, 0, 1, true],
            [$exit, $st['mode'] ?? null, $st['result'] ?? null, $st['cleanup']['planned'] ?? null, $st['cleanup']['done'] ?? null, $st['fill']['planned'] ?? null,
             $st['protected'] ?? null, $st['incomplete'] ?? null]);
        check('EmbyCache --release: the files are on the array view, gone from the pool; the duplicate stays on both',
            is_file("$py/user0/Filme/A/a.mkv") && filesize("$py/user0/Filme/A/a.mkv") === 3000 && is_file("$py/user0/Filme/B/b.srt")
            && !file_exists("$py/pool/Filme/A/a.mkv") && !file_exists("$py/pool/Filme/B/b.srt") && is_file("$py/pool/Filme/C/c.mkv"), $out . $err);
        same('MediaCache --release: the list names only what is still on the pool; an old origin file stays untouched, unused',
