})();
JS);
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/jack/desk.js') . ' 2>&1');
    $o = json_decode($raw, true);
    if (!is_array($o)) {
        check('gather cache: page ran under node', false, $raw);
        hardeningRm($tmp);
        return;
    }
    same('gather cache dialog: a gather.json from before — the switch off with its hint, the choice hidden', [['gather_cfg_cache', 'gather_cfg_cache_hint'], false, true,
        ['gather_cfg_cache_only', 'gather_cfg_cache_only.skip', 'gather_cfg_cache_only.most_free']], $o['off']);
    same('gather cache dialog: switched on — the choice shows; off again — it hides', [false, true], [$o['shown'], $o['hidden']]);
    $g = fn (bool $on, string $to) => ['jack.gather_save', ['gather' => ['shares' => ['Filme'], 'min_free_gb' => 256, 'dup_check' => 'size', 'move_cache' => $on, 'cache_only_target' => $to]]];
    same('gather cache dialog: saved — both always sent (off/«leave them», then on/«most free space»)', [$g(false, 'skip'), $g(true, 'most-free')], $o['posted']);
    same('gather cache dialog: saved on — opens on, the choice shown and set', [true, false, [false, true]], $o['on']);
    same('gather cache: the shares tile\'s words', ['', ' · gather_cache_on.skip', ' · gather_cache_on.most_free', ''], $o['words']);
    same('gather cache: the run dialog says it when on, not when off', [['gather_run_text {"shares":"Filme"}', 'gather_run_cache.most_free'], ['gather_run_text {"shares":"Filme"}', 'gather_layout']],
        [$o['run_on'], $o['run_off']]);
    hardeningRm($tmp);
}

function testJackForeign(): void
{
    $tmp = hardeningTmp('jackforeign');
    $us = "$tmp/user.scripts";
    $call = 'python3 /usr/local/emhttp/plugins/unraid-secretary-office/mediacache/mediacache_run.py --mode run';
    $scripts = [
        'Active'      => "#!/bin/bash\n# description=EmbyCache every 15 minutes\n$call\n",
        'Commented'   => "#!/bin/bash\n#$call\necho done\n",
        'Indented'    => "#!/bin/bash\n  \t#   $call\n",
        'Heredoc'     => "#!/bin/bash\n: <<'EOF'\n$call\nbash /x/consolidate_master.sh\nEOF\necho other\n",
        'HeredocOpen' => "#!/bin/bash\n: << END\n$call\nEND\nbash /mnt/user/system/consolidate_master.sh\n",
        'Off'         => "#!/bin/bash\n$call\n",
        'CustomEmpty' => "#!/bin/bash\n$call\n",
        'Unplanned'   => "#!/bin/bash\n$call\n",
        'AtStart'     => "#!/bin/bash\r\n$call\r\n",
        'Unrelated'   => "#!/bin/bash\necho embycache\n",
    ];
    $plans = ['Active' => ['custom', '*/15 * * * *'], 'Commented' => ['custom', '*/15 * * * *'], 'Indented' => ['hourly', ''], 'Heredoc' => ['daily', ''],
              'HeredocOpen' => ['weekly', ''], 'Off' => ['disabled', ''], 'CustomEmpty' => ['custom', ' '], 'AtStart' => ['start', ''], 'Unrelated' => ['hourly', '']];
    $sched = [];
    foreach ($scripts as $name => $text) {
        @mkdir("$us/scripts/$name", 0700, true);
        file_put_contents("$us/scripts/$name/script", $text);
        if (isset($plans[$name])) {
            $sched["/boot/config/plugins/user.scripts/scripts/$name/script"] = ['script' => "/boot/config/plugins/user.scripts/scripts/$name/script",
                'frequency' => $plans[$name][0], 'id' => "schedule$name", 'custom' => $plans[$name][1]];
        }
    }
    file_put_contents("$us/schedule.json", json_encode($sched));
    @mkdir("$tmp/plugins/other", 0700, true);
    @mkdir("$tmp/plugins/office", 0700, true);
    file_put_contents("$tmp/plugins/other/other.cron", "# */5 * * * * $call\n   #0 4 * * 0 bash /x/consolidate_master.sh\n0 4 * * 0 bash /x/consolidate_master.sh > /dev/null\n"
        . "*/10 * * * * /usr/local/emhttp/plugins/user.scripts/startCustom.php $us/scripts/Active/script mediacache_run.py\n");
    file_put_contents("$tmp/plugins/office/office.cron", "0 3 * * * $call\n");
    $found = jackForeignSchedules($us, "$tmp/plugins/*/*.cron", "$tmp/plugins/office/office.cron");
    $by = [];
    foreach ($found as $f) {
        $by[$f['where']] = [$f['tool'], $f['enabled']];
    }
    ksort($by);
    same('jack foreign: only lines that run count, a schedule that is off is listed but not on', [
        "$tmp/plugins/other/other.cron" => ['gather', true],
        'User Scripts: Active'          => ['embycache', true],
        'User Scripts: AtStart'         => ['embycache', true],
        'User Scripts: CustomEmpty'     => ['embycache', false],
        'User Scripts: HeredocOpen'     => ['gather', true],
        'User Scripts: Off'             => ['embycache', false],
        'User Scripts: Unplanned'       => ['embycache', false],
    ], $by);
    same('jack foreign: the warning and the caretaker name only the enabled ones', ['User Scripts: Active', 'User Scripts: AtStart', 'User Scripts: HeredocOpen', "$tmp/plugins/other/other.cron"],
        array_column(array_filter($found, fn ($f) => $f['enabled']), 'where'));
    // the user comments the line out (the report): the next look says nothing more
    file_put_contents("$us/scripts/Active/script", "#!/bin/bash\n# description=EmbyCache every 15 minutes\n# $call\n");
    check('jack foreign: commented out, gone at the next look', !in_array('User Scripts: Active', array_column(jackForeignSchedules($us, "$tmp/none/*.cron"), 'where'), true));
    same('jack active text: comments and a `: <<` block left out, a # later in a line kept', "a # b\nc",
        jackActiveText("#!/bin/sh\n  # x\na # b\n: <<-\"STOP\"\nhidden\n\tSTOP\nc\n"));
    same('jack active text: an unclosed block hides the rest (bash does the same)', 'a', jackActiveText("a\n: <<EOF\nb\n"));
    hardeningRm($tmp);
}

/** The plugin's cron file against a copy: only the job's own line changes, the order stays */
/**
 * The office's cron lines in root's crontab (caretakerWatchCron()): a fresh `plugin install` registers the plugin only
 * after its install script, so update_cron skipped the office's files then — the caretaker looks every minute and runs
 * update_cron once a line is missing and the plugin is registered, at most every CARETAKER_CRON_RETRY.
 */
function testCaretakerCronLook(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-cronlook-' . getmypid();
    @mkdir($tmp, 0700, true);
    $watch = "$tmp/agent-watch.cron";
    $sched = "$tmp/office.cron";
    $tab = "$tmp/root";
    $plg = "$tmp/office.plg";
    file_put_contents($watch, "# the look\n*/5 * * * * bash /x/scripts/job.sh watch > /dev/null 2>&1\n");
    file_put_contents($sched, "# schedules\n0 3 * * * bash /x/scripts/job.sh backup > /dev/null 2>&1\n");
    file_put_contents($tab, "# Generated mover schedule:\n40 3 * * * /usr/local/sbin/mover start\n");
    $ran = 0;
    $h = ['files' => [$watch, $sched], 'crontab' => $tab, 'plg' => $plg, 'apply' => function () use (&$ran, $tab, $watch, $sched) {
        $ran++;
        file_put_contents($tab, file_get_contents($watch) . file_get_contents($sched));
    }];
    $keep = $GLOBALS['ctCronApplied'] ?? null;
    $GLOBALS['ctCronApplied'] = 0;
    $now = 2_000_000_000;

    same('cron look: the plugin not registered yet (install script still running) — nothing run', [false, 0], [caretakerWatchCron($now, $h), $ran]);
    touch($plg);
    same('cron look: registered a minute later, lines missing — update_cron once', [true, 1], [caretakerWatchCron($now + 60, $h), $ran]);
    same('cron look: all lines there — nothing run', [false, 1], [caretakerWatchCron($now + 1300, $h), $ran]);
    file_put_contents($tab, file_get_contents($watch));
    same('cron look: a schedule line missing (schedules back after a reinstall) — update_cron again', [true, 2], [caretakerWatchCron($now + 1400, $h), $ran]);
    $h['apply'] = function () use (&$ran) { $ran++; };
    file_put_contents($tab, '');
    same('cron look: still missing within CARETAKER_CRON_RETRY — not again', [false, 2], [caretakerWatchCron($now + 1400 + 60, $h), $ran]);
    same('cron look: after CARETAKER_CRON_RETRY — once more', [true, 3], [caretakerWatchCron($now + 1400 + CARETAKER_CRON_RETRY, $h), $ran]);
    $h['apply'] = function () { throw new Problem('command_failed', ['detail' => 'update_cron']); };
    same('cron look: update_cron failing never breaks the tick', true, caretakerWatchCron($now + 1400 + 2 * CARETAKER_CRON_RETRY, $h));
    unlink($sched);
    file_put_contents($tab, file_get_contents($watch));
    same('cron look: no schedules file — only the look counts', false, caretakerWatchCron($now + 1400 + 3 * CARETAKER_CRON_RETRY, $h));

    if ($keep === null) {
        unset($GLOBALS['ctCronApplied']);
    } else {
        $GLOBALS['ctCronApplied'] = $keep;
    }
    array_map('unlink', glob("$tmp/*") ?: []);
    @rmdir($tmp);
}

function testOfficeCron(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-cron-' . getmypid();
    @mkdir($tmp, 0700, true);
    $file = "$tmp/office.cron";

    officeJobSetSchedule('snapshots', '*/5 * * * *', $file, false);
    officeJobSetSchedule('backup', '0 2 * * *', $file, false);
    same('office cron: both jobs', ['backup' => '0 2 * * *', 'snapshots' => '*/5 * * * *'], officeCronLines($file));
    $lines = array_values(array_filter(explode("\n", (string) file_get_contents($file)), fn ($l) => $l !== '' && $l[0] !== '#'));
    same('office cron: backup line first', '0 2 * * * ' . officeJobCommand('backup'), $lines[0] ?? null);

    officeJobSetSchedule('backup', '30  3 * * 1-5', $file, false);
    same('office cron: changed, spaces tidied', ['backup' => '30 3 * * 1-5', 'snapshots' => '*/5 * * * *'], officeCronLines($file));

    officeJobSetSchedule('gather', '0 4 * * 0', $file, false);
    officeJobSetSchedule('embycache', '5 * * * *', $file, false);
    same('office cron: Jack Emby\'s jobs beside them', ['backup' => '30 3 * * 1-5', 'snapshots' => '*/5 * * * *', 'embycache' => '5 * * * *', 'gather' => '0 4 * * 0'], officeCronLines($file));
    officeJobSetSchedule('embycache', null, $file, false);
    officeJobSetSchedule('gather', null, $file, false);

    officeJobSetSchedule('backup', null, $file, false);
    same('office cron: backup off, snapshots kept', ['snapshots' => '*/5 * * * *'], officeCronLines($file));
    officeJobSetSchedule('snapshots', null, $file, false);
    check('office cron: file gone when empty', !file_exists($file));

    foreach (['0 3 * * * rm -rf /', '61 3 * * *'] as $bad) {
        try {
            officeJobSetSchedule('backup', $bad, $file, false);
            check("office cron refuses $bad", false);
        } catch (Problem $p) {
            same("office cron refuses $bad", 'bad_cron', $p->key);
        }
    }
    try {
        officeJobSetSchedule('rm', '0 3 * * *', $file, false);
        check('office cron refuses an unknown job', false);
    } catch (Problem $p) {
        check('office cron refuses an unknown job', true);
    }
    // a line someone added by hand is not ours
    file_put_contents($file, "0 4 * * * bash /tmp/job.sh backup > /dev/null 2>&1\n");
    same('office cron: foreign line ignored', [], officeCronLines($file));
    exec('rm -rf ' . escapeshellarg($tmp));
}

/** The office's label in Unraid's menu bar (src/place.php): what passes, and the page's Name= line on a copy */
function testWhereArrayZfs(): void
{
    // a user's report (2026-10-09): ZFS-formatted array disks listed as six «single, no redundancy» pools
    foreach (['disk1', 'disk6', 'disk28'] as $n) {
        check("array disk pool left out: $n", waArrayDiskPool($n));
    }
    foreach (['cache', 'hazel', 'disks', 'disk', 'mydisk1', 'disk1x', 'Disk1'] as $n) {
        check("a real pool stays: $n", !waArrayDiskPool($n));
    }
    // the licence's device limit: Lifetime/Pro report -1 (unlimited) — no «9 of -1»
    check('licence limit -1 = unlimited', waLicenseLimit('-1') === null);
    check('licence limit empty = unlimited', waLicenseLimit('') === null);
    check('licence limit 0 = unlimited', waLicenseLimit('0') === null);
    check('licence limit 6', waLicenseLimit('6') === 6);
    check('licence limit 30', waLicenseLimit(' 30 ') === 30);
    // SMART: FAILING_NOW is bad, In_the_past only a notice
    $tmp = sys_get_temp_dir() . '/office-tests-smart-' . getmypid();
    file_put_contents($tmp, implode("\n", [
        'ID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE',
        '  5 Reallocated_Sector_Ct   0x0033   100   100   010    Pre-fail  Always       -       0',
        '190 Airflow_Temperature_Cel 0x0022   062   040   045    Old_age   Always   In_the_past 38 (Min/Max 20/60)',
        '197 Current_Pending_Sector  0x0012   001   001   005    Old_age   Always   FAILING_NOW 812',
    ]) . "\n");
    $sm = waSmart($tmp, [5, 197]);
    @unlink($tmp);
    $by = [];
    foreach (($sm['problems'] ?? []) as $p) {
        $by[$p['id']] = $p;
    }
    check('SMART 190 In_the_past: a notice', ($by[190]['level'] ?? '') === 'notice' && ($by[190]['key'] ?? '') === 'failed_past');
    check('SMART 197 FAILING_NOW: bad', ($by[197]['level'] ?? '') === 'bad' && ($by[197]['key'] ?? '') === 'failing');
    check('SMART 5 at 0: no problem', !isset($by[5]));
    // NVMe spare (2026-10-16, virtual NVMe on Unraid 7.4: «Available Spare 0 %», threshold 0 % — no threshold, no alarm)
    $nvme = function (int $spare, int $thresh): array {
        $f = sys_get_temp_dir() . '/office-tests-smart-nv-' . getmypid();
        file_put_contents($f, "SMART/Health Information (NVMe Log 0x02, NSID 0x1)\nCritical Warning:                   0x00\nTemperature:                        50 Celsius\n"
            . "Available Spare:                    {$spare}%\nAvailable Spare Threshold:          {$thresh}%\nPercentage Used:                    0%\n"
            . "Media and Data Integrity Errors:    0\n");
        $sm = waSmart($f, []);
        @unlink($f);
        return array_column($sm['problems'] ?? [], 'key');
    };
    same('SMART NVMe spare: 0 % of threshold 0 % — nothing; 5 % under 10 % — bad; 10 % at 10 % — nothing; 100 % — nothing',
        [[], ['nvme_spare'], [], []], [$nvme(0, 0), $nvme(5, 10), $nvme(10, 10), $nvme(100, 10)]);
}

