function testSilentControlsMore(): void
{
    $lang = fn (string $desk, string $l) => json_decode((string) file_get_contents(OFFICE_WEB . "/desks/$desk/lang/$l.json"), true) ?: [];
    $bk = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    $sp = (string) file_get_contents(OFFICE_WEB . '/desks/snapshot/desk.js');
    $cl = (string) file_get_contents(OFFICE_WEB . '/desks/cleanup/desk.js');
    $jk = (string) file_get_contents(OFFICE_WEB . '/desks/jack/desk.js');
    check('silent controls: «Set them to manual» says it holds for this Apply', str_contains($bk, "el('small', 'bk-once', T('setup.sources_manual_once'))"));
    check('silent controls: «also to {partner}» on a default not chosen says it waits', str_contains($bk, "if (!on && !off) tickText.appendChild(el('small', '', T('setup.preset.kopia_partner_tick_wait')));"));
    check('silent controls: Snapshotini\'s wake switch - its word and «Tour now» under it, shown only while on, off again after the tour',
        str_contains($sp, "wakeNote.append(el('span', '', T('wake_once')), wakeGo);") && str_contains($sp, 'wakeNote.hidden = !wake.checked || wakeLabel.hidden;')
        && str_contains($sp, '{ view.wake.checked = false; view.wakeSync(); }'));
    check('silent controls: Dustdevil\'s the same', str_contains($cl, "wakeNote.append(el('span', '', T('where.wake_once')), wakeGo);")
        && str_contains($cl, 'wakeNote.hidden = !v.wake.checked || v.wakeLabel.hidden;') && str_contains($cl, '{ view.wake.checked = false; view.wakeSync(); }'));
    check('silent controls: Jack Streamer\'s bar - drawn from his setup, gone on his other page and on other desks',
        str_contains($jk, 'setTimeout(setupBar, 0);') && substr_count($jk, 'Office.selbar(null)') >= 3);
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $b = $lang('backup', $l);
        $s = $lang('snapshot', $l);
        $c = $lang('cleanup', $l);
        $j = $lang('jack', $l);
        check("silent controls: the words ($l)", ($b['setup.sources_manual_once'] ?? '') !== '' && ($b['setup.preset.kopia_partner_tick_wait'] ?? '') !== ''
            && ($s['wake_once'] ?? '') !== '' && ($c['where.wake_once'] ?? '') !== '' && ($c['where.scan_now'] ?? '') === ($s['scan_now'] ?? null)
            && is_array($j['setup.bar_changes'] ?? null) && ($j['setup.bar_sub'] ?? '') !== '' && ($j['setup.discard'] ?? '') !== '');
    }
    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('silent controls: node is missing here - skipped', true);
        return;
    }
    $tmp = hardeningTmp('silent-more');
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const el = () => ({ dataset: {}, style: {}, appendChild() {}, append() {}, setAttribute() {} });
globalThis.Office = { sections: () => ({ el: {}, active: () => '', mount: () => false, places: () => [], note: () => ({ tile: '' }), render() {}, row() {}, pick() {}, clear() {} }), scope: () => T, t: T, el, fmt: {}, desk: () => {}, places: () => {},
  placesFrom: () => {}, placesTook: () => {}, store: () => null, storeJson: () => null, agent: { running: true } };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const e = OFFICE_DESK_TESTS.jack;
e.setState({ settings: { instances: [{ type: 'emby', servername: 'Emby', url: 'http://emby:8096', has_key: true, path_mappings: { '/data': '/mnt/user/Filme' } }],
  libraries: ['Filme'], valid_users: ['u1'], cache_path: '/mnt/maple', cache_budget: '200G' }, pools: ['/mnt/maple'], emby: [], share_info: {},
  jobs: { embycache: { running: false }, gather: { running: false } } });
e.initForm();
const f = e.form();
const out = [e.formChangeCount()];
f.values.cache_budget = '300';
out.push(e.formChangeCount());
f.chosenLibs.add('Serien');
f.chosenUsers.delete('u1');
out.push(e.formChangeCount());
f.values.cache_budget = '200';
f.chosenLibs.delete('Serien');
f.chosenUsers.add('u1');
out.push(e.formChangeCount());
console.log(JSON.stringify(out));
JS);
    $raw = (string) shell_exec(implode(' ', array_map('escapeshellarg', [$node, "$tmp/t.js", OFFICE_WEB . '/desks/jack/desk.js'])) . ' 2>&1');
    hardeningRm($tmp);
    same('silent controls: Jack Streamer\'s «n changes» - none at the start, the budget 1, a library and a person more, all back none', [0, 1, 3, 0], json_decode($raw, true) ?? $raw);
}

/**
 * A must the office couldn't look at (its disk sleeps) is no must (2026-10-17, nostromo: «Nötig (2)», «? steht auf ?»):
 * Nextcloud's data folder - one finding per folder, none while not looked at, never «?» in its words; the backup place
 * while its disks sleep likewise
 */
function testBackupAsleepNoMust(): void
{
    $look = fn (array $map) => fn (string $ct): array => $map[$ct] ?? [null, null];
    $ncs = [['container' => 'nextcloud'], ['container' => 'nextcloud-cron'], ['container' => 'nc2']];
    same('asleep no must: Nextcloud\'s disk asleep (app and cron) - no finding at all', [], backupNextcloudFindings($ncs, $look([])));
    $f = backupNextcloudFindings($ncs, $look(['nextcloud' => ['/mnt/user/nc', 040777], 'nextcloud-cron' => ['/mnt/user/nc', 040777], 'nc2' => ['/mnt/user/nc2', 040750]]));
    same('asleep no must: awake - one per data folder (app and cron share it), others\' read judged, the mode as digits',
        [['nextcloud_datadir', 'required', false, 'nextcloud', '/mnt/user/nc', '777'], ['nextcloud_datadir', 'required', true, 'nc2', '/mnt/user/nc2', '750']],
        array_map(fn ($x) => [$x['id'], $x['level'], $x['ok'], $x['params']['name'], $x['params']['path'], $x['params']['mode']], $f));
    same('asleep no must: a folder whose bits can\'t be read - not judged, nothing said', [], backupNextcloudFindings([['container' => 'nc']], $look(['nc' => ['/mnt/user/nc', null]])));
    $bp = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    check('asleep no must: the backup place while its disks sleep - no must «couldn\'t check»',
        str_contains($bp, "if (!\$dsSleeps) {\n            \$out[] = finding('dumps_share', 'required', !\$dsBad,"));
    $desks = '';
    foreach (glob(OFFICE_DIR . '/agent/desks/*.php') ?: [] as $file) {
        $desks .= (string) file_get_contents($file);
    }
    check('asleep no must: no «?» put into a user text\'s parameter anywhere in the desks', !preg_match("/=> '\\?'/", $desks));
}

function testBackup74Polish(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-74polish-' . getmypid();
    exec('rm -rf ' . escapeshellarg($tmp));
    $lib = escapeshellarg(OFFICE_DIR . '/backup/lib/common.sh');

    // ---- Plex's own SQLite checks the copy
    $px = "$tmp/proc/4242/root/usr/lib/plexmediaserver";
    foreach (["$tmp/bin", "$px/lib"] as $d) {
        @mkdir($d, 0700, true);
    }
    // the loader stand-in: <loader> --library-path <dir> <binary> --sqlite <db> <sql>, the arguments noted
    file_put_contents("$px/lib/ld-musl-x86_64.so.1", "#!/bin/bash\necho \"\$*\" >>\"$tmp/loader.log\"\n[[ \"\$1 \$3 \$4\" == '--library-path /proc/self/fd/7 --sqlite' ]] || { echo usage; exit 1; }\n"
        . "[[ -e \"$tmp/nosum\" ]] && exit 0\n[[ \"\$6\" == 'SELECT 6*7;' ]] && { echo 42; exit 0; }\nf=\"\${5#file:}\"; f=\"\${f%%\\?*}\"\n[[ -r \"\$f\" ]] || { echo \"unable to open \$f\"; exit 0; }\ngrep -q bad \"\$f\" && { printf '*** in database main ***\\nTree 11 page 488: btreeInitPage() returns error code 11\\n'; exit 0; }\necho ok\n");
    file_put_contents("$px/Plex Media Server", "binary\n");
    file_put_contents("$tmp/bin/docker", "#!/bin/bash\n[[ \"\$1 \$2 \$3\" == 'inspect -f {{.State.Pid}}' && \"\$4\" == Plex ]] && { echo 4242; exit 0; }\necho 0\n");
    file_put_contents("$tmp/bin/setpriv", "#!/bin/bash\necho \"\$*\" >>\"$tmp/setpriv.log\"\nwhile [[ \$# -gt 0 && \"\$1\" != -- ]]; do shift; done\nshift\nexec \"\$@\"\n");
    file_put_contents("$tmp/bin/sqlite3", "#!/bin/bash\necho 'Parse error in 2nd command line argument: unknown tokenizer: collating'\nexit 1\n");
    foreach (array_merge(glob("$tmp/bin/*"), ["$px/lib/ld-musl-x86_64.so.1"]) as $f) {
        chmod($f, 0755);
    }
    $check = fn (string $c, string $k, string $copy) => trim((string) shell_exec('bash -c ' . escapeshellarg("PATH=$tmp/bin:\$PATH UB_DATA=$tmp/data UB_PROC=$tmp/proc; source $lib >/dev/null 2>&1; "
        . 'media_sqlite_check ' . escapeshellarg($c) . ' ' . escapeshellarg($k) . ' ' . escapeshellarg($copy) . '; printf "%s|%s" "$SQ_CHECK_BY" "$SQ_CHECK_OUT"') . ' 2>&1'));
    // the copies in a folder of root's alone, as the run's staging folder
    foreach (["$tmp/db", "$tmp/my db"] as $d) {
        @mkdir($d, 0700, true);
    }
    file_put_contents("$tmp/db/sqlite_Plex_com.plexapp.plugins.library.db", 'good');
    file_put_contents("$tmp/db/bad.db", 'bad');
    file_put_contents("$tmp/my db/it's.db", 'good');
    same('plex sqlite: a sound copy - checked by Plex\'s own SQLite', 'plex|ok', $check('Plex', 'plex', "$tmp/db/sqlite_Plex_com.plexapp.plugins.library.db"));
    $log = (string) @file_get_contents("$tmp/loader.log");
    check('plex sqlite: the sum first, then quick_check on the copy bound into a fresh folder in /tmp, read only (immutable), the library and binary by fd',
        str_contains($log, "--library-path /proc/self/fd/6 /proc/self/fd/7 --sqlite :memory: SELECT 6*7;")
        && (bool) preg_match('#--sqlite file:/tmp/\.uso-sqlite\.\w{6}/copy\.db\?immutable=1 PRAGMA quick_check;#', $log), $log);
    check('plex sqlite: run as nobody, no new privileges', str_contains((string) @file_get_contents("$tmp/setpriv.log"), '--reuid=99 --regid=100 --clear-groups --no-new-privs --'));
    same('plex sqlite: a broken copy - its message, by Plex (so it fails its check)', "plex|*** in database main ***\nTree 11 page 488: btreeInitPage() returns error code 11",
        $check('Plex', 'plex', "$tmp/db/bad.db"));
    same('plex sqlite: a path with a space and a quote', 'plex|ok', $check('Plex', 'plex', "$tmp/my db/it's.db"));
    same('plex sqlite: nothing left - no folder in /tmp, no mount', [[], false],
        [glob('/tmp/.uso-sqlite.*') ?: [], str_contains((string) file_get_contents('/proc/mounts'), '.uso-sqlite.')]);
    same('plex sqlite: another media server - Unraid\'s sqlite3', 'host|Parse error in 2nd command line argument: unknown tokenizer: collating', $check('Jellyfin', 'jellyfin', "$tmp/db/x.db"));
    same('plex sqlite: no pid (the container not answering) - Unraid\'s sqlite3', 'host', explode('|', $check('Other', 'plex', "$tmp/db/x.db"))[0]);
    touch("$tmp/nosum");
    same('plex sqlite: a binary that doesn\'t answer the sum - Unraid\'s sqlite3', 'host', explode('|', $check('Plex', 'plex', "$tmp/db/x.db"))[0]);
    same('plex sqlite: the helpers beside it still there (ct_host_path finds the databases)', '/mnt/cache/appdata/plex/Library/x.db',
        trim((string) shell_exec('bash -c ' . escapeshellarg("UB_DATA=$tmp/data; source $lib >/dev/null 2>&1; declare -A CT_BINDS=([Plex]='/mnt/cache/appdata/plex|/config|true'); ct_host_path Plex /config/Library/x.db") . ' 2>&1')));
    $bk = (string) file_get_contents(OFFICE_DIR . '/backup/backup.sh');
    check('plex sqlite: the run - Unraid\'s sqlite3 stopping at «unknown tokenizer» marks the copy unchecked, a failure by Plex\'s own SQLite fails it',
        str_contains($bk, 'media_sqlite_check "$c" "$(media_kind "${CT_IMAGE[$c]}")" "$out"; r="$SQ_CHECK_OUT"')
        && str_contains($bk, 'elif [[ "$SQ_CHECK_BY" == "host" ]] && grep -qiE \'no such (collation|module|function|tokenizer)|unknown tokenizer\' <<<"$r"; then'));

    // ---- setup: a share without snapshots
    $mnt = "$tmp/mnt";
    $root = "$mnt/addons/UnraidSecretaryOffice/snapshots";
    $pool = "$mnt/maple";
    foreach (["$tmp/fake", "$tmp/data/unraid-backup/state", "$tmp/boot/config/shares", $root, "$mnt/user", "$mnt/disk1/Filme",
              "$pool/media", "$pool/UnraidSecretaryOffice/backup"] as $d) {
        @mkdir($d, 0700, true);
    }
    file_put_contents("$mnt/disk1/Filme/a.mkv", 'x');
    foreach (['media', 'UnraidSecretaryOffice', 'Filme'] as $n) {
        touch("$tmp/boot/config/shares/$n.cfg");
    }
    $env = "export PATH=$tmp/sbin:\$PATH UB_DATA=$tmp/data/unraid-backup UB_MNT=$mnt UB_BOOT=$tmp/boot UB_SHARES_CFG=$tmp/boot/config/shares"
         . " UB_DISKS_INI=$tmp/fake/disks.ini UB_NOTIFY_BIN=$tmp/sbin/notify UB_MOUNTS_FILE=$tmp/fake/mounts FAKE=$tmp/fake";
    @mkdir("$tmp/sbin", 0700);
    file_put_contents("$tmp/sbin/docker", "#!/bin/bash\ncase \"\$1\" in version) echo 29.0 ;; esac\nexit 0\n");
    file_put_contents("$tmp/sbin/zfs", "#!/bin/bash\n[[ \"\$*\" == *'-t filesystem'* ]] && cat \"\$FAKE/zfs.txt\"\nexit 0\n");
    file_put_contents("$tmp/sbin/virsh", "#!/bin/bash\nexit 0\n");
    file_put_contents("$tmp/sbin/mountpoint", "#!/bin/bash\n[[ \"\${@: -1}\" == */user ]]\n");
    file_put_contents("$tmp/sbin/mount", "#!/bin/bash\nmkdir -p \"\${@: -1}\"\n");
    file_put_contents("$tmp/sbin/umount", "#!/bin/bash\nexit 0\n");
    file_put_contents("$tmp/sbin/notify", "#!/bin/bash\nexit 0\n");
    foreach (glob("$tmp/sbin/*") as $f) {
        chmod($f, 0755);
    }
    file_put_contents("$tmp/boot/config/docker.cfg", "DOCKER_ENABLED=\"yes\"\nDOCKER_APP_CONFIG_PATH=\"/mnt/user/appdata/\"\n");
    file_put_contents("$tmp/fake/mounts", "maple $pool zfs rw 0 0\nmaple/media $pool/media zfs rw 0 0\nmaple/UnraidSecretaryOffice $pool/UnraidSecretaryOffice zfs rw 0 0\n"
        . "/dev/md1p1 $mnt/disk1 xfs rw 0 0\nshfs $mnt/user fuse.shfs rw 0 0\n");
    $z = fn ($n, $mp, $ref) => "$n\t$mp\ton\t" . crc32($n) . "\t$ref\t-\n";
    file_put_contents("$tmp/fake/zfs.txt", $z('maple', $pool, 1) . $z('maple/media', "$pool/media", 5000) . $z('maple/UnraidSecretaryOffice', "$pool/UnraidSecretaryOffice", 10));
    file_put_contents("$tmp/fake/disks.ini", "[\"maple\"]\nname=\"maple\"\nspundown=\"0\"\n[\"disk1\"]\nname=\"disk1\"\ntype=\"Data\"\nfsType=\"xfs\"\nspundown=\"0\"\nrotational=\"0\"\n");
    $data = "$tmp/data/unraid-backup";
    $setup = function () use ($env): array {
        $out = [];
        exec('bash -c ' . escapeshellarg("$env UB_SIZE_TIMEOUT=0 UB_EXPLAIN=0; bash " . escapeshellarg(OFFICE_DIR . '/backup/setup.sh') . " --plan </dev/null") . ' 2>&1', $out, $rc);
        return [$rc, implode("\n", $out)];
    };
    $json = fn (string $f) => json_decode((string) @file_get_contents("$data/state/$f"), true) ?: [];
    $share = fn (array $plan, string $n) => array_values(array_filter($plan['shares'] ?? [], fn ($s) => ($s['name'] ?? '') === $n))[0] ?? [];
    $coded = fn (array $msgs, string $code) => array_values(array_filter($msgs, fn ($m) => ($m['code'] ?? '') === $code));

    [$rc, $out] = $setup();
    $plan = $json('setup-plan.json');
    $f = $share($plan, 'Filme');
    same('no snapshots: a first setup - the XFS share is live, proposed off with the reason (never «local»)', [0, 'live', 'off', 'no_snapshots'],
        [$rc, $f['method'] ?? null, $f['mode'] ?? null, $f['why'] ?? null], $out);
    same('no snapshots: … nothing to warn about while it is off; the ZFS share keeps its proposal', [[], 'snap'],
        [$coded($plan['messages'] ?? [], 'share_no_snapshots'), $share($plan, 'media')['method'] ?? null]);

    // set to local earlier: it stays (the user's), warned about with the share
    file_put_contents("$data/settings.ini", "[general]\nserver = Test\nmount_root = $root\ndumps_share = UnraidSecretaryOffice\n[flash]\nmode = off\n"
        . "[kopia]\nenabled = no\n[share \"Filme\"]\nmode = snapshot\n[share \"media\"]\nmode = snapshot\n[share \"UnraidSecretaryOffice\"]\nmode = snapshot\n");
    [$rc, $out] = $setup();
    $plan = $json('setup-plan.json');
    $w = $coded($plan['messages'] ?? [], 'share_no_snapshots');
    same('no snapshots: set to local before - kept, warned once with the share (not the ZFS one)', [0, 'snapshot', 'previous', 1, 'warn', ['share' => 'Filme']],
        [$rc, $share($plan, 'Filme')['mode'] ?? null, $share($plan, 'Filme')['why'] ?? null, count($w), $w[0]['level'] ?? null, $w[0]['params'] ?? null], $out);

    // the Team Lead's check: settings.ini + the plan
    $settings = backupReadSettings("$data/settings.ini");
    same('no snapshots: the check names the share at local the plan found live', ['Filme'], backupLocalWithoutSnapshot($settings, $plan));
    $settings['share|media']['method'] = ['live'];
    same('no snapshots: … and one the user set to method live on ZFS', ['Filme', 'media'], backupLocalWithoutSnapshot($settings, $plan));
    same('no snapshots: … none without a plan, none at off or offsite', [[], []], [backupLocalWithoutSnapshot($settings, []),
        backupLocalWithoutSnapshot(['share|Filme' => ['mode' => ['kopia']]], $plan)]);
    $bp = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    check('no snapshots: the check is registered', str_contains($bp, "finding('share_no_snapshots', 'recommended', !\$noSnap, ['shares' => implode(', ', \$noSnap), 'n' => count(\$noSnap)], '#/backup/setup')"));

    // ---- the dataset dialog: is this unit in the last backup (its package in the run's list)?
    $oldMd = $GLOBALS['md'] ?? null;
    $GLOBALS['md'] = ['last' => ['finished' => time() - 600, 'result' => 'ok', 'packages' => ['list' => [['kind' => 'app', 'name' => 'Plex', 'result' => 'warnings'],
        ['kind' => 'app', 'name' => 'Emby', 'result' => 'failed'], ['kind' => 'vm', 'name' => 'Plex', 'result' => 'ok']]]]];
    $u = fn (?array $t) => array_intersect_key(mdLastBackup($t) ?? [], ['unit' => 1, 'fresh' => 1]);
    same('dataset dialog: in the last backup - fresh; new since (not in it), its package failed - not fresh; a VM by kind; no target - unknown',
        [['unit' => true, 'fresh' => true], ['unit' => false, 'fresh' => false], ['unit' => false, 'fresh' => false], ['unit' => true, 'fresh' => true], ['unit' => null, 'fresh' => true]],
        [$u(['kind' => 'app', 'name' => 'Plex']), $u(['kind' => 'app', 'name' => 'Jellyfin']), $u(['kind' => 'app', 'name' => 'Emby']), $u(['kind' => 'vm', 'name' => 'Plex']), $u(null)]);
    $GLOBALS['md'] = ['last' => ['finished' => time() - 600, 'result' => 'ok']];
    same('dataset dialog: a run without a package list (an old engine) - unknown, fresh as before', ['unit' => null, 'fresh' => true], $u(['kind' => 'app', 'name' => 'Jellyfin']));
    $GLOBALS['md'] = $oldMd;

    // ---- the page
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('no snapshots (page): the row says it, «local snapshot» greyed, «local» of a start is «not backed up» there',
        str_contains($js, "if (m === 'snapshot') modeCell.append(' ', chip(T('setup.no_snap'), 'warn', T(kopiaOn ? 'setup.no_snap_hint' : 'setup.no_snap_hint_nokopia')));")
        && str_contains($js, "else if (o.mode === 'snapshot' && shareNoSnap(sh)) { opt.disabled = mode !== 'snapshot'; opt.title = T('setup.no_snap_opt'); }")
        && substr_count($js, "lv === 1 ? shareLocal(sh.name) : LV[lv]") === 2 && substr_count($js, "setup.draft[k] = shareLocal(k.slice(6, -5));") === 2);
    check('dataset dialog (page): whether this app is in the last backup', str_contains($js, "last.unit === false ? T('dsw.last_without', { when: fmt.relative(last.time), name: target.name })"));
    check('apply (page): the new rows\' levels with the partner part', str_contains($js, "\${levelWord('app:' + a.id, `app|\${a.name}|partner`)}")
        && str_contains($js, "\${levelWord('vm:' + x.name, `vm|\${x.name}|partner`)}") && str_contains($js, "level: levelWord(w.owner.key, unitPartnerKey(w.owner.key))"));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $t = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/backup/lang/$l.json"), true) ?: [];
        check("74 polish ($l): the words", isset($t['setup.no_snap'], $t['setup.no_snap_hint'], $t['setup.no_snap_hint_nokopia'], $t['setup.no_snap_opt'], $t['setup.why.no_snapshots'],
            $t['setup.msg.share_no_snapshots'], $t['check.share_no_snapshots'], $t['check.share_no_snapshots_how']['one'], $t['dsw.last_fresh_in'], $t['dsw.last_without']));
    }
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Engine 2.54: a server without Docker backs up (2026-10-16, a fresh Unraid 7.4 server with Docker switched off: the
 * setup failed with «Docker does not answer»). setup.sh --plan on a fixture server whose docker never answers: Docker
 * switched off (docker.cfg DOCKER_ENABLED="no") is a plan without apps - docker_service false, one hint docker_off, no
 * error, Kopia's part skipped with the problem docker_off; Docker switched on but silent fails with the error code
 * docker_silent; Docker answering: docker_service true. The run's own check (ub_docker_service_off) the same; the page
 * greys «offsite» with the reason and says it in the apps step.
 */
function testSetupNoDocker(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-nodocker-' . getmypid();
    exec('rm -rf ' . escapeshellarg($tmp));
    $mnt = "$tmp/mnt";
    $root = "$mnt/addons/UnraidSecretaryOffice/snapshots";
    $pool = "$mnt/maple";
    foreach (["$tmp/bin", "$tmp/fake", "$tmp/data/unraid-backup/state", "$tmp/boot/config/shares", $root, "$mnt/user",
              "$pool/media", "$pool/UnraidSecretaryOffice/backup"] as $d) {
        @mkdir($d, 0700, true);
    }
    foreach (['media', 'UnraidSecretaryOffice'] as $n) {
        touch("$tmp/boot/config/shares/$n.cfg");
    }
    $env = "export PATH=$tmp/bin:\$PATH UB_DATA=$tmp/data/unraid-backup UB_MNT=$mnt UB_BOOT=$tmp/boot UB_SHARES_CFG=$tmp/boot/config/shares"
         . " UB_DISKS_INI=$tmp/fake/disks.ini UB_NOTIFY_BIN=$tmp/bin/notify UB_MOUNTS_FILE=$tmp/fake/mounts FAKE=$tmp/fake";
    // docker: silent unless «up» (then it answers and lists nothing)
    file_put_contents("$tmp/bin/docker", "#!/bin/bash\n[[ -e \"\$FAKE/up\" ]] || exit 1\ncase \"\$1\" in version) echo 29.0 ;; esac\nexit 0\n");
    file_put_contents("$tmp/bin/zfs", "#!/bin/bash\n[[ \"\$*\" == *'-t filesystem'* ]] && cat \"\$FAKE/zfs.txt\"\nexit 0\n");
    file_put_contents("$tmp/bin/virsh", "#!/bin/bash\nexit 0\n");
    file_put_contents("$tmp/bin/mountpoint", "#!/bin/bash\n[[ \"\${@: -1}\" == */user ]]\n");
    file_put_contents("$tmp/bin/mount", "#!/bin/bash\nmkdir -p \"\${@: -1}\"\n");
    file_put_contents("$tmp/bin/umount", "#!/bin/bash\nexit 0\n");
    file_put_contents("$tmp/bin/notify", "#!/bin/bash\nexit 0\n");
    foreach (glob("$tmp/bin/*") as $f) {
        chmod($f, 0755);
    }
    file_put_contents("$tmp/fake/mounts", "maple $pool zfs rw 0 0\nmaple/media $pool/media zfs rw 0 0\nmaple/UnraidSecretaryOffice $pool/UnraidSecretaryOffice zfs rw 0 0\n"
        . "shfs $mnt/user fuse.shfs rw 0 0\n");
    $z = fn ($n, $mp, $ref) => "$n\t$mp\ton\t" . crc32($n) . "\t$ref\t-\n";
    file_put_contents("$tmp/fake/zfs.txt", $z('maple', $pool, 1) . $z('maple/media', "$pool/media", 5000) . $z('maple/UnraidSecretaryOffice', "$pool/UnraidSecretaryOffice", 10));
    file_put_contents("$tmp/fake/disks.ini", "[\"maple\"]\nname=\"maple\"\nspundown=\"0\"\n");
    $data = "$tmp/data/unraid-backup";
    $setup = function (string $args) use ($env): array {
        $out = [];
        exec('bash -c ' . escapeshellarg("$env UB_SIZE_TIMEOUT=0 UB_EXPLAIN=0; bash " . escapeshellarg(OFFICE_DIR . '/backup/setup.sh') . " $args </dev/null") . ' 2>&1', $out, $rc);
        return [$rc, implode("\n", $out)];
    };
    $json = fn (string $f) => json_decode((string) @file_get_contents("$data/state/$f"), true) ?: [];
    $coded = fn (array $msgs, string $code) => array_values(array_filter($msgs, fn ($m) => ($m['code'] ?? '') === $code));
    $cfg = fn (string $on) => file_put_contents("$tmp/boot/config/docker.cfg", "DOCKER_ENABLED=\"$on\"\nDOCKER_APP_CONFIG_PATH=\"/mnt/user/appdata/\"\n");

    // Docker switched off, a first setup: a plan, no error, said once; no apps, offsite skipped for Docker
    $cfg('no');
    [$rc, $out] = $setup('--plan');
    $plan = $json('setup-plan.json');
    $st = $json('setup-status.json');
    same('no docker: switched off - the plan is written, no error', [0, 'ok', 0, false], [$rc, $st['result'] ?? null, $st['errors'] ?? null, $plan['docker_service'] ?? null], $out);
    same('no docker: said once, as a hint', [1, 'hint'], [count($coded($plan['messages'] ?? [], 'docker_off')), $coded($plan['messages'] ?? [], 'docker_off')[0]['level'] ?? null]);
    same('no docker: no apps, no containers; no «no Kopia container» hint', [[], [], []],
        [$plan['apps'] ?? null, $plan['containers'] ?? null, $coded($plan['messages'] ?? [], 'kopia_container_none')]);
    check('no docker: the shares are planned as usual', in_array('media', array_column($plan['shares'] ?? [], 'name'), true), json_encode($plan['shares'] ?? null));

    // a setting that wanted offsite while Docker is off: Kopia's part skipped with the reason, still no error
    file_put_contents("$data/settings.ini", "[general]\nserver = Test\nmount_root = $root\ndumps_share = UnraidSecretaryOffice\n[flash]\nmode = off\n"
        . "[kopia]\nenabled = yes\ncontainer = kopia\n[share \"media\"]\nmode = kopia\n");
    [$rc, $out] = $setup('--plan');
    $plan = $json('setup-plan.json');
    same('no docker: offsite wanted - Kopia skipped as docker_off, no error', [0, 'docker_off', 0], [$rc, $plan['kopia']['problem'] ?? null, $json('setup-status.json')['errors'] ?? null], $out);
    @unlink("$data/settings.ini");

    // Docker switched on but silent: an error the office says in its own words
    $cfg('yes');
    [$rc, $out] = $setup('--plan');
    $st = $json('setup-status.json');
    same('no docker: switched on but silent - the setup fails with docker_silent', [true, 'failed', 'error'],
        [$rc !== 0, $st['result'] ?? null, $coded($st['messages'] ?? [], 'docker_silent')[0]['level'] ?? null], $out);

    // Docker answering: as before
    touch("$tmp/fake/up");
    [$rc, $out] = $setup('--plan');
    $plan = $json('setup-plan.json');
    same('no docker: Docker answering - docker_service true, nothing said', [0, true, []], [$rc, $plan['docker_service'] ?? null, $coded($plan['messages'] ?? [], 'docker_off')], $out);
    @unlink("$tmp/fake/up");

    // the run's check: off by docker.cfg or with no docker at all; a missing docker.cfg is never off
    $lib = escapeshellarg(OFFICE_DIR . '/backup/lib/common.sh');
    $off = fn (string $path) => trim((string) shell_exec('bash -c ' . escapeshellarg("PATH=$path UB_DATA=$tmp/x UB_BOOT=$tmp/boot; source $lib >/dev/null 2>&1; ub_docker_service_off && echo off || echo on") . ' 2>&1'));
    $cfg('no');
    $offA = $off("$tmp/bin:/usr/bin:/bin");
    $cfg('yes');
    $offB = $off("$tmp/bin:/usr/bin:/bin");
    unlink("$tmp/boot/config/docker.cfg");
    $offC = $off("$tmp/bin:/usr/bin:/bin");
    @mkdir("$tmp/nodocker", 0700);
    foreach (['grep', 'sed', 'cat', 'date', 'mkdir', 'basename', 'dirname'] as $b) {
        $w = trim((string) shell_exec('command -v ' . $b));
        if ($w !== '') {
            @symlink($w, "$tmp/nodocker/$b");
        }
    }
    $offD = $off("$tmp/nodocker");
    same('no docker: the run\'s check - switched off, on, no docker.cfg, no docker at all', ['off', 'on', 'on', 'off'], [$offA, $offB, $offC, $offD]);
    $bk = (string) file_get_contents(OFFICE_DIR . '/backup/backup.sh');
    check('no docker: a run with Docker off goes on, Docker on but silent still ends it',
        str_contains($bk, 'if ub_docker_service_off; then log "Docker is switched off (Settings > Docker) - no apps to back up"')
        && str_contains($bk, 'else docker info >/dev/null 2>&1 || die "Docker is switched on but does not answer"; fi'));

    // the page: «offsite» greyed with the reason, the apps step and tile say it, a failed plan in the office's words
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('no docker (page): offsite greyed with the reason, apps step and tile', str_contains($js, "const dockerOff = plan.docker_service === false;")
        && str_contains($js, "if (dockerOff && !on) { kbox.querySelector('input').disabled = true;")
        && str_contains($js, "T(plan.docker_service === false ? 'setup.apps_docker_off' : 'setup.apps_none')")
        && str_contains($js, "sub: [T('setup.tile.docker_off')]")
        && str_contains($js, "if (plan.docker_service === false) note(T('setup.k_problem.docker_off'), 'warn');")
        && str_contains($js, "m.code && Office.has(`\${ID}.setup.msg.\${m.code}`) ? T('setup.msg.' + m.code, setupMsgParams(m.params)) : m.text"));
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/en.json'), true) ?: [];
    check('no docker (page): its words', isset($en['setup.msg.docker_off'], $en['setup.msg.docker_silent'], $en['setup.k_problem.docker_off'], $en['setup.apps_docker_off'], $en['setup.tile.docker_off']));
    exec('rm -rf ' . escapeshellarg($tmp));
}

function testSetupListDiff(): void
{
    // the apply dialog (2026-10-09): the same containers in another order are no change; a list shows only what
    // comes and goes
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('setup diff: docker|no_stop, known and skip compared as sets', str_contains($js, "const SET_KEYS = /^docker\\|(no_stop|known|skip)$/;")
        && str_contains($js, '!same(asSet(k, a[k]), asSet(k, b[k]))'));
    check('setup diff: a list shows only what comes and goes', str_contains($js, 'function listChangeText(was, is)')
        && str_contains($js, 'Array.isArray(saved[k]) && Array.isArray(view[k]) ? listChangeText(saved[k], view[k])'));
}

function testMenuName(): void
{
    foreach (['Sekretariat', 'Office', 'USO', 'Mein Büro', 'Büro 2.0', 'A', 'R&D'] as $ok) {
        check("menu name ok: $ok", officeMenuNameValid($ok));
    }
    foreach (['', ' Office', 'Office ', 'x"y', '${HOME}', 'a\\b', "a\nb", '1234567890123456', 'end-', '<b>'] as $bad) {
        check('menu name refused: ' . json_encode($bad), !officeMenuNameValid($bad));
    }
    check('menu name: 15 characters (umlauts count once)', officeMenuNameValid('Büroküche Ölmü'));

    $tmp = sys_get_temp_dir() . '/office-tests-menu-' . getmypid();
    @mkdir($tmp, 0700, true);
    copy(dirname(__DIR__) . '/plugin/' . OFFICE_MENU_PAGE, "$tmp/" . OFFICE_MENU_PAGE);
    $before = (string) file_get_contents("$tmp/" . OFFICE_MENU_PAGE);
    check('menu page: default name in the repository', str_contains($before, "\nName=\"" . OFFICE_MENU_DEFAULT . "\"\n"));
    check('menu page: renamed', officeMenuPageApply($tmp, 'Büro & Co'));
    $after = (string) file_get_contents("$tmp/" . OFFICE_MENU_PAGE);
    same('menu page: only the Name= line changed', str_replace('Name="' . OFFICE_MENU_DEFAULT . '"', 'Name="Büro & Co"', $before), $after);
    same('menu page: Unraid reads the name', 'Büro & Co', parse_ini_string(explode("\n---\n", $after)[0])['Name'] ?? null);
    check('menu page: a bad name changes nothing', !officeMenuPageApply($tmp, 'x"y') && file_get_contents("$tmp/" . OFFICE_MENU_PAGE) === $after);

    // under Settings → User Utilities: Menu=, Title= and Icon=; back in the menu bar as it was
    check('menu page: to Settings', officeMenuPageApply($tmp, 'Büro & Co', 'settings'));
    $ini = parse_ini_string(explode("\n---\n", (string) file_get_contents("$tmp/" . OFFICE_MENU_PAGE))[0]);
    same('menu page: under Settings', ['Utilities', 'Büro & Co', 'Büro & Co', 'unraid-secretary-office.png', 'building-o', 'f0f7'],
        [$ini['Menu'] ?? null, $ini['Name'] ?? null, $ini['Title'] ?? null, $ini['Icon'] ?? null, $ini['Tag'] ?? null, $ini['Code'] ?? null]);
    check('menu page: back to the menu bar', officeMenuPageApply($tmp, OFFICE_MENU_DEFAULT, 'menu'));
    same('menu page: as in the repository again', $before, file_get_contents("$tmp/" . OFFICE_MENU_PAGE));
    check('menu page: an unknown place changes nothing', !officeMenuPageApply($tmp, 'Office', 'dock'));
    same('menu url: menu bar', '/SecretaryOffice', officeMenuUrl('menu'));
    same('menu url: settings', '/Settings/SecretaryOffice', officeMenuUrl('settings'));

    // only a button in Unraid's header: the page without Menu=, the button page with it — and back
    copy(dirname(__DIR__) . '/plugin/' . OFFICE_BUTTON_PAGE, "$tmp/" . OFFICE_BUTTON_PAGE);
    $buttonBefore = (string) file_get_contents("$tmp/" . OFFICE_BUTTON_PAGE);
    check('menu page: to a button', officeMenuPageApply($tmp, 'USO', 'button'));
    $ini = parse_ini_string(explode("\n---\n", (string) file_get_contents("$tmp/" . OFFICE_MENU_PAGE))[0]);
    $btn = parse_ini_string(explode("\n---\n", (string) file_get_contents("$tmp/" . OFFICE_BUTTON_PAGE))[0]);
    same('menu page: no entry of its own as a button', [null, 'USO', 'USO'], [$ini['Menu'] ?? null, $ini['Name'] ?? null, $ini['Title'] ?? null]);
    same('button page: in the header', ['Buttons:90', 'USO', 'building-o', '/SecretaryOffice'], [$btn['Menu'] ?? null, $btn['Title'] ?? null, $btn['Icon'] ?? null, $btn['Href'] ?? null]);
    // its icon: the desk bell as a CSS mask in the header's text colour (Icon=/Code= are only the fallback).
    // Unraid runs a button page's body through parse_text() in <head> of every page: nothing there may match it
    $body = explode("\n---\n", $buttonBefore, 2)[1] ?? '';
    check('button page: the desk bell as a mask in currentColor', preg_match('/\.nav-item\.SecretaryOfficeButton\{--sso-bell:url\("data:image\/svg\+xml,([^"]*)"\)\}/', $body, $m) === 1
        && !preg_match('/[<>#]/', $m[1]) && @simplexml_load_string(rawurldecode($m[1])) !== false
        && str_contains($body, 'mask:var(--sso-bell)') && str_contains($body, 'background-color:currentColor'));
    check('button page: nothing for parse_text', !preg_match('/_\((.+?)\)_|^:(.+_help|.+_plug):$|^:end$/m', $body));
    same('menu url: button', '/SecretaryOffice', officeMenuUrl('button'));
    check('menu page: from the button back to the menu bar', officeMenuPageApply($tmp, OFFICE_MENU_DEFAULT, 'menu'));
    same('menu page: as in the repository after the button', $before, file_get_contents("$tmp/" . OFFICE_MENU_PAGE));
    same('button page: as in the repository again', $buttonBefore, file_get_contents("$tmp/" . OFFICE_BUTTON_PAGE));
    check('menu page: missing page', !officeMenuPageApply("$tmp/none", 'Office'));
    exec('rm -rf ' . escapeshellarg($tmp));
}

function testEstimates(): void
{
    // newest first, like backupHistory()
    $run = fn (string $id, string $result, int $total, array $kopia) => ['run' => $id, 'started' => 1000, 'finished' => 1000 + $total,
        'result' => $result, 'kopia_first' => null,
        'kopia' => array_map(fn ($n, $s) => ['name' => $n, 'ok' => true, 'seconds' => $s, 'finished' => 1000 + $total], array_keys($kopia), $kopia)];
    $first = $run('first', 'warnings', 37632, ['appdata' => 21850]);
    $small = fn (string $id, int $t, int $a) => $run($id, 'ok', $t, ['appdata' => $a]);

    $e = backupEstimates([$small('b', 547, 86), $first]);
    same('estimate: after the first run the newest counts', 547, $e['total']);
    same('estimate: newest Kopia source', 86, $e['sources']['appdata'] ?? null);

    $e = backupEstimates([$run('x', 'failed', 17, []), $run('y', 'aborted', 464, []), $small('b', 547, 86), $first]);
    same('estimate: failed and aborted runs skipped', 547, $e['total']);

    $e = backupEstimates([$small('d', 600, 90), $small('c', 30000, 20000), $small('b', 547, 86), $first]);
    same('estimate: one slow run among three does not count', 600, $e['total']);
    same('estimate: median Kopia of the last three', 90, $e['sources']['appdata'] ?? null);

    $e = backupEstimates([]);
    same('estimate: nothing known', null, $e['total']);
}

/**
 * Mr. Backupsy and a first upload to Kopia: which source has no snapshot in the repository yet (a new
 * repository starts every source anew), the Kopia process found in /proc (a copy), what it read, the
 * snapshot's size, and the rate between looks — replayed with what a large server's upload showed on 2026-10-06
 */
function testBackupFirstUpload(): void
{
    $run = fn (string $id, int $started, array $kopia) => ['run' => $id, 'started' => $started,
        'kopia' => array_map(fn ($n, $ok) => ['name' => $n, 'ok' => $ok, 'seconds' => 3, 'finished' => $started + 60], array_keys($kopia), $kopia)];
    $history = [$run('c', 3000, ['appdata' => true, 'app:immich' => false]), $run('b', 2000, ['Backups_statisch' => true]), $run('a', 1000, ['appdata' => true])];
    same('first upload: copied before, the repository unknown — not the first time', false, backupFirstUpload('Backups_statisch', $history, null));
    same('first upload: copied only into an earlier repository — the first time', true, backupFirstUpload('Backups_statisch', $history, 2500));
    same('first upload: copied since the repository came', false, backupFirstUpload('appdata', $history, 2500));
    same('first upload: failed so far, or never there', [true, true], [backupFirstUpload('app:immich', $history, null), backupFirstUpload('isos', $history, null)]);

    same('first upload: a container path on the host (the longest mapping)', '/mnt/user/appdata/kopia/repository.config',
        backupContainerHostPath([['Source' => '/mnt/user/appdata/kopia', 'Destination' => '/config'], ['Source' => '/mnt/user', 'Destination' => '/']],
            '/config/repository.config'));
    same('first upload: not mapped, or with ..', [null, null], [backupContainerHostPath([['Source' => '/mnt/x', 'Destination' => '/data']], '/config/repository.config'),
        backupContainerHostPath([['Source' => '/mnt/user/appdata/kopia', 'Destination' => '/config']], '/config/../etc/shadow')]);
    $policies = [['kind' => 'share', 'name' => 'Backups_statisch', 'path' => '/backup-snapshots/Backups_statisch'],
                 ['kind' => 'app', 'name' => 'immich', 'path' => '/backup-snapshots/.apps/immich']];
    same('first upload: where Kopia reads a source', [['/backup-snapshots/Backups_statisch', '/Backups_statisch'], ['/backup-snapshots/.apps/immich', '/.apps/immich'],
        [null, '/.vms/Debian'], [null, '/_flash']],
        [backupKopiaSourcePath('Backups_statisch', $policies), backupKopiaSourcePath('app:immich', $policies), backupKopiaSourcePath('vm:Debian', $policies),
         backupKopiaSourcePath('flash', $policies)]);

    // /proc as the host sees the engine's docker exec: the client, Kopia in the container, another source
    $proc = sys_get_temp_dir() . '/office-tests-upload-' . getmypid();
    $ps = ['3123' => ['docker', 'exec', '-u', '0', 'kopia', 'kopia', '--no-progress', 'snapshot', 'create', '/backup-snapshots/Backups_statisch', '--description', 'uso-backup 20261006-0100'],
           '4456' => ['kopia', '--no-progress', 'snapshot', 'create', '/backup-snapshots/Backups_statisch', '--description', 'uso-backup 20261006-0100'],
           '5789' => ['kopia', '--no-progress', 'snapshot', 'create', '/backup-snapshots/Backups_statisch_alt'],
           '6000' => ['kopia', 'server', 'start', '--address=0.0.0.0:51515']];
    foreach ($ps as $pid => $argv) {
        @mkdir("$proc/$pid", 0700, true);
        file_put_contents("$proc/$pid/cmdline", implode("\0", $argv) . "\0");
    }
    file_put_contents("$proc/4456/io", "rchar: 2390370860668\nwchar: 1180491244705\nsyscr: 36974388\nsyscw: 73561450\nread_bytes: 3466402299392\n");
    same('first upload: the Kopia process of the source (not the docker client, not another source)', [4456, 4456, null],
        [backupKopiaPid('/backup-snapshots/Backups_statisch', '/Backups_statisch', $proc), backupKopiaPid(null, '/Backups_statisch', $proc),
         backupKopiaPid('/backup-snapshots/isos', '/isos', $proc)]);
    same('first upload: what it has read (rchar, not what it sent)', [2390370860668, null], [backupProcRead(4456, $proc), backupProcRead(3123, $proc)]);
    same('first upload: read and sent in one look (rchar, wchar)', [[2390370860668, 1180491244705], [null, null]], [backupProcIo(4456, $proc), backupProcIo(3123, $proc)]);
    exec('rm -rf ' . escapeshellarg($proc));

    $zfs = "rowan/Backups_statisch@uso-backup-20261005-0100\t2355000000000\nrowan/Backups_statisch@uso-backup-20261006-0100\t2355490998272\n"
         . "rowan/Backups_statisch/child@uso-backup-20261006-0100\t1000\nrowan/Backups_statisch/child@other\t5\n";
    same('first upload: the size of this run\'s snapshot, child datasets too', [2355490999272, null],
        [backupZfsSnapSum($zfs, 'uso-backup-20261006-0100'), backupZfsSnapSum($zfs, 'uso-backup-20261007-0100')]);

    // a large server, 2026-10-06: Backups_statisch from 04:18:47; at 13:20 the snapshot (2.36 TB) was read past its size — done 13:27:58
    $c = ['source' => 'Backups_statisch', 'size' => 2355490998272, 'looks' => []];
    [$c, $o] = backupUploadStep($c, 1791253127, 2390370860668, 1791285605, 1180491244705);
    same('first upload: the first look — the average since it started, any moment now', ['Backups_statisch', true, 73599694, 0, 1],
        [$o['source'], $o['first'], $o['rate'], $o['left'], count($c['looks'])]);
    same('first upload: what it sent goes along to the page, the rate stays what it reads', [1180491244705, 2390370860668], [$o['sent'], $o['read']]);
    // a made-up one: 1 TB, 100 MB/s on average, 50 MB/s for the last minutes
    $t0 = 1000000;
    $c = ['source' => 'x', 'size' => 10 ** 12, 'looks' => []];
    [$c, $o] = backupUploadStep($c, $t0, 0, $t0 + 30);
    same('first upload: too early for a rate (nothing sent known)', [null, null, 0, null], [$o['rate'], $o['left'], $o['read'], $o['sent']]);
    [$c, $o] = backupUploadStep($c, $t0, 360 * 10 ** 9, $t0 + 3600);
    same('first upload: from the newest look before the last 15 minutes', [100840336, 6347], [$o['rate'], $o['left']]);
    [$c, $o] = backupUploadStep($c, $t0, 360 * 10 ** 9 + 300 * 50 * 10 ** 6, $t0 + 3900);
    same('first upload: the rate between looks minutes apart', [50000000, 12500], [$o['rate'], $o['left']]);
    for ($t = $t0 + 3920; $t <= $t0 + 6000; $t += 5) {
        [$c] = backupUploadStep($c, $t0, 375 * 10 ** 9 + ($t - $t0 - 3900) * 50 * 10 ** 6, $t);
    }
    check('first upload: a look every 20 seconds, the last 15 minutes and one before', count($c['looks']) <= BACKUP_UPLOAD_KEEP / 20 + 2
        && $t0 + 6000 - $c['looks'][0][0] > BACKUP_UPLOAD_KEEP && $t0 + 6000 - $c['looks'][1][0] <= BACKUP_UPLOAD_KEEP, json_encode([count($c['looks']), $c['looks'][0] ?? null]));
    [, $o] = backupUploadStep(['source' => 'x', 'size' => null, 'looks' => []], $t0, 10 ** 9, $t0 + 600);
    same('first upload: no size, no estimate (but a rate)', [null, 1666667], [$o['left'], $o['rate']]);
}

/**
 * The very first backup's rough estimate (2026-10-15, «No estimate yet» for hours): backupRough() gives the page the sizes of
 * the run's Kopia sources — in the Kopia step only, one new source per call (the tick stays cheap), kept per run; the page
 * reckons (tests/backuptiles.js «first estimate»). Asked for only while no good run exists (the state's 'rough').
 */
function testBackupRough(): void
{
    $cache = TESTS_RUN_DIR . '/backup-rough-test.json';
    @unlink($cache);
    $asked = [];
    $size = function (string $n) use (&$asked): ?int {
        $asked[] = $n;
        return ['appdata' => 100, 'media' => 5000][$n] ?? null;
    };
    $st = fn (string $phase, string $run = 'r1') => ['run' => $run, 'phase' => $phase, 'snapshot' => 'uso-backup-20261015-0100',
        'kopia' => ['planned' => ['appdata', 'media', 'flash'], 'done' => [], 'current' => 'appdata', 'current_since' => 1]];
    same('rough: nothing before the Kopia step', null, backupRough($st('snapshots'), [], $cache, $size));
    same('rough: one source per look, the others still unknown', [['appdata' => 100, 'media' => null, 'flash' => null], false, ['appdata']],
        [backupRough($st('kopia'), [], $cache, $size)['sizes'], backupRough($st('kopia'), [], $cache, $size)['complete'], array_slice($asked, 0, 1)]);
    $r = backupRough($st('kopia'), [], $cache, $size);
    same('rough: every source looked at once — a size not told stays null', [['appdata' => 100, 'media' => 5000, 'flash' => null], true, ['appdata', 'media', 'flash']],
        [$r['sizes'], $r['complete'], $asked]);
    backupRough($st('kopia'), [], $cache, $size);
    same('rough: never looked at again in the same run', 3, count($asked));
    backupRough($st('kopia', 'r2'), [], $cache, $size);
    same('rough: a new run looks anew', 4, count($asked));
    $mine = backupEstimates([]);
    same('rough: asked for only while no good run exists (estimates.total null)', null, $mine['total']);
    @unlink($cache);
}

/**
 * Mr. Backupsy's packages (engine 2.18): the office's reader on a made-up backup place, and the
 * engine's own helpers (lib/common.sh section 8: folder names, old run folders, an interrupted swap)
 */
function testBackupPackages(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-packages-' . getmypid();
    $put = function (string $file, mixed $data) use ($tmp): void {
        @mkdir(dirname("$tmp/$file"), 0700, true);
        file_put_contents("$tmp/$file", is_string($data) ? $data : json_encode($data));
    };
    $put('server/run.json', ['run' => '20261006-0200', 'result' => 'ok', 'files' => [['path' => 'libvirt.tar.gz', 'bytes' => 9, 'run' => '20261005-0200']]]);
    $put('server/libvirt.tar.gz', 'x');
    $put('apps/immich/manifest.json', ['name' => 'immich', 'type' => 'compose', 'run' => '20261006-0200', 'result' => 'warnings',
        'compose' => ['manager_dir' => 'immich'],
        'containers' => [['name' => 'immich_postgres', 'image' => 'ghcr.io/immich-app/postgres:14', 'digests' => ['ghcr.io/immich-app/postgres@sha256:ab'], 'inspect' => ['Id' => 'x']]],
        'dumps' => [['container' => 'immich_postgres', 'type' => 'postgres', 'state' => 'failed', 'login' => 'user', 'user_var' => 'POSTGRES_USER',
                     'password_var' => 'POSTGRES_PASSWORD', 'client' => 'psql', 'secret' => 'never']],
        'files' => [['path' => 'db/postgres_immich_postgres.sql.gz', 'bytes' => 100, 'run' => '20261005-0200', 'what' => 'dump', 'container' => 'immich_postgres'],
                    ['path' => 'compose/docker-compose.yml', 'bytes' => 20, 'run' => '20261006-0200', 'what' => 'compose']]]);
    $put('apps/gone/manifest.json', ['name' => 'gone', 'type' => 'template', 'run' => '20261001-0200', 'files' => []]);
    $put('apps/.ub-old-20261006-0200-immich/manifest.json', ['name' => 'aside']);
    $put('vms/Win_11/manifest.json', ['name' => 'Win 11', 'run' => '20261006-0200', 'xml' => 'Win_11.xml', 'uuid' => 'u-1', 'autostart' => true,
        'files' => [['path' => 'Win_11.xml', 'bytes' => 5], ['path' => 'nvram/u-1_VARS-pure-efi-tpm.fd', 'bytes' => 7], ['path' => 'tpm/u-1/tpm2/tpm2-00.permall', 'bytes' => 3]]]);
    $put('flash/manifest.json', ['run' => '20261006-0200', 'files' => [['path' => 'flash.tar.gz', 'bytes' => 4, 'run' => '20261004-0200']]]);
    $put('flash/flash.tar.gz', 'flsh');
    $put('20261001-0200/db/mariadb_x_y.sql.gz', 'x');            // an old run folder: the next run clears it away
    $put('20261002-0200/notes.txt', 'mine');                       // holds something else: stays, not counted

    $p = backupPackagesRead($tmp);
    same('packages: the last run', '20261006-0200', $p['run']);
    same('packages: apps, hidden folders left out', ['gone', 'immich'], array_column($p['apps'], 'folder'));
    same('packages: an app of an earlier run is stale', [true, false], array_column($p['apps'], 'stale'));
    $immich = $p['apps'][1];
    $dump = array_values(array_filter($immich['files'], fn ($f) => $f['what'] === 'dump'))[0] ?? [];
    same('packages: a kept dump keeps its run', ['20261005-0200', 'immich_postgres'], [$dump['run'] ?? null, $dump['container'] ?? null]);
    same('packages: dump credentials as names only', ['container' => 'immich_postgres', 'type' => 'postgres', 'state' => 'failed', 'login' => 'user',
        'user_var' => 'POSTGRES_USER', 'password_var' => 'POSTGRES_PASSWORD', 'client' => 'psql'], $immich['dumps'][0] ?? null);
    same('packages: no docker inspect for the page', ['name', 'image', 'image_id', 'digest', 'template'], array_keys($immich['containers'][0] ?? []));
    same('packages: bytes from the manifest', 120, $immich['bytes']);
    $vm = $p['vms'][0] ?? [];
    same('packages: a VM with NVRAM and TPM', ['Win 11', ['u-1_VARS-pure-efi-tpm.fd'], true, true, false],
        [$vm['name'] ?? null, $vm['nvram'] ?? null, $vm['tpm'] ?? null, $vm['autostart'] ?? null, $vm['snapshotdb'] ?? null]);
    same('packages: the libvirt archive in server/', "$tmp/server/libvirt.tar.gz", $p['server']['libvirt'] ?? null);
    same('packages: the flash archive keeps its run', '20261004-0200', $p['flash']['run'] ?? null);
    same('packages: old run folders the engine clears away', 1, $p['old_runs']);
    exec('rm -rf ' . escapeshellarg($tmp));

    // the engine's helpers, in bash
    $lib = escapeshellarg(OFFICE_DIR . '/backup/lib/common.sh');
    $sh = fn (string $script) => trim((string) shell_exec('bash -c ' . escapeshellarg("source $lib >/dev/null 2>&1; $script") . ' 2>&1'));
    same('engine: folder names', 'Windows_11__G__ming_|_hidden|immich|_|', $sh('printf "%s|" "$(pkg_folder "Windows 11 (Gäming)")" "$(pkg_folder ".hidden")" "$(pkg_folder immich)" "$(pkg_folder "")"'));
    $t = escapeshellarg(sys_get_temp_dir() . '/office-tests-engine-' . getmypid());
    same('engine: old run folders', '20261001-0200,20261003-0200', $sh("T=$t; mkdir -p \$T/20261001-0200/db \$T/20261002-0200 \$T/20261003-0200/manifest \$T/2026-x \$T/apps;"
        . ' echo x >$T/20261002-0200/mine.txt; : >$T/20261003-0200/libvirt.tar.gz; old_runs_list $T | xargs -n1 basename | paste -sd, -'));
    same('engine: an interrupted swap is put right', 'apps:a b|vms:v|left:0', $sh("T=$t; rm -rf \$T; mkdir -p \$T/apps/a \$T/apps/.ub-old-20261006-0200-a \$T/apps/.ub-old-20261006-0200-b"
        . ' $T/vms/.ub-old-20261006-0200-v $T/.ub-stage-20261006-0200/apps/a; touch $T/apps/a/new; pkg_recover $T >/dev/null;'
        . ' printf "apps:%s|vms:%s|left:%s" "$(ls $T/apps | paste -sd" " -)" "$(ls $T/vms)" "$(ls -A $T | grep -c "^\.ub-")"; [ -e $T/apps/a/new ] || echo " lost"'));
    exec('rm -rf ' . $t);
    same('engine 2.23: the btrfs brake scales with the disk (min_free_gb, at most a tenth, at least 1 GB, 0 = off)', '150|2|1|0|300|1',
        $sh('BTRFS_MIN_FREE_GB=150; a=$(brake_floor_gb 22000); b=$(brake_floor_gb 24); c=$(brake_floor_gb 5); BTRFS_MIN_FREE_GB=0; d=$(brake_floor_gb 22000);'
        . ' BTRFS_MIN_FREE_GB=300; e=$(brake_floor_gb 22000); BTRFS_MIN_FREE_GB=150; f=$(brake_floor_gb x); printf "%s|%s|%s|%s|%s|%s" $a $b $c $d $e $f'));
}

/**
 * Mr. Backupsy's Kopia per app and VM (engine 2.19): the engine's items, the rules the shares get for their
 * parts, the targets, the checks of settings.ini, sleeping disks, SQLite URIs; settings.ini of 2.18 (no
 * [app] sections) gives the very same rules as before; the office's reader of policies and packages.
 */
function testBackupKopiaItems(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-items-' . getmypid();
    @mkdir($tmp, 0700, true);
    $ini = "[general]\ndumps_share = UnraidSecretaryOffice\nmount_root = /mnt/addons/UnraidSecretaryOffice/snapshots\n"
         . "[kopia]\nenabled = yes\n[share \"appdata\"]\nmode = kopia\nkopia_ignore = /kopia/\n[share \"UnraidSecretaryOffice\"]\nmode = kopia\n";
    file_put_contents("$tmp/old.ini", $ini);
    file_put_contents("$tmp/new.ini", $ini
        . "[app \"nextcloud\"]\nkopia = yes\nfolder = appdata/nextcloud\nkopia_retention = 7 0 14 8 24 5\nkopia_ignore = /appdata/nextcloud/data/cache/\n"
        . "[app \"my app\"]\nkopia = yes\nfolder = appdata/myapp\n[app \"my_app\"]\nkopia = yes\n[app \"left\"]\nkopia = no\nfolder = appdata/left\n"
        . "[vm \"Win 11\"]\nmode = snapshot\nprepare = freeze\nkopia = yes\nfolder = domains/Win 11\n");
    file_put_contents("$tmp/bad.ini", $ini . "[app \"x\"]\nkopia = maybe\nfolder = appdata/../etc\nfolder = /appdata/x\nkopia_retention = 7 7\n");
    file_put_contents("$tmp/disks.ini", "[\"disk1\"]\nname=\"disk1\"\nspundown=\"0\"\n[\"disk10\"]\nname=\"disk10\"\nspundown=\"1\"\n"
        . "[\"maple\"]\nname=\"maple\"\nspundown=\"0\"\n[\"maple2\"]\nname=\"maple2\"\nspundown=\"1\"\n[\"rowan\"]\nname=\"rowan\"\nspundown=\"0\"\n");
    $lib = escapeshellarg(OFFICE_DIR . '/backup/lib/common.sh');
    $sh = function (string $file, string $script) use ($lib, $tmp): string {
        $pre = "UB_DATA=$tmp/data UB_DISKS_INI=$tmp/disks.ini; source $lib >/dev/null 2>&1; cfg_load $tmp/$file; cfg_validate >/dev/null; apply_settings;"
             . ' INV_METHOD[appdata]=snap; INV_LAYOUT[appdata]=single; INV_LOCS[appdata]="maple|zfs|maple/appdata|"$\'\\n\';'
             . ' INV_METHOD[UnraidSecretaryOffice]=snap; INV_LAYOUT[UnraidSecretaryOffice]=single; PLAN_KOPIA=(UnraidSecretaryOffice appdata); PLAN_FLASH=off;';
        return trim((string) shell_exec('bash -c ' . escapeshellarg("$pre $script") . ' 2>&1'));
    };
    $md5 = substr(md5('my_app'), 0, 6);
    same('items: apps first (sorted), then VMs; a name that comes out the same gets a suffix; kopia = no is none',
        "app|my app|my_app\napp|my_app|my_app-$md5\napp|nextcloud|nextcloud\nvm|Win 11|Win_11", $sh('new.ini', 'kopia_items'));
    same('items: an app\'s parts - its folders, then its package', "appdata|nextcloud\nUnraidSecretaryOffice|backup/apps/nextcloud",
        $sh('new.ini', 'kopia_item_parts app nextcloud'));
    same('items: a VM\'s package', "domains|Win 11\nUnraidSecretaryOffice|backup/vms/Win_11", $sh('new.ini', 'kopia_item_parts vm "Win 11"'));
    same('items: the share leaves their folders out, besides its own rules', "/kopia/\n/myapp/\n/nextcloud/", $sh('new.ini', 'kopia_want_ignores share appdata'));
    same('items: the backup place leaves their packages out', "/backup/apps/my_app/\n/backup/apps/nextcloud/\n/backup/vms/Win_11/",
        $sh('new.ini', 'kopia_want_ignores share UnraidSecretaryOffice'));
    same('items: a split share gets a rule per base', "/disk1/myapp/\n/disk1/nextcloud/\n/kopia/\n/maple/myapp/\n/maple/nextcloud/",
        $sh('new.ini', 'INV_LAYOUT[appdata]=split; INV_LOCS[appdata]="maple|zfs|x|"$\'\\n\'"disk1|btrfs|/mnt/disk1|appdata"; kopia_want_ignores share appdata'));
    same('items: own rules and retention, or inherited', "/appdata/nextcloud/data/cache/|7 0 14 8 24 5|inherit inherit inherit inherit inherit inherit",
        $sh('new.ini', 'printf "%s|%s|%s" "$(kopia_want_ignores app nextcloud)" "$(kopia_want_retention app nextcloud)" "$(kopia_want_retention app "my app")"'));
    $root = '/mnt/addons/UnraidSecretaryOffice/snapshots';
    same('items: the targets', "root|$root|\nshare|$root/UnraidSecretaryOffice|UnraidSecretaryOffice\nshare|$root/appdata|appdata\n"
        . "app|$root/.apps/my_app|my app\napp|$root/.apps/my_app-$md5|my_app\napp|$root/.apps/nextcloud|nextcloud\nvm|$root/.vms/Win_11|Win 11",
        $sh('new.ini', 'kopia_targets'));
    same('items: none with Kopia off', '', $sh('new.ini', 'KOPIA_ENABLED=no; kopia_items'));
    same('settings.ini of 2.18: no items, the same rules and targets as before', "|/kopia/|root|$root|\nshare|$root/UnraidSecretaryOffice|UnraidSecretaryOffice\nshare|$root/appdata|appdata",
        $sh('old.ini', 'printf "%s|%s|%s" "$(kopia_items)" "$(kopia_want_ignores share appdata)" "$(kopia_targets)"'));
    same('items: settings.ini valid', '0', $sh('new.ini', 'echo ${#CFG_ERRORS[@]}'));
    same('items: bad keys found', '4', $sh('bad.ini', 'echo ${#CFG_ERRORS[@]}'));
    same('engine: sleeping disks (a pool sleeps with any of its disks, disk1 is not disk10)', 'maple disk10',
        $sh('new.ini', 'for b in maple disk1 disk10 rowan map; do ub_base_asleep $b && printf "%s " $b; done'));
    same('engine: a path for an SQLite URI', '/a%20b/Plug-in%20Support/%C3%A4%3F%23.db', $sh('new.ini', 'uri_escape "/a b/Plug-in Support/ä?#.db"'));
    same('engine: a container path on the host', '/mnt/user/appdata/plex/Library/x|/mnt/user/Backups/Emby|1',
        $sh('new.ini', 'CT_BINDS[c]="/mnt/user/appdata/plex|/config|true"$\'\\n\'"/mnt/user/Backups/Emby|/config/backup|true";'
            . ' printf "%s|%s|" "$(ct_host_path c /config/Library/x)" "$(ct_host_path c /config/backup)"; ct_host_path c /data || echo 1'));
    exec('rm -rf ' . escapeshellarg($tmp));

    // the office: policies of apps and VMs, and what a package says about its databases and the app's own backups
    $pol = backupPolicies([['kind' => 'app', 'share' => '', 'name' => 'nextcloud', 'path' => '/backup-snapshots/.apps/nextcloud', 'ok' => true, 'differences' => []],
                           ['kind' => 'share', 'share' => 'appdata', 'path' => '/backup-snapshots/appdata', 'ok' => false, 'differences' => [['what' => 'ignore_missing', 'item' => '/nextcloud/']]],
                           ['kind' => 'odd', 'share' => 'x']]);
    same('policies: apps and VMs, the name (older engines: the share)', [['app', 'nextcloud'], ['share', 'appdata']], array_map(fn ($p) => [$p['kind'], $p['name']], $pol));
    $tmp = sys_get_temp_dir() . '/office-tests-items-pk-' . getmypid();
    @mkdir("$tmp/apps/emby", 0700, true);
    @mkdir("$tmp/server", 0700, true);
    file_put_contents("$tmp/server/run.json", json_encode(['run' => '20261006-0200']));
    file_put_contents("$tmp/apps/emby/manifest.json", json_encode(['name' => 'EmbyServer', 'type' => 'template', 'run' => '20261006-0200',
        'sqlite' => [['container' => 'EmbyServer', 'file' => 'db/sqlite_EmbyServer_library.db', 'source' => '/mnt/user/appdata/EmbyServer/data/library.db',
                      'path' => '/config/data/library.db', 'state' => 'unchanged', 'check' => 'ok', 'present' => true]],
        'own_backups' => [['kind' => 'emby', 'container' => 'EmbyServer', 'path' => '/mnt/user/Backups/EmbyServer', 'files' => 3, 'newest' => 1791200000, 'asleep' => false],
                          ['kind' => 'odd', 'path' => '/etc']],
        'files' => [['path' => 'db/sqlite_EmbyServer_library.db', 'bytes' => 9, 'run' => '20261006-0200', 'what' => 'sqlite', 'container' => 'EmbyServer']]]));
    $a = backupPackagesRead($tmp)['apps'][0] ?? [];
    same('packages: the SQLite copies', ['/config/data/library.db', 'unchanged', 'ok', true], [$a['sqlite'][0]['path'] ?? null, $a['sqlite'][0]['state'] ?? null, $a['sqlite'][0]['check'] ?? null, $a['sqlite'][0]['present'] ?? null]);
    same('packages: the app\'s own backups, known kinds only', [['emby', '/mnt/user/Backups/EmbyServer', 3]], array_map(fn ($o) => [$o['kind'], $o['path'], $o['files']], $a['own_backups'] ?? []));
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Engine 2.21: new things stay local and keep running until the user decided. The engine's rules (which
 * top-level folder is new, the rules that leave it out, kopia_known in settings.ini), the run's step right
 * before Kopia (fixture folders as the mounted snapshot, the policy's rules, state/new-local.json, drift,
 * one notification) and setup.sh --plan / --apply on a fixture server: stand-ins for docker (Kopia inside),
 * zfs, virsh, mount and notify on PATH - nothing real is touched, no Kopia, no mount, no container.
 * Engine 2.37: a new folder inherits its share's level - only the shares Unraid names for app configs and VMs
 * (docker.cfg, domain.cfg of the fixture) keep new folders waiting, and there a folder follows its app or VM.
 * Engine 2.38: a folder of an app or VM set up before and only local stays local with it, silently (kept-local.json).
 */
function testBackupNewLocal(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-newlocal-' . getmypid();
    exec('rm -rf ' . escapeshellarg($tmp));
    $mnt = "$tmp/mnt";
    $root = "$mnt/addons/UnraidSecretaryOffice/snapshots";
    foreach (["$tmp/bin", "$tmp/fake", "$tmp/data/unraid-backup/state", "$tmp/boot/config/shares", "$root/appdata"] as $d) {
        @mkdir($d, 0700, true);
    }
    $lib = escapeshellarg(OFFICE_DIR . '/backup/lib/common.sh');
    $env = "export PATH=$tmp/bin:\$PATH UB_DATA=$tmp/data/unraid-backup UB_MNT=$mnt UB_BOOT=$tmp/boot UB_SHARES_CFG=$tmp/boot/config/shares"
         . " UB_DISKS_INI=$tmp/fake/disks.ini UB_NOTIFY_BIN=$tmp/bin/notify UB_MOUNTS_FILE=$tmp/fake/mounts FAKE=$tmp/fake FAKE_ROOT=$root";
    // stand-ins: every call of docker logged, Kopia answers from fixtures, "policy set" only noted
    file_put_contents("$tmp/bin/docker", <<<'SH'
#!/bin/bash
echo "$*" >>"$FAKE/docker.log"
case "$1" in
  info) exit 0 ;;
  version) echo 29.0; exit 0 ;;
  ps) cat "$FAKE/ids" 2>/dev/null; exit 0 ;;
  compose) exit 1 ;;
  top) printf 'PID UID COMMAND\n7 0 /app/kopia server start\n'; exit 0 ;;
  inspect)
    shift
    if [[ "$1" == -f ]]; then
      case "$2" in
        *State.Running*) echo true ;;
        *Mounts*) printf '%s\x1e/uso\x1efalse\x1erslave\n' "$FAKE_ROOT" ;;
      esac
      exit 0
    fi
    cat "$FAKE/inspect.json"; exit 0 ;;
  exec)
    shift
    while [[ "$1" == -* ]]; do case "$1" in -u|-e) shift 2 ;; *) shift ;; esac; done
    shift
    case "$1" in
      cat) [[ "$2" == /proc/self/mountinfo ]] && exit 0; cat "$FAKE_ROOT${2#/uso}" 2>/dev/null; exit ;;
      kopia)
        shift; [[ "$1" == --no-progress ]] && shift
        case "$1 ${2:-}" in
          "repository status") cat "$FAKE/repo.json" ;;
          "policy list") cat "$FAKE/policies.json" 2>/dev/null || echo '[]' ;;
          "policy set") [[ -n "${FAKE_POLICY_FAIL:-}" ]] && exit 1 ;;
          "snapshot list") echo '[]' ;;
          --version*) echo "0.23.0 build" ;;
        esac
        exit 0 ;;
    esac
    exit 1 ;;
esac
exit 0
SH);
    file_put_contents("$tmp/bin/zfs", "#!/bin/bash\n[[ \"\$*\" == *'-t filesystem'* ]] && cat \"\$FAKE/zfs.txt\"\nexit 0\n");
    file_put_contents("$tmp/bin/virsh", <<<'SH'
#!/bin/bash
case "$1" in
  list) [[ "$*" == *--all* ]] && printf 'oldvm\nnewvm\n'; exit 0 ;;
  domstate) echo "shut off" ;;
  dominfo) echo "Autostart:      disable" ;;
  dumpxml) echo "<domain/>" ;;
  domblklist) printf 'Type Device Target Source\n'; [[ "$*" == *oldvm* ]] && printf 'file disk vda %s/user/domains/oldvm/vdisk1.img\n' "$UB_MNT" ;;
esac
exit 0
SH);
    file_put_contents("$tmp/bin/mountpoint", "#!/bin/bash\n[[ \"\${@: -1}\" == */user ]]\n");
    file_put_contents("$tmp/bin/mount", "#!/bin/bash\nmkdir -p \"\${@: -1}\"\n");
    file_put_contents("$tmp/bin/umount", "#!/bin/bash\nexit 0\n");
    file_put_contents("$tmp/bin/notify", "#!/bin/bash\nprintf '%s\\n' \"\$*\" >>\"\$FAKE/notify.log\"\n");
    foreach (glob("$tmp/bin/*") as $f) {
        chmod($f, 0755);
    }
    $sh = fn (string $script) => trim((string) shell_exec('bash -c ' . escapeshellarg("$env; source $lib >/dev/null 2>&1; $script") . ' 2>&1'));
    // engine 2.37: Unraid's places for app configs and VMs - the app/VM shares (as Unraid writes them: /mnt/user/...)
    file_put_contents("$tmp/boot/config/docker.cfg", "DOCKER_ENABLED=\"yes\"\nDOCKER_APP_CONFIG_PATH=\"/mnt/user/appdata/\"\n");
    file_put_contents("$tmp/boot/config/domain.cfg", "SERVICE=\"enable\"\nDOMAINDIR=\"/mnt/user/domains/\"\n");

    // --- engine 2.37: which shares are app/VM shares - by Unraid's settings, only the share itself
    same('app/VM shares: docker.cfg and domain.cfg name them (a pool path too), by those settings only',
        'appdata=docker domains=vm', $sh('ub_app_shares_load; for s in $(printf "%s\n" "${!APP_SHARE[@]}" | sort); do printf "%s=%s " "$s" "${APP_SHARE[$s]}"; done'));
    same('app/VM shares: one share for both, a pool path, a path deeper inside a share (no app share), files missing (none)',
        'stuff=docker vm|none|none',
        $sh("d=\$(mktemp -d); mkdir -p \$d/config; printf 'DOCKER_APP_CONFIG_PATH=\"/mnt/cache/stuff\"\\n' >\$d/config/docker.cfg; printf 'DOMAINDIR=\"/mnt/user/stuff/\"\\n' >\$d/config/domain.cfg;"
            . ' UB_BOOT=$d; ub_app_shares_load; for s in "${!APP_SHARE[@]}"; do printf "%s=%s" "$s" "${APP_SHARE[$s]}"; done;'
            . " printf 'DOCKER_APP_CONFIG_PATH=\"/mnt/user/data/appdata/\"\\n' >\$d/config/docker.cfg; rm \$d/config/domain.cfg; APP_SHARES_LOADED=; ub_app_shares_load; printf '|%s' \"\${#APP_SHARE[@]}\" | sed 's/|0/|none/';"
            . ' rm -f $d/config/docker.cfg; APP_SHARES_LOADED=; ub_app_shares_load; printf "|%s" "${#APP_SHARE[@]}" | sed "s/|0/|none/"; rm -rf $d'));
    same('app/VM shares: a path\'s share and top folder', 'appdata|nc appdata| domains|vm1 x|y - - -',
        $sh('for p in /mnt/user/appdata/nc/config /mnt/cache/appdata/ /mnt/user/domains/vm1/vdisk1.img "$UB_MNT/disk1/x/y/z" /mnt/addons/x/y /boot/x /mnt/user; do printf "%s " "$(ub_path_share_part "$p" || echo -)"; done'));

    // --- the rules: which top-level folder is new
    file_put_contents("$tmp/s.ini", "[general]\ndumps_share = UnraidSecretaryOffice\nmount_root = $root\n[kopia]\nenabled = yes\nignore = _UnraidSecretaryOffice-trash*/\nignore = .DS_Store\n"
        . "[share \"appdata\"]\nmode = kopia\nkopia_ignore = /kopia/\nkopia_ignore = /cache*/\nkopia_ignore = /deep/cache/\nkopia_known = /a/\nkopia_known = /decided/\n"
        . "[share \"UnraidSecretaryOffice\"]\nmode = kopia\nkopia_known =\n[share \"docs\"]\nmode = kopia\n[share \"local\"]\nmode = snapshot\nkopia_known = /x/\n"
        . "[app \"nc\"]\nkopia = yes\nfolder = appdata/nc\n");
    $pre = "cfg_load $tmp/s.ini; cfg_validate >/dev/null; apply_settings; INV_METHOD[appdata]=snap; INV_LAYOUT[appdata]=single;"
         . ' INV_LOCS[appdata]="maple|zfs|maple/appdata|"$\'\\n\'; INV_METHOD[UnraidSecretaryOffice]=snap; INV_LAYOUT[UnraidSecretaryOffice]=single;';
    same('new: settings.ini with kopia_known is valid (an empty one too)', '0', $sh("$pre echo \${#CFG_ERRORS[@]}"));
    file_put_contents("$tmp/bad.ini", "[share \"x\"]\nmode = kopia\nkopia_known = a\nkopia_known = /a/b/\nkopia_known = /../\nkopia_known = /ok/\n");
    same('new: kopia_known must be /<folder>/', '3', $sh("cfg_load $tmp/bad.ini; cfg_validate >/dev/null; echo \${#CFG_ERRORS[@]}"));
    same('new: watched - an app/VM share going to Kopia with kopia_known; a data share never (2.37: even with kopia_known, also empty), without it, or only local: as before',
        'appdata', $sh("$pre for s in appdata UnraidSecretaryOffice docs local; do share_watched \$s && printf '%s ' \$s; done"));
    // engine 2.37: who a folder of an app/VM share belongs to, and whether that one goes offsite
    $own = "$pre CT_NAMES=(ncweb newapp old kopia); CT_PROJECT[ncweb]=nc; CT_BINDS[ncweb]=\"/mnt/user/appdata/nc-extra/x|/x|true\"\$'\\n'\"/mnt/user/nextcloud_data|/data|true\";"
         . ' CT_BINDS[newapp]="/mnt/cache/appdata/newapp|/config|true"; CT_BINDS[old]="/mnt/user/appdata/a|/a|true"$\'\\n\'"/mnt/user/appdata/a2|/b|true"; CT_BINDS[kopia]="/mnt/user/appdata/kopia|/config|true";'
         . ' VM_NAMES=(vmk vml); VM_DISKS[vmk]="vda|/mnt/user/domains/vmk/vdisk1.img|maple|zfs||domains"; VM_DISKS[vml]="vda|/mnt/user/domains/vml/vdisk1.img|maple|zfs||domains";'
         . ' CFG[vm|vmk|kopia]=yes; CFG[share|domains|mode]=kopia;';
    same('owners: binds and VM disks in the app/VM shares only (a bind of a data share - Nextcloud\'s data - makes no owner)',
        'appdata|a=app|old appdata|a2=app|old appdata|kopia=app|kopia appdata|nc-extra=app|nc appdata|newapp=app|newapp domains|vmk=vm|vmk domains|vml=vm|vml',
        $sh("$own top_owners_load; for k in \$(printf '%s\\n' \"\${!TOP_OWNERS[@]}\" | sort); do printf '%s=%s ' \"\$k\" \"\${TOP_OWNERS[\$k]%\$'\\n'}\"; done"));
    same('owners: a folder follows its app/VM - its own Kopia source (nc, vmk), an app with another folder recorded (old: /a/ known - settings before 2.19); a new app, a local VM, no owner: not',
        'nc-extra=1 a2=1 newapp=0 b=0 vmk=1 vml=0',
        $sh("$own for n in nc-extra a2 newapp b; do top_owner_offsite appdata \$n && printf '%s=1 ' \$n || printf '%s=0 ' \$n; done; for n in vmk vml; do top_owner_offsite domains \$n && printf '%s=1 ' \$n || printf '%s=0 ' \$n; done"));
    // engine 2.38: an app/VM set up before ([docker] known / a [vm] section) and only local keeps its new folder local
    $kept = "$own CT_NAMES+=(loc); CT_BINDS[loc]=\"/mnt/user/appdata/locnew|/a|true\"\$'\\n'\"/mnt/user/appdata/both|/b|true\";"
          . ' CT_BINDS[newapp]+=$\'\\n\'"/mnt/user/appdata/both|/x|true"; DOCKER_KNOWN=(old kopia ncweb loc); CFG_SECTIONS+=("vm|vml");'
          . ' VM_NAMES+=(vmnew); VM_DISKS[vmnew]="vda|/mnt/user/domains/vmnew/vdisk1.img|maple|zfs||domains";';
    same('owners (2.38): kept local - an app with a known container (locnew), a VM with a section (vml); a new app (newapp), a folder of a new and an old app (both), no owner (b), a VM without a section (vmnew): not; no [docker] known list at all - every container counts as set up',
        'locnew=1 newapp=0 both=0 b=0 vml=1 vmnew=0|newapp=1',
        $sh("$kept for n in locnew newapp both b; do top_owner_kept_local appdata \$n && printf '%s=1 ' \$n || printf '%s=0 ' \$n; done;"
            . " for n in vml vmnew; do top_owner_kept_local domains \$n && printf '%s=1 ' \$n || printf '%s=0 ' \$n; done | sed 's/ \$//';"
            . " DOCKER_KNOWN=(); top_owner_kept_local appdata newapp && printf '|newapp=1' || printf '|newapp=0'"));
    same('owners: an offsite app\'s new folder is decided (it goes with the share), the others stay new',
        'nc-extra=1 a2=1 newapp=0 b=0',
        $sh("$own new_decided_load appdata; for n in nc-extra a2 newapp b; do new_decided appdata \$n && printf '%s=1 ' \$n || printf '%s=0 ' \$n; done"));
    same('new: what is decided - known, own and global rules, an app\'s own part, the backup place\'s folder',
        'a=1 decided=1 kopia=1 cache2=1 deep=0 nc=1 _UnraidSecretaryOffice-trash-1=1 .UnraidSecretaryOffice-trash=1 .DS_Store=1 b=0 ncx=0 backup:place=1 other:place=0',
        $sh("$pre new_decided_load appdata; for n in a decided kopia cache2 deep nc _UnraidSecretaryOffice-trash-1 .UnraidSecretaryOffice-trash .DS_Store b ncx; do new_decided appdata \"\$n\" && printf '%s=1 ' \$n || printf '%s=0 ' \$n; done;"
            . ' new_decided_load UnraidSecretaryOffice; new_decided UnraidSecretaryOffice backup && printf "backup:place=1 " || printf "backup:place=0 "; new_decided UnraidSecretaryOffice other && printf "other:place=1" || printf "other:place=0"'));
    same('new: fancier rules never count as leaving a folder out (it stays new - left out by the run itself)', '0 0 0 0 1 1',
        $sh('for r in "/@(b)/" "/b\\\\x/" "!/b/" "/b/c/" "b" "/b"; do rule_hides_top "$r" b && printf "1 " || printf "0 "; done'));
    same('new: a pattern character in a folder becomes ? in its rule', "/we ird?1??/\n/x/", $sh("$pre new_rules_for appdata 'we ird[1]*'; new_rules_for appdata x"));
    same('new: a split share gets a rule per base', "/maple/x/\n/disk1/x/",
        $sh("$pre INV_LAYOUT[appdata]=split; INV_LOCS[appdata]=\"maple|zfs|maple/appdata|\"\$'\\n'\"disk1|btrfs|/mnt/disk1|appdata\"; new_rules_for appdata x"));
    foreach (['a', 'b', 'decided', 'kopia', 'nc', 'still', 'we ird[1]', '_UnraidSecretaryOffice-trash-1', '.zfs'] as $d) {
        @mkdir("$root/appdata/$d", 0700, true);
    }
    symlink("$root/appdata/a", "$root/appdata/link");
    touch("$root/appdata/file");
    same('new: the folders at the top - no links, files or .zfs', "_UnraidSecretaryOffice-trash-1\na\nb\ndecided\nkopia\nnc\nstill\nwe ird[1]",
        $sh("top_dirs $root/appdata | LC_ALL=C sort"));
    same('new: a collection (kopia_known = *) is not watched - every folder goes', '0|',
        $sh("$pre CFG[share|appdata|kopia_known]='*'; cfg_validate >/dev/null; printf '%s|' \${#CFG_ERRORS[@]}; share_watched appdata && echo watched"));
    same('new: a folder\'s size only where cheap - a ZFS dataset of its own', '42|',
        $sh("$pre INV_BASE_PATH[maple]=/p; INV_CHILDREN[appdata]=\$'maple|maple/appdata/b|/p/appdata/b\\n'; ZDS_REF[maple/appdata/b]=42; printf '%s|%s' \"\$(new_folder_bytes appdata b)\" \"\$(new_folder_bytes appdata c)\""));
    same('new: the wanted policy of a share includes the rules for its new folders', "/cache*/\n/deep/cache/\n/kopia/\n/nc/\n/still/",
        $sh("$pre NEW_RULES[appdata]=/still/; kopia_want_ignores share appdata"));

    // --- the run, right before Kopia: the snapshot's folders, the policy, the state, drift, one notification
    file_put_contents("$tmp/data/unraid-backup/state/new-local.json", json_encode(['interface' => 1, 'folders' => [
        ['share' => 'appdata', 'folder' => 'still', 'bytes' => null, 'first_seen' => 1000, 'rules' => ['/still/']],
        ['share' => 'appdata', 'folder' => 'decided', 'bytes' => null, 'first_seen' => 1000, 'rules' => ['/decided/']],
        ['share' => 'appdata', 'folder' => 'vanished', 'bytes' => 7, 'first_seen' => 1000, 'rules' => ['/vanished/']],
        ['share' => 'docs', 'folder' => 'x', 'first_seen' => 1000, 'rules' => ['/x/']],
        ['share' => 'UnraidSecretaryOffice', 'folder' => 'olduser', 'first_seen' => 1000, 'rules' => ['/olduser/']],
        ['share' => "odd\nshare", 'folder' => 'x', 'first_seen' => 1, 'rules' => ['/x/']]]]));
    // UnraidSecretaryOffice stands for a data share like nextcloud_data: recorded up to 2.36 (kopia_known =), an engine 2.36 left
    // its new folder olduser out - 2.37 takes that rule away and lets a new folder newuser go along
    foreach (['backup', 'olduser', 'newuser'] as $d) {
        @mkdir("$root/UnraidSecretaryOffice/$d", 0700, true);
    }
    $kp = json_encode([['target' => ['path' => '/uso/appdata', 'userName' => 'root', 'host' => 'kopia'],
        'policy' => [], 'files' => ['ignore' => ['/kopia/', '/still/', '/decided/', '/vanished/']]],
        ['target' => ['path' => '/uso/UnraidSecretaryOffice', 'userName' => 'root', 'host' => 'kopia'], 'policy' => [], 'files' => ['ignore' => ['/olduser/']]]]);
    file_put_contents("$tmp/kp.json", $kp);
    $run = "$pre ub_data_dirs; TS=20261007-0100; LOG_FILE=$tmp/run.log; KOPIA_CONTAINER=kopia; KOPIA_USER=root; KOPIA_HOST=kopia; KOPIA_ID=root@kopia;"
         . " KP_JSON=\"\$(cat $tmp/kp.json)\"; KM_SRC=($root); KM_DST=(/uso); KM_RW=(false); KM_PROP=(rslave); PLAN_KOPIA=(appdata UnraidSecretaryOffice docs);"
         . ' declare -A SHARE_MOUNTED=([appdata]=single [UnraidSecretaryOffice]=single); ST_ACTIVE=yes; ST_MODE=backup; ST_STARTED=1;';
    same('run: before Kopia - what the last run left out and is still undecided (decided ones go, data shares go - no known_missing for docs, a data share, 2.37)',
        "appdata/still appdata/vanished |/still/\n/vanished/|new_waiting new_waiting |decided:/decided/ UnraidSecretaryOffice:/olduser/ docs:/x/",
        $sh("$run drift_check_new_local; for l in \"\${NEW_LIST[@]}\"; do IFS=\$'\\x1f' read -r s n _ <<<\"\$l\"; printf '%s/%s ' \$s \$n; done;"
            . ' printf "|%s|" "${NEW_RULES[appdata]%$\'\\n\'}"; for c in "${DRIFT_CODE[@]}"; do printf "%s " "${c%%$\'\\x1f\'*}"; done;'
            . ' printf "|"; for x in appdata UnraidSecretaryOffice docs; do [[ -n "${NEW_GOING[$x]:-}" ]] && printf "%s:%s " "$([[ $x == appdata ]] && echo decided || echo $x)" "$(sed "/^$/d" <<<"${NEW_GOING[$x]}" | tr "\n" ",")"; done | sed "s/,//g"'));
    same('run: the policy comparison tolerates the rules of folders no longer new (the run takes them away itself) - other extra rules still differ',
        '0|1', $sh("$run KP_JSON=\"\$(cat $tmp/kp.json)\"; kopia_policy_eval /uso/UnraidSecretaryOffice share '' 'inherit inherit inherit inherit inherit inherit' \$'/olduser/\\n'; printf '%s|' \$?;"
            . " kopia_policy_eval /uso/UnraidSecretaryOffice share '' 'inherit inherit inherit inherit inherit inherit' ''; printf '%s' \$?"));
    $out = $sh("$run drift_check_new_local; new_local_run; echo \"skip=\${SKIP_KOPIA[appdata]:-}\"");
