    $sh2 = array_column($plan['shares'] ?? [], null, 'name');
    same('setup plan: a new folder waits in an app share, the record stays (a gone folder drops out); in data shares nothing waits, nothing is recorded',
        [[['dir' => 'zz-new', 'bytes' => null, 'first_seen' => null]], ['/bigds/', '/bitcoin2/', '/c1/'], [], [], ['/olddir/'], null],
        [$sh2['appdata']['waiting'] ?? null, $plan['P']['share|appdata|kopia_known'] ?? null, $sh2['docs']['waiting'] ?? null, $sh2['UnraidSecretaryOffice']['waiting'] ?? null,
         $plan['P']['share|docs|kopia_known'] ?? null, $plan['P']['share|UnraidSecretaryOffice|kopia_known'] ?? null]);
    @unlink("$tmp/fake/docker.log");
    file_put_contents("$tmp/dec.json", json_encode($plan['P'] + ['_retire_sources' => 'no']));
    $out = $setup("--apply=$tmp/dec.json");
    $log = (string) @file_get_contents("$tmp/fake/docker.log");
    check('setup apply: undecided - Kopia\'s policy leaves the new folder out', (bool) preg_match('#policy set root@kopia:/uso/appdata .*--add-ignore /zz-new/#', $log), $log . $out);
    check('setup apply: a data share\'s new folders are left out of nothing (2.37)', !str_contains($log, '/newdoc/') && !str_contains($log, '/newuser/'), $log);
    check('setup apply: undecided - not recorded', !str_contains((string) @file_get_contents("$data/settings.ini"), 'kopia_known = /zz-new/'));
    // decided: local + Kopia
    @unlink("$tmp/fake/docker.log");
    file_put_contents("$tmp/fake/policies.json", json_encode([['target' => ['path' => '/uso/appdata', 'userName' => 'root', 'host' => 'kopia'], 'files' => ['ignore' => ['/kopia/', '/zz-new/']]]]));
    $dec = $plan['P'];
    $dec['share|appdata|kopia_known'][] = '/zz-new/';
    file_put_contents("$tmp/dec.json", json_encode($dec + ['_retire_sources' => 'no']));
    $setup("--apply=$tmp/dec.json");
    $log = (string) @file_get_contents("$tmp/fake/docker.log");
    check('setup apply: decided for Kopia - recorded, and its rule goes', str_contains((string) @file_get_contents("$data/settings.ini"), 'kopia_known = /zz-new/')
        && (bool) preg_match('#policy set root@kopia:/uso/appdata .*--remove-ignore /zz-new/#', $log), $log);
    // a container that came after the plan stays new at Apply
    file_put_contents("$tmp/fake/ids", "id1\nid2\nid3\nid4\n");
    $all = json_decode((string) file_get_contents("$tmp/fake/inspect.json"));
    $all[] = $ct('late', 'redis', []);
    file_put_contents("$tmp/fake/inspect.json", json_encode($all));
    $setup("--apply=$tmp/dec.json");
    $ini = (string) @file_get_contents("$data/settings.ini");
    check('setup apply: a container that came after the plan stays new (keeps running, not known)', !str_contains($ini, 'known = late') && str_contains($ini, 'no_stop = late'), $ini);
    // the share Unraid's syslog server writes into (rsyslog.cfg): proposed not backed up — the routers' words, not yours
    @mkdir("$pool/syslog", 0700, true);
    touch("$tmp/boot/config/shares/syslog.cfg");
    file_put_contents("$tmp/fake/mounts", "maple/syslog $pool/syslog zfs rw 0 0\n", FILE_APPEND);
    file_put_contents("$tmp/fake/zfs.txt", $z('maple/syslog', "$pool/syslog", 10), FILE_APPEND);
    file_put_contents("$tmp/boot/config/rsyslog.cfg", "local_server=\"1\"\nserver_folder=\"/mnt/user/syslog\"\nserver_filename=\"syslog-%FROMHOST-IP%.log\"\n");
    $out = $setup('--plan');
    $plan = json_decode((string) @file_get_contents("$data/state/setup-plan.json"), true) ?: [];
    $sh3 = array_column($plan['shares'] ?? [], null, 'name');
    same('setup plan: the share Unraid\'s syslog server writes into — proposed not backed up (why syslog), flagged syslog (2.32); the others not', ['off', 'syslog', true, false],
        [$plan['P']['share|syslog|mode'] ?? null, $sh3['syslog']['why'] ?? null, $sh3['syslog']['syslog'] ?? null, $sh3['docs']['syslog'] ?? null], $out);

    // --- engine 2.31: [general] preset_new, Mr. Backupsy's default for new things - kept, carried by the plan, never acted on
    $pnLine = fn (string $ini) => preg_match('/\[general\][^\[]*\npreset_new = ([a-z]+)\n/', $ini, $mm) ? $mm[1] : null;
    $pnPending = fn (array $plan) => array_values(array_filter($plan['pending'] ?? [], fn ($p) => str_contains($p['line'] ?? '', 'preset_new')));
    $pnApply = function (?string $value) use ($tmp, $data, $setup): string {
        $plan = json_decode((string) @file_get_contents("$data/state/setup-plan.json"), true) ?: [];
        $dec = $plan['P'] ?? [];
        if ($value === null) {
            unset($dec['general|preset_new']);
        } else {
            $dec['general|preset_new'] = $value;
        }
        file_put_contents("$tmp/dec.json", json_encode($dec + ['_retire_sources' => 'no']));
        return $setup("--apply=$tmp/dec.json");
    };
    same('preset_new: a settings.ini without the key - the plan carries auto (top level and P), nothing pending', ['auto', 'auto', []],
        [$plan['preset_new'] ?? null, $plan['P']['general|preset_new'] ?? null, $pnPending($plan)]);
    $pnApply('auto');
    $ini = (string) @file_get_contents("$data/settings.ini");
    same('preset_new: auto on a settings.ini without the key - no line (nothing changes for an install that never chose)', [null, false],
        [$pnLine($ini), str_contains($ini, 'preset_new =')]);
    $setup('--plan');
    $out = $pnApply('local');
    $ini = (string) @file_get_contents("$data/settings.ini");
    same('preset_new: the decision local written under [general]', 'local', $pnLine($ini), $ini . $out);
    same('preset_new: the settings written load without errors (the run accepts the key)', '0', $sh("cfg_load $data/settings.ini; cfg_validate >/dev/null; echo \${#CFG_ERRORS[@]}"));
    $setup('--plan');
    $plan = json_decode((string) @file_get_contents("$data/state/setup-plan.json"), true) ?: [];
    same('preset_new: the next plan carries it, nothing pending for it', ['local', 'local', []],
        [$plan['preset_new'] ?? null, $plan['P']['general|preset_new'] ?? null, $pnPending($plan)]);
    // 2.32: the syslog share is in settings.ini now - its why is «as before», the flag stays (so a default never switches it on)
    $sh3 = array_column($plan['shares'] ?? [], null, 'name');
    same('setup plan: the syslog share once set up - why previous, still flagged syslog (2.32), its mode kept', ['previous', true, 'off', false],
        [$sh3['syslog']['why'] ?? null, $sh3['syslog']['syslog'] ?? null, $plan['P']['share|syslog|mode'] ?? null, $sh3['docs']['syslog'] ?? null]);
    $pnApply('kopia');
    same('preset_new: kopia written', 'kopia', $pnLine((string) @file_get_contents("$data/settings.ini")));
    $setup('--plan');
    $pnApply(null);
    same('preset_new: decisions without the key keep the one settings.ini has', 'kopia', $pnLine((string) @file_get_contents("$data/settings.ini")));
    $setup('--plan');
    $pnApply('auto');
    same('preset_new: auto once settings.ini had the key - written as auto', 'auto', $pnLine((string) @file_get_contents("$data/settings.ini")));
    // by hand: a value it doesn't know - the run refuses the file (like any bad value), the setup takes it as auto and says so
    file_put_contents("$data/settings.ini", preg_replace('/\npreset_new = auto\n/', "\npreset_new = maybe\n", (string) file_get_contents("$data/settings.ini")));
    $bad = $sh("cfg_load $data/settings.ini; cfg_validate >/dev/null; printf '%s' \"\${CFG_ERRORS[*]}\"");
    check('preset_new: settings.ini takes auto, local or kopia only', str_contains($bad, "preset_new = 'maybe' is invalid (auto/local/kopia/partner/kopia_partner)"), $bad);
    $out = $setup('--plan');
    $plan = json_decode((string) @file_get_contents("$data/state/setup-plan.json"), true) ?: [];
    $warned = array_filter($plan['messages'] ?? [], fn ($m) => ($m['level'] ?? '') === 'warn' && str_contains($m['text'] ?? '', "preset_new = 'maybe' is not auto, local, kopia, partner or kopia_partner"));
    same('preset_new: a value it doesn\'t know - auto in the plan, with a warning', ['auto', 'auto', true], [$plan['preset_new'] ?? null, $plan['P']['general|preset_new'] ?? null, (bool) $warned], $out);
    $pnApply('local');
    // --forget: settings.ini goes aside with the key in it - the next setup starts as on a new server (auto)
    $out = $setup('--forget --yes');
    $reset = glob("$data/state/reset-*/settings.ini") ?: [];
    same('preset_new: --forget puts it aside with settings.ini', [false, 'local'],
        [file_exists("$data/settings.ini"), $reset ? $pnLine((string) file_get_contents(end($reset))) : null], $out);
    $setup('--plan');
    $plan = json_decode((string) @file_get_contents("$data/state/setup-plan.json"), true) ?: [];
    same('preset_new: after --forget the plan is a new server\'s - auto', [false, 'auto', 'auto'], [$plan['have_settings'] ?? null, $plan['preset_new'] ?? null, $plan['P']['general|preset_new'] ?? null]);
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Engine 2.22: VMs with prepare = shutdown go down before anything stops. backup.sh runs on a fixture
 * server — stand-ins for docker, zfs, zpool, btrfs, virsh, mount and notify on PATH, its data, the
 * shares and the backup place in a temporary folder (no Kopia, no notification, nothing real is
 * stopped, snapshotted or started): the order of what it did (one events file the stand-ins write),
 * downtime_s, status.json vms and state/vms — a VM that shuts down, one that ignores the request
 * (paused right before the snapshot), one that goes off late (while the apps stopped: started again,
 * not paused), a VM paused as before; a run without such VMs; a run stopped while a VM goes down (it
 * waits for it and starts it again); a run killed then (the next start starts it).
 */
function testBackupVmOrder(): void
{
    if (posix_getuid() !== 0) {
        check('vm order: backup.sh runs as root only — not run here', true);
        return;
    }
    $tmp = sys_get_temp_dir() . '/office-tests-vmorder-' . getmypid();
    exec('rm -rf ' . escapeshellarg($tmp));
    $mnt = "$tmp/mnt";
    $pool = "$mnt/maple";
    $fake = "$tmp/fake";
    $data = "$tmp/data/unraid-backup";
    $vms = ['vmshut', 'vmdeaf', 'vmlate', 'vmpause', 'vmslow'];
    foreach (["$tmp/bin", "$fake/vm", "$fake/ct", "$data/state", "$tmp/boot/config/shares", "$mnt/user/UnraidSecretaryOffice", "$pool/appdata/c1",
              "$pool/UnraidSecretaryOffice/backup", "$tmp/stage"] as $d) {
        @mkdir($d, 0700, true);
    }
    foreach ($vms as $v) {
        @mkdir("$pool/domains/$v", 0700, true);
        touch("$pool/domains/$v/vdisk1.img");
    }
    foreach (['appdata', 'domains', 'UnraidSecretaryOffice'] as $n) {
        touch("$tmp/boot/config/shares/$n.cfg");
    }
    file_put_contents("$fake/mounts", "maple $pool zfs rw 0 0\nmaple/appdata $pool/appdata zfs rw 0 0\nmaple/domains $pool/domains zfs rw 0 0\n"
        . "maple/UnraidSecretaryOffice $pool/UnraidSecretaryOffice zfs rw 0 0\nshfs $mnt/user fuse.shfs rw 0 0\n");
    $z = fn ($n, $mp) => "$n\t$mp\ton\t" . crc32($n) . "\t1000\t-\n";
    file_put_contents("$fake/zfs.txt", $z('maple', $pool) . $z('maple/appdata', "$pool/appdata") . $z('maple/domains', "$pool/domains")
        . $z('maple/UnraidSecretaryOffice', "$pool/UnraidSecretaryOffice"));
    file_put_contents("$fake/inspect.json", json_encode([['Name' => '/c1', 'Id' => 'id1', 'Config' => ['Image' => 'nginx', 'Env' => [], 'Labels' => new stdClass()],
        'State' => ['Running' => true], 'HostConfig' => ['NetworkMode' => 'bridge'],
        'Mounts' => [['Type' => 'bind', 'Source' => "$mnt/user/appdata/c1", 'Destination' => '/config', 'RW' => true]]]]));
    // the stand-ins note what changes something, with the second it happened: "<time> <what>"
    file_put_contents("$tmp/bin/docker", <<<'SH'
#!/bin/bash
ev() { echo "$(date +%s) $*" >>"$FAKE/events"; }
st() { cat "$FAKE/ct/$1" 2>/dev/null || echo running; }
case "$1" in
  info|version) exit 0 ;;
  ps) [[ "$*" == *q* ]] && echo id1 || printf 'c1\tnginx\tUp\n'; exit 0 ;;
  inspect)
    shift
    if [[ "$1" == -f ]]; then
      case "$2" in
        *Health*) [[ "$(st "$3")" == running ]] && echo "true " || echo "false " ;;
        *State.Running*) [[ "$(st "$3")" == running ]] && echo true || echo false ;;
      esac
      exit 0
    fi
    [[ "$1" == --format ]] && { echo "/c1  nginx  sha256:1"; exit 0; }
    cat "$FAKE/inspect.json"; exit 0 ;;
  stop) shift; while [[ "$1" == -* ]]; do shift 2; done
        for c in "$@"; do echo stopped >"$FAKE/ct/$c"; ev "docker stop $c"; done; exit 0 ;;
  start) shift; for c in "$@"; do echo running >"$FAKE/ct/$c"; ev "docker start $c"; done; exit 0 ;;
esac
exit 1
SH);
    // VMs: how each answers a shutdown request ($FAKE/vm/<name>.how): obey (off at once), deaf (never),
    // late (off once the apps were stopped), slow (off only once the test lets it: <name>.go - never by the clock;
    // while <name>.hold exists the request itself doesn't return: a stop lands while virsh shutdown runs)
    file_put_contents("$tmp/bin/virsh", <<<'SH'
#!/bin/bash
ev() { echo "$(date +%s) $*" >>"$FAKE/events"; }
V="$FAKE/vm"; n="${2:-}"
[[ "$2" == --* ]] && n="${@: -1}"
state() {
  local s; s="$(cat "$V/$n.state" 2>/dev/null || echo running)"
  if [[ "$s" == running && -e "$V/$n.asked" ]]; then
    case "$(cat "$V/$n.how" 2>/dev/null)" in
      late) grep -q 'docker stop' "$FAKE/events" 2>/dev/null && s="shut off" ;;
      slow) [[ -e "$V/$n.go" ]] && s="shut off" ;;
    esac
    [[ "$s" == "shut off" ]] && echo "$s" >"$V/$n.state"
  fi
  echo "$s"
}
case "$1" in
  list) cat "$FAKE/vms"; exit 0 ;;
  domstate) state; exit 0 ;;
  dominfo) echo "Autostart:      disable"; exit 0 ;;
  dumpxml) echo "<domain><name>$n</name><uuid>uuid-$n</uuid></domain>"; exit 0 ;;
  domblklist) printf 'Type Device Target Source\n----\nfile disk vdisk1 %s\n' "$MNT/user/domains/$n/vdisk1.img"; exit 0 ;;
  qemu-agent-command|domfsfreeze) [[ "$(cat "$V/$n.how" 2>/dev/null)" == freeze* ]] && { ev "virsh freeze $n"; exit 0; }; exit 1 ;;
  domfsthaw) ev "virsh thaw $n"; [[ "$(cat "$V/$n.how" 2>/dev/null)" == freeze-stuck ]] && exit 1; exit 0 ;;
  shutdown) ev "virsh shutdown $n"; [[ -e "$V/$n.asked" ]] || date +%s >"$V/$n.asked"
            [[ "$(cat "$V/$n.how" 2>/dev/null)" == obey ]] && echo "shut off" >"$V/$n.state"
            i=0; while [[ -e "$V/$n.hold" ]] && (( i++ < 100 )); do sleep 0.1; done; exit 0 ;;
  suspend) [[ "$(state)" == running ]] || exit 1; echo paused >"$V/$n.state"; ev "virsh suspend $n"; exit 0 ;;
  resume) echo running >"$V/$n.state"; ev "virsh resume $n"; exit 0 ;;
  start) [[ "$(state)" == "shut off" ]] || exit 1; echo running >"$V/$n.state"; rm -f "$V/$n.asked"; ev "virsh start $n"; exit 0 ;;
esac
exit 0
SH);
    file_put_contents("$tmp/bin/zfs", "#!/bin/bash\ncase \"\$*\" in *'-t filesystem'*) cat \"\$FAKE/zfs.txt\" ;; snapshot*) echo \"\$(date +%s) zfs \$*\" >>\"\$FAKE/events\" ;; esac\nexit 0\n");
    foreach (['zpool', 'btrfs', 'umount'] as $b) {
        file_put_contents("$tmp/bin/$b", "#!/bin/bash\nexit 0\n");
    }
    file_put_contents("$tmp/bin/mount", "#!/bin/bash\nexit 1\n");
    file_put_contents("$tmp/bin/mountpoint", "#!/bin/bash\n[[ \"\${@: -1}\" == */user ]]\n");
    file_put_contents("$tmp/bin/notify", "#!/bin/bash\necho \"\$*\" >>\"\$FAKE/notify.log\"\n");
    foreach (glob("$tmp/bin/*") as $f) {
        chmod($f, 0755);
    }
    $clock = "$fake/clock";
    testsClock("$tmp/bin", $clock);
    $env = "export PATH=$tmp/bin:\$PATH UB_DATA=$data UB_MNT=$mnt UB_BOOT=$tmp/boot UB_SHARES_CFG=$tmp/boot/config/shares UB_STAGE=$tmp/stage"
         . " UB_DISKS_INI=$fake/disks.ini UB_MOUNTS_FILE=$fake/mounts UB_NOTIFY_BIN=$tmp/bin/notify UB_NO_NOTIFY=1 FAKE=$fake MNT=$mnt"
         . ' UB_VM_SHUTDOWN_TIMEOUT=4 UB_VM_SHUTDOWN_RETRY=2';
    $settings = function (array $prep) use ($mnt, $data): void {
        $ini = "[general]\nserver = Test\nmount_root = $mnt/addons/UnraidSecretaryOffice/snapshots\nview_root = $mnt/addons/UnraidSecretaryOffice/btrfs-snap\n"
             . "snap_prefix = uso-backup-\ndumps_share = UnraidSecretaryOffice\nmin_free_gb = 0\n[docker]\nstop = all\nknown = c1\n[flash]\nmode = off\n"
             . "[libvirt]\nmode = off\n[kopia]\nenabled = no\n[share \"appdata\"]\nmode = snapshot\n[share \"domains\"]\nmode = snapshot\n"
             . "[share \"UnraidSecretaryOffice\"]\nmode = snapshot\n";
        foreach ($prep as $vm => $p) {
            $ini .= "[vm \"$vm\"]\nmode = snapshot\nprepare = $p\n";
        }
        file_put_contents("$data/settings.ini", $ini);
    };
    // a fresh night: every VM and the container running, nothing noted
    $night = function (array $how) use ($fake, $data, $vms): void {
        exec('rm -rf ' . escapeshellarg("$fake/vm") . ' ' . escapeshellarg("$fake/ct") . ' ' . escapeshellarg("$fake/events"));
        @mkdir("$fake/vm", 0700, true);
        @mkdir("$fake/ct", 0700, true);
        foreach ($how as $vm => $h) {
            file_put_contents("$fake/vm/$vm.how", $h);
        }
        file_put_contents("$fake/vms", implode("\n", array_keys($how)) . "\n");
        @unlink("$data/state/status.json");
    };
    $events = function () use ($fake): array {
        $out = [];
        foreach (file("$fake/events", FILE_IGNORE_NEW_LINES) ?: [] as $l) {
            [$t, $what] = explode(' ', $l, 2) + [1 => ''];
            $out[] = [(int) $t, preg_replace('/^zfs snapshot .*/', 'zfs snapshot', $what)];
        }
        return $out;
    };
    $at = function (array $ev, string $what, bool $last = false): ?int {
        $found = null;
        foreach ($ev as $i => [, $w]) {
            if ($w === $what) {
                $found = $i;
                if (!$last) {
                    break;
                }
            }
        }
        return $found;
    };
    // every run its own minute (the tests' clock)
    $run = function (string $args = '', string $more = '') use ($env, $clock): string {
        testsClockRun($clock);
        return testsClockRan('vm order', (string) shell_exec('bash -c ' . escapeshellarg("$env $more; bash " . escapeshellarg(OFFICE_DIR . '/backup/backup.sh') . " $args </dev/null") . ' 2>&1'));
    };
    $log = fn () => (string) @file_get_contents("$data/logs/latest.log");
    $status = fn () => json_decode((string) @file_get_contents("$data/state/status.json"), true) ?: [];

    // --- a night with a VM that shuts down, one that ignores it, one that goes off late, one paused, one to freeze whose
    // guest agent doesn't answer (2.42: the notification goes out here - its level)
    $settings(['vmshut' => 'shutdown', 'vmdeaf' => 'shutdown', 'vmlate' => 'shutdown', 'vmpause' => 'pause', 'vmslow' => 'freeze']);
    $night(['vmshut' => 'obey', 'vmdeaf' => 'deaf', 'vmlate' => 'late', 'vmpause' => 'obey', 'vmslow' => 'obey']);
    @unlink("$fake/notify.log");
    $out = $run('', 'UB_NO_NOTIFY=0');
    $ev = $events();
    $s = $status();
    $l = $log();
    $names = array_column($ev, 1);
    $stop = $at($ev, 'docker stop c1');
    $snap = $at($ev, 'zfs snapshot');
    check('vm order: the run went through', in_array($s['result'] ?? '', ['ok', 'warnings'], true) && $stop !== null && $snap !== null, $out . $l);
    check('vm order: every shutdown request (and the repeated one) before the first app stops',
        $stop !== null && $at($ev, 'virsh shutdown vmdeaf', true) < $stop && $at($ev, 'virsh shutdown vmshut') < $stop && $at($ev, 'virsh shutdown vmlate', true) < $stop
        && count(array_keys($names, 'virsh shutdown vmdeaf', true)) >= 2, json_encode($names));
    check('vm order: the apps stop only once the deadline passed — they never waited for a VM',
        $stop !== null && $ev[$stop][0] - $ev[$at($ev, 'virsh shutdown vmshut')][0] >= 4, json_encode($ev));
    $start = $at($ev, 'docker start c1');
    check('vm order: downtime_s is the apps\' stop only (from their stop to their start, not the VMs\' wait)',
        $start !== null && $stop !== null && ($s['downtime_s'] ?? -1) >= 0 && ($s['downtime_s'] ?? 99) <= $ev[$start][0] - $ev[$stop][0] + 1 && ($s['downtime_s'] ?? 99) < 4,
        json_encode([$s['downtime_s'] ?? null, $ev]));
    check('vm order: the VM that ignored its shutdown and the one to pause are paused after the apps, right before the snapshot',
        $stop !== null && $snap !== null && $stop < $at($ev, 'virsh suspend vmdeaf') && $at($ev, 'virsh suspend vmdeaf') < $snap
        && $stop < $at($ev, 'virsh suspend vmpause') && $at($ev, 'virsh suspend vmpause') < $snap, json_encode($names));
    check('vm order: the one off late is not paused, nor the one shut down', !in_array('virsh suspend vmlate', $names, true) && !in_array('virsh suspend vmshut', $names, true), json_encode($names));
    check('vm order: after the snapshot all are back, before the apps start',
        $snap !== null && $start !== null && $snap < $at($ev, 'virsh start vmshut') && $at($ev, 'virsh start vmshut') < $start
        && $snap < $at($ev, 'virsh start vmlate') && $snap < $at($ev, 'virsh resume vmdeaf') && $snap < $at($ev, 'virsh resume vmpause'), json_encode($names));
    $byVm = array_column($s['vms'] ?? [], null, 'name');
    same('vm order: status.json vms — what was done with each',
        [['shutdown', 'shutdown'], ['shutdown', 'paused'], ['shutdown', 'shutdown'], ['pause', 'paused']],
        array_map(fn ($v) => [$byVm[$v]['prepare'] ?? null, $byVm[$v]['done'] ?? null], ['vmshut', 'vmdeaf', 'vmlate', 'vmpause']));
    check('vm order: seconds held — a shutdown from its request, the ignored one from its pause',
        ($byVm['vmshut']['seconds'] ?? 0) >= 4 && ($byVm['vmdeaf']['seconds'] ?? 99) < 4, json_encode($s['vms'] ?? null));
    $pos = fn (string $needle) => ($p = strpos($l, $needle)) === false ? null : $p;
    // 2.42: the deadline is a plain line; the warning comes when the VM is really paused instead (vm_hold)
    $order = [$pos('VMs: shutting down 3 before anything stops'), $pos("VM 'vmshut': shut down"), $pos("  VM 'vmdeaf' did not shut down within 4 s"),
              $pos('Nextcloud ...'), $pos('Pausing apps: 1'), $pos("WARNING: VM 'vmdeaf' did not shut down within 4 s"), $pos("VM 'vmdeaf': paused"),
              $pos("VM 'vmlate': shut down (after its deadline)"), $pos('Creating snapshots')];
    $sorted = $order;
    sort($sorted);
    check('vm order: the log tells it in that order', !in_array(null, $order, true) && $order === $sorted, json_encode($order) . "\n" . $l);
    // engine 2.42: the VMs held otherwise than set up are coded warnings - the one off late is none
    same('vm order: status.json warning_items — the ignored shutdown and the failed freeze, coded (the late one: none)',
        [['code' => 'vm_not_shut_down', 'params' => ['name' => 'vmdeaf', 'seconds' => '4']], ['code' => 'vm_not_frozen', 'params' => ['name' => 'vmslow']]],
        $s['warning_items'] ?? null);
    same('vm order: two warnings, the result «warnings», last-run.json carries the items',
        [2, 'warnings', $s['warning_items'] ?? null],
        [$s['warnings'] ?? null, $s['result'] ?? null, (json_decode((string) @file_get_contents("$data/state/last-run.json"), true) ?: [])['warning_items'] ?? null]);
    check('vm order: no WARNING line for the VM off after its deadline', !preg_match("/WARNING: VM 'vmlate'/", $l), $l);
    $note = (string) @file_get_contents("$fake/notify.log");
    check('vm order: the notification is a warning, not an alert, and says why the VMs were paused',
        str_contains($note, '-s Unraid Secretary Office: Mr. Backupsy: Backup with warnings') && str_contains($note, '-i warning') && !str_contains($note, '-i alert')
        && str_contains($note, 'did not shut down - paused for') && str_contains($note, 'not frozen - paused for'), $note);
    check('vm order: nothing left in state/vms', !file_exists("$data/state/vms"));

    // --- a night without a VM to shut down: no wait, no line, the same order as before
    $settings(['vmpause' => 'pause']);
    $night(['vmpause' => 'obey']);
    $run();
    $ev = $events();
    $names = array_column($ev, 1);
    $l = $log();
    check('vm order: no VM to shut down — no request, no line, the apps stop and the VM is paused before the snapshot',
        !preg_grep('/^virsh shutdown/', $names) && !str_contains($l, 'shutting down') && $at($ev, 'docker stop c1') !== null
        && $at($ev, 'docker stop c1') < $at($ev, 'virsh suspend vmpause') && $at($ev, 'virsh suspend vmpause') < $at($ev, 'zfs snapshot'), json_encode($names) . $l);

    // --- stopped while a VM goes down: the run waits until it is off and starts it again; nothing else was stopped.
    // Twice: stopped while the request itself runs (virsh shutdown hasn't returned; bash runs the trap right after
    // it, before the line after it - the engine counts the VM as asked from before the request, 2026-10-09) and
    // while the run waits for it. No race with the real clock (this part failed 1 run in 3 when the VM went off
    // 3 s after its request and the deadline was 4 s): the VM goes off only once the stopped run said it waits
    // for it, so it is neither off before the stop (the apps would stop) nor after the run gave up; the deadline
    // far off and no repeated request here (the first night covers both).
    $settings(['vmslow' => 'shutdown']);
    $until = function (callable $ok): bool {
        for ($i = 0; $i < 300 && !$ok(); $i++) {
            usleep(50000);
        }
        return $ok();
    };
    foreach (['during the request' => true, 'while waiting' => false] as $when => $inFlight) {
        $night(['vmslow' => 'slow']);
        if ($inFlight) {
            touch("$fake/vm/vmslow.hold");
        }
        $t = testsClockRun($clock);
        // this run's own log (latest.log is the run before until this one has the lock)
        $runLog = fn () => (string) @file_get_contents("$data/logs/run-" . date('Ymd-Hi', $t) . '.log');
        $p = proc_open(['bash', '-c', "$env UB_VM_SHUTDOWN_TIMEOUT=60 UB_VM_SHUTDOWN_RETRY=120; exec bash " . escapeshellarg(OFFICE_DIR . '/backup/backup.sh') . ' </dev/null >/dev/null 2>&1'], [], $pipes);
        $pid = proc_get_status($p)['pid'];
        $until($inFlight ? fn () => str_contains((string) @file_get_contents("$fake/events"), 'virsh shutdown vmslow')
                         : fn () => str_contains($runLog(), "VM 'vmslow': shutting down"));
        $phase = $status()['phase'] ?? '';
        posix_kill($pid, SIGTERM);
        @unlink("$fake/vm/vmslow.hold");
        $waited = $until(fn () => str_contains($runLog(), 'Waiting for 1 VM(s) going down'));
        touch("$fake/vm/vmslow.go");
        for ($i = 0; $i < 300 && proc_get_status($p)['running']; $i++) {
            usleep(50000);
        }
        proc_close($p);
        $names = array_column($events(), 1);
        $s = $status();
        $l = $runLog();
        same("vm order: stopped $when in the VMs' shutdown — the phase", 'vm_shutdown', $phase);
        check("vm order: stopped $when while it goes down — waited for it, started again, no app stopped",
            $waited && $names === ['virsh shutdown vmslow', 'virsh start vmslow'], json_encode($names) . $l);
        same("vm order: stopped $when — aborted, no downtime, nothing noted", ['aborted', 0, false], [$s['result'] ?? null, $s['downtime_s'] ?? null, file_exists("$data/state/vms")]);
    }

    // --- a guest frozen for the snapshot whose thaw fails (2.48, review 2026-10-15): a second try, then an alert - a frozen
    // guest writes nothing until someone thaws it; one that thaws is a plain line
    $settings(['vmpause' => 'freeze', 'vmshut' => 'freeze']);
    $night(['vmpause' => 'freeze-stuck', 'vmshut' => 'freeze']);
    @unlink("$fake/notify.log");
    $out = $run('', 'UB_NO_NOTIFY=0');
    $names = array_column($events(), 1);
    $note = (string) @file_get_contents("$fake/notify.log");
    check('vm order: a thaw that fails is tried twice, then an alert names the VM; the one that thaws once',
        count(array_keys($names, 'virsh thaw vmpause', true)) === 2 && count(array_keys($names, 'virsh thaw vmshut', true)) === 1
        && str_contains($note, 'VM still frozen after the backup') && str_contains($note, '-i alert') && str_contains($note, 'vmpause') && !str_contains($note, "'vmshut' may still"),
        json_encode($names) . $note . $out);

    // --- stopped twice (2.48, review 2026-10-15): the second SIGTERM comes while the run's way out waits for the VM - it
    // never cuts that short: the VM is still started again once it is off, said in the log
    $settings(['vmslow' => 'shutdown']);
    $night(['vmslow' => 'slow']);
    $t = testsClockRun($clock);
    $runLog = fn () => (string) @file_get_contents("$data/logs/run-" . date('Ymd-Hi', $t) . '.log');
    $p = proc_open(['bash', '-c', "$env UB_VM_SHUTDOWN_TIMEOUT=60 UB_VM_SHUTDOWN_RETRY=120; exec bash " . escapeshellarg(OFFICE_DIR . '/backup/backup.sh') . ' </dev/null >/dev/null 2>&1'], [], $pipes);
    $pid = proc_get_status($p)['pid'];
    $until(fn () => str_contains($runLog(), "VM 'vmslow': shutting down"));
    posix_kill($pid, SIGTERM);
    $waited = $until(fn () => str_contains($runLog(), 'Waiting for 1 VM(s) going down'));
    posix_kill($pid, SIGTERM);
    $again = $until(fn () => str_contains($runLog(), 'Stop asked again'));
    touch("$fake/vm/vmslow.go");
    for ($i = 0; $i < 300 && proc_get_status($p)['running']; $i++) {
        usleep(50000);
    }
    proc_close($p);
    $names = array_column($events(), 1);
    check('vm order: stopped twice — the second stop is said and waits: the VM started again, nothing noted',
        $waited && $again && $names === ['virsh shutdown vmslow', 'virsh start vmslow'] && !file_exists("$data/state/vms")
        && ($status()['result'] ?? null) === 'aborted', json_encode($names) . $runLog());

    // --- killed while it goes down (kill -9): state/vms names it; the next start starts it once it is off
    $night(['vmslow' => 'slow']);
    file_put_contents("$data/state/vms", "vmslow|shutdown\n");
    file_put_contents("$fake/vm/vmslow.state", "shut off\n");
    $lib = escapeshellarg(OFFICE_DIR . '/backup/lib/common.sh');
    shell_exec('bash -c ' . escapeshellarg("$env; source $lib >/dev/null 2>&1; LOG_FILE=$tmp/recover.log; recover_interrupted_run") . ' 2>&1');
    same('vm order: killed — the next start starts it again', [['virsh start vmslow'], false], [array_column($events(), 1), file_exists("$data/state/vms")]);
    same('vm order: every date call one the tests\' clock knows', '', testsClockUnsupported($clock));
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Engine 2.42 on the page: a VM held otherwise than set up (a shutdown past its deadline, a guest agent that didn't
 * freeze → paused) is a coded warning in status.json / last-run.json warning_items; the agent passes it through
 * (backupRunFromStatus, only what the engine's shape allows), Mr. Backupsy's bubble and the run's row say it in the
 * office's words (warn_code.<code>, five languages) - here the German sentence under node. The running card's
 * sentence vm_shutdown_now names «a VM», not «one» (read as one of the apps).
 */
function testBackupVmWarn(): void
{
    $run = backupRunFromStatus(['run' => '20261011-0300', 'started' => 1000, 'finished' => 2000, 'result' => 'warnings', 'warnings' => 2,
        'warning_items' => [['code' => 'vm_not_shut_down', 'params' => ['name' => 'Windows11', 'seconds' => '300', 'Bad' => 'x', 'n' => ['x']]],
            ['code' => 'Not a code'], 'junk', ['code' => 'vm_not_frozen', 'params' => ['name' => "a\nb"]]]]);
    same('vm warn: the agent passes the coded warnings through, only in the engine\'s shape',
        [['code' => 'vm_not_shut_down', 'params' => ['name' => 'Windows11', 'seconds' => '300']], ['code' => 'vm_not_frozen', 'params' => []]],
        $run['warning_items']);
    same('vm warn: an older engine\'s run — none', [], backupRunFromStatus(['run' => 'x'])['warning_items']);
    // engine 2.65: a coded message's params - only in a warning's shape (an older engine's run: none)
    same('message params: an older engine\'s run none, the engine\'s kept, anything else dropped', [[], ['place' => '/mnt/cache/b', 'need' => '8589934592']],
        [backupRunFromStatus(['run' => 'x'])['message_params'], backupRunFromStatus(['run' => 'x', 'message_params' => ['place' => '/mnt/cache/b', 'need' => '8589934592',
         'Bad' => 'x', 'nl' => "a\nb", 'n' => 5]])['message_params']]);
    $codes = ['vm_not_shut_down', 'vm_shutdown_refused', 'vm_not_frozen', 'vm_not_paused'];
    $engine = (string) file_get_contents(OFFICE_DIR . '/backup/backup.sh');
    foreach ($codes as $c) {
        check("vm warn: the engine writes $c", str_contains($engine, "warn_code $c "));
    }
    foreach (['en', 'de', 'it', 'fr', 'es'] as $code) {
        $l = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/backup/lang/$code.json"), true);
        same("vm warn: the sentences in $code, each with {name}", $codes,
            array_values(array_filter($codes, fn ($c) => str_contains((string) ($l["warn_code.$c"] ?? ''), '{name}'))));
        check("vm warn: vm_shutdown_now in $code names a VM", str_contains((string) ($l['vm_shutdown_now'] ?? ''), 'VM'));
    }
    $de = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/de.json'), true);
    same('vm warn: the German running sentence, as Benj wrote it',
        'Zuerst fahren VMs herunter — die Apps laufen bis dahin weiter (höchstens 5 Minuten; eine VM, die nicht heruntergefahren werden kann, wird stattdessen für den Snapshot angehalten).',
        $de['vm_shutdown_now'] ?? null);
    $node = testsNode();
    if ($node === '') {
        check('vm warn: node is missing here - skipped', true);
        return;
    }
    $tmp = hardeningTmp('vm-warn');
    file_put_contents("$tmp/run.json", json_encode($run));
    file_put_contents("$tmp/t.js", <<<'JS'
