ev() { echo "\$(date +%s) \$*" >>"\$FAKE/events"; }
$flip
V="\$FAKE/vm"; n="\${2:-}"
[[ "\$2" == --* ]] && n="\${@: -1}"
state() { cat "\$V/\$n.state" 2>/dev/null || echo running; }
case "\$1" in
