/**
 * Sleeping pools never go back to «wake» unasked (2026-10-08 on a large server: its «skip» became «wake» at an Apply
 * whose dialog listed only share and no_stop lines; reproduced on a test server with a page holding a plan older than
 * settings.ini). The page sends general|asleep_pools only when the user chose it there (setupDecisions()), its dialog
 * lists what is really sent against what settings.ini says (missing = the engine's default), every general key in
 * words; the agent refuses decisions made on a plan older than settings.ini (backupSetupPlanOld(), setup_plan_old)
 */
function testSetupAsleepKept(): void
{
    // the agent: a plan older than settings.ini is refused, a newer one or no settings.ini goes
    $tmp = hardeningTmp('setup-asleep-kept');
    file_put_contents("$tmp/settings.ini", "[general]\nasleep_pools = skip\n");
    touch("$tmp/settings.ini", 1000);
    same('plan old: made before settings.ini was written - refused; at the same second or after - goes; no settings.ini - goes',
        [true, false, false, false], [backupSetupPlanOld(990, "$tmp/settings.ini"), backupSetupPlanOld(1000, "$tmp/settings.ini"),
         backupSetupPlanOld(1005, "$tmp/settings.ini"), backupSetupPlanOld(10, "$tmp/none.ini")]);
    $agent = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    check('plan old: setup_apply passes the page\'s plan time and refuses before anything is written',
        str_contains($agent, "backupSetupApply(\$r['decisions'] ?? null, \$r['plan_time'] ?? null)")
        && strpos($agent, "throw new Problem('setup_plan_old')") < strpos($agent, '$file = "$data/state/setup-decisions.json";'));
    $desk = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('plan old: the page sends its plan\'s time and looks again when refused',
        str_contains($desk, "{ decisions: setupDecisions(), plan_time: setup.plan.time }") && str_contains($desk, "j.error.key === 'setup_plan_old') { setupPlan(false, true)"));
    // every general key setup.sh knows has words in the apply dialog (the partner list has its own group)
    preg_match_all('/pinit "general\|([a-z_]+)"/', (string) file_get_contents(OFFICE_DIR . '/backup/setup.sh'), $m);
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/en.json'), true);
    $missing = array_values(array_filter(array_unique($m[1]), fn ($k) => $k !== 'partner_place' && !isset($en["setup.key.general_$k"])));
    check('plan old: setup.sh\'s general keys found', count($m[1]) >= 10, (string) count($m[1]));
    same('plan old: every general key in words in the apply dialog', [], $missing);

    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('plan old: page - node is missing here - skipped', true);
        hardeningRm($tmp);
        return;
    }
    $general = ['general|dumps_share' => 'UnraidSecretaryOffice', 'general|notify_success' => 'yes', 'general|keep_logs' => '60'];
    $plan = fn (array $p, array $o, int $time) => ['time' => $time, 'have_settings' => true, 'asleep_pools' => $p['general|asleep_pools'] ?? null,
        'P' => $general + ['kopia|enabled' => 'no', 'share|UnraidSecretaryOffice|mode' => 'snapshot', 'docker|no_stop' => [], 'docker|skip' => [], 'docker|known' => []] + $p,
        'O' => $general + ['kopia|enabled' => 'no', 'share|UnraidSecretaryOffice|mode' => 'snapshot'] + $o,
        'shares' => [['name' => 'UnraidSecretaryOffice', 'exists' => true, 'folders' => [], 'waiting' => []]],
        'containers' => [], 'vms' => [], 'databases' => [], 'nextcloud' => [], 'missing_databases' => [], 'bases' => []];
    // a large server's page: a plan made before «skip» was written (settings.ini had no key then)
    file_put_contents("$tmp/stale.json", json_encode($plan(['general|asleep_pools' => 'wake'], [], 1000)));
    // a plan made after: settings.ini says skip
    file_put_contents("$tmp/fresh.json", json_encode($plan(['general|asleep_pools' => 'skip'], ['general|asleep_pools' => 'skip'], 2000)));
    $js = <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
globalThis.Office = { scope: () => T, t: T, el: () => ({}), fmt: { size: (b) => b + ' B', relative: () => 'now' }, desk: () => {}, places: () => {}, placesFrom: () => {}, placesTook: () => {}, selbar: () => {}, has: () => true };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const b = OFFICE_DESK_TESTS.backup;
const load = (f) => { b.setup.draft = null; b.setup.base = null; b.setup.plan = JSON.parse(fs.readFileSync(f, 'utf8')); b.setupDraftKeep(); };
const look = () => {
  const saved = b.setupSaved();
  const { view, keys } = b.setupApplyChanges(saved);
  const sent = b.setupDecisions();
  const k = 'general|asleep_pools';
  return { sent: k in sent ? sent[k] : null, listed: keys.includes(k), line: keys.includes(k) ? `${b.changeLabel(k)}: ${b.valueText(saved[k], k)} → ${b.valueText(view[k], k)}` : null,
    saved: saved[k] ?? null, n: Object.keys(sent).length };
};
const out = {};
load(process.argv[3]); out.staleUntouched = look();
b.dset('general|asleep_pools', 'skip'); out.staleSkip = look();
load(process.argv[4]); out.freshUntouched = look();
b.dset('general|asleep_pools', 'wake'); out.freshWake = look();
// the user's «wake» on the fresh plan, then a new plan comes (a tour): the choice stays and is still sent
b.setup.plan = { ...JSON.parse(fs.readFileSync(process.argv[4], 'utf8')), time: 3000 }; b.setupDraftKeep(); out.keptAcrossPlan = look();
// preset_new missing in settings.ini: the engine's auto, whatever the plan proposes
load(process.argv[3]); b.setup.plan.P['general|preset_new'] = 'local'; out.presetSaved = b.setupSaved()['general|preset_new'];
// a proposal of mine and a change of the user's: counted apart; «leave out» takes the proposal off, the user's stays
// 2026-10-10: a proposal of Mr. Backupsy's (keep_logs 60 → 30) beside the user's own «wake»
load(process.argv[4]); b.setup.plan.P['general|keep_logs'] = '30'; b.setupDraftFromPlan(); out.splitMine = b.setupSplit();
b.dset('general|asleep_pools', 'wake'); out.splitBoth = b.setupSplit();
b.setupDecline('general|keep_logs'); out.splitDeclined = b.setupSplit();
out.declinedSent = [b.setupDecisions()['general|keep_logs'], b.setupDecisions()['general|asleep_pools']];
console.log(JSON.stringify(out));
JS;
    file_put_contents("$tmp/t.js", $js);
    $cmd = escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/backup/desk.js') . ' '
        . escapeshellarg("$tmp/stale.json") . ' ' . escapeshellarg("$tmp/fresh.json") . ' 2>&1';
    $raw = (string) shell_exec($cmd);
    $r = json_decode($raw, true);
    if (!is_array($r)) {
        check('plan old: page ran under node', false, $raw);
        hardeningRm($tmp);
        return;
    }
    same('asleep kept: a large server\'s page (its plan older than «skip») - wake never sent, nothing listed; setup.sh keeps settings.ini\'s skip',
        [null, false], [$r['staleUntouched']['sent'], $r['staleUntouched']['listed']]);
    same('asleep kept: the user picks «leave them asleep» there - sent and listed in words',
        ['skip', 'setup.key.general_asleep_pools: setup.asleep.short_wake → setup.asleep.short_skip'], [$r['staleSkip']['sent'], $r['staleSkip']['line']]);
    same('asleep kept: a fresh plan, untouched - not sent, not listed (settings.ini\'s skip stays)', [null, false, 'skip'],
        [$r['freshUntouched']['sent'], $r['freshUntouched']['listed'], $r['freshUntouched']['saved']]);
    same('asleep kept: «wake them» chosen on a fresh plan - sent and listed', ['wake', 'setup.key.general_asleep_pools: setup.asleep.short_skip → setup.asleep.short_wake'],
        [$r['freshWake']['sent'], $r['freshWake']['line']]);
    same('asleep kept: the choice survives a new plan and is still sent', ['wake', true], [$r['keptAcrossPlan']['sent'], $r['keptAcrossPlan']['listed']]);
    same('asleep kept: the rest of the draft still goes (one key fewer than the draft, _retire_sources added)', $r['freshWake']['n'] - 1, $r['freshUntouched']['n']);
    same('asleep kept: preset_new missing in settings.ini counts as the engine\'s auto', 'auto', $r['presetSaved']);
    same('setup bar split: untouched — the plan\'s keep_logs is a proposal of mine, nothing of the user\'s', ['yours' => [], 'mine' => ['general|keep_logs']], $r['splitMine']);
    same('setup bar split: «wake» chosen — «1 proposal of mine · 1 change of yours»', ['yours' => ['general|asleep_pools'], 'mine' => ['general|keep_logs']], $r['splitBoth']);
    same('setup bar split: «leave out» the proposal — only the user\'s change is left, keep_logs sent as saved', [['yours' => ['general|asleep_pools'], 'mine' => []], ['60', 'wake']],
        [$r['splitDeclined'], $r['declinedSent']]);
    hardeningRm($tmp);
}

/**
 * The backup place on a fresh server: what speaks against a share (backupPlaceFacts() from the shares' cfg,
 * disks.ini and the plan's locations - warnings only), and the setup's step 0 under node: the warnings'
 * texts, Mr. Backupsy's word while none is chosen, and a new plan keeping what the user chose but didn't apply
 */
function testBackupPlace(): void
{
    $tmp = hardeningTmp('backup-place');
    mkdir("$tmp/shares");
    file_put_contents("$tmp/disks.ini", implode("\n", ['["parity"]', 'type="Parity"', 'device=""', '["disk1"]', 'type="Data"', 'fsType="xfs"',
        '["disk2"]', 'type="Data"', 'fsType="luks:btrfs"', '["cache"]', 'type="Cache"', 'fsType="btrfs"', 'fsProfile="single"', '["cache2"]', 'type="Cache"', 'fsType=""',
        '["fast"]', 'type="Cache"', 'fsType="luks:zfs"', 'fsProfile="mirror"', '["fast2"]', 'type="Cache"', 'fsType=""', '']));
    $cfg = fn (string $name, string $use, string $pool = '', string $pool2 = '', string $include = '') => file_put_contents("$tmp/shares/$name.cfg",
        "shareInclude=\"$include\"\nshareExclude=\"\"\nshareUseCache=\"$use\"\nshareCachePool=\"$pool\"\nshareCachePool2=\"$pool2\"\n");
    $cfg('appdata', 'only', 'cache');
    $cfg('UnraidSecretaryOffice', 'only', 'fast');
    $cfg('isos', 'yes', 'cache');
    $cfg('onarray', 'no', '', '', 'disk2');
    $cfg('arrayx', 'no');
    $cfg('moved', 'prefer', 'fast', 'cache');
    $sh = fn (string $name, string $loc = '-', string $method = 'none') => ['name' => $name, 'locations' => $loc, 'method' => $method];
    $shares = [$sh('appdata', 'cache', 'snap'), $sh('UnraidSecretaryOffice'), $sh('isos', 'cache', 'snap'), $sh('onarray'), $sh('arrayx', 'disk2', 'snap'),
               $sh('moved', 'fast', 'snap'), $sh('newpool', 'fast', 'snap'), $sh('legacy', 'disk1', 'live'), $sh('liveonly', '-', 'live'), $sh('../x'), $sh('.hidden')];
    $w = fn (string $code, string $where) => ['code' => $code, 'where' => $where];
    $f = backupPlaceFacts($shares, "$tmp/shares", "$tmp/disks.ini");
    same('backup place: a ZFS mirror pool of its own - nothing to say', [], $f['UnraidSecretaryOffice'] ?? null);
    same('backup place: appdata\'s pool, the array behind it with an XFS disk, a secondary storage, no redundancy',
        [$w('same_pool', 'cache'), $w('no_history', 'disk1'), $w('secondary', ''), $w('no_redundancy', 'cache')], $f['isos'] ?? null);
    same('backup place: the array limited to a btrfs disk - only no parity', [$w('no_redundancy', '')], $f['onarray'] ?? null);
    same('backup place: the whole array (an XFS disk among them)', [$w('no_history', 'disk1'), $w('no_redundancy', '')], $f['arrayx'] ?? null);
    same('backup place: prefer with a secondary pool - appdata\'s pool as the secondary, the mover', [$w('same_pool', 'cache'), $w('secondary', 'cache'), $w('no_redundancy', 'cache')], $f['moved'] ?? null);
    same('backup place: no cfg, its folder on a mirror pool - nothing', [], $f['newpool'] ?? null);
    same('backup place: no cfg, the plan found it on an XFS disk', [$w('no_history', 'disk1'), $w('no_redundancy', '')], $f['legacy'] ?? null);
    same('backup place: the plan says live, the part unknown', [$w('no_history', '')], $f['liveonly'] ?? null);
    check('backup place: odd names never read', !isset($f['../x']) && !isset($f['.hidden']));
    file_put_contents("$tmp/disks.ini", str_replace("device=\"\"", "device=\"sdb\"", (string) file_get_contents("$tmp/disks.ini")));
    same('backup place: the array with parity is redundant', [], backupPlaceFacts([$sh('onarray')], "$tmp/shares", "$tmp/disks.ini")['onarray'] ?? null);
    same('backup place: no disks.ini (array stopped) - only what the cfg tells', [$w('secondary', '')], backupPlaceFacts([$sh('isos')], "$tmp/shares", "$tmp/none.ini")['isos'] ?? null);

    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('backup place: setup page - node is missing here - skipped', true);
        hardeningRm($tmp);
        return;
    }
    $c = fn (string $name, string $dir) => ['name' => $name, 'why' => 'writes', 'previous' => false, 'binds' => [['share' => 'appdata', 'path' => $dir, 'rw' => true]], 'volumes' => []];
    $a = ['time' => 1000, 'have_settings' => false,
        'P' => ['kopia|enabled' => 'no', 'general|dumps_share' => '', 'flash|mode' => 'tar', 'zfs|retention' => '7 4 3', 'docker|no_stop' => [], 'docker|skip' => [],
                'share|appdata|mode' => 'snapshot', 'share|isos|mode' => 'off'],
        'shares' => [['name' => 'appdata', 'exists' => true, 'folders' => [['dir' => 'c1', 'container' => 'c1'], ['dir' => 'c2', 'container' => 'c2'], ['dir' => 'c3', 'container' => 'c3']], 'waiting' => []],
                     ['name' => 'isos', 'exists' => true, 'folders' => [], 'waiting' => []]],
        'containers' => [$c('c1', 'c1'), $c('c2', 'c2'), $c('c3', 'c3')], 'vms' => [], 'databases' => [], 'nextcloud' => []];
    // the user made the office's share in Unraid meanwhile: the engine proposes it, and a new retention
    $b = $a;
    $b['time'] = 2000;
    $b['P']['general|dumps_share'] = 'UnraidSecretaryOffice';
    $b['P']['share|UnraidSecretaryOffice|mode'] = 'snapshot';
    $b['P']['zfs|retention'] = '14 4 3';
    $b['shares'][] = ['name' => 'UnraidSecretaryOffice', 'exists' => true, 'folders' => [], 'waiting' => []];
    file_put_contents("$tmp/a.json", json_encode($a));
    file_put_contents("$tmp/b.json", json_encode($b));
    $js = <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
globalThis.Office = { scope: () => T, t: T, el: () => ({}), fmt: { size: (b) => b + ' B', relative: () => 'now' }, desk: () => {}, places: () => {}, placesFrom: () => {}, placesTook: () => {}, selbar: () => {}, has: () => false };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const b = OFFICE_DESK_TESTS.backup;
const out = {};
// the place's lines: testBackupPlaceVerdict (2026-10-17, one question decides)
const plan = (names) => ({ shares: names.map((name) => ({ name })) });
out.intro = [b.placeIntro(plan(['appdata', 'system', 'domains', 'isos']), ''), b.placeIntro(plan(['appdata', 'isos', 'Backups']), ''),
  b.placeIntro(plan(['appdata', 'isos']), 'isos')];
// a first plan: what the user picks and doesn't apply
b.setup.plan = JSON.parse(fs.readFileSync(process.argv[3], 'utf8'));
b.setupDraftKeep();
b.dset('flash|mode', 'off');
b.dset('general|dumps_share', 'isos');
b.setup.levels['app:ct:c2'] = 0;
b.setup.held['ct:c3'] = 'run';
b.setupDerive();
out.before = [b.setup.draft['docker|skip'], b.setup.draft['docker|no_stop']];
// a new plan (a tour, or the setup opened again)
b.setup.plan = JSON.parse(fs.readFileSync(process.argv[4], 'utf8'));
b.setupDraftKeep();
const d = b.setup.draft;
out.after = { flash: d['flash|mode'], ds: d['general|dumps_share'], retention: d['zfs|retention'], skip: d['docker|skip'], noStop: d['docker|no_stop'],
  levels: [b.setup.levels['app:ct:c1'], b.setup.levels['app:ct:c2']], held: b.setup.held['ct:c3'], office: d['share|UnraidSecretaryOffice|mode'] };
// the same plan once more without anything chosen: just the plan
b.setupDraftFromPlan();
out.plain = [b.setup.draft['flash|mode'], b.setup.levels['app:ct:c2']];
console.log(JSON.stringify(out));
JS;
    file_put_contents("$tmp/t.js", $js);
    $cmd = escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/backup/desk.js') . ' '
        . escapeshellarg("$tmp/a.json") . ' ' . escapeshellarg("$tmp/b.json") . ' 2>&1';
    $r = json_decode((string) shell_exec($cmd), true);
    if (!is_array($r)) {
        check('backup place: setup page ran under node', false, (string) shell_exec($cmd));
        hardeningRm($tmp);
        return;
    }
    same('backup place: Mr. Backupsy\'s word - no share to choose (only isos), choose one, none once chosen', ['setup.place_none', 'setup.place_choose', null], $r['intro']);
    same('backup place: before the new plan - the user\'s levels in the draft', [['c2'], ['c2', 'c3']], $r['before']);
    same('backup place: a new plan keeps what the user chose (flash, a level, a hold); takes the engine\'s new proposals (the share made meanwhile, a retention)',
        ['flash' => 'off', 'ds' => 'UnraidSecretaryOffice', 'retention' => '14 4 3', 'skip' => ['c2'], 'noStop' => ['c2', 'c3'], 'levels' => [1, 0], 'held' => 'run', 'office' => 'snapshot'],
        $r['after']);
    same('backup place: «Discard» still goes back to the plan', ['tar', 1], $r['plain']);
    hardeningRm($tmp);
}

/**
 * The default (2026-10-07/08; engine 2.31 [general] preset_new): the setup's three defaults under node - «auto» is
 * the plan as today, «local» every share, app and VM local with Kopia off, «kopia» all of them local + Kopia; what the
 * engine never backs up on its own stays as the plan says (the system share, Kopia's own folder, Time Machine targets,
 * drift.ignore, a VM it can't snapshot), media servers keep running, an app that ran only because nothing of it was
 * backed up is held as the engine proposes, the user's Kopia ignore rules stay; a row changed by hand marks the draft;
 * a new plan keeps the default for what was there and the user's changes, and what came later gets the default; the
 * first upload to Kopia with its sizes; whether «local + Kopia» can start at all. Then the default for new things: what
 * is new (setupNewItems), the stored default on new apps, VMs, shares and folders only - the rest exactly as without
 * it -, big and unknown new shares left to the user under «kopia», Kopia off, «only what is new» and «everything» chosen
 * on the page, a re-plan, an engine without the key. Plus: every text a default asks for exists.
 */
function testBackupPresets(): void
{
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/en.json'), true);
    preg_match("/const PRESETS = \\[([^\\]]*)\\]/", $js, $m);
    $kinds = preg_match_all("/'([a-z_]+)'/", $m[1] ?? '', $k) ? $k[1] : [];
    preg_match("/const PRESET_KEEP = \\[([^\\]]*)\\]/", $js, $m);
    $keeps = preg_match_all("/'([a-z_]+)'/", $m[1] ?? '', $k) ? [...$k[1], 'vm_cannot'] : [];
    same('presets: the five starts (2.42: the two with a partner)', ['auto', 'local', 'partner', 'kopia', 'kopia_partner'], $kinds);
    // one scope: a function declared twice is silently the second one (the run's firstUpload() was the setup's up to 1.38.0)
