    check('default: kopia stored - everything that was there before exactly as without a default', $n['kopiaOld']);
    $lines = array_column($n['kopiaLines'], 1, 0);
    same('default: the apply dialog\'s «New» names the new shares too, with their mode', ['setup.mode.kopia', 'setup.mode.off', 'setup.mode.snapshot'],
        [$lines['setup.new_share {"name":"fresh"}'] ?? null, $lines['setup.new_share {"name":"huge"}'] ?? null, $lines['setup.new_share {"name":"unk"}'] ?? null]);
    same('default: kopia stored - the first upload counts the new share, the new VM\'s share and the new VM - not the VMs there that stay local (left out), not the big share',
        [['domains', 'fresh'], ['vmnew']], [$n['kopiaUpload']['shares'], $n['kopiaUpload']['vms']]);
    same('default: local stored - the new app local and stopped for the snapshot (it writes into a backed-up share), the new VM held, every new share local (one without snapshots not backed up, 2.55), the folder only local; Kopia stays on',
        ['levels' => [1, 1], 'held' => 'stop', 'noStop' => false, 'items' => [null, null], 'prepare' => 'freeze', 'modes' => ['snapshot', 'snapshot', 'off', 'snapshot', 'snapshot'],
         'loose' => 'local', 'kopia' => 'yes', 'key' => 'local', 'now' => 'local', 'changed' => false, 'chosen' => true,
         'start' => 'setup.preset.new_sub {"name":"setup.preset.local"}'], $n['local']);
    check('default: local stored - everything that was there before exactly as without a default', $n['localOld']);
    same('default: the dialog\'s new rows — none changed by hand right after the default decided (its sentence stands)', 0, $n['handNone'] ?? null);
    same('default: … the new VM\'s level, a new share\'s mode and a waiting folder changed by hand — those rows say «changed by you», the sentence goes',
        ['appdata/loose', 'setup.new_share {"name":"fresh"}', 'setup.new_vm {"name":"vmnew"}'], $n['hand'] ?? null);
    check('default: … the dialog: the sentence only without a hand row, the chip on such a row',
        str_contains($js, "kind !== 'auto' && !hand ? T('setup.apply_new_default'") && str_contains($js, "if (mine) what.append(' ', chip(T('setup.preset.changed'), 'quiet'));")
        && ($n['handLines'] ?? false) === true);
    // 2026-10-12 (Benj): a new thing once - under «New on the server» with its proposal and «Don't take it», its keys out of the changes
    same('default: the new rows name the keys they own (share|fresh|, vm|vmnew|)', true,
        in_array('share|fresh|', $n['owns'] ?? [], true) && in_array('vm|vmnew|', $n['owns'] ?? [], true));
    check('default: … the dialog leaves them out of the changes and offers the proposal on the new row',
        str_contains($js, "const changes = items.filter((x) => x.kind === 'key' && !ownOf(x.id)).map((x) => x.id);")
        && str_contains($js, "no.onclick = () => { mineKeys.forEach((k) => setupDecline(k)); renderSetup(); setupApply(); };"));
    same('default: kopia stored while Kopia is off - never switched on: the new things local', [[1, 1], 'no', ['snapshot', 'off', 'snapshot', 'snapshot', 'snapshot']],
        [$n['kopiaOff']['levels'], $n['kopiaOff']['kopia'], $n['kopiaOff']['modes']]);
    same('default: «only to what is new» chosen on the page - the new things get it, the key set, the hand change and every row before stay',
        [[2, 2], 'kopia', 'kopia', 0, true], [$n['newOnly']['levels'], $n['newOnly']['key'], $n['newOnly']['modes'][0], $n['newOnlyHand'], $n['newOnlyOld']]);
    same('default: «only to what is new» - its card reckons the first upload of the new things only, as the draft says once chosen',
        [[['domains', 'fresh'], ['vmnew']], [['domains', 'fresh'], ['vmnew']]],
        array_map(fn ($u) => [$u['shares'] ?? null, $u['vms'] ?? null], $n['newOnlyUpload']));
    same('default: «Discard» after choosing - back to the default chosen (it stays until Apply), the hand change goes', [2, 2, 'kopia', false], $n['newOnlyDiscard']);
    same('default: another one «only to what is new» - the new things local, every row before as without a default', [[1, 1], 'local', 'snapshot', true],
        [$n['newOnlyLocal']['levels'], $n['newOnlyLocal']['key'], $n['newOnlyLocal']['modes'][0], $n['newOnlyLocalOld']]);
    same('default: «apply to everything now» - every row local + Kopia (the big and the unknown new share too: they were there when chosen), the key set, «Start: …»',
        [[2, 2], ['kopia', 'kopia', 'kopia'], 'kopia', 'setup.preset.start {"name":"setup.preset.kopia"}', [2, 2, 'kopia']],
        [$n['all']['levels'], array_slice($n['all']['modes'], 0, 3), $n['all']['key'], $n['all']['start'], $n['allApps']]);
    same('default: a re-plan under the stored default - the newcomer gets it (local + Kopia, stopped), a hand change on a new row stays',
        [2, 'stop', 'yes', 1, true], $n['replan']);
    same('default: a plan from engine 2.30 - auto; a choice works on the draft, no key for Apply', [['auto', 1], [false, 2, 'kopia']], [$n['oldAuto'], $n['oldChosen']]);
    // the page's parts that need a browser: in the code (the coordinator checks the pages headless)
    $php = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    check('default: Apply takes the key with auto, local, kopia, partner or kopia_partner only', str_contains($php, "\$key === 'general|preset_new' && !in_array(\$value, ['auto', 'local', 'kopia', 'partner', 'kopia_partner'], true)"));
    check('default: desk.js - step 0\'s line, the chip on new rows (apps, VMs, shares, waiting folders), the scope in the dialog, «New» names the default',
        str_contains($js, 'const pl = presetLine(plan);') && substr_count($js, 'newChip(') >= 5 && str_contains($js, 'presetScope(newOnly,')
        && str_contains($js, "T('setup.apply_new_default'") && str_contains($js, "plan.preset_new === undefined"));
    hardeningRm($tmp);
}

/**
 * Engine 2.20: a run that finds the lock busy is skipped, never silent — the engine's helpers (the holder
 * note, skipped.json, the history line, the history's own lock) on a temporary data folder, and the
 * office's side: who holds the lock, skips kept apart from the runs (history, estimates, the last run),
 * the Dashboard tile. Nothing runs backup.sh; a stand-in "backup.sh" only sleeps.
 */
function testBackupSkip(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-skip-' . getmypid();
    @mkdir("$tmp/data/state", 0700, true);
    @mkdir("$tmp/data/logs", 0700, true);
    file_put_contents("$tmp/backup.sh", "sleep 30\n");
    $sleeper = proc_open(['bash', "$tmp/backup.sh"], [], $pipes);
    $sleeperPid = (int) proc_get_status($sleeper)['pid'];
    $lib = escapeshellarg(OFFICE_DIR . '/backup/lib/common.sh');
    $state = "$tmp/data/state";
    $sh = fn (string $script) => trim((string) shell_exec('bash -c ' . escapeshellarg("UB_DATA=$tmp/data; source $lib >/dev/null 2>&1; TS=20261007-0100; $script") . ' 2>&1'));
    $note = fn (array $n) => file_put_contents("$state/lock-holder.json", json_encode($n));
    $read = 'ub_holder_read; printf "%s|%s|%s|%s|%s" "$HOLDER_KIND" "$HOLDER_MODE" "$HOLDER_WHAT" "$HOLDER_RUN" "$HOLDER_STARTED"';

    // the engine: who holds the lock - trusted only while its pid lives (and runs backup.sh / setup.sh)
    same('engine holder: no note - other', 'other||||0', $sh($read));
    $note(['holder' => 'backup', 'mode' => 'check', 'run' => '20261006-0100', 'pid' => $sleeperPid, 'started' => 1791241200]);
    same('engine holder: a check of backup.sh', 'check|check||20261006-0100|1791241200', $sh($read));
    $note(['holder' => 'backup', 'mode' => 'backup', 'run' => '20261006-0100', 'pid' => getmypid(), 'started' => 1]);
    same('engine holder: the pid runs something else - other', 'other||||0', $sh($read));
    $note(['holder' => 'restore', 'what' => "next\ncloud", 'pid' => getmypid(), 'started' => 5]);
    same('engine holder: a restore, control characters gone', 'restore||next cloud||5', $sh($read));
    $note(['holder' => 'restore', 'what' => 'x', 'pid' => 4194305, 'started' => 5]);
    same('engine holder: a dead pid - other', 'other||||0', $sh($read));
    @unlink("$state/lock-holder.json");
    file_put_contents("$state/status.json", json_encode(['mode' => 'backup', 'run' => '20261006-0100', 'pid' => $sleeperPid, 'started' => 9, 'result' => 'running']));
    same('engine holder: no note, but status.json names a running backup.sh (an engine before 2.20)', 'backup|backup||20261006-0100|9', $sh($read));
    file_put_contents("$state/status.json", json_encode(['mode' => 'backup', 'run' => '20261006-0100', 'pid' => $sleeperPid, 'started' => 9, 'result' => 'ok']));
    same('engine holder: no note, status.json not running - other', 'other||||0', $sh($read));
    @unlink("$state/status.json");
    same('engine holder: written with its own pid', 'backup|dryrun|20261007-0100|7|true',
        $sh('ub_holder_write backup dryrun "$TS" 7; jq -r --argjson me $$ \'[.holder, .mode, .run, .started, (.pid == $me)] | map(tostring) | join("|")\' "$UB_STATE/lock-holder.json"'));
    same('engine holder: its own note cleared', '0', $sh('ub_holder_write setup plan "$TS" 1; ub_holder_clear; ls "$UB_STATE" | grep -c lock-holder'));
    $note(['holder' => 'restore', 'pid' => $sleeperPid]);
    same("engine holder: another's note stays", '1', $sh('ub_holder_clear; ls "$UB_STATE" | grep -c lock-holder'));

    // a skipped run: skipped.json always, a history line only for a real backup run
    $note(['holder' => 'backup', 'mode' => 'backup', 'run' => '20261006-0100', 'pid' => $sleeperPid, 'started' => 1791241200]);
    file_put_contents("$state/history.jsonl", json_encode(['run' => '20261006-0100', 'started' => 100, 'finished' => 500, 'result' => 'ok', 'kopia' => ['done' => [['name' => 'appdata', 'ok' => true, 'seconds' => 300, 'finished' => 450]]]]) . "\n");
    $sh('ub_holder_read; status_skipped check skipped_busy_backup kopia appdata');
    $j = readJson("$state/skipped.json");
    same('engine skip: a check - skipped.json', ['check', 'skipped', 'skipped_busy_backup', 'backup', 'kopia', 'appdata', '20261006-0100'],
        [$j['mode'] ?? null, $j['result'] ?? null, $j['reason'] ?? null, $j['holder']['kind'] ?? null, $j['holder']['phase'] ?? null, $j['holder']['current'] ?? null, $j['holder']['run'] ?? null]);
    same('engine skip: a check - no history line', 1, count(file("$state/history.jsonl")));
    $sh('ub_holder_read; status_skipped backup skipped_busy_backup kopia appdata');
    $lines = file("$state/history.jsonl", FILE_IGNORE_NEW_LINES);
    same('engine skip: a backup - a history line', [2, 'skipped', '20261007-0100'], [count($lines), json_decode($lines[1], true)['result'] ?? null, json_decode($lines[1], true)['run'] ?? null]);
    same('engine skip: status.json untouched', false, is_file("$state/status.json"));
    same('engine history: the last UB_HISTORY_MAX lines', '3|l3|l5', $sh('UB_HISTORY_MAX=3; for i in 1 2 3 4 5; do history_append "{\"l\":\"l$i\"}"; done;'
        . ' printf "%s|%s|%s" "$(wc -l <"$UB_STATE/history.jsonl")" "$(head -1 "$UB_STATE/history.jsonl" | jq -r .l)" "$(tail -1 "$UB_STATE/history.jsonl" | jq -r .l)"'));

    // the office: skips are no runs - history, estimates and the last run never see them
    file_put_contents("$state/history.jsonl", implode("\n", [
        json_encode(['run' => '20261005-0100', 'started' => 1000, 'finished' => 1600, 'result' => 'ok', 'downtime_s' => 60,
                     'kopia' => ['done' => [['name' => 'appdata', 'ok' => true, 'seconds' => 400, 'finished' => 1500]]]]),
        json_encode(['run' => '20261006-0100', 'started' => 2000, 'finished' => 2000, 'result' => 'skipped', 'time' => 2000, 'mode' => 'backup',
                     'reason' => 'skipped_busy_backup', 'holder' => ['kind' => 'backup', 'started' => 1000, 'phase' => 'kopia', 'current' => 'appdata']]),
        json_encode(['run' => '20261006-0100', 'started' => 2100, 'finished' => 2100, 'result' => 'skipped', 'time' => 2100, 'mode' => 'odd',
                     'reason' => 'skipped_busy_x', 'holder' => ['kind' => '<b>', 'what' => str_repeat('a', 200)]]),
    ]) . "\n");
    $history = backupHistory([], null, $skips, "$state/history.jsonl");
    same('office history: the skipped lines are no runs', ['20261005-0100'], array_column($history, 'run'));
    same('office history: skips newest first, unknown holder = other', [[2100, 'skipped_busy_other', 'other', 'backup'], [2000, 'skipped_busy_backup', 'backup', 'backup']],
        array_map(fn ($k) => [$k['time'], $k['reason'], $k['holder']['kind'], $k['mode']], $skips));
    same('office history: texts from the engine kept short', 80, mb_strlen($skips[0]['holder']['what']));
    same('office history: estimates from the runs only', 600, backupEstimates($history)['total']);
    same('office: not a skip', null, backupSkipRow(['result' => 'ok']));

    // who holds the lock, for the office (Mr. Backupsy, Mr. Restori)
    same('office holder: nobody holds the lock', null, backupLockHolder("$tmp/data"));
    $lock = fopen("$state/lock", 'c');
    flock($lock, LOCK_EX);
    $note(['holder' => 'backup', 'mode' => 'dryrun', 'run' => '20261006-0100', 'pid' => $sleeperPid, 'started' => 1791241200]);
    same('office holder: a dry run of backup.sh', ['dryrun', '20261006-0100', 1791241200], array_values(array_intersect_key(backupLockHolder("$tmp/data") ?? [], ['holder' => 1, 'run' => 1, 'started' => 1])));
    $note(['holder' => 'setup', 'mode' => 'plan', 'pid' => $sleeperPid]);
    same('office holder: "setup" but the pid runs backup.sh - other', 'other', backupLockHolder("$tmp/data")['holder'] ?? null);
    $note(['holder' => 'restore', 'what' => 'nextcloud', 'pid' => getmypid(), 'started' => 7]);
    same('office holder: a restore', ['restore', 'nextcloud'], [backupLockHolder("$tmp/data")['holder'] ?? null, backupLockHolder("$tmp/data")['what'] ?? null]);
    $note(['holder' => 'restore', 'pid' => 4194305]);
    same('office holder: a dead pid - other', 'other', backupLockHolder("$tmp/data")['holder'] ?? null);
    @unlink("$state/lock-holder.json");
    same('office holder: no note - other', 'other', backupLockHolder("$tmp/data")['holder'] ?? null);
    file_put_contents("$state/status.json", json_encode(['mode' => 'check', 'run' => '20261006-0100', 'pid' => $sleeperPid, 'started' => 9, 'result' => 'running']));
    same('office holder: no note, a running check in status.json (an engine before 2.20)', ['check', 9], [backupLockHolder("$tmp/data")['holder'] ?? null, backupLockHolder("$tmp/data")['started'] ?? null]);
    @unlink("$state/status.json");
    flock($lock, LOCK_UN);
    fclose($lock);

    // the Dashboard tile: a skip newer than the last run shows, an older one doesn't
    require_once OFFICE_DIR . '/src/dashboard.php';
    $last = ['result' => 'ok', 'started' => 1000, 'finished' => 1600];
    same('dashboard: a skip after the last run', ['backup.dash_skipped', 'orange', 2000], officeDashBackupState(['history' => [$last], 'skips' => [['time' => 2000]]]));
    same('dashboard: a run after the skip', ['dash.bk_ok', 'green', 1600], officeDashBackupState(['history' => [$last], 'skips' => [['time' => 900]]]));
    same('dashboard: running beats a skip', ['dash.bk_running', 'orange', null], officeDashBackupState(['running' => true, 'history' => [$last], 'skips' => [['time' => 2000]]]));
    same('dashboard: nothing yet', ['dash.bk_none', 'orange', null], officeDashBackupState([]));

    proc_terminate($sleeper);
    proc_close($sleeper);
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Mr. Backupsy's check that the Kopia container comes back by itself after a reboot or an array stop (a large server,
 * 2026-10-07: a Kopia off Unraid's autostart list stayed off after an array stop, the night's run went without its
 * offsite part and `kopia_running` noticed it only afterwards): Unraid's autostart file (`name` or `name delay`),
 * Docker's own restart policy, Compose Manager's autostart of a stack; nothing while Kopia is off in the settings,
 * for another container than the settings name, or for a stack Compose Manager doesn't know.
 */
/** The Team Lead's «Kopia is connected to its repository»: the newest run that checked it says it, not a check or a --no-kopia run */
function testBackupKopiaWord(): void
{
    $f = sys_get_temp_dir() . '/office-tests-kopiaword-' . getmypid() . '.jsonl';
    file_put_contents($f, implode("\n", [
        json_encode(['run' => '20261011-2233', 'kopia' => ['enabled' => true, 'state' => 'no']]),
        json_encode(['run' => '20261012-0100', 'kopia' => ['enabled' => true, 'state' => 'yes']]),
        json_encode(['run' => '20261012-0818', 'kopia' => ['enabled' => true, 'state' => 'skip']]),
        json_encode(['run' => '20261012-0903', 'mode' => 'check', 'kopia' => ['enabled' => true, 'state' => '']]),
    ]) . "\n");
    same('kopia word: the newest run that checked the repository counts (yes), not the --no-kopia run or the check after it', 'yes', backupKopiaLastWord($f));
    file_put_contents($f, json_encode(['run' => '20261012-0818', 'kopia' => ['enabled' => true, 'state' => 'skip']]) . "\n");
    same('kopia word: no run ever checked it - null (the finding says «couldn\'t check»)', null, backupKopiaLastWord($f));
    same('kopia word: no history - null', null, backupKopiaLastWord($f . '.missing'));
    @unlink($f);
}

function testBackupKopiaAutostart(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-kopiaauto-' . getmypid();
    $compose = "$tmp/compose";
    @mkdir("$compose/backup", 0700, true);
    @mkdir("$compose/media", 0700, true);
    @mkdir("$compose/old", 0700, true);
    @mkdir("$compose/bare", 0700, true);
    $list = "$tmp/unraid-autostart";

    // Unraid's list as the Docker page writes it: a name, or a name and the seconds to wait after it
    file_put_contents($list, "EmbyServer\nkopia 30\n\nbitcoind\n");
    same('kopia autostart: Unraid\'s list, with the delay', ['EmbyServer' => 0, 'kopia' => 30, 'bitcoind' => 0], houseAutostart($list));
    same('kopia autostart: no file, an empty list', [], houseAutostart("$tmp/none"));

    $summary = ['kopia_enabled' => true, 'kopia_container' => 'kopia'];
    $inspect = fn (string $restart = 'no', ?string $project = null) => ['HostConfig' => ['RestartPolicy' => ['Name' => $restart]],
        'Config' => ['Labels' => $project === null ? [] : ['com.docker.compose.project' => $project]]];
    $f = fn (array $s, string $name, array $i, ?string $file = null) => backupKopiaAutostart($s, $name, $i, $file ?? $list, $compose);

    $r = $f($summary, 'kopia', $inspect());
    same('kopia autostart: on the list with a delay — a finding in order, a must like kopia_running, on the Docker page',
        ['kopia_autostart', 'required', true, ['name' => 'kopia'], 'docker'], [$r['id'], $r['level'], $r['ok'], $r['params'], $r['link']]);
    file_put_contents($list, "EmbyServer\nkopia\n");
    same('kopia autostart: on the list without a delay', true, $f($summary, 'kopia', $inspect())['ok']);
    file_put_contents($list, "EmbyServer\nkopia2 10\nbitcoind\n");
    same('kopia autostart: missing from the list — red', false, $f($summary, 'kopia', $inspect())['ok']);
    same('kopia autostart: a name that only begins like it doesn\'t count', false, isset(houseAutostart($list)['kopia']));
    same('kopia autostart: no list at all — red', false, $f($summary, 'kopia', $inspect(), "$tmp/none")['ok']);
    same('kopia autostart: Docker\'s restart policy "always" brings it back itself', true, $f($summary, 'kopia', $inspect('always'))['ok']);
    same('kopia autostart: "unless-stopped" doesn\'t — Unraid stopped it', false, $f($summary, 'kopia', $inspect('unless-stopped'))['ok']);
    file_put_contents($list, "EmbyServer\nkopia 30\n");
    same('kopia autostart: nothing while Kopia is off in the settings', null, $f(['kopia_enabled' => false, 'kopia_container' => 'kopia'], 'kopia', $inspect()));
    same('kopia autostart: only the container the settings name', null, $f($summary, 'kopia-old', $inspect()));
    same('kopia autostart: no container named in the settings — nothing', null, $f(['kopia_enabled' => true, 'kopia_container' => null], 'kopia', $inspect()));

    // a container of a Compose stack: Compose Manager's autostart of that stack decides, never Unraid's list
    file_put_contents("$compose/backup/project_name", "backup\n");
    file_put_contents("$compose/backup/name", "Backup\n");
    file_put_contents("$compose/backup/autostart", 'true');
    file_put_contents("$compose/media/project_name", "media\n");
    file_put_contents("$compose/media/autostart", "false\n");
    file_put_contents("$compose/old/name", "Old-Stack\n");                      // an older folder: no project_name yet
    file_put_contents("$compose/old/autostart", 'true');
    same('compose autostart: the stack is on', true, houseComposeAutostart('backup', $compose));
    same('compose autostart: the stack is off', false, houseComposeAutostart('media', $compose));
    same('compose autostart: a stack Compose Manager doesn\'t know', null, houseComposeAutostart('other', $compose));
    same('compose autostart: an older folder goes by its name, as compose lower-cases it', true, houseComposeAutostart('old-stack', $compose));
    same('compose autostart: a folder without the file is off', false, houseComposeAutostart('bare', $compose));
    same('compose autostart: no projects folder — nothing known', null, houseComposeAutostart('backup', "$tmp/nowhere"));
    same('kopia autostart: in a stack that starts by itself (not on Unraid\'s list)', true, $f($summary, 'kopia', $inspect('no', 'backup'), "$tmp/none")['ok']);
    same('kopia autostart: in a stack that doesn\'t — red, though a line of that name is on Unraid\'s list', false, $f($summary, 'kopia', $inspect('unless-stopped', 'media'))['ok']);
    same('kopia autostart: in a stack nobody the office knows starts — no finding', null, $f($summary, 'kopia', $inspect('no', 'other')));
    same('kopia autostart: "always" in a stack that doesn\'t start — Docker brings it back', true, $f($summary, 'kopia', $inspect('always', 'media'))['ok']);
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Mr. Restori: his own reader of the packages (dumps with their database and the credentials' variable
 * names, the folders a container binds, templates, compose files, stale packages), share paths, database types.
 */
function testRestore(): void
{
    // rsync 3.5.1 refuses a destination through a symlink another user owns — an exclusive share's /mnt/user/<share> is
    // Unraid's link, owned by nobody (2026-10-11, a large server: «rsync exit 3» on every files restore into appdata)
    $rs = (string) file_get_contents(OFFICE_DIR . '/agent/desks/restore.php');
    check('restore copy: rsync gets the pool path of an exclusive share (officeUnraidPath), the journal keeps the share\'s',
        str_contains($rs, '$rsTo = officeUnraidPath($to);') && str_contains($rs, "\$rsFrom = array_map('officeUnraidPath', \$sources);"));
    $tmp = sys_get_temp_dir() . '/office-tests-restore-' . getmypid();
    $put = function (string $file, mixed $data) use ($tmp): void {
        @mkdir(dirname("$tmp/$file"), 0700, true);
        file_put_contents("$tmp/$file", is_string($data) ? $data : json_encode($data));
    };
    $put('server/run.json', ['run' => '20261006-0200', 'result' => 'ok', 'files' => []]);
    $put('apps/nextcloud/manifest.json', ['name' => 'nextcloud', 'type' => 'compose', 'run' => '20261006-0200', 'result' => 'ok',
        'compose' => ['project' => 'nextcloud', 'manager_dir' => 'nextcloud', 'working_dir' => '/boot/x', 'config_files' => ['/boot/x/compose.yaml']],
        'containers' => [
            ['name' => 'nextcloud-db', 'image' => 'mariadb:11.4', 'digests' => ['mariadb@sha256:ab'],
             'inspect' => ['Config' => ['Env' => ['MARIADB_VERSION=11.4', 'MARIADB_PASSWORD=secret']],
                           'Mounts' => [['Type' => 'bind', 'Source' => '/mnt/user/appdata/nextcloud/db/', 'Destination' => '/var/lib/mysql', 'RW' => true],
                                        ['Type' => 'volume', 'Source' => '/var/lib/docker/volumes/x', 'Destination' => '/x']]]],
            ['name' => 'nextcloud-app', 'image' => 'nextcloud:31', 'digests' => [], 'inspect' => ['Config' => ['Env' => []], 'Mounts' => []]],
        ],
        'dumps' => [['container' => 'nextcloud-db', 'type' => 'mariadb', 'state' => 'failed', 'login' => 'user', 'user_var' => 'MARIADB_USER',
                     'password_var' => 'MARIADB_PASSWORD', 'client' => 'mariadb']],
        'nextcloud' => [['container' => 'nextcloud-app', 'occ' => '/var/www/html/occ', 'user' => 'www-data', 'same_as' => '']],
        'files' => [['path' => 'db/mariadb_nextcloud-db_nextcloud.sql.gz', 'bytes' => 100, 'run' => '20261005-0200', 'what' => 'dump', 'container' => 'nextcloud-db'],
                    ['path' => 'compose/compose.yaml', 'bytes' => 20, 'run' => '20261006-0200', 'what' => 'compose'],
                    ['path' => '../escape', 'bytes' => 1, 'run' => '20261006-0200', 'what' => 'other']]]);
    $put('apps/emby/manifest.json', ['name' => 'EmbyServer', 'type' => 'template', 'run' => '20261001-0200',
        'containers' => [['name' => 'EmbyServer', 'image' => 'emby/embyserver', 'template' => 'my-EmbyServer.xml']],
        'files' => [['path' => 'my-EmbyServer.xml', 'bytes' => 9, 'run' => '20261001-0200', 'what' => 'template']]]);
    $put('vms/Win/manifest.json', ['name' => 'Win', 'run' => '20261006-0200', 'xml' => 'Win.xml', 'uuid' => '43CD8087-9364-2C3D-EB36-29696480E7D8',
        'disks' => [['source' => '/mnt/user/domains/Win/vdisk1.img', 'snapshot' => 'maple/domains/Win@unraidbackup-20261006-0200', 'share' => 'domains']],
        'files' => [['path' => 'Win.xml', 'bytes' => 5, 'what' => 'xml'], ['path' => 'nvram/43cd8087-9364-2c3d-eb36-29696480e7d8_VARS-pure-efi.fd', 'bytes' => 7, 'what' => 'nvram']]]);
    $put('vms/Win/Win.xml', '<domain><hostdev/><hostdev/></domain>');
    $p = rsPackages($tmp);
    same('restore: apps by name', ['EmbyServer', 'nextcloud'], array_column($p['apps'], 'name'));
    same('restore: a package of an earlier run is stale', [true, false], array_column($p['apps'], 'stale'));
    $nc = $p['apps'][1];
    same('restore: a kept dump with its database and the variables only', ['db/mariadb_nextcloud-db_nextcloud.sql.gz', 'nextcloud', true, 'user', 'MARIADB_USER', 'MARIADB_PASSWORD'],
        [$nc['dumps'][0]['file'] ?? null, $nc['dumps'][0]['db'] ?? null, $nc['dumps'][0]['kept'] ?? null, $nc['dumps'][0]['login'] ?? null,
         $nc['dumps'][0]['user_var'] ?? null, $nc['dumps'][0]['password_var'] ?? null]);
    same('restore: no secrets in the package as read', false, str_contains(json_encode($p), 'secret'));
    same('restore: binds only, without the trailing slash', [['source' => '/mnt/user/appdata/nextcloud/db', 'dest' => '/var/lib/mysql', 'rw' => true]], $nc['containers'][0]['binds']);
    same('restore: database types from env and image', ['mariadb', null], array_column($nc['containers'], 'db'));
    same('restore: compose files, no path out of the package', [['compose.yaml'], 2], [$nc['compose']['files'], count($nc['files'])]);
    same('restore: templates', ['my-EmbyServer.xml'], $p['apps'][0]['templates']);
    $vm = $p['vms'][0] ?? [];
    same('restore: a VM with its UUID, NVRAM and devices', ['43cd8087-9364-2c3d-eb36-29696480e7d8', ['43cd8087-9364-2c3d-eb36-29696480e7d8_VARS-pure-efi.fd'], 2, false],
        [$vm['uuid'] ?? null, $vm['nvram'] ?? null, $vm['hostdev'] ?? null, $vm['tpm'] ?? null]);
    exec('rm -rf ' . escapeshellarg($tmp));

    $ctx = ['fs' => ['maple' => 'zfs', 'disk1' => 'btrfs']];
    same('restore: share paths', [['appdata', 'nextcloud/db', null], ['appdata', 'x', 'maple'], null, null, null, ['domains', '', null]],
        [rsSharePath('/mnt/user/appdata/nextcloud/db/', $ctx), rsSharePath('/mnt/maple/appdata/x', $ctx), rsSharePath('/mnt/disks/ud/x', $ctx),
         rsSharePath('/mnt/user/appdata/../etc', $ctx), rsSharePath('/mnt/user/.hidden/x', $ctx), rsSharePath('/mnt/user/domains', $ctx)]);

    // whether he suits the server says what is really there (a fresh server: no package, no snapshot yet)
    $set = ['general' => ['dumps_share' => ['UnraidSecretaryOffice']]];
    $cow = ['zfs' => ['maple'], 'btrfs' => []];
    $fitOf = fn (array $f) => [$f['ok'], $f['why'], $f['params']['n'] ?? null];
    $ran = fn (int $finished, bool $written) => ['finished' => $finished, 'packages' => ['written' => $written, 'apps' => 25, 'vms' => 3]];
    same('restore fit: the packages of his last look', [true, 'packages', 2],
        $fitOf(rsFit(['time' => 100, 'apps' => [['id' => 'a']], 'vms' => [['id' => 'v']]], [], $set, $cow)));
    same('restore fit: a real run wrote packages after his last look', [true, 'packages', 28], $fitOf(rsFit(['time' => 100, 'apps' => []], $ran(200, true), $set, $cow)));
    same('restore fit: set up, no packages yet (none written, or before his look)', [[true, 'no_packages', null], [true, 'no_packages', null], [true, 'no_packages', null]],
        [$fitOf(rsFit(['time' => 100, 'apps' => []], $ran(200, false), $set, $cow)), $fitOf(rsFit(['time' => 300, 'apps' => []], $ran(200, true), $set, $cow)),
         $fitOf(rsFit(['time' => 300], [], $set, ['zfs' => [], 'btrfs' => []]))]);
    same('restore fit: a fresh server with ZFS — nothing yet, worth hiring with Mr. Backupsy (never «snapshots»)', [true, 'with_backup', null],
        $fitOf(rsFit(['time' => 0], [], [], $cow)));
    same('restore fit: neither packages nor ZFS/btrfs', [false, 'nothing', null], $fitOf(rsFit(['time' => 0], [], [], ['zfs' => [], 'btrfs' => []])));
    $en = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/restore/lang/en.json'), true) ?: [];
    foreach (['packages', 'no_packages', 'with_backup', 'nothing'] as $why) {
        check("restore fit: words for $why", isset($en["fit.$why"]));
    }
}

/**
 * Mr. Restori restores (steps 2-6): what a dump holds per database, the credentials only as variable names in
 * the container's script, where things go aside (flash, next to it), clean paths, Kopia's list; the job's steps on
 * a temporary folder (aside, put, move, fresh, copy — each recording how «Put back» undoes it) and the put back
 * built from the journal; the engine's lock with his note; a whole job as its own process (done, and refused while
 * the lock is held); interrupted journals; the Dashboard's row. Everything in a temporary folder.
 */
/**
 * 1.60.1 (a user, a partner restore on Backup2): Mr. Restori's running restore as a card in the row's place, like Mr.
 * Backupsy's run - the steps short (the full sentence in the journal), the current one's % and time left from the live
 * rate only with its size known, the whole's end only when every copy step still to come has a size; no history.
 */
function testRestoreRunCard(): void
{
    $rjs = (string) file_get_contents(OFFICE_WEB . '/desks/restore/desk.js');
    check('restore run card: above the tiles while a restore runs, no banner over it', str_contains($rjs, 'view.card = card;') && !str_contains($rjs, "T('notice.restoring'"));
    $node = testsNode();
    if ($node === '') {
        check('restore run card: node is missing here - skipped', true);
        return;
    }
    $tmp = hardeningTmp('restore-runcard');
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const el = (tag, cls, t) => ({ tag, className: cls || '', textContent: t == null ? '' : String(t), children: [], style: {}, dataset: {},
  appendChild(c) { this.children.push(c); return c; }, append(...c) { this.children.push(...c); }, setAttribute() {} });
const text = (n) => (typeof n === 'string' ? n : n.textContent + (n.children || []).map(text).join(''));
const strings = JSON.parse(fs.readFileSync(process.argv[3], 'utf8'));
globalThis.Office = { scope: () => T, t: T, el, store: () => null, desk: () => {}, places: () => {}, placesFrom: () => {}, placesTook: () => {},
  sections: () => ({ places: () => [] }), has: (k) => k.replace(/^restore\./, '') in strings,
  fmt: { size: (b) => b + ' B', relative: (t) => 'rel ' + t, date: (t) => 'date ' + t, time: (t) => 'T' + t, duration: (s) => Math.round(s) + 's' } };
(0, eval)(fs.readFileSync(process.argv[4], 'utf8'));
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const r = OFFICE_DESK_TESTS.restore;
const job = (pr, more = {}) => ({ id: 'j1', kind: 'start_from', what: 'Windows11 ← Sender', result: 'running', started: 1000, sizes: null, ...more,
  steps: [{ do: 'pull', unit: 'vm:Windows11', partner: 'Sender', bytes: 1000, state: 'ok' }, { do: 'mount', dataset: 'x', path: '/p', state: 'ok' },
    { do: 'copy', from: '/a', to: '/mnt/user/domains/Windows11', state: 'running', progress: pr }, { do: 'start_from', kind: 'vm', to: '/t', name: 'W', state: 'pending' }] });
const out = {};
const d0 = r.runCardData(job({ done: 640, total: 1000, percent: 64 }), 2000);
out.steps = d0.steps.map((s) => [s.name, s.state]);
out.first = [d0.at, d0.percent, d0.left, d0.end, d0.errors, d0.warnings];
// two more samples: 10 bytes/s - 280 s left; the copy is the last copy step - the end is known
r.runCardData(job({ done: 700, total: 1000, percent: 70 }), 2006);
const d2 = r.runCardData(job({ done: 720, total: 1000, percent: 72 }), 2008);
out.rate = [d2.percent, d2.left, d2.end];
// a copy step still to come without a size: the step's time left, no end
const j3 = job({ done: 720, total: 1000, percent: 72 });
j3.steps.push({ do: 'copy', from: '/b', to: '/c', state: 'pending' });
const d3 = r.runCardData(j3, 2010);
out.noEnd = [d3.left !== null, d3.end];
// no size known: the % only
const d4 = r.runCardData(job({ done: 720, total: null, percent: 72 }, { id: 'j2' }), 2010);
out.pctOnly = [d4.percent, d4.left, d4.end];
const card = r.runCard(job({ done: 720, total: 1000, percent: 72 }), 2012);
out.card = text(card);
out.cls = card.className;
console.log(JSON.stringify(out));
JS);
    file_put_contents("$tmp/strings.json", file_get_contents(OFFICE_WEB . '/desks/restore/lang/en.json'));
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/restore/desk.js') . ' ' . escapeshellarg("$tmp/strings.json")
        . ' ' . escapeshellarg(testsRunHelpersJs($tmp)) . ' 2>&1');
    $r = json_decode($raw, true) ?: [];
    same('restore run card: the steps by their short names, done / running / waiting', [['ss.pull', 'ok'], ['ss.mount', 'ok'], ['ss.copy', 'running'], ['ss.start_from_vm', 'pending']],
        $r['steps'] ?? $raw);
    same('restore run card: the first look - the step, its 64 %, no time yet (one sample), no errors', [2, 64, null, null, 0, 0], $r['first'] ?? $raw);
    same('restore run card: the live rate (the median: 10 B/s) - 28 s left, the end known (no copy step after it)', [72, 28, 2036], $r['rate'] ?? $raw);
    same('restore run card: a copy step to come without a size - the step\'s time, no end', [true, null], $r['noEnd'] ?? $raw);
    same('restore run card: no size - the % only, nothing made up', [72, null, null], $r['pctOnly'] ?? $raw);
    check('restore run card: the card - its title, «running» with the wave, the steps, «n % · left», the end, the counts, «Journal»',
        str_contains($r['card'] ?? '', 'jk.start_from') && str_contains($r['card'] ?? '', 'jr.running') && str_contains($r['card'] ?? '', '72 % · rc.left')
        && str_contains($r['card'] ?? '', 'rc.end') && str_contains($r['card'] ?? '', 'rc.errors') && str_contains($r['card'] ?? '', 'rc.log')
        && ($r['cls'] ?? '') === 'card rs-run running', $raw);
    $rjs2 = (string) file_get_contents(OFFICE_WEB . '/desks/restore/desk.js');
    check('restore run card 1.60.1: above the tiles whatever tile is open (the tiles stay), from the agent\'s word until the poll has the job, placed again at every poll',
        !str_contains($rjs2, 'sw.grid.hidden') && !str_contains($rjs2, "if (j && sw.active() !== 'journal')") && str_contains($rjs2, 'else if (run) view.card.appendChild(runCardShort(run));')
        && str_contains($rjs2, '} else if (live) placeRunCard();'));
    $bjs2 = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('backup run card 1.60.1: above the tiles too, the tiles stay', str_contains($bjs2, 'if (live()) root.appendChild(runningCard());') && !str_contains($bjs2, 's.grid.hidden = live();'));
    check('restore 1.60.1: a receiver with partners\' copies but no packages of its own says so (bubble.kept_only)', str_contains($rjs2, "held ? T('bubble.kept_only', { n: held }) : T('bubble.no_packages')"));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $lj = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/restore/lang/$l.json"), true) ?: [];
        same("restore run card: $l - the card's words and a short name for every step kind", [], array_values(array_filter(['rc.since', 'rc.left', 'rc.end', 'rc.errors',
            'rc.warnings', 'rc.log', 'ss.pull', 'ss.copy', 'ss.mount', 'ss.start_from_vm', 'ss.define', 'ss.aside', 'ss.kopia', 'ss.play', 'ss.start', 'ss.stop'], fn ($k) => !isset($lj[$k]))));
    }
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * 1.60.1 (a user, Windows11 from a test server onto Backup2: 8 GiB on 3.9, 3 vCPUs pinned to 10-12 on 2 CPUs, two
 * ISOs not there - it would not start): a VM's XML from another server fitted to this host (rspAdaptXml).
 */
function testRestoreVmFit(): void
{
    $xml = "<domain type='kvm'><name>W</name><memory unit='KiB'>8388608</memory><currentMemory unit='KiB'>8388608</currentMemory>"
        . "<vcpu placement='static'>3</vcpu><cputune><vcpupin vcpu='0' cpuset='10'/><vcpupin vcpu='1' cpuset='11'/><vcpupin vcpu='2' cpuset='1'/><emulatorpin cpuset='12'/></cputune>"
        . "<cpu mode='host-passthrough'><topology sockets='1' dies='1' cores='3' threads='1'/></cpu><devices>"
        . "<disk type='file' device='disk'><source file='/mnt/user/domains/W/vdisk1.img'/><target dev='hdc'/></disk>"
        . "<disk type='file' device='cdrom'><source file='/mnt/fast/isos/Win11.iso'/><target dev='hda'/></disk>"
        . "<disk type='file' device='cdrom'><source file='/mnt/user/isos/virtio-win-0.1.285-1.iso'/><target dev='hdb'/></disk>"
        . "<interface type='bridge'><source bridge='br1'/></interface><interface type='network'><source network='lan'/></interface>"
        . "<hostdev mode='subsystem' type='pci'><source><address bus='0x01'/></source></hostdev></devices></domain>";
    $host = ['cpus' => 2, 'mem_kib' => 4089000, 'bridges' => ['br0', 'virbr0'], 'networks' => ['default'], 'host' => 'backup2'];
    $here = fn (string $p) => $p === '/mnt/user/domains/W/vdisk1.img';
    [$out, $ch, $refuse] = rspAdaptXml($xml, $host, $here);
    $d = new DOMDocument();
    $d->loadXML($out);
    $x = new DOMXPath($d);
    $q = fn (string $e) => array_map(fn ($n) => $n->nodeValue, iterator_to_array($x->query($e)));
    same('vm fit: the changes said, each once', ['pins', 'vcpus', 'memory', 'hostdev', 'bridge', 'bridge', 'cdrom', 'cdrom'], array_column($ch, 'code'));
    same('vm fit: pins to CPUs not here gone (the one to CPU 1 kept), vCPUs capped with the topology', [['1'], ['2'], '2', '1'],
        [$q('/domain/cputune/vcpupin/@cpuset'), $q('/domain/vcpu'), $q('/domain/cpu/topology/@cores')[0] ?? null, $q('/domain/cpu/topology/@sockets')[0] ?? null]);
    same('vm fit: memory capped to three quarters, on Unraid\'s 512 MB steps (2.5 GiB), both values', [['2621440'], ['2621440'], ['KiB']],
        [$q('/domain/memory'), $q('/domain/currentMemory'), $q('/domain/memory/@unit')]);
    same('vm fit: no passthrough left, the missing bridge and network -> br0, the ISOs emptied with their drives kept, the vdisk untouched',
        [0, ['br0', 'br0'], 2, 0, ['/mnt/user/domains/W/vdisk1.img'], null],
        [$x->query('//hostdev')->length, $q('/domain/devices/interface/source/@bridge'), $x->query("//disk[@device='cdrom']")->length,
         $x->query("//disk[@device='cdrom']/source")->length, $q("//disk[@device='disk']/source/@file"), $refuse]);
    same('vm fit: the journal\'s numbers', [['n' => '3', 'cpus' => '2'], ['from' => '3', 'to' => '2'], ['from' => '8', 'to' => '2.5'], ['from' => 'br1', 'to' => 'br0']],
        [$ch[0]['params'], $ch[1]['params'], $ch[2]['params'], $ch[4]['params']]);
    [, , $refuse] = rspAdaptXml($xml, $host, fn () => false);
    same('vm fit: a disk image not here - no definition, said with its path', ['path' => '/mnt/user/domains/W/vdisk1.img'], $refuse);
    [$same, $none] = rspAdaptXml($xml, ['cpus' => 16, 'mem_kib' => 67108864, 'bridges' => ['br1', 'br0'], 'networks' => ['lan'], 'host' => 'x'], fn () => true);
    same('vm fit: a host it fits (CPUs, memory, its bridge, every file there) - the XML as it was but for the passthrough', [['hostdev'], false],
        [array_column($none, 'code'), str_contains($same, '<hostdev')]);
    same('vm fit: a small host - the form\'s first steps (256 MB, 128 MB)', [['262144'], ['131072']],
        [(function () use ($xml) { $d = new DOMDocument(); $d->loadXML(rspAdaptXml($xml, ['cpus' => 4, 'mem_kib' => 600000, 'bridges' => ['br0']], fn () => true)[0]);
            return array_map(fn ($n) => $n->nodeValue, iterator_to_array((new DOMXPath($d))->query('/domain/memory'))); })(),
         (function () use ($xml) { $d = new DOMDocument(); $d->loadXML(rspAdaptXml($xml, ['cpus' => 4, 'mem_kib' => 300000, 'bridges' => ['br0']], fn () => true)[0]);
            return array_map(fn ($n) => $n->nodeValue, iterator_to_array((new DOMXPath($d))->query('/domain/memory'))); })()]);
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/restore-partner.php');
    check('vm fit: only for a copy from another server (the manifest\'s host), the original XML kept as <name>.xml.original',
        str_contains($src, "if (strtolower(rsStr(\$m['host'] ?? '')) !== (\$host['host'] ?? '')) {") && str_contains($src, '$keep = "$dir/$name.xml.original";'));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $lj = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/restore/lang/$l.json"), true) ?: [];
        same("vm fit: $l - its words", [], array_values(array_filter(['sa.head', 'sa.pins', 'sa.vcpus', 'sa.memory', 'sa.hostdev', 'sa.bridge', 'sa.cdrom', 'sn.start_vm_disk_missing'],
            fn ($k) => !isset($lj[$k]))));
    }
}

/**
 * Review 2026-10-15 (R1): a VM's XML from a partner's copy is the partner's word — and `virsh define` alone runs its
 * <emulator> as root (libvirt asks the binary what it can; tried on a test server). rspXmlForeign(): what would run
 * or reach this server goes (said in the step), a path of this server outside the VM's own folder refuses the
 * definition; both define paths (start from a copy, a VM restored from a pulled backup place) go through it.
 */
function testRestoreVmForeign(): void
{
    $dir = '/mnt/user/domains/W';
    $ok = "<domain type='kvm'><name>W</name><title>/etc/x in prose</title><metadata><vmtemplate xmlns='unraid' icon='/boot/x.png'/></metadata>"
        . "<os><type>hvm</type><loader readonly='yes' type='pflash'>/usr/share/qemu/ovmf-x64/OVMF_CODE-pure-efi.fd</loader>"
        . "<nvram>/etc/libvirt/qemu/nvram/1234_VARS-pure-efi.fd</nvram></os><devices><emulator>/usr/local/sbin/qemu</emulator>"
        . "<disk type='file' device='disk'><source file='$dir/vdisk1.img'/><target dev='hdc'/></disk>"
        . "<disk type='file' device='cdrom'><source file='/mnt/user/isos/virtio.iso'/><target dev='hda'/></disk>"
        . "<interface type='bridge'><source bridge='br0'/><target dev='vnet0'/></interface>"
        . "<rng model='virtio'><backend model='random'>/dev/urandom</backend></rng></devices></domain>";
    [$out, $ch, $refuse] = rspXmlForeign($ok, 'W', [$dir]);
    same('vm foreign: an ordinary Unraid VM - as it was, nothing said, nothing refused', [$ok, [], null], [$out, $ch, $refuse]);
    $bad = "<domain type='kvm' xmlns:qemu='http://libvirt.org/schemas/domain/qemu/1.0'><name>W</name><devices>"
        . "<emulator>$dir/qemu</emulator><disk type='file' device='disk'><source file='$dir/vdisk1.img'/><target dev='hdc'/></disk>"
        . "<filesystem type='mount'><driver type='virtiofs'/><binary path='/usr/libexec/virtiofsd'/><source dir='/'/><target dir='root'/></filesystem>"
        . "<interface type='ethernet'><script path='$dir/up.sh'/><downscript path='$dir/down.sh'/></interface>"
        . "<hostdev mode='subsystem' type='pci'><source><address bus='0x01'/></source></hostdev><input type='evdev'><source dev='/dev/input/event0'/></input>"
        . "</devices><qemu:commandline><qemu:arg value='-netdev'/><qemu:arg value='tap,script=/tmp/x'/></qemu:commandline></domain>";
    [$out, $ch, $refuse] = rspXmlForeign($bad, 'W', [$dir]);
    same('vm foreign: what would run here or reach this server - removed and said, the emulator Unraid\'s',
        [['qemu', 'filesystem', 'net_script', 'passthrough', 'emulator'], ['1', '1', '2', '2'], null, false, false, false, false, true],
        [array_column($ch, 'code'), array_map(fn ($c) => $c['params']['n'] ?? null, array_slice($ch, 0, 4)), $refuse,
         str_contains($out, 'commandline'), str_contains($out, '<filesystem'), str_contains($out, 'script'), str_contains($out, 'hostdev'),
         str_contains($out, '<emulator>/usr/local/sbin/qemu</emulator>')]);
    $refused = [];
    foreach ([
        'a disk of the flash'            => "<disk type='file' device='disk'><source file='/boot/config/go'/></disk>",
        'a host disk'                    => "<disk type='block' device='disk'><source dev='/dev/sda'/></disk>",
        'another VM\'s disk'             => "<disk type='file' device='disk'><source file='/mnt/user/domains/Other/vdisk1.img'/></disk>",
        'a way out of its folder'        => "<disk type='file' device='disk'><source file='$dir/../Other/vdisk1.img'/></disk>",
        'a relative path'                => "<disk type='file' device='disk'><source file='boot/config/go'/></disk>",
        'a host file as cdrom'           => "<disk type='file' device='cdrom'><source file='/etc/shadow'/></disk>",
        'a storage pool\'s volume'       => "<disk type='volume' device='disk'><source pool='default' volume='v'/></disk>",
        'a serial port into a host file' => "<serial type='file'><source path='/boot/config/go'/></serial>",
        'a host file as fw_cfg'          => "<sysinfo type='fwcfg'><entry name='opt/x' file='/root/.ssh/id_rsa'/></sysinfo>",
    ] as $what => $dev) {
        [, , $r] = rspXmlForeign("<domain type='kvm'><name>W</name><devices>$dev</devices></domain>", 'W', [$dir]);
        if (($r['note'] ?? '') !== 'vm_foreign_path') {
            $refused[] = $what;
        }
    }
    same('vm foreign: a path of this server outside the VM\'s folder (or an odd disk) refuses the definition', [], $refused);
    [, , $r] = rspXmlForeign("<domain type='kvm'><name>Windows11</name></domain>", 'W', [$dir]);
    same('vm foreign: another VM\'s name (its definition would be replaced) - refused', ['note' => 'vm_foreign_name', 'params' => ['other' => 'Windows11']], $r);
    [, , $r] = rspXmlForeign("<domain type='kvm'><name>W</name><os><kernel>/boot/bzimage</kernel></os></domain>", 'W', [$dir]);
    same('vm foreign: a kernel of this server - refused', 'vm_foreign_path', $r['note'] ?? null);
    [, , $r] = rspXmlForeign('', 'W', [$dir]);
    same('vm foreign: a configuration that can\'t be read - refused in its own words, never «?» as a path', ['note' => 'vm_xml_unreadable', 'params' => []], $r);
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/restore-partner.php');
    $rs = (string) file_get_contents(OFFICE_DIR . '/agent/desks/restore.php');
    $start = substr($src, (int) strpos($src, 'function rspStartVm('), 6000);
    check('vm foreign: «start from a copy» checks the XML before anything is put in place, the original kept when changed',
        str_contains($start, 'rspXmlForeign($xml, $name, [$folder])') && strpos($start, 'rspXmlForeign(') < strpos($start, "foreach (\$pkg['nvram']")
        && strpos($start, 'rspXmlForeign(') < strpos($start, "'define', \$file"));
    check('vm foreign: a VM restored from a pulled backup place too (its XML under the restored mounts)',
        (bool) preg_match('/function rsDoDefine\(.*?str_starts_with\(\$xml, rspMountRoot\(\) \. \'\/\'\).*?rspXmlForeign\(/s', $rs));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $lj = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/restore/lang/$l.json"), true) ?: [];
        same("vm foreign: $l - its words", [], array_values(array_filter(['sa.qemu', 'sa.filesystem', 'sa.net_script', 'sa.passthrough', 'sa.emulator',
            'sn.vm_foreign_path', 'sn.vm_foreign_name', 'sn.vm_xml_unreadable'], fn ($k) => !isset($lj[$k]))));
    }
}

/**
 * 1.60.1 (a user's stack «dropnook» onto another server): a Compose stack from another server's copy made in the
 * Compose Manager here - same folder name, never over one, never without the Compose Manager, its paths fitted, not started.
 */
function testRestoreStack(): void
{
    $tmp = hardeningTmp('restore-stack');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $dir = "$tmp/appdata/drop/" . RSP_INSIDE;
    @mkdir("$dir/compose", 0755, true);
    $yaml = "services:\n  drop:\n    image: x/drop\n    volumes:\n      - /mnt/fast/appdata/drop:/config\n      - /mnt/user/drop:/data\n"
        . "  drop-share:\n    image: x/share\n    volumes:\n      - /mnt/fastpool/gone/x:/x\n      - /mnt/cache/drop/tmp:/tmp\n";
    file_put_contents("$dir/compose/compose.yaml", $yaml);
    file_put_contents("$dir/compose/compose.override.yaml", "services:\n  drop:\n    labels: {a: b}\n");
    file_put_contents("$dir/compose/name", "dropnook\n");
    file_put_contents("$dir/compose/autostart", "true\n");
    $m = ['kind' => 'app', 'type' => 'compose', 'name' => 'dropnook', 'host' => 'Sender', 'compose' => ['project' => 'dropnook', 'manager_dir' => 'dropnook']];
    $old = $GLOBALS['rs'] ?? null;
    $GLOBALS['rs'] = ['compose_here' => true, 'compose_root' => "$tmp/projects", 'pool_here' => fn (string $p) => $p === 'cache', 'path_here' => fn () => true,
        'shares_ini' => ['appdata' => [], 'drop' => []]];
    try {
        // the fitting alone
        [$fit, $mapped, $missing] = rspFitCompose($yaml, fn ($p) => $p === 'cache', fn ($sh) => in_array($sh, ['appdata', 'drop'], true), fn () => true);
        same('stack: a pool not here -> /mnt/user/<share> when the share is here; a share not here named missing; a pool here and /mnt/user left',
            [[['/mnt/fast/appdata', '/mnt/user/appdata']], ['/mnt/fastpool/gone'], true, true, true],
            [$mapped, $missing, str_contains($fit, '/mnt/user/appdata/drop:/config'), str_contains($fit, '/mnt/cache/drop/tmp:/tmp'), str_contains($fit, '/mnt/user/drop:/data')]);
        // 1.60.1 (a user, dropnook on Backup2): a share that isn't here (/mnt/user/drop/...) and a host path that isn't there
        // are named missing too - the share as «its data didn't come along»
        $y2 = "services:\n  drop:\n    volumes:\n      - /mnt/user/drop:/data\n      - /mnt/user/drop/shares/counters:/c\n      - \"/opt/gone/x:/y\"\n      - /var/run/docker.sock:/var/run/docker.sock\n";
        [, , $miss2] = rspFitCompose($y2, fn () => false, fn ($sh) => $sh === 'appdata', fn ($p) => $p === '/var/run/docker.sock');
        same('stack 1.60.1: /mnt/user/<share> of a share not here and a host path not there - missing; the shares named', [['/mnt/user/drop', '/opt/gone/x'], ['drop']],
            [$miss2, rspSharesMissing($miss2)]);
        // 1.60.1 (a user, the real dropnook compose.yaml - tests/fixtures/dropnook-compose.yaml): the paths are YAML anchors in an
        // x-settings block, the services bind them with the long syntax (source: *data); host paths only, never a target
        $real = (string) file_get_contents(OFFICE_DIR . '/tests/fixtures/dropnook-compose.yaml');
        [$fitR, $mapR, $missR] = rspFitCompose($real, fn () => false, fn ($sh) => $sh === 'appdata', fn ($p) => in_array($p, ['/boot/config/ident.cfg', '/mnt/user/appdata/drop'], true));
        same('stack 1.60.1: the real dropnook file - the share drop (anchors, long syntax) missing, NPM\'s certificates folder too; ident.cfg there; never /data or /config',
            [['/mnt/user/drop', '/mnt/user/appdata/Nginx-Proxy-Manager-Official/letsencrypt'], ['drop']], [$missR, rspSharesMissing($missR)]);
        [$fitP] = rspFitCompose(str_replace('&data            /mnt/user/drop', '&data            /mnt/fast/drop', $real), fn ($p) => $p === 'cache', fn ($sh) => true, fn () => true);
        check('stack 1.60.1: … a pool path in an anchor is fitted where it is defined (the alias stays)', str_contains($fitP, '&data            /mnt/user/drop') && str_contains($fitP, 'source: *data'));
        // made: the project with its files, fitted, the original beside, autostart as it was, an undo
        $undo = [];
        $r = rspStartStack($m, $dir, $undo);
        $pd = "$tmp/projects/dropnook";
        same('stack: created in the Compose Manager\'s projects under its folder name - files, fitted compose.yaml, the original kept, autostart kept, not started',
            ['created', true, true, true, "true\n", false, ['/mnt/fastpool/gone']],
            [$r['state'] ?? null, str_contains((string) @file_get_contents("$pd/compose.yaml"), '/mnt/user/appdata/drop'), (string) @file_get_contents("$pd/compose.yaml.original") === $yaml,
             is_file("$pd/compose.override.yaml") && !is_file("$pd/compose.override.yaml.original"), (string) @file_get_contents("$pd/autostart"), (bool) glob("$tmp/projects/.dropnook.uso-*"), $r['missing'] ?? null]);
        same('stack: … its undo puts the project aside', [['aside', $pd]], array_map(fn ($u) => [$u['do'], $u['path']], $undo));
        // never over a project of that name
        file_put_contents("$pd/compose.yaml", 'mine');
        $undo = [];
        same('stack: a project of that name here - left as it is, said, nothing made', ['exists', 'mine', []], [rspStartStack($m, $dir, $undo)['state'] ?? null, file_get_contents("$pd/compose.yaml"), $undo]);
        // no Compose Manager (a user: Dockge, Portainer, docker compose by hand are ways too): a hint, never a block -
        // nothing created, the copy's own files fitted in place with the originals beside, the paths said
        exec('rm -rf ' . escapeshellarg("$tmp/projects"));
        $GLOBALS['rs']['compose_here'] = false;
        $GLOBALS['rs']['compose_cli'] = false;
        $undo = [];
        $r = rspStartStack($m, $dir, $undo);
        same('stack: no Compose Manager - nothing made, the copy\'s files fitted where they are (original beside), where they lie said',
            ['no_manager', false, [], "$dir/compose", true, true, [['/mnt/fast/appdata', '/mnt/user/appdata']]],
            [$r['state'] ?? null, is_dir("$tmp/projects"), $undo, $r['path'] ?? null, str_contains((string) file_get_contents("$dir/compose/compose.yaml"), '/mnt/user/appdata/drop'),
             (string) @file_get_contents("$dir/compose/compose.yaml.original") === $yaml, $r['mapped'] ?? null]);
        $GLOBALS['rs']['compose_cli'] = true;
        same('stack: … docker compose here but no Compose Manager - said so, still nothing made; a second time keeps the first original',
            ['no_manager_cli', true], [rspStartStack($m, $dir, $undo)['state'] ?? null, (string) @file_get_contents("$dir/compose/compose.yaml.original") === $yaml]);
        // «Create the stack now» (1.60.1): once the Compose Manager is here, the stack part alone from the copy the journal recorded
        $GLOBALS['rs']['data'] = "$tmp/rsdata";
        $GLOBALS['rs']['compose_cli'] = false;
        file_put_contents("$dir/manifest.json", json_encode($m));
        $jid = '20261012-160000-beef';
        @mkdir("$tmp/rsdata/$jid", 0700, true);
        $j = ['id' => $jid, 'kind' => 'partner_start', 'what' => 'appdata', 'result' => 'warnings', 'steps' => [['do' => 'start_from', 'state' => 'warning', 'undo' => [],
              'params' => ['stacks' => [['state' => 'no_manager', 'name' => 'dropnook', 'path' => "$dir/compose", 'mapped' => [], 'missing' => []]]]]]];
        rsJournalWrite($j);
        $GLOBALS['rs']['compose_here'] = false;
        $err = null;
        try { rspStackLater($jid, 'dropnook'); } catch (Problem $e) { $err = $e->key; }
        same('stack later: without the Compose Manager - refused, said', 'restore_compose_missing', $err);
        $GLOBALS['rs']['compose_here'] = true;
        $r = rspStackLater($jid, 'dropnook')['stack'] ?? [];
        $jr = rsJournal($jid);
        same('stack later: made from the recorded copy - fitted, the original carried along, its line and undo in the journal',
            ['created', true, true, 'created', [['aside', "$tmp/projects/dropnook"]]],
            [$r['state'] ?? null, str_contains((string) @file_get_contents("$tmp/projects/dropnook/compose.yaml"), '/mnt/user/appdata/drop'), is_file("$tmp/projects/dropnook/compose.yaml.original"),
             $jr['steps'][0]['params']['stacks'][0]['state'] ?? null, array_map(fn ($u) => [$u['do'], $u['path']], $jr['steps'][0]['undo'] ?? [])]);
        $err = null;
        try { rspStackLater($jid, 'dropnook'); } catch (Problem $e) { $err = $e->key; }
        same('stack later: … once only (the stack\'s line says created now)', 'unknown_target', $err);
    } finally {
        $GLOBALS['rs'] = $old;
    }
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/restore-partner.php');
    check('stack: the share scan makes it after the app\'s templates and says it (params.stacks); trouble makes the step a warning',
        str_contains($src, "\$stack = (\$m['type'] ?? '') === 'compose' && \$place ? rspStartStack(\$m, \$dir, \$undo) : null;") && str_contains($src, "'params' => ['stacks' => \$stacks,"));
    $rjs = (string) file_get_contents(OFFICE_WEB . '/desks/restore/desk.js');
    check('stack: the journal and the run card say it - created (not started), left, the way to the Apps', str_contains($rjs, "T('sk.' + k.state, { name: k.name || '', path: k.path || '' })")
        && str_contains($rjs, "a.href = '/Apps';"));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $lj = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/restore/lang/$l.json"), true) ?: [];
        same("stack: $l - its words", [], array_values(array_filter(['sk.created', 'sk.exists', 'sk.no_manager', 'sk.no_manager_cli', 'sk.create_now', 'errors.restore_compose_missing', 'sk.no_files', 'sk.to_apps', 'sk.mapped', 'sk.missing'], fn ($k) => !isset($lj[$k]))));
    }
    // 1.60.1: declined proposals - kept root-only with the value proposed, never a [partner] key; «Propose again» forgets
    $GLOBALS['backupDeclineDir'] = "$tmp/decl";
    backupDecline('general|keep_logs', '30');
    backupDecline('share|media|mode', 'kopia');
    $bad = null;
    try { backupDecline('partner|5e6f7a8b|name', 'x'); } catch (Problem $e) { $bad = $e->key; }
    same('declines: remembered with the value, a [partner] key refused, the file root-only', [['general|keep_logs' => '30', 'share|media|mode' => 'kopia'], 'bad_request', '600'],
        [array_map(fn ($d) => $d['value'], backupDeclined()), $bad, decoct(fileperms("$tmp/decl/declined.json") & 0777)]);
    backupDeclineUndo('general|keep_logs');
    same('declines: «Propose again» forgets one', ['share|media|mode'], array_keys(backupDeclined()));
    unset($GLOBALS['backupDeclineDir']);
    $bjs = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('the tour on the setup page: the page follows a run there too and draws the setup anew when it ends (a user: «it hung»)',
        str_contains($bjs, "if (view && (page === 'main' || page === 'setup') && state && (state.running") && str_contains($bjs, "else if (view && page === 'setup' && was !== !!(state && state.running)) renderSetup();"));
    check('declines: applied before the proposals become the base, listed under the general settings with «Propose again»',
        str_contains($bjs, "  setupDeclinedApply();                    // 1.60.1") && str_contains($bjs, 'const dl = declinedList();') && str_contains($bjs, '`${ID}.setup_decline`'));
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * 1.60.1 (approved): «Make it a dataset of its own…» from Mr. Backupsy's setup - the look and its refusals, the
 * dialog's states (no fresh backup), the job's steps in their order with a stand-in zfs, the comparison, the old folder
 * into the storeroom, and the rollback after a failure.
 */
function testSetupMakeDataset(): void
{
    if (posix_geteuid() !== 0) {
        check('make dataset: root only — not run here', true);
        return;
    }
    $tmp = hardeningTmp('make-dataset');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $mnt = "$tmp/mnt";
    foreach (["$mnt/tank/appdata/drop/sub", "$mnt/tank/appdata/web", "$mnt/tank/appdata/has/kids", "$mnt/tank/appdata/bad name", "$mnt/arr/media/x", "$tmp/bin", "$tmp/rs"] as $d) {
        @mkdir($d, 0755, true);
    }
    file_put_contents("$mnt/tank/appdata/drop/a.txt", str_repeat('a', 5000));
    file_put_contents("$mnt/tank/appdata/drop/sub/b.txt", 'b');
    chmod("$mnt/tank/appdata/drop", 0750);
    // a zfs stand-in: create/destroy make and remove <mnt>/<dataset>, everything else succeeds
    file_put_contents("$tmp/bin/zfs", "#!/bin/bash\necho \"zfs \$*\" >>\"$tmp/zfs.log\"\ncase \"\$1\" in\n  create) [[ -e \"$tmp/zfs.fail\" ]] && exit 1; mkdir -p \"$mnt/\$2\" ;;\n  destroy) rm -rf \"$mnt/\$2\" ;;\nesac\nexit 0\n");
    chmod("$tmp/bin/zfs", 0755);
    $zfsMap = ['tank' => "$mnt/tank", 'tank/appdata' => "$mnt/tank/appdata", 'tank/appdata/web' => "$mnt/tank/appdata/web", 'tank/appdata/has/kids' => "$mnt/tank/appdata/has/kids"];
    $oldRs = $GLOBALS['rs'] ?? null;
    $oldMd = $GLOBALS['md'] ?? null;
    $oldPath = getenv('PATH');
    $GLOBALS['md'] = ['mnt' => $mnt, 'zfs' => $zfsMap, 'bytes' => 5001, 'last' => ['finished' => time() - 3600, 'result' => 'ok']];
    $GLOBALS['rs'] = ['data' => "$tmp/rs", 'users' => fn () => [['drop', 'drop-share'], []], 'vm_states' => []];
    putenv("PATH=$tmp/bin:$oldPath");
    try {
        $look = fn (string $dir, string $share = 'appdata') => mdLook(['kind' => 'app', 'name' => 'x', 'share' => $share, 'dir' => $dir]);
        same('make dataset: the refusals - already a dataset, datasets inside, a name ZFS doesn\'t take, not on ZFS, not there',
            ['md_already', 'md_children', 'md_name', 'md_not_zfs', 'md_missing'],
            [$look('web')['blockers'][0]['key'] ?? null, $look('has')['blockers'][0]['key'] ?? null, $look('bad name')['blockers'][0]['key'] ?? null,
             $look('x', 'media')['blockers'][0]['key'] ?? null, $look('gone')['blockers'][0]['key'] ?? null]);
        $l = $look('drop');
        same('make dataset: the look - the folder on its pool, the dataset to make, what stops, about how long, the last backup fresh',
            [[], "$mnt/tank/appdata/drop", 'tank/appdata/drop', ['drop', 'drop-share'], 5001, 31, true],
            [$l['blockers'], $l['target']['path'] ?? null, $l['target']['dataset'] ?? null, $l['stops']['containers'] ?? null, $l['bytes'], $l['downtime'], $l['last']['fresh'] ?? null]);
        $p = mdPlan(['kind' => 'app', 'name' => 'drop', 'share' => 'appdata', 'dir' => 'drop']);
        same('make dataset: the job\'s steps - stop, aside, create, copy, compare, start what was stopped, the old folder into the storeroom',
            ['stop', 'md_aside', 'md_create', 'md_copy', 'md_compare', 'start', 'md_store'], array_column($p['steps'], 'do'));
        $GLOBALS['md']['last'] = ['finished' => time() - 3 * 86400, 'result' => 'ok'];
        same('make dataset: no fresh backup (3 days old) - refused unless the user said he knows', ['md_no_fresh_backup', []],
            [mdPlan(['kind' => 'app', 'name' => 'drop', 'share' => 'appdata', 'dir' => 'drop'])['blockers'][0]['key'] ?? null,
             mdPlan(['kind' => 'app', 'name' => 'drop', 'share' => 'appdata', 'dir' => 'drop'], true)['blockers']]);
        $GLOBALS['md']['last'] = ['finished' => time() - 600, 'result' => 'failed'];
        same('make dataset: … the last one failed - not fresh either', false, mdLastBackup()['fresh']);

        // the steps, one by one, with the stand-in zfs (the containers: no docker here - their steps are Mr. Restori's own)
        $j = rsJournalNew('20261012-150000-abcd', $p);
        $j['id'] = '20261012-150000-abcd';
        @mkdir(rsDir($j['id']), 0700, true);
        $at = fn (string $do) => array_search($do, array_column($j['steps'], 'do'), true);
        $run = function (string $do) use (&$j, $at): array {
            $i = $at($do);
            $r = rsStep($j, $i);
            $j['steps'][$i] = array_merge($j['steps'][$i], $r);
            return $r;
        };
        $aside = $j['steps'][$at('md_aside')]['to'];
        same('make dataset: aside, create (inherits: zfs create <parent>/<name>), copy, compare - each ok',
            ['ok', 'ok', 'ok', 'ok'], [$run('md_aside')['state'], $run('md_create')['state'], $run('md_copy')['state'], $run('md_compare')['state']]);
        same('make dataset: … the files in the new dataset, the top folder\'s mode as before, the stand-in asked to create tank/appdata/drop',
            [str_repeat('a', 5000), 'b', '750', true],
            [(string) @file_get_contents("$mnt/tank/appdata/drop/a.txt"), (string) @file_get_contents("$mnt/tank/appdata/drop/sub/b.txt"),
             decoct(fileperms("$mnt/tank/appdata/drop") & 0777), str_contains((string) @file_get_contents("$tmp/zfs.log"), 'zfs create tank/appdata/drop')]);
        $r = $run('md_store');
        same('make dataset: the old folder into Ms. Dustdevil\'s storeroom, a «leftover» of this job in her manifest', ['ok', false, 'leftover', $aside],
            [$r['state'], is_dir($aside), (glob("$mnt/tank/appdata/" . CL_TRASH . '/*/manifest.json') ? json_decode((string) file_get_contents(glob("$mnt/tank/appdata/" . CL_TRASH . '/*/manifest.json')[0]), true)['items'][0]['kind'] ?? null : null),
             (glob("$mnt/tank/appdata/" . CL_TRASH . '/*/manifest.json') ? json_decode((string) file_get_contents(glob("$mnt/tank/appdata/" . CL_TRASH . '/*/manifest.json')[0]), true)['items'][0]['from'] ?? null : null)]);

        // a Compose stack: never stopped or started by me - running, «Make it» waits (a blocker the dialog turns into its
        // advice); stopped, the job looks again first and leaves the starting to the user
        $sl = mdLook(['kind' => 'app', 'name' => 'dropnook', 'share' => 'appdata', 'dir' => 'drop', 'stack' => 'dropnook']);
        same('make dataset: a stack still running - no stop of mine, said which runs', [['md_stack_running'], 'dropnook', [], 'drop, drop-share'],
            [array_column($sl['blockers'], 'key'), $sl['stops']['stack'] ?? null, $sl['stops']['containers'] ?? null, $sl['blockers'][0]['params']['names'] ?? null]);
        $GLOBALS['rs']['users'] = fn () => [[], []];
        $GLOBALS['md']['last'] = ['finished' => time() - 600, 'result' => 'ok'];
        $sp = mdPlan(['kind' => 'app', 'name' => 'dropnook', 'share' => 'appdata', 'dir' => 'drop', 'stack' => 'dropnook']);
        same('make dataset: a stopped stack - looked at again first, no stop or start steps, «start it again» afterwards',
            [[], ['md_stopped', 'md_aside', 'md_create', 'md_copy', 'md_compare', 'md_store'], 'after.md_stack_start'],
            [$sp['blockers'], array_column($sp['steps'], 'do'), $sp['after'][0]['key'] ?? null]);
        $GLOBALS['rs']['users'] = fn () => [['drop'], []];
        $jj = ['id' => 'x', 'stopped' => []];
        same('make dataset: … one of it started meanwhile - the job refuses before it changes anything', ['failed', 'md_stack_running'],
            [($x = mdDoStopped($jj, ['stack' => 'dropnook', 'paths' => ['/x']]))['state'], $x['note'] ?? null]);
        $GLOBALS['rs']['users'] = fn () => [['drop', 'drop-share'], []];
        $GLOBALS['md']['last'] = ['finished' => time() - 3 * 86400, 'result' => 'ok'];
        // a failure after the copy: rolled back - the dataset destroyed, the folder back, nothing lost
        $GLOBALS['md']['zfs'] = $zfsMap;
        foreach (["$mnt/tank/appdata/web2"] as $d) { @mkdir($d, 0755, true); }
        file_put_contents("$mnt/tank/appdata/web2/i.html", 'hi');
        $p2 = mdPlan(['kind' => 'app', 'name' => 'web2', 'share' => 'appdata', 'dir' => 'web2'], true);
        $j = rsJournalNew('20261012-150100-abcd', $p2);
        $j['id'] = '20261012-150100-abcd';
        @mkdir(rsDir($j['id']), 0700, true);
        $run('md_aside');
        $run('md_create');
        file_put_contents("$mnt/tank/appdata/web2/half", 'x');      // a copy that went wrong half-way
        $j['steps'][$at('md_copy')]['state'] = 'failed';
        mdRollback($j);
        same('make dataset: rollback - the job\'s dataset destroyed, the folder back in its place with its files, said', [true, 'hi', false, 'md_rolled_back', ['destroy', 'back']],
            [str_contains((string) file_get_contents("$tmp/zfs.log"), 'zfs destroy tank/appdata/web2'), (string) @file_get_contents("$mnt/tank/appdata/web2/i.html"),
             file_exists("$mnt/tank/appdata/web2/half"), $j['reason'] ?? null, array_column($j['rollback'] ?? [], 'what')]);
        // zfs create refused: nothing made, the folder back
        touch("$tmp/zfs.fail");
        $p3 = mdPlan(['kind' => 'app', 'name' => 'web2', 'share' => 'appdata', 'dir' => 'web2'], true);
        $j = rsJournalNew('20261012-150200-abcd', $p3);
        $j['id'] = '20261012-150200-abcd';
        @mkdir(rsDir($j['id']), 0700, true);
        $run('md_aside');
        same('make dataset: zfs create refused - failed, rolled back, the folder where it was', ['failed', 'hi'],
            [$run('md_create')['state'], (function () use (&$j) { $j['steps'][2]['state'] = 'failed'; mdRollback($j); return (string) @file_get_contents($GLOBALS['md']['mnt'] . '/tank/appdata/web2/i.html'); })()]);
    } finally {
        putenv("PATH=$oldPath");
        $GLOBALS['rs'] = $oldRs;
        $GLOBALS['md'] = $oldMd;
    }
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/restore.php');
    check('make dataset: one of Mr. Restori\'s jobs - its steps, the rollback after a failure or a stop', str_contains($src, "'md_create'  => mdDoCreate(\$j, \$s),")
        && str_contains($src, "if ((\$failed || \$GLOBALS['rsStop']) && (\$j['kind'] ?? '') === 'make_dataset') {"));
    $bjs = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('make dataset: the setup - «Why?» at a VM, an app\'s folder and a share that can\'t go alone; the dialog greys «Make it» without a fresh backup',
        str_contains($bjs, "main.appendChild(whyFold('vm:' + v.name,") && str_contains($bjs, "whyFold(`app:\${a.id}:\${f.share}/\${f.dir}`") && str_contains($bjs, "whyFold('share:' + sh.name,")
        && str_contains($bjs, "if (go) go.disabled = !ok;") && str_contains($bjs, "no_fresh_ok: !fresh && cb.checked"));
    check('make dataset 1.60.1: the job followed (the wave left of its step, n %), its result and the next step said, the setup planned anew; a stack\'s every container named',
        str_contains($bjs, "line.append(el('span', 'spin'), ' ', st ? T('dsw.step.' + st.do) : T('dsw.queued')") && str_contains($bjs, "await setupPlan(false);           // the unit a dataset of its own now")
        && str_contains($bjs, "Office.api.get({ a: 'part', desk: 'restore', part: 'job' })") && str_contains($bjs, "T('dsw.stack_members', { list: all.map("));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $bk = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/backup/lang/$l.json"), true) ?: [];
        $rs = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/restore/lang/$l.json"), true) ?: [];
        same("make dataset: $l - its words", [], array_values(array_merge(
            array_filter(['dsw.why', 'dsw.make', 'dsw.vm', 'dsw.app', 'dsw.share_split', 'dsw.delicate', 'dsw.last_old', 'dsw.no_fresh_ok', 'dsw.backup_first', 'dsw.go',
                'dsw.no.md_already', 'dsw.no.md_no_fresh_backup', 'errors.md_busy'], fn ($k) => !isset($bk[$k])),
            array_filter(['jk.make_dataset', 'step.md_create', 'ss.md_copy', 'sn.md_compare_failed', 'errors.md_rolled_back'], fn ($k) => !isset($rs[$k])))));
    }
    exec('rm -rf ' . escapeshellarg($tmp));
}

function testRestoreJobs(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-rsjob-' . getmypid();
    @mkdir("$tmp/data/unraid-backup/state", 0700, true);
    $GLOBALS['rs']['data'] = "$tmp/data/restore";
    $GLOBALS['rs']['job_file'] = "$tmp/data/restore-job.json";
    $GLOBALS['rs']['ub_data'] = "$tmp/data/unraid-backup";

    // what a dump holds: tables per database (pg_dumpall's \connect in its forms), complete lines only
    $db = null;
    $count = [];
    rsDumpCount("\\connect template1\nCREATE TABLE x (\n\\connect zztest\nCREATE TABLE public.a (\nCREATE TABLE public.b (\n"
        . "\\connect -reuse-previous=on \"dbname='o''brien'\"\nCREATE TABLE c (\n\\connect \"My \"\"DB\"\"\"\nCREATE TABLE d (\n-- CREATE TABLE not\n", $db, $count);
    same('restore: tables per database from a dump', ['template1' => 1, 'zztest' => 2, "o'brien" => 1, 'My "DB"' => 1], $count);
    file_put_contents("$tmp/d.sql.gz", gzencode(str_repeat("CREATE TABLE t (\n", 3)));
    same('restore: a .gz\'s size from its trailer', 51, rsGzSize("$tmp/d.sql.gz"));
    same('restore: tables of a dump read from the file', ['' => 3], rsDumpTables("$tmp/d.sql.gz"));

    // credentials: only variable names, only known ones; the script never carries a value
    same('restore: Postgres logs in with the package\'s variables', ['login' => 'user', 'user_var' => 'POSTGRES_USER', 'password_var' => 'POSTGRES_PASSWORD'],
        rsLogin(['type' => 'postgres', 'user_var' => 'POSTGRES_USER', 'password_var' => 'POSTGRES_PASSWORD']));
    same('restore: an unknown variable falls back to the image\'s', 'MARIADB_ROOT_PASSWORD', rsLogin(['type' => 'mariadb', 'login' => 'root', 'password_var' => 'PATH'])['password_var']);
    same('restore: MariaDB as the app\'s user', ['login' => 'user', 'user_var' => 'MARIADB_USER', 'password_var' => 'MARIADB_PASSWORD'],
        rsLogin(['type' => 'mariadb', 'login' => 'user', 'user_var' => 'MARIADB_USER', 'password_var' => 'MARIADB_PASSWORD']));
    $script = rsDbScript('dump', ['type' => 'mariadb', 'login' => 'user', 'user_var' => 'MARIADB_USER', 'password_var' => 'MARIADB_PASSWORD']);
    check('restore: the dump script names variables and takes the database as $1',
        str_contains($script, '-u"$MARIADB_USER" -p"$MARIADB_PASSWORD"') && str_contains($script, '--databases "$1"'), $script);
    check('restore: a fresh cluster is ready over TCP (not the init server on the socket), a running one on the socket',
        str_contains(rsDbScript('ready', ['type' => 'postgres', 'tcp' => true]), '-h 127.0.0.1') && !str_contains(rsDbScript('ready', ['type' => 'postgres']), '-h '));
    check('restore: a database name from the dump never goes to psql -d (a connection string there)',
        str_contains(rsDbScript('tables', ['type' => 'postgres']), 'PGDATABASE="$1"') && !str_contains(rsDbScript('tables', ['type' => 'postgres']), '-d '));
    try {
        rsDbScript('play', ['type' => 'postgres', 'user_var' => 'HOME; rm -rf /', 'password_var' => '']);
        check('restore: a variable not on the list is refused', false);
    } catch (Problem) {
        check('restore: a variable not on the list is refused', true);
    }

    // where what he replaces goes aside
    same('restore: a template aside on the flash', '/x/aside/20261006-120000/plugins/dockerMan/templates-user/my-a.xml',
        rsAsideFor('/boot/config/plugins/dockerMan/templates-user/my-a.xml', '20261006-120000', 'restored-aside', '/x/aside'));
    same('restore: a file outside the flash goes aside next to it', '/mnt/user/appdata/x/compose.yaml.restored-aside-20261006-120000',
        rsAsideFor('/mnt/user/appdata/x/compose.yaml', '20261006-120000'));
    same('restore: clean paths', [true, false, false, false, false], array_map('rsCleanPath', ['/mnt/user/a/b.env', '/mnt/user/../etc', 'rel/x', "/a/b\n", '/a//b']));
    // relative to now, so the test doesn't depend on the time of day it runs
    $recent = date('Ymd-His', time() - 60);
    $future = date('Ymd-His', time() + 3600);
    $old = date('Ymd-His', time() - 2 * 86400);
    same('restore: a stamp from the page only when it is plausible',
        [true, false, false, 15],
        [rsStampOf(['stamp' => $recent]) === $recent, rsStampOf(['stamp' => $future]) === $future,
         rsStampOf(['stamp' => $old]) === $old, strlen(rsStampOf(['stamp' => "$recent\n"]))]);

    // Kopia's list: only real ids, newest first, texts cut
    same('restore: Kopia\'s snapshots', [['abcdef0123456789abcdef0123456789', 2], ['0123456789abcdef0123456789abcdef', 1]],
        array_map(fn ($s) => [$s['id'], $s['files']], rsKopiaParse(json_encode([
            ['id' => '0123456789abcdef0123456789abcdef', 'startTime' => '2026-10-01T01:00:00Z', 'stats' => ['totalSize' => 5, 'fileCount' => 1]],
            ['id' => '../bad', 'startTime' => '2026-10-03T01:00:00Z'],
            ['id' => 'abcdef0123456789abcdef0123456789', 'startTime' => '2026-10-02T01:00:00Z', 'stats' => ['totalSize' => 7, 'fileCount' => 2], 'description' => "uso-backup\n20261002"],
        ]))));

    // templates and compose files: what differs or is missing, a compose file read elsewhere by its unique place
    @mkdir("$tmp/pkg/compose", 0700, true);
    @mkdir("$tmp/pkg/compose-files", 0700, true);
    @mkdir("$tmp/live/tpl", 0700, true);
    @mkdir("$tmp/live/cm/app", 0700, true);
    @mkdir("$tmp/live/share", 0700, true);
    file_put_contents("$tmp/pkg/my-app.xml", 'new');
    file_put_contents("$tmp/live/tpl/my-app.xml", 'old');
    file_put_contents("$tmp/pkg/compose/compose.yaml", 'same');
    file_put_contents("$tmp/live/cm/app/compose.yaml", 'same');
    file_put_contents("$tmp/pkg/compose/.env", 'A=1');
    file_put_contents("$tmp/pkg/compose-files/compose.yaml", 'indirect');
    $pkg = ['path' => "$tmp/pkg", 'templates' => ['my-app.xml'], 'containers' => [],
            'compose' => ['project' => 'app', 'dir' => 'app', 'working_dir' => "$tmp/live/share", 'config_files' => ["$tmp/live/share/compose.yaml"], 'files' => ['compose.yaml', '.env']],
            'files' => [['path' => 'compose-files/compose.yaml'], ['path' => 'compose-files/../x']]];
    $items = rsConfigItems($pkg, "$tmp/live/cm", "$tmp/live/tpl");
    same('restore: templates and compose files compared', [['template', 'differs'], ['compose', 'same'], ['compose', 'missing'], ['compose_file', 'missing']],
        array_map(fn ($i) => [$i['what'], $i['now']], $items));
    $plan = rsPlanConfigFor(['id' => 'app', 'name' => 'app'], $pkg, null, $items, '20261006-120000', "$tmp/flash");
    same('restore: what differs goes aside next to it, the same stays', ['aside', 'put', 'put', 'put'], array_column($plan['steps'], 'do'));
    same('restore: a file aside next to it', "$tmp/live/tpl/my-app.xml.restored-aside-20261006-120000", $plan['steps'][0]['to']);

    // the job's steps on a temporary folder, each with how «Put back» undoes it
    $id = '20261006-120000-ab12';
    rsPrivateDir(rsData());
    rsPrivateDir(rsDir($id));
    $live = "$tmp/live";
    file_put_contents("$live/db.sqlite", 'current');
    chmod("$live/db.sqlite", 0640);
    @mkdir("$tmp/snap/folder/sub", 0700, true);
    file_put_contents("$tmp/snap/folder/sub/f.txt", 'from the snapshot');
    @mkdir("$live/folder", 0755);
    file_put_contents("$live/folder/f.txt", 'live');
    $plan = rsPlanBase('files', 'zz', ['path' => "$live/folder"]);
    $plan['steps'] = [
        ['do' => 'aside', 'path' => "$live/db.sqlite", 'to' => "$live/db.sqlite.aside-20261006-120000", 'optional' => true],
        ['do' => 'aside', 'path' => "$live/db.sqlite-wal", 'to' => "$live/db.sqlite-wal.aside-20261006-120000", 'optional' => true],
        ['do' => 'put', 'from' => "$tmp/pkg/my-app.xml", 'to' => "$live/db.sqlite", 'mode' => 0600],
        ['do' => 'copy', 'from' => "$tmp/snap/folder", 'to' => "$live/folder.restored-20261006-120000"],
        ['do' => 'aside', 'path' => "$live/folder", 'to' => "$live/folder.aside-20261006-120000"],
        ['do' => 'move', 'from' => "$live/folder.restored-20261006-120000", 'to' => "$live/folder"],
        ['do' => 'put', 'from' => "$tmp/pkg/compose/.env", 'to' => "$live/new.env", 'mode' => 0600],
    ];
    $plan['stamp'] = '20261006-120000';
    $j = rsJournalNew($id, $plan);
    $states = [];
    foreach (array_keys($j['steps']) as $i) {
        $j['steps'][$i] = array_merge($j['steps'][$i], rsStep($j, $i));
        $states[] = $j['steps'][$i]['state'];
    }
    same('restore: the steps ran', ['ok', 'skipped', 'ok', 'ok', 'ok', 'ok', 'ok'], $states);
    clearstatcache();
    same('restore: the copy took the old one\'s mode, the old one aside', ['new', 0640, 'current'],
        [file_get_contents("$live/db.sqlite"), fileperms("$live/db.sqlite") & 0777, file_get_contents("$live/db.sqlite.aside-20261006-120000")]);
    same('restore: the folder swapped in, the live one aside', ['from the snapshot', 'live'],
        [@file_get_contents("$live/folder/sub/f.txt"), @file_get_contents("$live/folder.aside-20261006-120000/f.txt")]);
    same('restore: never over something that is there', 'exists', rsStep($j, 2)['note'] ?? null);
    $j['result'] = 'ok';
    writeAtomic(rsDir($id) . '/plan.json', jsonEncode($plan), 0600, 0, 0);
    rsJournalWrite($j);
    same('restore: what was put aside is in the journal (the missing -wal not)', ["$live/db.sqlite", "$live/folder"], array_column($j['aside'], 'from'));

    // «Put back»: from the journal, newest step first; what he restored goes aside itself
    check('restore: it can be put back', rsCanPutback($j));
    $back = rsPlanSeal(rsPlanPutback(['id' => $id], '20261006-130000'), '20261006-130000');
    same('restore: the put back\'s steps (first a look for a file held open)', ['not_open', 'aside', 'aside', 'move', 'aside', 'move'], array_column($back['steps'], 'do'));
    same('restore: nothing blocks the put back', [], $back['blockers']);
    $p = rsJournalNew('20261006-130000-cd34', $back);
    rsPrivateDir(rsDir($p['id']));
    $states = [];
    foreach (array_keys($p['steps']) as $i) {
        $p['steps'][$i] = array_merge($p['steps'][$i], rsStep($p, $i));
        $states[] = $p['steps'][$i]['state'];
    }
    same('restore: the put back ran', ['ok', 'ok', 'ok', 'ok', 'ok', 'ok'], $states);
    clearstatcache();
    same('restore: everything as before, the restored aside', ['current', 'live', 'new', 'from the snapshot', false],
        [@file_get_contents("$live/db.sqlite"), @file_get_contents("$live/folder/f.txt"), @file_get_contents("$live/db.sqlite.putback-20261006-130000"),
         @file_get_contents("$live/folder.putback-20261006-130000/sub/f.txt"), file_exists("$live/new.env")]);
    rsMarkPutback($id, $p['id'], 'ok');
    check('restore: a restore put back can\'t be put back again', !rsCanPutback(rsJournal($id)));

    // the engine's lock: his note while he holds it, the next one finds it busy, the note goes with him
    $h = rsLockTake('zz-app', 'db');
    same('restore: he holds the lock and says so', ['restore', 'zz-app'], [backupLockHolder(rsUbData())['holder'] ?? null, backupLockHolder(rsUbData())['what'] ?? null]);
    $busy = rsLockTake('other', 'db');
    same('restore: a second one finds it busy', 'restore', is_array($busy) ? $busy['holder'] : 'handle');
    same('restore: nothing starts meanwhile', 'restore_busy_restore', rsBusy()['key'] ?? null);
    rsLockRelease($h);
    same('restore: the lock and his note are gone', [null, false], [backupLockHolder(rsUbData()), is_file(rsUbData() . '/state/lock-holder.json')]);

    // a whole job as its own process (php agent.php job restore <id>), and refused while the lock is held
    $run = function (string $jid) use ($tmp): int {
        exec('OFFICE_DATA_DIR=' . escapeshellarg("$tmp/data") . ' ' . escapeshellarg(PHP_BINARY) . ' ' . escapeshellarg(OFFICE_DIR . '/agent/agent.php')
            . ' job restore ' . escapeshellarg($jid) . ' 2>&1', $out, $code);
        return $code;
    };
    file_put_contents("$live/one.txt", 'one');
    $plan = rsPlanBase('config', 'zz-job', ['app' => 'zz']);
    $plan['stamp'] = '20261006-140000';
    $plan['steps'] = [['do' => 'aside', 'path' => "$live/one.txt", 'to' => "$live/one.txt.aside-20261006-140000"], ['do' => 'put', 'from' => "$tmp/pkg/my-app.xml", 'to' => "$live/one.txt"]];
    $jid = rsLaunch($plan, false);
    same('restore: a job runs on its own', [0, 'ok', 'new', 'one', false], [$run($jid), rsJournal($jid)['result'] ?? null, @file_get_contents("$live/one.txt"),
        @file_get_contents("$live/one.txt.aside-20261006-140000"), is_file(rsUbData() . '/state/lock-holder.json')]);
    same('restore: a job runs once', 1, $run($jid));
    $h = rsLockTake('someone', 'test');
    $plan['steps'] = [['do' => 'aside', 'path' => "$live/one.txt", 'to' => "$live/one.txt.aside-20261006-150000"]];
    $plan['stamp'] = '20261006-150000';
    $jid = rsLaunch($plan, false);
    same('restore: refused while the lock is held — untouched, exit 75', [75, 'refused', 'restore_busy_restore', true],
        [$run($jid), rsJournal($jid)['result'] ?? null, rsJournal($jid)['reason'] ?? null, is_file("$live/one.txt")]);
    rsLockRelease($h);

    // a journal whose job is gone was interrupted; the Dashboard shows a restore only while its heartbeat is fresh
    $k = rsJournalNew('20261006-160000-ef56', $plan);
    rsPrivateDir(rsDir($k['id']));
    $k['result'] = 'running';
    $k['pid'] = 4194305;
    rsJournalWrite($k, false);
    $rows = array_column(rsJournals(), 'result', 'id');
    same('restore: a job that died is interrupted', 'interrupted', $rows[$k['id']] ?? null);
    require_once OFFICE_DIR . '/src/dashboard.php';
    same('dashboard: Mr. Restori while he restores', [true, false, false],
        [officeDashRestoring(['result' => 'running', 'what' => 'x', 'heartbeat' => 1000], 1100), officeDashRestoring(['result' => 'running', 'what' => 'x', 'heartbeat' => 1000], 2000),
         officeDashRestoring(['result' => 'ok', 'what' => 'x', 'heartbeat' => 1000], 1010)]);

    unset($GLOBALS['rs']['data'], $GLOBALS['rs']['job_file'], $GLOBALS['rs']['ub_data']);
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Mr. Restori and a share on several pools and disks (like drop: primary hazel, secondary moss, an array disk):
 * moments across the parts (the engine's run on all, a manual snapshot on two, a plan's on one), never a moment
 * whose parts hold nothing by default, the union of the parts as the source (primary first), a ZFS dataset of its
 * own at the top of a share from its own snapshots, targets on the share (/mnt/user/<share>/…, never the pool),
 * a whole share entry by entry with what binds it stopping, the swap run and put back, a part with content a
 * moment doesn't cover, a missing share (its old settings as information only), an empty one (straight in), too
 * many entries, a share's settings in words, where Unraid places it and how much room is there. All in a
 * temporary folder: pools as folders, /mnt/user/<share> as a link to its pool (like an exclusive share).
 */
function testRestoreShares(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-rsshare-' . getmypid();
    $mnt = "$tmp/mnt";
    @mkdir("$tmp/data/unraid-backup/state", 0700, true);
    $GLOBALS['rs']['data'] = "$tmp/data/restore";
    $GLOBALS['rs']['job_file'] = "$tmp/data/restore-job.json";
    $GLOBALS['rs']['ub_data'] = "$tmp/data/unraid-backup";
    $GLOBALS['rs']['sizes_file'] = "$tmp/data/restore-sizes.json";
    // what stops: the container that binds the whole share (only asked for with roots, as for a whole share)
    $GLOBALS['rs']['users'] = fn (array $paths, array $roots): array => [$roots ? ['zz-drop'] : [], $roots ? [] : ['zz-drop']];
    $put = function (string $file, ?string $text = null): void {
        @mkdir($text === null ? $file : dirname($file), 0755, true);
        if ($text !== null) {
            file_put_contents($file, $text);
        }
    };
    $snap = fn (string $pool, string $name, string $share = 'zzdrop'): string => "$mnt/$pool/$share/.zfs/snapshot/$name";
    $T0 = (int) strtotime('2026-10-06 01:16');
    $T1 = (int) strtotime('2026-10-06 14:59');
    $T2 = (int) strtotime('2026-10-06 15:00');
    $Th = (int) strtotime('2026-10-05 12:00');
    // live: the data on hazel, moss's part empty, the array disk's empty
    $put("$mnt/hazel/zzdrop/files");
    $put("$mnt/hazel/zzdrop/texts/t1.txt", 'live text');
    $put("$mnt/hazel/zzdrop/shares/a/x", 'live x');
    $put("$mnt/moss/zzdrop");
    $put("$mnt/disk1/zzdrop");
    // snapshots: the engine's run on all three, a manual one on hazel and moss, a plan's on moss only, one on hazel only
    $put($snap('hazel', 'hazel-only') . '/files/h.png', 'h');
    $put($snap('hazel', 'hazel-only') . '/texts/t1.txt', 'hazel-only text');
    $put($snap('hazel', 'unraidbackup-20261006-0100') . '/files/f0.png', 'png0');
    $put($snap('hazel', 'manual-x') . '/files/f1.png', 'png1');
    $put($snap('hazel', 'manual-x') . '/texts/t1.txt', 'old text');
    $put($snap('hazel', 'manual-x') . '/shares');                       // a dataset of its own: empty in its parent's snapshot
    $put($snap('hazel', 'manual-x') . '/.thumbs/t', 'thumb');
    $put($snap('hazel', 'manual-x') . '/files.restored-20261006-150008/old', 'mine');   // what he left himself: not listed
    $put("$mnt/hazel/zzdrop/shares/.zfs/snapshot/manual-x/a/x", 'snap x');
    $put($snap('moss', 'unraidbackup-20261006-0100') . '/files/m0.png', 'm0');
    $put($snap('moss', 'manual-x'));
    $put($snap('moss', 'uso-plan-test-20261006-1500'));
    $put("$mnt/disk1/.btrfs-snap/20261006-0100/zzdrop/files/d1.png", 'd1');
    // the share's settings as the last run packed them (a share that is gone now)
    $put("$tmp/pkg/server/shares/zzgone.cfg", "shareUseCache=\"prefer\"\nshareCachePool=\"hazel\"\nshareCachePool2=\"zzpool2\"\nshareAllocator=\"mostfree\"\n"
        . "shareSplitLevel=\"1\"\nshareFloor=\"2000\"\nshareExport=\"eh\"\nshareSecurity=\"private\"\nshareExportNFS=\"-\"\n");
    // an empty share on hazel only, and one with too much at its top
    $put("$mnt/hazel/zzempty");
    $put($snap('hazel', 'manual-e', 'zzempty') . '/data/d.txt', 'd');
    for ($i = 0; $i <= RS_ENTRIES_MAX; $i++) {
        $put($snap('hazel', 'manual-m', 'zzmany') . "/f$i");
    }
    $put("$mnt/user");
    foreach (['zzdrop', 'zzempty', 'zzmany'] as $s) {
        symlink("$mnt/hazel/$s", "$mnt/user/$s");
    }
    $ctx = [
        'fs' => ['hazel' => 'zfs', 'moss' => 'zfs', 'disk1' => 'btrfs'],
        'zfs' => ["$mnt/hazel/zzdrop" => 'zz-hazel/zzdrop', "$mnt/moss/zzdrop" => 'zz-moss/zzdrop', "$mnt/hazel/zzdrop/shares" => 'zz-hazel/zzdrop/shares',
                  "$mnt/hazel/zzempty" => 'zz-hazel/zzempty', "$mnt/hazel/zzmany" => 'zz-hazel/zzmany'],
        'snaps' => ['zz-hazel/zzdrop' => [['name' => 'hazel-only', 'time' => $Th], ['name' => 'unraidbackup-20261006-0100', 'time' => $T0], ['name' => 'manual-x', 'time' => $T1]],
                    'zz-moss/zzdrop' => [['name' => 'unraidbackup-20261006-0100', 'time' => $T0 + 60], ['name' => 'manual-x', 'time' => $T1], ['name' => 'uso-plan-test-20261006-1500', 'time' => $T2]],
                    'zz-hazel/zzdrop/shares' => [['name' => 'manual-x', 'time' => $T1]],
                    'zz-hazel/zzempty' => [['name' => 'manual-e', 'time' => $T1]], 'zz-hazel/zzmany' => [['name' => 'manual-m', 'time' => $T1]]],
        // disk1 still holds a part of it (the engine noted it at the setup): the array is no storage of the share any more
        'asleep' => [], 'prefixes' => ['uso-backup-', 'unraidbackup-'], 'btrfs_dir' => '.btrfs-snap', 'settings' => ['share|zzdrop' => ['locations' => ['hazel, moss, disk1']]],
        'cfg' => ['zzdrop' => ['shareUseCache' => 'prefer', 'shareCachePool' => 'hazel', 'shareCachePool2' => 'moss', 'shareFloor' => '1000'],
                  'zzempty' => ['shareUseCache' => 'only', 'shareCachePool' => 'hazel'], 'zzmany' => ['shareUseCache' => 'only', 'shareCachePool' => 'hazel'], 'zzgone' => []],
        'mnt' => $mnt, 'user' => "$mnt/user",
        'disks' => ['hazel' => ['name' => 'hazel', 'fsFree' => '1000000'], 'moss' => ['name' => 'moss', 'fsFree' => '500000'], 'disk1' => ['name' => 'disk1', 'fsFree' => '7']],
        'shares_ini' => ['zzdrop' => ['exclusive' => 'no'], 'zzempty' => ['exclusive' => 'yes'], 'zzmany' => ['exclusive' => 'yes']],
        'old_shares' => "$tmp/pkg/server/shares", 'now' => [],
    ];
    $owner = ['kind' => 'app', 'name' => 'zz', 'id' => 'zz', 'vm_state' => null];
    $stamp = '20261006-160000';
    $c = $ctx;

    // moments: by run (the engine's, on every part — ZFS and btrfs alike) or by name; newest first; which parts each covers
    $m = rsMoments(rsLocate('/mnt/user/zzdrop', $c));
    same('restore shares: moments across the parts, newest first', [
            ['name:uso-plan-test-20261006-1500', ['moss']], ['name:manual-x', ['hazel', 'moss']],
            ['run:20261006-0100', ['hazel', 'moss', 'disk1']], ['name:hazel-only', ['hazel']]],
        array_map(fn ($x) => [$x['id'], array_keys($x['parts'])], $m));
    same('restore shares: the engine\'s run named by its ZFS snapshot, the newest part\'s time', ['unraidbackup-20261006-0100', $T0 + 60, true],
        [$m[2]['name'], $m[2]['time'], $m[2]['ours']]);
    rsMomentHolds($m, true);
    same('restore shares: which parts hold anything', [[], ['hazel'], ['hazel', 'moss', 'disk1'], ['hazel']], array_column($m, 'holds'));

    // a whole share: the default moment holds something (not the plan's empty one on moss), its entries, copy by default
    $p = rsPlanFilesFor('/mnt/user/zzdrop', '', '', false, $owner, $stamp, $c);
    same('restore shares: the default moment is never one whose parts hold nothing', 'name:manual-x', $p['target']['snap']);
    same('restore shares: the moment\'s parts', [['hazel', true, true], ['moss', true, false], ['disk1', false, false]],
        array_map(fn ($x) => [$x['base'], $x['covered'], $x['holds']], $p['moment']['parts']));
    same('restore shares: entries at its top (his own leftovers not)', ['.thumbs', 'files', 'shares', 'texts'], array_column($p['options']['entries'], 'name'));
    same('restore shares: data there, so copy by default', ['copy', []], [$p['target']['mode'], $p['blockers']]);
    same('restore shares: copies go onto the share, not the pool', ["$mnt/user/zzdrop/.thumbs.restored-$stamp", "$mnt/user/zzdrop/files.restored-$stamp",
            "$mnt/user/zzdrop/shares.restored-$stamp", "$mnt/user/zzdrop/texts.restored-$stamp"],
        array_column($p['steps'], 'to'));
    same('restore shares: a dataset of its own comes from its own snapshot', ["$mnt/hazel/zzdrop/shares/.zfs/snapshot/manual-x"], $p['steps'][2]['sources']);
    $notes = array_column($p['notes'], 'key');
    check('restore shares: Unraid places it by the share\'s settings', in_array('note.files_place2', $notes, true), json_encode($notes));
    $place = array_values(array_filter($p['notes'], fn ($n) => $n['key'] === 'note.files_place2'))[0]['params'] ?? [];
    same('restore shares: primary and secondary storage', ['/mnt/user/zzdrop', 'hazel', 'moss'], [$place['path'] ?? null, $place['primary'] ?? null, $place['secondary'] ?? null]);

    // chosen entries, swapped: copies first, what binds the whole share stops, each aside through the share, the copy in place
    $c = $ctx;
    $p = rsPlanFilesFor('/mnt/user/zzdrop', 'name:manual-x', 'swap', false, $owner, $stamp, $c, ['texts', 'files', 'nope']);
    same('restore shares: only chosen entries that are there, in their order', ['files', 'texts'], $p['target']['items']);
    same('restore shares: the swap\'s steps', ['copy', 'copy', 'not_open', 'stop', 'aside', 'move', 'aside', 'move', 'start'], array_column($p['steps'], 'do'));
    same('restore shares: what binds the share stops', [['zz-drop'], ['zz-drop']], [$p['steps'][3]['containers'], $p['stops']]);
    same('restore shares: aside on the share', ["$mnt/user/zzdrop/files" => "$mnt/user/zzdrop/files.aside-$stamp", "$mnt/user/zzdrop/texts" => "$mnt/user/zzdrop/texts.aside-$stamp"],
        array_column($p['aside'], 'to', 'from'));
    same('restore shares: nothing blocks it', [], $p['blockers']);
    $c = $ctx;
    $q = rsPlanFilesFor('/mnt/user/zzdrop', 'name:manual-x', 'swap', false, $owner, $stamp, $c, ['shares']);
    same('restore shares: a dataset of its own whose mountpoint isn\'t inherited is not swapped', ['restore_swap_mountpoint'], array_column($q['blockers'], 'key'));
    $c = $ctx;
    same('restore shares: nothing chosen', ['restore_nothing_chosen'], array_column(rsPlanFilesFor('/mnt/user/zzdrop', 'name:manual-x', 'swap', false, $owner, $stamp, $c, [])['blockers'], 'key'));

    // the swap runs on the folders, then «Put back» brings back what was there
    $id = "$stamp-ab12";
    rsPrivateDir(rsData());
    rsPrivateDir(rsDir($id));
    $p['stamp'] = $stamp;
    $j = rsJournalNew($id, $p);
    $states = [];
    foreach (array_keys($j['steps']) as $i) {
        $j['steps'][$i] = array_merge($j['steps'][$i], rsStep($j, $i));
        $states[] = $j['steps'][$i]['state'];
    }
    same('restore shares: the swap ran', array_fill(0, 9, 'ok'), $states);
    clearstatcache();
    same('restore shares: the snapshot\'s state in place, the live one aside', ['png1', 'old text', 'live text'],
        [@file_get_contents("$mnt/hazel/zzdrop/files/f1.png"), @file_get_contents("$mnt/hazel/zzdrop/texts/t1.txt"), @file_get_contents("$mnt/hazel/zzdrop/texts.aside-$stamp/t1.txt")]);
    $j['result'] = 'ok';
    writeAtomic(rsDir($id) . '/plan.json', jsonEncode($p), 0600, 0, 0);
    rsJournalWrite($j);
    $back = rsPlanSeal(rsPlanPutback(['id' => $id], '20261006-170000'), '20261006-170000');
    same('restore shares: the put back\'s steps', [['not_open', 'stop', 'aside', 'move', 'aside', 'move', 'start'], []], [array_column($back['steps'], 'do'), $back['blockers']]);
    $pb = rsJournalNew('20261006-170000-cd34', $back);
    rsPrivateDir(rsDir($pb['id']));
    $states = [];
    foreach (array_keys($pb['steps']) as $i) {
        $pb['steps'][$i] = array_merge($pb['steps'][$i], rsStep($pb, $i));
        $states[] = $pb['steps'][$i]['state'];
    }
    clearstatcache();
    same('restore shares: put back — as before, the restored state aside', [array_fill(0, 7, 'ok'), 'live text', false, 'old text', 'png1'],
        [$states, @file_get_contents("$mnt/hazel/zzdrop/texts/t1.txt"), file_exists("$mnt/hazel/zzdrop/files/f1.png"),
         @file_get_contents("$mnt/hazel/zzdrop/texts.putback-20261006-170000/t1.txt"), @file_get_contents("$mnt/hazel/zzdrop/files.putback-20261006-170000/f1.png")]);

    // one folder from the engine's run: the union of its parts (primary first), copied together
    $c = $ctx;
    $p = rsPlanFilesFor('/mnt/user/zzdrop/files', 'run:20261006-0100', 'copy', false, $owner, $stamp, $c);
    same('restore shares: the union of the parts, primary storage first', [$snap('hazel', 'unraidbackup-20261006-0100') . '/files', $snap('moss', 'unraidbackup-20261006-0100') . '/files',
            "$mnt/disk1/.btrfs-snap/20261006-0100/zzdrop/files"], $p['steps'][0]['sources'] ?? null);
    $union = array_values(array_filter($p['notes'], fn ($n) => $n['key'] === 'note.files_union'))[0]['params']['bases'] ?? null;
    same('restore shares: said so', 'hazel + moss + disk1', $union);
    $j = rsJournalNew("$stamp-ef56", $p);
    rsPrivateDir(rsDir($j['id']));
    $r = rsStep($j, 0);
    same('restore shares: the copy holds every part', ['ok', 'png0', 'm0', 'd1'], [$r['state'], @file_get_contents("$mnt/user/zzdrop/files.restored-$stamp/f0.png"),
        @file_get_contents("$mnt/user/zzdrop/files.restored-$stamp/m0.png"), @file_get_contents("$mnt/user/zzdrop/files.restored-$stamp/d1.png")]);
    $c = $ctx;
    same('restore shares: never over a copy that is there', ['restore_exists'], array_column(rsPlanFilesFor('/mnt/user/zzdrop/files', 'run:20261006-0100', 'copy', false, $owner, $stamp, $c)['blockers'], 'key'));

    // a part with content now that the moment doesn't cover: said so (warning); a moment that holds nothing of it is refused
    $put("$mnt/moss/zzdrop/texts/m.txt", 'on moss');
    $stamp = '20261006-161000';
    $c = $ctx;
    $p = rsPlanFilesFor('/mnt/user/zzdrop/texts', 'name:hazel-only', 'swap', false, $owner, $stamp, $c);
    $un = array_values(array_filter($p['notes'], fn ($n) => $n['key'] === 'note.files_uncovered'))[0] ?? [];
    same('restore shares: a part with content the moment doesn\'t cover', ['moss', 'texts', true], [$un['params']['bases'] ?? null, $un['params']['names'] ?? null, $un['warn'] ?? null]);
    $c = $ctx;
    same('restore shares: a moment that holds nothing of it', ['restore_not_in_snapshot'],
        array_column(rsPlanFilesFor('/mnt/user/zzdrop/texts', 'name:uso-plan-test-20261006-1500', 'copy', false, $owner, $stamp, $c)['blockers'], 'key'));
    $c = $ctx;
    $c['asleep'] = ['moss' => true];
    same('restore shares: a part asleep — through /mnt/user only with «wake»', ['restore_asleep'],
        array_column(rsPlanFilesFor('/mnt/user/zzdrop/texts', 'name:manual-x', 'copy', false, $owner, $stamp, $c)['blockers'], 'key'));
    $c = $ctx;
    $c['asleep'] = ['hazel' => true];
    $p = rsPlanFilesFor('/mnt/user/zzdrop', '', '', false, $owner, $stamp, $c);
    same('restore shares: the part holding the data asleep — «wake», never "nothing there"', [['restore_asleep'], ['hazel'], ['moss', 'disk1']],
        [array_column($p['blockers'], 'key'), $p['options']['asleep'], array_values(array_unique(array_merge(...array_column($p['options']['moments'], 'bases'))))]);
    $c = $ctx;
    $c['asleep'] = ['hazel' => true];
    $p = rsPlanFilesFor('/mnt/user/zzdrop', '', '', true, $owner, $stamp, $c);
    same('restore shares: with «wake» it is looked into', ['name:manual-x', []], [$p['target']['snap'], array_column($p['blockers'], 'key')]);

    // «wake» really wakes the sleeping parts first (a block read from each of their disks, waited for), only those, only when ticked
    $woke = [];
    $GLOBALS['rs']['wake_run'] = function (array $commands) use (&$woke): array {
        $woke[] = $commands;
        return array_map(fn ($cmd) => [0, '', ''], $commands);
    };
    $disks = ['hazel' => ['name' => 'hazel', 'device' => 'null', 'spundown' => '1', 'fsFree' => '1000000'], 'hazel2' => ['name' => 'hazel2', 'device' => 'null', 'spundown' => '0'],
              'moss' => ['name' => 'moss', 'device' => 'null', 'spundown' => '0', 'fsFree' => '500000'], 'disk1' => ['name' => 'disk1', 'device' => 'null', 'fsFree' => '7']];
    $c = $ctx;
    $c['disks'] = $disks;
    $c['asleep'] = ['hazel' => true, 'hazel2' => false, 'moss' => false];
    $p = rsPlanFilesFor('/mnt/user/zzdrop', '', '', false, $owner, $stamp, $c);
    same('restore shares: without «wake» no disk is woken', [[], ['restore_asleep']], [$woke, array_column($p['blockers'], 'key')]);
    $c = $ctx;
    $c['disks'] = $disks;
    $c['asleep'] = ['hazel' => true, 'hazel2' => false, 'moss' => false];
    $p = rsPlanFilesFor('/mnt/user/zzdrop', '', 'swap', true, $owner, $stamp, $c, ['files', 'texts']);
    same('restore shares: «wake» wakes every disk of the sleeping pool, nothing else', [['hazel', 'hazel2']], array_map('array_keys', $woke));
    same('restore shares: the dd read of one block', ['dd', 'if=/dev/null', 'of=/dev/null', 'bs=4096', 'count=1', 'iflag=direct'], $woke[0]['hazel'] ?? null);
    same('restore shares: woken, then its moments and the choices kept', [['woken' => ['hazel'], 'failed' => []], [], ['hazel'], 'name:manual-x', ['files', 'texts'], 'swap', []],
        [$p['woke'], $p['options']['asleep'], $p['options']['woken'], $p['target']['snap'], $p['target']['items'], $p['target']['mode'], array_column($p['blockers'], 'key')]);
    $woke = [];
    $GLOBALS['rs']['wake_run'] = function (array $commands) use (&$woke): array {
        $woke[] = $commands;
        return array_map(fn ($cmd) => [1, '', 'timeout'], $commands);
    };
    $c = $ctx;
    $c['disks'] = $disks;
    $c['asleep'] = ['hazel' => true, 'hazel2' => false, 'moss' => false];
    $p = rsPlanFilesFor('/mnt/user/zzdrop', '', '', true, $owner, $stamp, $c);
    same('restore shares: a disk that doesn\'t answer stays asleep — said so, never read', [['woken' => [], 'failed' => ['hazel']], ['hazel'], ['restore_wake_failed'], ['moss', 'disk1']],
        [$p['woke'], $p['options']['asleep'], array_column($p['blockers'], 'key'), array_values(array_unique(array_merge(...array_column($p['options']['moments'], 'bases'))))]);
    unset($GLOBALS['rs']['wake_run']);
    $c = $ctx;
    same('restore shares: the entries chosen stay when copy is chosen instead', [['files', 'texts'], 'copy'],
        (fn ($p) => [$p['target']['items'], $p['target']['mode']])(rsPlanFilesFor('/mnt/user/zzdrop', 'name:manual-x', 'copy', false, $owner, $stamp, $c, ['texts', 'files'])));
    $c = $ctx;
    $c['fs']['disk2'] = 'xfs';
    $bases = fn (array $cfg) => (function () use ($c, $cfg) { $c['cfg']['zz'] = $cfg; return rsShareBases('zz', $c); })();
    same('restore shares: the array is a part only as primary or secondary storage', [['hazel', 'moss'], ['hazel', 'disk1', 'disk2'], ['disk1', 'disk2'], ['hazel']],
        [$bases(['shareUseCache' => 'prefer', 'shareCachePool' => 'hazel', 'shareCachePool2' => 'moss']), $bases(['shareUseCache' => 'yes', 'shareCachePool' => 'hazel']),
         $bases(['shareUseCache' => 'no', 'shareCachePool' => 'hazel']), $bases(['shareUseCache' => 'only', 'shareCachePool' => 'hazel'])]);

    // a share that is gone: never created here — its old settings as information, pools this server lacks named
    $c = $ctx;
    $p = rsPlanFilesFor('/mnt/user/zzgone/x', '', '', false, $owner, $stamp, $c);
    $old = $p['share_now']['old'] ?? [];
    same('restore shares: a missing share blocks, with its old settings', [['restore_share_missing'], 'missing', 'hazel', 'zzpool2', 'to_primary', ['zzpool2']],
        [array_column($p['blockers'], 'key'), $p['share_now']['state'], $old['primary'] ?? null, $old['secondary'] ?? null, $old['mover'] ?? null, $old['missing_pools'] ?? null]);
    same('restore shares: the old settings in words', ['mostfree', '1', 2048000, 'hidden', 'private', 'no'],
        [$old['allocator'] ?? null, $old['split'] ?? null, $old['floor'] ?? null, $old['smb'] ?? null, $old['security'] ?? null, $old['nfs'] ?? null]);

    // an empty share: straight in — nothing to put aside, «put in place» by default
    $c = $ctx;
    $p = rsPlanFilesFor('/mnt/user/zzempty', '', '', false, $owner, $stamp, $c);
    same('restore shares: an empty share is filled straight in', ['empty', 'swap', ['copy', 'not_open', 'stop', 'move', 'start'], [], 'after.files_place'],
        [$p['share_now']['state'], $p['target']['mode'], array_column($p['steps'], 'do'), $p['aside'], $p['after'][0]['key'] ?? null]);
    check('restore shares: and says so', in_array('note.files_share_empty', array_column($p['notes'], 'key'), true));
    same('restore shares: an exclusive share is placed on its pool only', ['note.files_place', 'hazel'],
        [array_values(array_filter($p['notes'], fn ($n) => str_starts_with($n['key'], 'note.files_place')))[0]['key'] ?? null,
         array_values(array_filter($p['notes'], fn ($n) => str_starts_with($n['key'], 'note.files_place')))[0]['params']['primary'] ?? null]);
    $c = $ctx;
    same('restore shares: too much at the top of a share', [['restore_too_many'], RS_ENTRIES_MAX + 1],
        [array_column(rsPlanFilesFor('/mnt/user/zzmany', '', '', false, $owner, $stamp, $c)['blockers'], 'key'),
         rsPlanFilesFor('/mnt/user/zzmany', '', '', false, $owner, $stamp, $c)['blockers'][0]['params']['n'] ?? null]);

    // the shares an app needs, as they are; settings in words; where Unraid puts it and how much room
    $c = $ctx;
    same('restore shares: the shares as they are', ['data', 'empty', 'missing'], [rsShareNow('zzdrop', $c)['state'], rsShareNow('zzempty', $c)['state'], rsShareNow('zzgone', $c)['state']]);
    $s = fn (array $cfg) => array_intersect_key(rsShareSettings($cfg, $ctx), array_flip(['primary', 'secondary', 'mover']));
    same('restore shares: primary and secondary storage from the cfg', [
            ['primary' => 'array', 'secondary' => null, 'mover' => null], ['primary' => 'hazel', 'secondary' => null, 'mover' => null],
            ['primary' => 'hazel', 'secondary' => 'array', 'mover' => 'to_secondary'], ['primary' => 'cache', 'secondary' => 'moss', 'mover' => 'to_primary']],
        [$s([]), $s(['shareUseCache' => 'only', 'shareCachePool' => 'hazel']), $s(['shareUseCache' => 'yes', 'shareCachePool' => 'hazel']),
         $s(['shareUseCache' => 'prefer', 'shareCachePool2' => 'moss'])]);
    same('restore shares: odd values are not taken', ['array', 'no', 'public'],
        array_values(array_intersect_key(rsShareSettings(['shareUseCache' => 'x;y', 'shareSecurity' => '<b>', 'shareExport' => 'e;rm'], $ctx), array_flip(['primary', 'security', 'smb']))));
    $c = $ctx;
    same('restore shares: room on primary and secondary, less the minimum free space', ['hazel', 'moss', 999000 * 1024, 499000 * 1024, 1498000 * 1024],
        array_values(rsShareSpace('zzdrop', $c)));

    unset($GLOBALS['rs']['data'], $GLOBALS['rs']['job_file'], $GLOBALS['rs']['ub_data'], $GLOBALS['rs']['sizes_file'], $GLOBALS['rs']['users']);
    $GLOBALS['rs']['du'] = ['queue' => [], 'running' => []];
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Mr. Restori and a Nextcloud restored from the engine's snapshot (the end-to-end test of 2026-10-11 on a large server:
 * the restored Nextcloud answered «maintenance» to every request): where its config.php lies on the host (the official
 * image, a bind of its own for config, linuxserver's), which restore brings it back (its config folder in what comes
 * back, the engine's moment, swapped — not a copy, not another app's folder, not another snapshot), the plan's step
 * after the containers' start and its note, and the step itself on a stand-in docker: occ as Nextcloud's user while the
 * container runs, a warning naming the command when it doesn't run or occ refuses — never failed.
 */
function testRestoreNextcloud(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-rsnc-' . getmypid();
    $mnt = "$tmp/mnt";
    $ctx0 = ['fs' => ['hazel' => 'zfs']];
    $b = fn (string $src, string $dest) => ['source' => $src, 'dest' => $dest, 'rw' => true];
    same('restore nextcloud: config.php beside occ, through the deepest bind, as the share path', [
            '/mnt/user/zzapps/zz-nc/config', '/mnt/user/zzapps/zz-ncconf', '/mnt/user/zzapps/zz-lsio/www/nextcloud/config',
            '/mnt/user/zzapps/zz-lsio/www/nextcloud/config', null, null],
        [rsNcConfigDir('/var/www/html/occ', [$b('/mnt/user/zzapps/zz-nc', '/var/www/html'), $b('/mnt/user/zzdata', '/var/www/html/data')], $ctx0),
         rsNcConfigDir('/var/www/html/occ', [$b('/mnt/user/zzapps/zz-nc', '/var/www/html'), $b('/mnt/hazel/zzapps/zz-ncconf/', '/var/www/html/config')], $ctx0),
         rsNcConfigDir('/app/www/public/occ', [$b('/mnt/user/zzapps/zz-lsio', '/config')], $ctx0),
         rsNcConfigDir('/config/www/nextcloud/occ', [$b('/mnt/user/zzapps/zz-lsio', '/config')], $ctx0),
         rsNcConfigDir('/var/www/html/occ', [$b('/mnt/user/zzdata', '/var/www/html/data')], $ctx0),
         rsNcConfigDir('/var/www/html/occ', [$b('/var/lib/docker/volumes/nc/_data', '/var/www/html')], $ctx0)]);
    $ncs = [['container' => 'zz-nc-app', 'occ' => '/var/www/html/occ', 'user' => 'www-data', 'same_as' => '', 'config' => '/mnt/user/zzapps/zz-nc/config'],
            ['container' => 'zz-nc-cron', 'occ' => '/var/www/html/occ', 'user' => 'www-data', 'same_as' => 'zz-nc-app', 'config' => '/mnt/user/zzapps/zz-nc/config']];
    same('restore nextcloud: brought back with its folder or its whole share — once per instance, never a neighbour\'s',
        [['zz-nc-app'], ['zz-nc-app'], [], [], ['zz-nc-cron']],
        [array_column(rsNcBack($ncs, ['/mnt/user/zzapps/zz-nc']), 'container'), array_column(rsNcBack($ncs, ['/mnt/user/zzapps']), 'container'),
         array_column(rsNcBack($ncs, ['/mnt/user/zzapps/zz-nc-old', '/mnt/user/zzapps/zz-other']), 'container'),
         array_column(rsNcBack([['container' => 'x', 'config' => null]], ['/mnt/user/zzapps']), 'container'),
         array_column(rsNcBack([$ncs[1]], ['/mnt/user/zzapps/zz-nc']), 'container')]);

    // the plan: a share zzapps on hazel (an exclusive share: /mnt/user/zzapps is the link), the Nextcloud's folder and another app's
    @mkdir("$tmp/data/unraid-backup/state", 0700, true);
    $GLOBALS['rs']['data'] = "$tmp/data/restore";
    $GLOBALS['rs']['job_file'] = "$tmp/data/restore-job.json";
    $GLOBALS['rs']['ub_data'] = "$tmp/data/unraid-backup";
    $GLOBALS['rs']['sizes_file'] = "$tmp/data/restore-sizes.json";
    $GLOBALS['rs']['users'] = fn (array $paths, array $roots): array => [str_contains(implode(' ', $paths), 'zz-nc') ? ['zz-nc-db', 'zz-nc-app'] : ['zz-other'], []];
    $put = function (string $file, ?string $text = null): void {
        @mkdir($text === null ? $file : dirname($file), 0755, true);
        if ($text !== null) {
            file_put_contents($file, $text);
        }
    };
    $snap = fn (string $name): string => "$mnt/hazel/zzapps/.zfs/snapshot/$name";
    $put("$mnt/hazel/zzapps/zz-nc/config/config.php", "<?php \$CONFIG = ['maintenance' => false];");
    $put("$mnt/hazel/zzapps/zz-other/x.txt", 'live');
    $put($snap('uso-backup-20261011-0300') . '/zz-nc/config/config.php', "<?php \$CONFIG = ['maintenance' => true];");
    $put($snap('uso-backup-20261011-0300') . '/zz-other/x.txt', 'snap');
    $put($snap('manual-y') . '/zz-nc/config/config.php', "<?php \$CONFIG = ['maintenance' => false];");
    $put("$mnt/user");
    symlink("$mnt/hazel/zzapps", "$mnt/user/zzapps");
    $T0 = (int) strtotime('2026-10-11 03:00');
    $ctx = [
        'fs' => ['hazel' => 'zfs'], 'zfs' => ["$mnt/hazel/zzapps" => 'zz-hazel/zzapps'],
        'snaps' => ['zz-hazel/zzapps' => [['name' => 'uso-backup-20261011-0300', 'time' => $T0], ['name' => 'manual-y', 'time' => $T0 + 3600]]],
        'asleep' => [], 'prefixes' => ['uso-backup-', 'unraidbackup-'], 'btrfs_dir' => '.btrfs-snap', 'settings' => [],
        'cfg' => ['zzapps' => ['shareUseCache' => 'only', 'shareCachePool' => 'hazel']],
        'mnt' => $mnt, 'user' => "$mnt/user", 'disks' => ['hazel' => ['name' => 'hazel', 'fsFree' => '1000000']],
        'shares_ini' => ['zzapps' => ['exclusive' => 'yes']], 'old_shares' => null, 'now' => [],
    ];
    $owner = ['kind' => 'app', 'name' => 'zz-nc', 'id' => 'zz-nc', 'vm_state' => null, 'nextcloud' => $ncs];
    $other = ['kind' => 'app', 'name' => 'zz-other', 'id' => 'zz-other', 'vm_state' => null, 'nextcloud' => []];
    $stamp = '20261011-120000';
    $plan = function (string $path, string $moment, string $mode, array $who) use ($ctx, $stamp): array {
        $c = $ctx;
        return rsPlanFilesFor($path, $moment, $mode, false, $who, $stamp, $c);
    };
    $p = $plan('/mnt/user/zzapps/zz-nc', 'run:20261011-0300', 'swap', $owner);
    same('restore nextcloud: swapped from the engine\'s snapshot — maintenance off after the containers\' start, nothing blocks',
        [['copy', 'not_open', 'stop', 'aside', 'move', 'start', 'maintenance_off'], [], ['container' => 'zz-nc-app', 'occ' => '/var/www/html/occ', 'user' => 'www-data']],
        [array_column($p['steps'], 'do'), array_column($p['blockers'], 'key'), array_intersect_key(end($p['steps']), array_flip(['container', 'occ', 'user']))]);
    same('restore nextcloud: said under «Afterwards», with the command', ['after.files_swap', 'after.nextcloud_maintenance', 'zz-nc-app', 'www-data', '/var/www/html/occ'],
        [$p['after'][0]['key'] ?? null, $p['after'][1]['key'] ?? null, $p['after'][1]['params']['container'] ?? null, $p['after'][1]['params']['user'] ?? null,
         $p['after'][1]['params']['occ'] ?? null]);
    $whole = $plan('/mnt/user/zzapps', 'run:20261011-0300', 'swap', $owner + ['nextcloud' => $ncs]);
    same('restore nextcloud: the whole share brings its folder back too', 'maintenance_off', end($whole['steps'])['do'] ?? null);
    $none = fn (array $p) => [in_array('maintenance_off', array_column($p['steps'], 'do'), true), in_array('after.nextcloud_maintenance', array_column($p['after'], 'key'), true)];
    same('restore nextcloud: not for a copy, another snapshot, another app\'s folder, an app without Nextcloud',
        [[false, false], [false, false], [false, false], [false, false]],
        [$none($plan('/mnt/user/zzapps/zz-nc', 'run:20261011-0300', 'copy', $owner)), $none($plan('/mnt/user/zzapps/zz-nc', 'name:manual-y', 'swap', $owner)),
         $none($plan('/mnt/user/zzapps/zz-other', 'run:20261011-0300', 'swap', $owner)), $none($plan('/mnt/user/zzapps/zz-other', 'run:20261011-0300', 'swap', $other))]);
    $en = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/restore/lang/en.json'), true) ?: [];
    check('restore nextcloud: the step, its notes and the line have words',
        isset($en['step.maintenance_off'], $en['sn.nc_not_running'], $en['sn.nc_maintenance_failed'], $en['after.nextcloud_maintenance']));

    // the step on a stand-in docker: a running one, a stopped one, one whose occ refuses
    $put("$tmp/bin/docker", "#!/bin/sh\necho \"\$*\" >> " . escapeshellarg("$tmp/docker.calls") . "\n"
        . "case \"\$*\" in\n"
        . "  *inspect*zz-nc-app*|*inspect*zz-nc-bad*) echo true ;;\n"
        . "  *inspect*) echo 'Error: No such object' >&2; exit 1 ;;\n"
        . "  *exec*zz-nc-bad*) echo 'Nextcloud is not installed' >&2; exit 1 ;;\n"
        . "  *exec*) echo 'Maintenance mode disabled' ;;\n"
        . "esac\n");
    chmod("$tmp/bin/docker", 0755);
    $GLOBALS['rs']['docker'] = "$tmp/bin/docker";
    $GLOBALS['rs']['nc_wait'] = 0;
    $id = "$stamp-ab12";
    rsPrivateDir(rsData());
    rsPrivateDir(rsDir($id));
    $p['stamp'] = $stamp;
    $j = rsJournalNew($id, $p);
    $i = count($j['steps']) - 1;
    $r = rsStep($j, $i);
    same('restore nextcloud: occ as Nextcloud\'s user while the container runs', ['ok', "inspect -f {{.State.Running}} zz-nc-app\nexec -u www-data zz-nc-app php /var/www/html/occ maintenance:mode --off"],
        [$r['state'], trim((string) @file_get_contents("$tmp/docker.calls"))]);
    @unlink("$tmp/docker.calls");
    $j['steps'][$i]['container'] = 'zz-nc-gone';
    $r = rsStep($j, $i);
    same('restore nextcloud: a container that doesn\'t run — a warning naming the command, occ not asked', ['warning', 'nc_not_running',
            'docker exec -u www-data zz-nc-gone php /var/www/html/occ maintenance:mode --off', 1],
        [$r['state'], $r['note'] ?? null, $r['params']['command'] ?? null, count(file("$tmp/docker.calls"))]);
    @unlink("$tmp/docker.calls");
    $j['steps'][$i]['container'] = 'zz-nc-bad';
    $r = rsStep($j, $i);
    same('restore nextcloud: occ refuses — three tries, then a warning (never failed)', ['warning', 'nc_maintenance_failed', 3, 'Nextcloud is not installed'],
        [$r['state'], $r['note'] ?? null, count(preg_grep('/^exec /', file("$tmp/docker.calls"))), $r['detail'] ?? null]);
    @unlink("$tmp/docker.calls");
    $j['steps'][$i]['user'] = 'www-data; rm -rf /';
    $r = rsStep($j, $i);
    same('restore nextcloud: a step of an odd shape runs nothing', ['warning', false], [$r['state'], is_file("$tmp/docker.calls")]);

    unset($GLOBALS['rs']['data'], $GLOBALS['rs']['job_file'], $GLOBALS['rs']['ub_data'], $GLOBALS['rs']['sizes_file'], $GLOBALS['rs']['users'],
          $GLOBALS['rs']['docker'], $GLOBALS['rs']['nc_wait']);
    $GLOBALS['rs']['du'] = ['queue' => [], 'running' => []];
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Mr. Restori's findings of 2026-10-06 (a VM's folder in domains, a ZFS dataset of its own): sizes from the source by a
 * du that sees an unmounted ZFS snapshot, allocated and apparent (sparse), ZFS sources counted with their data's own
 * size where the target doesn't compress; an empty folder counts as nothing there («put in place», it goes aside); the
 * snapshots of a dataset he put aside are still offered (and said to stay with it); a folder holding a running VM's
 * disks is never swapped or put back under it (and checked again in the job); rsync keeps sparse files sparse; a
 * journal put back says so and where the restored state went; Kopia's list shows what a snapshot holds. All in a
 * temporary folder, VMs and ZFS as stand-ins.
 */
function testRestoreFindings(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-rsfind-' . getmypid();
    $mnt = "$tmp/mnt";
    @mkdir("$tmp/data/unraid-backup/state", 0700, true);
    $GLOBALS['rs']['data'] = "$tmp/data/restore";
    $GLOBALS['rs']['job_file'] = "$tmp/data/restore-job.json";
    $GLOBALS['rs']['ub_data'] = "$tmp/data/unraid-backup";
    $GLOBALS['rs']['sizes_file'] = "$tmp/data/restore-sizes.json";
    $GLOBALS['rs']['users'] = fn (array $paths, array $roots): array => [[], []];
    $GLOBALS['rs']['inherited'] = fn (string $ds): bool => true;
    $GLOBALS['rs']['ratios'] = fn (array $snaps): array => array_fill_keys($snaps, 1.25);
    $compresses = false;
    $GLOBALS['rs']['compresses'] = function (string $ds) use (&$compresses): bool { return $compresses; };
    $vmState = 'running';
    $GLOBALS['rs']['vm_disks'] = function () use (&$vmState): array {
        return ['VM1' => ['state' => $vmState, 'disks' => ['/mnt/user/domains/VM1/vdisk1.img']],
                'Other' => ['state' => 'running', 'disks' => ['/mnt/maple/domains/Other/vdisk1.img']]];
    };
    $put = function (string $file, ?string $text = null): void {
        @mkdir($text === null ? $file : dirname($file), 0755, true);
        if ($text !== null) {
            file_put_contents($file, $text);
        }
    };
    $T = (int) strtotime('2026-10-06 16:00');
    $aside = "$mnt/maple/domains/VM2.aside-20261006-175854";
    // VM1: a dataset of its own, empty now, its snapshot holds the disk; VM2: data now, its old dataset put aside with the snapshot
    $put("$mnt/maple/domains/VM1/.zfs/snapshot/uso-backup-20261006-1600/vdisk1.img", 'disk one');
    $put("$mnt/maple/domains/VM2/vdisk1.img", 'live two');
    $put("$aside/.zfs/snapshot/uso-backup-20261006-1600/vdisk1.img", 'old two');
    $put("$mnt/user");
    symlink("$mnt/maple/domains", "$mnt/user/domains");
    $ctx = [
        'fs' => ['maple' => 'zfs'],
        'zfs' => ["$mnt/maple/domains" => 'zz-maple/domains', "$mnt/maple/domains/VM1" => 'zz-maple/domains/VM1',
                  "$mnt/maple/domains/VM2" => 'zz-maple/domains/VM2', $aside => 'zz-maple/domains/VM2.aside-20261006-175854'],
        'snaps' => ['zz-maple/domains/VM1' => [['name' => 'uso-backup-20261006-1600', 'time' => $T]],
                    'zz-maple/domains/VM2.aside-20261006-175854' => [['name' => 'uso-backup-20261006-1600', 'time' => $T]]],
        'asleep' => [], 'prefixes' => ['uso-backup-', 'unraidbackup-'], 'btrfs_dir' => '.btrfs-snap', 'settings' => [],
        'cfg' => ['domains' => ['shareUseCache' => 'only', 'shareCachePool' => 'maple']],
        'mnt' => $mnt, 'user' => "$mnt/user", 'disks' => ['maple' => ['name' => 'maple', 'fsFree' => '1000000000']],
        'shares_ini' => ['domains' => ['exclusive' => 'yes']], 'old_shares' => null, 'now' => [],
    ];
    $owner = ['kind' => 'vm', 'name' => 'VM1', 'id' => 'VM1', 'vm_state' => 'shut off'];
    $stamp = '20261006-190000';
    $src1 = "$mnt/maple/domains/VM1/.zfs/snapshot/uso-backup-20261006-1600";

    // 2: an empty folder (here a dataset holding only its .zfs) is nothing there: «put in place» by default, it goes aside
    $c = $ctx;
    $p = rsPlanFilesFor('/mnt/user/domains/VM1', '', '', false, $owner, $stamp, $c);
    $notes = array_column($p['notes'], 'key');
    same('restore findings: an empty folder — put in place by default, as a dataset, the empty one aside',
        [true, 'swap', ['copy', 'vms_off', 'not_open', 'aside', 'move'], 'empty', 'zz-maple/domains/VM1.restored-' . $stamp],
        [$p['options']['nothing_live'], $p['target']['mode'], array_column($p['steps'], 'do'), $p['aside'][0]['what'] ?? null, $p['steps'][0]['dataset'] ?? null]);
    check('restore findings: and says so (place, the empty folder aside)', in_array('note.files_place_empty', $notes, true)
        && in_array('after.files_empty_aside', array_column($p['after'], 'key'), true) && ($p['after'][0]['key'] ?? '') === 'after.files_place', json_encode([$notes, $p['after']]));
    // 7: its snapshots go with the dataset put aside — said so
    $snapNote = array_values(array_filter($p['notes'], fn ($n) => $n['key'] === 'note.files_dataset_snaps'))[0] ?? [];
    same('restore findings: the snapshots stay with the dataset put aside — said so', [1, "zz-maple/domains/VM1.aside-$stamp", true],
        [$snapNote['params']['n'] ?? null, $snapNote['params']['dataset'] ?? null, $snapNote['warn'] ?? null]);
    // 6: a running VM keeps its disk there — refused, with a reason; the job looks again before replacing anything
    same('restore findings: never under a running VM', [['restore_vm_uses'], 'VM1', 'running', '/mnt/user/domains/VM1/vdisk1.img'],
        [array_values(array_diff(array_column($p['blockers'], 'key'), [])), $p['blockers'][0]['params']['name'] ?? null,
         $p['blockers'][0]['params']['state'] ?? null, $p['blockers'][0]['params']['path'] ?? null]);
    same('restore findings: the job checks the VMs again with every way to the folder',
        [['/mnt/user/domains/VM1', '/mnt/maple/domains/VM1'], ['VM1']], [$p['steps'][1]['paths'] ?? null, $p['steps'][1]['names'] ?? null]);
    same('restore findings: a VM elsewhere doesn\'t count', [], array_column(rsVmsUsing(['/mnt/user/domains/VM2']), 'name'));
    same('restore findings: the VM running blocks the step in the job, shut off it passes', ['failed', 'vm_running', 'VM1 (running)'],
        (fn ($r) => [$r['state'], $r['note'] ?? null, $r['params']['names'] ?? null])(rsDoVmsOff($p['steps'][1])));
    $vmState = 'shut off';
    same('restore findings: shut off it passes', 'ok', rsDoVmsOff($p['steps'][1])['state']);
    $c = $ctx;
    $p = rsPlanFilesFor('/mnt/user/domains/VM1', '', '', false, $owner, $stamp, $c);
    same('restore findings: VM shut off — nothing blocks, said to stay off', [[], true],
        [array_column($p['blockers'], 'key'), in_array('note.files_vms_off', array_column($p['notes'], 'key'), true)]);
    $c = $ctx;
    $q = rsPlanFilesFor('/mnt/user/domains/VM1', '', 'copy', false, $owner, $stamp, $c);
    same('restore findings: a copy next to it never asks the VMs (nothing replaced)', [['copy'], []], [array_column($q['steps'], 'do'), $q['blockers']]);

    // 1: the size comes from the source; old entries (the du that said 1 KB) count as not measured; 3: ZFS → its data's size
    same('restore findings: measured from the source, in the background', [true, null, [$src1]], [$p['sizes']['measuring'], $p['sizes']['need'], $p['sizes']['paths']]);
    rsSizesSave([$src1 => ['bytes' => 1024, 'at' => time(), 'seconds' => 0]]);
    $c = $ctx;
    same('restore findings: a size from the old du is measured again', true, rsPlanFilesFor('/mnt/user/domains/VM1', '', '', false, $owner, $stamp, $c)['sizes']['measuring']);
    $g = 1 << 30;
    rsSizesSave([$src1 => ['bytes' => 16 * $g, 'apparent' => 108 * $g, 'at' => time(), 'seconds' => 3]]);
    $c = $ctx;
    $p = rsPlanFilesFor('/mnt/user/domains/VM1', '', '', false, $owner, $stamp, $c);
    same('restore findings: into a target that doesn\'t compress, the data\'s own size; the apparent size beside it',
        [false, 20 * $g, 20 * $g, 108 * $g, [$src1 => 1.25], false],
        [$p['sizes']['measuring'], $p['sizes']['need'], $p['sizes']['logical'], $p['sizes']['apparent'], (array) $p['sizes']['scale'], $p['sizes']['compresses']]);
    $compresses = true;
    $c = $ctx;
    same('restore findings: into a ZFS dataset that compresses, what it takes there', 16 * $g, rsPlanFilesFor('/mnt/user/domains/VM1', '', '', false, $owner, $stamp, $c)['sizes']['need']);

    // 7: the snapshots of a dataset put aside are still offered for the folder, as what they are
    $c = $ctx;
    $owner2 = ['kind' => 'vm', 'name' => 'VM2', 'id' => 'VM2', 'vm_state' => 'shut off'];
    $p = rsPlanFilesFor('/mnt/user/domains/VM2', '', '', false, $owner2, $stamp, $c);
    $mid = 'aside:VM2.aside-20261006-175854@uso-backup-20261006-1600';
    same('restore findings: the snapshot of the dataset put aside is a moment of its own (data there: copy)',
        [[$mid], $aside, $mid, 'copy', ["$aside/.zfs/snapshot/uso-backup-20261006-1600"], true],
        [array_column($p['options']['moments'], 'id'), $p['options']['moments'][0]['aside'] ?? null, $p['target']['snap'], $p['target']['mode'],
         $p['steps'][0]['sources'] ?? null, in_array('note.files_from_aside', array_column($p['notes'], 'key'), true)]);
    same('restore findings: counted for the folder\'s row', 1, rsFolder('/mnt/user/domains/VM2', [], $c)['snaps']);
    // a backup run after it went aside snapshots the leftover too: that one holds no state of the folder — never offered
    $put("$aside/.zfs/snapshot/uso-backup-20261006-1828/leftover.txt", 'empty leftover');
    $c = $ctx;
    $c['snaps']['zz-maple/domains/VM2.aside-20261006-175854'][] = ['name' => 'uso-backup-20261006-1828', 'time' => (int) strtotime('2026-10-06 18:31')];
    same('restore findings: a snapshot of the folder put aside taken after it went aside is left out',
        [[$mid], 1], [array_column(rsPlanFilesFor('/mnt/user/domains/VM2', '', '', false, $owner2, $stamp, $c)['options']['moments'], 'id'),
                      rsFolder('/mnt/user/domains/VM2', [], $c)['snaps']]);

    // 1: du sees an unmounted ZFS snapshot (it looks inside: <path>/.), allocated and apparent of a sparse file
    same('restore findings: du looks inside a folder, apparent on request',
        [['nice', '-n', '10', 'du', '-s', '-B1', '-x', "$src1/."], ['nice', '-n', '10', 'du', '-s', '-B1', '-x', '--apparent-size', "$src1/vdisk1.img"]],
        [rsDuCommand($src1, false), rsDuCommand("$src1/vdisk1.img", true)]);
    $sp = "$tmp/sparse";
    $put("$sp/disk.img", str_repeat('x', 65536));
    $h = fopen("$sp/disk.img", 'r+');
    ftruncate($h, 64 << 20);
    fclose($h);
    $GLOBALS['rs']['du'] = ['queue' => [], 'running' => []];
    rsDuQueue($sp);
    for ($i = 0; $i < 100 && (rsSizeOf(rsSizes(), $sp) === null); $i++) {
        rsDuTick();
        usleep(50000);
    }
    $m = rsSizeOf(rsSizes(), $sp);
    check('restore findings: the background du measures allocated and apparent', $m !== null && $m['bytes'] < (8 << 20) && $m['apparent'] >= (64 << 20), json_encode($m));

    // 3: rsync keeps sparse files sparse
    $id = "$stamp-ab12";
    rsPrivateDir(rsData());
    rsPrivateDir(rsDir($id));
    $j = rsJournalNew($id, rsPlanBase('files', 'zz', []) + ['stamp' => $stamp]);
    $j['steps'] = [['do' => 'copy', 'from' => $sp, 'sources' => [$sp], 'to' => "$tmp/copy", 'state' => 'running']];
    $r = rsStep($j, 0);
    clearstatcache();
    $st = @stat("$tmp/copy/disk.img");
    check('restore findings: the copy keeps the sparse file sparse', $r['state'] === 'ok' && $st && $st['size'] === (64 << 20) && $st['blocks'] * 512 < (8 << 20),
        json_encode([$r, $st ? [$st['size'], $st['blocks']] : null]));

    // 6: «Put back» of such a restore — never under a running VM, the VMs checked again first
    $vmState = 'running';
    $jid = '20261006-180000-cd34';
    rsPrivateDir(rsDir($jid));
    $jr = rsJournalNew($jid, rsPlanBase('files', 'VM1', ['path' => '/mnt/user/domains/VM1']) + ['stamp' => '20261006-180000']);
    $jr['result'] = 'ok';
    $jr['steps'] = [['do' => 'aside', 'state' => 'ok', 'undo' => [
        ['do' => 'aside', 'path' => '/mnt/maple/domains/VM1', 'to' => '/mnt/maple/domains/VM1.putback-{T}', 'optional' => true],
        ['do' => 'move', 'from' => '/mnt/maple/domains/VM1.aside-20261006-180000', 'to' => '/mnt/maple/domains/VM1']]]];   // only planned, never run
    writeAtomic(rsDir($jid) . '/plan.json', jsonEncode(rsPlanBase('files', 'VM1', []) + ['stamp' => '20261006-180000']), 0600, 0, 0);
    rsJournalWrite($jr, false);
    $GLOBALS['rs']['vm_disks'] = fn (): array => ['VM1' => ['state' => 'running', 'disks' => ['/mnt/maple/domains/VM1/vdisk1.img']]];
    $b = rsPlanPutback(['id' => $jid], '20261006-200000');
    check('restore findings: a put back under a running VM is refused, its VMs checked first',
        in_array('restore_vm_uses', array_column($b['blockers'], 'key'), true) && ($b['steps'][0]['do'] ?? '') === 'vms_off', json_encode([$b['blockers'], $b['steps']]));
    same('restore findings: VM disks found by any way to them', [['VM1'], []],
        [array_column(rsVmsUsing(['/mnt/user/domains/VM1']), 'name'), rsVmsUsing(['/mnt/disks/x/domains/VM1', '/boot/config'])]);

    // 5: a journal put back: when, where the restored state went, its put back's entry
    $pid = '20261006-200000-ef56';
    rsPrivateDir(rsDir($pid));
    $pj = rsJournalNew($pid, rsPlanBase('putback', 'VM1', ['id' => $jid]) + ['stamp' => '20261006-200000']);
    $pj['result'] = 'ok';
    $pj['finished'] = 1791300000;
    $pj['aside'] = [['from' => "$mnt/maple/domains/VM1", 'to' => "$mnt/maple/domains/VM1.putback-20261006-200000"]];
    rsJournalWrite($pj, false);
    rsMarkPutback($jid, $pid, 'ok');
    $row = rsJournalRow(rsJournal($jid));
    same('restore findings: the journal says it was put back, when, and where the restored state went',
        [$pid, 'ok', 1791300000, ["$mnt/maple/domains/VM1.putback-20261006-200000"], false],
        [$row['putback']['id'] ?? null, $row['putback']['result'] ?? null, $row['putback']['finished'] ?? null, array_column($row['putback']['aside'] ?? [], 'to'), $row['can_putback']]);

    // 8: Kopia's list shows what a snapshot holds (rootEntry.summ), not the files read anew in that run
    $k = rsKopiaParse(json_encode([['id' => '0123456789abcdef0123456789abcdef', 'startTime' => '2026-10-05T23:17:22Z',
        'stats' => ['totalSize' => 28788869, 'fileCount' => 2, 'cachedFiles' => 801, 'nonCachedFiles' => 2, 'dirCount' => 187],
        'rootEntry' => ['summ' => ['size' => 28788869, 'files' => 803, 'dirs' => 187, 'numFailed' => 0]]],
        ['id' => 'abcdef0123456789abcdef0123456789', 'startTime' => '2026-10-04T23:17:22Z',
         'stats' => ['totalSize' => 5, 'fileCount' => 2, 'cachedFiles' => 7, 'nonCachedFiles' => 2]]]));
    same('restore findings: Kopia — what the snapshot holds (old ones: cached + read anew)', [[803, 187, 28788869, 0], [9, null, 5, 0]],
        array_map(fn ($x) => [$x['files'], $x['dirs'], $x['bytes'], $x['failed']], $k));

    // the page sums sizes the same way, under node
    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('restore findings page: node is missing here - skipped', true);
    } else {
        $js = <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
globalThis.Office = { scope: () => T, t: T, el: () => ({}), store: () => null, desk: () => {}, places: () => {}, placesFrom: () => {}, placesTook: () => {}, sections: () => ({ places: () => [] }), has: () => false, fmt: {} };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const r = OFFICE_DESK_TESTS.restore;
const sizes = { measuring: true, need: null, paths: ['/a', '/b'], scale: { '/a': 1.25 }, compresses: false, free: 100 };
const map = { '/a': { bytes: 1000, apparent: 9000 }, '/b': { bytes: 10, apparent: 10 } };
console.log(JSON.stringify([r.sizesDone(sizes, map), r.sizesDone({ ...sizes, compresses: true }, map),
  r.sizesDone(sizes, { '/a': { bytes: 1024 }, '/b': map['/b'] })]));
JS;
        file_put_contents("$tmp/t.js", $js);
        $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/restore/desk.js') . ' 2>&1');
        $o = json_decode($raw, true);
        same('restore findings page: sizes summed like the agent (scaled where the target doesn\'t compress, apparent, old entries not measured)',
            [[1260, 1260, 9010, false], 1010, null],
            is_array($o) ? [[$o[0]['need'] ?? null, $o[0]['logical'] ?? null, $o[0]['apparent'] ?? null, $o[0]['measuring'] ?? null], $o[1]['need'] ?? null, $o[2]] : $raw);
    }

    unset($GLOBALS['rs']['data'], $GLOBALS['rs']['job_file'], $GLOBALS['rs']['ub_data'], $GLOBALS['rs']['sizes_file'], $GLOBALS['rs']['users'],
          $GLOBALS['rs']['inherited'], $GLOBALS['rs']['ratios'], $GLOBALS['rs']['compresses'], $GLOBALS['rs']['vm_disks']);
    $GLOBALS['rs']['du'] = ['queue' => [], 'running' => []];
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Mr. Restori's databases tile: the dumps and the media servers' SQLite copies of every package (in the shapes of
 * a large server's real manifests, engine 2.20), earlier nights' copies from the backup place's snapshots (the SQLite
 * copies too), where a package is kept; then the page's list under node — per app, one media server's copies as one
 * entry, names, the tile's line («none» too), each earlier night once and never the one listed, the requests
 * «Restore…» sends (the existing kinds db / sqlite). Everything in a temporary folder.
 */
function testRestoreDatabases(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-rsdb-' . getmypid();
