    $put('snapA/apps/EmbyServer/manifest.json', $emby('20261005-1600', 414000000));
    $t06 = rsRunTime('20261006-1600');
    $t0602 = rsRunTime('20261006-0200');
    $t05 = rsRunTime('20261005-1600');

