            [$r['headers']['content-encoding'] ?? null, $r['headers']['vary'] ?? null, $r['gz'], $r['json']['state']['mark'] ?? $r['raw'], $r['length']]);
        check('api gzip: … all the bytes', $r['bytes'] > strlen($pad) && str_ends_with($r['body'], '}'));
    }
