        [$r['status'], $r['headers']['content-encoding'] ?? null, $r['headers']['vary'] ?? null, $r['gz'], $r['json']['agent']['running'] ?? $r['raw'], $r['length']]);
    $r = $ask('a=nothing', 'gzip');
