  querySelector: (s) => (s === '#sso' ? ROOT : mk()), querySelectorAll: () => [], createElement: () => mk(), createElementNS: () => mk(), addEventListener() {},
  removeEventListener() {}, documentElement: { scrollHeight: 20000 }, activeElement: null, hidden: false, body: mk() };
