O.strings = JSON.parse(fs.readFileSync(stringsFile, 'utf8'));
O.lang = 'de';
const toasts = [];
O.toast = (m) => toasts.push(m);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
