    $r2 = $as('$p = rsPlan(["kind" => "partner_start", "pair" => "' . $id . '", "unit" => "share:appdata", "snap" => "uso-backup-20261007-0200", "stamp" => "' . $st . '"]);'
        . ' $jid = rsLaunch($p, false); $code = rsJob([$jid]); return ["id" => $jid, "code" => $code, "j" => rsJournal($jid)];');
