    $tick = fn (string $more = '') => $as('$GLOBALS["rs"]["state"] = ["kept" => ["stale"], "partners" => []]; $GLOBALS["rspNext"] = 0; ' . $more . ' rspTick(); return readJson(deskFile("restore"))["kept"] ?? "unwritten";');
