        substr_count((string) file_get_contents(OFFICE_WEB . '/desks/caretaker/partner.js'), "needLine('send')") === 3 && str_contains((string) file_get_contents(OFFICE_WEB . '/desks/caretaker/partner.js'), "needLine('receive')"));

