        . '"drop" => ["kind" => "app", "name" => "dropnook", "dirs" => ["appdata/drop"], "needs" => ["drop", "appdata"]]];'
        . ' return rsPlan(["kind" => "partner_start", "pair" => "' . $id . '", "unit" => "share:appdata", "snap" => "uso-backup-20261007-0200", "stamp" => "' . $at(9100) . '"' . $more . ']);');
    $x1 = $needsPlan('');
