    check('drill share file: a kind of its own, an estimate, its texts on his page', in_array('sharefile', DRILL_STEP_KINDS, true)
        && drillEstimate($pick['step'], ['kopia_mb' => 0]) === 10 && str_contains((string) file_get_contents(OFFICE_WEB . '/desks/restore/drill.js'), "'drill.pv_sharefile_wait_' + p.share_file.why"));

    $j = drillJournalNew('20261102-031500-5f5f', ['scope' => 'now', 'deadline' => time() + 3600, 'steps' => [$pick['step']]]);
    rsPrivateDir(drillDir($j['id']));
    $env = ['ctx' => $ctx];
    $scratch = "$live/.uso-drill-{$j['id']}";
    $r = drillDoShareFile($j, 0, $env);
    same('drill share file: the photo back from the newest backup snapshot (not a plan\'s), size and checksum the same — L1 from the local snapshot',
        ['ok', 'sharefile_ok', 1, 'snapshot', '20261101-0300', 1793500000, '2019/Sommer/strand.jpg', 5000, ".uso-drill-{$j['id']}"],
        [$r['state'], $r['code'], $r['level'], $r['copy'], $r['run'], $r['state_time'], $r['params']['file'] ?? null, $r['params']['bytes'] ?? null, $r['params']['folder'] ?? null]);
    $trash = "$live/" . OFFICE_STOREROOM;
    $runs = glob("$trash/*", GLOB_ONLYDIR) ?: [];
    $man = $runs ? readJson("{$runs[0]}/manifest.json") : null;
    $as = 'restore/' . substr(md5($live), 0, 8) . "/.uso-drill-{$j['id']}";
    same('drill share file: the scratch folder in Ms. Dustdevil\'s storeroom of the share with her manifest (a leftover) — nothing deleted, the real file untouched',
        [false, 1, [['kind' => 'leftover', 'name' => ".uso-drill-{$j['id']}", 'label' => $j['id'], 'from' => $scratch, 'as' => $as]], $photo, $photo],
        [file_exists($scratch), count($runs), $man['items'] ?? null, (string) @file_get_contents("{$runs[0]}/$as/strand.jpg"), (string) file_get_contents("$live/2019/Sommer/strand.jpg")]);
    $made = array_values(array_filter($j['made'], fn ($x) => $x['kind'] === 'scratch'));
    same('drill share file: written down before it was made, gone with the storeroom it went into', [[$scratch, true, $trash]],
        array_map(fn ($x) => [$x['name'], $x['gone'], $x['trash'] ?? null], $made));
    check('drill share file: the manifest\'s entry in the shape Ms. Dustdevil reads', clTrashAsOk($as, 'leftover', basename($runs[0])));
    same('drill share file: Ms. Dustdevil finds that storeroom (awake only)', [[$trash], []], [drillTrashRoots([]), drillTrashRoots(['maple' => true])]);

    // never over anything: the folder there already
    $j2 = drillJournalNew('20261102-031600-6a6a', ['scope' => 'now', 'deadline' => time() + 3600, 'steps' => [$pick['step']]]);
    rsPrivateDir(drillDir($j2['id']));
    @mkdir("$live/.uso-drill-{$j2['id']}");
    file_put_contents("$live/.uso-drill-{$j2['id']}/keep.txt", 'mine');
    $r = drillDoShareFile($j2, 0, $env);
    same('drill share file: its folder there already — not checked, nothing written, nothing moved', ['not_checked', 'sharefile_taken', 'mine', []],
        [$r['state'], $r['code'], (string) file_get_contents("$live/.uso-drill-{$j2['id']}/keep.txt"), $j2['made']]);
    // what came back differs: failed (the snapshot's file changed under it is simulated by a hash stand-in: a short copy)
    $env2 = $env;
    $env2['ctx']['asleep'] = ['maple' => true];
    same('drill share file: the pool asleep now — asleep, never looked into', ['asleep', []], [drillDoShareFile($j2, 0, $env2)['state'], $j2['made']]);
    exec('rm -rf ' . escapeshellarg("$snap/2019"));
    same('drill share file: nothing small enough in the snapshot — not checked', ['not_checked', 'sharefile_none'],
        array_values(array_intersect_key(drillDoShareFile($j2, 0, $env), ['state' => 1, 'code' => 1])));
    $env3 = $env;
    $env3['ctx']['snaps']['maple/Familienfotos'] = [['name' => 'uso-plan-x-20261031-0000', 'time' => 1793400000]];
    same('drill share file: only a plan\'s snapshot — not checked (the backup\'s is proven)', 'sharefile_no_snap', drillDoShareFile($j2, 0, $env3)['code']);

    // the sweeper after a crash: a scratch folder left — into the storeroom too; never a folder of another name
    $j3 = drillJournalNew('20261102-031700-7b7b', ['scope' => 'now', 'deadline' => time() + 3600, 'steps' => []]);
    rsPrivateDir(drillDir($j3['id']));
    $left = "$live/.uso-drill-{$j3['id']}";
    @mkdir($left);
    file_put_contents("$left/strand.jpg", 'copy');
    drillMade($j3, ['kind' => 'scratch', 'name' => $left]);
    drillMade($j3, ['kind' => 'scratch', 'name' => "$live/2019"]);
    @mkdir("$live/2019", 0700, true);
    drillCleanup($j3, null, false);
    same('drill share file: the cleanup puts a left scratch folder away, never another folder', [false, true, [true, false]],
        [file_exists($left), is_dir("$live/2019"), array_column($j3['made'], 'gone')]);
    check('drill share file: the agent\'s code writes only through Ms. Dustdevil\'s helpers, never removes',
        !preg_match('/\b(unlink|rmdir|rm -rf)\b/', (string) preg_replace('/^.*?function drillShareFilePick\b|function drillTrashRoots\b.*$/s', '', (string) file_get_contents(OFFICE_DIR . '/agent/desks/restore-drill.php'))));
    exec('rm -rf ' . escapeshellarg($tmp));
    [$GLOBALS['drill'], $GLOBALS['rs']] = $saved;
}

/**
 * The drill's SQLite check and a media server's own lower(): Jellyfin indexes lower("Name") with .NET's Unicode lower,
 * the sqlite3 command has only SQLite's ASCII one — integrity_check then reports «row N missing from index …» for
 * «Željko Ivanek» although the copy is whole (nostromo, 2026-10-20). Only such index complaints are forgiven.
 */
function testDrillSqliteAppIndex(): void
{
    if (trim((string) shell_exec('command -v sqlite3')) === '') {
        check('drill sqlite app index: sqlite3 missing here - skipped', true);
        return;
    }
    $tmp = sys_get_temp_dir() . '/office-tests-drill-sq-' . getmypid();
    exec('rm -rf ' . escapeshellarg($tmp));
    @mkdir($tmp, 0700, true);
    $db = "$tmp/j.db";
    exec('sqlite3 ' . escapeshellarg($db) . ' ' . escapeshellarg('CREATE TABLE Peoples (Id TEXT, Name TEXT); CREATE INDEX "IX_Peoples_NameLower" ON "Peoples" (lower("Name")); CREATE INDEX "IX_Peoples_Name" ON "Peoples" ("Name"); INSERT INTO Peoples VALUES (\'1\', \'Željko Ivanek\');'));
    $uri = 'file:' . drillUriPath($db) . '?mode=ro&immutable=1';
    same('drill sqlite app index: only lower() index complaints → those indexes',
        ['IX_Peoples_NameLower'], drillSqliteAppIndexes($uri, "row 162 missing from index IX_Peoples_NameLower\nrow 598 missing from index IX_Peoples_NameLower"));
    same('drill sqlite app index: … with the «in database main» header line too',
        ['IX_Peoples_NameLower'], drillSqliteAppIndexes($uri, "*** in database main ***\nwrong # of entries in index IX_Peoples_NameLower"));
    same('drill sqlite app index: a plain column index missing a row is damage', null, drillSqliteAppIndexes($uri, 'row 5 missing from index IX_Peoples_Name'));
    same('drill sqlite app index: anything else besides is damage', null,
        drillSqliteAppIndexes($uri, "row 162 missing from index IX_Peoples_NameLower\nPage 7: btreeInitPage() returns error code 11"));
    same('drill sqlite app index: an index that isn\'t there is damage', null, drillSqliteAppIndexes($uri, 'row 1 missing from index IX_Nope'));
    foreach (['de', 'en', 'it', 'fr', 'es'] as $l) {
        $j = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/restore/lang/$l.json"), true);
        check("drill sqlite app index: $l says it, with the index's name", str_contains((string) ($j['drill.code.sqlite_ok_app_index'] ?? ''), '{indexes}'));
    }
    exec('rm -rf ' . escapeshellarg($tmp));
}

function testRestoreDrill(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-drill-' . getmypid();
    exec('rm -rf ' . escapeshellarg($tmp));
    @mkdir("$tmp/data/unraid-backup/state", 0700, true);
    $saved = [$GLOBALS['drill'] ?? [], $GLOBALS['rs']['data'] ?? null, $GLOBALS['rs']['job_file'] ?? null, $GLOBALS['rs']['ub_data'] ?? null, $GLOBALS['rs']['var_ini'] ?? null];
    $GLOBALS['rs']['data'] = "$tmp/data/restore";
    $GLOBALS['rs']['job_file'] = "$tmp/data/restore-job.json";
    $GLOBALS['rs']['ub_data'] = "$tmp/data/unraid-backup";
    $GLOBALS['rs']['var_ini'] = "$tmp/var.ini";
    file_put_contents("$tmp/var.ini", "fsState=\"Started\"\nmdResyncPos=\"0\"\n");
    $GLOBALS['drill'] = ['data' => "$tmp/data/restore-drill", 'cert' => "$tmp/data/restore-drill.json", 'job_file' => "$tmp/data/restore-drill-job.json",
                         'var_ini' => "$tmp/var.ini", 'run_dir' => "$tmp/run", 'ram' => 4 << 30, 'next_backup' => null];
    @mkdir("$tmp/run", 0700, true);
    $fix = OFFICE_DIR . '/tests/fixtures/restore-drill';
    $man = fn (string $f) => json_decode((string) file_get_contents("$fix/$f.json"), true);

    // ---- the one gate: every docker run argument list, against a large server's database containers
    $id = '20261101-041200-ab12';
    $seen = [];
    $seenC = [];
    foreach (['immich', 'nextcloud', 'zz-test-db'] as $app) {
        $m = $man("app-$app");
        $m = json_decode(str_replace('=scrubbed"', '=SECRET-SENTINEL"', json_encode($m)), true);     // what a password would be
        foreach (rsAppPackage($m, $app, '/x')['containers'] as $n => $pc) {
            if (!in_array($pc['db'], ['postgres', 'mariadb', 'mongodb'], true)) {
                continue;
            }
            $c = drillContainerOf($m, $pc['name']);
            $args = drillContainerArgs($c, $pc['db'], DRILL_PREFIX . "$id-$n", $id, 2 << 30, 'drill-own-pw');
            $flat = implode(' ', $args);
            $seen[$pc['name']] = $args;
            check("drill gate $pc[name]: keeps to the «never» list", drillArgsSafe($args, $c, $pc['db']), $flat);
            same("drill gate $pc[name]: after the image its own command, then the lean server's options — exactly",
                [...array_slice($c['entrypoint'], 1), ...$c['cmd'], ...($pc['db'] === 'postgres' ? array_merge(...array_map(fn ($o) => ['-c', $o], DRILL_LEAN['postgres'])) : DRILL_LEAN['mariadb'])],
                array_slice($args, array_search($c['image_id'], $args, true) + 1));
            $seenC[$pc['name']] = [$c, $pc['db']];
            check("drill gate $pc[name]: no value of the app's environment, no app label, no port, no bind, no device, no privilege",
                !str_contains($flat, 'SECRET-SENTINEL') && !str_contains($flat, 'com.docker.compose') && !preg_match('/ (-p|-v|--mount|--device|--privileged|--cap-add|--volumes-from) /', " $flat "), $flat);
            same("drill gate $pc[name]: network none, once", ['--network', 'none'], array_slice($args, array_search('--network', $args, true), 2));
            check("drill gate $pc[name]: the image by its id from the manifest, never a tag (no pull)", in_array($c['image_id'], $args, true) && !in_array($pc['image'], $args, true));
            check("drill gate $pc[name]: its label, limits, no restart, small logs, no new privileges",
                in_array("uso.drill=$id", $args, true) && in_array('uso.installed-by=restori-drill', $args, true) && in_array('--memory', $args, true)
                && in_array('--pids-limit', $args, true) && in_array('no-new-privileges', $args, true) && in_array('max-size=10m', $args, true)
                && ($args[array_search('--restart', $args, true) + 1] ?? '') === 'no');
            $tmpfs = array_values(array_map(fn ($i) => explode(':', $args[$i + 1])[0], array_keys($args, '--tmpfs', true)));
            same("drill gate $pc[name]: its data and every volume of the image on tmpfs (no anonymous volume)",
                $pc['db'] === 'postgres' ? ['/var/lib/postgresql/data'] : ['/var/lib/mysql'], $tmpfs);
        }
    }
    $names = array_keys($seen);
    sort($names);
    same('drill gate: a large server\'s four database containers', ['immich_postgres', 'nextcloud-db', 'zz-test-db-mdb', 'zz-test-db-pg'], $names);
    $im = $seen['immich_postgres'] ?? [];
    check('drill gate: Immich keeps its entrypoint and its config (vchord preload), its initdb arguments, trust login',
        ($im[array_search('--entrypoint', $im, true) + 1] ?? '') === '/usr/local/bin/immich-docker-entrypoint.sh'
        && in_array('config_file=/etc/postgresql/postgresql.conf', $im, true) && in_array('POSTGRES_INITDB_ARGS=--data-checksums', $im, true)
        && in_array('POSTGRES_HOST_AUTH_METHOD=trust', $im, true) && in_array('--shm-size', $im, true), implode(' ', $im));
    $md = $seen['nextcloud-db'] ?? [];
    check('drill gate: MariaDB with its own root password, room for big rows, its command kept',
        in_array('MARIADB_ROOT_PASSWORD=drill-own-pw', $md, true) && in_array('--max-allowed-packet=1G', $md, true)
        && in_array('--transaction-isolation=READ-COMMITTED', $md, true) && !preg_grep('/^MARIADB_(USER|PASSWORD|DATABASE)=/', $md), implode(' ', $md));
    $c = drillContainerOf($man('app-immich'), 'immich_postgres');
    same('drill gate: the environment taken is only what shapes the server', ['POSTGRES_INITDB_ARGS', 'LANG', 'PGDATA', 'DB_STORAGE_TYPE'], array_keys($c['env']));
    $bad = [
        'a port'           => [...$im, '-p', '5432:5432'],
        'another network'  => array_map(fn ($a) => $a === 'none' ? 'host' : $a, $im),
        'a second network' => [...$im, '--network=bridge'],
        'a bind'           => [...$im, '-v', '/mnt/user/appdata/immich/postgres:/x'],
        'an app password'  => [...$im, '-e', 'POSTGRES_PASSWORD=x'],
        'an app label'     => [...$im, '--label', 'com.docker.compose.project=immich'],
        'privileged'       => [...$im, '--privileged'],
        'no label'         => array_values(array_filter($im, fn ($a) => !str_starts_with($a, 'uso.drill='))),
    ];
    $mdc = $seenC['nextcloud-db'][0] ?? [];
    $bad += [
        'a server option not on the allow-list'      => [...$im, '-c', 'archive_command=/bin/sh -c x'],
        'a lean option changed'                      => array_map(fn ($a) => $a === 'max_wal_size=256MB' ? 'max_wal_size=50GB' : $a, $im),
        'a lean option missing'                      => array_values(array_filter($im, fn ($a) => $a !== 'checkpoint_timeout=30s')),
        'the app\'s command changed'                 => array_map(fn ($a) => $a === 'config_file=/etc/postgresql/postgresql.conf' ? 'config_file=/tmp/x.conf' : $a, $im),
        'the image twice'                            => [...$im, $c['image_id']],
    ];
    foreach ($bad as $what => $args) {
        check("drill gate: refused with $what", !drillArgsSafe($args, $c, 'postgres'));
    }
    foreach (['an init file' => '--init-file=/tmp/x.sql', 'a binlog of its own' => '--log-bin=/var/lib/mysql/bin', 'the plugin dir' => '--plugin-dir=/tmp'] as $what => $opt) {
        check("drill gate: MariaDB refused with $what after the lean options", !drillArgsSafe([...$md, $opt], $mdc, 'mariadb'));
    }
    check('drill gate: Postgres\' lean options are not MariaDB\'s (the type decides)', !drillArgsSafe($im, $c, 'mariadb'));
    same('drill lean: Postgres — nothing kept for a crash, WAL recycled at 256 MB (Immich\'s config allows 5 GB), small buffers; MariaDB — small redo, no binlog, no doublewrite, room for big rows',
        [['fsync=off', 'synchronous_commit=off', 'full_page_writes=off', 'wal_level=minimal', 'max_wal_senders=0', 'archive_mode=off', 'max_wal_size=256MB', 'min_wal_size=64MB',
          'checkpoint_timeout=30s', 'shared_buffers=128MB'],
         ['--max-allowed-packet=1G', '--innodb-log-file-size=64M', '--innodb-flush-log-at-trx-commit=0', '--skip-log-bin', '--innodb-doublewrite=0']],
        [array_values(array_filter(array_slice($im, array_search($c['image_id'], $im, true) + 4), fn ($a) => $a !== '-c')), array_slice($md, -5)]);
    $own = fn (array $ep, array $cmd) => drillServerArgs(['entrypoint' => $ep, 'cmd' => $cmd], 'postgres') !== [];
    same('drill lean: only when the command starts the server — postgres, options only behind an entrypoint, nothing; never an app\'s own script',
        [true, true, true, false, false, false],
        [$own(['docker-entrypoint.sh'], ['postgres']), $own(['docker-entrypoint.sh'], ['-c', 'x=y']), $own(['docker-entrypoint.sh'], []), $own([], ['-c', 'x=y']),
         $own(['docker-entrypoint.sh'], ['/start-db.sh']), $own([], [])]);
    same('drill lean: MongoDB gets none', [], drillServerArgs(['entrypoint' => ['docker-entrypoint.sh'], 'cmd' => ['mongod']], 'mongodb'));
    foreach (['another drill\'s name' => [DRILL_PREFIX . '20261101-041200-ffff-1', $c], 'no image id' => [DRILL_PREFIX . "$id-1", ['image_id' => ''] + $c]] as $what => [$name, $cc]) {
        try {
            drillContainerArgs($cc, 'postgres', $name, $id, 1 << 30, 'x');
            check("drill gate: the builder refuses $what", false);
        } catch (Problem) {
            check("drill gate: the builder refuses $what", true);
        }
    }
    $u = drillContainerOf(['containers' => [['name' => 'pg', 'image_id' => 'sha256:' . str_repeat('a', 64), 'inspect' => ['Config' => ['User' => '999:998', 'Volumes' => ['/data' => [], '/../etc' => []]]]]]], 'pg');
    $ua = drillContainerArgs($u, 'postgres', DRILL_PREFIX . "$id-2", $id, 1 << 30, 'x');
    check('drill gate: a numeric user runs as itself and owns its tmpfs; a volume path with .. is dropped',
        in_array('999:998', $ua, true) && (bool) preg_grep('#^/var/lib/postgresql/data:rw,size=\d+m,uid=999,gid=998$#', $ua) && !preg_grep('#/\.\./#', $ua), implode(' ', $ua));

    // ---- qcow2 headers and raw disks, read here
    $qhead = function (int $version, string $backing, ?string $fmt) {
        $h = "QFI\xfb" . pack('N', $version) . pack('J', 0) . pack('N', 0) . pack('N', 16) . pack('J', 100 << 30) . str_repeat("\0", 104 - 32);
        if ($version >= 3) {
            $h = substr_replace($h, pack('N', 104), 100, 4);
        }
        $ext = $fmt !== null ? pack('N', 0xE2792ACA) . pack('N', strlen($fmt)) . str_pad($fmt, (strlen($fmt) + 7) & ~7, "\0") : '';
        $ext .= pack('NN', 0, 0);
        $off = ($version >= 3 ? 104 : 72) + strlen($ext);
        $h = substr($h, 0, $version >= 3 ? 104 : 72) . $ext;
        if ($backing !== '') {
            $h = substr_replace($h, pack('J', $off), 8, 8);
            $h = substr_replace($h, pack('N', strlen($backing)), 16, 4);
            $h .= $backing;
        }
        return $h;
    };
    same('drill qcow2: v3 with a backing file and its format', ['version' => 3, 'size' => 100 << 30, 'backing' => 'vdisk2.img', 'backing_format' => 'raw'],
        drillQcow2($qhead(3, 'vdisk2.img', 'raw')));
    same('drill qcow2: v2 with an absolute backing path', '/mnt/user/domains/Win/base.qcow2', drillQcow2($qhead(2, '/mnt/user/domains/Win/base.qcow2', null))['backing'] ?? null);
    same('drill qcow2: no backing file', [null, null], array_values(array_intersect_key(drillQcow2($qhead(3, '', null)) ?? [], ['backing' => 1, 'backing_format' => 1])));
    $far = $qhead(3, '', null);
    $far = substr_replace($far, pack('J', 1 << 20), 8, 8);
    $far = substr_replace($far, pack('N', 12), 16, 4);
    same('drill qcow2: a backing name beyond what was read is «there, unreadable here»', '', drillQcow2($far)['backing'] ?? null);
    same('drill qcow2: not a qcow2, a version it doesn\'t know', [null, null], [drillQcow2(str_repeat("\0", 512)), drillQcow2("QFI\xfb" . pack('N', 9) . str_repeat("\0", 100))]);
    $mbr = str_repeat("\0", 510) . "\x55\xAA" . str_repeat("\0", 4096);
    $gpt = str_repeat("\0", 512) . 'EFI PART' . str_repeat("\0", 4000);
    $gpt4k = str_repeat("\0", 4096) . 'EFI PART' . str_repeat("\0", 100);
    same('drill raw disks: MBR, GPT (512 and 4K sectors), nothing, something', ['mbr', 'gpt', 'gpt', 'empty', 'data'],
        [drillRawLook($mbr), drillRawLook($gpt), drillRawLook($gpt4k), drillRawLook(str_repeat("\0", 8192)), drillRawLook(str_repeat("\0", 100) . 'x')]);

    // ---- a VM disk chain in a run's snapshot (a fake pool: maple, its dataset domains with one snapshot of run 20261101-0300)
    $snap = "$tmp/mnt/maple/domains/.zfs/snapshot/uso-backup-20261101-0300";
    @mkdir("$snap/Win", 0700, true);
    @mkdir("$snap/Lin", 0700, true);
    @mkdir("$snap/Empty", 0700, true);
    @mkdir("$tmp/mnt/maple/isos", 0700, true);
    file_put_contents("$snap/Win/vdisk2.S1qcow2", $qhead(3, 'vdisk2.img', 'raw'));
    file_put_contents("$snap/Win/vdisk2.img", $mbr);
    file_put_contents("$snap/Lin/top.qcow2", $qhead(3, '/mnt/maple/isos/base.img', 'raw'));
    file_put_contents("$snap/Empty/vdisk1.img", str_repeat("\0", 2 << 20));
