    $sample = drillKopiaSample($kj, $kj['steps'][0], ['obj' => $o('dROOT'), 'run' => '20261101-0200'], $e1);
    same('drill Kopia sample: the dump played from Kopia later is not read twice', [1, 12], [$sample['files'], $sample['bytes']]);
    $e1 = ['kopia_reserved' => (1 << 20) - 20] + $kenv;
    $sample = drillKopiaSample($kj, $kj['steps'][0], ['obj' => $o('dROOT'), 'run' => '20261101-0200'], $e1);
    same('drill Kopia sample: what is kept for the dumps from Kopia is not the samples\'', [1, 12], [$sample['files'], $sample['bytes']]);
    // «what you would lose»: a dump played from Kopia says how far Kopia alone brings it back — never the local state
    $kl = array_column(drillCertLose([
        ['kind' => 'dump', 'of' => 'app', 'id' => 'immich', 'name' => 'immich', 'result' => 'ok', 'level' => 2, 'copy' => 'snapshot', 'state_time' => 500, 'params' => ['seconds' => 30], 'seconds' => 30],
        ['kind' => 'dump', 'of' => 'app', 'id' => 'immich', 'name' => 'immich', 'result' => 'ok', 'level' => 2, 'copy' => 'kopia', 'state_time' => 400, 'params' => ['seconds' => 50], 'seconds' => 60],
        ['kind' => 'kopia', 'of' => 'app', 'id' => 'immich', 'name' => 'immich', 'result' => 'ok', 'level' => 1, 'copy' => 'kopia', 'state_time' => 450, 'params' => [], 'seconds' => 5],
    ], 'UnraidSecretaryOffice'), null, 'id');
    same('drill certificate: kopia_played — the state a database came back with from Kopia alone; local and the play time stay the local copy\'s',
        [400, 500, 450, 30, 2], [$kl['immich']['kopia_played'] ?? null, $kl['immich']['local'] ?? null, $kl['immich']['kopia'] ?? null, $kl['immich']['played'] ?? null, $kl['immich']['best'] ?? null]);

    // ---- packages (L1), on a fake backup place
    $base = "$tmp/place";
    @mkdir("$base/apps/zz/db", 0700, true);
    @mkdir("$base/vms/Lin/nvram", 0700, true);
    @mkdir("$base/server", 0700, true);
    file_put_contents("$base/apps/zz/db/postgres_zz-pg.sql.gz", $dump);
    file_put_contents("$base/apps/zz/my-zz.xml", '<?xml version="1.0"?><Container><Name>zz</Name></Container>');
    $files = [['path' => 'db/postgres_zz-pg.sql.gz', 'bytes' => strlen($dump), 'run' => '20261101-0200', 'what' => 'dump', 'container' => 'zz-pg'],
              ['path' => 'my-zz.xml', 'bytes' => (int) filesize("$base/apps/zz/my-zz.xml"), 'run' => '20261101-0200', 'what' => 'template', 'container' => '']];
    file_put_contents("$base/apps/zz/manifest.json", json_encode(['name' => 'zz', 'type' => 'template', 'run' => '20261101-0200', 'files' => $files,
        'dumps' => [['container' => 'zz-pg', 'type' => 'postgres']], 'containers' => [['name' => 'zz-pg', 'image' => 'postgres:16']]]));
    file_put_contents("$base/vms/Lin/Lin.xml", '<domain><name>Lin</name><uuid>9b3e9c65-84b4-2410-470b-8f719c38ea29</uuid></domain>');
    file_put_contents("$base/vms/Lin/nvram/9b3e9c65-84b4-2410-470b-8f719c38ea29_VARS.fd", 'vars');
    file_put_contents("$base/vms/Lin/manifest.json", json_encode(['name' => 'Lin', 'run' => '20261101-0200', 'xml' => 'Lin.xml', 'uuid' => '9b3e9c65-84b4-2410-470b-8f719c38ea29',
        'files' => [['path' => 'Lin.xml', 'bytes' => (int) filesize("$base/vms/Lin/Lin.xml"), 'what' => 'xml'],
                    ['path' => 'nvram/9b3e9c65-84b4-2410-470b-8f719c38ea29_VARS.fd', 'bytes' => 4, 'what' => 'nvram']]]));
    file_put_contents("$base/server/run.json", json_encode(['run' => '20261101-0200', 'files' => []]));
    $penv = ['base' => $base, 'pk' => rsPackages($base)];
    $pkg = function (string $kind, string $pid) use (&$penv): array {
        return drillDoPackage(['kind' => $kind, 'id' => $pid, 'name' => $pid, 'stale' => false], $penv);
    };
    $r = $pkg('app', 'zz');
    same('drill package: every file there with its size, the dump with its closing line, the template readable — L1', ['ok', 'package_ok', 1, 'package', 2],
        [$r['state'], $r['code'], $r['level'], $r['copy'], $r['params']['files'] ?? null]);
    same('drill package: a VM — its XML naming it, its NVRAM', ['ok', 1], [$pkg('vm', 'Lin')['state'], $pkg('vm', 'Lin')['level']]);
    file_put_contents("$base/apps/zz/db/postgres_zz-pg.sql.gz", gzencode("CREATE TABLE t (\n"));
    $r = $pkg('app', 'zz');
    same('drill package: a dump of another size — failed, named', ['failed', 'package_size_differs', 'db/postgres_zz-pg.sql.gz'], [$r['state'], $r['code'], $r['params']['file'] ?? null]);
    $files[0]['bytes'] = (int) filesize("$base/apps/zz/db/postgres_zz-pg.sql.gz");
    file_put_contents("$base/apps/zz/manifest.json", json_encode(['name' => 'zz', 'type' => 'template', 'run' => '20261101-0200', 'files' => $files, 'containers' => []]));
    $penv['pk'] = rsPackages($base);
    same('drill package: a dump without its closing line — incomplete', 'dump_incomplete', $pkg('app', 'zz')['code']);
    unlink("$base/vms/Lin/nvram/9b3e9c65-84b4-2410-470b-8f719c38ea29_VARS.fd");
    same('drill package: a file of the manifest missing', ['failed', 'package_file_missing'], array_values(array_intersect_key($pkg('vm', 'Lin'), ['state' => 1, 'code' => 1])));
    same('drill package: no manifest — failed', 'manifest_unreadable', $pkg('app', 'nothing')['code']);
    $sj = ['steps' => [['do' => 'dump', 'kind' => 'app', 'id' => 'zz', 'name' => 'zz']]];
    $senv = ['place' => ['asleep' => true]] + $penv;
    same('drill package: the backup place fell asleep since the plan — «asleep», nothing read', 'asleep', drillStep($sj, 0, $senv)['state']);

    // ---- SQLite (L1): integrity, user_version, the main table — through the sqlite3 command, read only
    if (bin('sqlite3')) {
        $db = "$tmp/lib ?#%.db";                 // characters an SQLite URI must have encoded
        exec('sqlite3 ' . escapeshellarg($db) . ' ' . escapeshellarg('PRAGMA user_version = 7; CREATE TABLE MediaItems (id INTEGER); INSERT INTO MediaItems VALUES (1), (2), (3);'));
        $look = drillSqliteLook('file:' . drillUriPath($db) . '?mode=ro&immutable=1', true);
        same('drill SQLite: a copy read through its URI — intact, its version, the main table and its rows', [null, 'ok', 7, 'MediaItems', 3],
            [$look['error'], $look['integrity'], $look['version'], $look['table'], $look['rows']]);
        $look = drillSqliteLook('file:' . drillUriPath($db) . '?mode=ro', false);
        same('drill SQLite: the live database, without integrity_check', [null, 7, 3], [$look['error'], $look['version'], $look['rows']]);
        file_put_contents("$tmp/broken.db", 'SQLite format 3' . str_repeat("\x07", 3000));
        check('drill SQLite: a damaged file — not «ok»', drillSqliteLook('file:' . drillUriPath("$tmp/broken.db") . '?mode=ro&immutable=1', true)['integrity'] !== 'ok');
        check('drill SQLite: nothing written next to it (no -wal, -shm, -journal)', !file_exists("$db-wal") && !file_exists("$db-shm") && !file_exists("$db-journal"));
    }

    // ---- a long command ends at once when the array is being stopped (the job must never hold the pool busy)
    file_put_contents("$tmp/var.ini", "fsState=\"Stopping\"\n");
    $t0 = microtime(true);
    $r = drillRunStoppable(['sleep', '20'], 60);
    same('drill: a long command ended by the array stop — within seconds, said why', [124, true, 'array_stopping'],
        [$r[0], microtime(true) - $t0 < 5, $GLOBALS['rsStopWhy'] ?? null]);
    file_put_contents("$tmp/var.ini", "fsState=\"Started\"\nmdResyncPos=\"0\"\n");
    $GLOBALS['rsStop'] = false;
    $GLOBALS['rsStopWhy'] = null;
    same('drill: … and runs to its end otherwise', [0, "x\n"], array_slice(drillRunStoppable(['echo', 'x'], 10), 0, 2));

    // ---- a whole job in-process: packages only (no container, no Kopia) — lock, marker, journal, certificate, one warning on a failure
    file_put_contents("$tmp/data/unraid-backup/settings.ini", "[general]\ndumps_share = UnraidSecretaryOffice\n[kopia]\nenabled = no\n");
    file_put_contents("$base/vms/Lin/nvram/9b3e9c65-84b4-2410-470b-8f719c38ea29_VARS.fd", 'vars');
    file_put_contents("$base/apps/zz/db/postgres_zz-pg.sql.gz", $dump);
    $files[0]['bytes'] = strlen($dump);
    file_put_contents("$base/apps/zz/manifest.json", json_encode(['name' => 'zz', 'type' => 'template', 'run' => '20261101-0200', 'files' => $files, 'containers' => []]));
    $GLOBALS['drill']['base'] = $base;
    $GLOBALS['drill']['next_backup'] = null;
    $notify = "$tmp/notify";
    file_put_contents($notify, "#!/bin/sh\nfor a in \"\$@\"; do printf '%s\\n' \"\$a\"; done >>" . escapeshellarg("$tmp/notify.log") . "\n");
    chmod($notify, 0755);
    $beforeNotify = getenv('OFFICE_NOTIFY_BIN');
    putenv("OFFICE_NOTIFY_BIN=$notify");
    putenv("OFFICE_NOTIFY_STAMP=$tmp/notify.stamp");
    $plan = ['kind' => 'drill', 'scope' => 'now', 'what' => 'now', 'stamp' => '20261103-034000', 'deadline' => time() + 3600, 'blockers' => [], 'steps' => [
        ['do' => 'package', 'kind' => 'app', 'id' => 'zz', 'name' => 'zz', 'run' => '20261101-0200', 'stale' => false],
        ['do' => 'package', 'kind' => 'vm', 'id' => 'Lin', 'name' => 'Lin', 'run' => '20261101-0200', 'stale' => false],
        ['do' => 'package', 'kind' => 'app', 'id' => 'gone', 'name' => 'gone', 'run' => '20261101-0200', 'stale' => false]]];
    $jid = drillLaunch($plan, false);
    $h = rsLockTake('someone', 'test');
    same('drill job: refused while the engine\'s lock is held — exit 75, nothing touched', [75, 'refused', 'restore_busy_restore'],
        [drillJob([$jid]), drillJournal($jid)['result'] ?? null, drillJournal($jid)['reason'] ?? null]);
    rsLockRelease($h);
    $jid = drillLaunch(['stamp' => '20261103-034100'] + $plan, false);
    $code = drillJob([$jid]);
    if (function_exists('pcntl_signal')) {
        foreach ([SIGTERM, SIGINT, SIGHUP] as $sig) {
            pcntl_signal($sig, SIG_DFL);
        }
    }
    $jj = drillJournal($jid);
    same('drill job: ran its steps, ended «failed» (one package gone), exit 1', [1, 'failed', ['ok', 'ok', 'failed']], [$code, $jj['result'] ?? null, array_column($jj['steps'] ?? [], 'state')]);
    same('drill job: the lock given back, its note gone, the RAM marker gone', [null, false, false],
        [backupLockHolder(rsUbData()), is_file(rsUbData() . '/state/lock-holder.json'), is_file("$tmp/run/drill.open")]);
    $cert = drillCertificate();
    same('drill job: the certificate says so, with its history', ['failed', $jid, 3], [$cert['last']['result'] ?? null, $cert['last']['id'] ?? null, $cert['last']['items'] ?? null]);
    $told = (string) @file_get_contents("$tmp/notify.log");
    check('drill job: one warning to Unraid\'s notifications, naming what failed', substr_count($told, 'Unraid Secretary Office: ') === 1 && str_contains($told, "warning\n")
        && str_contains($told, 'gone'), $told);
    putenv($beforeNotify === false ? 'OFFICE_NOTIFY_BIN' : "OFFICE_NOTIFY_BIN=$beforeNotify");
    putenv('OFFICE_NOTIFY_STAMP');

    // ---- agent.sh's drill_release: only with a marker, only a pid running agent.php, the drill's throwaways by label
    @mkdir("$tmp/bin", 0700, true);
    copy($dock, "$tmp/bin/docker");
    chmod("$tmp/bin/docker", 0755);
    $agent = escapeshellarg(OFFICE_DIR . '/plugin/scripts/agent.sh');
    $release = fn () => trim((string) shell_exec('bash -c ' . escapeshellarg('PATH=' . escapeshellarg("$tmp/bin") . ":\$PATH; source $agent; RUN=" . escapeshellarg("$tmp/run")
        . '; LOG=' . escapeshellarg("$tmp/agent.log") . '; drill_release') . ' 2>&1'));
    file_put_contents("$tmp/docker.log", '');
    $release();
    same('drill_release: no marker — nothing, not even a docker call', '', (string) file_get_contents("$tmp/docker.log"));
    $sleeper = proc_open(['sleep', '30'], [], $pp);
    file_put_contents("$tmp/run/drill.open", proc_get_status($sleeper)['pid'] . " $jid\n");
    $release();
    check('drill_release: a marker — the throwaways by their label, never a process that isn\'t agent.php, the marker gone',
        str_contains((string) file_get_contents("$tmp/docker.log"), 'ps -aq --filter label=uso.drill') && proc_get_status($sleeper)['running'] && !is_file("$tmp/run/drill.open"));
    proc_terminate($sleeper);
    proc_close($sleeper);

    // ---- the page's tile and words, under node (drill.js alone, desk.js's helpers as stand-ins)
    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node !== '') {
        file_put_contents("$tmp/drill-page.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
globalThis.Office = { scope: () => T, t: T, el: () => ({}), store: () => null, desk: () => {}, places: () => {}, placesFrom: () => {}, placesTook: () => {}, has: () => true, errorText: (e) => 'error ' + e.key,
  api: { get: async () => ({ ok: true, part: null }) }, agent: { running: true } };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const fmt = { size: (b) => b + ' B', date: (t) => 'D' + t, relative: (t) => 'R' + t, time: (t) => 'T' + t, duration: (s) => s + 's' };
Office.restoreDrill.init({ T, fmt, date: fmt.date, tiles: () => {}, redraw: () => {}, shown: () => true });
const d = OFFICE_DESK_TESTS.drill;
const out = { none: d.tileLine() };
d.setCert({ interface: 1, last: { result: 'passed', proven: 31, failed: 0, ended: 100 } });
out.passed = d.tileLine();
d.setCert({ interface: 1, last: { result: 'failed', proven: 30, failed: 2, ended: 100 } });
out.failed = d.tileLine();
d.setJob({ result: 'running', steps: [{ state: 'ok' }, { state: 'running' }, { state: 'pending' }] });
out.running = d.tileLine();
out.code = d.codeText('too_big_for_ram', { need: 3, budget: 2, container: 'x' });
out.reasons = [d.reasonText('array_stopping'), d.reasonText('drill_parity')];
// the settings: Kopia's cap shown and typed in GB (kept as MB), the weekly night named
Office.locale = 'en';
out.gb = [d.kopiaGb(1024), d.kopiaGb(50000), d.kopiaGb(512), d.kopiaGb(0), d.kopiaGb(102400), d.kopiaGb(1536)];
Office.locale = 'de';
out.gbDe = d.kopiaGb(50000);
out.parse = ['1,5', '1.5', ' 2 ', '0', '100', '100.1', '-1', 'abc', '', '1,5,0', '.5', '1e3'].map(d.parseGb);
d.setState({ settings: { schedule: 'weekly', weekday: 1 } });
out.sched = [d.schedText('weekly'), d.schedText('monthly')];
d.setState({ settings: { schedule: 'weekly' } });
out.schedOld = d.schedText('weekly');
// the job's poll: a failed ask (Office.api.get answers offline, never throws) keeps it going, slower; back — its pace again
const delays = [];
globalThis.setTimeout = (fn, ms) => { delays.push(ms); return 1; };
globalThis.clearTimeout = () => {};
Office.pollDelay = (b, f) => (f > 0 ? b * 10 * f : b);
d.setJob({ id: 'j1', result: 'running', steps: [] });
let asks = 0;
Office.api.get = async () => (++asks <= 2 ? { ok: false, error: { key: 'offline' } } : { ok: true, part: { id: 'j1', result: 'running', steps: [{ state: 'ok' }] } });
(async () => {
  await d.poll(); await d.poll(); await d.poll();
  out.poll = [delays, d.job().steps.length];
  console.log(JSON.stringify(out));
})();
JS);
        $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/drill-page.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/restore/drill.js') . ' 2>&1');
        $o = json_decode($raw, true);
        same('drill page: the tile — none yet, passed, failed, practising (step n of all)', [
            ['drill.tile_none', ''], ['drill.tile_passed {"n":31,"failed":0}', 'R100'], ['drill.tile_failed {"n":30,"failed":2}', 'R100'],
            ['drill.tile_running', 'drill.tile_step {"n":2,"total":3}']],
            is_array($o) ? [$o['none'], $o['passed'], $o['failed'], $o['running']] : $raw);
        same('drill page: a code\'s words with its sizes made readable; a stop of its own, a refusal', ['drill.code.too_big_for_ram {"need":"3 B","budget":"2 B","container":"x"}',
            ['drill.code.array_stopping {}', 'error drill_parity']], is_array($o) ? [$o['code'], $o['reasons']] : $raw);
        same('drill page: Kopia\'s cap in GB — up to one decimal, no «.0», the page\'s decimal sign; a comma or a point typed, 0–100 only',
            [['1', '48.8', '0.5', '0', '100', '1.5'], '48,8', [1.5, 1.5, 2, 0, 100, null, null, null, null, null, 0.5, null]],
            is_array($o) ? [$o['gb'] ?? null, $o['gbDe'] ?? null, $o['parse'] ?? null] : $raw);
        same('drill page: weekly names its night (the setting\'s, a file without one: Saturday to Sunday); monthly as it was',
            [['drill.sched.weekly {"night":"drill.night.1"}', 'drill.sched.monthly {}'], 'drill.sched.weekly {"night":"drill.night.0"}'],
            is_array($o) ? [$o['sched'] ?? null, $o['schedOld'] ?? null] : $raw);
        same('drill page: the job\'s poll goes on after failed asks, slower, and at its pace once they come through again (review 2026-10-09)',
            [[20000, 40000, 2000], 1], is_array($o) ? $o['poll'] ?? null : $raw);
    }

    // ---- the strings: every text the drill asks for, in English (the five languages are compared by testStrings)
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/restore/lang/en.json'), true) ?: [];
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/restore/drill.js');
    preg_match_all("/(?<![.\\w])T\\(\\s*'([a-z0-9_.]+)'\\s*[,)]/", $js, $m);
    foreach (array_unique($m[1]) as $key) {
        check("drill.js asks for restore.$key", isset($en[$key]));
    }
    $php = (string) file_get_contents(OFFICE_DIR . '/agent/desks/restore-drill.php');
    preg_match_all("/'code' => '([a-z_]+)'|\\\$code = '([a-z_]+)'|\\['(?:failed|warning)', '([a-z_]+)'\\]/", $php, $m, PREG_SET_ORDER);
    // his restore's notes taken as codes, his stops, and the codes chosen by a condition
    $codes = ['verify_ok', 'play_failed', 'play_errors', 'verify_empty', 'verify_differs', 'verify_unread', 'verify_none', 'deadline', 'stopped', 'array_stopping', 'budget',
              'vm_disk_size', 'vm_chain_ok', 'vm_disk_empty', 'vm_disk_missing', 'vm_chain_outside', 'kopia_none', 'kopia_incomplete', 'kopia_old', 'kopia_sample_failed',
              'extensions_missing', 'db_missing_in_dump', 'dump_old', 'sqlite_ok', 'sqlite_foreign', 'kopia_ok', 'package_ok'];
    foreach ($m as $x) {
        foreach (array_slice($x, 1) as $c) {
            if ($c !== '' && !in_array($c, DRILL_RESULTS, true)) {
                $codes[] = $c;
            }
        }
    }
    foreach (array_unique($codes) as $c) {
        check("drill: a text for its code $c", isset($en["drill.code.$c"]));
    }
    foreach (['result' => ['passed', 'failed', 'aborted', 'refused', 'interrupted', 'queued', 'running'], 'state' => [...DRILL_RESULTS, 'skipped', 'pending', 'running'],
              'kind' => DRILL_STEP_KINDS, 'copy' => ['package', 'local', 'kopia'], 'scope' => ['monthly', 'weekly', 'now'], 'sched' => DRILL_SCHEDULES,
              'set' => [...DRILL_SCHEDULES, 'live_catalog', 'live_sqlite'], 'pv' => DRILL_STEP_KINDS, 'level_hint' => ['0', '1', '2'], 'level_word' => ['0', '1', '2'],
              'copy_hint' => ['package', 'local', 'kopia'], 'done' => ['passed', 'failed', 'other'], 'night' => ['0', '1', '2', '3', '4', '5', '6']] as $group => $names) {
        foreach ($names as $n) {
            check("drill: a text for drill.$group.$n", isset($en["drill.$group.$n"]));
        }
    }
    // 2026-10-12 (Benj): no L0/L1/L2 jargon on the page - the level is a word (vorhanden · gelesen · zurückgespielt)
    foreach (['en', 'de', 'it', 'fr', 'es'] as $lc) {
        $ll = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/restore/lang/$lc.json"), true);
        same("drill: no L-number shown in $lc", [], array_keys(array_filter($ll, fn ($v) => (bool) preg_match('/\bL[012]\b/', is_array($v) ? implode(' ', $v) : (string) $v))));
    }
    $de = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/restore/lang/de.json'), true);
    same('drill: the German chip words', ['vorhanden', 'gelesen', 'zurückgespielt', '{word} · {copy}'],
        [$de['drill.level_word.0'] ?? null, $de['drill.level_word.1'] ?? null, $de['drill.level_word.2'] ?? null, $de['drill.level'] ?? null]);
    foreach (['drill_array', 'drill_parity', 'drill_running', 'drill_deadline', 'drill_nothing', 'restore_array_stopping'] as $e) {
        check("drill: a text for errors.$e", isset($en["errors.$e"]));
    }

    $GLOBALS['drill'] = $saved[0];
    [, $GLOBALS['rs']['data'], $GLOBALS['rs']['job_file'], $GLOBALS['rs']['ub_data'], $GLOBALS['rs']['var_ini']] = $saved;
    foreach (['data', 'job_file', 'ub_data', 'var_ini'] as $kk) {
        if ($GLOBALS['rs'][$kk] === null) {
            unset($GLOBALS['rs'][$kk]);
        }
    }
    $GLOBALS['rsStop'] = false;
    unset($GLOBALS['rsDeadline'], $GLOBALS['rsDeadlineWhy'], $GLOBALS['rsStopWhy']);
    exec('rm -rf ' . escapeshellarg($tmp));
}

// ===================================================================== partner offices, stage 2: the other desks

/** A syslog line of sshd's at time $t (Unraid's «Oct  8 12:00:00 Tower …») */
function partner2SshLine(int $t, string $ip, ?string $fp, string $how = 'publickey'): string
{
    return date('M', $t) . ' ' . str_pad(date('j', $t), 2, ' ', STR_PAD_LEFT) . date(' H:i:s', $t)
        . " Tower sshd-session[4711]: Accepted $how for root from $ip port 50001 ssh2" . ($fp !== null ? ": ED25519 $fp" : '') . "\n";
}

/**
 * The night watchman and the partner door: the office's own line noted by himself, other lines news, a known pair's
 * line changed, the pair's key from elsewhere and its address with another key, refusals, the door's transfers in
 * the data flow, what its retention destroyed, the posture tips, «What I keep an eye on» — and nothing of a key in
 * his files
 */
function testWatchmanPartner(): void
{
    if (posix_geteuid() !== 0) {
        check('watchman partner: root only (the pairs file is root\'s) — not run here', true);
        return;
    }
    $tmp = hardeningTmp('watch-partner');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $src = "$tmp/src";
    $data = "$tmp/data";
    foreach (['crontabs', 'cron.d', 'logplugins', 'atjobs', 'agents', 'extra', 'ssh/root', 'flash', 'prun'] as $d) {
        @mkdir("$src/$d", 0700, true);
    }
    $paths = ['syslog' => "$src/syslog", 'plugins' => "$src/logplugins", 'go' => "$src/go", 'extra' => "$src/extra", 'passwd' => "$src/passwd",
              'shadow' => "$src/shadow", 'ssh' => "$src/ssh", 'sec' => "$src/sec.ini", 'sec_nfs' => "$src/sec_nfs.ini", 'share_cfg' => "$src/share.cfg",
              'etc_passwd' => "$src/passwd", 'crontabs' => "$src/crontabs", 'cron_d' => "$src/cron.d", 'cron_files' => "$src/flash",
              'userscripts' => "$src/flash/user.scripts", 'atjobs' => "$src/atjobs", 'agents' => "$src/agents",
              'partner_pairs' => "$src/pdata/pairs.json", 'partner_run' => "$src/prun", 'partner_data' => "$src/pdata"];
    file_put_contents($paths['passwd'], "root:x:0:0::/root:/bin/bash\n");
    file_put_contents($paths['go'], "#!/bin/bash\n");
    file_put_contents($paths['syslog'], '');
    file_put_contents("$src/cron.d/root", "*/1 * * * * /usr/local/emhttp/plugins/dynamix/scripts/monitor &> /dev/null\n");
    file_put_contents("$src/crontabs/root", "# nothing\n");
    $keys = "$src/ssh/root/authorized_keys";
    $benj = partnerTestKey('benj@mac');
    $fpBenj = partnerFingerprint($benj);
    file_put_contents($keys, "$benj\n");
    $docker = fn () => [];
    $acks = "$tmp/acks.json";
    $now = time();
    $round = fn (int $t) => watchmanRound($paths, $data, 1000, $t, $docker, false, $acks);
    $open = fn () => array_values(array_filter(watchmanLoad($data)['book'], 'watchmanOpen'));
    $openKeys = function () use ($open): array {
        $k = array_column($open(), 'key');
        sort($k);
        return $k;
    };
    $tips = fn () => array_column((array) (watchmanLoad($data)['state']['posture']['tips'] ?? []), 'id');
    $round($now - 600);                                  // his first round: the baseline

    // ---- the pairing: the pair stored, then its line written (the Team Lead's order) — the office's own, noted by himself
    $kA = partnerTestKey();
    $fpA = partnerFingerprint($kA);
    $pairA = partnerTestPair('a1b2c3d4', ['name' => 'vault', 'address' => '192.168.77.2', 'their_key' => $fpA, 'paired' => $now - 100, 'trust' => 'friend']);
    partnerPairsWrite([$pairA], $paths['partner_pairs']);
    $lineA = partnerDoorLine('a1b2c3d4', '192.168.77.2', $kA);
    file_put_contents($keys, "$benj\n$lineA\n");
    touch($keys, $now - 98);
    // 1.60: whether the office sends to a pair is the setup's say (settings.ini partner lines), not the pair's
    @mkdir(BACKUP_DATA_DIR, 0700, true);
    $hadIni = is_file(BACKUP_DATA_DIR . '/settings.ini') ? (string) file_get_contents(BACKUP_DATA_DIR . '/settings.ini') : null;
    file_put_contents(BACKUP_DATA_DIR . '/settings.ini', "[partner \"a1b2c3d4\"]\nname = vault\naddress = 192.168.77.2\nport = 22\nrate_mbit = 0\n\n[vm \"vault-vm\"]\nmode = snapshot\npartner = a1b2c3d4\n");
    $r = $round($now);
    $paired = array_values(array_filter(watchmanLoad($data)['book'], fn ($e) => $e['kind'] === 'partner_paired'));
    same('watch partner: the office\'s own door line — one line, noted by himself (by office), never open',
        [1, 'office', false, 'vault', 'teamlead', [], []],
        [count($paired), $paired[0]['by'] ?? null, isset($paired[0]) && watchmanOpen($paired[0]), $paired[0]['p']['name'] ?? null,
         $paired[0]['p']['installed_by'] ?? null, $r['added'], $openKeys()]);
    same('watch partner: … in words', 'Partner vault paired — its door in authorized_keys (192.168.77.2)',
        officeNotifyText('watchman', 'entry.partner_paired', watchmanText($paired[0] ?? [], 'en'), 'en'));
    same('watch partner: … its key and its line known', [true, true],
        [isset(watchmanLoad($data)['baseline']['flash']['keys']['root'][$fpA]), isset(watchmanLoad($data)['baseline']['partner']['lines']['a1b2c3d4'])]);
    $r = $round($now + 60);
    same('watch partner: the next round — nothing new, no second note', [[], 1],
        [$r['added'], count(array_filter(watchmanLoad($data)['book'], fn ($e) => $e['kind'] === 'partner_paired'))]);
    same('watch partner: a friend gets plain copies — a posture tip (info), linking the Team Lead', [true, 'info', '#/caretaker/partner'],
        [in_array('partner_friend', $tips(), true), WATCH_POSTURE['partner_friend'],
         array_column((array) watchmanLoad($data)['state']['posture']['tips'], null, 'id')['partner_friend']['link']['path'] ?? null]);
    $hadIni === null ? @unlink(BACKUP_DATA_DIR . '/settings.ini') : file_put_contents(BACKUP_DATA_DIR . '/settings.ini', $hadIni);

    // ---- a line of no pair, and one written long after its pair was stored: news (the flash watch's new key)
    $kB = partnerTestKey();
    $kC = partnerTestKey();
    $pairC = partnerTestPair('c3d4e5f6', ['name' => 'aunt', 'address' => '192.168.77.3', 'their_key' => partnerFingerprint($kC), 'paired' => $now - 7200, 'trust' => 'family']);
    partnerPairsWrite([$pairA, $pairC], $paths['partner_pairs']);
    file_put_contents($keys, "$benj\n$lineA\n" . partnerDoorLine('b2c3d4e5', '10.1.1.1', $kB) . "\n" . partnerDoorLine('c3d4e5f6', '192.168.77.3', $kC) . "\n");
    touch($keys, $now + 290);
    $r = $round($now + 300);
    same('watch partner: a door of no pair and a line written long after its pairing stay news — new keys, told by the flash watch',
        (function (array $k) { sort($k); return $k; })(['flash_ssh_key:root:' . partnerFingerprint($kB), 'flash_ssh_key:root:' . partnerFingerprint($kC)]), $openKeys());
    same('watch partner: … and a door of no pair is a posture tip (advice)', [true, 'advice'], [in_array('partner_unknown', $tips(), true), WATCH_POSTURE['partner_unknown']]);
    watchmanAck('*', $data, $now + 310, false);
    // a pair whose address faces the internet
    $pairD = partnerTestPair('d4e5f6a7', ['name' => 'far', 'address' => '203.0.113.7', 'their_key' => null, 'receive' => null]);
    partnerPairsWrite([$pairA, $pairC, $pairD], $paths['partner_pairs']);
    $round($now + 400);
    same('watch partner: a pair facing the internet — a posture tip (advice)', true, in_array('partner_public', $tips(), true));

    // ---- a known pair's line changed: restrict gone (and «I know, thanks» makes it the new normal)
    $edit = function (string $from, string $to) use (&$lineA, $keys): void {
        $new = str_replace($from, $to, $lineA);
        file_put_contents($keys, str_replace($lineA, $new, (string) file_get_contents($keys)));
        $lineA = $new;
    };
    $edit('restrict,from=', 'from=');
    $r = $round($now + 600);
    $e = array_column($open(), null, 'kind')['door_changed'] ?? [];
    same('watch partner: a known pair\'s line changed — door_changed (important), what changed', [['door_changed'], ['restrict'], false, true, true],
        [$r['added'], $e['p']['what'] ?? null, $e['p']['restrict'] ?? null, $e['p']['command'] ?? null, WATCH_KINDS['door_changed'][1]]);
    same('watch partner: … in words (German)', 'Die Tür von Partner vault wurde geändert: restrict fehlt',
        officeNotifyText('watchman', 'entry.door_changed', watchmanText($e, 'de'), 'de'));
    same('watch partner: … the door is wider than the office made it — a posture tip', true, in_array('partner_wide', $tips(), true));
    watchmanAck($e['id'] ?? '', $data, $now + 610, false);
    $r = $round($now + 900);
    same('watch partner: noted — the line as it is now is normal', [], $r['added']);
    $edit('from="192.168.77.2"', 'restrict,from="192.168.77.2"');
    $r = $round($now + 1200);
    same('watch partner: restrict back alone — safer, normal by itself', [], $r['added']);
    $edit('from="192.168.77.2"', 'from="192.168.77.99"');
    $r = $round($now + 1500);
    same('watch partner: another from= — door_changed again', [['door_changed'], ['from'], '192.168.77.99', '192.168.77.2'],
        [$r['added'], array_column($open(), null, 'kind')['door_changed']['p']['what'] ?? null,
         array_column($open(), null, 'kind')['door_changed']['p']['from'] ?? null, array_column($open(), null, 'kind')['door_changed']['p']['from_old'] ?? null]);
    $edit('from="192.168.77.99"', 'from="192.168.77.2"');
    $round($now + 1550);
    watchmanAck('*', $data, $now + 1560, false);
    $r = $round($now + 1600);
    same('watch partner: back as it was and noted — quiet', [], $r['added']);

    // ---- logins: the pair's key from its address is the door at work; its key elsewhere, its address with another key
    $t = $now + 1650;
    file_put_contents($paths['syslog'], partner2SshLine($t, '192.168.77.2', $fpA) . partner2SshLine($t + 1, '10.0.0.66', $fpA)
        . partner2SshLine($t + 2, '192.168.77.2', $fpBenj), FILE_APPEND);
    $r = $round($now + 1800);
    $moved = array_column(array_filter($open(), fn ($x) => $x['kind'] === 'door_key_moved'), null, 'key');
    ksort($moved);
    same('watch partner: logins — its key from its address nothing; from elsewhere and its address with another key: door_key_moved, no login_new_ip',
        [['door_key_moved', 'door_key_moved'], ['door_key_moved:a1b2c3d4:10.0.0.66' => 'address', 'door_key_moved:a1b2c3d4:192.168.77.2' => 'key'], 'T1078'],
        [$r['added'], array_map(fn ($x) => $x['p']['how'], $moved), WATCH_ATTACK['door_key_moved']]);
    same('watch partner: … in words', 'A login at partner vault\'s door that doesn\'t fit: 10.0.0.66',
        officeNotifyText('watchman', 'entry.door_key_moved', watchmanText($moved['door_key_moved:a1b2c3d4:10.0.0.66'] ?? [], 'en'), 'en'));
    watchmanAck($moved['door_key_moved:a1b2c3d4:10.0.0.66']['id'] ?? '', $data, $now + 1810, false);
    file_put_contents($paths['syslog'], partner2SshLine($now + 1850, '10.0.0.66', $fpA) . partner2SshLine($now + 1851, '192.168.77.2', $fpA), FILE_APPEND);
    $r = $round($now + 2100);
    same('watch partner: noted — that address with that key is fine now', [], $r['added']);

    // ---- refusals at the door: three within a minute from one pair
    $refused = fn (array $times) => file_put_contents("$src/prun/refused-a1b2c3d4.json", json_encode(['pair' => 'a1b2c3d4', 'times' => $times, 'last' => 'unknown_verb']));
    $t = $now + 2300;
    $refused([$t - 50, $t - 20]);
    $r = $round($t);
    same('watch partner: two refusals — nothing', [], $r['added']);
    $refused([$t - 50, $t - 20, $t + 10, $t + 30]);
    $r = $round($t + 300);
    $e = array_column($open(), null, 'kind')['door_refused'] ?? [];
    same('watch partner: three within a minute — door_refused (important), counting the burst', [['door_refused'], 3, ['unknown_verb'], true],
        [$r['added'], $e['count'] ?? null, $e['p']['why'] ?? null, WATCH_KINDS['door_refused'][1]]);
    $r = $round($t + 600);
    same('watch partner: the same refusals again — nothing new', [[], 3], [$r['added'], array_column($open(), null, 'kind')['door_refused']['count'] ?? null]);

    // ---- «What I keep an eye on», and nothing of a key anywhere in his files
    $sum = watchmanSummary(watchmanLoad($data)['baseline'], readJson("$data/seen.json"))['partner'] ?? [];
    $pairs = array_column((array) ($sum['pairs'] ?? []), null, 'id');
    same('watch partner: what he keeps an eye on — the pairs by name, their door there or not, a door of no pair', [['vault', 'ok', true], ['far', false], ['b2c3d4e5']],
        [[$pairs['a1b2c3d4']['name'] ?? null, $pairs['a1b2c3d4']['line'] ?? null, $pairs['a1b2c3d4']['door'] ?? null], [$pairs['d4e5f6a7']['name'] ?? null, $pairs['d4e5f6a7']['door'] ?? null],
         $sum['strays'] ?? null]);
    $blob = '';
    foreach (glob("$data/*") ?: [] as $f) {
        $blob .= (string) @file_get_contents($f);
    }
    $blob .= jsonEncode(watchmanMirror(['baseline' => watchmanLoad($data)['baseline'], 'state' => [], 'book' => []], 'boot', $now, true));
    same('watch partner: no key\'s value in his files or the mirror — fingerprints only', [false, false, false, true],
        [str_contains($blob, substr($kA, 12)), str_contains($blob, substr($kB, 12)), str_contains($blob, substr($benj, 12, 68)), str_contains($blob, $fpA)]);
    same('watch partner: the night shift gets the doors from the mirror', ['a1b2c3d4', 'c3d4e5f6'],
        array_keys((array) (watchmanMirror(['baseline' => watchmanLoad($data)['baseline'], 'state' => [], 'book' => []], 'boot', $now, true)['baseline']['partner']['pairs'] ?? [])));

    // ---- what the door's retention destroyed: no snap_gone (its record, root only, read by offset)
    $del = "$src/pdata/deletes.jsonl";
    same('watch partner deletes: none yet', [[], null], watchmanPartnerDeletes($del, null, false));
    $ds = 'tank/' . PARTNER_PARENT . '/a1b2c3d4/share-appdata';
    file_put_contents($del, json_encode(['t' => $now, 'pair' => 'a1b2c3d4', 'dataset' => $ds, 'snaps' => ['uso-backup-20261001-0200', 'not-the-engine']]) . "\n"
        . json_encode(['t' => $now, 'pair' => 'a1b2c3d4', 'dataset' => 'tank/appdata', 'snaps' => ['uso-backup-20261001-0200']]) . "\n");
    chmod($del, 0600);
    [$ev, $pos] = watchmanPartnerDeletes($del, null, false) ?? [[], null];
    same('watch partner deletes: only the engine\'s names, only under the partners\' place', ["$ds@uso-backup-20261001-0200" => $now], $ev);
    same('watch partner deletes: read on from where he stopped', [], watchmanPartnerDeletes($del, $pos, false)[0] ?? null);
    same('watch partner deletes: his first look starts at its end', [], watchmanPartnerDeletes($del, null, true)[0] ?? null);
    chmod($del, 0644);
    same('watch partner deletes: a record others may read or write is no record', null, watchmanPartnerDeletes($del, null, false));
    chmod($del, 0600);
    $known = ['zfs' => ['tank' => ['time' => $now - 300, 's' => ["$ds@uso-backup-20261001-0200" => '111:0', 'tank/data@mine' => '222:0']]]];
    $look = ['zfs' => ['pools' => ['tank'], 'snaps' => ['tank' => ["$ds@uso-backup-20261002-0200" => ['333', 0]]], 'asleep' => [], 'capped' => []], 'btrfs' => null];
    $diff = watchmanSnapDiff($known, $look, ['d' => [], 'r' => [], 'm' => [], 'p' => $ev], [], ['uso-backup-'], $now);
    same('watch partner snaps: what the door destroyed is expected, anything else still gone', [['partner' => 1], ['tank/data@mine']],
        [$diff['expected'], array_column($diff['gone'][0]['list'] ?? [], 'name')]);

    // ---- the data flow: the door at work is the office's own
    $gb = 1024 ** 3;
    $t0 = strtotime('2026-10-05 10:02:00');
    $lookF = fn (array $o) => $o + ['conns' => [], 'smb' => ['on' => true, 'sessions' => []], 'containers' => null, 'nfs' => false, 'holder' => null,
                                    'kopia' => 'kopia', 'office_shares' => ['UnraidSecretaryOffice']];
    $zfs = fn (int $w) => ['datasets' => ['tank' => ['w' => 1, 'u' => 900 * $gb, 's' => null], 'tank/' . PARTNER_PARENT => ['w' => 0, 'u' => 20 * $gb, 's' => null],
        "tank/" . PARTNER_PARENT . "/a1b2c3d4/share-appdata" => ['w' => $w, 'u' => 20 * $gb, 's' => 1000]], 'pools' => ['tank'], 'asleep' => []];
    $conn = fn (int $sent) => ['local' => '192.0.2.20', 'lport' => 22, 'peer' => '192.168.77.2', 'pport' => 50000, 'service' => 'ssh', 'sent' => $sent, 'rcvd' => 0];
    $door = fn (bool $on) => ['ips' => ['192.168.77.2'], 'door' => $on, 'received' => 0, 'sending' => false];
    $bf = null;
    $book = [];
    [, $flow, $cnt] = watchmanFlowCompare($bf, [], null, $lookF(['zfs' => $zfs(0), 'conns' => [$conn(0)], 'partner' => $door(false)]), $book, $t0);
    [$added, $flow, $cnt] = watchmanFlowCompare($bf, $flow, $cnt, $lookF(['zfs' => $zfs(15 * $gb), 'conns' => [$conn(60 * $gb)], 'partner' => $door(true)]), $book, $t0 + 300);
    $h = intdiv($t0 + 300, 3600);
    same('watch partner flow: while the door receives — its writes into the partners\' place and the pair\'s SSH are the office\'s own',
        [[], [$h => 15 * $gb], [$h => 60 * $gb]], [$added, $flow['shares']['tank/' . PARTNER_PARENT]['o'] ?? null, $flow['clients']['192.168.77.2|ssh']['o'] ?? null]);
    [$added, $flow, $cnt] = watchmanFlowCompare($bf, $flow, $cnt, $lookF(['zfs' => $zfs(30 * $gb), 'conns' => [$conn(120 * $gb)], 'partner' => $door(false)]), $book, $t0 + 600);
    same('watch partner flow: the round after (it ran at the last one) — still its own', [], $added);
    [$added, $flow, $cnt] = watchmanFlowCompare($bf, $flow, $cnt, $lookF(['zfs' => $zfs(45 * $gb), 'conns' => [$conn(180 * $gb)], 'partner' => $door(false)]), $book, $t0 + 900);
    sort($added);
    same('watch partner flow: nobody receives — the same is told', ['flow_client', 'flow_written'], $added);
    $sending = ['ips' => ['192.168.77.2'], 'door' => false, 'received' => 0, 'sending' => true];
    $book = [];
    [$added] = watchmanFlowCompare($bf, $flow, $cnt, $lookF(['zfs' => $zfs(45 * $gb), 'conns' => [$conn(240 * $gb)], 'partner' => $sending]), $book, $t0 + 1200);
    same('watch partner flow: while this office sends (phase partner) the pair\'s SSH is its own', [], $added);

    // ---- texts
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/watchman/lang/en.json'), true) ?: [];
    check('watch partner: the page can say it', isset($en['group.partner'], $en['noted.office_partner'], $en['watch.partner'], $en['posture.to_caretaker'], $en['door_what.restrict']));
    @unlink(watchmanLockFile($data, 'book'));
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Ms. Snapshotini and a partner's copies: the chip's data, never a target, never deleted, renamed, held — unless the
 * pair is gone; her plans' retention leaves them out
 */
function testSnapshotPartner(): void
{
    if (posix_geteuid() !== 0) {
        check('snapshot partner: root only (the pairs file is root\'s) — not run here', true);
        return;
    }
    $tmp = hardeningTmp('snap-partner');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $pairs = "$tmp/partner/pairs.json";
    partnerPairsWrite([partnerTestPair('a1b2c3d4', ['name' => 'vault'])], $pairs);
    $P = PARTNER_PARENT;
    file_put_contents("$tmp/zfs-ds.txt", "tank\tfilesystem\t1000\t9000\t100\t50\t/mnt/tank\ntank/appdata\tfilesystem\t500\t9000\t400\t100\t/mnt/tank/appdata\n"
        . "tank/$P\tfilesystem\t300\t9000\t96\t0\tnone\ntank/$P/a1b2c3d4\tfilesystem\t200\t9000\t96\t0\tnone\n"
        . "tank/$P/a1b2c3d4/share-appdata\tfilesystem\t200\t9000\t150\t50\tlegacy\ntank/$P/deadbeef\tfilesystem\t100\t9000\t96\t0\tnone\n"
        . "tank/$P/deadbeef/vm-old\tfilesystem\t100\t9000\t90\t10\tlegacy\n");
    file_put_contents("$tmp/zfs-snaps.txt", "tank/appdata@uso-backup-20261001-0200\t11\t1700000000\t10\t400\t5\t0\t-\n"
        . "tank/$P/a1b2c3d4/share-appdata@uso-backup-20261001-0200\t12\t1700000000\t10\t150\t5\t0\t-\n"
        . "tank/$P/a1b2c3d4/share-appdata@uso-plan-hourly-20261001-0300\t13\t1700003600\t10\t150\t5\t0\t-\n"
        . "tank/$P/deadbeef/vm-old@uso-backup-20260901-0200\t14\t1690000000\t10\t90\t5\t0\t-\n");
    file_put_contents("$tmp/zpool.txt", "tank\t8000000\t5000000\t3000000\t62\tONLINE\t16\n");
    file_put_contents("$tmp/disks.ini", "[\"tank\"]\nname=\"tank\"\ntype=\"Cache\"\nfsType=\"zfs\"\nspundown=\"0\"\n");
    file_put_contents("$tmp/zfs", "#!/bin/sh\nprintf '%s\\n' \"\$*\" >> " . escapeshellarg("$tmp/zfs-args.txt") . "\ncase \"\$1\" in\n  list)\n    file=snaps\n"
        . "    for a in \"\$@\"; do [ \"\$a\" = filesystem,volume ] && file=ds; done\n    cat " . escapeshellarg($tmp) . "/zfs-\$file.txt\n    exit 0;;\nesac\nexit 0\n");
    file_put_contents("$tmp/zpool", "#!/bin/sh\n[ \"\$1\" = list ] && cat " . escapeshellarg("$tmp/zpool.txt") . "\nexit 0\n");
    chmod("$tmp/zfs", 0755);
    chmod("$tmp/zpool", 0755);
    $iniBefore = $GLOBALS['disksIni'] ?? null;
    $GLOBALS['disksIni'] = "$tmp/disks.ini";
    $GLOBALS['snapshotHost'] = ['zfs' => "$tmp/zfs", 'zpool' => "$tmp/zpool", 'docker' => null];
    $GLOBALS['snapshotPartnerPairs'] = $pairs;

    $z = snapshotPartnerMark(snapshotReadZfs(null, false), $pairs);
    $vol = array_column($z['volumes'], 'partner', 'name');
    same('snapshot partner: datasets under the partners\' place carry the pair — its name, or gone; the place itself; others nothing', [
        ['id' => null, 'name' => null, 'gone' => false, 'place' => true], ['id' => 'a1b2c3d4', 'name' => 'vault', 'gone' => false, 'place' => false],
        ['id' => 'deadbeef', 'name' => null, 'gone' => true, 'place' => false], false],
        [$vol["tank/$P"] ?? null, $vol["tank/$P/a1b2c3d4/share-appdata"] ?? null, $vol["tank/$P/deadbeef/vm-old"] ?? null, isset($vol['tank/appdata'])]);
    $snap = array_column($z['snapshots'], null, 'id');
    $copy = $snap["zfs:tank/$P/a1b2c3d4/share-appdata@uso-backup-20261001-0200"] ?? [];
    $left = $snap["zfs:tank/$P/deadbeef/vm-old@uso-backup-20260901-0200"] ?? [];
    same('snapshot partner: a copy of a pair of today is locked, a leftover of an ended one is not, hers never', [true, false, false],
        [snapshotPartnerLocked($copy), snapshotPartnerLocked($left), snapshotPartnerLocked($snap['zfs:tank/appdata@uso-backup-20261001-0200'] ?? [])]);

    $GLOBALS['snapshot'] = ['zfs' => $z, 'btrfs' => ['devices' => [], 'snapshots' => []], 'vm' => ['snapshots' => []]];
    foreach (['rename' => fn () => snapshotRename($copy['id'], 'mine'), 'hold' => fn () => snapshotHold($copy['id'], true),
              'release' => fn () => snapshotHold($copy['id'], false)] as $what => $fn) {
        try {
            $fn();
            check("snapshot partner: $what refused", false);
        } catch (Problem $p) {
            same("snapshot partner: $what refused — partner_copy, naming the pair", ['partner_copy', 'vault'], [$p->key, $p->params['partner'] ?? null]);
        }
    }
    @unlink("$tmp/zfs-args.txt");
    $r = snapshotDelete([$copy['id']]);
    same('snapshot partner: delete refused (a failure, nothing destroyed)', [['partner_copy'], [], false],
        [array_column($r['failures'], 'key'), $r['deleted'], str_contains((string) @file_get_contents("$tmp/zfs-args.txt"), 'destroy')]);
    same('snapshot partner: the estimate leaves it out', 0, snapshotEstimate([$copy['id']])['bytes']);
    try {
        snapshotCreate(['name' => 'manual-1', 'targets' => ["zfs:tank/$P/a1b2c3d4/share-appdata"]]);
        check('snapshot partner: create on a partner\'s copy refused', false);
    } catch (Problem $p) {
        same('snapshot partner: create on a partner\'s copy refused — partner_dataset', ['partner_dataset', "tank/$P/a1b2c3d4/share-appdata"], [$p->key, $p->params['target'] ?? null]);
    }
    same('snapshot partner: create never ran zfs snapshot', [], preg_grep('/^snapshot /', explode("\n", (string) @file_get_contents("$tmp/zfs-args.txt"))));
    $planFile = $GLOBALS['snapPlanFile'] ?? null;
    $GLOBALS['snapPlanFile'] = "$tmp/plans.json";
    try {
        snapPlanSave(['label' => 'Partner', 'cron' => '0 * * * *', 'targets' => ["zfs:tank/$P/a1b2c3d4/share-appdata"], 'keep' => 3]);
        check('snapshot partner: a schedule on a partner\'s copy refused', false);
    } catch (Problem $p) {
        same('snapshot partner: a schedule on a partner\'s copy refused — partner_dataset, nothing saved', ['partner_dataset', false], [$p->key, is_file("$tmp/plans.json")]);
    }
    if ($planFile === null) {
        unset($GLOBALS['snapPlanFile']);
    } else {
        $GLOBALS['snapPlanFile'] = $planFile;
    }
    $plan = ['id' => 'hourly', 'targets' => ['zfs:tank'], 'recursive' => true, 'keep' => 1, 'max_days' => 0];
    $doomed = snapPlanDoomed($plan, ['zfs:tank'], snapshotAll($GLOBALS['snapshot']), time(), ['uso-backup-']);
    same('snapshot partner: her plan\'s retention never touches a partner\'s copy (even named like her plan, under a recursive target)', [], $doomed);
    // a leftover of an ended pair: hers again (Ms. Dustdevil may put the dataset away, she may delete its snapshots)
    snapshotRefusePartner($left);
    check('snapshot partner: a leftover of an ended pair is not refused', true);
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/snapshot/lang/en.json'), true) ?: [];
    check('snapshot partner: the page can say it', isset($en['partner.copy'], $en['partner.left'], $en['errors.partner_copy'], $en['errors.partner_dataset'], $en['why.partner'], $en['help.partner']));
    same('snapshot partner: the chip says «partner\'s copy» (de «Kopie des Partners»)', ["partner's copy: vault", 'Kopie des Partners: vault'],
        [officeNotifyText('snapshot', 'partner.copy', ['name' => 'vault'], 'en'), officeNotifyText('snapshot', 'partner.copy', ['name' => 'vault'], 'de')]);
    $GLOBALS['snapshot'] = null;
    unset($GLOBALS['snapshotHost'], $GLOBALS['snapshotPartnerPairs']);
    if ($iniBefore === null) {
        unset($GLOBALS['disksIni']);
    } else {
        $GLOBALS['disksIni'] = $iniBefore;
    }
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Ms. Snapshotini and the entries a deleted VM left in Unraid's snapshot list (issue #3): an orphan only when the VM is gone
 * and nothing of any entry is left on disk (ZFS snapshot, overlay, .running/.mem), anything unsure is none; «Remove entry
 * from Unraid's list» moves the VM's folder into the storeroom in libvirt.img, «Put back» returns it — never over a VM again
 */
function testVmOrphans(): void
{
    $tmp = hardeningTmp('vmorph');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $db = "$tmp/qemu/snapshotdb";
    $xml = "$tmp/qemu";
    $trash = "$tmp/" . CL_TRASH;
    $pool = "$tmp/pool";
    foreach (["$db", "$pool/domains/GoneLeft", "$pool/domains/QemuFile", "$tmp/isos", "$tmp/elsewhere/Linked"] as $d) {
        @mkdir($d, 0755, true);
    }
    file_put_contents("$tmp/libvirt-sock", '');
    file_put_contents("$tmp/virsh", "#!/bin/sh\n[ \"\$1\" = list ] && printf 'Existing\\nOther VM\\n'\nexit 0\n");
    file_put_contents("$xml/Existing.xml", "<domain><name>Existing</name></domain>\n");
    file_put_contents("$tmp/isos/x.iso", 'iso');
    file_put_contents("$pool/domains/QemuFile/vdisk1.Q1qcow2", 'overlay');
    file_put_contents("$tmp/zfs-ds.txt", "tank\tfilesystem\t1000\t9000\t100\t50\t$pool\ntank/domains\tfilesystem\t500\t9000\t400\t100\t$pool/domains\n"
        . "tank/domains/GoneLeft\tfilesystem\t300\t9000\t300\t10\t$pool/domains/GoneLeft\n");
    file_put_contents("$tmp/zfs-snaps.txt", "tank/domains/GoneLeft@S3\t11\t1745000000\t10\t300\t5\t0\t-\n");
    file_put_contents("$tmp/zpool.txt", "tank\t8000000\t5000000\t3000000\t62\tONLINE\t16\nsleepy\t8000000\t5000000\t3000000\t62\tONLINE\t1\n");
    file_put_contents("$tmp/disks.ini", "[\"tank\"]\nname=\"tank\"\ntype=\"Cache\"\nfsType=\"zfs\"\nspundown=\"0\"\n[\"sleepy\"]\nname=\"sleepy\"\ntype=\"Cache\"\nfsType=\"zfs\"\nspundown=\"1\"\n");
    file_put_contents("$tmp/zfs", "#!/bin/sh\ncase \"\$1\" in\n  list)\n    file=snaps\n    for a in \"\$@\"; do [ \"\$a\" = filesystem,volume ] && file=ds; done\n"
        . "    cat " . escapeshellarg($tmp) . "/zfs-\$file.txt\n    exit 0;;\nesac\nexit 0\n");
    file_put_contents("$tmp/zpool", "#!/bin/sh\n[ \"\$1\" = list ] && cat " . escapeshellarg("$tmp/zpool.txt") . "\nexit 0\n");
    chmod("$tmp/zfs", 0755);
    chmod("$tmp/zpool", 0755);
    chmod("$tmp/virsh", 0755);
    $zfsEntry = fn (string $name, string $primary) => ['name' => $name, 'parent' => 'None', 'state' => 'shutoff', 'desc' => '', 'creationtime' => 1745000000,
                                                       'method' => 'ZFS', 'primarypath' => $primary];
    $qemuEntry = fn (string $name, string $overlay) => ['name' => $name, 'parent' => 'Base', 'state' => 'shutoff', 'creationtime' => 1745000000, 'method' => 'QEMU',
        'disks' => [['@attributes' => ['name' => 'hdc', 'snapshot' => 'external'], 'source' => ['@attributes' => ['file' => $overlay]]],
                    ['@attributes' => ['name' => 'hda'], 'source' => ['@attributes' => ['file' => "$tmp/isos/x.iso"]]]],
        'primarypath' => dirname($overlay)];
    $lists = [
        'Gone ZFS' => ['S20250420a' => $zfsEntry('S20250420a', "$pool/domains/Gone ZFS"), 'S20250420b' => $zfsEntry('S20250420b', "$pool/domains/Gone ZFS")],
        'GoneLeft' => ['S3' => $zfsEntry('S3', "$pool/domains/GoneLeft")],
        'Existing' => ['E1' => $qemuEntry('E1', "$pool/domains/Existing/vdisk1.E1qcow2")],
        'Mystery'  => ['M1' => ['method' => 'BTRFS'] + $zfsEntry('M1', "$pool/domains/Mystery")],
        'QemuGone' => ['G1' => $qemuEntry('G1', "$pool/domains/QemuGone/vdisk1.G1qcow2")],
        'QemuFile' => ['Q1' => $qemuEntry('Q1', "$pool/domains/QemuFile/vdisk1.Q1qcow2"), 'Q2' => $qemuEntry('Q2', "$pool/domains/QemuFile/vdisk1.Q2qcow2")],
        'Sleepy'   => ['Z1' => $zfsEntry('Z1', '/mnt/sleepy/domains/Sleepy')],
        'Nowhere'  => ['N1' => $zfsEntry('N1', '/uso-nowhere/domains/Nowhere')],
    ];
    foreach ($lists as $vm => $entries) {
        @mkdir("$db/$vm", 0755);
        file_put_contents("$db/$vm/snapshots.db", json_encode($entries, JSON_PRETTY_PRINT));
    }
    file_put_contents("$tmp/elsewhere/Linked/snapshots.db", json_encode(['L1' => $qemuEntry('L1', "$pool/domains/Linked/vdisk1.L1qcow2")]));
    symlink("$tmp/elsewhere/Linked", "$db/Linked");
    @mkdir("$db/Corrupt", 0755);
    file_put_contents("$db/Corrupt/snapshots.db", '{not json');

    $iniBefore = $GLOBALS['disksIni'] ?? null;
    $GLOBALS['disksIni'] = "$tmp/disks.ini";
    $GLOBALS['snapshotHost'] = ['zfs' => "$tmp/zfs", 'zpool' => "$tmp/zpool", 'docker' => null];
    $GLOBALS['snapshotVm'] = ['db' => $db, 'xml' => $xml, 'trash' => $trash, 'virsh' => "$tmp/virsh", 'sock' => "$tmp/libvirt-sock"];
    $GLOBALS['snapshot'] = null;

    $z = snapshotReadZfs(null, false);
    $v = snapshotReadVms($z);
    $folders = [];
    foreach ($v['folders'] as $f) {
        $folders[$f['vm']] = [$f['orphan'], $f['left'], array_map(fn ($u) => $u['why'] . ':' . $u['what'], $f['unsure'])];
    }
    ksort($folders);
    same('vm orphans: every deleted VM\'s list judged — orphan only with nothing on disk and nothing unsure', [
        'Gone ZFS' => [true, [], []],
        'GoneLeft' => [false, [['zfs' => 'tank/domains/GoneLeft@S3']], []],
        'Linked'   => [false, [], ["link:$db/Linked"]],
        'Mystery'  => [false, [], ['method:BTRFS']],
        'Nowhere'  => [false, [], ['no_dataset:/uso-nowhere/domains/Nowhere']],
        'QemuFile' => [false, [['file' => "$pool/domains/QemuFile/vdisk1.Q1qcow2"]], []],
        'QemuGone' => [true, [], []],
        'Sleepy'   => [false, [], ['asleep:sleepy']],
    ], $folders);
    $snap = array_column($v['snapshots'], null, 'id');
    same('vm orphans: the rows carry it — an orphan\'s entries unlistable, a sibling of a leftover not, an existing VM\'s untouched; the CD (hda) never counts',
        [true, true, false, [], null, false, null, false],
        [$snap['vm:Gone ZFS/S20250420a']['unlistable'] ?? null, $snap['vm:QemuGone/G1']['unlistable'] ?? null, $snap['vm:QemuFile/Q2']['unlistable'] ?? null,
         $snap['vm:QemuFile/Q2']['left'] ?? null, array_key_exists('unsure', $snap['vm:QemuFile/Q2'] ?? []) ? $snap['vm:QemuFile/Q2']['unsure'] : 'x', $snap['vm:Existing/E1']['orphaned'] ?? null,
         $snap['vm:Existing/E1']['unlistable'] ?? null, isset($snap['vm:Corrupt/x'])]);
    same('vm orphans: nothing in the storeroom yet', [], $v['away']);

    // a memory dump or a running VM's XML beside the folder is left too; a sleeping disk is never looked at
    @mkdir("$pool/domains/QemuGone", 0755);
    file_put_contents("$pool/domains/QemuGone/memoryG1.mem", 'mem');
    same('vm orphans: a memory dump left in the VM\'s folder counts', [['file' => "$pool/domains/QemuGone/memoryG1.mem"]],
        snapshotVmLeft($lists['QemuGone']['G1'], $z)['left']);
    unlink("$pool/domains/QemuGone/memoryG1.mem");
    same('vm orphans: on a sleeping disk unsure, an awake one looked at, a share\'s path spread over the bases', [null, false],
        [snapshotVmPathThere('/mnt/disk7/domains/x.mem', ['disk7' => true]), snapshotVmPathThere('/mnt/uso-no-such-pool/x', ['disk7' => true])]);
    same('vm orphans: no ZFS at all — unsure', ['no_zfs', []], [snapshotVmLeft($lists['GoneLeft']['S3'], null)['unsure']['why'] ?? null, snapshotVmLeft($lists['GoneLeft']['S3'], null)['left']]);

    // refusals: not an orphan, an existing VM, nothing of that name, a name that is none
    foreach (['GoneLeft' => 'vm_unlist_not_orphan', 'Existing' => 'vm_unlist_vm_there', 'Nobody' => 'vm_unlist_gone', 'Mystery' => 'vm_unlist_not_orphan'] as $vm => $key) {
        try {
            snapshotVmUnlist($vm);
            check("vm orphans: $vm refused", false);
        } catch (Problem $p) {
            same("vm orphans: $vm refused — $key", $key, $p->key);
        }
    }
    foreach (['../x', 'a/b', '', ' lead', "nl\n"] as $bad) {
        try {
            snapshotVmField(['vm' => $bad], 'vm');
            check('vm orphans: a name that is none refused: ' . json_encode($bad), false);
        } catch (Problem $p) {
            check('vm orphans: a name that is none refused: ' . json_encode($bad), in_array($p->key, ['bad_request', 'missing_field'], true));
        }
    }
    check('vm orphans: GoneLeft still in Unraid\'s list after the refusal', is_file("$db/GoneLeft/snapshots.db"));

    // the orphan goes: the whole folder into the storeroom, a manifest of Ms. Dustdevil's shape
    $r = snapshotVmUnlist('Gone ZFS');
    [$runPath, $as] = explode('|', $r['id'], 2);
    $manifest = readJson("$runPath/manifest.json") ?? [];
    $item = $manifest['items'][0] ?? [];
    same('vm orphans: «Remove entry from Unraid\'s list» — the folder in the storeroom, gone from the list, the manifest as she writes it',
        [true, 'snapshotdb/Gone ZFS', false, true, ['snapshotdb', 'Gone ZFS', "$db/Gone ZFS", ['S20250420a', 'S20250420b']], true],
        [$r['ok'], $as, file_exists("$db/Gone ZFS"), is_file("$runPath/$as/snapshots.db"), [$item['kind'] ?? null, $item['name'] ?? null, $item['from'] ?? null, $item['entries'] ?? null],
         clTrashAsOk($as, 'snapshotdb', basename($runPath))]);
    same('vm orphans: her state — no longer a list of hers, one in the storeroom with its two entries',
        [false, [['vm' => 'Gone ZFS', 'entries' => 2, 'vm_back' => false, 'taken' => false]]],
        [in_array('Gone ZFS', array_column($r['state']['vm']['folders'], 'vm'), true),
         array_map(fn ($a) => array_intersect_key($a, ['vm' => 1, 'entries' => 1, 'vm_back' => 1, 'taken' => 1]), $r['state']['vm']['away'])]);
    $id = $r['state']['vm']['away'][0]['id'] ?? '';

    // «Put back»: never while a VM of that name exists again, never over a list Unraid made meanwhile
    file_put_contents("$xml/Gone ZFS.xml", '<domain/>');
    try {
        snapshotVmRelist($id);
        check('vm orphans: put back refused while the VM exists again', false);
    } catch (Problem $p) {
        same('vm orphans: put back refused while the VM exists again — vm_relist_vm_back, nothing moved', ['vm_relist_vm_back', false], [$p->key, file_exists("$db/Gone ZFS")]);
    }
    unlink("$xml/Gone ZFS.xml");
    mkdir("$db/Gone ZFS");
    try {
        snapshotVmRelist($id);
        check('vm orphans: put back refused over a new list', false);
    } catch (Problem $p) {
        same('vm orphans: put back refused over a new list — vm_relist_taken', 'vm_relist_taken', $p->key);
    }
    rmdir("$db/Gone ZFS");
    try {
        snapshotVmRelist("$runPath|snapshotdb/../x");
        check('vm orphans: an id the storeroom doesn\'t list refused', false);
    } catch (Problem $p) {
        same('vm orphans: an id the storeroom doesn\'t list refused — vm_relist_gone', 'vm_relist_gone', $p->key);
    }
    // a manifest entry not of her shape (a «from» elsewhere) is never listed
    @mkdir("$trash/20260101-000000/snapshotdb/Fake", 0755, true);
    file_put_contents("$trash/20260101-000000/manifest.json", json_encode(['time' => 1, 'items' => [
        ['kind' => 'snapshotdb', 'name' => 'Fake', 'from' => '/etc/libvirt/qemu', 'as' => 'snapshotdb/Fake'],
        ['kind' => 'snapshotdb', 'name' => 'Up', 'from' => "$db/..", 'as' => 'snapshotdb/..']]]));
    same('vm orphans: only entries of her shape are listed', ['Gone ZFS'], array_column(snapshotVmAway(['Existing']), 'vm'));
    exec('rm -rf ' . escapeshellarg("$trash/20260101-000000"));
    // issue #7: a list put away into the storeroom of the old name is hers too
    $oldTrash = "$tmp/" . CL_TRASH_OLD;
    @mkdir("$oldTrash/20250101-000000/snapshotdb/Older", 0755, true);
    file_put_contents("$oldTrash/20250101-000000/snapshotdb/Older/snapshots.db", '{"a":1}');
    file_put_contents("$oldTrash/20250101-000000/manifest.json", json_encode(['time' => 2, 'items' => [['kind' => 'snapshotdb', 'name' => 'Older', 'from' => "$db/Older", 'as' => 'snapshotdb/Older']]]));
    same('vm orphans: a list in the storeroom of its old name (before issue #7) is listed too', ['Gone ZFS', 'Older'], array_column(snapshotVmAway(['Existing']), 'vm'));
    exec('rm -rf ' . escapeshellarg($oldTrash));

    $r = snapshotVmRelist($id);
    same('vm orphans: put back — in Unraid\'s list again, an orphan again, the run gone with the storeroom',
        [true, true, true, false, []],
        [$r['ok'], is_file("$db/Gone ZFS/snapshots.db"), in_array('Gone ZFS', array_column(array_filter($r['state']['vm']['folders'], fn ($f) => $f['orphan']), 'vm'), true),
         file_exists($runPath), $r['state']['vm']['away']]);

    // Ms. Dustdevil judges a snapshot list without its VM the same way: offered only as a true orphan
    $ctxBefore = $GLOBALS['clCtx'] ?? null;
    $GLOBALS['clCtx'] = ['roots' => [], 'asleep' => sleepingDisks()];
    @mkdir("$db/EmptyFolder", 0755);
    $lv = [];
    foreach (clLibvirtOrphans(['ok' => true, 'vms' => ['Existing' => ['name' => 'Existing', 'uuid' => null, 'nvram' => null]]]) as $o) {
        if ($o['kind'] === 'snapshotdb') {
            $lv[$o['name']] = [$o['vm_why'], $o['entries'], array_map(fn ($x) => $x['zfs'] ?? $x['file'], $o['left']), array_column($o['unsure'], 'why')];
        }
    }
    ksort($lv);
    same('vm orphans: Ms. Dustdevil — only true orphans offered; what is left named, unsure offers nothing; an existing VM\'s and a linked list never listed', [
        'Corrupt'     => ['vm_unsure', 0, [], ['unreadable']],
        'EmptyFolder' => [null, 0, [], []],
        'Gone ZFS'    => [null, 2, [], []],
        'GoneLeft'    => ['vm_left', 1, ['tank/domains/GoneLeft@S3'], []],
        'Mystery'     => ['vm_unsure', 1, [], ['method']],
        'Nowhere'     => ['vm_unsure', 1, [], ['no_dataset']],
        'QemuFile'    => ['vm_left', 2, ["$pool/domains/QemuFile/vdisk1.Q1qcow2"], []],
        'QemuGone'    => [null, 1, [], []],
        'Sleepy'      => ['vm_unsure', 1, [], ['asleep']],
    ], $lv);
    $zfsAsked = false;
    $GLOBALS['snapshotHost']['zfs'] = "$tmp/no-zfs-here";       // a list of QEMU entries only never asks ZFS
    $j = clSnapshotDbJudge("$db/QemuGone", $zfsAsked);
    same('vm orphans: Ms. Dustdevil lists ZFS only for a list of the ZFS method', [false, null], [$zfsAsked, $j['vm_why']]);
    $j = clSnapshotDbJudge("$db/Gone ZFS", $zfsAsked);
    same('vm orphans: … and ZFS that can\'t be asked is unsure, never an orphan', [null, 'vm_unsure', ['no_zfs']], [$zfsAsked, $j['vm_why'], array_column($j['unsure'], 'why')]);
    $GLOBALS['snapshotHost']['zfs'] = "$tmp/zfs";
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/cleanup.php');
    check('vm orphans: Ms. Dustdevil refuses to put away such a list (vm_left, vm_unsure) and passes the reason on to her page',
        str_contains($src, "'vm_left'       => new Problem('cleanup_vm_left'") && str_contains($src, "'vm_unsure'     => new Problem('cleanup_vm_unsure'")
        && str_contains($src, "\$why = \$vmf['ok'] ? (\$o['vm_why'] ?? null) : 'vm_off';"));
    rmdir("$db/EmptyFolder");
    if ($ctxBefore === null) {
        unset($GLOBALS['clCtx']);
    } else {
        $GLOBALS['clCtx'] = $ctxBefore;
    }

    // libvirt not running: nothing about VMs can be told — no folders, nothing removed
    unlink("$tmp/libvirt-sock");
    $v = snapshotReadVms($z);
    same('vm orphans: libvirt not running — no VM is gone, nothing judged', [[], false], [$v['folders'], (array_column($v['snapshots'], 'orphaned', 'id')['vm:QemuGone/G1'] ?? null)]);
    try {
        snapshotVmUnlist('QemuGone');
        check('vm orphans: refused without libvirt', false);
    } catch (Problem $p) {
        same('vm orphans: refused without libvirt — vm_unlist_vm_off', 'vm_unlist_vm_off', $p->key);
    }
    check('vm orphans: Ms. Dustdevil\'s «Put back» refuses a list whose VM exists again', str_contains((string) file_get_contents(OFFICE_DIR . '/agent/desks/cleanup.php'),
        "snapshotVmExists(basename(\$it['from']), snapshotVmDomains())"));
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/snapshot/lang/en.json'), true) ?: [];
    check('vm orphans: the page can say it', isset($en['unlist'], $en['why.vm_orphan'], $en['why.vm_left_zfs'], $en['help.vm_gone'], $en['away.title'], $en['errors.vm_relist_vm_back']));
    same('vm orphans: de says it as asked', ['Eintrag aus Unraids Liste entfernen', 'Zurückholen'],
        [officeNotifyText('snapshot', 'unlist', [], 'de'), officeNotifyText('snapshot', 'relist', [], 'de')]);

    $GLOBALS['snapshot'] = null;
    unset($GLOBALS['snapshotHost'], $GLOBALS['snapshotVm']);
    if ($iniBefore === null) {
        unset($GLOBALS['disksIni']);
    } else {
        $GLOBALS['disksIni'] = $iniBefore;
    }
    exec('rm -rf ' . escapeshellarg($tmp));
}

/** Ms. Dustdevil and what partners left: the leftovers of ended pairs, never while the door receives, her storeroom's shape, «Where is what» */
function testCleanupPartner(): void
{
    if (posix_geteuid() !== 0) {
        check('cleanup partner: root only (the pairs file is root\'s) — not run here', true);
        return;
    }
    $tmp = hardeningTmp('clean-partner');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    @mkdir("$tmp/run", 0700, true);
    $pairs = "$tmp/partner/pairs.json";
    partnerPairsWrite([partnerTestPair('a1b2c3d4', ['name' => 'vault'])], $pairs);
    $P = PARTNER_PARENT;
    $asked = [];
    $zfs = function (array $args) use (&$asked, $P): array {
        $asked[] = implode(' ', $args);
        return [0, "tank\t9000\t0\ntank/appdata\t500\t100\ntank/$P\t3000\t0\ntank/$P/a1b2c3d4\t1000\t0\ntank/$P/a1b2c3d4/share-appdata\t1000\t300\n"
            . "tank/$P/deadbeef\t1500\t0\ntank/$P/deadbeef/share-media\t1000\t200\ntank/$P/deadbeef/vm-Debian\t500\t50\ntank/$P/cafe0001\t400\t0\n"
            . "tank/$P/_UnraidSecretaryOffice-trash-20261008-101010-feed0002\t77\t7\ntank/$P/not-an-id\t1\t0\n"];
    };
    file_put_contents("$tmp/run/door-" . getmypid() . '.json', json_encode(['pid' => getmypid(), 'pair' => 'cafe0001', 'unit' => 'share:x', 'dataset' => "tank/$P/cafe0001/share-x", 'since' => time()]));
    $host = ['pools' => [['tank'], ['cold']], 'zfs' => $zfs, 'pairs' => $pairs, 'run' => "$tmp/run", 'alive' => fn (int $pid) => $pid === getmypid()];
    $r = clPartners($host);
    $list = array_column($r['list'], null, 'name');
    ksort($list);
    same('cleanup partner: the copies of ended pairs are leftovers — sized by zfs, their units; a pair of today\'s are not; asked only the awake pools',
        [['cafe0001', 'deadbeef'], [1500, 250, ['share:media', 'vm:Debian'], "tank/$P/deadbeef", 'leftover', null], ['list -Hp -t filesystem -o name,used,usedbysnapshots -d 3 tank'], ['cold']],
        [array_keys($list), [$list['deadbeef']['bytes'] ?? null, $list['deadbeef']['snaps'] ?? null, $list['deadbeef']['units'] ?? null, $list['deadbeef']['dataset'] ?? null,
         $list['deadbeef']['category'] ?? null, $list['deadbeef']['why'] ?? null], $asked, $r['asleep']]);
    same('cleanup partner: never while the door receives for that pair', 'transfer', $list['cafe0001']['why'] ?? null);
    same('cleanup partner: every dataset of the place is known (her storeroom\'s parked one too — never mounted)', [true, true, false],
        [isset($r['there']["tank/$P/_UnraidSecretaryOffice-trash-20261008-101010-feed0002"]), isset($r['there']["tank/$P/a1b2c3d4"]), isset($r['there']["tank/$P/a1b2c3d4/share-appdata"])]);
    same('cleanup partner: her storeroom\'s manifest — a partner\'s dataset only as <pool>/…-partners/<her name for it>', [true, false, false, false],
        [clTrashAsOk("@tank/$P/_UnraidSecretaryOffice-trash-20261008-101010-deadbeef", 'partner', '20261008-101010'),
         clTrashAsOk('@tank/appdata/_UnraidSecretaryOffice-trash-20261008-101010-deadbeef', 'partner', '20261008-101010'),
         clTrashAsOk("@tank/$P/deadbeef/_UnraidSecretaryOffice-trash-20261008-101010-x", 'partner', '20261008-101010'),
         clTrashAsOk("@tank/$P/_UnraidSecretaryOffice-trash-20261008-101010-deadbeef", 'appdata', '20261007-000000')]);
    same('cleanup partner: back only to where it was, under the partners\' place', ["/mnt/tank/$P", '', ''],
        [clPartnerHome(['dataset' => "tank/$P/deadbeef", 'from' => "/mnt/tank/$P/deadbeef"]), clPartnerHome(['dataset' => 'tank/appdata', 'from' => '/mnt/tank/appdata']),
         clPartnerHome(['dataset' => "tank/$P/deadbeef", 'from' => '/mnt/tank/elsewhere'])]);
    // a pair of today: a unit nothing came of for 30 days (1.60: the door takes any unit; one that stopped coming keeps its
    // snapshots for good) is dust — one received lately not, an odd child dataset not (not the door's name for a unit);
    // never while a transfer of the door names that unit
    $recFile = partnerDir() . '/received/a1b2c3d4.json';
    $recWas = @file_get_contents($recFile);
    partnerWritePrivate($recFile, ['pair' => 'a1b2c3d4', 'units' => ['share:appdata' => ['snap' => 'uso-backup-20261008-0200', 'bytes' => 1, 'seconds' => 1, 'time' => time() - 86400, 'snaps' => 3],
        'share:old' => ['snap' => 'uso-backup-20260901-0200', 'bytes' => 1, 'seconds' => 1, 'time' => time() - 40 * 86400, 'snaps' => 6]], 'used_bytes' => 1705, 'time' => time() - 86400]);
    $zfs2 = fn (array $args) => [0, "tank/$P\t3000\t0\ntank/$P/a1b2c3d4\t1705\t0\ntank/$P/a1b2c3d4/share-appdata\t1000\t300\n"
        . "tank/$P/a1b2c3d4/share-old\t600\t60\ntank/$P/a1b2c3d4/vm-Gone\t100\t10\ntank/$P/a1b2c3d4/odd_name\t5\t0\n"];
    file_put_contents("$tmp/run/door-4242.json", json_encode(['pid' => 4242, 'pair' => 'a1b2c3d4', 'unit' => 'vm:Gone', 'dataset' => "tank/$P/a1b2c3d4/vm-Gone", 'since' => time()]));
    $r2 = clPartners(['pools' => [['tank'], []], 'zfs' => $zfs2, 'pairs' => $pairs, 'run' => "$tmp/run", 'alive' => fn (int $pid) => in_array($pid, [getmypid(), 4242], true)]);
    $drop = array_column($r2['list'], null, 'id');
    ksort($drop);
    same('cleanup partner: a dropped unit of a pair of today listed (its used, its snapshots, «<unit> of <name>»), the kept one and an odd name not, the transfer guard per unit',
        [["partner:tank/a1b2c3d4/share-old", "partner:tank/a1b2c3d4/vm-Gone"],
         ['dropped', 'share:old', 'vault', "tank/$P/a1b2c3d4/share-old", 600, 60, null, 'share:old · vault'], ['vm:Gone', 'transfer']],
        [array_keys($drop), [$drop["partner:tank/a1b2c3d4/share-old"]['category'] ?? null, $drop["partner:tank/a1b2c3d4/share-old"]['unit'] ?? null,
          $drop["partner:tank/a1b2c3d4/share-old"]['pair_name'] ?? null, $drop["partner:tank/a1b2c3d4/share-old"]['dataset'] ?? null,
          $drop["partner:tank/a1b2c3d4/share-old"]['bytes'] ?? null, $drop["partner:tank/a1b2c3d4/share-old"]['snaps'] ?? null,
          array_key_exists('why', $drop["partner:tank/a1b2c3d4/share-old"] ?? []) ? $drop["partner:tank/a1b2c3d4/share-old"]['why'] : 'x', clLabel($drop["partner:tank/a1b2c3d4/share-old"] ?? ['kind' => '', 'name' => ''])],
         [$drop["partner:tank/a1b2c3d4/vm-Gone"]['unit'] ?? null, $drop["partner:tank/a1b2c3d4/vm-Gone"]['why'] ?? null]]);
    if ($recWas === false) {
        @unlink($recFile);
    } else {
        file_put_contents($recFile, $recWas);
    }
    same('cleanup partner: the guard names the unit — another unit of the pair, or another pair, isn\'t held up', [true, true, false, false],
        [clPartnerUnitBusy(partnerLookDoors("$tmp/run", fn (int $pid) => $pid === 4242), 'a1b2c3d4', 'vm:Gone', "tank/$P/a1b2c3d4/vm-Gone"),
         clPartnerUnitBusy([['pair' => 'a1b2c3d4', 'unit' => '', 'dataset' => "tank/$P/a1b2c3d4/vm-Gone/x"]], 'a1b2c3d4', 'vm:Gone', "tank/$P/a1b2c3d4/vm-Gone"),
         clPartnerUnitBusy(partnerLookDoors("$tmp/run", fn (int $pid) => $pid === 4242), 'a1b2c3d4', 'share:old', "tank/$P/a1b2c3d4/share-old"),
         clPartnerUnitBusy(partnerLookDoors("$tmp/run", fn (int $pid) => $pid === 4242), 'deadbeef', 'vm:Gone', "tank/$P/deadbeef/vm-Gone")]);
    @unlink("$tmp/run/door-4242.json");
    same('cleanup partner: a pair that keeps nothing here (receive null) and no record of it — nothing of it is dust (1.60: without a record nothing is known)', [],
        (function () use ($tmp, $zfs2) {
            $file = "$tmp/partner/pairs-noreceive.json";
            partnerPairsWrite([partnerTestPair('a1b2c3d4', ['name' => 'vault', 'receive' => null, 'their_key' => null])], $file);
            $ids = array_column(clPartners(['pools' => [['tank'], []], 'zfs' => $zfs2, 'pairs' => $file, 'run' => "$tmp/run"])['list'], 'id');
            sort($ids);
            return $ids;
        })());
    $unitTrash = "tank/$P/_UnraidSecretaryOffice-trash-20261008-101010-share-old-a1b2c3d4";
    same('cleanup partner: a unit put away lies in the partners\' place, the pair\'s id at the end — her manifest takes it, the way back only to that pair\'s unit',
        [true, true, true, false, false, false],
        [clTrashAsOk("@$unitTrash", 'partner', '20261008-101010'), clPartnerTrashOk($unitTrash, "tank/$P/a1b2c3d4/share-old"),
         clPartnerTrashOk("tank/$P/_UnraidSecretaryOffice-trash-20261008-101010-deadbeef", "tank/$P/deadbeef"),
         clPartnerTrashOk($unitTrash, "tank/$P/deadbeef/share-old"), clPartnerTrashOk($unitTrash, "cold/$P/a1b2c3d4/share-old"),
         clPartnerTrashOk("tank/$P/a1b2c3d4/_UnraidSecretaryOffice-trash-20261008-101010-share-old-a1b2c3d4", "tank/$P/a1b2c3d4/share-old")]);
    same('cleanup partner: a unit goes back only into its pair\'s dataset, only by the door\'s name for it', ["/mnt/tank/$P/a1b2c3d4", '', ''],
        [clPartnerHome(['dataset' => "tank/$P/a1b2c3d4/share-old", 'from' => "/mnt/tank/$P/a1b2c3d4/share-old"]),
         clPartnerHome(['dataset' => "tank/$P/a1b2c3d4/odd_name", 'from' => "/mnt/tank/$P/a1b2c3d4/odd_name"]),
         clPartnerHome(['dataset' => "tank/$P/a1b2c3d4/share-old/deeper", 'from' => "/mnt/tank/$P/a1b2c3d4/share-old/deeper"])]);
    // Ms. Snapshotini and the watchman's view: until it is put away it is the pair's copy (locked); put away, a leftover
    $marked = snapshotPartnerMark(['volumes' => [['name' => "tank/$P/a1b2c3d4/share-old"], ['name' => $unitTrash]], 'snapshots' => []], $pairs);
    same('cleanup partner: Ms. Snapshotini keeps her hands off a dropped unit until it is put away', [true, false],
        [snapshotPartnerLocked($marked['volumes'][0]), snapshotPartnerLocked($marked['volumes'][1])]);

    // «Where is what»: the partners' places with sizes per pair
    $GLOBALS['waPartnerHost'] = ['pools' => [['tank'], ['cold']], 'zfs' => $zfs, 'pairs' => $pairs];
    $w = waPartners();
    unset($GLOBALS['waPartnerHost']);
    $byId = array_column($w['places'][0]['pairs'] ?? [], null, 'id');
    same('cleanup where: the partners\' place per pool — its size, per pair name or ended, sizes, units; what lies in her storeroom; pools asleep',
        ["tank/$P", 3000, ['vault', false, 1000, ['share:appdata']], [null, true, 1500], 1, ['cold']],
        [$w['places'][0]['dataset'] ?? null, $w['places'][0]['used'] ?? null,
         [$byId['a1b2c3d4']['name'] ?? null, $byId['a1b2c3d4']['gone'] ?? null, $byId['a1b2c3d4']['used'] ?? null, $byId['a1b2c3d4']['units'] ?? null],
         [array_key_exists('name', $byId['deadbeef'] ?? []) ? $byId['deadbeef']['name'] : 'x', $byId['deadbeef']['gone'] ?? null, $byId['deadbeef']['used'] ?? null],
         $w['places'][0]['stored'] ?? null, $w['asleep']]);
    same('cleanup partner: a sleeping pool only — nothing asked', [[], 1], (function () use ($pairs, &$asked) {
        $asked = [];
        $none = function (array $a) use (&$asked) { $asked[] = $a; return [0, '']; };
        return [clPartners(['pools' => [[], ['tank']], 'zfs' => $none, 'pairs' => $pairs, 'run' => '/nonexistent'])['list'], count($asked) + 1];
    })());
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/cleanup/lang/en.json'), true) ?: [];
    check('cleanup partner: the page can say a dropped unit', isset($en['cat.partners.dropped'], $en['cat.partners.dropped_text'], $en['pa.dropped_text'])
        && str_contains($en['pa.dropped_name'] ?? '', '{unit}') && str_contains($en['pa.dropped_name'] ?? '', '{name}'));
    check('cleanup partner: the page can say it', isset($en['section.partners'], $en['cat.partners.leftover'], $en['park.text_partners'], $en['park.where_partners'],
        $en['item.partner'], $en['why.transfer'], $en['errors.cleanup_partner_transfer'], $en['where.partners.title'], $en['fact.partners'], $en['bubble.partners']));
    exec('rm -rf ' . escapeshellarg($tmp));
}

/** Ms. Protocolli reads the partner door's log (ids only, never paths): the data folder's, its older part, what it logged in RAM */
/**
 * Ms. Protocolli's saved filters (agent/desks/logs-filters.php, data/logs-filters.json): saved per list under a name
 * (what a bar has set, a preset kept as a preset — it stays relative), renamed and deleted by id; a bad name, nothing
 * set, a name twice in a list, too many, an unknown list, category, log, service or time refused with its reason — and nothing of
 * it kept; request fields read, never cast (a missing «only» or a time as text is bad_request); the file read in exactly
 * its shape, a rewrite keeps every entry and key it doesn't know (`open` too: never set here); the page gets them with
 * her state, with the server's last start and its time offset; a container's log has its last write.
 */
function testLogsFilters(): void
{
    $tmp = hardeningTmp('logsfilters');
    $file = "$tmp/filters.json";
    $GLOBALS['logsFiltersFile'] = $file;
    $refused = function (callable $f): string {
        try {
            $f();
            return '';
        } catch (Problem $p) {
            return $p->key;
        }
    };
    $req = fn (array $x = []): array => $x + ['words' => '', 'cat' => '', 'src' => '', 'svc' => '', 'only' => false, 'time' => '', 'from' => null, 'to' => null];
    $act = fn (string $action, array $r) => desks()['logs']['actions'][$action]($r);
    try {
        // refused with its reason, nothing kept
        same('logs filters: refused with its reason', ['logs_filter_name_empty', 'logs_filter_name_long', 'logs_filter_name_form', 'bad_request',
            'logs_filter_nothing', 'bad_request', 'bad_request', 'bad_request', 'logs_filter_range', 'logs_filter_range', 'logs_filter_words',
            'bad_request', 'bad_request'], [
            $refused(fn () => logsFilterSave('syslog', '   ', $req(['cat' => 'drive']))),
            $refused(fn () => logsFilterSave('syslog', str_repeat('ä', LOGS_FILTER_NAME + 1), $req(['cat' => 'drive']))),
            $refused(fn () => logsFilterSave('syslog', "Disks\ntoday", $req(['cat' => 'drive']))),
            $refused(fn () => logsFilterSave('nosuch', 'Disks', $req(['cat' => 'drive']))),
            $refused(fn () => logsFilterSave('syslog', 'Nothing', $req(['words' => '   ']))),
            $refused(fn () => logsFilterSave('syslog', 'Purple', $req(['cat' => 'purple']))),
            $refused(fn () => logsFilterSave('found', 'Up', $req(['src' => 'src:../x']))),
            $refused(fn () => logsFilterSave('syslog', 'Week', $req(['time' => 'week']))),
            $refused(fn () => logsFilterSave('syslog', 'Back', $req(['time' => 'range', 'from' => 2000000000, 'to' => 1900000000]))),
            $refused(fn () => logsFilterSave('syslog', 'Open', $req(['time' => 'range']))),
            $refused(fn () => logsFilterSave('syslog', 'Tab', $req(['words' => "a\tb"]))),
            $refused(fn () => logsFilterSave('syslog', 'Two words', $req(['svc' => 'php fpm']))),
            $refused(fn () => logsFilterSave('syslog', 'Pid', $req(['svc' => 'sshd[12]']))),
        ]);
        same('logs filters: request fields read, never cast — a missing «only», a time as text, a list as a number',
            ['bad_request', 'bad_request', 'missing_field', 'missing_field'], [
            $refused(fn () => $act('filter_save', array_diff_key($req(['list' => 'syslog', 'name' => 'X', 'cat' => 'drive']), ['only' => 1]))),
            $refused(fn () => $act('filter_save', $req(['list' => 'syslog', 'name' => 'X', 'time' => 'range', 'from' => '1900000000']))),
            $refused(fn () => $act('filter_save', $req(['list' => 5, 'name' => 'X', 'cat' => 'drive']))),
            $refused(fn () => $act('filter_rename', ['id' => 'a1b2c3d4e5f6'])),
        ]);
        check('logs filters: nothing refused was kept', !is_file($file));

        // saved per list, a preset as a preset, a range as seconds (either end open)
        $a = logsFilterSave('syslog', ' Disks today ', $req(['cat' => 'drive', 'time' => 'today']));
        $b = logsFilterSave('found', 'Samba', $req(['words' => ' smbd ', 'src' => 'src:syslog', 'time' => 'range', 'from' => 1900000000]));
        $c = logsFilterSave('read', 'Problems', $req(['only' => true, 'svc' => 'sshd-session']));
        same('logs filters: an id each', [true, true, true], array_map(fn ($x) => (bool) preg_match('/^[0-9a-f]{12}$/D', $x['id'] ?? ''), [$a, $b, $c]));
        same('logs filters: what the page gets — per list, the name trimmed, a preset stays a preset, open never set', [
            ['id' => $a['id'], 'list' => 'syslog', 'name' => 'Disks today', 'words' => '', 'cat' => 'drive', 'src' => '', 'svc' => '', 'only' => false, 'time' => ['preset' => 'today'], 'open' => false],
            ['id' => $b['id'], 'list' => 'found', 'name' => 'Samba', 'words' => 'smbd', 'cat' => '', 'src' => 'src:syslog', 'svc' => '', 'only' => false, 'time' => ['from' => 1900000000, 'to' => null], 'open' => false],
            ['id' => $c['id'], 'list' => 'read', 'name' => 'Problems', 'words' => '', 'cat' => '', 'src' => '', 'svc' => 'sshd-session', 'only' => true, 'time' => null, 'open' => false],
        ], logsFiltersForPage());
        same('logs filters: a name once per list (any case) — the same name in another list is fine',
            ['logs_filter_twice', ''], [$refused(fn () => logsFilterSave('syslog', 'disks TODAY', $req(['cat' => 'fs']))),
             $refused(fn () => logsFilterSave('varlog', 'Disks today', $req(['time' => 'boot'])))]);
        for ($i = count(array_filter(logsFiltersForPage(), fn ($f) => $f['list'] === 'varlog')); $i < LOGS_FILTER_MAX; $i++) {
            logsFilterSave('varlog', "Filter $i", $req(['words' => "w$i"]));
        }
        same('logs filters: at most LOGS_FILTER_MAX per list', ['logs_filter_full', ''], [$refused(fn () => logsFilterSave('varlog', 'One more', $req(['words' => 'x']))),
            $refused(fn () => logsFilterSave('docker', 'One more', $req(['words' => 'x'])))]);

        // rename and delete by id, as kept now
        logsFilterRename($a['id'], 'Disks, today');
        same('logs filters: renamed', 'Disks, today', array_column(logsFiltersForPage(), 'name', 'id')[$a['id']] ?? null);
        same('logs filters: rename — a name twice in its list, an id that isn\'t there, a bad name', ['logs_filter_twice', 'logs_filter_gone', 'logs_filter_name_empty'],
            [(function () use ($req, $a, $refused) { logsFilterSave('syslog', 'Network', $req(['cat' => 'network'])); return $refused(fn () => logsFilterRename($a['id'], 'network ')); })(),
             $refused(fn () => logsFilterRename('000000000000', 'X')), $refused(fn () => logsFilterRename($a['id'], ' '))]);
        same('logs filters: … another list\'s name is fine', '', $refused(fn () => logsFilterRename($a['id'], 'Samba')));
        logsFilterRemove($c['id']);
        same('logs filters: deleted, and again refused', [false, 'logs_filter_gone'], [in_array($c['id'], array_column(logsFiltersForPage(), 'id'), true),
            $refused(fn () => logsFilterRemove($c['id']))]);

        // exactly her shape; what she doesn't know stays in the file
        $raw = json_decode((string) file_get_contents($file), true);
        $raw['later'] = ['x' => 1];
        $raw['filters'][0]['later'] = 'kept';
        $raw['filters'][0]['open'] = true;
        $raw['filters'][] = 'junk';
        $raw['filters'][] = ['id' => 'abcdefabcdef', 'list' => 'elsewhere', 'name' => 'Not hers', 'words' => 'x'];
        $raw['filters'][] = ['id' => 'abcdefabcde0', 'list' => 'syslog', 'name' => 'A week', 'words' => '', 'cat' => '', 'src' => '', 'only' => false, 'time' => ['preset' => 'week']];
        $raw['filters'][] = ['id' => 'abcdefabcde1', 'list' => 'docker', 'name' => 'From before', 'words' => 'x', 'cat' => '', 'src' => '', 'only' => false, 'time' => null];
        file_put_contents($file, json_encode($raw));
        $page = logsFiltersForPage();
        same('logs filters: only entries in exactly her shape (a list, a time she doesn\'t know left out)', [$a['id'], $b['id']], array_slice(array_column($page, 'id'), 0, 2));
        check('logs filters: … none of the unknown ones', !array_intersect(['abcdefabcdef', 'abcdefabcde0'], array_column($page, 'id')));
        same('logs filters: an entry from before the services — read with none', '', array_column($page, 'svc', 'id')['abcdefabcde1'] ?? null);
        same('logs filters: `open` read (a later «apply when opening»), never set by her', [true, false], [$page[0]['open'], $page[1]['open']]);
        logsFilterRename($b['id'], 'Samba logs');
        $raw = json_decode((string) file_get_contents($file), true);
        $last = array_slice(array_values(array_filter($raw['filters'], fn ($f) => !is_array($f) || ($f['id'] ?? '') !== 'abcdefabcde1')), -3);
        same('logs filters: a rewrite keeps what she doesn\'t know — keys, entries, open', [['x' => 1], 'kept', true, 'junk', 'elsewhere', ['preset' => 'week'], 1],
            [$raw['later'] ?? null, $raw['filters'][0]['later'] ?? null, $raw['filters'][0]['open'] ?? null, $last[0], $last[1]['list'] ?? null, $last[2]['time'] ?? null, $raw['v'] ?? null]);
        file_put_contents($file, '{"filters": "nonsense", "later": 2}');
        same('logs filters: a list that isn\'t one is none', [], logsFiltersForPage());
        same('logs filters: … saving starts a new list, the other keys kept', [1, 2], (function () use ($req, $file) {
            logsFilterSave('docker', 'Mine', $req(['words' => 'x']));
            $raw = json_decode((string) file_get_contents($file), true);
            return [count(logsFiltersForPage()), $raw['later'] ?? null];
        })());

        // with her state: the server's last start, its offset; a container's log has its last write
        file_put_contents("$tmp/uptime", "3600.42 7000.00\n");
        same('logs filters: the last start from /proc/uptime (none when unreadable)', [true, null],
            [abs((logsBootTime("$tmp/uptime") ?? 0) - (time() - 3600)) <= 1, logsBootTime("$tmp/none")]);
        $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/logs.php');
        check('logs filters: her state brings them, the last start and the offset',
            str_contains($src, "'filters' => logsFiltersForPage(), 'boot' => logsBootTime(), 'tz' => (int) date('Z')]"));
        check('logs filters: a container\'s log with its last write (newest of its parts)', str_contains($src, "'time'     => \$time,")
            && str_contains($src, '$time = max($time ?? 0, (int) @filemtime($p)) ?: null;'));
        $en = langFile(OFFICE_WEB . '/desks/logs/lang/en.json');
        $keys = ['name_empty', 'name_long', 'name_form', 'words', 'range', 'nothing', 'twice', 'full', 'gone'];
        same('logs filters: a text for every reason', [], array_values(array_filter($keys, fn ($k) => !isset($en["errors.logs_filter_$k"]))));
    } finally {
        unset($GLOBALS['logsFiltersFile']);
        hardeningRm($tmp);
    }
}

/**
 * Ms. Protocolli's lists on the page (tests/logsfilters.js under node): every list's bar with a time filter, the time in
 * the note line, a saved filter applied by its click only, «Save filter…», rename / delete, a new visit empties every bar;
 * the order (newest / oldest / by service, named only when not the list's own) and a click on a line's service;
 * and in desk.js: «apply when opening» stays off, nothing of a filter in Office.store.
 */
function testLogsFiltersPage(): void
{
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/logs/desk.js');
    check('logs filters page: «apply when opening» is off (decided 2026-10-19: a page never opens with a hidden filter)', str_contains($js, 'const APPLY_ON_OPEN = false;'));
    check('logs filters page: the time filter and saved filters never in the browser\'s store', !preg_match("/Office\\.store(?:Json)?\\('logs\\.(?:time|saved|filter|only|query)/", $js));
    check('logs filters page: every bar emptied at a visit', str_contains($js, "Object.values(bars).forEach((b) => { b.reset(); b.time.clear(); b.svc = ''; });"));
    $node = testsNode();
    if ($node === '') {
        check('logs filters page: node is missing here - skipped', true);
        return;
    }
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg(OFFICE_DIR . '/tests/logsfilters.js') . ' '
        . escapeshellarg(OFFICE_WEB . '/assets/core.js') . ' ' . escapeshellarg(OFFICE_WEB . '/desks/logs/desk.js') . ' '
        . escapeshellarg(OFFICE_DIR . '/tests/ui/states') . ' 2>&1');
    $lines = array_values(array_filter(explode("\n", trim($raw))));
    $r = json_decode((string) end($lines), true);
    if (!is_array($r) || !isset($r['pass'], $r['fail'])) {
        check('logs filters page: ran under node', false, $raw);
        return;
    }
    check("logs filters page: her lists under node ({$r['pass']} checks)", $r['pass'] >= 54 && !$r['fail']);
    foreach ($r['fail'] as $f) {
        check('logs filters page: ' . ($f[0] ?? '?'), false, 'got ' . json_encode($f[1] ?? null) . ', want ' . json_encode($f[2] ?? null));
    }
}

function testLogsPartner(): void
{
    $made = [];
    foreach ([DATA_DIR . '/partner/door.log', RUN_DIR . '/partner/door.log'] as $f) {
        if (!is_dir(dirname($f))) {
            @mkdir(dirname($f), 0700, true);
            $made[] = dirname($f);
        }
        if (!is_file($f)) {
            file_put_contents($f, "2026-10-08 00:14:11  2ec7accd 192.168.20.111 refused unknown_verb: rm -rf\n");
            $made[] = $f;
        }
    }
    $s = logsSources();
    same('logs partner: the door\'s log and what it logged in RAM — the office\'s, files, labelled', [['office', 'partner_door', 'file'], ['office', 'partner_door_ram', 'file'], false],
        [[$s['partner:door']['group'] ?? null, $s['partner:door']['label'] ?? null, $s['partner:door']['kind'] ?? null],
         [$s['partner:door-ram']['group'] ?? null, $s['partner:door-ram']['label'] ?? null, $s['partner:door-ram']['kind'] ?? null], isset($s['partner:door.1'])]);
    foreach (['en', 'de', 'it', 'fr', 'es'] as $lang) {
        $l = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/logs/lang/$lang.json"), true) ?: [];
        check("logs partner: the source names ($lang)", isset($l['source.partner_door'], $l['source.partner_door_old'], $l['source.partner_door_ram']));
    }
    foreach (array_reverse($made) as $x) {
        is_dir($x) ? @rmdir($x) : @unlink($x);
    }
}

/** A router line in the shape Unraid's syslog server writes it (the header's local time), for testWatchmanNet() */
function netTestLine(int $t, string $body, string $host = 'gateway-1'): string
{
    return date('M', $t) . ' ' . str_pad(date('j', $t), 2, ' ', STR_PAD_LEFT) . date(' H:i:s', $t) . " $host $body\n";
}

/** A UniFi CEF body of 10.6.106's shape (`CEF: 0|`, UNIFIutcTime) */
function netTestCef(int $t, string $id, string $name, string $ext): string
{
    return "CEF: 0|Ubiquiti|UniFi Network|10.6.106|$id|$name|4|$ext UNIFIutcTime=" . gmdate('Y-m-d\TH:i:s', $t) . '.123Z';
}

/** The fixture's lines without their header (# …), each with its line end */
function netTestFixture(string $name): array
{
    $out = [];
    foreach (file(__DIR__ . "/fixtures/router/$name", FILE_IGNORE_NEW_LINES) ?: [] as $l) {
        if ($l !== '' && $l[0] !== '#') {
            $out[] = "$l\n";
        }
    }
    return $out;
}

/**
 * The night watchman reads the router (stage 1, UniFi only): Unraid's syslog server's files read by offset and inode,
 * the CEF and netfilter parsers on the real lines of a large server's gateway (scrubbed) and on lines built from the
 * documentation, every kind of the group `net`, the «other» count, values with spaces, the loop's file never read, his
 * own lines never counted, the cap, the privacy rule over every entry, the baseline, «I know, thanks», a chain, the
 * router's clock, silence; the Team Lead's six checks, the Consultant's look, Ms. Protocolli's sources, metrics.
 */
function testWatchmanNet(): void
{
    $tmp = hardeningTmp('watch-net');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $src = "$tmp/src";
    $data = "$tmp/data";
    $logs = "$tmp/syslog";
    foreach (['crontabs', 'cron.d', 'logplugins', 'atjobs', 'agents', 'extra', 'ssh/root', 'flash', 'net/br0', 'net/lo'] as $d) {
        @mkdir("$src/$d", 0700, true);
    }
    @mkdir($logs, 0777, true);
    $paths = ['syslog' => "$src/syslog", 'plugins' => "$src/logplugins", 'go' => "$src/go", 'extra' => "$src/extra", 'passwd' => "$src/passwd",
              'shadow' => "$src/shadow", 'ssh' => "$src/ssh", 'sec' => "$src/sec.ini", 'sec_nfs' => "$src/sec_nfs.ini", 'share_cfg' => "$src/share.cfg",
              'etc_passwd' => "$src/passwd", 'crontabs' => "$src/crontabs", 'cron_d' => "$src/cron.d", 'cron_files' => "$src/flash",
              'userscripts' => "$src/flash/user.scripts", 'atjobs' => "$src/atjobs", 'agents' => "$src/agents", 'ident' => "$src/ident.cfg",
              'rsyslog_cfg' => "$src/rsyslog.cfg", 'var_ini' => "$src/var.ini", 'disks_ini' => "$src/disks.ini", 'shares_ini' => "$src/shares.ini",
              'net_class' => "$src/net", 'arp' => "$src/arp", 'array_events' => "$src/array-events", 'logger' => null];
    unset($paths['logger']);
    file_put_contents($paths['passwd'], "root:x:0:0::/root:/bin/bash\n");
    file_put_contents($paths['go'], "#!/bin/bash\n");
    file_put_contents($paths['syslog'], '');
    file_put_contents("$src/cron.d/root", "*/1 * * * * /usr/local/emhttp/plugins/dynamix/scripts/monitor &> /dev/null\n");
    file_put_contents("$src/crontabs/root", "# nothing\n");
    file_put_contents($paths['ident'], "NAME=\"Tower\"\nUSE_SSH=\"yes\"\n");
    file_put_contents($paths['var_ini'], "fsState=\"Started\"\nspindownDelay=\"30\"\n");
    file_put_contents($paths['disks_ini'], "[\"maple\"]\nname=\"maple\"\ndevice=\"nvme0n1\"\nrotational=\"0\"\nspundown=\"0\"\ntype=\"Cache\"\nspindownDelay=\"0\"\nfsType=\"zfs\"\n"
        . "[\"hazel\"]\nname=\"hazel\"\ndevice=\"sdb\"\nrotational=\"1\"\nspundown=\"0\"\ntype=\"Cache\"\nspindownDelay=\"15\"\nfsType=\"zfs\"\n"
        . "[\"hazel2\"]\nname=\"hazel2\"\ndevice=\"sdc\"\nrotational=\"1\"\nspundown=\"1\"\ntype=\"Cache\"\nspindownDelay=\"15\"\n"
        . "[\"disk1\"]\nname=\"disk1\"\ndevice=\"sdd\"\nrotational=\"1\"\nspundown=\"0\"\ntype=\"Data\"\nspindownDelay=\"-1\"\nfsType=\"xfs\"\n");
    file_put_contents($paths['shares_ini'], "[\"syslog\"]\nname=\"syslog\"\nuseCache=\"only\"\ncachePool=\"maple\"\ncachePool2=\"\"\nexclusive=\"yes\"\n"
        . "[\"media\"]\nname=\"media\"\nuseCache=\"only\"\ncachePool=\"hazel\"\ncachePool2=\"\"\nexclusive=\"yes\"\n"
        . "[\"old\"]\nname=\"old\"\nuseCache=\"no\"\ncachePool=\"\"\ncachePool2=\"\"\nexclusive=\"no\"\n");
    file_put_contents("$src/net/br0/address", "02:00:00:00:00:20\n");
    file_put_contents("$src/net/lo/address", "00:00:00:00:00:00\n");
    file_put_contents($paths['arp'], "IP address       HW type     Flags       HW address            Mask     Device\n192.0.2.1        0x1         0x2         02:00:00:00:00:09     *        br0\n");
    file_put_contents($paths['rsyslog_cfg'], "local_server=\"1\"\nserver_protocol=\"udp\"\nserver_port=\"514\"\nserver_folder=\"$logs\"\nserver_filename=\"syslog-%FROMHOST-IP%.log\"\n"
        . "log_rotation=\"1\"\nlog_size=\"50M\"\nlog_files=\"4\"\nremote_server=\"\"\nremote_protocol=\"udp\"\nremote_port=\"\"\n");
    $GLOBALS['watchnetIfaces'] = ['lo' => ['unicast' => [['family' => 2, 'address' => '127.0.0.1'], ['family' => 10, 'address' => '::1']]],
                                  'br0' => ['unicast' => [['family' => 2, 'address' => '192.0.2.20'], ['family' => 10, 'address' => 'fe80::20']]]];
    $docker = fn () => [];
    $acks = "$tmp/acks.json";
    $gw = "$logs/syslog-192.0.2.1.log";
    $open = fn () => array_values(array_filter(watchmanLoad($data)['book'], 'watchmanOpen'));
    $byKind = function () use ($open): array {
        $out = [];
        foreach ($open() as $e) {
            if (str_starts_with($e['kind'], 'net_')) {
                $out[$e['kind']][] = $e;
            }
        }
        ksort($out);
        return $out;
    };
    $net = fn () => readJson("$data/net.json") ?? [];

    // ---- the parsers, on the real lines of a large server's gateway (scrubbed)
    $real = netTestFixture('unifi-10.6.106-real.log');
    $doc = netTestFixture('unifi-doc.log');
    $now = strtotime('2026-10-08 10:30:00');
    $p = watchnetParse(rtrim($real[0], "\n"), $now);
    $t = watchnetType($p);
    same('net parse: the real 544 «Network Accessed» (Audit, «CEF: 0|» with its space) — an admin login: admin, address, method, the version, UTC',
        ['cef', 'Ubiquiti', 'UniFi Network', '10.6.106', '544', 'Network Accessed', 'admin_login', 'admin-1', '192.0.2.136', 'web', strtotime('2026-10-08 07:18:55 UTC'), 'gateway-1'],
        [$p['kind'], $p['cef']['vendor'], $p['cef']['product'], $p['cef']['version'], $p['cef']['id'], $p['cef']['name'], $t['type'], $t['admin'], $t['ip'], $t['method'],
         $p['utc'], $p['host']]);
    same('net parse: the header\'s local time is the router\'s local time (09:18:55 CEST = 07:18:55 UTC)', strtotime('2026-10-08 09:18:55'), $p['th']);
    $p = watchnetParse(rtrim($real[2], "\n"), $now);
    same('net parse: values with spaces run to the next key (2h 24m, 18.35 MB, the alias)', ['2h 24m', '18.35 MB', 'device-1 00:02', 'Client Devices', 'Default'],
        [$p['x']['UNIFIduration'] ?? null, $p['x']['UNIFIusageDown'] ?? null, $p['x']['UNIFIclientAlias'] ?? null, $p['x']['UNIFIcategory'] ?? null, $p['x']['UNIFInetworkName'] ?? null]);
    same('net parse: 401 WiFi Client Disconnected — understood, nothing to say', 'client_other', watchnetType($p)['type']);
    $t = watchnetType(watchnetParse(rtrim($real[3], "\n"), $now));
    same('net parse: 400 WiFi Client Connected — the client\'s MAC, address, name, network', ['client', '02:00:00:00:00:02', '192.0.2.191', 'device-1 00:02', 'Default'],
        [$t['type'], $t['mac'], $t['ip'], $t['name'], $t['network']]);
    $p = watchnetParse(rtrim(netTestLine($now, netTestCef($now, '544', 'Network Accessed', 'UNIFIcategory=Audit UNIFIadmin=Admin One src=192.0.2.140 msg=Admin One accessed UniFi Network')), "\n"), $now);
    same('net parse: an admin\'s name with a space (the real line had one)', ['Admin One', '192.0.2.140'], [watchnetType($p)['admin'], watchnetType($p)['ip']]);
    $c = watchnetCef('CEF:0|Ubi\\|quiti|UniFi Network|10.6|1|a\\\\b|3|msg=x\\=y \\\\ z key2=v');
    same('net parse: CEF escapes — \\| and \\\\ in the header, \\= and \\\\ in values', ['Ubi|quiti', 'a\\b', 'x=y \\ z', 'v'],
        [$c['h']['vendor'] ?? null, $c['h']['name'] ?? null, $c['x']['msg'] ?? null, $c['x']['key2'] ?? null]);
    $nf = array_map(fn ($l) => watchnetParse(rtrim($l, "\n"), $now), array_values(array_filter($doc, fn ($l) => str_contains($l, 'kernel:'))));
    same('net parse: netfilter — [ZONE-ACTION-RULE] and [ZONE-RULE-ACTION], an uptime in front, zone/action/rule/addresses/ports as fields',
        [['LAN_OUT', 'D', '2000', '192.0.2.20', '203.0.113.9', 'TCP', 443], ['INTERNAL_EXTERNAL', 'R', '30001', '192.0.2.20', '203.0.113.200', 'UDP', 53]],
        array_map(fn ($x) => [$x['nf']['zone'], $x['nf']['action'], $x['nf']['rule'], $x['nf']['src'], $x['nf']['dst'], $x['nf']['proto'], $x['nf']['dpt']], array_slice($nf, 0, 2)));
    same('net parse: the concept\'s old sample [Block-Unraid-Out-1] is no tag — «other»', 'other',
        watchnetParse(rtrim(netTestLine($now, 'kernel: [Block-Unraid-Out-1]IN=br0 OUT=eth4 SRC=192.0.2.20 DST=203.0.113.9 PROTO=TCP SPT=1 DPT=2'), "\n"), $now)['kind']);
    same('net parse: a line nobody understands, a broken CEF, too long — «other»; his own SIEM line — never counted', ['other', 'other', 'other', 'own'],
        [watchnetParse(rtrim(end($doc), "\n"), $now)['kind'], watchnetParse('Oct  8 10:00:00 gw CEF: 0|Ubiquiti|broken', $now)['kind'],
         watchnetParse(str_repeat('x', WATCHNET_LINE_MAX + 1), $now)['kind'],
         watchnetParse('Oct  8 10:00:00 Tower uso-watchman[123]: {"v":1,"kind":"login_new_ip"}', $now)['kind']]);
    $types = array_map(fn ($l) => watchnetType(watchnetParse(rtrim($l, "\n"), $now))['type'] ?? 'other', array_slice($doc, 0, 9));
    same('net parse: the documentation\'s lines — wired client, three detections, a port forward and a WiFi change, VPN, update, WAN',
        ['client', 'detection', 'detection', 'detection', 'config', 'config', 'vpn', 'update', 'wan'], $types);
    same('net parse: the port forward is the firewall\'s, the WiFi change another setting', ['port_forward', null],
        [watchnetType(watchnetParse(rtrim($doc[4], "\n"), $now))['area'], watchnetType(watchnetParse(rtrim($doc[5], "\n"), $now))['area']]);

    // ---- his first round: the baseline (the gateway's history learned, the loop's file never read)
    file_put_contents($gw, implode('', $real));
    chmod($gw, 0666);
    file_put_contents("$logs/syslog-192.0.2.20.log", netTestLine($now - 60, netTestCef($now - 60, '544', 'Network Accessed', 'UNIFIcategory=Audit UNIFIadmin=intruder src=203.0.113.250')));
    file_put_contents("$logs/syslog-127.0.0.1.log", "Oct  8 10:00:00 Tower kernel: hello\n");
    file_put_contents("$logs/syslog-::ffff:192.0.2.20.log", "Oct  8 10:00:00 Tower kernel: hello\n");
    touch($gw, $now - 1800);
    $round = fn (int $t) => watchmanRound($paths, $data, 1000, $t, $docker, false, $acks);
    $r = $round($now);
    $b = watchmanLoad($data)['baseline']['net'] ?? [];
    same('net round 1: the baseline — nothing told; the gateway, its admin and address, its client learned',
        [[], ['192.0.2.1'], ['192.0.2.136'], ['02:00:00:00:00:02']],
        [array_values(array_filter($r['added'], fn ($k) => str_starts_with($k, 'net_'))), array_keys($b['senders'] ?? []), array_keys($b['admins']['admin-1']['ips'] ?? []),
         array_keys($b['devices'] ?? [])]);
    $n = $net();
    same('net round 1: the files of this server\'s own addresses (the loop: Remote syslog server pointing at itself; 127.0.0.1; the ::ffff: form) never read',
        [['127.0.0.1', '192.0.2.20'], ['192.0.2.1']], [(function ($x) { sort($x); return $x; })($n['look']['own'] ?? []), array_keys($n['pos'] ?? [])]);
    same('net round 1: lines read, his position at the file\'s end', [7, filesize($gw)], [(int) ($n['senders']['192.0.2.1']['lines'] ?? 0), (int) ($n['pos']['192.0.2.1']['size'] ?? 0)]);

    // ---- what the documentation says the gateway sends (and lines of our own) — every kind
    $t1 = $now + 300;
    $more = $doc;
    $more[] = netTestLine($t1 - 50, netTestCef($t1 - 50, '544', 'Network Accessed', 'UNIFIcategory=Audit UNIFIhost=gateway-1 UNIFIaccessMethod=web UNIFIadmin=admin-1 src=192.0.2.140 msg=admin-1 accessed UniFi Network using the web.'));
    $more[] = netTestLine($t1 - 49, netTestCef($t1 - 49, '544', 'Network Accessed', 'UNIFIcategory=Audit UNIFIadmin=Admin One src=192.0.2.136 msg=Admin One accessed UniFi Network'));
    $more[] = netTestLine($t1 - 40, netTestCef($t1 - 40, '400', 'WiFi Client Connected', 'UNIFIcategory=Client Devices UNIFIclientHostname=Tower UNIFIclientIp=192.0.2.66 UNIFIclientMac=02:00:00:00:00:66 UNIFIwifiName=wifi-1 msg=Tower connected'));
    $more[] = netTestLine($t1 - 39, netTestCef($t1 - 39, '402', 'Wired Client Connected', 'UNIFIcategory=Client Devices UNIFIclientHostname=box UNIFIclientIp=192.0.2.20 UNIFIclientMac=02:00:00:00:00:67 msg=box connected'));
    $more[] = netTestLine($t1 - 38, netTestCef($t1 - 38, '402', 'Wired Client Connected', 'UNIFIcategory=Client Devices UNIFIclientHostname=Tower UNIFIclientIp=192.0.2.20 UNIFIclientMac=02:00:00:00:00:20 msg=the server itself'));
    $more[] = netTestLine($t1 - 30, netTestCef($t1 - 30, '400', 'WiFi Client Connected', 'UNIFIcategory=Client Devices UNIFIclientAlias=device-1 00:02 UNIFIclientIp=192.0.2.191 UNIFIclientMac=00:11:22:33:44:55 msg=a known name'));
    $more[] = netTestLine($t1 - 29, netTestCef($t1 - 29, '400', 'WiFi Client Connected', 'UNIFIcategory=Client Devices UNIFIclientAlias=device-1 00:02 UNIFIclientIp=192.0.2.192 UNIFIclientMac=06:00:00:00:00:99 msg=a phone\'s new private address'));
    $more[] = 'Oct  8 10:29:00 Tower uso-watchman[555]: {"v":1,"kind":"net_spoof","text":"planted"}' . "\n";
    file_put_contents($gw, implode('', $more), FILE_APPEND);
    touch($gw, $t1 - 10);
    $r = $round($t1);
    $k = $byKind();
    same('net round 2: every kind from the router\'s lines',
        ['net_blocked_from_server' => 2, 'net_firewall_change' => 1, 'net_ips_server' => 2, 'net_new_device' => 3, 'net_router_login' => 2, 'net_spoof' => 2, 'net_vpn_login' => 1],
        array_map('count', $k));
    $dev = array_column($k['net_new_device'] ?? [], null, 'key');
    same('net new device: key MAC; learned at once; a known device\'s name on a vendor MAC is important, two made-up MACs are not',
        [['192.0.2.77', 'device-4', false], [true, '02:00:00:00:00:02'], [false], true],
        [[$dev['net_new_device:02:00:00:00:00:04']['p']['ip'] ?? null, $dev['net_new_device:02:00:00:00:00:04']['p']['name'] ?? null, !empty($dev['net_new_device:02:00:00:00:00:04']['important'])],
         [!empty($dev['net_new_device:00:11:22:33:44:55']['important']), $dev['net_new_device:00:11:22:33:44:55']['p']['taken'] ?? null],
         [!empty($dev['net_new_device:06:00:00:00:00:99']['important'])], isset(watchmanLoad($data)['baseline']['net']['devices']['02:00:00:00:00:04'])]);
    $spoof = array_column($k['net_spoof'] ?? [], null, 'key');
    same('net spoof: the server\'s name with another MAC, its address with another MAC — the server\'s own MAC is no spoof',
        [['name', 'tower', '02:00:00:00:00:66'], ['address', '192.0.2.20', '02:00:00:00:00:67']],
        [[$spoof['net_spoof:name:tower']['p']['what'] ?? null, $spoof['net_spoof:name:tower']['p']['name'] ?? null, $spoof['net_spoof:name:tower']['p']['mac'] ?? null],
         [$spoof['net_spoof:address:192.0.2.20']['p']['what'] ?? null, $spoof['net_spoof:address:192.0.2.20']['p']['ip'] ?? null, $spoof['net_spoof:address:192.0.2.20']['p']['mac'] ?? null]]);
    $login = array_column($k['net_router_login'] ?? [], null, 'key');
    same('net router login: a known admin from a new address, a new admin — learned per admin',
        [[false, '192.0.2.140'], [true, '192.0.2.136']],
        [[$login['net_router_login:192.0.2.1:admin-1:192.0.2.140']['p']['new_admin'] ?? null, $login['net_router_login:192.0.2.1:admin-1:192.0.2.140']['p']['ip'] ?? null],
         [$login['net_router_login:192.0.2.1:Admin One:192.0.2.136']['p']['new_admin'] ?? null, $login['net_router_login:192.0.2.1:Admin One:192.0.2.136']['p']['ip'] ?? null]]);
    $ips = array_column($k['net_ips_server'] ?? [], null, 'key');
    same('net IPS: against the server (in) and from it (out) — key signature and direction; the hit on another client only a count',
        [['in', '203.0.113.77', 3306], ['out', '203.0.113.66'], 1, 1, 1],
        [[$ips['net_ips_server:2010937:in']['p']['dir'] ?? null, $ips['net_ips_server:2010937:in']['p']['remote'] ?? null, $ips['net_ips_server:2010937:in']['p']['dpt'] ?? null],
         [$ips['net_ips_server:2030001:out']['p']['dir'] ?? null, $ips['net_ips_server:2030001:out']['p']['remote'] ?? null],
         ($s = watchmanPageState($data, $t1, false)['net'])['detections']['in'] ?? null, $s['detections']['out'] ?? null, $s['detections']['other'] ?? null]);
    $bl = array_column($k['net_blocked_from_server'] ?? [], null, 'key');
    same('net blocked from the server: per destination /24 and port; the WAN\'s own drops and another client\'s are not his',
        ['net_blocked_from_server:203.0.113.0/24 tcp/443', 'net_blocked_from_server:203.0.113.0/24 udp/53'], (function ($x) { sort($x); return $x; })(array_keys($bl)));
    $cfg = array_values(array_filter(watchmanLoad($data)['book'], fn ($e) => $e['kind'] === 'net_router_config'));
    same('net config: a WiFi change by a known admin — one line a day, noted by himself (by router); the port forward — net_firewall_change (important)',
        [1, 'router', false, 'port_forward', true], [count($cfg), $cfg[0]['by'] ?? null, isset($cfg[0]) && watchmanOpen($cfg[0]), $k['net_firewall_change'][0]['p']['area'] ?? null,
         WATCH_KINDS['net_firewall_change'][1]]);
    same('net vpn: a user not seen before from its remote address', ['vpn-user-1', '203.0.113.50', true],
        [$k['net_vpn_login'][0]['p']['user'] ?? null, $k['net_vpn_login'][0]['p']['ip'] ?? null, $k['net_vpn_login'][0]['p']['new_user'] ?? null]);
    $n = $net();
    $day = $n['days'][date('Y-m-d', $t1)]['192.0.2.1'] ?? [];
    same('net counts: the «other» line counted, his own planted line never; updates and the WAN dropped (counts only)', [1, 1, 1, 7 + count($more) - 1],
        [(int) ($day['other'] ?? -1), (int) ($day['c']['update'] ?? 0), (int) ($day['c']['wan'] ?? 0), (int) ($n['senders']['192.0.2.1']['lines'] ?? 0)]);
