    }
    $cfgFile(['server_folder' => $logs]);
    $a = watchnetAdvisor($o);
    same('net advisor: the senders with a file there, never the loop\'s', ['192.0.2.1', '192.0.2.105'], array_column((array) $a['senders'], 'sender'));
    $guide = "$tmp/advisor/network.json";
    advisorNetworkSeen($guide, $now);
    same('net advisor: the router guide opened — noted (root only) for the Team Lead', [$now, 0600], [watchnetGuideSeen($guide), fileperms($guide) & 0777]);

    // ---- Ms. Protocolli's sources: every sender's file (ids, never paths from a request), its rotated part; her tour skips .1
    $lf = watchnetLogFiles(['cfg' => $paths['rsyslog_cfg'], 'disks_ini' => $paths['disks_ini'], 'shares_ini' => $paths['shares_ini']]);
    same('net logs: router:<sender> and router.1:<sender> (an address may end in .1 itself) — the loop\'s file too (it is a log); the tour leaves .1 out',
        [true, true, true, false, true],
        [isset($lf['router:192.0.2.1']), isset($lf['router.1:192.0.2.1']), isset($lf['router:192.0.2.20']), logsTourWanted('router.1:192.0.2.1'), logsTourWanted('router:192.0.2.1')]);
    foreach (['en', 'de', 'it', 'fr', 'es'] as $lang) {
        $l = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/logs/lang/$lang.json"), true) ?: [];
        check("net logs: the source names ($lang)", isset($l['source.router'], $l['source.router_old']));
    }

    // ---- Mr. Backupsy's setup: the share Unraid's syslog server writes into is proposed «not backed up» (setup.sh's syslog_share())
    $sh = (string) file_get_contents(OFFICE_DIR . '/backup/setup.sh');
    $fn = preg_match('/^syslog_share\(\) \{.*?^\}$/ms', $sh, $m) ? $m[0] : '';
    $run = fn (string $cfg) => trim((string) shell_exec('bash -c ' . escapeshellarg($fn . "\nUB_RSYSLOG_CFG=" . escapeshellarg($cfg) . " syslog_share; echo \" \$?\"")));
    $cfgFile([]);
    file_put_contents("$tmp/off.cfg", "local_server=\"\"\nserver_folder=\"/mnt/user/syslog\"\n");
    same('net backup: setup.sh knows the syslog server\'s share (on), not when it is off', ['syslog 0', '1'], [$run($paths['rsyslog_cfg']), $run("$tmp/off.cfg")]);
    check('net backup: share_propose proposes it not backed up (why code syslog)', (bool) preg_match('/syslog_share\)" && \[\[ "\$s" == "\$sl" \]\]; then\s+why "\$s" syslog ""[^\n]*PROP_MODE=off/', $sh));
    $bl = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/en.json'), true) ?: [];
    check('net backup: the page says why', isset($bl['setup.why.syslog']));

    unset($GLOBALS['watchnetIfaces']);
    @unlink(watchmanLockFile($data, 'book'));
    @unlink(watchmanLockFile($data, 'round'));
    exec('rm -rf ' . escapeshellarg($tmp));
}

/** The type of the first fixture line holding $needle (after $from, a marker), for testWatchmanNetMikrotik() */
function netTestRos(array $lines, string $needle, int $now, string $from = ''): array
{
    $on = $from === '';
    foreach ($lines as $l) {
        $on = $on || str_contains($l, $from);
        if ($on && str_contains($l, $needle)) {
            $p = watchnetParse(rtrim($l, "\n"), $now);
            return ['p' => $p] + ($p['kind'] === 'other' ? ['type' => 'other'] : watchnetType($p));
        }
    }
    return ['type' => 'missing', 'p' => []];
}

/** The typed events between two markers of a fixture (logouts, unknown text and the lab's own lines left out) */
function netTestRosTypes(array $lines, string $from, string $to, int $now, array $skip = ['event', 'logout', 'other']): array
{
    $out = [];
    $on = false;
    foreach ($lines as $l) {
        if (str_contains($l, $from)) {
            $on = true;
            continue;
        }
        if ($on && str_contains($l, $to)) {
            break;
        }
        if ($on) {
            $p = watchnetParse(rtrim($l, "\n"), $now);
            $t = $p['kind'] === 'other' ? 'other' : watchnetType($p)['type'];
            if (!in_array($t, $skip, true)) {
                $out[] = $t;
            }
        }
    }
    return $out;
}

/**
 * The night watchman reads a MikroTik router (#2, package 1: the parser): real RouterOS 7.24.5 lines from the lab on
 * a test server (tests/fixtures/router/mikrotik-*.log) — every step of the lab's script typed (logins per channel, failures,
 * a second user's changes per area, links, leases, VPN, the firewall's prefixes, WAN loss by DHCP and PPPoE, reboots,
 * the upgrade line), the same events in the formats syslog / no topics / default / iso8601 / cef; in a round: UniFi
 * and MikroTik side by side, the existing kinds from RouterOS lines, the new types typed but no entry yet (package 2),
 * an unknown sender, a 1970 clock, overlong and hostile lines, the privacy rule.
 */
function testWatchmanNetMikrotik(): void
{
    $now = strtotime('2026-10-09 15:00:00');
    $main = netTestFixture('mikrotik-7.24.5-chr.log');
    $T = fn (string $needle, string $from = '') => netTestRos($main, $needle, $now, $from);

    // ---- every line of the main run: RouterOS's (typed or counted), only one line without topics (the format switch) «other»
    $kinds = [];
    foreach ($main as $l) {
        $kinds[watchnetParse(rtrim($l, "\n"), $now)['kind']][] = $l;
    }
    same('mikrotik parse: every line of the lab\'s main run is RouterOS\'s (typed or counted) — also the one without topics at the format switch',
        [['ros'], 578, 578], [array_keys($kinds), count($kinds['ros'] ?? []), count($main)]);

    // ---- step 2: logins per channel (confirmed on 7.24.5: local, ssh, api, rest-api, ftp, telnet)
    $logins = [];
    foreach (['via local', 'via ssh', 'via api', 'via rest-api', 'via ftp', 'via telnet'] as $via) {
        $t = $T("logged in from 10.77.3.1 $via", 'uso-step 2 logins');
        if ($via === 'via local') {
            $t = $T('user admin logged in via local', 'uso-step 2 logins');
        }
        $logins[] = [$t['type'], $t['admin'] ?? null, $t['ip'] ?? null, $t['method'] ?? null];
    }
    same('mikrotik login: «user admin logged in [from A] via C» — the console without an address',
        [['admin_login', 'admin', null, 'local'], ['admin_login', 'admin', '10.77.3.1', 'ssh'], ['admin_login', 'admin', '10.77.3.1', 'api'],
         ['admin_login', 'lab', '10.77.3.1', 'rest-api'], ['admin_login', 'admin', '10.77.3.1', 'ftp'], ['admin_login', 'admin', '10.77.3.1', 'telnet']], $logins);
    // (step 2's REST call reused the session of a minute before — RouterOS logs a REST login once per session, here lab\'s in step 4)
    $p = $T('logged in from 10.77.3.1 via ssh', 'uso-step 2 logins')['p'];
    same('mikrotik parse: syslog format — the header\'s identity, the topics, the router\'s time', ['ros', 'syslog', 'lab-chr', ['system', 'info', 'account'], strtotime('2026-10-09 13:41:19')],
        [$p['kind'], $p['fmt'], $p['host'], $p['topics'], $p['th']]);
    same('mikrotik login: REST\'s inner «user lab logged in via api» (no address, after the rest-api line) — understood, nothing to say; logouts likewise',
        ['event', 'logout'], [$T('user lab logged in via api')['type'], $T('user admin logged out from 10.77.3.1 via ssh')['type']]);

    // ---- step 3: failures — the burst, an unknown user, the console, a command typed as the user name (telnet)
    $fails = array_values(array_filter(array_map(fn ($l) => watchnetParse(rtrim($l, "\n"), $now), $main), fn ($p) => $p['kind'] === 'ros' && watchnetType($p)['type'] === 'login_fail'));
    $byMethod = [];
    foreach ($fails as $p) {
        $t = watchnetType($p);
        $byMethod[$t['method']] = ($byMethod[$t['method']] ?? 0) + 1;
    }
    ksort($byMethod);
    same('mikrotik failure: «login failure for user U [from A] via C» per channel (6 ssh in a burst + later ones), L2TP\'s «authentication failed»',
        ['api' => 2, 'ftp' => 1, 'l2tp' => 4, 'local' => 1, 'rest-api' => 2, 'ssh' => 9, 'telnet' => 2], $byMethod);
    $t = $T('login failure for user nosuchuser');
    $c = $T('login failure for user admin via local');
    $x = $T('login failure for user /system identity print');
    same('mikrotik failure: an unknown user, the console without address, a command as the user name — a name, nothing executed',
        [['nosuchuser', '10.77.3.1', 'ssh'], ['admin', null, 'local'], ['/system identity print', 'telnet']],
        [[$t['admin'], $t['ip'], $t['method']], [$c['admin'], $c['ip'], $c['method']], [$x['admin'], $x['method']]]);
    $v = $T('user alice authentication failed');
    same('mikrotik failure: L2TP «<10.9.9.20>: user alice authentication failed» — the peer\'s address, a VPN failure', ['login_fail', 'alice', '10.9.9.20', 'l2tp', true],
        [$v['type'], $v['admin'], $v['ip'], $v['method'], $v['vpn'] ?? null]);

    // ---- step 4: a second user's changes — the area by the object, who and from where, the message rebuilt
    $cfg = [];
    foreach (['filter rule added', 'filter rule changed', 'filter rule moved', 'filter rule removed', 'nat rule added', 'mangle rule added', 'raw rule added',
              'address list entry added', 'address added', 'system identity changed', 'device changed', 'user lab added'] as $n) {
        $t = $T("$n by", 'uso-step 4 second');
        $cfg[$n] = [$t['type'], array_key_exists('area', $t) ? $t['area'] : 'x', $t['admin'] ?? null, $t['ip'] ?? null, $t['how'] ?? null, $t['msg'] ?? null];
    }
    same('mikrotik config: «<object> <verb> by ssh-cmd:lab+ct@A[/action:n] (<command>)» — filter → firewall, nat → nat, mangle/raw/address list → policy, the rest a setting',
        ['filter rule added'        => ['config', 'firewall', 'lab', '10.77.3.1', 'ssh-cmd', 'filter rule added'],
         'filter rule changed'      => ['config', 'firewall', 'lab', '10.77.3.1', 'ssh-cmd', 'filter rule changed'],
         'filter rule moved'        => ['config', 'firewall', 'lab', '10.77.3.1', 'ssh-cmd', 'filter rule moved'],
         'filter rule removed'      => ['config', 'firewall', 'lab', '10.77.3.1', 'ssh-cmd', 'filter rule removed'],
         'nat rule added'           => ['config', 'nat', 'lab', '10.77.3.1', 'ssh-cmd', 'nat rule added'],
         'mangle rule added'        => ['config', 'policy', 'lab', '10.77.3.1', 'ssh-cmd', 'mangle rule added'],
         'raw rule added'           => ['config', 'policy', 'lab', '10.77.3.1', 'ssh-cmd', 'raw rule added'],
         'address list entry added' => ['config', 'policy', 'lab', '10.77.3.1', 'ssh-cmd', 'address list entry added'],
         'address added'            => ['config', null, 'lab', '10.77.3.1', 'ssh-cmd', 'address added'],
         'system identity changed'  => ['config', null, 'lab', '10.77.3.1', 'ssh-cmd', 'system identity changed'],
         'device changed'           => ['config', null, 'lab', '10.77.3.1', 'ssh-cmd', 'device changed'],
         'user lab added'           => ['config', null, 'admin', '10.77.3.1', 'ssh-cmd', 'user lab added']], $cfg);
    $r = $T('comment=lab-rest');
    $a = $T('comment=lab-api');
    same('mikrotik config: a REST change says «by api:lab@::» (no address), the API\'s «by api:lab@A»; the command never in the message',
        [['lab', null, 'api'], ['lab', '10.77.3.1', 'api'], false],
        [[$r['admin'], $r['ip'], $r['how']], [$a['admin'], $a['ip'], $a['how']], str_contains(json_encode(array_diff_key($T('nat rule added by'), ['p' => 1])), '10.9.9.15')]);
    same('mikrotik config: the identity changed — the header carries the new name at once; ether2 disabled by an admin logs NO link line',
        ['lab-chr-x', []], [$T('name=lab-chr-x)')['p']['host'], netTestRosTypes($main, 'set ether2 disabled=yes', 'set ether2 disabled=no', $now, ['event', 'logout', 'other', 'admin_login'])]);

    // ---- step 5: links from the hypervisor
    same('mikrotik link: «ether2 link down/up» (no speed on a CHR) — down/up ×4, the interface name',
        ['link', 'link', 'link', 'link', 'link', 'link', 'link', 'link'], netTestRosTypes($main, 'uso-step 5 link', 'uso-step 6 dhcp', $now, ['event', 'logout', 'other', 'admin_login']));
    $l = $T('ether2 link down', 'uso-step 5 link');
    same('mikrotik link: iface and up', ['ether2', false, true], [$l['iface'], $l['up'], $T('ether2 link up', 'uso-step 5 link')['up']]);

    // ---- step 6: the lease — MAC, address, host name, the DHCP server's name; deassigned understood
    $d = $T('lab-dhcp assigned');
    same('mikrotik lease: 7.24.5 «lab-dhcp assigned 10.9.9.20 for 52:54:00:4D:54:12 lab-client» (no lease time) — a client',
        ['client', '52:54:00:4d:54:12', '10.9.9.20', 'lab-client', 'lab-dhcp', 'client_other'],
        [$d['type'], $d['mac'], $d['ip'], $d['name'], $d['network'], $T('lab-dhcp deassigned')['type']]);

    // ---- step 7: WireGuard logs nothing per peer; L2TP's login
    same('mikrotik vpn: WireGuard\'s handshake — no line but the config lines (and the interface\'s link up)', ['link', 'config', 'config', 'config'],
        netTestRosTypes($main, 'uso-step 7a wireguard', 'uso-step 7b l2tp', $now, ['event', 'logout', 'other', 'admin_login']));
    $v = $T('alice logged in, 10.0.0.2 from 10.9.9.20');
    same('mikrotik vpn: «alice logged in, 10.0.0.2 from 10.9.9.20» (l2tp,ppp,info,account) — user, remote address, how; logged out understood',
        ['vpn', 'alice', '10.9.9.20', 'l2tp', 'logout'], [$v['type'], $v['user'], $v['ip'], $v['how'], $T('alice logged out, ')['type']]);

    // ---- step 8: the firewall — the prefix says drop, no prefix is no block
    $w = $T('drop-wan-in input:', 'uso-step 8a');
    same('mikrotik firewall: «drop-wan-in input: in:ether1 out:(unknown 0), connection-state:new src-mac …, proto TCP (SYN), A:p->B:q, len 60»',
        ['blocked', 'D', 'drop-wan-in', 'input', 'ether1', '', '10.77.1.1', '10.77.1.10', 'TCP', 2323],
        [$w['type'], $w['action'], $w['rule'], $w['zone'], $w['in'], $w['out'], $w['src'], $w['dst'], $w['proto'], $w['dpt']]);
    $f = $T('drop-from-server forward:');
    $u = $T('firewall,info input: in:ether1');
    $i = $T('connection-state:invalid');
    same('mikrotik firewall: forward ICMP (no ports), a log=yes rule without prefix (UDP) — no block, a forward UDP line',
        [['blocked', 'forward', '10.9.9.20', '10.77.1.1', 'ICMP', null, 'ether2', 'ether1'], ['nf_other', 'A', 'UDP', 5005], ['blocked', 'UDP', 33434]],
        [[$f['type'], $f['zone'], $f['src'], $f['dst'], $f['proto'], $f['dpt'], $f['in'], $f['out']], [$u['type'], $u['action'], $u['proto'], $u['dpt']],
         [$i['type'], $i['proto'], $i['dpt']]]);
    same('mikrotik firewall: the prefix\'s words — reject is R, «allow-ssh» or «counted» no block', ['R', 'nf_other', 'nf_other', 'D'],
        [watchnetRosFirewall('reject-from-guest forward: in:bridge out:ether1, proto TCP (SYN), 10.9.9.30:1->10.77.1.1:22, len 60')['action'],
         watchnetRosFirewall('allow-ssh input: in:ether1 out:(unknown 0), proto TCP (SYN), 10.77.1.1:1->10.77.1.10:22, len 60')['type'],
         watchnetRosFirewall('counted input: in:ether1 out:(unknown 0), proto TCP (SYN), 10.77.1.1:1->10.77.1.10:22, len 60')['type'],
         watchnetRosFirewall('WAN_BLOCKED input: in:ether1 out:(unknown 0), proto UDP, [2001:db8::5]:53->[2001:db8::1]:53, len 60')['action']]);

    // ---- step 9: the WAN — DHCP client and PPPoE
    $lost = $T('client1 on ether1 lost IP address');
    $got = $T('client1 on ether1 got IP address', 'uso-step 9 WAN');
    same('mikrotik wan: «client1 on ether1 lost IP address A - lease stopped locally» (dhcp,info — no warning) / «… got IP address A»',
        [['wan_down', 'ether1', 'dhcp', 'client1'], ['wan_up', 'ether1', 'dhcp']], [[$lost['type'], $lost['iface'], $lost['via'], $lost['client']], [$got['type'], $got['iface'], $got['via']]]);
    $pc = $T('pppoe-out1: connected');
    $pt = $T('pppoe-out1: terminating... - disconnected');
    $pa = $T('pppoe-out1: terminating... - administrator request');
    same('mikrotik wan: PPPoE «pppoe-out1: connected» / «terminating... - <reason>»; initializing/connecting/disconnected understood',
        [['wan_up', 'pppoe-out1', 'pppoe'], ['wan_down', 'disconnected'], ['wan_down', 'administrator request'], 'event', 'event'],
        [[$pc['type'], $pc['iface'], $pc['via']], [$pt['type'], $pt['reason']], [$pa['type'], $pa['reason']], $T('pppoe-out1: initializing...')['type'],
         $T('pppoe-out1: disconnected')['type']]);
    same('mikrotik wan: a server-side PPP session («<l2tp-alice>: connected») is no WAN', 'event', $T('<l2tp-alice>: connected')['type']);

    // ---- step 10: reboots and the clock
    $c = $T('router rebooted by ssh-cmd:admin+ct@10.77.3.1/reboot');
    $u = $T('router was rebooted without proper shutdown');
    same('mikrotik reboot: «router rebooted by <how>:<user>@A/reboot» (clean), «router was rebooted without proper shutdown» (unclean)',
        [['reboot', true, 'admin'], ['reboot', false]], [[$c['type'], $c['clean'], $c['by']], [$u['type'], $u['clean']]]);
    $s = $T('uso-clock-test 2026-09-30');
    same('mikrotik clock: «change time A => B» understood; the header follows the router\'s clock (Sep 30)', ['clock', strtotime('2026-09-30 13:59:43')],
        [$T('change time Oct/09/2026')['type'], $s['p']['th']]);

    // ---- step 12: the upgrade line names the version
    $up = netTestRos(netTestFixture('mikrotik-7.23.8-upgrade.log'), 'installed system-', $now);
    same('mikrotik upgrade: «installed system-7.24.5» — the only line with a version (no «upgraded from … to …»)', ['update', '7.24.5'], [$up['type'], $up['version']]);

    // ---- step 11: the same events in every format
    $block = fn (string $file, string $from, string $to) => netTestRosTypes(netTestFixture($file), $from, $to, $now);
    $want = ['admin_login', 'login_fail', 'admin_login', 'config', 'config', 'link', 'link', 'client_other', 'client', 'blocked', 'blocked', 'admin_login'];
    same('mikrotik formats: the step-11 repeat types alike — syslog without topics, default, iso8601, cef',
        [$want, $want, $want, $want],
        [$block('mikrotik-7.24.5-chr-notopics.log', 'add-topics-string=no: start', ': reboot'),
         $block('mikrotik-7.24.5-chr-default.log', 'default: start', 'default: reboot'),
         $block('mikrotik-7.24.5-chr-iso8601.log', 'iso8601 topics=yes: start', ': reboot'),
         $block('mikrotik-7.24.5-chr-cef.log', '11 cef: start', '11 cef: reboot')]);
    $nt = netTestRos(netTestFixture('mikrotik-7.24.5-chr-notopics.log'), 'login failure for user admin', $now)['p'];
    $df = netTestRos(netTestFixture('mikrotik-7.24.5-chr-default.log'), 'login failure for user admin', $now)['p'];
    $cf = netTestRos(netTestFixture('mikrotik-7.24.5-chr-cef.log'), 'msg=filter rule added', $now);
    same('mikrotik formats: no topics (identity kept), default (the address as host, Unraid\'s time), cef (topics from the name, the version, «#015» and \\= undone)',
        [['notopics', 'lab-chr', []], ['default', '10.77.3.10', ['system', 'error', 'critical']], ['cef', ['system', 'info'], '7.24.5', 'CHR QEMU Standard PC (i440FX + PIIX, 1996)', 'filter rule added', 'firewall']],
        [[$nt['fmt'], $nt['host'], $nt['topics']], [$df['fmt'], $df['host'], $df['topics']],
         [$cf['p']['fmt'], $cf['p']['topics'], $cf['p']['version'], $cf['p']['board'], $cf['msg'] ?? null, $cf['area'] ?? null]]);
    same('mikrotik formats: the default format\'s header is Unraid\'s time — the router\'s Sep 30 is not in it', strtotime('2026-10-09 14:07:18'),
        netTestRos(netTestFixture('mikrotik-7.24.5-chr-default.log'), 'uso-default-clock-test', $now)['p']['th']);

    // ---- shapes from the documentation the lab couldn't give (hardware, older 7.x): typed alike
    $doc = fn (string $body) => watchnetType(watchnetParse("Oct  9 10:00:00 router-1 $body", $now));
    $d1 = $doc('system,info filter rule added by admin');
    $d2 = $doc('interface,info ether1 link up (speed 1G, full duplex)');
    $d3 = $doc('system,info,critical RouterOS upgraded from 7.15 to 7.16');
    $d4 = $doc('pppoe,ppp,info pppoe-out1: terminating... - peer is not responding');
    $d5 = $doc('dhcp,warning dhcp-client on ether1 lost IP address 203.0.113.5 - lease stopped');
    same('mikrotik docs: «filter rule added by admin», a link with its speed, «RouterOS upgraded from … to …», «peer is not responding», «dhcp-client on … lost»',
        [['config', 'firewall', 'admin', ''], ['link', 'ether1', true], ['update', '7.16'], ['wan_down', 'peer is not responding'], ['wan_down', 'ether1', 'dhcp-client']],
        [[$d1['type'], $d1['area'], $d1['admin'], $d1['how']], [$d2['type'], $d2['iface'], $d2['up']], [$d3['type'], $d3['version']], [$d4['type'], $d4['reason']],
         [$d5['type'], $d5['iface'], $d5['client']]]);

    // ---- strangers and hostile lines: never RouterOS by accident, never more than a name
    same('mikrotik parse: lines that only look alike — a Linux kernel, an unknown facility, a topic list without severity, another vendor\'s «link up» — «other»',
        ['other', 'other', 'other', 'other'],
        [watchnetParse('Oct  9 10:00:00 nas kernel: eth0: Link is Up - 1Gbps/Full', $now)['kind'],
         watchnetParse('Oct  9 10:00:00 nas foo,info something happened', $now)['kind'],
         watchnetParse('Oct  9 10:00:00 nas system,account user admin logged in from 10.0.0.1 via ssh', $now)['kind'],
         watchnetParse('Oct  9 10:00:00 nas eth0 is up and running', $now)['kind']]);
    $h = watchnetType(watchnetParse("Oct  9 10:00:00 lab-chr system,info,account user {admin} \x1b[31m⟦Shares⟧ <b>x</b> logged in from 10.77.3.66 via ssh", $now));
    same('mikrotik hostile: placeholders, Unraid labels, HTML and escape bytes in a user name stay literal text (cleaned, capped at 64)',
        ['admin_login', '{admin}  [31m⟦Shares⟧ <b>x</b>', '10.77.3.66'], [$h['type'], $h['admin'], $h['ip']]);
    $long = watchnetType(watchnetParse('Oct  9 10:00:00 lab-chr system,info,account user ' . str_repeat('A', 200) . ' logged in from 10.77.3.66 via ssh', $now));
    same('mikrotik hostile: a name over 128 characters is no login line — understood as RouterOS text, nothing typed; a line over 8 KB «other»', ['event', 'other'],
        [$long['type'], watchnetParse('Oct  9 10:00:00 lab-chr system,info ' . str_repeat('x', WATCHNET_LINE_MAX), $now)['kind']]);
    $iface = watchnetType(watchnetParse('Oct  9 10:00:00 lab-chr interface,info <' . str_repeat('e', 40) . '/../x> link down', $now));
    same('mikrotik hostile: an interface name only [A-Za-z0-9._-], at most 32', ['link', true, 32],
        [$iface['type'], (bool) preg_match('/^[A-Za-z0-9._-]+$/D', (string) ($iface['iface'] ?? '')), strlen((string) ($iface['iface'] ?? ''))]);

    // ---- a round: UniFi and MikroTik side by side, an unknown sender, the existing kinds from RouterOS lines, the new types without entries
    $tmp = hardeningTmp('watch-net-mt');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $src = "$tmp/src";
    $data = "$tmp/data";
    $logs = "$tmp/syslog";
    foreach (['crontabs', 'cron.d', 'logplugins', 'atjobs', 'agents', 'extra', 'ssh/root', 'flash', 'net/br0', 'net/lo'] as $dir) {
        @mkdir("$src/$dir", 0700, true);
    }
    @mkdir($logs, 0777, true);
    $paths = ['syslog' => "$src/syslog", 'plugins' => "$src/logplugins", 'go' => "$src/go", 'extra' => "$src/extra", 'passwd' => "$src/passwd",
              'shadow' => "$src/shadow", 'ssh' => "$src/ssh", 'sec' => "$src/sec.ini", 'sec_nfs' => "$src/sec_nfs.ini", 'share_cfg' => "$src/share.cfg",
              'etc_passwd' => "$src/passwd", 'crontabs' => "$src/crontabs", 'cron_d' => "$src/cron.d", 'cron_files' => "$src/flash",
              'userscripts' => "$src/flash/user.scripts", 'atjobs' => "$src/atjobs", 'agents' => "$src/agents", 'ident' => "$src/ident.cfg",
              'rsyslog_cfg' => "$src/rsyslog.cfg", 'var_ini' => "$src/var.ini", 'disks_ini' => "$src/disks.ini", 'shares_ini' => "$src/shares.ini",
              'net_class' => "$src/net", 'arp' => "$src/arp", 'array_events' => "$src/array-events"];
    file_put_contents($paths['passwd'], "root:x:0:0::/root:/bin/bash\n");
    file_put_contents($paths['go'], "#!/bin/bash\n");
    file_put_contents($paths['syslog'], '');
    file_put_contents("$src/crontabs/root", "# nothing\n");
    file_put_contents($paths['ident'], "NAME=\"Tower\"\nUSE_SSH=\"yes\"\n");
    file_put_contents($paths['var_ini'], "fsState=\"Started\"\nspindownDelay=\"30\"\n");
    file_put_contents($paths['disks_ini'], "[\"maple\"]\nname=\"maple\"\ndevice=\"nvme0n1\"\nrotational=\"0\"\nspundown=\"0\"\ntype=\"Cache\"\nspindownDelay=\"0\"\nfsType=\"zfs\"\n");
    file_put_contents($paths['shares_ini'], "[\"syslog\"]\nname=\"syslog\"\nuseCache=\"only\"\ncachePool=\"maple\"\ncachePool2=\"\"\nexclusive=\"yes\"\n");
    // the server is the lab's fake client (10.9.9.20, its MAC): the guide's drop-from-server lines are the server's
    file_put_contents("$src/net/br0/address", "52:54:00:4d:54:12\n");
    file_put_contents("$src/net/lo/address", "00:00:00:00:00:00\n");
    file_put_contents($paths['arp'], "IP address       HW type     Flags       HW address            Mask     Device\n10.77.3.10       0x1         0x2         52:54:00:4d:54:03     *        br0\n");
    file_put_contents($paths['rsyslog_cfg'], "local_server=\"1\"\nserver_protocol=\"udp\"\nserver_port=\"514\"\nserver_folder=\"$logs\"\nserver_filename=\"syslog-%FROMHOST-IP%.log\"\n"
        . "log_rotation=\"1\"\nlog_size=\"50M\"\nlog_files=\"4\"\nremote_server=\"\"\nremote_protocol=\"udp\"\nremote_port=\"\"\n");
    $ifaces = $GLOBALS['watchnetIfaces'] ?? null;
    $GLOBALS['watchnetIfaces'] = ['lo' => ['unicast' => [['family' => 2, 'address' => '127.0.0.1']]], 'br0' => ['unicast' => [['family' => 2, 'address' => '10.9.9.20']]]];
    $acks = "$tmp/acks.json";
    $round = fn (int $t) => watchmanRound($paths, $data, 1000, $t, fn () => [], false, $acks);
    $added = fn (array $r) => array_values(array_filter($r['added'], fn ($k) => str_starts_with($k, 'net_')));
    $net = fn () => readJson("$data/net.json") ?? [];
    $mt = "$logs/syslog-10.77.3.10.log";
    $gw = "$logs/syslog-192.0.2.1.log";
    $cut = 0;
    foreach ($main as $i => $l) {
        if (str_contains($l, 'uso-step 4 second')) {
            $cut = $i;
            break;
        }
    }
    // round 1: steps 1–3 of the router and a large server's UniFi gateway — learned (admin from 10.77.3.1), nothing told
    file_put_contents($mt, implode('', array_slice($main, 0, $cut)));
    file_put_contents($gw, implode('', netTestFixture('unifi-10.6.106-real.log')));
    touch($mt, $now - 600);
    touch($gw, $now - 600);
    $r = $round($now);
    $n = $net();
    same('mikrotik round 1: both routers learned — nothing told; MikroTik by its lines (vendor, product, identity), UniFi as before',
        [[], ['MikroTik', 'RouterOS', 'lab-chr', true], ['Ubiquiti', 'UniFi Network']],
        [$added($r), [$n['senders']['10.77.3.10']['meta']['vendor'] ?? null, $n['senders']['10.77.3.10']['meta']['product'] ?? null,
                      $n['senders']['10.77.3.10']['meta']['host'] ?? null, !empty($n['senders']['10.77.3.10']['ros'])],
         [$n['senders']['192.0.2.1']['meta']['vendor'] ?? null, $n['senders']['192.0.2.1']['meta']['product'] ?? null]]);
    same('mikrotik round 1: the router\'s admin and address learned from its login lines', ['10.77.3.1'],
        array_keys(watchmanLoad($data)['baseline']['net']['admins']['admin']['ips'] ?? []));
    // round 2: the rest of the run (+ the upgrade's line, a new device's lease, a 1970 clock, an unknown sender, hostile lines)
    $t2 = $now + 600;
    $extra = [netTestLine($t2 - 60, 'dhcp,info lab-dhcp assigned 10.9.9.13 for 52:54:00:4D:54:77 guest-phone', 'lab-chr'),
              netTestLine($t2 - 50, 'system,info installed system-7.24.5', 'lab-chr'),
              'Jan  1 01:00:07 lab-chr system,info,account user admin logged in from 10.77.3.70 via winbox' . "\n",
              '1970-01-01T00:00:09Z lab-chr system,info,account user admin logged in from 10.77.3.71 via web' . "\n",
              netTestLine($t2 - 40, "system,info,account user {admin} ⟦Shares⟧ <b>x</b> logged in from 10.77.3.66 via ssh", 'lab-chr'),
              'Oct  9 15:09:00 lab-chr system,info ' . str_repeat('x', WATCHNET_LINE_MAX) . "\n"];
    file_put_contents($mt, implode('', array_slice($main, $cut)) . implode('', $extra), FILE_APPEND);
    file_put_contents("$logs/syslog-10.77.3.99.log", "Oct  9 15:05:00 nas kernel: eth0: Link is Up - 1Gbps/Full\nOct  9 15:05:01 nas smbd[123]: connection from 10.77.3.1\n");
    touch($mt, $t2 - 10);
    $r = $round($t2);
    $kinds = array_count_values($added($r));
    ksort($kinds);
    same('mikrotik round 2: the existing kinds from RouterOS lines — a new admin and addresses, firewall/NAT/policy changes, a new device, a VPN user, the server blocked, a new sender — and RouterOS\'s own (a port, two outages, an unclean restart: testWatchmanNetMikrotikBook)',
        ['net_blocked_from_server' => 2, 'net_firewall_change' => 3, 'net_link_down' => 1, 'net_new_device' => 1, 'net_outage' => 2, 'net_router_config' => 1,
         'net_router_login' => 4, 'net_router_reboot' => 1, 'net_sender_new' => 1, 'net_vpn_login' => 1], $kinds);
    $book = watchmanLoad($data)['book'];
    $by = [];
    foreach ($book as $e) {
        if (str_starts_with($e['kind'], 'net_')) {
            $by[$e['kind']][$e['key']] = $e;
        }
    }
    same('mikrotik round 2: firewall changes per area (filter → firewall, nat, mangle/raw/address list → policy), the admin «lab»',
        ['net_firewall_change:10.77.3.10:firewall', 'net_firewall_change:10.77.3.10:nat', 'net_firewall_change:10.77.3.10:policy'],
        (function ($x) { sort($x); return $x; })(array_keys($by['net_firewall_change'] ?? [])));
    same('mikrotik round 2: logins — «lab» new, the 1970 and hostile ones keyed by their address; the router named by its identity',
        ['net_router_login:10.77.3.10:admin:10.77.3.70', 'net_router_login:10.77.3.10:admin:10.77.3.71', 'net_router_login:10.77.3.10:lab:10.77.3.1',
         'net_router_login:10.77.3.10:{admin} ⟦Shares⟧ <b>x</b>:10.77.3.66'],
        (function ($x) { sort($x); return $x; })(array_keys($by['net_router_login'] ?? [])));
    $old = $by['net_router_login']['net_router_login:10.77.3.10:admin:10.77.3.70'] ?? [];
    same('mikrotik clock: a 1970 header (and an ISO one) — the event\'s time is its arrival, not 1970', [$t2, $t2, 'lab-chr'],
        [(int) ($old['time'] ?? 0), (int) ($by['net_router_login']['net_router_login:10.77.3.10:admin:10.77.3.71']['time'] ?? 0), $old['p']['router'] ?? null]);
    $hostile = $by['net_router_login']['net_router_login:10.77.3.10:{admin} ⟦Shares⟧ <b>x</b>:10.77.3.66'] ?? [];
    $text = json_encode(watchmanText($hostile, 'en'), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    same('mikrotik hostile: «{admin} ⟦Shares⟧ <b>x</b>» stays a literal value in the entry and its words (never a template)', [true, '{admin} ⟦Shares⟧ <b>x</b>'],
        [str_contains($text, '{admin} ⟦Shares⟧ <b>x</b>'), $hostile['p']['admin'] ?? null]);
    $dev = $by['net_new_device']['net_new_device:52:54:00:4d:54:77'] ?? [];
    $bl = array_keys($by['net_blocked_from_server'] ?? []);
    sort($bl);
    same('mikrotik round 2: the lease of a new MAC (name, address, the DHCP server) — the server\'s own lease no device; the drop-from-server lines keyed',
        [['guest-phone', '10.9.9.13', 'lab-dhcp'], false, ['net_blocked_from_server:10.77.1.0/24 icmp', 'net_blocked_from_server:10.77.1.0/24 udp/33434']],
        [[$dev['p']['name'] ?? null, $dev['p']['ip'] ?? null, $dev['p']['network'] ?? null], isset($by['net_new_device']['net_new_device:52:54:00:4d:54:12']), $bl]);
    $vpn = array_values($by['net_vpn_login'] ?? [])[0] ?? [];
    same('mikrotik round 2: the VPN user from its remote address', ['alice', '10.9.9.20', 'l2tp'], [$vpn['p']['user'] ?? null, $vpn['p']['ip'] ?? null, $vpn['p']['how'] ?? null]);
    same('mikrotik round 2: the failures were in round 1 (learned: no entry); ether2\'s link, the DHCP and PPPoE outages, the restarts — and the new types counted per day',
        [['net_link_down:10.77.3.10:ether2:2026-10-09', 'net_outage:10.77.3.10:ether1:2026-10-09', 'net_outage:10.77.3.10:pppoe-out1:2026-10-09',
          'net_router_reboot:10.77.3.10:' . strtotime('2026-10-09 13:58:01'), 'net_router_reboot:10.77.3.10:2026-10-09'], true, true, true, true, true],
        [(function ($x) { sort($x); return $x; })(array_column(array_filter($book, fn ($e) => preg_match('/fail|link|outage|reboot/', $e['kind'])), 'key')),
         ($n2 = $net())['days'][date('Y-m-d', $t2)]['10.77.3.10']['c']['login_fail'] > 5, $n2['days'][date('Y-m-d', $t2)]['10.77.3.10']['c']['link'] > 5,
         $n2['days'][date('Y-m-d', $t2)]['10.77.3.10']['c']['wan_down'] > 5, $n2['days'][date('Y-m-d', $t2)]['10.77.3.10']['c']['reboot'] >= 4,
         ($n2['days'][date('Y-m-d', $t2)]['10.77.3.10']['other'] ?? 0) >= 1]);
    same('mikrotik round 2: the version from «installed system-7.24.5», kept; the formats seen; the unknown sender all «other»',
        ['7.24.5', ['syslog', 'notopics'], 2, 2, null],
        [$n2['senders']['10.77.3.10']['meta']['version'] ?? null, array_keys($n2['senders']['10.77.3.10']['fmt'] ?? []),
         (int) ($n2['days'][date('Y-m-d', $t2)]['10.77.3.99']['lines'] ?? 0), (int) ($n2['days'][date('Y-m-d', $t2)]['10.77.3.99']['other'] ?? 0),
         $n2['senders']['10.77.3.99']['meta']['vendor'] ?? null]);
    file_put_contents($mt, netTestLine($t2 + 100, 'system,info,account user admin logged in from 10.77.3.1 via ssh', 'lab-chr'), FILE_APPEND);
    touch($mt, $t2 + 110);
    $round($t2 + 300);
    same('mikrotik round 3: a round without a version line — the version kept', '7.24.5', $net()['senders']['10.77.3.10']['meta']['version'] ?? null);

    // ---- the privacy rule over every entry: another client's address, MAC or name only in net_new_device
    $bystander = ['10.9.9.13', '52:54:00:4d:54:77', '52:54:00:4D:54:77', 'guest-phone', '10.0.0.2', '10.9.9.15'];
    $leaks = [];
    foreach (watchmanLoad($data)['book'] as $e) {
        if (!str_starts_with($e['kind'], 'net_') || in_array($e['kind'], ['net_new_device', 'net_spoof'], true)) {
            continue;
        }
        $blob = json_encode($e['p'], JSON_UNESCAPED_UNICODE) . json_encode(watchmanText($e, 'en'), JSON_UNESCAPED_UNICODE);
        foreach ($bystander as $x) {
            if (str_contains($blob, $x)) {
                $leaks[] = "{$e['kind']}: $x";
            }
        }
        if (mb_strlen((string) ($e['p']['evidence'] ?? '')) > WATCHNET_EVIDENCE) {
            $leaks[] = "{$e['kind']}: evidence too long";
        }
    }
    same('mikrotik privacy: no other client\'s address, MAC or name in any other entry or its words (the VPN\'s inner address, a NAT target never); evidence ≤ 300', [], $leaks);
    $fw = array_values($by['net_firewall_change'] ?? [])[0] ?? [];
    same('mikrotik evidence: rebuilt from the type\'s fields — the change and who, never the command; the device\'s MAC by its first half',
        [true, false, true, false], [(bool) preg_match('/(?:rule|entry) (?:added|changed|moved|removed) by (?:ssh-cmd|api):(?:lab|admin)/', (string) ($fw['p']['evidence'] ?? '')), str_contains((string) ($fw['p']['evidence'] ?? ''), '/ip firewall'),
         str_contains((string) ($dev['p']['evidence'] ?? ''), '52:54:00:…'), str_contains((string) ($dev['p']['evidence'] ?? ''), '52:54:00:4d:54:77')]);
    $GLOBALS['watchnetIfaces'] = $ifaces;
}

/** The lines of a fixture from the one holding $from up to (not with) the one holding $to ('' = to the end) */
function netTestSlice(array $lines, string $from, string $to = ''): array
{
    $out = [];
    $on = false;
    foreach ($lines as $l) {
        if (!$on && str_contains($l, $from)) {
            $on = true;
        } elseif ($on && $to !== '' && str_contains($l, $to)) {
            break;
        }
        if ($on) {
            $out[] = $l;
        }
    }
    return $out;
}

/**
 * The watch book's MikroTik kinds (#2, package 2) over the lab's real lines (and lines of their exact shape at chosen
 * times): a burst of failed router logins (one entry per router and address, the names tried only when they are admins,
 * the console's single failure a count, an address learned for failing or noted with «I know, thanks» only counted), a
 * port losing its link (closed by himself when it is back, opened again, flapping told once; the loopback, virtual ups
 * and the WAN ports no entry), the internet away (open over two rounds and closed with its minutes, a short one noted by
 * himself, a second loss that day on the same entry making it long, one still away after 30 minutes told while it
 * lasts, one whose closing line never came closed after a day; PPPoE's retries one loss, its carrier port no link
 * entry, «administrator request» none), the router restarted (clean: a plain line a day, unclean: told — and joined with
 * the server's own start as a power loss), their words in every language, the privacy rule, the Team Lead's hint for a
 * MikroTik without topics.
 */
function testWatchmanNetMikrotikBook(): void
{
    $main = netTestFixture('mikrotik-7.24.5-chr.log');
    $at = fn (string $hm) => strtotime("2026-10-09 $hm");
    $L = fn (string $hm, string $body) => netTestLine(strtotime("2026-10-09 $hm"), $body);
    $tmp = hardeningTmp('watch-net-mtb');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $src = "$tmp/src";
    $data = "$tmp/data";
    $logs = "$tmp/syslog";
    foreach (['crontabs', 'cron.d', 'logplugins', 'atjobs', 'agents', 'extra', 'ssh/root', 'flash', 'net/br0', 'net/lo'] as $dir) {
        @mkdir("$src/$dir", 0700, true);
    }
    @mkdir($logs, 0777, true);
    $paths = ['syslog' => "$src/syslog", 'plugins' => "$src/logplugins", 'go' => "$src/go", 'extra' => "$src/extra", 'passwd' => "$src/passwd",
              'shadow' => "$src/shadow", 'ssh' => "$src/ssh", 'sec' => "$src/sec.ini", 'sec_nfs' => "$src/sec_nfs.ini", 'share_cfg' => "$src/share.cfg",
              'etc_passwd' => "$src/passwd", 'crontabs' => "$src/crontabs", 'cron_d' => "$src/cron.d", 'cron_files' => "$src/flash",
              'userscripts' => "$src/flash/user.scripts", 'atjobs' => "$src/atjobs", 'agents' => "$src/agents", 'ident' => "$src/ident.cfg",
              'rsyslog_cfg' => "$src/rsyslog.cfg", 'var_ini' => "$src/var.ini", 'disks_ini' => "$src/disks.ini", 'shares_ini' => "$src/shares.ini",
              'net_class' => "$src/net", 'arp' => "$src/arp", 'array_events' => "$src/array-events"];
    file_put_contents($paths['passwd'], "root:x:0:0::/root:/bin/bash\n");
    file_put_contents($paths['go'], "#!/bin/bash\n");
    file_put_contents($paths['syslog'], '');
    file_put_contents("$src/crontabs/root", "# nothing\n");
    file_put_contents($paths['ident'], "NAME=\"Tower\"\nUSE_SSH=\"yes\"\n");
    file_put_contents($paths['var_ini'], "fsState=\"Started\"\nspindownDelay=\"30\"\n");
    file_put_contents($paths['disks_ini'], "[\"maple\"]\nname=\"maple\"\ndevice=\"nvme0n1\"\nrotational=\"0\"\nspundown=\"0\"\ntype=\"Cache\"\nspindownDelay=\"0\"\nfsType=\"zfs\"\n");
    file_put_contents($paths['shares_ini'], "[\"syslog\"]\nname=\"syslog\"\nuseCache=\"only\"\ncachePool=\"maple\"\ncachePool2=\"\"\nexclusive=\"yes\"\n");
    file_put_contents("$src/net/br0/address", "52:54:00:4d:54:12\n");
    file_put_contents("$src/net/lo/address", "00:00:00:00:00:00\n");
    file_put_contents($paths['arp'], "IP address       HW type     Flags       HW address            Mask     Device\n10.77.3.10       0x1         0x2         52:54:00:4d:54:03     *        br0\n");
    file_put_contents($paths['rsyslog_cfg'], "local_server=\"1\"\nserver_protocol=\"udp\"\nserver_port=\"514\"\nserver_folder=\"$logs\"\nserver_filename=\"syslog-%FROMHOST-IP%.log\"\n"
        . "log_rotation=\"1\"\nlog_size=\"50M\"\nlog_files=\"4\"\nremote_server=\"\"\nremote_protocol=\"udp\"\nremote_port=\"\"\n");
    $ifaces = $GLOBALS['watchnetIfaces'] ?? null;
    $GLOBALS['watchnetIfaces'] = ['lo' => ['unicast' => [['family' => 2, 'address' => '127.0.0.1']]], 'br0' => ['unicast' => [['family' => 2, 'address' => '10.9.9.20']]]];
    $mt = "$logs/syslog-10.77.3.10.log";
    $round = function (int $now, array $lines) use ($paths, $data, $mt, $tmp): array {
        file_put_contents($mt, str_replace(' gateway-1 ', ' lab-chr ', implode('', $lines)), FILE_APPEND);
        touch($mt, $now - 5);
        return watchmanRound($paths, $data, 1000, $now, fn () => [], false, "$tmp/acks.json");
    };
    $book = function () use ($data): array {
        $out = [];
        foreach (watchmanLoad($data)['book'] as $e) {
            $out[$e['key']] = $e;
        }
        return $out;
    };
    $told = fn (array $r) => array_values(array_unique(array_column(array_filter($r['told'], fn ($x) => $x['kind'] !== 'chain'), 'kind')));
    $new = fn (array $r) => array_values(array_filter($r['added'], fn ($k) => str_starts_with($k, 'net_')));
    $burst = fn (string $hm0, string $ip, int $n, string $user = 'admin', string $via = 'ssh') => array_map(
        fn ($i) => netTestLine(strtotime("2026-10-09 $hm0") + $i, "system,error,critical login failure for user $user from $ip via $via"), range(0, $n - 1));
    $fk = 'net_router_login_failures:10.77.3.10:10.77.3.1';

    // ---- round 1: the router's history is learned — admin from 10.77.3.1, a burst from 10.77.3.50 makes that address known for failing
    $r = $round($at('13:41:33'), array_merge($burst('13:30:00', '10.77.3.50', 6), netTestSlice($main, 'uso-step MAIN', 'uso-step 3 failures')));
    same('mikrotik book round 1: learned, nothing told; a burst in the history makes its address known for failing (counted)', [[], 6],
        [$new($r), (int) (watchmanLoad($data)['baseline']['net']['fail_ips']['10.77.3.50']['n'] ?? 0)]);

    // ---- round 2: step 3 — the burst from Tower's address, the console's single failure, the known address again
    $step3 = netTestSlice($main, 'uso-step 3 failures', 'uso-step 3b');
    $mine = array_values(array_filter($step3, fn ($l) => str_contains($l, 'login failure for user') && str_contains($l, 'from 10.77.3.1 ')));
    $strangers = count(array_filter($mine, fn ($l) => !str_contains($l, 'login failure for user admin from')));
    $r = $round($at('13:44:30'), array_merge($step3, $burst('13:44:00', '10.77.3.50', 5)));
    $b = $book();
    $f = $b[$fk] ?? [];
    same('mikrotik failures: one entry per router and address — counted up (every failure of the burst), told; the known address and the console only counted',
        [['net_router_login_failures'], count($mine), true, ['net_router_login_failures'], false, false],
        [$new($r), (int) ($f['count'] ?? 0), watchmanImportant($f), $told($r), isset($b['net_router_login_failures:10.77.3.10:10.77.3.50']),
         isset($b['net_router_login_failures:10.77.3.10:local'])]);
    same('mikrotik failures: the names tried only when they are admins he knows («admin»), the others a count — never «nosuchuser» or a command typed as a name',
        [['admin'], $strangers, true, false, false, 'T1110'],
        [$f['p']['users'] ?? null, (int) ($f['p']['unknown'] ?? 0), in_array('ssh', (array) ($f['p']['methods'] ?? []), true),
         str_contains(json_encode($f, JSON_UNESCAPED_SLASHES), 'nosuchuser'), str_contains(json_encode($f, JSON_UNESCAPED_SLASHES), 'identity print'), WATCH_ATTACK['net_router_login_failures']]);
    same('mikrotik failures: the known address\'s burst counted quietly; the console\'s single failure tracked under «local»', [true, true],
        [(int) (watchmanLoad($data)['baseline']['net']['fail_ips']['10.77.3.50']['quiet'] ?? 0) >= 5, isset((readJson("$data/net.json") ?? [])['fails']['10.77.3.10|local'])]);
    same('mikrotik failures: the words (en) and the notification\'s subject', [count($mine) . ' failed logins at router lab-chr from 10.77.3.1', 'Night watchman: failed logins at router lab-chr from 10.77.3.1'],
        [explode(' — ', officeNotifyText('watchman', 'entry.net_router_login_failures', ['n' => (int) $f['count']] + watchmanText($f, 'en'), 'en'))[0],
         officeNotifyText('watchman', 'notify.net_router_login_failures', ['n' => 1] + watchmanText($f, 'en'), 'en')]);

    // «I know, thanks»: this address's failures are counted from now on — a new burst no entry
    same('mikrotik failures: «I know, thanks»', ['ok' => true, 'noted' => 1], watchmanAck([$f['id']], $data, $at('13:45:00'), false));
    $r = $round($at('13:45:40'), $burst('13:45:30', '10.77.3.1', 6, 'admin', 'api'));
    same('mikrotik failures: … then a new burst from it only counted (no entry, the noted one stays noted)', [[], 1, true],
        [$new($r), count(array_filter($book(), fn ($e) => $e['kind'] === 'net_router_login_failures')),
         isset(watchmanLoad($data)['baseline']['net']['fail_ips']['10.77.3.1'])]);

    // ---- round 3: step 5 — ether2 down/up ×4: one entry, closed by himself (back), not told
    $r = $round($at('13:47:00'), netTestSlice($main, 'uso-step 5 link', 'uso-step 6 dhcp'));
    $b = $book();
    $l = $b['net_link_down:10.77.3.10:ether2:2026-10-09'] ?? [];
    same('mikrotik link: «ether2 link down» ×4 — one entry per port and day, count 4, back at 13:46:14, noted by himself, not told',
        [['net_link_down'], 4, $at('13:46:14'), 'router', false, [], 'T1200'],
        [$new($r), (int) ($l['count'] ?? 0), $l['p']['back'] ?? null, $l['by'] ?? null, watchmanImportant($l), $told($r), WATCH_ATTACK['net_link_down']]);

    // ---- step 6–8 (leases, VPN, firewall) between, then step 9: the WAN lost over two rounds
    $round($at('13:54:00'), netTestSlice($main, 'uso-step 6 dhcp', 'uso-step 9 WAN'));
    $wan = netTestSlice($main, 'uso-step 9 WAN', 'uso-step 10a');
    $cut = 0;
    foreach ($wan as $i => $line) {
        if (str_contains($line, 'ether1 link up')) {
            $cut = $i;
            break;
        }
    }
    $r = $round($at('13:55:00'), array_slice($wan, 0, $cut));
    $o = $book()['net_outage:10.77.3.10:ether1:2026-10-09'] ?? [];
    same('mikrotik outage: «client1 on ether1 lost IP address» — open (p.down), not told yet, its shape «still away»; ether1\'s link down no link entry (a WAN port)',
        [['net_outage'], $at('13:54:28'), false, [], 'net_outage_open', false],
        [$new($r), $o['p']['down'] ?? null, watchmanImportant($o), $told($r), watchnetEntryVariant($o), isset($book()['net_link_down:10.77.3.10:ether1:2026-10-09'])]);
    same('mikrotik outage: the words while it lasts (en)', 'The internet is away at lab-chr (ether1) since 13:54 — 1 min so far',
        officeNotifyText('watchman', watchmanEntryKey($o), ['n' => 1] + watchmanText($o, 'en'), 'en'));
    $r = $round($at('13:57:00'), array_slice($wan, $cut));
    $o = $book()['net_outage:10.77.3.10:ether1:2026-10-09'] ?? [];
    same('mikrotik outage: … «got IP address» closes it — 131 s, over two minutes: important, told now that it is over; still open in the book until noted',
        [[], null, $at('13:56:39'), 131, true, ['net_outage'], true, null],
        [$new($r), array_key_exists('down', (array) ($o['p'] ?? [])) ? $o['p']['down'] : 'x', $o['p']['to'] ?? null, (int) ($o['p']['secs'] ?? 0), watchmanImportant($o), $told($r), watchmanOpen($o), watchnetEntryVariant($o)]);
    same('mikrotik outage: the words once over (en, de); no WAN address anywhere',
        ['The internet was away at lab-chr (ether1): 13:54–13:56, 2 min', 'Das Internet war bei lab-chr (ether1) weg: 13:54–13:56, 2 Min.', false],
        [officeNotifyText('watchman', watchmanEntryKey($o), ['n' => 1] + watchmanText($o, 'en'), 'en'),
         officeNotifyText('watchman', watchmanEntryKey($o), ['n' => 1] + watchmanText($o, 'de'), 'de'), str_contains(json_encode($o), '10.77.1.10')]);

    // ---- step 10: restarts — four clean ones a plain line, the unclean one told; the clock lines nothing
    $r = $round($at('14:02:00'), netTestSlice($main, 'uso-step 10a', 'uso-step 10h'));
    $b = $book();
    $c = $b['net_router_reboot:10.77.3.10:2026-10-09'] ?? [];
    $u = $b['net_router_reboot:10.77.3.10:' . $at('13:58:01')] ?? [];
    same('mikrotik restart: clean — one plain line a day, count 4, by admin, noted by himself; unclean — its own entry, important, told; no outage from the boots\' «got IP»',
        [['net_router_reboot'], 4, ['admin'], 'router', true, true, ['net_router_reboot'], 'net_router_reboot_unclean', 1],
        [$new($r), (int) ($c['count'] ?? 0), $c['p']['admins'] ?? null, $c['by'] ?? null, watchmanOpen($u), watchmanImportant($u), $told($r),
         watchnetEntryVariant($u), count(array_filter($b, fn ($e) => $e['kind'] === 'net_outage'))]);
    // the server started at 13:55 (its boot line, booked by himself): the next round joins them — a power loss for both
    $raw = readJson("$data/book.json");
    $raw['entries'][] = ['noted' => $at('14:03:00'), 'by' => 'array'] + watchmanEntry('server_boot', 'server_boot:test-boot', $at('13:55:00'), ['logins' => []]);
    file_put_contents("$data/book.json", json_encode($raw));
    $round($at('14:05:00'), []);
    $u = $book()['net_router_reboot:10.77.3.10:' . $at('13:58:01')] ?? [];
    same('mikrotik restart: the server\'s own start 3 minutes before — joined (p.power), its words say both lost power',
        [$at('13:55:00'), 'net_router_reboot_power', true],
        [$u['p']['power'] ?? null, watchnetEntryVariant($u), str_contains(officeNotifyText('watchman', watchmanEntryKey($u), ['n' => 1] + watchmanText($u, 'en'), 'en'), '13:55')]);
    $pb = [watchmanEntry('server_boot', 'server_boot:x', 1000, []), watchmanEntry('net_router_reboot', 'r:1', 1000 + WATCHNET_POWER + 1, ['clean' => false])];
    watchnetPowerLink($pb);
    same('mikrotik restart: … more than WATCHNET_POWER apart — not joined', false, isset($pb[1]['p']['power']));

    // ---- PPPoE (steps 9c–9f): the retries one loss, its carrier port no link entry, «administrator request» nothing
    $r = $round($at('14:12:30'), netTestSlice($main, 'uso-step 9c PPPoE', 'uso-step 9f'));
    $b = $book();
    $pp = $b['net_outage:10.77.3.10:pppoe-out1:2026-10-09'] ?? [];
    same('mikrotik PPPoE: link loss 60 s + «failed to authenticate» 27 s — one entry, two losses, 87 s: short, noted by himself; ether2\'s link down carries it (no link entry, a WAN port now)',
        [['net_outage'], 2, 87, 'router', false, 4, true],
        [$new($r), (int) ($pp['count'] ?? 0), (int) ($pp['p']['secs'] ?? 0), $pp['by'] ?? null, watchmanImportant($pp),
         (int) ($b['net_link_down:10.77.3.10:ether2:2026-10-09']['count'] ?? 0), isset((readJson("$data/net.json") ?? [])['senders']['10.77.3.10']['wan']['ether2'])]);

    // ---- flapping: ether5 down/up 4 times, then 6 more — told once; the loopback and a virtual interface coming up: nothing
    $flap = function (string $hm0, int $n, string $iface = 'ether5') {
        $out = [];
        for ($i = 0; $i < $n; $i++) {
            $out[] = netTestLine(strtotime("2026-10-09 $hm0") + 4 * $i, "interface,info $iface link down");
            $out[] = netTestLine(strtotime("2026-10-09 $hm0") + 4 * $i + 2, "interface,info $iface link up");
        }
        return $out;
    };
    $r = $round($at('14:21:00'), array_merge($flap('14:20:00', 4), [$L('14:20:50', 'interface,info lo link up'), $L('14:20:51', 'interface,info wg-lab link up')]));
    $r2 = $round($at('14:31:00'), $flap('14:30:00', 6));
    $l = $book()['net_link_down:10.77.3.10:ether5:2026-10-09'] ?? [];
    same('mikrotik link: ether5 ×4 (noted by himself), then ×6 more — the same entry opened again, count 10: flapping, important, told once, open until noted',
        [['net_link_down'], [], 10, true, true, ['net_link_down'], 'net_link_down_flapping'],
        [$new($r), $new($r2), (int) ($l['count'] ?? 0), watchmanOpen($l), !empty($l['p']['flapping']), $told($r2), watchnetEntryVariant($l)]);
    same('mikrotik link: lo and wg-lab coming up make no entry', [false, false],
        [isset($book()['net_link_down:10.77.3.10:lo:2026-10-09']), isset($book()['net_link_down:10.77.3.10:wg-lab:2026-10-09'])]);

    // ---- a short outage (noted by himself), a second loss that day on the same entry makes it long (told)
    $r = $round($at('14:41:00'), [$L('14:40:00', 'dhcp,info client3 on ether6 lost IP address 10.77.6.10 - lease stopped locally'),
                                   $L('14:40:40', 'dhcp,info client3 on ether6 got IP address 10.77.6.10')]);
    $s6 = $book()['net_outage:10.77.3.10:ether6:2026-10-09'] ?? [];
    same('mikrotik outage: 40 s — a plain line he noted himself, not told', [['net_outage'], 'router', false, []],
        [$new($r), $s6['by'] ?? null, watchmanImportant($s6), $told($r)]);
    $r = $round($at('15:06:00'), [$L('15:03:00', 'dhcp,info client3 on ether6 lost IP address 10.77.6.10 - lease stopped locally'),
                                   $L('15:04:30', 'dhcp,info client3 on ether6 got IP address 10.77.6.10')]);
    $s6 = $book()['net_outage:10.77.3.10:ether6:2026-10-09'] ?? [];
    same('mikrotik outage: … a second loss that day (90 s) — the same entry, opened again, 130 s in all: told',
        [[], 2, 130, true, ['net_outage'], 'The internet was away 2 times at lab-chr (ether6) on 2026-10-09: 2 min in all, the longest 2 min'],
        [$new($r), (int) ($s6['count'] ?? 0), (int) ($s6['p']['secs'] ?? 0), watchmanOpen($s6), $told($r),
         officeNotifyText('watchman', watchmanEntryKey($s6), ['n' => (int) $s6['count']] + watchmanText($s6, 'en'), 'en')]);

    // ---- still away after 30 minutes: told while it lasts (an hour after the last outage told); its closing line never comes:
    // closed after a day, its end unknown
    $round($at('16:11:00'), [$L('16:10:00', 'pppoe,ppp,info pppoe-out2: terminating... - peer is not responding')]);
    $r = $round($at('16:41:00'), [$L('16:40:30', 'pppoe,ppp,info pppoe-out2: initializing...')]);
    $p2 = $book()['net_outage:10.77.3.10:pppoe-out2:2026-10-09'] ?? [];
    same('mikrotik outage: 31 minutes away, still — important now, told while it lasts, «31 min so far»',
        [true, ['net_outage'], 31, 'net_outage_open'], [watchmanImportant($p2), $told($r), (int) ($p2['p']['minutes'] ?? 0), watchnetEntryVariant($p2)]);
    $round($at('16:10:00') + WATCHNET_OUTAGE_STALE + 600, [netTestLine($at('16:10:00') + WATCHNET_OUTAGE_STALE + 500, 'script,info still here')]);
    $p2 = $book()['net_outage:10.77.3.10:pppoe-out2:2026-10-09'] ?? [];
    same('mikrotik outage: no closing line for a day — closed, its end unknown, open in the book (told already)', [null, null, true, true],
        [array_key_exists('down', (array) ($p2['p'] ?? [])) ? $p2['p']['down'] : 'x', array_key_exists('to', (array) ($p2['p'] ?? [])) ? $p2['p']['to'] : 'x',
         !empty($p2['p']['unknown']), watchmanOpen($p2)]);

    // ---- the words: every kind and shape in every language, the fold, «I know, thanks», the privacy rule
    $variants = ['net_outage_open', 'net_link_down_flapping', 'net_router_reboot_unclean', 'net_router_reboot_power'];
    $gaps = [];
    foreach (['en', 'de', 'it', 'fr', 'es'] as $lang) {
        $l = langFile(OFFICE_WEB . "/desks/watchman/lang/$lang.json");
        foreach (['net_router_login_failures', 'net_link_down', 'net_outage', 'net_router_reboot'] as $k) {
            foreach (["entry.$k", "check.$k", "check.{$k}_how", "notify.$k", "adopt.$k", "fold.$k"] as $key) {
                if (!isset($l[$key])) {
                    $gaps[] = "$lang $key";
                }
            }
        }
        foreach ($variants as $v) {
            if (!isset($l["entry.$v"])) {
                $gaps[] = "$lang entry.$v";
            }
        }
        if (!isset($l['entry.net_too_much_mikrotik'])) {
            $gaps[] = "$lang entry.net_too_much_mikrotik";
        }
    }
    same('mikrotik book: every new kind and shape has its words in all five languages (entry, check, how, notify, adopt, fold)', [], $gaps);
    $loose = [];
    foreach ($book() as $e) {
        if (!in_array($e['kind'], ['net_router_login_failures', 'net_link_down', 'net_outage', 'net_router_reboot'], true)) {
            continue;
        }
        foreach (['en', 'de', 'fr'] as $lang) {
            foreach ([watchmanEntryKey($e), "notify.{$e['kind']}", "check.{$e['kind']}"] as $key) {
                $t = officeNotifyText('watchman', $key, ['n' => (int) $e['count']] + watchmanText($e, $lang), $lang);
                if ($t === '' || $t === $key || preg_match('/\{[a-z_]+\}/', $t)) {
                    $loose[] = "$lang $key: $t";
                }
            }
        }
        if (preg_match('/\b(?:10\.77\.1\.10|10\.77\.6\.10|10\.9\.9\.\d+)\b/', json_encode($e['p']) . json_encode(watchmanText($e, 'en')))
            && $e['kind'] !== 'net_router_login_failures') {
            $loose[] = "{$e['kind']}: an address";
        }
    }
    same('mikrotik book: the words filled (no placeholder left) in en/de/fr; links, outages and restarts carry no address (the WAN\'s neither)', [], $loose);

    // ---- the Team Lead: a MikroTik whose newest lines come without topics — a hint; with them again — none
    $o = ['cfg' => $paths['rsyslog_cfg'], 'shares_ini' => $paths['shares_ini'], 'disks_ini' => $paths['disks_ini'], 'var_ini' => $paths['var_ini'],
          'sec' => "$src/sec.ini", 'sec_nfs' => "$src/sec_nfs.ini", 'server' => watchnetServer($paths, []), 'containers' => [], 'link' => '#/advisor',
          'hired' => true, 'now' => $at('15:00:00')];
    $hint = fn (array $fmt) => array_values(array_map(fn ($f) => [$f['level'], $f['ok'], $f['params']['router']], array_filter(watchnetChecks($o + ['net' =>
        ['senders' => ['10.77.3.10' => ['ros' => true, 'meta' => ['host' => 'lab-chr'], 'fmt' => $fmt], '192.0.2.1' => ['cef' => true]]]]),
        fn ($f) => $f['id'] === 'syslog_mikrotik_format')));
    same('mikrotik team lead: the default format or no topics lately — a hint naming the router; topics again since, or only long ago — none; not hired — none',
        [[['hint', false, 'lab-chr']], [['hint', false, 'lab-chr']], [], [], []],
        [$hint(['default' => $at('14:00:00')]), $hint(['notopics' => $at('14:00:00'), 'syslog' => $at('13:00:00')]),
         $hint(['notopics' => $at('13:00:00'), 'syslog' => $at('14:00:00')]), $hint(['default' => $at('15:00:00') - 2 * 86400]),
         array_values(array_filter(watchnetChecks(['hired' => false] + $o + ['net' => ['senders' => ['x' => ['ros' => true, 'fmt' => ['default' => $at('14:00:00')]]]]]),
             fn ($f) => $f['id'] === 'syslog_mikrotik_format'))]);
    $ct = langFile(OFFICE_WEB . '/desks/caretaker/lang/en.json');
    check('mikrotik team lead: the hint\'s words', isset($ct['check.syslog_mikrotik_format'], $ct['check.syslog_mikrotik_format_how']));

    // ---- his summary: a MikroTik's version unknown until a line says it, the format hint, prefixes that say no drop
    $sum = watchnetSummary(watchmanLoad($data)['baseline']['net'] ?? null, readJson("$data/net.json"), false, $at('16:10:00') + WATCHNET_OUTAGE_STALE + 600);
    $x = array_column($sum['senders'] ?? [], null, 'sender')['10.77.3.10'] ?? [];
    same('mikrotik summary: RouterOS, the version not said yet, topics there (no hint), firewall lines without a drop prefix counted', [true, 'RouterOS', '', false, true],
        [$x['ros'] ?? null, $x['product'] ?? null, $x['version'] ?? null, $x['ros_format'] ?? null, isset($x['prefix_other'])]);
    $GLOBALS['watchnetIfaces'] = $ifaces;
    exec('rm -rf ' . escapeshellarg($tmp));
}

// ===================================================================== updates

/**
 * The Consultant's MikroTik guide (#2, package 4): a guide of the group network like UniFi's; the lines to paste — the
 * logging action in the syslog format with add-topics-string=yes (RouterOS 7.24 leaves the topics out without it), the
 * four rules by severity, the two firewall log rules whose prefixes the night watchman reads as drops (limit=10,20:packet),
 * the clock, a first line — each tried on the lab's RouterOS 7.24.5; their labels and paragraphs in every language, no
 * «MikroTik: later» left in UniFi's guide, the search's places.
 */
function testAdvisorMikrotikGuide(): void
{
    $pub = dirname(__DIR__) . '/public';
    same('mikrotik guide: a guide of the network group, after UniFi\'s', [['guide' => 'mikrotik', 'optional' => true, 'group' => 'network'], ['syslogserver', 'unifi', 'mikrotik', 'neighbours']],
        [ADVISOR_EXTERNALS['mikrotik'] ?? null, array_values(array_keys(array_filter(ADVISOR_EXTERNALS, fn ($x) => ($x['group'] ?? '') === 'network')))]);
    $js = (string) file_get_contents("$pub/desks/advisor/desk.js");
    preg_match("/  mikrotik: \\{.*?copy: \\{(.*?)\\n    \\},/s", $js, $m);
    preg_match_all("/^      ([a-z_]+): '(.*)',\$/m", (string) ($m[1] ?? ''), $c, PREG_SET_ORDER);
    $copy = array_column($c, 2, 1);
    same('mikrotik guide: the lines to paste', ['action', 'rules', 'drop_wan', 'drop_server', 'clock', 'hello'], array_keys($copy));
    check('mikrotik guide: the action — remote to this server, UDP 514, the syslog format WITH the topics (add-topics-string=yes)',
        str_contains($copy['action'] ?? '', '/system logging action add name=unraid target=remote remote={ip} remote-port=514 remote-protocol=udp remote-log-format=syslog')
        && str_contains($copy['action'] ?? '', 'add-topics-string=yes'));
    same('mikrotik guide: four rules by severity, one line', ['info', 'warning', 'error', 'critical'],
        preg_match_all('/\/system logging add topics=([a-z]+) action=unraid/', $copy['rules'] ?? '', $r) ? $r[1] : []);
    $rule = fn (string $s) => preg_match('/log-prefix="([a-z-]+)"/', $s, $x) ? $x[1] : '';
    same('mikrotik guide: the firewall log rules with limit=10,20:packet — their prefixes are drops to the night watchman (a line of their shape: blocked)',
        [true, true, 'blocked', 'blocked'],
        [str_contains($copy['drop_wan'] ?? '', 'limit=10,20:packet') && str_contains($copy['drop_wan'] ?? '', 'chain=input'),
         str_contains($copy['drop_server'] ?? '', 'limit=10,20:packet') && str_contains($copy['drop_server'] ?? '', 'src-address={ip}'),
         watchnetRosFirewall($rule($copy['drop_wan'] ?? '') . ' input: in:ether1 out:(unknown 0), proto TCP (SYN), 203.0.113.5:4455->192.0.2.1:22, len 60')['type'],
         watchnetRosFirewall($rule($copy['drop_server'] ?? '') . ' forward: in:bridge out:ether1, proto UDP, 192.0.2.20:5353->8.8.8.8:53, len 70')['type']]);
    check('mikrotik guide: the page fills in the server\'s address and the browser\'s time zone (a safe name, else autodetect)',
        str_contains($js, "v.replaceAll('{ip}', ip)") && str_contains($js, "time-zone-autodetect=no time-zone-name={tz}") && str_contains($js, "'time-zone-autodetect=yes'"));
    check('mikrotik guide: «hello unraid» proves the path', ($copy['hello'] ?? '') === '/log info "hello unraid"');
    $en = langFile("$pub/desks/advisor/lang/en.json");
    $keys = array_merge(['ext.mikrotik.name', 'net.mikrotik.what', 'net.mikrotik.check'], array_map(fn ($i) => "net.mikrotik.$i", range(1, 6)),
        array_map(fn ($k) => "copy.mikrotik.$k", array_keys($copy)));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $code) {
        $t = langFile("$pub/desks/advisor/lang/$code.json");
        same("mikrotik guide/$code: every paragraph and label", [], array_values(array_diff($keys, array_keys($t))));
        check("mikrotik guide/$code: add-topics-string named, UniFi's guide no longer says «MikroTik: later»",
            str_contains((string) ($t['net.mikrotik.2'] ?? ''), 'add-topics-string=yes') && !str_contains((string) ($t['net.unifi.6'] ?? ''), 'MikroTik'));
    }
    check('mikrotik guide: no seventh paragraph by accident', !isset($en['net.mikrotik.7']));
    $pj = json_decode((string) file_get_contents("$pub/desks/advisor/places.json"), true) ?: [];
    check('mikrotik guide: the search knows it (places.json: its name, its paragraphs)', in_array('ext.mikrotik.name', $pj['keys'] ?? [], true)
        && in_array('net.mikrotik.*', $pj['texts'] ?? [], true) && in_array('net.mikrotik.what', $pj['texts'] ?? [], true)
        && str_contains($js, "mikrotik: 'net.mikrotik'"));
}

/**
 * The data folder's version marker and the one place for migrations (agent/lib/migrate.php): an old data folder (an
 * agent.json of 1.30) gets its marker at the first start, a step newer than 1.30 runs once (and renames aside, never
 * deletes), a step older than it doesn't, a failing step is tried again at the next start, a second start does nothing;
 * a fresh folder, a folder of an unknown version, a downgrade, an older office in between; the real steps; the hook in
 * setUp() before anything reads state.
 */
function testMigrate(): void
{
    $tmp = sys_get_temp_dir() . '/office-tests-migrate-' . getmypid();
    exec('rm -rf ' . escapeshellarg($tmp));
    $dir = "$tmp/data";
    @mkdir($dir, 0755, true);
    file_put_contents("$dir/agent.json", '{"running":false,"version":"1.30.0","pid":1}');
    file_put_contents("$dir/caretaker.json", '{"time":1}');
    file_put_contents("$dir/whereabouts.json", '{"old":true}');
    $ran = ['a' => 0, 'b' => 0, 'c' => 0];
    $fail = 1;
    $steps = [
        ['id' => 'b', 'version' => '1.20.0', 'run' => function () use (&$ran): string { $ran['b']++; return 'b'; }],
        ['id' => 'a', 'version' => '1.31.0', 'run' => function (string $d, string $to) use (&$ran): string {
            $ran['a']++;
            return 'aside: ' . basename((string) officeMigrateAside("$d/whereabouts.json", $to));
        }],
        ['id' => 'c', 'version' => '1.40.0', 'run' => function () use (&$ran, &$fail): string {
            $ran['c']++;
            if ($fail-- > 0) {
                throw new RuntimeException('not now');
            }
            return 'c';
        }],
    ];
    $lines = [];
    $log = function (string $l) use (&$lines): void { $lines[] = $l; };
    $start = function (string $to, ?array $s = null) use ($dir, &$steps, $log, &$lines): ?array {
        $lines = [];
        return officeMigrateStart($dir, $to, $s ?? $steps, $log);
    };
    $agentIs = fn (string $v) => file_put_contents("$dir/agent.json", jsonEncode(['running' => true, 'version' => $v]));     // what writeInfo() does next

    same('migrate: an old folder comes from its agent.json', ['1.30.0', null], officeMigrateFrom($dir));
    $r = $start('1.41.0');
    $mark = officeMarkRead($dir);
    same('migrate: the first start — the newer steps run (the failing one stays pending), the older one is counted done',
        [['a'], ['c'], ['a' => 1, 'b' => 0, 'c' => 1]], [$r['ran'], $r['failed'], $ran]);
    same('migrate: the marker — version, since, where it came from, done, pending',
        ['1.41.0', true, [['version' => '1.30.0']], ['b', 'a'], ['c']],
        [$mark['version'] ?? null, ($mark['since'] ?? 0) >= time() - 5, array_map(fn ($u) => ['version' => $u['version']], $mark['updated_from'] ?? []),
         $mark['done'] ?? null, $mark['pending'] ?? null]);
    same('migrate: the marker is exactly the office\'s shape', ['version', 'since', 'updated_from', 'done', 'pending'], array_keys(readJson("$dir/office.json") ?? []));
    same('migrate: what made way is renamed aside, never deleted; the rest untouched', [false, '{"old":true}', '{"time":1}'],
        [file_exists("$dir/whereabouts.json"), @file_get_contents("$dir/whereabouts.json.before-1.41.0"), file_get_contents("$dir/caretaker.json")]);
    check('migrate: logged — the marker, each step, the failure', count($lines) === 3 && str_contains($lines[0], 'version marker written')
        && str_contains($lines[0], '1.30.0') && str_contains($lines[1], 'step a') && str_contains($lines[2], 'step c') && str_contains($lines[2], 'failed'), json_encode($lines));
    $agentIs('1.41.0');
    $since = $mark['since'];
    touch("$dir/office.json", 1000000000);
    $r = $start('1.41.0');
    same('migrate: the next start tries the failed step again — only that one', [['c'], [], ['a' => 1, 'b' => 0, 'c' => 2]], [$r['ran'], $r['failed'], $ran]);
    same('migrate: … and the marker keeps its since', [$since, ['b', 'a', 'c'], []], [officeMarkRead($dir)['since'], officeMarkRead($dir)['done'], officeMarkRead($dir)['pending']]);
    $before = file_get_contents("$dir/office.json");
    touch("$dir/office.json", 1000000000);
    $r = $start('1.41.0');
    clearstatcache();
    same('migrate: a second start does nothing — no step, no line, the marker not written', [[], [], ['a' => 1, 'b' => 0, 'c' => 2], $before, 1000000000],
        [$r['ran'], $lines, $ran, file_get_contents("$dir/office.json"), filemtime("$dir/office.json")]);
    same('migrate: what made way stays aside (a second aside gets a number)', basename("$dir/x.before-1.41.0-2"),
        (function () use ($dir) { file_put_contents("$dir/x", '1'); file_put_contents("$dir/x.before-1.41.0", '0'); return basename((string) officeMigrateAside("$dir/x", '1.41.0')); })());
    same('migrate: nothing there — nothing renamed', null, officeMigrateAside("$dir/none", '1.41.0'));

    // an update: from the marker's version; since and updated_from move on
    $r = $start('1.42.0');
    $mark = officeMarkRead($dir);
    same('migrate: an update — nothing left to do, the marker moves on', [[], '1.42.0', ['1.30.0', '1.41.0']],
        [$r['ran'], $mark['version'], array_column($mark['updated_from'], 'version')]);
    check('migrate: … said once', count($lines) === 1 && str_contains($lines[0], '1.41.0 → 1.42.0'), json_encode($lines));
    $agentIs('1.42.0');

    // a downgrade that knows the marker: only its own steps count, the newer one's run again when it comes back
    $r = $start('1.40.5', array_slice($steps, 0, 2));
    $mark = officeMarkRead($dir);
    same('migrate: a downgrade — said, nothing run, only the steps it knows kept as done', [true, [], ['b', 'a'], '1.40.5'],
        [$r['downgrade'], $r['ran'], $mark['done'], $mark['version']]);
    check('migrate: … the downgrade in the log', count($lines) === 1 && str_contains($lines[0], 'a downgrade'), json_encode($lines));
    $agentIs('1.40.5');
    $r = $start('1.42.0');
    same('migrate: back again — the step it didn\'t know runs again (idempotent)', [['c'], ['a' => 1, 'b' => 0, 'c' => 3]], [$r['ran'], $ran]);
    $agentIs('1.42.0');

    // an office from before the marker ran in between (it wrote agent.json, not office.json): the steps since it run again
    $agentIs('1.35.0');
    same('migrate: an older agent.json than the marker — an office from before the marker ran in between', ['1.35.0', '1.35.0'], officeMigrateFrom($dir));
    $r = $start('1.42.0');
    same('migrate: … the steps newer than it run again, the older ones not', [['c'], ['a' => 1, 'b' => 0, 'c' => 4]], [$r['ran'], $ran]);
    same('migrate: … the way it went in updated_from', ['1.30.0', '1.41.0', '1.42.0', '1.40.5', '1.42.0', '1.35.0'],
        array_column(officeMarkRead($dir)['updated_from'], 'version'));
    check('migrate: … said', str_contains($lines[0] ?? '', '1.35.0 (from before the marker)'), json_encode($lines));

    // a fresh folder: nothing to change, every step done; a folder with state files but no version: every step runs
    $fresh = "$tmp/fresh";
    @mkdir($fresh, 0755, true);
    $count = $ran;
    same('migrate: a fresh folder', ['', null], officeMigrateFrom($fresh));
    $r = officeMigrateStart($fresh, '1.42.0', $steps, $log);
    same('migrate: … no step runs, all done, the marker written', [[], $count, ['b', 'a', 'c'], '1.42.0', []],
        [$r['ran'], $ran, officeMarkRead($fresh)['done'], officeMarkRead($fresh)['version'], officeMarkRead($fresh)['updated_from']]);
    $unknown = "$tmp/unknown";
    @mkdir($unknown, 0755, true);
    file_put_contents("$unknown/backup.json", '{}');
    same('migrate: state files without a version — unknown, older than all', ['0', null], officeMigrateFrom($unknown));
    $fail = 0;
    $r = officeMigrateStart($unknown, '1.42.0', $steps, $log);
    same('migrate: … every step runs', ['b', 'a', 'c'], $r['ran']);
    @mkdir("$tmp/broken", 0755, true);
    file_put_contents("$tmp/broken/office.json", '{"version":"x y","done":["a"]}');
    same('migrate: a marker not in the office\'s shape counts as none', [], officeMarkRead("$tmp/broken"));

    // the real steps: unique ids, versions, callables — the first changes nothing in the folder
    $real = officeMigrateSteps();
    $ids = array_column($real, 'id');
    check('migrate: the real steps — unique ids, a version each, callable', $ids && count($ids) === count(array_unique($ids))
        && !array_filter($real, fn ($s) => !preg_match(OFFICE_MARK_VERSION, (string) ($s['version'] ?? '')) || !is_callable($s['run'] ?? null)
            || !preg_match('/^[a-z0-9][a-z0-9-]*\z/', (string) $s['id'])));
    $listing = fn () => scandir($dir);
    $was = $listing();
    $r = officeMigrate('1.41.0', '1.42.0', $dir, null, null, $log);
    same('migrate: the real steps run on an older folder — with nothing of the past in it they change nothing', [true, true, $was],
        [in_array('marker', $r['ran'], true) || in_array('marker', officeMarkRead($dir)['done'], true),
         !array_diff(['where-files', 'staff-merged'], array_merge($r['ran'], officeMarkRead($dir)['done'])), $listing()]);
    $versions = array_column($real, 'version');
    usort($versions, 'version_compare');
    same('migrate: the real steps are listed oldest first (they run in that order)', $versions, array_column($real, 'version'));

    // the hook: in setUp(), after the private folders, before agent.json is written and before any desk's start
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/agent.php');
    $setUp = preg_match('/^function setUp\(\): void\n\{\n(.*?)^\}/ms', $src, $m) ? $m[1] : '';
    $at = fn (string $s) => strpos($setUp, $s);
    check('migrate: setUp() runs officeMigrateStart() before writeInfo() and the desks\' start', $at('officeMigrateStart()') !== false
        && $at('officeMigrateStart()') < $at('writeInfo(true)') && $at('officeMigrateStart()') < $at("(\$desk['start'])()") && $at('privateDirEnsure(OFFICE_PRIVATE') < $at('officeMigrateStart()'));
    check('migrate: the agent requires lib/migrate.php', str_contains($src, "require __DIR__ . '/lib/migrate.php';"));
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Mr. Backupsy's setup after an engine update (upgrade audit proposal 5, backupSetupReplan()): a plan whose `version`
 * isn't the running engine's is made anew on the next look — once per engine version (the note is written before
 * setup.sh starts; a failed plan isn't tried again at every look), not while a run or anything holds the lock, not for
 * an engine the office can't drive; no plan answered while it runs; the plan it made says so in its messages (once —
 * a later plan doesn't); the page no longer sniffs the plan's shape.
 */
function testBackupReplan(): void
{
    $state = ['found' => true, 'compatible' => true, 'running' => false, 'version' => '2.34'];
    $old = ['version' => '2.33', 'time' => 100, 'messages' => [['level' => 'warn', 'step' => 'shares', 'text' => 'x']]];
    $r = backupSetupReplan($old, $state, null, true, 1000);
    same('backup replan: an older engine\'s plan — planned anew, no plan answered meanwhile, the note first',
        [null, true, ['from' => '2.33', 'to' => '2.34', 'at' => 1000]], [$r['plan'], $r['start'], $r['note']]);
    $note = $r['note'];
    $r = backupSetupReplan($old, $state, $note, true, 1060);
    same('backup replan: … once — the plan failed (still the old one): not again, the old plan shown', [$old, false, $note], [$r['plan'], $r['start'], $r['note']]);
    foreach ([['running' => true], ['compatible' => false], ['found' => false]] as $odd) {
        $r = backupSetupReplan($old, $odd + $state, null, true, 1000);
        same('backup replan: not now — ' . json_encode($odd), [$old, false, null], [$r['plan'], $r['start'], $r['note']]);
    }
    $r = backupSetupReplan($old, $state, null, false, 1000);
    same('backup replan: not while something holds the engine\'s lock (setup, restore, recover)', [$old, false, null], [$r['plan'], $r['start'], $r['note']]);
    $r = backupSetupReplan(['time' => 5], $state, null, true, 1000);
    same('backup replan: a plan without a version counts as older', [true, '?'], [$r['start'], $r['note']['from'] ?? null]);
    $r = backupSetupReplan(null, $state, null, true, 1000);
    same('backup replan: no plan at all — nothing here (the page asks for its first plan itself)', [null, false], [$r['plan'], $r['start']]);

    // the new plan: said in its messages, the note remembers which plan that was
    $new = ['version' => '2.34', 'time' => 1003, 'messages' => [['level' => 'info', 'step' => 'plan', 'text' => 'Plan written']]];
    $r = backupSetupReplan($new, $state, $note, true, 1010);
    $said = $r['plan']['messages'][1] ?? [];
    same('backup replan: the plan made anew says so in its list (code replanned, the versions)',
        [false, 'Plan written', 'replanned', 'info', ['from' => '2.33', 'to' => '2.34'], 1003],
        [$r['start'], $r['plan']['messages'][0]['text'] ?? null, $said['code'] ?? null, $said['level'] ?? null, $said['params'] ?? null, $r['note']['plan'] ?? null]);
    $r2 = backupSetupReplan($new, $state, $r['note'], true, 1200);
    same('backup replan: … on every look at that plan', 'replanned', $r2['plan']['messages'][1]['code'] ?? null);
    $later = ['version' => '2.34', 'time' => 2000, 'messages' => []];
    $r3 = backupSetupReplan($later, $state, $r['note'], true, 2010);
    same('backup replan: a later plan (Look again, after Apply) says nothing of it', [[], false], [$r3['plan']['messages'], $r3['start']]);
    $r4 = backupSetupReplan($new, $state, null, true, 1010);
    same('backup replan: this engine\'s plan without a note — as it is', $new, $r4['plan']);
    $r5 = backupSetupReplan($old, ['version' => '2.35'] + $state, $r['note'], true, 3000);
    same('backup replan: the next engine update — planned anew again', [true, '2.35'], [$r5['start'], $r5['note']['to'] ?? null]);

    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    $get = preg_match('/^function backupSetupGet\(\): array\n\{\n(.*?)^\}/ms', $src, $m) ? $m[1] : '';
    check('backup replan: setup_get decides, notes before it starts, and starts setup.sh --plan',
        str_contains($get, 'backupSetupReplan(') && strpos($get, 'writeAtomic($noteFile') < strpos($get, "'--plan'") && str_contains($get, "\$replan['start'] = false"));
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('backup replan: the page no longer sniffs the plan\'s shape', !str_contains($js, 'restale') && !str_contains($js, 'c.binds === undefined'));
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/en.json'), true) ?: [];
    check('backup replan: the office has its words', str_contains((string) ($en['setup.msg.replanned'] ?? ''), '{from}') && str_contains((string) ($en['setup.msg.replanned'] ?? ''), '{to}'));
}

/**
 * 1.63.0 (the monthly reinstall test: a partnership ended and paired anew, Tower ↔ USOPartner, a new id): the setup's plan
 * was made before the re-pairing — it named the old id like settings.ini, the page showed «local + USOPartner», no
 * change, no Apply, while the Team Lead said units wait. backupSetupPairsReplan(): a plan whose partners aren't the pairs
 * this office sends to is made anew on the next look (once per set of pairs); the plan made then hands the old pair's
 * units to the new one (setup.sh, testBackupPartnerPhase «2.45»/«2.47») and the page proposes exactly that.
 */
function testBackupPairsReplan(): void
{
    $state = ['found' => true, 'compatible' => true, 'running' => false, 'version' => '2.47'];
    $stale = ['version' => '2.47', 'time' => 100, 'partners' => [['id' => '2ec7accd', 'name' => 'USOPartner', 'source' => 'pairs']]];
    $r = backupSetupPairsReplan($stale, $state, ['c3553dcc'], null, true, 1000);
    same('pairs replan: the plan names the ended id, the Team Lead pairs another — planned anew, the note first', [true, ['pairs' => 'c3553dcc', 'at' => 1000]], [$r['start'], $r['note']]);
    same('pairs replan: … once for these pairs (the plan failed: not at every look)', false, backupSetupPairsReplan($stale, $state, ['c3553dcc'], $r['note'], true, 1060)['start']);
    same('pairs replan: … the pairs changed again — planned anew again', true, backupSetupPairsReplan($stale, $state, ['d4664edd'], $r['note'], true, 1100)['start']);
    $fresh = ['partners' => [['id' => 'c3553dcc'], ['id' => 'aaaa1111']]] + $stale;
    same('pairs replan: the plan has the pairs (any order) — nothing', false, backupSetupPairsReplan($fresh, $state, ['aaaa1111', 'c3553dcc'], null, true, 1000)['start']);
    same('pairs replan: a partnership ended without a new one (the plan still names it) — planned anew (its units go)', true,
        backupSetupPairsReplan($stale, $state, [], null, true, 1000)['start']);
    same('pairs replan: paired for the first time since the plan — planned anew', true,
        backupSetupPairsReplan(['partners' => []] + $stale, $state, ['c3553dcc'], null, true, 1000)['start']);
    foreach ([['running' => true], ['compatible' => false], ['found' => false]] as $odd) {
        same('pairs replan: not now — ' . json_encode($odd), false, backupSetupPairsReplan($stale, $odd + $state, ['c3553dcc'], null, true, 1000)['start']);
    }
    same('pairs replan: not while something holds the lock; no plan; a plan without partners (an engine before 2.27)', [false, false, false],
        [backupSetupPairsReplan($stale, $state, ['c3553dcc'], null, false, 1000)['start'], backupSetupPairsReplan(null, $state, ['c3553dcc'], null, true, 1000)['start'],
         backupSetupPairsReplan(['time' => 5], $state, ['c3553dcc'], null, true, 1000)['start']]);
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    $get = preg_match('/^function backupSetupGet\(\): array\n\{\n(.*?)^\}/ms', $src, $m) ? $m[1] : '';
    $at = strpos($get, 'backupSetupPairsReplan(');
    check('pairs replan: setup_get asks after the engine\'s replan, only with a pairs.json, the pairs this office sends to; the note before setup.sh, no plan meanwhile',
        $at !== false && $at > strpos($get, 'backupSetupReplan(') && str_contains($get, "if (!\$replan['start'] && function_exists('partnerPairs') && @lstat(partnerDir() . '/pairs.json') !== false)")
        && str_contains($get, "fn (\$p) => \$p['my_key'] !== null") && strpos($get, 'writeAtomic($pairsFile', $at) < strpos($get, "'--plan'", $at)
        && strpos($get, "\$replan['plan'] = null;", $at) !== false);

    // the page: the stale plan shows no partner change (the bug), the plan made anew proposes the new id — Apply sends it
    $node = testsNode();
    if ($node === '') {
        check('pairs replan: page — node is missing here - skipped', true);
        return;
    }
    $tmp = hardeningTmp('pairs-replan');
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
const [bkFile, coreFile, planFile, stateFile] = process.argv.slice(2);
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const el = (tag, cls, text) => ({ tag, className: cls || '', textContent: text == null ? '' : String(text), children: [], dataset: {}, style: {},
  appendChild(c) { this.children.push(c); return c; }, append(...c) { this.children.push(...c); }, setAttribute() {} });
globalThis.Office = { scope: () => T, t: T, el, fmt: { size: (b) => b + ' B', relative: () => 'now', duration: (s) => s + ' s', date: (t) => 'D' + t, time: (t) => 'H' + t, number: (n) => String(n) },
  desk: () => {}, places: () => {}, placesFrom: () => {}, placesTook: () => {}, selbar: () => null, has: () => false,
  store: (k) => (k === 'backup.proposals_dismissed' ? globalThis.dismissed : null),
  storeJson: () => null, agent: { running: true }, place: (k, n) => n, stat: (o) => ({ stat: o }), withGreeting: (id, s) => s,
  sections: () => ({ el: el('div'), grid: el('div'), body: el('div'), active: () => '', note: () => ({ tile: '' }), places: () => [], mount: () => false, pick() {}, render() {}, clear() {} }),
  filterBar: () => { const bar = { el: {}, read: () => ({ words: [], only: false, pick: '', tile: '' }), set() { return bar; }, reset() { return bar; }, done() { return bar; }, tile() { return bar; } }; return bar; } };
const core = fs.readFileSync(coreFile, 'utf8');
new Function('Office', core.slice(core.indexOf('const fold = '), core.indexOf('/** Text or a node')))(globalThis.Office);
(0, eval)(fs.readFileSync(bkFile, 'utf8'));
const b = OFFICE_DESK_TESTS.backup;
const S = b.setup;
const demo = JSON.parse(fs.readFileSync(planFile, 'utf8')).plan;
b.setState(JSON.parse(fs.readFileSync(stateFile, 'utf8')));
const OLD = '2ec7accd', NEW = 'c3553dcc';
const partnerKeys = (o) => Object.keys(o).filter((k) => /partner/.test(k)).sort();
const look = () => {
  b.setupDraftFromPlan();
  const items = b.setupChangeItems().items.filter((x) => /partner/.test(x.id));
  const spec = b.setupBarSpec();
  const dec = b.setupDecisions();
  return { bar: spec && spec.title, items: items.map((x) => [x.id, x.kind]),
    sent: Object.fromEntries(Object.entries(dec).filter(([k]) => /\|partner(_place)?$/.test(k)).sort()), lines: b.partnerApplyLines() };
};
const out = {};
// the plan from before the re-pairing: P and O name the old id — nothing to apply
let plan = JSON.parse(JSON.stringify(demo));
plan.migrated = {}; plan.declined = {};
S.plan = plan; S.choice = null;
out.stale = look();
// the plan made anew: setup.sh gave the old pair's units to the new id (partner_anew), O still the old
plan = JSON.parse(JSON.stringify(demo));
plan.migrated = {}; plan.declined = {};
const swap = (v) => (Array.isArray(v) ? v.map((x) => (x === OLD ? NEW : x)) : v);
plan.P = Object.fromEntries(Object.entries(plan.P).map(([k, v]) => [k.replace(`partner|${OLD}|`, `partner|${NEW}|`), swap(v)]));
plan.P[`partner|${NEW}|address`] = '100.84.12.9';
plan.partners = [{ ...plan.partners[0], id: NEW, address: '100.84.12.9' }];
plan.messages = [...(plan.messages || []), { level: 'hint', step: 'partners', code: 'partner_anew', params: { partner: 'Grosseltern', new: 'Grosseltern', n: '4' } }];
S.plan = plan; S.choice = null;
out.anew = look();
// «Discard» clicked on this plan before: a changed partnership still keeps the bar (1.63.0, live on the test server)
globalThis.dismissed = String(plan.time || '');
out.dismissed = (b.setupBarSpec() || {}).title || null;
console.log(JSON.stringify(out));
JS);
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/backup/desk.js') . ' '
        . escapeshellarg(OFFICE_WEB . '/assets/core.js') . ' ' . escapeshellarg(OFFICE_DIR . '/tests/ui/demo/post/backup.setup_get.json') . ' '
        . escapeshellarg(OFFICE_DIR . '/tests/ui/demo/backup.json') . ' 2>&1');
    $r = json_decode($raw, true);
    hardeningRm($tmp);
    if (!is_array($r)) {
        check('pairs replan: page ran under node', false, substr($raw, 0, 2000));
        return;
    }
    same('pairs replan: page — the plan from before the re-pairing: no partner change (why the page offered no Apply)', [], $r['stale']['items'] ?? null);
    $new = 'c3553dcc';
    same('pairs replan: page — the plan made anew: the old partnership goes, the new comes, every unit to it — proposals, the bar is there',
        [['general|partner_place', 'unit'], ['partner|2ec7accd|', 'partner'], ['partner|c3553dcc|', 'partner'], ['share|Dokumente|partner', 'unit'],
         ['share|Familienfotos|partner', 'unit'], ['vm|Home-Assistant|partner', 'unit']], $r['anew']['items'] ?? null);
    check('pairs replan: page — … the bar counts them as proposals of mine', str_starts_with((string) ($r['anew']['bar'] ?? ''), 'setup.bar_proposals'), (string) json_encode($r['anew']['bar'] ?? null));
    check('pairs replan: page — … an earlier «Discard» on this plan never hides a changed partnership', str_starts_with((string) ($r['dismissed'] ?? ''), 'setup.bar_proposals'),
        (string) json_encode($r['dismissed'] ?? null));
    $bk = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('pairs replan: page — … only that: other proposals set aside stay set aside', str_contains($bk, "=== String(setup.plan.time || '')\n    && !split.mine.some((id) => id.startsWith('partner|'));"));
    same('pairs replan: page — Apply sends the new id for every unit, never the old',
        ['general|partner_place' => [$new], 'share|Dokumente|partner' => [$new], 'share|Familienfotos|partner' => [$new], 'vm|Home-Assistant|partner' => [$new]],
        $r['anew']['sent'] ?? null);
    $line = (string) ($r['anew']['lines'][0][1] ?? '');
    check('pairs replan: page — the dialog\'s «To Grosseltern» says each unit is taken over from the old partnership',
        substr_count($line, 'partner.apply_from {"name":"Grosseltern"}') === 4 && !str_contains($line, 'partner.apply_new'), $line);
}

/**
 * Unraid 8 and the .plg's max (upgrade audit proposal 7): the version the office was tested on is one constant
 * (OFFICE_UNRAID_TESTED, src/place.php), the .plg's max is <major>.99.99 of it (plugin/build.sh refuses another); the
 * team lead recommends looking for an office release before an Unraid update once this Unraid is newer than the tested
 * major.minor or within the last minor before max — in place on the tested one and older.
 */
function testUnraidTested(): void
{
    $ok = fn (?string $v, string $t = '7.3') => ($f = caretakerUnraidTested($v, $t)) === null ? null : $f['ok'];
    same('unraid tested: the tested one and older — in place', [true, true, true, true], [$ok('7.3.2'), $ok('7.3.0'), $ok('7.2.4'), $ok('7.3.0-rc.1')]);
    same('unraid tested: newer than tested — look for an office release first', [false, false, false], [$ok('7.4.0'), $ok('7.4.0-beta.2'), $ok('7.10.1')]);
    same('unraid tested: within the last minor before max (7.99.x) — also when tested that far', [false, false], [$ok('7.99.0', '7.99'), $ok('7.99.5')]);
    same('unraid tested: version unknown — nothing said', [null, null], [$ok(null), $ok('weird')]);
    $f = caretakerUnraidTested('7.4.1', '7.3');
    same('unraid tested: the finding — recommended (never a must), its params, Unraid\'s Plugins page',
        ['unraid_tested', 'recommended', ['version' => '7.4.1', 'tested' => '7.3', 'next' => '8'], 'plugins'], [$f['id'], $f['level'], $f['params'], $f['link']]);
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/caretaker/lang/en.json'), true) ?: [];
    check('unraid tested: the team lead has its words (tested, version, next)', isset($en['check.unraid_tested'])
        && str_contains((string) ($en['check.unraid_tested_how'] ?? ''), '{tested}') && str_contains((string) ($en['check.unraid_tested_how'] ?? ''), '{next}'));
    check('unraid tested: one constant, major.minor', (bool) preg_match('/^\d+\.\d+\z/', OFFICE_UNRAID_TESTED));
    $plg = (string) file_get_contents(OFFICE_DIR . '/plugin/unraid-secretary-office.plg');
    same('unraid tested: the .plg\'s max agrees with it', officeUnraidMax(), preg_match('/\smax="([^"]+)"/', $plg, $m) ? $m[1] : null);
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/caretaker.php');
    check('unraid tested: the team lead\'s checks ask for it', str_contains($src, 'caretakerUnraidTested($version)'));

    // build.sh refuses a .plg whose max doesn't agree (a stand-in tree with only what its first checks read)
    $tmp = hardeningTmp('unraid-tested');
    $build = function (string $max) use ($tmp): string {
        exec('rm -rf ' . escapeshellarg("$tmp/tree"));
        @mkdir("$tmp/tree/plugin", 0700, true);
        @mkdir("$tmp/tree/src", 0700, true);
        @mkdir("$tmp/tree/agent", 0700, true);
        copy(OFFICE_DIR . '/plugin/build.sh', "$tmp/tree/plugin/build.sh");
        foreach (['src/place.php', 'src/bootstrap.php', 'agent/agent.php'] as $f) {
            copy(OFFICE_DIR . "/$f", "$tmp/tree/$f");
        }
        file_put_contents("$tmp/tree/plugin/unraid-secretary-office.plg", preg_replace('/(\s)max="[^"]+"/', '$1max="' . $max . '"',
            (string) file_get_contents(OFFICE_DIR . '/plugin/unraid-secretary-office.plg'), 1));
        return (string) shell_exec('cd ' . escapeshellarg("$tmp/tree") . ' && bash plugin/build.sh ' . escapeshellarg(AGENT_VERSION) . ' 2026.10.08 2>&1');
    };
    $bad = $build('8.99.99');
    check('unraid tested: build.sh refuses a max beyond the tested major', str_contains($bad, "the .plg's max is '8.99.99'"), $bad);
    $good = $build(officeUnraidMax());
    check('unraid tested: … and passes the one that agrees', !str_contains($good, "the .plg's max") && !str_contains($good, 'OFFICE_UNRAID_TESTED'), $good);
    hardeningRm($tmp);
}

/**
 * The .plg refuses an update while one of the office's long jobs runs from the plugin folder outside the agent: a backup
 * run or the setup (atd, cron), Mr. Restori's restore or drill, Jack Emby's EmbyCache or gather — one pgrep -f
 * pattern; the agent, its night shift and the short jobs don't hold it up. pgrep matches POSIX EREs against the whole
 * command line, as grep -E does here.
 */
function testPlgGuard(): void
{
    $plg = (string) file_get_contents(OFFICE_DIR . '/plugin/unraid-secretary-office.plg');
    $line = preg_match('/^jobs="([^"\n]+)"$/m', $plg, $m) ? $m[1] : '';
    check('plg guard: the pattern is one plain string, pgrep -f uses it', $line !== '' && str_contains($plg, 'pgrep -f "$jobs"'));
    $dir = '/usr/local/emhttp/plugins/unraid-secretary-office';
    $pattern = str_replace(['$dir', '\\$'], [$dir, '$'], $line);
    $hit = function (string $cmd) use ($pattern): bool {
        exec('printf "%s\n" ' . escapeshellarg($cmd) . ' | grep -qE ' . escapeshellarg($pattern), $o, $code);
        return $code === 0;
    };
    $busy = [
        "/bin/bash $dir/backup/backup.sh --check",                              // atd (backupLaunch)
        "bash $dir/backup/backup.sh",                                           // cron (job.sh's exec)
        "/bin/bash $dir/backup/backup.sh --recover",                            // agent.sh backup_recover
        "/bin/bash $dir/backup/setup.sh --plan",
        "/usr/bin/php $dir/agent/agent.php job restore 20261008-125107-32f9",   // hostLaunch (PHP_BINARY)
        "/usr/bin/php $dir/agent/agent.php job restore-drill 20261008-011005-57db",
        "/usr/bin/php $dir/agent/agent.php job gather run --office",
        "php $dir/agent/agent.php job embycache",                               // cron (job.sh's exec)
        "php $dir/agent/agent.php job gather",
        "/usr/bin/php $dir/agent/agent.php job moverelli dry --office",        // Ms. Moverelli's Smart Mover (hostLaunch)
        "php $dir/agent/agent.php job moverelli",                               // cron (job.sh's exec)
    ];
    $free = [
        "php $dir/agent/agent.php run",
        "php $dir/agent/agent.php nightshift",
        "php $dir/agent/agent.php job snapshot-plans",
        "/usr/bin/php $dir/agent/agent.php job restore-partner-look",
        "/usr/bin/php $dir/agent/agent.php job partner-ping",
        "nice -n 10 /usr/bin/php $dir/agent/agent.php job logs-tour",
        "bash $dir/scripts/agent.sh supervise",
        "grep $dir/backup/backup.sh",
        "/usr/bin/php /tmp/x/agent/agent.php job restore 1",
        "bash /tmp/uso-upgrade/backup/backup.sh",
    ];
    same('plg guard: these hold the update up', array_fill(0, count($busy), true), array_map($hit, $busy));
    same('plg guard: these don\'t', array_fill(0, count($free), false), array_map($hit, $free));
    $guard = strpos($plg, 'pgrep -f "$jobs"');
    check('plg guard: before the agent is stopped and the folder replaced', $guard !== false && $guard < strpos($plg, 'scripts/agent.sh" stop') && $guard < strpos($plg, 'rm -rf "$dir"'));
    // the install: unpacked beside and checked before the agent is stopped, then the swap — two renames
    $install = plgScript('install', '/x');
    $at = fn (string $what) => strpos($install, $what);
    check('plg install: the guard, then unpacked beside and checked, then the old agent stopped, the swap, the new agent started',
        $at('pgrep -f "$jobs"') < $at('tar -xJf "$package" -C "$new"') && $at('tar -xJf "$package" -C "$new"') < $at('[ ! -f "$new/$name/scripts/partner-door.sh" ]')
        && $at('[ ! -f "$new/$name/scripts/partner-door.sh" ]') < $at('bash "$dir/scripts/agent.sh" stop') && $at('bash "$dir/scripts/agent.sh" stop') < $at('mv "$dir" "$old/$name"')
        && $at('mv "$dir" "$old/$name"') < $at('mv "$new/$name" "$dir"') && $at('mv "$new/$name" "$dir"') < $at('officeMenuPageApply')
        && $at('officeMenuPageApply') < $at('bash "$dir/scripts/agent.sh" start;') && !str_contains($install, 'rm -rf "$dir"'));
    check('plg install: nothing of the array or var.ini (a boot install runs before emhttp)', !preg_match('/^[^#\n]*(var\.ini|fsState|mdState)/m', $install));
    // the remove: the same guard, first; what the office holds let go before the code goes
    $remove = plgScript('remove', '/x');
    same('plg remove: the same pattern as the install', [$line], preg_match('/^jobs="([^"\n]+)"$/m', $remove, $m) ? [$m[1]] : []);
    $at = fn (string $what) => strpos($remove, $what);
    check('plg remove: the guard first, then agent.sh release, the schedules aside, then the folder goes', $at('pgrep -f "$jobs"') !== false
        && $at('pgrep -f "$jobs"') < $at('bash "$dir/scripts/agent.sh" release') && $at('bash "$dir/scripts/agent.sh" release') < $at('.cron.removed-$stamp')
        && $at('.cron.removed-$stamp') < $at('rm -rf "$dir"'));
}

/**
 * Exact shapes, tolerant writes (CLAUDE.md «Updates», the upgrade audit's finding 4): pairs.json, tickets.json and
 * ticket-pairs.json keep every entry a version doesn't recognise — a newer office's, met after a downgrade — where it
 * stood, as it was, through every write that touches another entry; a file of another `v` is not written over.
 */
function testPartnerTolerant(): void
{
    if (posix_geteuid() !== 0) {
        check('partner tolerant writes: root only — not run here', true);
        return;
    }
    $tmp = hardeningTmp('partner-tolerant');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $file = "$tmp/partner/pairs.json";
    $a = partnerTestPair('a1b2c3d4');
    partnerPairsWrite([$a], $file);
    $raw = fn (): array => json_decode((string) file_get_contents($file), true);
    // from «the future»: a pair with a field this version doesn't know, an entry of a kind it doesn't know, a key beside
    $f1 = partnerTestPair('f1f1f1f1', ['name' => 'later', 'compress' => 'zstd']);
    $f2 = ['id' => 'f2f2f2f2', 'kind' => 'mirror', 'name' => 'mirrorbox', 'address' => '192.168.77.8', 'schedule' => ['every' => 'hour'], 'extra' => [1, 2.5, null, true]];
    $future = ['v' => 1, 'pairs' => [$f1, $a, $f2], 'mirrors_since' => 1791336000];
    file_put_contents($file, json_encode($future, JSON_UNESCAPED_SLASHES) . "\n");
    chmod($file, 0600);
    same('tolerant: the reader takes only the pair in this version\'s shape', ['a1b2c3d4'], array_column(partnerPairs($file), 'id'));
    // a write that touches another entry: the future ones where they stood, as they were
    $a2 = ['name' => 'renamed'] + $a;
    partnerPairsWrite([$a2], $file);
    same('tolerant: a write that changes another pair keeps the future entries where they stood, field for field, and the key beside',
        ['v' => 1, 'pairs' => [$f1, $a2, $f2], 'mirrors_since' => 1791336000], $raw());
    // 1.60: a pair in the shape up to 1.59 (send with units, receive with window and units) is read and written in the new shape
    $old159 = partnerTestPair('c3d4e5f6', ['send' => ['units' => ['share:media'], 'rate_mbit' => 5, 'wanted' => ['share:media', 'place'], 'offered' => null],
        'receive' => ['pool' => 'tank', 'quota_gb' => 10, 'retention' => '2 0 0', 'window' => '00:00-07:00', 'wake' => false, 'units' => ['share:appdata']]]);
    file_put_contents($file, json_encode(['v' => 1, 'pairs' => [$f1, $a2, $f2, $old159]], JSON_UNESCAPED_SLASHES) . "\n");
    chmod($file, 0600);
    same('tolerant: a pair of up to 1.59 is read — its units and window stripped', [['rate_mbit' => 5], ['pool' => 'tank', 'quota_gb' => 10, 'retention' => '2 0 0', 'wake' => false]],
        [partnerPairs($file)[1]['send'] ?? null, partnerPairs($file)[1]['receive'] ?? null]);
    same('tolerant: … reading writes nothing', 'share:media', $raw()['pairs'][3]['send']['units'][0] ?? null);
    partnerPairsWrite(partnerPairs($file), $file);
    same('tolerant: … the next write has the shape of 1.60, in its place', [['rate_mbit' => 5], ['pool' => 'tank', 'quota_gb' => 10, 'retention' => '2 0 0', 'wake' => false]],
        [$raw()['pairs'][3]['send'] ?? null, $raw()['pairs'][3]['receive'] ?? null]);
    $b = partnerTestPair('b2c3d4e5', ['their_key' => null, 'receive' => null]);
    partnerPairsWrite([$a2, $b], $file);
    same('tolerant: a new pair at the end', ['f1f1f1f1', 'a1b2c3d4', 'f2f2f2f2', 'b2c3d4e5'], array_column($raw()['pairs'], 'id'));
    partnerPairsWrite([$b], $file);
    same('tolerant: a pair ended goes, the future ones stay', [$f1, $f2, $b], $raw()['pairs']);
    // an old-shape pair (send before 2.29) is this version's: written in the shape of 1.60, in its place
    $old = $raw();
    $old['pairs'][2]['send'] = ['units' => ['share:media'], 'rate_mbit' => 0];
    file_put_contents($file, json_encode($old, JSON_UNESCAPED_SLASHES));
    partnerPairsWrite(partnerPairs($file), $file);
    same('tolerant: an old-shape pair upgraded in its place, the others untouched', [$f1, $f2, array_replace($b, ['send' => ['rate_mbit' => 0]])],
        $raw()['pairs']);
    // a file of another v: not this version's to write
    $v2 = json_encode(['v' => 2, 'pairs' => [$a]]);
    file_put_contents($file, $v2);
    try {
        partnerPairsWrite([$b], $file);
        check('tolerant: a pairs.json of another v is not written over', false);
    } catch (Problem $e) {
        same('tolerant: a pairs.json of another v is not written over', ['partner_shape', $v2], [$e->key, file_get_contents($file)]);
    }

    // tickets.json and ticket-pairs.json, the same way (written by the office's own functions, as that office)
    $B = partnerTestOffice("$tmp/B");
    $now = time();
    $ticket = fn (string $tid, array $over = []) => $over + ['id' => $tid, 'of' => 'a1b2c3d4', 'name' => 'newbox', 'address' => '192.168.77.9', 'from' => '192.168.77.9',
        'key' => partnerFingerprint(partnerTestKey()), 'created' => $now - 60, 'expires' => $now + 3600, 'units' => ['share:appdata']];
    partnerTestAs($B, 'partnerTicketsWrite(' . var_export([$ticket('c3c3c3c3')], true) . '); return true;');
    $tf = "$B[data]/partner/tickets.json";
    $ft = $ticket('e5e5e5e5', ['scope' => 'all']);
    file_put_contents($tf, json_encode(['v' => 1, 'tickets' => [$ft, $ticket('c3c3c3c3')]]));
    $d4 = $ticket('d4d4d4d4');
    partnerTestAs($B, 'partnerTicketsWrite(' . var_export([$d4], true) . '); return true;');
    same('tolerant: tickets.json — a future ticket kept, the one given up gone, the new one at the end', ['v' => 1, 'tickets' => [$ft, $d4]],
        json_decode((string) file_get_contents($tf), true));
    same('tolerant: … and never used', ['d4d4d4d4'], array_column(partnerTestAs($B, 'return partnerTickets();'), 'id'));
    $pf = "$B[data]/partner/ticket-pairs.json";
    $tp = ['id' => 'c3c3c3c3', 'kind' => 'ticket', 'name' => 'oldbox', 'of' => 'homeserver', 'address' => '192.168.77.2', 'port' => 22,
           'host_keys' => [partnerFingerprint(partnerTestKey())], 'my_key' => partnerFingerprint(partnerTestKey()), 'units' => ['share:appdata'],
           'expires' => $now + 3600, 'paired' => $now - 60, 'last_heard' => null];
    $ftp = ['kind' => 'restore-all', 'id' => 'e6e6e6e6'] + $tp;
    file_put_contents($pf, json_encode(['v' => 1, 'pairs' => [$ftp]]));
    chmod($pf, 0600);
    partnerTestAs($B, 'partnerTicketPairsWrite(' . var_export([$tp], true) . '); return true;');
    same('tolerant: ticket-pairs.json — a future ticket pair kept, the new one at the end', [$ftp, $tp], json_decode((string) file_get_contents($pf), true)['pairs'] ?? null);
    hardeningRm($tmp);
}

/**
 * One of the .plg's inline scripts ('install' or 'remove'), pointed at a folder of the tests: the plugin folder under
 * $root/plugins, the flash $root/flash, the RAM folder $root/run — nothing of the live plugin is touched.
 */
function plgScript(string $method, string $root): string
{
    $plg = (string) file_get_contents(OFFICE_DIR . '/plugin/unraid-secretary-office.plg');
    $re = $method === 'remove' ? '/<FILE Run="\/bin\/bash" Method="remove">\s*<INLINE>\s*<!\[CDATA\[\n(.*?)\]\]>/s'
                               : '/<FILE Run="\/bin\/bash">\s*<INLINE>\s*<!\[CDATA\[\n(.*?)\]\]>/s';
    $s = preg_match($re, $plg, $m) ? $m[1] : '';
    return strtr($s, ['dir=/usr/local/emhttp/plugins/$name' => "dir=$root/plugins/\$name", 'flash=/boot/config/plugins/$name' => "flash=$root/flash",
                      'run=/var/run/$name' => "run=$root/run", 'docker=/boot/config/docker.cfg' => "docker=$root/docker.cfg", 'keys=/boot/config/ssh/root/authorized_keys' => "keys=$root/authorized_keys",
                      '/usr/local/sbin/update_cron' => "$root/update_cron", '@VERSION@' => '2026.10.08', '@OFFICE_VERSION@' => '1.42.0']);
}

/** A stand-in of the plugin folder's agent.sh: each call a line "<marker> <command>" in $USO_PLG_LOG; START and STATUS its exits */
function plgTestAgentSh(): string
{
    return "#!/bin/bash\nhere=\$(cd \"\$(dirname \"\$0\")/..\" && pwd)\necho \"\$(cat \"\$here/marker\") \$*\" >>\"\$USO_PLG_LOG\"\n"
        . "case \"\$1\" in start) exit \${START:-0} ;; status) exit \${STATUS:-3} ;; esac\nexit 0\n";
}

/** The .plg's remove (pointed at the tests' folders): the busy guard, what the office holds let go, the schedules aside */
function testPlgRemove(): void
{
    $tmp = hardeningTmp('plgremove');
    $name = 'unraid-secretary-office';
    $dir = "$tmp/plugins/$name";
    $flash = "$tmp/flash";
    $log = "$tmp/calls.log";
    $script = plgScript('remove', $tmp);
    file_put_contents("$tmp/remove.sh", $script);
    check('plg remove: the script read, pointed at the tests\' folders', str_contains($script, "dir=$tmp/plugins/\$name")
        && !preg_match('#/usr/local/emhttp/plugins/\$name|/boot/config/(plugins|ssh)|/usr/local/sbin#', $script), $script);
    file_put_contents("$tmp/update_cron", "echo update_cron >>\"\$USO_PLG_LOG\"\n");
    $cron = "# Unraid Secretary Office - written by the office, change it there\n0 2 * * * bash /usr/local/emhttp/plugins/$name/scripts/job.sh backup > /dev/null 2>&1\n";
    $benj = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIBenjBenjBenjBenjBenjBenjBenjBenjBenjBenj benj@MacBook\n";
    $installed = function () use ($tmp, $dir, $flash, $name, $cron, $benj): void {
        hardeningRm($dir);
        hardeningRm($flash);
        mkdir("$dir/scripts", 0755, true);
        mkdir("$dir/backup", 0755, true);
        mkdir("$flash/partners", 0700, true);
        file_put_contents("$dir/marker", 'old');
        file_put_contents("$dir/scripts/agent.sh", plgTestAgentSh());
        file_put_contents("$dir/backup/backup.sh", "sleep 20\ntrue\n");
        file_put_contents("$flash/$name.cfg", "DATA_DIR=\"/mnt/user/appdata/UnraidSecretaryOffice/data\"\n");
        file_put_contents("$flash/$name.cron", $cron);
        file_put_contents("$flash/$name.cron.removed-20260101-010101", 'an earlier remove\'s');
        file_put_contents("$flash/agent-watch.cron", "*/5 * * * * bash /usr/local/emhttp/plugins/$name/scripts/job.sh watch > /dev/null 2>&1\n");
        file_put_contents("$flash/$name-2026.10.08.txz", 'the package');
        file_put_contents("$flash/partners/a1b2c3d4.key", 'a key');
        file_put_contents("$tmp/authorized_keys", $benj . "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIPartPartPartPartPartPartPartPartPartPart uso-partner:a1b2c3d4\n");
    };
    $run = function () use ($tmp, $log): array {
        @unlink($log);
        exec('cd / && env USO_PLG_LOG=' . escapeshellarg($log) . ' bash ' . escapeshellarg("$tmp/remove.sh") . ' 2>&1', $out, $code);
        return [$code, implode("\n", $out), is_file($log) ? file($log, FILE_IGNORE_NEW_LINES) : []];
    };
    $asides = fn (): array => array_map('basename', glob("$flash/$name.cron.removed-*") ?: []);

    // busy: a backup run from the plugin folder — nothing removed, nothing released
    $installed();
    $busy = proc_open(['bash', "$dir/backup/backup.sh"], [['file', '/dev/null', 'r'], ['file', '/dev/null', 'w'], ['file', '/dev/null', 'w']], $pipes, '/');
    usleep(200000);
    [$code, $out, $calls] = $run();
    same('plg remove while a backup runs: refused, nothing touched', [1, [], true, $cron, true],
        [$code, $calls, is_dir($dir), @file_get_contents("$flash/$name.cron"), is_file("$flash/partners/a1b2c3d4.key")]);
    check('plg remove while a backup runs: it says why', str_contains($out, 'The office is busy right now') && str_contains($out, 'Nothing was removed'), $out);
    if (is_resource($busy)) {
        proc_terminate($busy, SIGKILL);
        proc_close($busy);
    }

    // the remove: released first (agent.sh release, while the scripts are there), the schedules aside, the rest as before
    [$code, $out, $calls] = $run();
    $aside = $asides();
    same('plg remove: what the office holds let go first, then update_cron, the code gone', [0, ['old release', 'update_cron'], false], [$code, $calls, file_exists($dir)]);
    check('plg remove: the schedules aside, byte for byte, the earlier aside made way', count($aside) === 1 && preg_match('/^' . preg_quote($name) . '\.cron\.removed-\d{8}-\d{6}$/D', $aside[0])
        && $aside[0] !== "$name.cron.removed-20260101-010101" && file_get_contents("$flash/$aside[0]") === $cron && !file_exists("$flash/$name.cron"), json_encode($aside));
    same('plg remove: the watch line, the partners\' keys and their lines, the package and the mirror gone; the .cfg kept',
        [false, false, $benj, false, true], [file_exists("$flash/agent-watch.cron"), file_exists("$flash/partners"), file_get_contents("$tmp/authorized_keys"),
        file_exists("$flash/$name-2026.10.08.txz"), is_file("$flash/$name.cfg")]);
    check('plg remove: it says that the partnerships ended and where the schedules went', str_contains($out, 'partnerships with other offices have ended')
        && str_contains($out, "$flash/$aside[0]") && str_contains($out, 'puts them back'), $out);

    // nothing of that: no word about it
    $installed();
    unlink("$flash/$name.cron");
    hardeningRm("$flash/partners");
    file_put_contents("$tmp/authorized_keys", $benj);
    [$code, $out, $calls] = $run();
    same('plg remove without schedules or partners: done, the earlier aside kept, nothing said of either', [0, ["$name.cron.removed-20260101-010101"], false, false],
        [$code, $asides(), str_contains($out, 'partnerships'), str_contains($out, 'put aside')]);
    // no plugin folder (a broken install): removed all the same
    hardeningRm($dir);
    [$code, , $calls] = $run();
    same('plg remove without the plugin folder: done, nothing to release', [0, []], [$code, $calls]);

    // agent.sh release: what the array stop releases, without the night shift — and the array stop uses it
    $sh = (string) file_get_contents(OFFICE_DIR . '/plugin/scripts/agent.sh');
    $body = preg_match('/^release\(\) \{\n(.*?)^\}/ms', $sh, $m) ? preg_replace('/\s*#.*$/m', '', $m[1]) : '';
    same('agent.sh release: the agent stopped, then drill, partner door, backup mounts, Mr. Restori\'s pulls',
        ['stop', 'drill_release', 'partner_release', 'backup_release', 'restored_release'], preg_split('/\s+/', trim($body)));
    check('agent.sh: the array stop releases the same way, then the night shift; "release" is a command', preg_match('/\n\s+release\s+# [^\n]*\n\s+night_start/', $sh)
        && str_contains($sh, '    release)   release ;;'));
    hardeningRm($tmp);
}

/** officeCronBack(): the schedules a remove put aside, back at the agent's start — only when there is no cron file */
function testCronBack(): void
{
    $tmp = hardeningTmp('cronback');
    $file = "$tmp/unraid-secretary-office.cron";
    $lines = [];
    $applied = 0;
    $apply = function () use (&$applied): void { $applied++; };
    $logf = function (string $l) use (&$lines): void { $lines[] = $l; };
    $cron = '0 2 * * * ' . officeJobCommand('backup') . "\n" . '*/5 * * * * ' . officeJobCommand('snapshots') . "\n";
    same('cron back: nothing aside, nothing done', [null, 0, []], [officeCronBack($file, $apply, $logf), $applied, $lines]);
    file_put_contents("$file.removed-20260101-010101", "an older one\n");
    file_put_contents("$file.removed-20261008-120000", $cron);
    file_put_contents("$file.removed-notatime", "not ours\n");
    same('cron back: the newest aside back, byte for byte, the crontab told', ["$file.removed-20261008-120000", $cron, 1],
        [officeCronBack($file, $apply, $logf), @file_get_contents($file), $applied]);
    check('cron back: said in the log with its jobs', count($lines) === 1 && str_contains($lines[0], 'schedules from before the removal are back')
        && str_contains($lines[0], 'backup, snapshots'), json_encode($lines));
    same('cron back: the others left as they are', ["$file.removed-20260101-010101", "$file.removed-notatime"], glob("$file.removed-*"));
    same('cron back: a cron file there — nothing done', [null, 1, "an older one\n"], [officeCronBack($file, $apply, $logf), $applied, file_get_contents("$file.removed-20260101-010101")]);
    unlink($file);
    symlink("$tmp/elsewhere", "$file.removed-20261009-000000");
    same('cron back: an aside that is a link is none', "$file.removed-20260101-010101", officeCronBack($file, $apply, $logf));
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/agent.php');
    $setUp = preg_match('/^function setUp\(\): void\n\{\n(.*?)^\}/ms', $src, $m) ? $m[1] : '';
    $at = fn (string $s) => strpos($setUp, $s);
    check('cron back: in setUp(), after the steps, before the desks\' start', $at('officeCronBack()') !== false && $at('officeMigrateStart()') < $at('officeCronBack()')
        && $at('officeCronBack()') < $at('foreach (desks()'));
    hardeningRm($tmp);
}

function testPlgInstall(): void
{
    $tmp = hardeningTmp('plginstall');
    $name = 'unraid-secretary-office';
    $dir = "$tmp/plugins/$name";
    $flash = "$tmp/flash";
    $log = "$tmp/calls.log";
    $script = plgScript('install', $tmp);
    file_put_contents("$tmp/install.sh", $script);
    check('plg install: the script read, pointed at the tests\' folders', str_contains($script, "dir=$tmp/plugins/\$name") && !str_contains($script, '/usr/local/emhttp/plugins/$name')
        && !str_contains($script, '/boot/config/plugins/$name') && !str_contains($script, '/var/run/$name'));
    // a package: what the build puts in, as far as the install looks at it
    $pack = function (string $marker, array $leave = [], bool $broken = false) use ($tmp, $name, $flash): void {
        hardeningRm("$tmp/stage");
        $p = "$tmp/stage/$name";
        foreach (['agent', 'scripts', 'backup', 'src'] as $d) {
            @mkdir("$p/$d", 0755, true);
        }
        file_put_contents("$p/marker", $marker);
        // the menu step's php (place.php) as a stub: without it each run left a «Failed opening required» in Unraid's phplog
        file_put_contents("$p/src/place.php", "<?php\nfunction officeMenuName(): string { return 'Sekretariat'; }\nfunction officeMenuPlace(): string { return 'tasks'; }\nfunction officeMenuPageApply(string \$d, string \$n, string \$p): void {}\n");
        file_put_contents("$p/agent/agent.php", "<?php\n");
        file_put_contents("$p/scripts/agent.sh", plgTestAgentSh());
        file_put_contents("$p/scripts/partner-door.sh", "#!/bin/bash\n");
        foreach ($leave as $f) {
            unlink("$p/$f");
        }
        @mkdir($flash, 0700, true);
        $txz = "$flash/$name-2026.10.08.txz";
        exec('tar -cJf ' . escapeshellarg($txz) . ' -C ' . escapeshellarg("$tmp/stage") . " $name");
        if ($broken) {
            file_put_contents($txz, substr((string) file_get_contents($txz), 0, 200));
        }
    };
    $old = function () use ($dir): void {          // the version that runs now
        hardeningRm($dir);
        mkdir("$dir/scripts", 0755, true);
        mkdir("$dir/backup", 0755, true);
        file_put_contents("$dir/marker", 'old');
        file_put_contents("$dir/gone.txt", 'only the old version has me');
        file_put_contents("$dir/scripts/agent.sh", plgTestAgentSh());
        file_put_contents("$dir/backup/backup.sh", "sleep 20\ntrue\n");     // not exec'd into sleep: bash stays
    };
    $run = function (array $env = []) use ($tmp, $log): array {
        @unlink($log);
        $e = '';
        foreach ($env + ['USO_PLG_LOG' => $log] as $k => $v) {
            $e .= "$k=" . escapeshellarg((string) $v) . ' ';
        }
        exec("cd / && env $e bash " . escapeshellarg("$tmp/install.sh") . ' 2>&1', $out, $code);
        return [$code, implode("\n", $out), is_file($log) ? file($log, FILE_IGNORE_NEW_LINES) : []];
    };
    $left = fn (): array => array_values(array_filter(scandir("$tmp/plugins") ?: [], fn ($n) => $n !== '.' && $n !== '..' && $n !== $name));

    // at boot: no folder yet — unpacked, put into place, the agent (or the night shift) started
    $pack('new');
    @mkdir("$tmp/plugins", 0755, true);
    [$code, $out, $calls] = $run();
    same('plg install at boot: done, the new version in place, its agent started', [0, 'new', ['new start', 'new status']],
        [$code, @file_get_contents("$dir/marker"), $calls]);
    same('plg install at boot: nothing left beside it', [], $left());
    check('plg install at boot: the .cfg written', str_contains((string) @file_get_contents("$flash/$name.cfg"), 'DATA_DIR="'));
    check('plg install at boot: it says it is installed', str_contains($out, 'Unraid Secretary Office 1.42.0 (plugin 2026.10.08) is installed'));

    // an update: the old agent stopped, the new folder in place of the old one (files the new one lacks are gone), the
    // new agent started, older packages off the flash
    $old();
    file_put_contents("$flash/$name-2026.01.01.txz", 'an older package');
    [$code, , $calls] = $run();
    same('plg update: the old agent stopped, the new one started, the new version in place', [0, ['old stop', 'new start', 'new status'], 'new', false],
        [$code, $calls, @file_get_contents("$dir/marker"), is_file("$dir/gone.txt")]);
    same('plg update: nothing left beside it, the older package gone, this one kept', [[], false, true],
        [$left(), is_file("$flash/$name-2026.01.01.txz"), is_file("$flash/$name-2026.10.08.txz")]);

    // a package that can't be unpacked, or one without what the office needs: nothing changed, the agent never stopped
    foreach (['a damaged package' => [[], true], 'a package without agent.php' => [['agent/agent.php'], false],
              'a package without the partners\' door' => [['scripts/partner-door.sh'], false]] as $what => [$leave, $broken]) {
        $old();
        $pack('new', $leave, $broken);
        [$code, $out, $calls] = $run();
        same("plg update, $what: refused, the old version untouched and running", [1, 'old', true, []],
            [$code, @file_get_contents("$dir/marker"), is_file("$dir/gone.txt"), $calls]);
        check("plg update, $what: it says so", str_contains($out, 'could not be unpacked') && str_contains($out, 'Nothing was changed'), $out);
        same("plg update, $what: nothing left beside it", [], $left());
    }

    // what an install that was cut off left: gone — not a folder of an install running right now
    $old();
    $pack('new');
    mkdir("$tmp/plugins/$name.new-999999999/$name", 0755, true);
    mkdir("$tmp/plugins/$name.old-999999998/$name", 0755, true);
    mkdir("$tmp/plugins/$name.new-" . getmypid(), 0755, true);
    $run();
    same('plg update: an earlier install\'s leftovers gone, a running one\'s kept', ["$name.new-" . getmypid()], $left());
    rmdir("$tmp/plugins/$name.new-" . getmypid());

    // after the swap the new version stays: an agent that doesn't start is said, the install still ends well
    $old();
    [$code, $out, $calls] = $run(['START' => 1]);
    same('plg update, the new agent doesn\'t start: the new version stays, done', [0, 'new', ['old stop', 'new start']], [$code, @file_get_contents("$dir/marker"), $calls]);
    check('plg update, the new agent doesn\'t start: it says so', str_contains($out, 'its agent did not start'), $out);
    // the agent runs: its heartbeat in RAM, written after the start, ends the wait at once
    $old();
    @mkdir("$tmp/run", 0700, true);
    file_put_contents("$tmp/run/agent.json", '{"running":true,"version":"1.42.0"}');
    touch("$tmp/run/agent.json", time() + 5);
    $t = microtime(true);
    [$code, $out] = $run(['STATUS' => 0]);
    check('plg update, the agent checked in: no word about it, no wait', $code === 0 && !str_contains($out, 'checked in') && microtime(true) - $t < 5, $out);

    // busy: a backup run from the plugin folder — refused before anything happens
    $old();
    $busy = proc_open(['bash', "$dir/backup/backup.sh"], [['file', '/dev/null', 'r'], ['file', '/dev/null', 'w'], ['file', '/dev/null', 'w']], $pipes, '/');
    usleep(200000);
    [$code, $out, $calls] = $run();
    same('plg update while a backup runs: refused, nothing touched', [1, 'old', []], [$code, @file_get_contents("$dir/marker"), $calls]);
    check('plg update while a backup runs: it says why', str_contains($out, 'The office is busy right now'), $out);
    if (is_resource($busy)) {
        proc_terminate($busy, SIGKILL);
        proc_close($busy);
    }
    hardeningRm($tmp);
}

/**
 * The engine's lock seen through shfs (QA 2026-10-08, finding 1): on a data folder whose share isn't exclusive the flock
 * lies on the pool's file — /proc/locks names that one, never the inode stat() shows through /mnt/user — so «Stop the
 * run» said «not running». flockHeld() looks for the file behind shfs ((dev << 48) | ino, Unraid 7.3.2), and probes
 * (a shared flock without waiting, let go at once) only a FUSE file whose number names no mounted device. A stand-in
 * holds the lock in a process of its own; the folder is reached two ways; shfs's view is a stat() as it would show it.
 */
function testFlockShfs(): void
{
    $tmp = hardeningTmp('flock');
    mkdir("$tmp/data/state", 0700, true);
    symlink("$tmp/data", "$tmp/user");                   // the same folder a second way
    $lock = "$tmp/data/state/lock";
    touch($lock);
    $p = proc_open([PHP_BINARY, '-r', '$h = fopen($argv[1], "r"); flock($h, LOCK_EX); echo "held\n"; sleep(30);', $lock],
        [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['file', '/dev/null', 'w']], $pipes);
    $ready = trim((string) fgets($pipes[1])) === 'held';
    $pid = proc_get_status($p)['pid'];
    check('flock: the stand-in holds the lock', $ready);
    check('flock: held — seen on its path', flockHeld($lock));
    check('flock: … and the other way', flockHeld("$tmp/user/state/lock"));
    file_put_contents("$tmp/data/state/lock-holder.json", json_encode(['holder' => 'restore', 'what' => 'zz-app', 'pid' => $pid, 'started' => time()]));
    same('flock: who holds it, the other way', ['restore', 'zz-app'], [backupLockHolder("$tmp/user")['holder'] ?? null, backupLockHolder("$tmp/user")['what'] ?? null]);

    // the file as /mnt/user of a share that isn't exclusive shows it: shfs's device, (dev << 48) | ino of the file behind
    $st = stat($lock);
    $major = (($st['dev'] >> 8) & 0xfff) | (($st['dev'] >> 32) & ~0xfff);
    $minor = ($st['dev'] & 0xff) | (($st['dev'] >> 12) & ~0xff);
    $shfs = ['dev' => 0x34, 'ino' => (($st['dev'] & 0xffff) << 48) | $st['ino']];
    $fuse = "59 44 0:52 / /mnt/user rw,nosuid,nodev,noatime shared:15 - fuse.shfs shfs rw,user_id=0,group_id=0\n";
    $pool = "48 44 $major:$minor / /mnt/cache rw,noatime shared:5 - zfs cache rw,xattr\n";
    check('flock: its device fits shfs\'s 16 bits (the test\'s own premise)', ($st['dev'] & 0xffff) === $st['dev']);
    check('flock: through shfs, the pool\'s file found', flockHeld($lock, $shfs, $fuse . $pool));
    same('flock: … what it looks for', ['ids' => [flockId(0x34, $shfs['ino']), flockId($st['dev'], $st['ino'])], 'probe' => false], flockIds($shfs, $fuse . $pool));
    // a partner test server, 2026-10-08: stat through /mnt/user dev=2e ino=11258999068426506, /proc/locks 00:28:266 (cache pool, inode 266)
    same('flock: a partner test server\'s numbers', ['ids' => ['00:2e:11258999068426506', '00:28:266'], 'probe' => false],
        flockIds(['dev' => 0x2e, 'ino' => 11258999068426506], "59 44 0:46 / /mnt/user rw - fuse.shfs shfs rw\n48 44 0:40 / /mnt/cache rw - zfs cache rw\n"));
    // a FUSE file whose number names no mounted device: probed — busy while held, never blocking, never taking it away
    same('flock: an unknown FUSE number is probed', true, flockIds($shfs, $fuse)['probe']);
    $t = microtime(true);
    check('flock: the probe says held', flockHeld($lock, $shfs, $fuse));
    check('flock: … at once', microtime(true) - $t < 0.5);
    check('flock: … and the stand-in still holds it', flockHeld($lock) && proc_get_status($p)['running']);
    // anything else that isn't FUSE: only its own id, no probe
    same('flock: a ZFS file with a big inode: its own id only', ['ids' => [flockId(0x34, $shfs['ino'])], 'probe' => false],
        flockIds($shfs, "59 44 0:52 / /mnt/big rw - zfs big rw\n"));
    same('flock: a block device: its own id only', ['ids' => [flockId(0x901, 5)], 'probe' => false], flockIds(['dev' => 0x901, 'ino' => 5], $fuse));

    proc_terminate($p);
    proc_close($p);
    for ($i = 0; $i < 100 && flockHeld($lock); $i++) {
        usleep(20000);
    }
    check('flock: let go — not held, any way', !flockHeld($lock) && !flockHeld("$tmp/user/state/lock") && !flockHeld($lock, $shfs, $fuse . $pool)
        && !flockHeld($lock, $shfs, $fuse));
    same('flock: … nobody holds it', null, backupLockHolder("$tmp/user"));
    exec('flock -n ' . escapeshellarg($lock) . ' true 2>&1', $out, $rc);
    same('flock: the probe let go — a run\'s flock -n takes it', 0, $rc);
    hardeningRm($tmp);
}

/**
 * One run a minute (QA 2026-10-08, finding 3): the run id, its log and the snapshots' name carry the minute — a second
 * «Back up now» in the same minute failed («ZFS snapshot … failed») and left two history lines with one id. The office
 * refuses it (backupMinuteTaken(): the last run's id, or this mode's log), and backup.sh itself ends right after taking
 * the lock when its log is there already — an ERROR line, exit 1, nothing of that run touched (engine 2.34).
 */
/** «Abort» sent: the page says so until that run ends (2026-10-10: a «docker stop -t 60» held the trap a minute) */
function testBackupAbortAsked(): void
{
    $f = backupAbortFile();
    @unlink($f);
    same('abort asked: none noted - null', null, backupAbortAsked(true, ['pid' => 42]));
    writeAtomic($f, jsonEncode(['pid' => 42, 'at' => 1000]), 0600);
    same('abort asked: noted for this run\'s PID - its time; in RAM, root only', [1000, '600'], [backupAbortAsked(true, ['pid' => 42]), sprintf('%o', fileperms($f) & 0777)]);
    same('abort asked: another run (another PID) or no run going - null', [null, null], [backupAbortAsked(true, ['pid' => 43]), backupAbortAsked(false, ['pid' => 42])]);
    same('abort asked: no status yet - null', null, backupAbortAsked(true, null));
    @unlink($f);
}

function testBackupOneMinute(): void
{
    $tmp = hardeningTmp('minute');
    $data = "$tmp/data";
    @mkdir("$data/state", 0700, true);
    @mkdir("$data/logs", 0700, true);
    $now = mktime(1, 2, 40, 10, 8, 2026);
    same('one a minute: nothing ran yet', null, backupMinuteTaken('backup', $data, $now));
    file_put_contents("$data/state/status.json", json_encode(['run' => '20261008-0101', 'result' => 'ok']));
    same('one a minute: the last run a minute before', null, backupMinuteTaken('backup', $data, $now));
    file_put_contents("$data/state/status.json", json_encode(['run' => '20261008-0102', 'result' => 'ok']));
    same('one a minute: the last run this minute — 20 s to wait', 20, backupMinuteTaken('backup', $data, $now));
    same('one a minute 1.60.1: only a real backup waits (its snapshots carry the minute) - a tour or a dry run never', [20, null, null],
        [backupMinuteTaken('nokopia', $data, $now), backupMinuteTaken('dryrun', $data, $now), backupMinuteTaken('check', $data, $now)]);
    file_put_contents("$data/state/status.json", json_encode(['run' => '20261008-0102', 'mode' => 'check', 'result' => 'ok']));
    same('one a minute 1.60.1: a tour this minute - a backup needn\'t wait', null, backupMinuteTaken('backup', $data, $now));
    file_put_contents("$data/state/status.json", json_encode(['run' => '20261008-0101', 'result' => 'ok']));
    touch("$data/logs/check-20261008-0102.log");
    same('one a minute: a check\'s log this minute — neither another check nor a backup waits', [null, null], [backupMinuteTaken('check', $data, $now), backupMinuteTaken('backup', $data, $now)]);
    touch("$data/logs/run-20261008-0102.log");
    same('one a minute: a run\'s log this minute', [20, 20, null], [backupMinuteTaken('backup', $data, $now), backupMinuteTaken('nokopia', $data, $now), backupMinuteTaken('dryrun', $data, $now)]);
    $start = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    check('one a minute 1.60.1: backupStart() asks before it launches - a taken minute queues the backup for the next one (atd), never a refusal',
        ($a = strpos($start, 'return backupQueue($mode, $dir, $wait);')) !== false && $a < strpos($start, 'backupLaunch(array_merge([$dir')
        && str_contains($start, "hostLaunch('backup-queued', ['/bin/sh', '-c', \$script]") && str_contains($start, "'start_cancel' => fn (array \$r) => backupQueueCancel(),"));
    $eng0 = (string) file_get_contents(OFFICE_DIR . '/backup/backup.sh');
    check('one a minute 2.45: a tour\'s and a dry run\'s log carry the second; a setup\'s too', str_contains($eng0, 'check)   LOG_FILE="$UB_LOGS/check-$TSS.log" ;;')
        && str_contains($eng0, 'LOG_FILE="$UB_LOGS/dryrun-$TSS.log"') && str_contains((string) file_get_contents(OFFICE_DIR . '/backup/setup.sh'), 'LOG_FILE="$UB_LOGS/setup-$(date +%Y%m%d-%H%M%S).log"'));
    $names = ['check-20261012-1721.log', 'check-20261012-172002.log', 'check-20261012-1720.log', 'check-20261012-171959.log'];
    sort($names, SORT_STRING);
    same('one a minute 2.45: by name a seconds log sorts after its minute\'s and before the next minute (the engine\'s pruning, sort)',
        ['check-20261012-171959.log', 'check-20261012-1720.log', 'check-20261012-172002.log', 'check-20261012-1721.log'], $names);
    $sorted = (string) shell_exec("printf '%s\\n' check-20261012-1721.log check-20261012-172002.log check-20261012-1720.log | LC_ALL=C sort -t- -k2");
    same('one a minute 2.45: … the engine\'s own sort -t- -k2 too', "check-20261012-1720.log\ncheck-20261012-172002.log\ncheck-20261012-1721.log\n", $sorted);
    same('one a minute 2.45: the office lists a log named by the second', ['check', mktime(17, 20, 2, 10, 12, 2026)],
        (function () { preg_match(BACKUP_LOG_NAME, 'check-20261012-172002.log', $m); return [$m[1] ?? null, (int) DateTime::createFromFormat('Ymd-His', "$m[2]-$m[3]")->getTimestamp()]; })());
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/en.json'), true);
    check('one a minute: its words, with the seconds', str_contains($en['errors.one_run_a_minute'] ?? '', '{seconds}'));

    // the engine: its log of this minute is there (the tests' clock: 2026-10-08 01:02, whatever the real one says)
    $eng = "$tmp/eng";
    @mkdir("$eng/state", 0700, true);
    @mkdir("$eng/logs", 0700, true);
    @mkdir("$tmp/bin", 0700, true);
    touch("$eng/state/lock", 1000);
    testsClock("$tmp/bin", "$tmp/clock", mktime(1, 2, 0, 10, 8, 2026));
    foreach (['run', 'dryrun', 'check'] as $kind) {
        touch("$eng/logs/$kind-20261008-0102.log");
    }
    foreach (['backup' => []] as $what => $args) {          // 2.45: only a real backup - a tour's or dry run's log carries the second
        $p = proc_open(array_merge(['bash', OFFICE_DIR . '/backup/backup.sh'], $args), [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, null,
            ['UB_DATA' => $eng, 'UB_NO_NOTIFY' => '1', 'PATH' => "$tmp/bin:" . getenv('PATH'), 'OFFICE_RUN_DIR' => TESTS_RUN_DIR]);
        $out = (string) stream_get_contents($pipes[1]);
        $err = (string) stream_get_contents($pipes[2]);
        $rc = proc_close($p);
        check("one a minute: the engine's $what ends — exit 1, an ERROR line", $rc === 1 && str_contains($err, 'ERROR: a run of this minute was made already'), "rc $rc: $out $err");
        clearstatcache();
        same("one a minute: … nothing of the run touched ($what)", [false, false, false, false, 1000],
            [is_file("$eng/state/status.json"), is_file("$eng/state/lock-holder.json"), is_link("$eng/logs/latest.log"), is_file("$eng/state/skipped.json"), filemtime("$eng/state/lock")]);
    }
    same('one a minute: every date call one the tests\' clock knows', '', testsClockUnsupported("$tmp/clock"));

    // the page (2026-10-12, Benj: «Tour» right after an apply met the refusal — the apply's own tour had just run): it knows
    // the last run's start and greys «Tour», «Start a run…» and the menu's runs until the minute changes, the tooltip
    // counting down, the bubble saying which run just ran; the agent's refusal stays the last guard
    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('one a minute: page - node is missing here - skipped', true);
        hardeningRm($tmp);
        return;
    }
    $js = <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const node = (tag, cls, text) => ({ tag, cls, text, title: '', disabled: false, dataset: {}, appendChild() {}, append() {} });
globalThis.Office = { scope: () => T, t: T, el: node, fmt: { time: (t) => `time(${t})`, relative: (t) => `rel(${t})`, date: (t) => `date(${t})`, size: (b) => b + ' B' },
  desk: () => {}, places: () => {}, placesFrom: () => {}, placesTook: () => {}, selbar: () => {}, has: () => false, agent: { running: true }, dialogOpen: () => false };
let timers = 0;
globalThis.setInterval = () => ++timers;       // the countdown's ticks are not run here (node would never end)
globalThis.clearInterval = () => {};
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const b = OFFICE_DESK_TESTS.backup;
const now = Math.floor(Date.now() / 1000);
const minute = Math.floor(now / 60) * 60;
const st = (status, more) => ({ found: true, compatible: true, running: false, history: [], status, ...more });
const out = { minute };
b.setState(st({ mode: 'check', started: minute + 0, finished: minute + 5, result: 'ok' }));
out.check = b.minuteTaken(minute + 51);
b.setState(st({ mode: 'backup', started: minute + 0, finished: minute + 5, result: 'ok' }));
const m = b.minuteTaken(minute + 51);
out.taken = [m && m.left, m && m.mode, b.minuteTaken(minute + 60), b.minuteTaken(minute - 1) && b.minuteTaken(minute - 1).left];
out.bubble = b.bubbleText('').filter((x) => x.startsWith('minute.'));
const acts = b.deskActions();
out.buttons = acts.map((x) => [x.text, x.disabled, x.title.replace(/\d+/, 'n')]);
out.timer = timers > 0;
b.setState(st({ mode: 'backup', started: minute - 70, finished: minute - 3, result: 'ok' }));
out.older = [b.minuteTaken(), b.deskActions().map((x) => [x.disabled, x.title]), b.bubbleText('').filter((x) => x.startsWith('minute.'))];
b.setState(st({ mode: 'dryrun', started: now, result: 'running' }, { running: true, holder: { holder: 'dryrun' } }));
out.live = b.minuteTaken();
b.setState(st({ mode: 'dryrun', started: now, result: 'ok' }));
out.dry = b.minuteTaken();
b.setState(st({ mode: 'backup', started: minute, result: 'ok' }, { queued: { at: minute + 60, mode: 'backup' } }));
out.queued = [b.bubbleText('').filter((x) => x.startsWith('minute.queued')).length, b.deskActions().map((x) => x.text)];
console.log(JSON.stringify(out));
JS;
    file_put_contents("$tmp/minute.js", $js);
    $r = json_decode((string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/minute.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/backup/desk.js') . ' 2>&1'), true);
    same('one a minute (page) 1.60.1: a tour this minute holds nothing', [true, null], [array_key_exists('check', $r ?? []), $r['check'] ?? null]);
    same('one a minute (page): a backup started this minute — 9 s left at :51, free at the next minute (a browser a second behind: 61)', [9, 'backup', null, 61], $r['taken'] ?? null);
    same('one a minute (page): the bubble says the backup just ran, with its time', [sprintf('minute.ran_backup {"time":"time(%d)"}', $r['minute'] ?? 0)], $r['bubble'] ?? null);
    same('one a minute (page) 1.60.1: «Tour» and «Start a run…» never grey - the tip says a backup starts at the next minute',
        [['check', false, 'minute.queue_hint {"time":"time(n)"}'], ['start', false, 'minute.queue_hint {"time":"time(n)"}']],
        $r['buttons'] ?? null);
    same('one a minute (page) 1.60.1: a backup queued for the next minute - said in the bubble, «Don\'t start it» beside the buttons', [1, ['check', 'start', 'minute.cancel']], $r['queued'] ?? null);
    check('one a minute (page): a countdown ticks until the minute changes', ($r['timer'] ?? false) === true);
    same('one a minute (page): a run of an earlier minute — nothing grey, no tooltip, no line', [null, [[false, ''], [false, '']], []], $r['older'] ?? null);
    same('one a minute (page): while a run goes on — not this rule (the run card and «Stop» speak)', [true, null], [array_key_exists('live', $r ?? []), $r['live'] ?? null]);
    same('one a minute (page) 1.60.1: a dry run holds nothing either', [true, null], [array_key_exists('dry', $r ?? []), $r['dry'] ?? null]);
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('one a minute (page) 1.60.1: the start dialog says when a backup starts; the menu\'s tour and dry run never wait',
        str_contains($js, "T('minute.queue_note', { time: fmt.time(taken.at) })") && str_contains($js, 'const go = ready;'));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $w = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/backup/lang/$l.json"), true);
        check("one a minute (page): its words in $l", str_contains($w['minute.queued'] ?? '', '{time}') && str_contains($w['minute.queue_hint'] ?? '', '{time}')
            && str_contains($w['minute.queue_note'] ?? '', '{time}') && isset($w['minute.cancel']) && str_contains($w['minute.ran_backup'] ?? '', '{time}'));
    }
    hardeningRm($tmp);
}

/**
 * Settings are changed only by what a request says (QA 2026-10-08, finding 5): `backup.schedule {}` or `{"cron":[1]}`
 * switched the nightly backup off. A schedule needs `cron` — a line, or null/false/"" for «off»; a switch needs true or
 * false; a form the page always sends whole (Jack Emby's settings and gather, Ms. Snapshotini's plan) needs its parts.
 * Everything here is refused before anything is written.
 */
function testStrictSettings(): void
{
    $refused = function (callable $f): string {
        try {
            $f();
            return 'done';
        } catch (Problem $p) {
            return $p->key;
        }
    };
    $act = fn (string $desk, string $action, array $r): string => $refused(fn () => desks()[$desk]['actions'][$action]($r));
    same('strict: backup.schedule without cron', 'bad_request', $act('backup', 'schedule', []));
    same('strict: backup.schedule with cron of the wrong type', ['bad_request', 'bad_request', 'bad_request', 'bad_request'],
        [$act('backup', 'schedule', ['cron' => [1]]), $act('backup', 'schedule', ['cron' => 5]), $act('backup', 'schedule', ['cron' => true]), $act('backup', 'schedule', ['cron' => ['0 3 * * *']])]);
    same('strict: jack.schedule without cron', 'bad_request', $act('jack', 'schedule', ['job' => 'gather']));
    same('strict: jack.schedule with an array', 'bad_request', $act('jack', 'schedule', ['job' => 'gather', 'cron' => ['x']]));
    same('strict: «off» said', [null, null, null, null], [cronField(['cron' => null]), cronField(['cron' => false]), cronField(['cron' => '']), cronField(['cron' => '  '])]);
    same('strict: a line, trimmed', '0 3 * * *', cronField(['cron' => ' 0 3 * * * ']));
    same('strict: snapshot.plan_toggle without enabled — never «paused»', ['bad_request', 'bad_request'],
        [$act('snapshot', 'plan_toggle', ['id' => 'nosuch']), $act('snapshot', 'plan_toggle', ['id' => 'nosuch', 'enabled' => 'no'])]);
    same('strict: a switch', [true, false, 'bad_request', 'bad_request'], [boolField(['x' => true], 'x'), boolField(['x' => false], 'x'),
        $refused(fn () => boolField([], 'x')), $refused(fn () => boolField(['x' => 1], 'x'))]);
    same('strict: caretaker.menu_name without its place — never back to the menu bar', ['missing_field', 'missing_field'],
        [$act('caretaker', 'menu_name', ['name' => 'Office']), $act('caretaker', 'menu_name', ['name' => 'Office', 'place' => ['menu']])]);
    same('strict: caretaker.menu_name with a name of the wrong type', 'menu_name_bad', $act('caretaker', 'menu_name', ['name' => ['x'], 'place' => 'menu']));
    same('strict: the gather\'s settings — both said', ['jack_bad_number', 'bad_request', 'jack_bad_number', 'bad_request'],
        [$refused(fn () => jackGatherCheck(['shares' => ['media'], 'dup_check' => 'size'], ['media'])), $refused(fn () => jackGatherCheck(['shares' => ['media'], 'min_free_gb' => 5], ['media'])),
         $refused(fn () => jackGatherCheck(['shares' => ['media'], 'min_free_gb' => [5], 'dup_check' => 'size'], ['media'])),
         $refused(fn () => jackGatherCheck(['shares' => ['media'], 'min_free_gb' => 5, 'dup_check' => 'other'], ['media']))]);
    $gc = ['shares' => ['media'], 'min_free_gb' => 300, 'dup_check' => 'cmp', 'move_cache' => true, 'cache_only_target' => 'most-free'];
    same('strict: the gather\'s settings as the page sends them', $gc, jackGatherCheck($gc, ['media']));
    same('strict: the gather\'s cache switch and its target — said, a real switch, a known target (#14)', array_fill(0, 5, 'bad_request'), array_map(
        fn ($x) => $refused(fn () => jackGatherCheck($x, ['media'])), [array_diff_key($gc, ['move_cache' => 1]), array_diff_key($gc, ['cache_only_target' => 1]),
        ['move_cache' => 'true'] + $gc, ['move_cache' => 1] + $gc, ['cache_only_target' => 'disk1'] + $gc]));
    $inst = ['instances' => [['url' => 'http://10.0.0.5:8096', 'api_key' => 'abcdef0123456789', 'servername' => 'Emby']]];
    same('strict: Jack Emby\'s settings without their lists', 'bad_request', $refused(fn () => jackSave($inst)));
    same('strict: … one list missing', 'bad_request', $refused(fn () => jackSave($inst + ['libraries' => [], 'library_types' => [], 'valid_users' => []])));
    $plans = (string) file_get_contents(OFFICE_DIR . '/agent/lib/snapshotplans.php');
    check('strict: Ms. Snapshotini\'s plan — its switches said, keep and max_days numbers', str_contains($plans, "\$recursive = boolField(\$in, 'recursive');")
        && str_contains($plans, "\$skipAsleep = boolField(\$in, 'skip_asleep');") && str_contains($plans, '!is_int($keep) || !is_int($days)'));
}

/**
 * Requests of the wrong type are refused, never cast (QA 2026-10-08, findings 6 and 14): Unraid's php.ini hides
 * warnings (error_reporting 22517), so «Array to string conversion» never reached the agent's log. The agent reports
 * everything now (error_reporting(E_ALL) in serve(), agentPhpError(): `@` still silences, the same one once an hour);
 * the malformed requests qa1 sent — arrays where strings belong in partner_*, jack.output tool "../x", office.fire
 * {"desk":["x"]}, ?a=state&desk[]=y — answer bad_request (or unknown_target) and raise no warning.
 */
function testRequestTypes(): void
{
    // the agent's handler: what it logs, what `@` silences, once an hour
    $lines = [];
    $log = function (string $l) use (&$lines): void { $lines[] = $l; };
    $level = error_reporting(E_ALL);
    agentPhpError(E_WARNING, 'Array to string conversion', '/x/partner.php', 1554, $log, 1000);
    agentPhpError(E_WARNING, 'Array to string conversion', '/x/partner.php', 1554, $log, 1001);
    agentPhpError(E_WARNING, 'Array to string conversion', '/x/partner.php', 1554, $log, 2000);
    agentPhpError(E_NOTICE, 'something else', '/x/util.php', 7, $log, 2000);
    agentPhpError(E_WARNING, 'Array to string conversion', '/x/partner.php', 1554, $log, 4700);
    @agentPhpErrorSilenced($log);
    error_reporting($level);
    same('php errors: logged once an hour per place, then with how many came meanwhile', [
        'PHP: Array to string conversion (partner.php:1554)', 'PHP: something else (util.php:7)',
        'PHP: Array to string conversion (partner.php:1554) — 2 more within the hour before'], $lines);
    $agent = (string) file_get_contents(OFFICE_DIR . '/agent/agent.php');
    check('php errors: the agent reports everything from its start', ($e = strpos($agent, 'error_reporting(E_ALL);')) !== false
        && $e < strpos($agent, "set_error_handler('agentPhpError');") && $e > strpos($agent, 'function serve(): int'));

    // the agent's actions with what qa1 sent: refused, and no warning raised
    $warned = [];
    set_error_handler(function (int $no, string $t, string $f, int $l) use (&$warned): bool { $warned[] = "$t (" . basename($f) . ":$l)"; return true; });
    $level = error_reporting(E_ALL);
    $ask = fn (array $r): string => (string) (handle(json_encode($r))['error']['key'] ?? 'ok');
    $staff = TESTS_RUN_DIR . '/types-staff.json';          // the desks asked here work here (testAgentHired: when they don't)
    file_put_contents($staff, json_encode(['hired' => ['jack' => 1, 'restore' => 1]]));
    $GLOBALS['agentStaffFile'] = $staff;
    $answers = [];
    foreach (['partner_add', 'partner_ticket_start'] as $a) {
        $answers[] = $ask(['action' => "caretaker.$a", 'step' => ['x']]);
        $answers[] = $ask(['action' => "caretaker.$a", 'step' => 'do', 'address' => ['x']]);
    }
    foreach (['partner_ping', 'partner_end', 'partner_ticket_end'] as $a) {
        $answers[] = $ask(['action' => "caretaker.$a", 'id' => ['x'], 'step' => 'look']);
    }
    $answers[] = $ask(['action' => 'caretaker.partner_ticket_make', 'pair' => ['x']]);
    same('types: partner_* with arrays where strings belong — bad_request', array_fill(0, 8, 'bad_request'), $answers);
    same('types: jack.output / jack.log of a tool he hasn\'t — refused, never read as EmbyCache', ['unknown_target', 'unknown_target'],
        [$ask(['action' => 'jack.output', 'tool' => '../x']), $ask(['action' => 'jack.log', 'tool' => '../x'])]);
    same('types: restore.drill_set with nothing it knows — refused, not an ok that changed nothing', 'bad_request', $ask(['action' => 'restore.drill_set', 'x' => 1]));
    unset($GLOBALS['agentStaffFile']);
    @unlink($staff);
    same('types: a text of the wrong type', ['bad_request', 'x', 'd'], [(function () { try { return optText(['a' => [1]], 'a'); } catch (Problem $p) { return $p->key; } })(),
        optText(['a' => 'x'], 'a'), optText([], 'a', 'd')]);
    error_reporting($level);
    restore_error_handler();
    same('types: … and not one warning', [], $warned);

    // the web side: the query and the request
    $web = shell_exec(escapeshellarg(PHP_BINARY) . ' -r ' . escapeshellarg('require ' . var_export(OFFICE_DIR . '/src/bootstrap.php', true) . '; require '
        . var_export(OFFICE_DIR . '/src/api.php', true) . '; error_reporting(E_ALL); $w = []; set_error_handler(function ($n, $t) use (&$w) { $w[] = $t; return true; });'
        . ' $k = function (callable $f) { try { $f(); return "ok"; } catch (OfficeProblem $p) { return $p->key; } };'
        . ' echo json_encode([$k(fn () => apiText(["desk" => ["y"]], "desk")), $k(fn () => apiText(["a" => ["state"]], "a")), apiText([], "lang", "en"),'
        . ' $k(fn () => officeStaffAction("office.fire", ["desk" => ["x"]])), $k(fn () => officeStaffAction("office.hire", ["desks" => [["x"]]])),'
        . ' $k(fn () => officeStaffAction("office.hire", ["desks" => "snapshot"])), $w]);') . ' 2>&1');
    same('types: the web side refuses ?desk[]=y, {"a": [..]}, office.fire {"desk": ["x"]}, office.hire of non-strings — no warning',
        ['bad_request', 'bad_request', 'en', 'bad_request', 'bad_request', 'bad_request', []], json_decode((string) $web, true) ?? $web);
    $api = (string) file_get_contents(OFFICE_DIR . '/src/api.php');
    check('types: api.php reads its query and the action through apiText()', !preg_match('/\(string\) \(\$(_GET|data)\[/', $api));
}

/**
 * A desk that doesn't work here answers its look only (QA 2026-10-08, note 1: the agent switched an unhired watchman's
 * SIEM and whole-LAN watch on — only the web side checked): every other action of it is refused at the agent's
 * dispatch (not_hired) before its handler runs — the same rule as src/api.php's. Hired, the same requests reach their
 * handler (here: refused there for their payload — nothing is written); the Team Lead (always there) acts with any list.
 */
function testAgentHired(): void
{
    $staff = TESTS_RUN_DIR . '/hired-staff.json';
    $ask = fn (array $r): string => (string) (handle(json_encode($r))['error']['key'] ?? 'ok');
    $writes = [['action' => 'watchman.syslog_set', 'on' => 'x'], ['action' => 'watchman.net_lan_set', 'on' => 'x'],
               ['action' => 'watchman.notify_set', 'on' => 'x'], ['action' => 'watchman.posture_ack', 'id' => ['x']],
               ['action' => 'watchman.round'], ['action' => 'backup.schedule', 'cron' => [1]], ['action' => 'jack.schedule', 'job' => 'gather'],
               ['action' => 'snapshot.plan_toggle', 'id' => 'nosuch'], ['action' => 'snapshot.estimate', 'ids' => ['../x']],
               ['action' => 'restore.drill_set', 'x' => 1], ['action' => 'cleanup.measure', 'ids' => []]];
    $refusedThere = ['bad_request', 'bad_request', 'bad_request', 'bad_request', 'not_hired', 'bad_request', 'bad_request', 'bad_request',
                     'bad_request', 'bad_request', 'no_selection'];
    foreach (['no list' => null, 'an empty list' => ['hired' => []], 'others hired' => ['hired' => ['logs' => 1, 'advisor' => 2]]] as $what => $list) {
        @unlink($staff);
        if ($list !== null) {
            file_put_contents($staff, json_encode($list));
        }
        $GLOBALS['agentStaffFile'] = $staff;
        same("hired: $what — a desk's switches, schedules, settings and plans refused (not_hired)", array_fill(0, count($writes), 'not_hired'),
            array_map($ask, $writes));
        same("hired: $what — its look stays open (refresh), the Team Lead acts", [true, true, true, 'missing_field'],
            [agentDeskMayAct('watchman', 'refresh'), agentDeskMayAct('snapshot', 'refresh'), agentDeskMayAct('caretaker', 'menu_name'),
             $ask(['action' => 'caretaker.menu_name', 'name' => 'Office'])]);
    }
    file_put_contents($staff, json_encode(['hired' => ['watchman' => 1, 'backup' => 2, 'jack' => 3, 'snapshot' => 4, 'restore' => 5, 'whereabouts' => 6]]));
    $GLOBALS['agentStaffFile'] = $staff;
    $answers = array_map($ask, $writes);
    // watchman.round: hired in the list here, but his own check reads the live list — refused there, not at the dispatch
    same('hired: hired — the same requests reach their handlers (Ms. Whereabouts\' hiring counts for Ms. Dustdevil)', $refusedThere, $answers);
    same('hired: an unknown action of an unhired desk is still unknown_action', 'unknown_action', $ask(['action' => 'logs.nosuch']));
    file_put_contents($staff, json_encode(['hired' => ['backup' => 1]]));
    same('hired: one desk hired — the others still refused', ['not_hired', 'bad_request'],
        [$ask(['action' => 'watchman.syslog_set', 'on' => 'x']), $ask(['action' => 'backup.schedule', 'cron' => [1]])]);
    unset($GLOBALS['agentStaffFile']);
    @unlink($staff);
    $agent = (string) file_get_contents(OFFICE_DIR . '/agent/agent.php');
    check('hired: the dispatch asks before the handler', ($g = strpos($agent, "!agentDeskMayAct(\$deskId, \$action)")) !== false
        && $g < strpos($agent, 'return $handler($request);'));
}

/** For testRequestTypes(): a warning raised under `@` */
function agentPhpErrorSilenced(callable $log): void
{
    agentPhpError(E_WARNING, 'silenced', '/x/y.php', 1, $log, 5000);
}

/**
 * «Report a problem or a wish…» (agent/lib/report.php): the scrubber over crafted lines — paths (a film with spaces),
 * shares, pools, the server's and partners' names, users, addresses (IPv4, IPv6), MACs, mails, tokens, URLs with a
 * password, known secrets (one split by a control character) — nothing of them survives, and scrubbing twice is once;
 * the label map complete for every desk and every logLine() a desk writes; the desk's lines from agent.log; the preview's
 * parts, its token in RAM (0600) and no request; the report ID; the weekly pre-check; one send per token; the send
 * against a stand-in inbox (php -S) with every answer the Worker may give (and none at all); reports.json's shape; the
 * strict readers; the .cfg override of the inbox's address.
 */
function testReport(): void
{
    $tmp = hardeningTmp('report');
    @mkdir("$tmp/shares");
    @mkdir("$tmp/pools");
    @mkdir("$tmp/partner");
    @mkdir("$tmp/office", 0700);
    @mkdir("$tmp/run", 0700);
    $guid = '0781-5583-3311-A1B2C3D4E5F6';
    file_put_contents("$tmp/var.ini", "regGUID=\"$guid\"\nflashGUID=\"0951-1666-4C02-ABCDEF012345\"\ncsrf_token=\"0123456789ABCDEF\"\n");
    file_put_contents("$tmp/ident.cfg", "NAME=\"HomeServer\"\n");
    foreach (['Media', 'Backups', 'Fotos Familie', 'appdata', 'system'] as $s) {
        touch("$tmp/shares/$s.cfg");
    }
    foreach (['cache', 'hazel'] as $p) {
        touch("$tmp/pools/$p.cfg");
    }
    file_put_contents("$tmp/passwd", "root:x:0:0::/root:/bin/bash\nnobody:x:99:100::/:/bin/false\nbenj:x:1000:100::/:/bin/false\n");
    $sshKey = 'ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIHkz9nq1Wc1o2Fv7Kp0Qm3yXcT5bLr8dE4uS6aJ0hN2i uso-partner:p1';
    file_put_contents("$tmp/partner/pairs.json", json_encode(['v' => 1, 'pairs' => [['id' => 'p1', 'name' => 'Tower', 'address' => 'tower.lan', 'my_key' => $sshKey]]]));
    file_put_contents("$tmp/emby.json", json_encode(['instances' => [['url' => 'http://10.0.0.5:8096', 'api_key' => 'abcdef0123456789abcdef']]]));
    file_put_contents("$tmp/supporter.json", json_encode(['key' => 'USO1.eyJ2IjoxfQ.MEUCIQD-sig']));
    $ctx = ['var_ini' => "$tmp/var.ini", 'ident' => "$tmp/ident.cfg", 'shares_dir' => "$tmp/shares", 'pools_dir' => "$tmp/pools", 'mounts' => ['/mnt/disk1', '/mnt/user', '/mnt/hazel'],
            'passwd' => "$tmp/passwd", 'partner_dir' => "$tmp/partner", 'jack_settings' => "$tmp/emby.json", 'supporter' => "$tmp/supporter.json",
            'report_id_file' => "$tmp/office/report-id", 'hostname' => 'homeserver', 'reports' => "$tmp/office/reports.json", 'run_dir' => "$tmp/run",
            'hired' => ['caretaker', 'snapshot', 'backup'], 'unraid_version' => "$tmp/unraid-version", 'log' => "$tmp/agent.log",
            'url' => ''];       // no inbox: «Your reports» asks nobody where they stand here (testReportStatus does)
    file_put_contents("$tmp/unraid-version", "version=\"7.3.2\"\n");

    // the report ID: of its own, kept, never the tip page's server ID
    $id = reportId($ctx);
    same('report: the ID is sha256("uso-report:" + GUID)', hash('sha256', 'uso-report:' . strtoupper($guid)), $id);
    same('report: … kept in data/office/report-id, 0600', ["$id\n", '600'], [(string) @file_get_contents("$tmp/office/report-id"), decoct(fileperms("$tmp/office/report-id") & 0777)]);
    file_put_contents("$tmp/var2.ini", "regGUID=\"FFFF-0000-1111-222222222222\"\n");
    same('report: … made once (another GUID later keeps it)', $id, reportId(['var_ini' => "$tmp/var2.ini"] + $ctx));
    check('report: … unlinkable to the tip page\'s server ID', !str_contains(strtoupper($id), strtoupper(substr(hash('sha256', 'uso-supporter:' . strtoupper($guid)), 0, 16))));

    // the scrubber
    $know = reportKnow($ctx);
    same('report: shares and pools numbered by their names (Unraid\'s own shares kept)', [['Backups' => '‹share-1›', 'Fotos Familie' => '‹share-2›', 'Media' => '‹share-3›'], ['cache' => '‹pool-1›', 'hazel' => '‹pool-2›']],
        [$know['shares'], $know['pools']]);
    $lines = [
        'moved /mnt/user/Media/My Film (2020)/My Film.mkv: done' => 'moved /mnt/user/‹share-3›/…: done',
