        [array_map(fn ($i) => [$i['type'], $i['width'], $i['height']], $pv['images'] ?? []), $pv['ticked']]);
    same('report images: … kept beside the token in RAM (0600), the inbox empty, no bytes in the answer', [true, true, '600', [], false],
