/**
 * A job's schedule says when it runs next (officeJobSchedule() `next`, for the desks' schedule tiles): on a cron file of
 * the test's own — an enabled line's next run is in the future, matches its expression and is the first that does; a
 * job without a line: next null; a line cron can't read (written by hand): next null and no warning.
 */
function testOfficeJobScheduleNext(): void
{
    $tmp = hardeningTmp('cronnext');
    $file = "$tmp/office.cron";
    officeJobSetSchedule('backup', '30 4 * * *', $file, false);
    officeJobSetSchedule('embycache', '*/15 * * * *', $file, false);
    $now = time();
    $first = function (string $cron, ?int $next) use ($now): bool {
        $f = cronFields($cron);
        if (!$f || $next === null || $next <= $now || !cronMatches($f, $next)) {
            return false;
        }
        for ($t = intdiv($now, 60) * 60 + 60; $t < $next; $t += 60) {
            if (cronMatches($f, $t)) {
                return false;
            }
        }
        return true;
    };
    $b = officeJobSchedule('backup', $file);
    same('job schedule next: the shape — next beside the four keys', ['script', 'frequency', 'custom', 'enabled', 'next'], array_keys($b));
    check('job schedule next: an enabled line — in the future, its expression\'s next minute (04:30)',
        $b['enabled'] && is_int($b['next']) && $first('30 4 * * *', $b['next']) && date('H:i', $b['next']) === '04:30' && $b['next'] - $now <= 86400);
    $e = officeJobSchedule('embycache', $file);
    check('job schedule next: every 15 minutes — within the next quarter of an hour', is_int($e['next']) && $first('*/15 * * * *', $e['next']) && $e['next'] - $now <= 900);
    $g = officeJobSchedule('gather', $file);
    same('job schedule next: no line — off, next null', [false, null], [$g['enabled'], $g['next']]);
    file_put_contents($file, '61 3 * * * ' . officeJobCommand('backup') . "\n");
    $warned = [];
    set_error_handler(function (int $no, string $str) use (&$warned): bool {
        $warned[] = $str;
        return true;
    });
    $x = officeJobSchedule('backup', $file);
    restore_error_handler();
    same('job schedule next: a line cron can\'t read — next null, no warning', [true, null, []], [$x['enabled'], $x['next'], $warned]);
    hardeningRm($tmp);
}

/**
 * «All n: I know, thanks» on a folded row (the action ack_some, `watchmanAck()` with a list of ids): exactly the listed
 * entries still open are noted (their state adopted like one «I know, thanks» each), the rest of the book untouched; none
 * of them open = watch_gone; ids are WATCH_ID's shape, at most WATCH_BOOK_MAX, read with idList(); the single «ack» still
 * takes one id only; an unhired watchman refuses it at the dispatch like every other write.
 */
function testWatchBookNoteSome(): void
{
    $data = hardeningTmp('watch-some');
    exec('rm -rf ' . escapeshellarg($data) . '/*');
    $now = time();
    file_put_contents("$data/baseline.json", json_encode(['hired' => 1, 'time' => $now - 9000, 'ips' => []]));
    $entry = fn (string $id, string $ip, ?int $noted = null): array => array_merge(
        watchmanEntry('login_new_ip', "login_new_ip:$ip", $now - 600, ['ip' => $ip, 'users' => ['root'], 'services' => ['ssh']]), ['id' => $id, 'noted' => $noted]);
    [$a, $b, $c, $d] = ['w00000000a1', 'w00000000b2', 'w00000000c3', 'w00000000d4'];
    file_put_contents("$data/book.json", json_encode(['entries' => [$entry($a, '203.0.113.1'), $entry($b, '203.0.113.2'), $entry($c, '203.0.113.3'),
        $entry($d, '203.0.113.4', $now - 300)]]));
    $open = fn (): array => array_column(array_filter(watchmanLoad($data)['book'], 'watchmanOpen'), 'id');
    same('note some: two of three open entries noted', ['ok' => true, 'noted' => 2], watchmanAck([$a, $b], $data, $now, false));
    $l = watchmanLoad($data);
    same('note some: … only those — the third stays open, «by» the page, their addresses known now', [[$c], 'page', true, true, false],
        [$open(), array_column($l['book'], 'by', 'id')[$a] ?? null, isset($l['baseline']['ips']['203.0.113.1']), isset($l['baseline']['ips']['203.0.113.2']),
         isset($l['baseline']['ips']['203.0.113.3'])]);
    same('note some: the open counts follow', ['login_new_ip' => 1], $l['state']['open'] ?? null);
    $err = function (mixed $ids) use ($data, $now): string {
        try {
            watchmanAck($ids, $data, $now + 10, false);
            return 'ok';
        } catch (Problem $e) {
            return $e->key;
        }
    };
    same('note some: none of them open any more — watch_gone; one open among noted ones — noted', ['watch_gone', 'ok', []],
        [$err([$a, $b, $d]), $err([$c, $d]), $open()]);
    same('note some: ids of the wrong shape, none, more than the book holds — bad_request', ['bad_request', 'bad_request', 'bad_request', 'bad_request', 'bad_request'],
        [$err(['nope']), $err([]), $err([123]), $err([$a, "$b\n"]), $err(array_fill(0, WATCH_BOOK_MAX + 1, $a))]);
    exec('rm -rf ' . escapeshellarg($data));

    // through the agent's dispatch: hired or not, the request's shape
    $staff = TESTS_RUN_DIR . '/watch-some-staff.json';
    $ask = fn (array $r): string => (string) (handle(json_encode($r))['error']['key'] ?? 'ok');
    file_put_contents($staff, json_encode(['hired' => ['backup' => 1]]));
    $GLOBALS['agentStaffFile'] = $staff;
    same('note some: an unhired watchman refuses it (not_hired)', 'not_hired', $ask(['action' => 'watchman.ack_some', 'ids' => [$a]]));
    file_put_contents($staff, json_encode(['hired' => ['watchman' => 1]]));
    same('note some: hired — ids missing, not a list, not strings, of the wrong shape; the single ack with a list', ['no_selection', 'no_selection', 'invalid_selection', 'bad_request', 'bad_request'],
        [$ask(['action' => 'watchman.ack_some']), $ask(['action' => 'watchman.ack_some', 'ids' => $a]), $ask(['action' => 'watchman.ack_some', 'ids' => [5]]),
         $ask(['action' => 'watchman.ack_some', 'ids' => ['x']]), $ask(['action' => 'watchman.ack', 'id' => [$a, $b]])]);
    unset($GLOBALS['agentStaffFile']);
    @unlink($staff);
}

/**
 * Ms. Dustdevil's storeroom for Docker's volumes (issue #1): where it lies (beside Docker's data), which volumes she can
 * keep, the copy first and the rm only after it (a stand-in docker on a folder of fake volumes), a copy that fails, a
 * full pool, Docker refusing the rm, a volume whose folder is gone (rm -f), one she can't copy (for good), the
 * manifest's record read back, and «Put back»: refused over a volume of that name, created anew with its labels and
 * its content, the storeroom's copy emptied in the background; a copy back that fails leaves nothing behind
 */
function testCleanupVolumes(): void
{
    $tmp = hardeningTmp('clean-volumes');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $fake = "$tmp/fake";
    @mkdir("$fake/vols", 0755, true);
    @mkdir("$fake/inuse", 0755, true);
    @mkdir("$fake/enoent", 0755, true);
    $docker = "$tmp/docker";
    file_put_contents($docker, <<<SH
#!/bin/bash
FAKE='$fake'
echo "\$*" >>"\$FAKE/docker.log"
[[ \$1 == volume ]] || exit 1
case \$2 in
  inspect)
    v="\$FAKE/vols/\$3"
    [[ -d \$v ]] || { echo "Error response from daemon: get \$3: no such volume" >&2; exit 1; }
    printf '[{"Name":"%s","Driver":"%s","Labels":%s,"Options":%s,"Mountpoint":"%s/_data","Scope":"local"}]\\n' "\$3" "\$(cat "\$v/driver")" "\$(cat "\$v/labels")" "\$(cat "\$v/options")" "\$v" ;;
  rm)
    f=0; n=\$3; [[ \$3 == -f ]] && { f=1; n=\$4; }
    [[ -e \$FAKE/inuse/\$n ]] && { echo "Error response from daemon: remove \$n: volume is in use - [abc]" >&2; exit 1; }
    [[ \$f == 0 && -e \$FAKE/enoent/\$n ]] && { echo "Error response from daemon: remove \$n: unlinkat /var/lib/docker/volumes/\$n/_data: no such file or directory" >&2; exit 1; }
    [[ -d \$FAKE/vols/\$n ]] || { echo "Error: No such volume: \$n" >&2; exit 1; }
    rm -rf "\$FAKE/vols/\$n"; echo "\$n" ;;
  create)
    shift 2; labels=''
    while [[ \$# -gt 1 ]]; do
      case \$1 in
        --driver) d=\$2; shift 2 ;;
        --label) k=\${2%%=*}; labels+="\${labels:+,}\\"\$k\\":\\"\${2#*=}\\""; shift 2 ;;
        *) exit 9 ;;
      esac
    done
    v="\$FAKE/vols/\$1"; [[ -e \$v ]] && exit 1
    mkdir -p "\$v/_data"; echo "\$d" >"\$v/driver"; echo "{\$labels}" >"\$v/labels"; echo null >"\$v/options"; echo "\$1" ;;
  *) exit 1 ;;
esac
SH);
    chmod($docker, 0755);
    $mkvol = function (string $name, string $labels = '{"com.docker.compose.project":"app","x":""}', string $options = 'null', string $driver = 'local') use ($fake): string {
        $v = "$fake/vols/$name";
        @mkdir("$v/_data/sub", 0755, true);
        file_put_contents("$v/_data/sub/data", str_repeat('x', 8192));         // something on disk (folders take no blocks on tmpfs)
        file_put_contents("$v/driver", "$driver\n");
        file_put_contents("$v/labels", "$labels\n");
        file_put_contents("$v/options", "$options\n");
        return "$v/_data";
    };
    $log = fn () => trim((string) @file_get_contents("$fake/docker.log"));
    $logClear = fn () => @unlink("$fake/docker.log");

    // where: beside Docker's data — the share of DOCKER_IMAGE_FILE on the pool that holds it
    $mnt = "$tmp/mnt";
    @mkdir("$mnt/cache/system/docker", 0755, true);
    @mkdir("$mnt/disk1/system", 0755, true);
    $GLOBALS['clFresh']['share']['system'] = ['shareUseCache' => 'only', 'shareCachePool' => 'cache'];
    $GLOBALS['clFresh']['share']['sysx'] = ['shareUseCache' => 'yes', 'shareCachePool' => 'gone'];
    @mkdir("$mnt/disk1/sysx/docker", 0755, true);
    $ctx = ['roots' => ['cache' => ['fs' => 'zfs', 'kind' => 'pool'], 'disk1' => ['fs' => 'xfs', 'kind' => 'disk']], 'asleep' => []];
    $trash = "$mnt/cache/system/" . CL_TRASH;
    same('volumes: the storeroom beside Docker\'s folder, on the pool of its share',
        ['pool' => 'cache', 'root' => $trash, 'asleep' => false], clVolumePlace(['DOCKER_IMAGE_FILE' => '/mnt/user/system/docker/'], $ctx, $mnt));
    same('volumes: beside docker.img on a pool named directly', ['pool' => 'cache', 'root' => $trash, 'asleep' => false],
        clVolumePlace(['DOCKER_IMAGE_FILE' => '/mnt/cache/system/docker/docker.img'], $ctx, $mnt));
    same('volumes: a share found where it lies (its pool gone), a sleeping disk never looked at',
        [['pool' => 'disk1', 'root' => "$mnt/disk1/sysx/" . CL_TRASH, 'asleep' => false], null],
        [clVolumePlace(['DOCKER_IMAGE_FILE' => '/mnt/user/sysx/docker'], $ctx, $mnt),
         clVolumePlace(['DOCKER_IMAGE_FILE' => '/mnt/user/sysx/docker'], ['asleep' => ['disk1' => true]] + $ctx, $mnt)]);
    same('volumes: no storeroom where it can\'t be told', [null, null, null, null],
        [clVolumePlace([], $ctx, $mnt), clVolumePlace(['DOCKER_IMAGE_FILE' => '/var/lib/docker.img'], $ctx, $mnt),
         clVolumePlace(['DOCKER_IMAGE_FILE' => '/mnt/user/../boot/docker'], $ctx, $mnt), clVolumePlace(['DOCKER_IMAGE_FILE' => '/mnt/remotes/nas/docker'], $ctx, $mnt)]);
    unset($GLOBALS['clFresh']['share']['system'], $GLOBALS['clFresh']['share']['sysx']);
    $place = ['pool' => 'cache', 'root' => $trash, 'asleep' => false];

    same('volumes: kept are the local driver\'s without options only', [true, false, false, false],
        [clVolumeKeepable(['driver' => 'local', 'options' => [], 'mountpoint' => '/var/lib/docker/volumes/a/_data']),
         clVolumeKeepable(['driver' => 'local', 'options' => ['type' => 'nfs', 'device' => ':/x'], 'mountpoint' => '/var/lib/docker/volumes/a/_data']),
         clVolumeKeepable(['driver' => 'rclone', 'options' => [], 'mountpoint' => '/var/lib/docker/volumes/a/_data']),
         clVolumeKeepable(['driver' => 'local', 'options' => [], 'mountpoint' => ''])]);

    // into the storeroom: copied (owners, permissions, links), recorded, then removed from Docker
    $data = $mkvol('pgdata');
    file_put_contents("$data/sub/PG_VERSION", "16\n");
    file_put_contents("$data/secret", 'x');
    chmod("$data/secret", 0600);
    @chown("$data/secret", 999);
    @chgrp("$data/secret", 999);
    chmod($data, 0700);
    @symlink('sub/PG_VERSION', "$data/link");
    $run = null;
    $r = clVolumeAway($docker, 'pgdata', $run, $place);
    $copy = ($run['path'] ?? '') . '/volumes/pgdata';
    same('volumes: into the storeroom — copied, then removed from Docker', [['ok' => true, 'stored' => true], false, "16\n", 'sub/PG_VERSION'],
        [$r, is_dir("$fake/vols/pgdata"), @file_get_contents("$copy/sub/PG_VERSION"), @readlink("$copy/link")]);
    clearstatcache();
    same('volumes: the copy keeps owners and permissions (the folder\'s own too)', [0600, posix_geteuid() === 0 ? 999 : fileowner("$copy/secret"), 0700],
        [@fileperms("$copy/secret") & 0777, @fileowner("$copy/secret"), @fileperms($copy) & 0777]);
    same('volumes: the rm only after the copy', ['volume inspect pgdata', 'volume rm pgdata'], explode("\n", $log()));
    $runs = array_values(array_filter(clTrashRuns([], ['ok' => false], [$trash]), fn ($x) => $x['path'] === ($run['path'] ?? '')));
    $it = $runs[0]['items'][0] ?? [];
    same('volumes: the manifest names it with its record — read back exactly',
        ['volume', 'pgdata', 'volumes/pgdata', "$data", ['name' => 'pgdata', 'driver' => 'local', 'labels' => ['com.docker.compose.project' => 'app', 'x' => ''], 'options' => []], true],
        [$it['kind'] ?? null, $it['name'] ?? null, $it['as'] ?? null, $it['from'] ?? null, $it['volume'] ?? null, $it['present'] ?? null]);
    check('volumes: no .partial left', !array_filter(scandir($run['path'] . '/volumes'), fn ($n) => str_ends_with($n, '.partial')));

    // a copy that fails: nothing removed, nothing left in the storeroom
    $logClear();
    $mkvol('cache1');
    file_put_contents("$tmp/cp-fails", "#!/bin/bash\nmkdir -p \"\${@: -1}\"; echo 'cp: error writing: No space left on device' >&2; exit 1\n");
    chmod("$tmp/cp-fails", 0755);
    $GLOBALS['clVolumeCp'] = "$tmp/cp-fails";
    $r = clVolumeAway($docker, 'cache1', $run, $place);
    unset($GLOBALS['clVolumeCp']);
    same('volumes: a copy that fails — an error, the volume stays, no copy, not in the manifest',
        ['cleanup_volume_copy_failed', true, ['pgdata'], ['pgdata']],
        [$r['error']['key'] ?? null, is_dir("$fake/vols/cache1"), array_values(array_diff(scandir($run['path'] . '/volumes'), ['.', '..'])),
         array_column(readJson($run['path'] . '/manifest.json')['items'] ?? [], 'name')]);
    check('volumes: … and Docker was never asked to remove it', !str_contains($log(), 'rm cache1'), $log());
    // a full pool: refused before copying
    $GLOBALS['clVolumeFree'] = fn (string $p) => 10.0;
    $r = clVolumeAway($docker, 'cache1', $run, $place);
    unset($GLOBALS['clVolumeFree']);
    same('volumes: not enough space — refused before copying, the volume stays', ['cleanup_volume_no_space', true, dirname($trash)],
        [$r['error']['key'] ?? null, is_dir("$fake/vols/cache1"), $r['error']['params']['path'] ?? null]);
    // Docker refuses the rm (a container took it meanwhile): the copy goes again
    touch("$fake/inuse/cache1");
    $r = clVolumeAway($docker, 'cache1', $run, $place);
    @unlink("$fake/inuse/cache1");
    same('volumes: Docker refusing the rm — the copy goes again, the volume stays', ['cleanup_docker_failed', true, false, ['pgdata']],
        [$r['error']['key'] ?? null, is_dir("$fake/vols/cache1"), file_exists($run['path'] . '/volumes/cache1'), array_column(readJson($run['path'] . '/manifest.json')['items'] ?? [], 'name')]);
    // the storeroom's pool asleep, no storeroom at all: refused
    same('volumes: the storeroom asleep or not to be found — refused, kept', ['cleanup_asleep', 'cleanup_volume_no_place', true],
        [(clVolumeAway($docker, 'cache1', $run, ['asleep' => true] + $place)['error']['key'] ?? null), (clVolumeAway($docker, 'cache1', $run, null)['error']['key'] ?? null), is_dir("$fake/vols/cache1")]);
    // a volume whose folder is gone: removed with -f, nothing to keep
    $logClear();
    $mkvol('ghost');
    exec('rm -rf ' . escapeshellarg("$fake/vols/ghost/_data"));
    touch("$fake/enoent/ghost");
    $r = clVolumeAway($docker, 'ghost', $run, $place);
    same('volumes: its folder gone — docker volume rm, then rm -f; counts as removed', [['ok' => true, 'stored' => false], false, ['volume inspect ghost', 'volume rm ghost', 'volume rm -f ghost']],
        [$r, is_dir("$fake/vols/ghost"), explode("\n", $log())]);
    // a volume she can't copy (mounted from elsewhere): removed for good, as today
    $logClear();
    $mkvol('nfs1', '{}', '{"type":"nfs","device":":/export","o":"addr=10.0.0.2"}');
    $r = clVolumeAway($docker, 'nfs1', $run, $place);
    same('volumes: mounted from elsewhere — removed for good, nothing copied', [['ok' => true, 'stored' => false], false, false],
        [$r, is_dir("$fake/vols/nfs1"), file_exists($run['path'] . '/volumes/nfs1')]);

    // the manifest's record: only her own shape
    same('volumes: records not hers don\'t count', [null, null, null, null, null, true],
        [clVolumeRecord(['name' => 'a', 'driver' => 'local', 'labels' => [], 'options' => ['type' => 'nfs']], 'a'),
         clVolumeRecord(['name' => 'a', 'driver' => 'rclone', 'labels' => [], 'options' => []], 'a'),
         clVolumeRecord(['name' => 'a', 'driver' => 'local', 'labels' => ['k=v' => 'x'], 'options' => []], 'a'),
         clVolumeRecord(['name' => 'b', 'driver' => 'local', 'labels' => [], 'options' => []], 'a'),
         clVolumeRecord(['name' => 'a', 'driver' => 'local', 'labels' => ['k' => "x\ny"], 'options' => []], 'a'),
         is_array(clVolumeRecord(['name' => 'a', 'driver' => 'local', 'labels' => ['k' => 'v'], 'options' => []], 'a'))]);

    // «Put back»: never over a volume of that name
    $runRec = $runs[0];
    $mkvol('pgdata', '{}');
    $before = $log();
    $GLOBALS['clJobs'] = ['queue' => [], 'running' => []];
    $e = null;
    try {
        clVolumeBack($docker, $runRec, $it);
    } catch (Problem $p) {
        $e = $p->toArray();
    }
    same('volumes: back — refused while Docker has one of that name, said so; the copy stays', ['cleanup_volume_exists', true, '{}'],
        [$e['key'] ?? null, is_dir($copy), trim((string) @file_get_contents("$fake/vols/pgdata/labels"))]);
    exec('rm -rf ' . escapeshellarg("$fake/vols/pgdata"));
    // a copy back that fails: the volume just made goes again, the storeroom keeps its copy
    $GLOBALS['clVolumeCp'] = "$tmp/cp-fails";
    $e = null;
    try {
        clVolumeBack($docker, $runRec, $it);
    } catch (Problem $p) {
        $e = $p->toArray();
    }
    unset($GLOBALS['clVolumeCp']);
    same('volumes: back — a copy that fails removes the new volume, the copy stays', ['cleanup_volume_back_failed', false, true],
        [$e['key'] ?? null, is_dir("$fake/vols/pgdata"), is_dir($copy)]);
    $logClear();
    clVolumeBack($docker, $runRec, $it);
    $back = "$fake/vols/pgdata/_data";
    clearstatcache();
    same('volumes: back — created with its labels, its content and owners copied in, the folder\'s permissions too',
        ['{"com.docker.compose.project":"app","x":""}', "16\n", 0600, 0700, 'sub/PG_VERSION'],
        [trim((string) @file_get_contents("$fake/vols/pgdata/labels")), @file_get_contents("$back/sub/PG_VERSION"), @fileperms("$back/secret") & 0777,
         @fileperms($back) & 0777, @readlink("$back/link")]);
    same('volumes: back — asked Docker in this order', ['volume inspect pgdata', 'volume create --driver local --label com.docker.compose.project=app --label x= pgdata', 'volume inspect pgdata'],
        explode("\n", $log()));
    $purging = glob("$trash/*.purging") ?: [];
    same('volumes: back — the storeroom\'s copy goes in the background, like an emptied run', [false, 1, true, true],
        [file_exists($copy), count($purging), is_dir(($purging[0] ?? '') . '/volume'), isset($GLOBALS['clJobs']['queue']['purge:' . ($purging[0] ?? '')])
            || in_array('purge:' . ($purging[0] ?? ''), array_column($GLOBALS['clJobs']['queue'], 'key'), true)]);
    $GLOBALS['clJobs'] = ['queue' => [], 'running' => []];
    hardeningRm($tmp);
}

/**
 * Issue #7: Ms. Dustdevil's storeroom and Mr. Restori's set-aside folder are hidden folders. The old names are read for
 * good and moved over once per place (clTrashMigrate()): only the old folder (renamed), only the new one (nothing), both
 * (runs one by one, a clash gets a suffix, what isn't hers stays — and so does the old folder), a rename that fails
 * (the old folder stays in use), a dataset of its own (zfs rename while its mountpoint follows), busy (the engine's
 * lock: next time), once per place; «Put back» of a run that was moved (hers through clRestore(), his through his undo
 * steps); the other desks and the engine know both names (watchman, partners' places, let-go journals, the backup's
 * excludes, Kopia's ignore rules)
 */
function testHiddenStoreroom(): void
{
    $tmp = hardeningTmp('hidden-trash');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');

    // --- the names
    same('hidden: the names — new and old are both the storeroom, nothing else is',
        [true, true, true, true, false, false, false],
        [storeroomName('.UnraidSecretaryOffice-trash'), storeroomName('_UnraidSecretaryOffice-trash'), storeroomName('.UnraidSecretaryOffice-trash-20261009-101010-foo'),
         storeroomName(CL_TRASH), storeroomName('UnraidSecretaryOffice-trash'), storeroomName('.UnraidSecretaryOffice-restore'), storeroomName('appdata')]);
    same('hidden: the storeroom is hidden, Mr. Restori\'s folder too; the other places keep their names',
        ['.UnraidSecretaryOffice-trash', '_UnraidSecretaryOffice-trash', '.UnraidSecretaryOffice-restore', '_UnraidSecretaryOffice-restore', '/boot/config/.UnraidSecretaryOffice-restore', OFFICE_ASIDE],
        [CL_TRASH, CL_TRASH_OLD, CL_RESTORE_ASIDE, CL_RESTORE_ASIDE_OLD, RS_FLASH_ASIDE, RS_LIBVIRT_ASIDE]);
    same('hidden: a path in a storeroom (either name), a dataset put away; not a name that only looks alike',
        [true, true, true, false, false],
        [storeroomIn('/mnt/cache/appdata/.UnraidSecretaryOffice-trash/20261009-101010'), storeroomIn('tank/appdata/_UnraidSecretaryOffice-trash-20261009-101010-x'),
         storeroomIn('.UnraidSecretaryOffice-trash'), storeroomIn('/mnt/cache/appdata/my_UnraidSecretaryOffice-trash'), storeroomIn('/mnt/cache/appdata/x')]);
    same('hidden: both folders of a place are read; datasets put away under either name',
        [['/x/s/.UnraidSecretaryOffice-trash', '/x/s/_UnraidSecretaryOffice-trash'], ['/x/s/.UnraidSecretaryOffice-trash', '/x/s/_UnraidSecretaryOffice-trash'], ['/x/other'], true, true, false],
        [clTrashBoth('/x/s/.UnraidSecretaryOffice-trash'), clTrashBoth('/x/s/_UnraidSecretaryOffice-trash'), clTrashBoth('/x/other'),
         clTrashDataset('.UnraidSecretaryOffice-trash-20261009-101010-a'), clTrashDataset('_UnraidSecretaryOffice-trash-20261009-101010-a'), clTrashDataset('.UnraidSecretaryOffice-trash')]);

    // --- where a path an older record names lies now
    @mkdir("$tmp/w/_UnraidSecretaryOffice-restore/20261007-090000", 0755, true);
    @mkdir("$tmp/v", 0755, true);
    same('hidden: an old path stays while it is there; else the new name (also where to write, the old folder there or not); other paths as they are',
        ["$tmp/w/_UnraidSecretaryOffice-restore/20261007-090000", "$tmp/w/.UnraidSecretaryOffice-restore/{T}/x", "$tmp/v/.UnraidSecretaryOffice-restore/{T}/y", "$tmp/v/.UnraidSecretaryOffice-trash/20261001-000000",
         "$tmp/v/_UnraidSecretaryOffice-trash-20261001-000000-ds", "$tmp/v/a.aside-20261007-090000"],
        [officeHiddenNow("$tmp/w/_UnraidSecretaryOffice-restore/20261007-090000"), officeHiddenNow("$tmp/w/_UnraidSecretaryOffice-restore/{T}/x"),
         officeHiddenNow("$tmp/v/_UnraidSecretaryOffice-restore/{T}/y"),
         officeHiddenNow("$tmp/v/_UnraidSecretaryOffice-trash/20261001-000000"), officeHiddenNow("$tmp/v/_UnraidSecretaryOffice-trash-20261001-000000-ds"),
         officeHiddenNow("$tmp/v/a.aside-20261007-090000")]);

    // a run as she writes it: a folder put away (appdata/<name>) and a dataset put away next to the storeroom
    $mkRun = function (string $root, string $stamp, string $share, string $name, ?string $ds = null): string {
        @mkdir("$root/$stamp/appdata/$name/sub", 0775, true);
        file_put_contents("$root/$stamp/appdata/$name/sub/data", 'x');
        $items = [['kind' => 'appdata', 'name' => $name, 'label' => 'cache', 'from' => "$share/$name", 'as' => "appdata/$name", 'dataset' => null, 'bytes' => 1]];
        if ($ds !== null) {
            $items[] = ['kind' => 'appdata', 'name' => basename($ds), 'label' => 'cache', 'from' => "$share/" . basename($ds), 'as' => '@' . dirname($ds) . '/' . CL_TRASH_OLD . "-$stamp-" . basename($ds),
                        'dataset' => $ds, 'bytes' => 1];
        }
        file_put_contents("$root/$stamp/manifest.json", json_encode(['written_by' => 'Unraid Secretary Office (Ms. Dustdevil)', 'version' => 1, 'time' => 1760000000, 'items' => $items]));
        return "$root/$stamp";
    };
    $runsOf = function (array $roots): array {
        $GLOBALS['clCtx'] = ['roots' => [], 'asleep' => []];
        // the test server's own flash storeroom (Ms. Dustdevil put real share settings there, Tower 2026-10-16) isn't the test's
        $out = array_values(array_filter(clTrashRuns([], ['ok' => false], $roots), fn ($r) => !str_starts_with((string) ($r['root'] ?? ''), CL_FLASH . '/')));
        unset($GLOBALS['clCtx']);
        return $out;
    };
    $migrate = function (array $places, array $host = []): array {
        $GLOBALS['clMigrateHost'] = $host + ['busy' => false, 'mounts' => []];
        $r = clTrashMigrate($places);
        unset($GLOBALS['clMigrateHost']);
        return $r;
    };

    // --- only the old folder: renamed, every run along; listed as before, from the same places
    $GLOBALS['clTrashMigrated'] = [];
    $s1 = "$tmp/mnt/cache/appdata";
    $old1 = "$s1/" . CL_TRASH_OLD;
    $new1 = "$s1/" . CL_TRASH;
    $mkRun($old1, '20261001-101010', $s1, 'gone-app');
    @mkdir("$old1/20261002-000000.purging/x", 0775, true);
    same('hidden: before — the old folder is read as hers (one run, its item there, from where it came)',
        [1, true, "$s1/gone-app", $old1],
        (function () use ($runsOf, $new1) { $r = array_values(array_filter($runsOf([$new1]), fn ($x) => !$x['purging'])); return [count($r), $r[0]['items'][0]['present'] ?? null, $r[0]['items'][0]['from'] ?? null, $r[0]['root'] ?? null]; })());
    same('hidden: only the old folder — renamed (one rename, nothing copied)', [$new1 => 'renamed'], $migrate([$new1]));
    same('hidden: … the old one gone, the runs in the new one (also one being emptied)', [false, true, true],
        [is_dir($old1), is_file("$new1/20261001-101010/appdata/gone-app/sub/data"), is_dir("$new1/20261002-000000.purging")]);
    $r = array_values(array_filter($runsOf([$new1]), fn ($x) => !$x['purging']));
    same('hidden: … listed from the new folder, its item there, from the same place', [1, $new1, true, "$s1/gone-app"],
        [count($r), $r[0]['root'] ?? null, $r[0]['items'][0]['present'] ?? null, $r[0]['items'][0]['from'] ?? null]);
    same('hidden: … once per place: asked again, nothing is done', [], $migrate([$new1]));

    // «Put back» of the moved run — her own action, on her look given (no server read)
    @mkdir($s1, 0755, true);
    $GLOBALS['clScanStub'] = fn () => ['trash' => ['runs' => $runsOf([$new1])], 'stacks' => ['root' => "$tmp/none"], 'backup_running' => false];
    $id = $r[0]['items'][0]['id'] ?? '';
    $res = clRestore([$id]);
    unset($GLOBALS['clScanStub']);
    same('hidden: «Put back» of a run that was moved — back where it came from, the run gone (only the purging one stays)',
        [true, true, false, ['20261002-000000.purging']],
        [$res['results'][0]['ok'] ?? null, is_file("$s1/gone-app/sub/data"), is_dir("$new1/20261001-101010"), array_values(array_diff(scandir($new1) ?: [], ['.', '..']))]);

    // --- only the new folder: nothing to do
    $GLOBALS['clTrashMigrated'] = [];
    same('hidden: only the new folder — nothing to move', [], $migrate([$new1]));

    // --- both: the runs one by one; a clash gets a suffix (its datasets still its own); a stranger stays, and the old folder
    $GLOBALS['clTrashMigrated'] = [];
    $s2 = "$tmp/mnt/cache/domains";
    $old2 = "$s2/" . CL_TRASH_OLD;
    $new2 = "$s2/" . CL_TRASH;
    $mkRun($new2, '20261001-101010', $s2, 'already');
    $mkRun($old2, '20261001-101010', $s2, 'clashing', 'cache/domains/Win');
    $mkRun($old2, '20261003-030303', $s2, 'plain');
    @mkdir("$old2/20261004-000000.purging", 0775, true);
    @mkdir("$new2/20261004-000000", 0775, true);
    file_put_contents("$old2/notes.txt", 'mine');
    same('hidden: both — the runs moved, the stranger stays and so does the old folder', [$new2 => 'partly'], $migrate([$old2]));
    same('hidden: … the clash got a suffix (also the run being emptied); the others as they are; nothing copied',
        [['20261001-101010', '20261001-101010-2', '20261003-030303', '20261004-000000', '20261004-000000-2.purging'], ['notes.txt']],
        [array_values(array_diff(scandir($new2) ?: [], ['.', '..'])), array_values(array_diff(scandir($old2) ?: [], ['.', '..']))]);
    $m = readJson("$new2/20261001-101010-2/manifest.json") ?? [];
    same('hidden: … the moved run still owns its dataset (named by its time without the suffix); another time\'s it doesn\'t',
        [true, false, true],
        [clTrashAsOk($m['items'][1]['as'] ?? '', 'appdata', '20261001-101010-2'), clTrashAsOk($m['items'][1]['as'] ?? '', 'appdata', '20261003-030303'),
         clTrashAsOk('@cache/domains/' . CL_TRASH . '-20261001-101010-2-Win', 'appdata', '20261001-101010-2')]);
    $items = array_merge(...array_column($runsOf([$new2]), 'items'));
    same('hidden: … every run listed from both folders — the folders and the dataset', ['already', 'clashing', 'Win', 'plain'],
        array_column(array_values(array_filter($items, fn ($it) => $it['kind'] === 'appdata')), 'name'));
    unlink("$old2/notes.txt");
    $GLOBALS['clTrashMigrated'] = [];
    same('hidden: … the stranger gone, the next agent start removes the empty old folder', [[$new2 => 'merged'], false], [$migrate([$new2]), is_dir($old2)]);

    // --- a rename that fails: something else has the new name — logged, the old folder stays in use
    $GLOBALS['clTrashMigrated'] = [];
    $s3 = "$tmp/mnt/cache/isos";
    $old3 = "$s3/" . CL_TRASH_OLD;
    $mkRun($old3, '20261005-050505', $s3, 'img');
    file_put_contents("$s3/" . CL_TRASH, 'a file of that name');
    same('hidden: a rename that fails — said, the old folder stays and is read as hers',
        [["$s3/" . CL_TRASH => 'failed'], true, ['img']],
        [$migrate(["$s3/" . CL_TRASH]), is_file("$old3/20261005-050505/appdata/img/sub/data"), array_column(array_merge(...array_column($runsOf(["$s3/" . CL_TRASH]), 'items')), 'name')]);
    unlink("$s3/" . CL_TRASH);
    $GLOBALS['clTrashMigrated'] = [];
    $old4 = "$tmp/mnt/cache/x/" . CL_TRASH_OLD;
    @mkdir("$old4/20261006-060606", 0775, true);
    @mkdir("$tmp/mnt/cache/x/" . CL_TRASH . '/20261006-060606', 0775, true);
    same('hidden: both, a run whose name is taken gets the next free suffix', [["$tmp/mnt/cache/x/" . CL_TRASH => 'merged'], true],
        [$migrate(["$tmp/mnt/cache/x/" . CL_TRASH]), is_dir("$tmp/mnt/cache/x/" . CL_TRASH . '/20261006-060606-2')]);

    // --- busy: the engine's lock or a job of hers inside the old folder — next time
    $GLOBALS['clTrashMigrated'] = [];
    $s5 = "$tmp/mnt/cache/y";
    $old5 = "$s5/" . CL_TRASH_OLD;
    @mkdir("$old5/20261007-070707", 0775, true);
    same('hidden: busy (a backup or a restore holds the engine\'s lock) — not now', [["$s5/" . CL_TRASH => 'busy'], true], [$migrate(["$s5/" . CL_TRASH], ['busy' => true]), is_dir($old5)]);
    $GLOBALS['clJobs'] = ['queue' => [], 'running' => ['purge:' . "$old5/20261007-070707.purging" => []]];
    same('hidden: … a job of hers inside the old folder — not now either', ["$s5/" . CL_TRASH => 'busy'], $migrate(["$s5/" . CL_TRASH]));
    $GLOBALS['clJobs'] = ['queue' => [], 'running' => []];
    same('hidden: … then at the next look', ["$s5/" . CL_TRASH => 'renamed'], $migrate(["$s5/" . CL_TRASH]));

    // --- a dataset of its own: zfs rename while its mountpoint follows the name; never one set by hand or named otherwise
    $zfsLog = [];
    $zfs = function (string $source) use (&$zfsLog) {
        return function (array $args) use (&$zfsLog, $source) {
            $zfsLog[] = implode(' ', $args);
            return $args[0] === 'get' ? [0, "$source\n", ''] : [0, '', ''];
        };
    };
    $GLOBALS['clTrashMigrated'] = [];
    $s6 = "$tmp/mnt/tank/appdata";
    @mkdir("$s6/" . CL_TRASH_OLD, 0775, true);
    same('hidden: a dataset of its own — zfs rename, its children along', [["$s6/" . CL_TRASH => 'renamed'],
        ['get -H -o source mountpoint tank/appdata/' . CL_TRASH_OLD, 'rename tank/appdata/' . CL_TRASH_OLD . ' tank/appdata/' . CL_TRASH]],
        [$migrate(["$s6/" . CL_TRASH], ['mounts' => ["$s6/" . CL_TRASH_OLD => ['zfs', 'tank/appdata/' . CL_TRASH_OLD]], 'zfs' => $zfs('inherited from tank/appdata')]), $zfsLog]);
    $zfsLog = [];
    $GLOBALS['clTrashMigrated'] = [];
    same('hidden: … its mountpoint set by hand: left as it is (no rename)', [["$s6/" . CL_TRASH => 'failed'], ['get -H -o source mountpoint tank/appdata/' . CL_TRASH_OLD]],
        [$migrate(["$s6/" . CL_TRASH], ['mounts' => ["$s6/" . CL_TRASH_OLD => ['zfs', 'tank/appdata/' . CL_TRASH_OLD]], 'zfs' => $zfs('local')]), $zfsLog]);
    $zfsLog = [];
    $GLOBALS['clTrashMigrated'] = [];
    same('hidden: … a filesystem named otherwise, or no ZFS: left as it is', [["$s6/" . CL_TRASH => 'failed'], [], true],
        [$migrate(["$s6/" . CL_TRASH], ['mounts' => ["$s6/" . CL_TRASH_OLD => ['zfs', 'tank/appdata/other']], 'zfs' => $zfs('default')]), $zfsLog, is_dir("$s6/" . CL_TRASH_OLD)]);

    // --- Mr. Restori's set-aside folder: moved over by his time; a time taken in both stays where it is (his journals name it)
    $GLOBALS['clTrashMigrated'] = [];
    $f = "$tmp/boot/config";
    @mkdir("$f/" . CL_RESTORE_ASIDE_OLD . '/20261007-090000/plugins/dockerMan/templates-user', 0755, true);
    file_put_contents("$f/" . CL_RESTORE_ASIDE_OLD . '/20261007-090000/plugins/dockerMan/templates-user/my-a.xml', '<old/>');
    @mkdir("$f/" . CL_RESTORE_ASIDE_OLD . '/20261008-080000', 0755, true);
    file_put_contents("$f/" . CL_RESTORE_ASIDE_OLD . '/20261008-080000/x', 'old');
    @mkdir("$f/" . CL_RESTORE_ASIDE . '/20261008-080000', 0755, true);
    same('hidden: his folder — both there: a time of the old one moved, a time taken in both stays (and so the old folder)',
        [["$f/" . CL_RESTORE_ASIDE => 'partly'], true, true],
        [$migrate(["$f/" . CL_RESTORE_ASIDE]), is_file("$f/" . CL_RESTORE_ASIDE . '/20261007-090000/plugins/dockerMan/templates-user/my-a.xml'), is_dir("$f/" . CL_RESTORE_ASIDE_OLD . '/20261008-080000')]);
    // his «Put back» from a journal of before: the undo steps name where it lies now — the moved one under the new name,
    // the one still in the old folder where it is; where he writes, never under the old name
    $j = ['steps' => [
        ['do' => 'aside', 'state' => 'ok', 'undo' => [
            ['do' => 'aside', 'path' => '/boot/config/plugins/dockerMan/templates-user/my-a.xml', 'to' => "$f/" . CL_RESTORE_ASIDE_OLD . '/{T}/plugins/dockerMan/templates-user/my-a.xml', 'optional' => true],
            ['do' => 'move', 'from' => "$f/" . CL_RESTORE_ASIDE_OLD . '/20261007-090000/plugins/dockerMan/templates-user/my-a.xml', 'to' => '/boot/config/plugins/dockerMan/templates-user/my-a.xml']]],
        ['do' => 'aside', 'state' => 'ok', 'undo' => [['do' => 'move', 'from' => "$f/" . CL_RESTORE_ASIDE_OLD . '/20261008-080000/x', 'to' => '/boot/config/x']]],
        ['do' => 'define', 'state' => 'ok', 'undo' => [['do' => 'define', 'xml' => "<domain><x>$f/" . CL_RESTORE_ASIDE_OLD . '/a</x></domain>', 'name' => 'Win']]]]];
    $u = rsUndoSteps($j);
    same('hidden: his «Put back» after the move — from where it lies now (the time still in the old folder there); written only under the new name; an XML untouched',
        ["$f/" . CL_RESTORE_ASIDE_OLD . '/20261008-080000/x', "$f/" . CL_RESTORE_ASIDE . '/{T}/plugins/dockerMan/templates-user/my-a.xml',
         "$f/" . CL_RESTORE_ASIDE . '/20261007-090000/plugins/dockerMan/templates-user/my-a.xml', "<domain><x>$f/" . CL_RESTORE_ASIDE_OLD . '/a</x></domain>'],
        [$u[1]['from'] ?? null, $u[2]['to'] ?? null, $u[3]['from'] ?? null, $u[0]['xml'] ?? null]);
    check('hidden: … and the moved file is really there to go back', is_file($u[3]['from'] ?? ''));
    rename("$f/" . CL_RESTORE_ASIDE_OLD . '/20261008-080000', "$f/" . CL_RESTORE_ASIDE . '/20261008-080001');
    @rmdir("$f/" . CL_RESTORE_ASIDE_OLD);
    same('hidden: … once the old folder is gone, the rest under the new name too', "$f/" . CL_RESTORE_ASIDE . '/20261008-080000/x', rsUndoSteps($j)[1]['from'] ?? null);

    // --- the other desks know both names
    same('hidden: the night watchman — a share put whole into the storeroom still counts for it (either name)', ['Serien', 'Serien', 'Alt', null],
        [watchmanGoneShare('tank/.UnraidSecretaryOffice-trash-20261009-101010-Serien/sub'), watchmanGoneShare('tank/_UnraidSecretaryOffice-trash-20261006-140500-Serien'),
         watchmanGoneShare('tank/.UnraidSecretaryOffice-trash-20261009-101010-2-Alt'), watchmanGoneShare('tank/.UnraidSecretaryOffice-trash')]);
    same('hidden: … the office\'s hidden folders are no intruder\'s hidden folder; a stranger\'s still is, and a scratch folder',
        [false, false, true, true],
        [(bool) preg_match(WATCH_ODD_EXE, watchmanOddPath('/mnt/cache/appdata/.UnraidSecretaryOffice-trash/20261009-101010/appdata/x/run')),
         (bool) preg_match(WATCH_ODD_EXE, watchmanOddPath('/boot/config/.UnraidSecretaryOffice-restore/20261009-101010/bin/x')),
         (bool) preg_match(WATCH_ODD_EXE, watchmanOddPath('/mnt/cache/appdata/.hidden/miner')), (bool) preg_match(WATCH_ODD_EXE, watchmanOddPath('/tmp/.UnraidSecretaryOffice-trash/x'))]);
    same('hidden: partners\' places — a dataset she put away under either name is hers', [true, true, 'deadbeef'],
        [partnerLookDataset('tank/' . PARTNER_PARENT . '/.UnraidSecretaryOffice-trash-20261009-101010-deadbeef')['trash'] ?? null,
         partnerLookDataset('tank/' . PARTNER_PARENT . '/_UnraidSecretaryOffice-trash-20261008-101010-deadbeef')['trash'] ?? null,
         partnerLookDataset('tank/' . PARTNER_PARENT . '/.UnraidSecretaryOffice-trash-20261009-101010-deadbeef')['id'] ?? null]);
    @mkdir("$tmp/letgo", 0700, true);
    file_put_contents("$tmp/letgo/letgo-20261008-190000.json", json_encode(['trash' => ['/mnt/disk1/UnraidSecretaryOffice/' . CL_TRASH_OLD, '/mnt/pool/UnraidSecretaryOffice/' . CL_TRASH]]));
    same('hidden: Mr. Backupsy\'s let-go journals of before — the storeroom they name, by its name now',
        ['/mnt/disk1/UnraidSecretaryOffice/' . CL_TRASH, '/mnt/pool/UnraidSecretaryOffice/' . CL_TRASH], backupLetGoTrashRoots([], "$tmp/letgo"));

    // --- the engine: both names are the storeroom (never snapshotted, never a share's children); Kopia leaves out both
    $lib = escapeshellarg(OFFICE_DIR . '/backup/lib/common.sh');
    $sh = fn (string $script) => trim((string) shell_exec('bash -c ' . escapeshellarg("export UB_DATA=$tmp/ub; source $lib >/dev/null 2>&1; $script") . ' 2>&1'));
    same('hidden: engine — the storeroom by either name, datasets put away under either; nothing else',
        '1 1 1 1 0 0', $sh('for n in .UnraidSecretaryOffice-trash _UnraidSecretaryOffice-trash .UnraidSecretaryOffice-trash-20261009-101010-x _UnraidSecretaryOffice-trash-1 UnraidSecretaryOffice-trash appdata; do ub_storeroom "$n" && printf "1 " || printf "0 "; done'));
    file_put_contents("$tmp/old.ini", "[kopia]\nenabled = yes\nignore = _UnraidSecretaryOffice-trash*/\nignore = .DS_Store\n");
    file_put_contents("$tmp/both.ini", "[kopia]\nenabled = yes\nignore = _UnraidSecretaryOffice-trash*/\nignore = .UnraidSecretaryOffice-trash*/\n");
    file_put_contents("$tmp/none.ini", "[kopia]\nenabled = yes\nignore = .DS_Store\n");
    same('hidden: engine — who leaves out the old name leaves out the new one too (before the setup wrote it); once; nobody else',
        ['_UnraidSecretaryOffice-trash*/|.DS_Store|.UnraidSecretaryOffice-trash*/', '_UnraidSecretaryOffice-trash*/|.UnraidSecretaryOffice-trash*/', '.DS_Store'],
        array_map(fn ($f) => $sh("cfg_load $tmp/$f.ini; apply_settings; IFS='|'; echo \"\${KOPIA_IGNORE[*]}\""), ['old', 'both', 'none']));
    check('hidden: engine — a share\'s storeroom datasets are left out by both names (plan and partner units)',
        substr_count((string) file_get_contents(OFFICE_DIR . '/backup/lib/common.sh'), 'ub_storeroom "${ds##*/}"') === 2
        && !str_contains((string) file_get_contents(OFFICE_DIR . '/backup/lib/common.sh'), '== _UnraidSecretaryOffice-trash*'));
    $setupSrc = (string) file_get_contents(OFFICE_DIR . '/backup/setup.sh');
    check('hidden: setup — the plan adds both of Kopia\'s rules for the storeroom', str_contains($setupSrc, 'plist_add "kopia|ignore" "$UB_STOREROOM*/"')
        && str_contains($setupSrc, 'plist_add "kopia|ignore" "$UB_STOREROOM_OLD*/"'));

    $GLOBALS['clTrashMigrated'] = [];
    hardeningRm($tmp);
}

/**
 * The engine's drift notes in the office's words (engine 2.41; Benj 2026-10-12: «Geändert seit der Einrichtung» showed
 * «App 'zz-uso-nc' has a Kopia source of its own …» in English). Read in the engine: every `drift_add <level> "<text>"`
 * of lib/common.sh and backup.sh names a code (a snake_case word; the backup place's `dumps_<problem>` is said as
 * `message.dumps_*`), the codes from before 2.41 keep their value, every code has `drift_code.<code>` in all five
 * languages and each placeholder of it is a param of the call (`share`/`value` for a value, `where` for `locations`).
 * In bash: the checks of a gone app and a gone VM and drift_json_write — drift.json with `params` (a name with | and ",
 * a text with a newline). Under node: driftText() with the German strings — every code of the engine in German, the
 * codes from before 2.41 by their value, an item without params whose sentence needs one, an unknown code and no code
 * by the engine's text.
 */
function testDriftCodes(): void
{
    $calls = driftCalls([OFFICE_DIR . '/backup/lib/common.sh', OFFICE_DIR . '/backup/backup.sh']);
    check('drift codes: the engine\'s drift_add calls found (' . count($calls) . ')', count($calls) >= 43);
    same('drift codes: every drift_add names a code', [], array_values(array_map(fn ($c) => "{$c['file']}:{$c['line']}",
        array_filter($calls, fn ($c) => count($c['words']) < 2))));
    $codes = [];          // code => [allowed placeholders of each call]
    $bad = [];
    foreach ($calls as $c) {
        $code = $c['words'][1] ?? '';
        if ($code === '"dumps_$DUMPS_PROBLEM"') {
            continue;
        }
        if (!preg_match('/^[a-z][a-z0-9_]*$/D', $code)) {
            $bad[] = "{$c['file']}:{$c['line']} $code";
            continue;
        }
        $value = $c['words'][2] ?? '""';
        $keys = [];
        foreach (array_slice($c['words'], 3) as $w) {
            if (preg_match('/^([a-z_]+)=/', $w, $m)) {
                $keys[] = $m[1];
            } else {
                $bad[] = "{$c['file']}:{$c['line']} $code: not key=value: $w";
            }
        }
        if ($value !== '""') {
            array_push($keys, 'share', 'value');
        }
        if (in_array('locations', $keys, true)) {
            $keys[] = 'where';
        }
        $codes[$code][] = $keys;
    }
    same('drift codes: each a snake_case word, its params key=value', [], $bad);
    check('drift codes: the dynamic one is the backup place\'s', (bool) array_filter($calls, fn ($c) => ($c['words'][1] ?? '') === '"dumps_$DUMPS_PROBLEM"'));
    $old = ['place_no_history', 'place_not_kopia', 'new_waiting', 'known_missing', 'new_container', 'new_database', 'new_nextcloud', 'new_vm'];
    same('drift codes: the codes from before 2.41 keep their value', [], array_values(array_filter($old,
        fn ($k) => !isset($codes[$k]) || array_filter($codes[$k], fn ($keys) => !in_array('value', $keys, true)))));
    $miss = [];
    $holes = [];
    foreach (['en', 'de', 'it', 'fr', 'es'] as $lang) {
        $l = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/backup/lang/$lang.json"), true);
        foreach ($codes as $code => $each) {
            $s = $l["drift_code.$code"] ?? null;
            if (!is_string($s)) {
                $miss[] = "$lang drift_code.$code";
                continue;
            }
            preg_match_all('/\{(\w+)\}/', $s, $m);
            foreach ($each as $keys) {
                foreach (array_diff($m[1], $keys) as $k) {
                    $holes[] = "$lang drift_code.$code {{$k}}";
                }
            }
        }
        foreach (['missing', 'unknown', 'forbidden', 'off'] as $p) {
            if (!is_string($l["message.dumps_$p"] ?? null)) {
                $miss[] = "$lang message.dumps_$p";
            }
        }
    }
    same('drift codes: every code has its words in all five languages (' . count($codes) . ' codes)', [], $miss);
    same('drift codes: every placeholder is a param of the call', [], array_values(array_unique($holes)));
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/en.json'), true);
    check('drift codes: Benj\'s finding has words of its own', str_contains($en['drift_code.app_source_orphan'] ?? '', '«{name}»'));

    // --- in bash: the checks and drift.json
    $tmp = hardeningTmp('drift-codes');
    file_put_contents("$tmp/s.ini", "[general]\ndumps_share = UnraidSecretaryOffice\nmount_root = /mnt/addons/UnraidSecretaryOffice/snapshots\n"
        . "[kopia]\nenabled = yes\n[share \"appdata\"]\nmode = kopia\n[share \"UnraidSecretaryOffice\"]\nmode = kopia\n"
        . "[app \"zz-uso-nc\"]\nkopia = yes\nfolder = appdata/zz-uso-nc\n[vm \"Old VM\"]\nmode = snapshot\nprepare = freeze\n");
    $lib = escapeshellarg(OFFICE_DIR . '/backup/lib/common.sh');
    $script = "UB_DATA=$tmp/data; source $lib >/dev/null 2>&1; cfg_load $tmp/s.ini; cfg_validate >/dev/null; apply_settings;"
        . ' CT_NAMES=(); CT_PROJECT=(); VM_SERVICE=yes; VM_NAMES=(); PLAN_MOUNT=(appdata UnraidSecretaryOffice); PLAN_KITEMS=("app|zz-uso-nc|zz-uso-nc");'
        . ' drift_check_items; drift_check_vms;'
        . ' drift_add warn "New share \'a|b\'"$\'\\n\'"line 2" share_new "" name=\'a|b "c" x=y\' locations="disk1, maple" bytes=12;'
        . " UB_STATE=$tmp/state; mkdir -p \$UB_STATE; KP_CHECKED=no; drift_json_write; cat \$UB_STATE/drift.json";
    $raw = (string) shell_exec('bash -c ' . escapeshellarg($script) . ' 2>&1');
    $dj = json_decode($raw, true);
    same('drift codes (bash): a gone app\'s and a gone VM\'s notes with code and params, value only for old codes; a name with | " = and a text with a newline',
        [['info', 'app_source_orphan', '', ['name' => 'zz-uso-nc']], ['info', 'vm_gone', '', ['name' => 'Old VM']],
         ['warn', 'share_new', '', ['name' => 'a|b "c" x=y', 'locations' => 'disk1, maple', 'bytes' => '12'], "New share 'a|b'\nline 2"]],
        array_map(fn ($i) => array_merge([$i['level'] ?? null, $i['code'] ?? null, $i['value'] ?? null, $i['params'] ?? null],
            ($i['code'] ?? '') === 'share_new' ? [$i['text'] ?? null] : []), $dj['items'] ?? [$raw]));
    // engine 2.65 (C-B29): a new VM whose disk lies on xfs was «in the snapshot of their share» - false there. Said as it is:
    // not set up yet, and what holds the disk - Kopia's copy of its share (read live) or nothing; on ZFS the old words
    file_put_contents("$tmp/v.ini", "[general]\ndumps_share = UnraidSecretaryOffice\nmount_root = /mnt/addons/UnraidSecretaryOffice/snapshots\n"
        . "[kopia]\nenabled = yes\n[share \"vmk\"]\nmode = kopia\n[share \"UnraidSecretaryOffice\"]\nmode = kopia\n[vm \"setvm\"]\nmode = snapshot\nprepare = none\n");
    $vms = ' CT_NAMES=(); VM_SERVICE=yes; VM_NAMES=(zvm xvm kvm setvm);'
        . ' VM_SNAP=([zvm]=yes [xvm]=live [kvm]=live [setvm]=live); VM_OWN_DS=([zvm]=cache/domains/zvm);'
        . ' VM_DISKS=([zvm]="hdc|/mnt/user/domains/zvm/v.img|cache|zfs|cache/domains/zvm|domains" [xvm]="hdc|/mnt/user/uso-vmxfs/x/v.img|disk1|xfs||uso-vmxfs"'
        . ' [kvm]="hdc|/mnt/user/vmk/k/v.img|disk1|xfs||vmk" [setvm]="hdc|/mnt/user/vmk/s/v.img|disk1|xfs||vmk");';
    $vraw = (string) shell_exec('bash -c ' . escapeshellarg("UB_DATA=$tmp/data2; source $lib >/dev/null 2>&1; cfg_load $tmp/v.ini; cfg_validate >/dev/null; apply_settings;"
        . "$vms drift_check_vms; UB_STATE=$tmp/state2; mkdir -p \$UB_STATE; KP_CHECKED=no; drift_json_write; cat \$UB_STATE/drift.json") . ' 2>&1');
    same('drift codes (bash): a new VM on ZFS in its share\'s snapshot; on xfs not set up and not held (nothing, or only Kopia\'s copy of its share); one set up the same',
        [['info', 'new_vm', ['name' => 'zvm']], ['info', 'new_vm_unheld', ['name' => 'xvm']], ['warn', 'vm_disk_live', ['name' => 'xvm']],
         ['info', 'new_vm_unheld', ['name' => 'kvm']], ['warn', 'vm_disk_live_kopia', ['name' => 'kvm', 'share' => 'vmk']], ['warn', 'vm_disk_live_kopia', ['name' => 'setvm', 'share' => 'vmk']]],
        array_map(fn ($i) => [$i['level'] ?? null, $i['code'] ?? null, $i['params'] ?? null], json_decode($vraw, true)['items'] ?? [$vraw]));
    check('drift codes (bash): the English text stays as it was', str_starts_with($dj['items'][0]['text'] ?? '', "App 'zz-uso-nc' has a Kopia source of its own in settings.ini"));
    $empty = json_decode((string) shell_exec('bash -c ' . escapeshellarg("source $lib >/dev/null 2>&1; UB_STATE=$tmp/state2; mkdir -p \$UB_STATE; KP_CHECKED=no;"
        . ' drift_json_write; cat $UB_STATE/drift.json') . ' 2>&1'), true);
    same('drift codes (bash): no drift = an empty list', [], $empty['items'] ?? null);

    // --- under node: the desk's words
    $node = testsNode();
    if ($node === '') {
        check('drift codes: node is missing here - skipped', true);
        hardeningRm($tmp);
        return;
    }
    $items = [];
    foreach ($codes as $code => $each) {
        $p = [];
        foreach ($each[0] as $k) {
            if (!in_array($k, ['share', 'value', 'where'], true)) {
                $p[$k] = $k === 'bytes' ? '2048' : "P-$k";
            }
        }
        $items[] = ['level' => 'warn', 'code' => $code, 'value' => in_array('value', $each[0], true) ? 'V-value' : '', 'params' => $p, 'text' => "EN $code"];
    }
    $cases = [
        ['level' => 'info', 'code' => 'app_source_orphan', 'value' => '', 'params' => ['name' => 'zz-uso-nc'],
         'text' => "App 'zz-uso-nc' has a Kopia source of its own in settings.ini but no container of it exists any more - what is left of it still goes there"],
        ['level' => 'info', 'code' => 'new_container', 'value' => 'web', 'text' => 'an engine 2.40\'s'],
        ['level' => 'warn', 'code' => 'share_new', 'value' => '', 'params' => ['name' => 'Schule', 'locations' => 'daten', 'bytes' => '3221225472'], 'text' => 'demo'],
        ['level' => 'warn', 'code' => 'share_new', 'value' => '', 'params' => ['name' => 'Schule', 'locations' => 'daten', 'bytes' => ''], 'text' => 'no size'],
        ['level' => 'warn', 'code' => 'share_new', 'value' => '', 'text' => 'without params'],
        ['level' => 'warn', 'code' => 'share_new', 'value' => '', 'params' => ['name', 'x'], 'text' => 'params a list'],
        ['level' => 'warn', 'code' => 'brand_new', 'value' => 'x', 'params' => ['name' => 'x'], 'text' => 'unknown code'],
        ['level' => 'warn', 'text' => 'an engine 2.17\'s'],
        ['level' => 'error', 'code' => 'dumps_missing', 'value' => 'UnraidSecretaryOffice', 'params' => ['share' => 'UnraidSecretaryOffice'], 'text' => 'dumps'],
    ];
    file_put_contents("$tmp/items.json", json_encode(['items' => $items, 'cases' => $cases]));
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
const [bkFile, coreFile, langDir, itemsFile] = process.argv.slice(2);
