        $ct('ml', 'immich-machine-learning', [$vol('model-cache', '/cache')]),
        $ct('pg', 'postgres:16', [$vol($hex, '/var/lib/postgresql/data')]),
        $ct('web', 'nginx', [$bind("$mnt/user/appdata/web", '/config')])]));
    file_put_contents("$data/settings.ini", "[general]\nserver = Test\nmount_root = $root\nview_root = $mnt/addons/UnraidSecretaryOffice/btrfs-snap\nsnap_prefix = uso-backup-\n"
        . "dumps_share = UnraidSecretaryOffice\n[docker]\nstop = all\nknown = kopia\nknown = ml\nknown = pg\nknown = web\n[flash]\nmode = off\n[kopia]\nenabled = yes\ncontainer = kopia\nidentity = root@kopia\n"
        . "[share \"appdata\"]\nmode = kopia\nkopia_ignore = /kopia/\n[share \"UnraidSecretaryOffice\"]\nmode = kopia\n[share \"cfgsaved\"]\nmode = kopia\n");
    $env = "export PATH=$tmp/bin:\$PATH UB_DATA=$data UB_MNT=$mnt UB_BOOT=$tmp/boot UB_SHARES_CFG=$tmp/boot/config/shares"
         . " UB_DISKS_INI=$tmp/fake/disks.ini UB_NOTIFY_BIN=$tmp/bin/notify UB_MOUNTS_FILE=$tmp/fake/mounts FAKE=$tmp/fake FAKE_ROOT=$root"
         . " UB_SHARES_INI=$tmp/fake/shares.ini";
    // engine 2.65 (C-M16): configs without a root anywhere - «fresh» Unraid lists (a share just made, still empty), «cfgonly»
    // and «cfgsaved» (in settings.ini) it no longer lists (their roots gone, e.g. after Unraid renamed it)
    foreach (['fresh', 'cfgonly', 'cfgsaved'] as $c) {
        touch("$tmp/boot/config/shares/$c.cfg");
    }
    file_put_contents("$tmp/fake/shares.ini", "[\"appdata\"]\nname=\"appdata\"\n[\"UnraidSecretaryOffice\"]\nname=\"UnraidSecretaryOffice\"\n[\"fresh\"]\nname=\"fresh\"\n");
    $out = (string) shell_exec('bash -c ' . escapeshellarg("$env UB_SIZE_TIMEOUT=0 UB_EXPLAIN=0; bash " . escapeshellarg(OFFICE_DIR . '/backup/setup.sh') . ' --plan </dev/null') . ' 2>&1');
    $plan = json_decode((string) @file_get_contents("$data/state/setup-plan.json"), true) ?: [];
    $msgs = is_array($plan['messages'] ?? null) ? $plan['messages'] : [];
    check('setup messages (engine): the plan was written', $msgs !== [], $out);
    $by = fn (string $c) => array_values(array_map(fn ($m) => $m['params'] ?? null, array_filter($msgs, fn ($m) => ($m['code'] ?? '') === $c)));
    same('setup messages (engine): the Docker volumes as a code - each app with its volumes: the name (empty: anonymous) and the path in the container',
        [['app' => 'ml', 'volumes' => [['name' => 'model-cache', 'target' => '/cache']]], ['app' => 'pg', 'volumes' => [['name' => '', 'target' => '/var/lib/postgresql/data']]]],
        $by('docker_volumes'));
    $i = array_key_first(array_filter($msgs, fn ($m) => ($m['code'] ?? '') === 'docker_volumes'));
    same('setup messages (engine): … its «Fix:» line right after it as `more`; the terminal keeps the English text', ['more', true, true],
        [$msgs[$i + 1]['code'] ?? null, str_contains($out, "'ml' uses Docker volumes (model-cache at /cache)"), str_contains($out, 'Fix: in the template')]);
    same('setup messages (engine): the Kopia sources - orphaned (under its root, no share any more), gone from the container, another identity',
        [[['path' => '/uso/oldshare', 'source' => 'root@kopia:/uso/oldshare']], [['path' => '/backup-snapshots/olddata', 'source' => 'root@kopia:/backup-snapshots/olddata']], [['source' => 'admin@laptop:/home/x']]],
        [$by('source_orphan'), $by('source_gone'), $by('source_foreign')]);
    $ks = is_array($plan['kopia']['sources'] ?? null) ? $plan['kopia']['sources'] : [];
    same('setup messages (engine): 2.59 the plan\'s old source under its root says what it is - kind, name, why, its snapshots and the newest; the others only state and source',
        [[['state' => 'orphan', 'source' => 'root@kopia:/uso/oldshare', 'kind' => 'share', 'name' => 'oldshare', 'why' => 'gone', 'snapshots' => 1, 'newest' => '2026-10-01T02:00:00Z']],
         [['source', 'state'], ['source', 'state'], ['source', 'state']]],
        [array_values(array_filter($ks, fn ($x) => ($x['state'] ?? '') === 'orphan')),
         array_values(array_map(function ($x) { $k = array_keys($x); sort($k); return $k; }, array_filter($ks, fn ($x) => ($x['state'] ?? '') !== 'orphan')))]);
    same('setup messages (engine): the live test that couldn\'t mount - coded with the root', [['root' => $root]], $by('kopia_probe_failed'));
    $shp = array_column(is_array($plan['shares'] ?? null) ? $plan['shares'] : [], null, 'name');
    same('setup messages (engine): a config Unraid no longer lists is no share — never offered (2.65); one it lists is still empty; one saved is gone',
        [false, ['kopia', 'empty'], ['gone', false]],
        [isset($shp['cfgonly']), [$shp['fresh']['mode'] ?? null, $shp['fresh']['why'] ?? null], [$shp['cfgsaved']['why'] ?? null, $shp['cfgsaved']['exists'] ?? null]]);
    same('setup messages (engine): no message without a code - hints, warnings and (2.58) the OK and error lines too', [],
        array_values(array_map(fn ($m) => $m['text'], array_filter($msgs, fn ($m) => ($m['code'] ?? '') === ''))));
    same('setup messages (engine): the OK lines as codes with their params (2.58) - the backup place, the file systems',
        [true, true], [in_array(['level' => 'ok', 'code' => 'backup_place'], array_map(fn ($m) => array_intersect_key($m, ['level' => 1, 'code' => 1]), $msgs), true),
         (bool) array_filter($msgs, fn ($m) => ($m['code'] ?? '') === 'fs_present' && in_array($m['params']['fs'] ?? '', ['zfs', 'btrfs'], true))]);
    $unknown = array_values(array_unique(array_filter(array_map(fn ($g) => $g['code'] ?? '', backupSetupNotes($msgs)), fn ($c) => $c !== '' && !isset($en["setup.msg.$c"]))));
    same('setup messages (engine): every code of this plan has the office\'s words', [], $unknown);
    $notes = array_column(array_filter(backupSetupNotes($msgs), fn ($g) => isset($g['code'])), null, 'code');
    same('setup messages (engine): grouped for the page - ml a cache, pg data; two gone paths would be one entry',
        [['ml'], ['pg']], [array_column(array_column($notes['volumes_cache']['items'] ?? [], 'params'), 'app'), array_column(array_column($notes['volumes_data']['items'] ?? [], 'params'), 'app')]);
    exec('rm -rf ' . escapeshellarg($tmp));
}

/**
 * Ms. Moverelli's fixture: a data folder, share cfgs (Back prefer, Docs yes with a threshold, Filme yes, Arr no), a /mnt
 * tree, a stand-in move binary (pool → disk1, a data disk → the pool, a folder as Unraid's: created there, removed here when
 * empty; /mnt/user0 refused as Unraid's move does; MOVE_STOP writes a stop request after its first call, MOVE_SLEEP
 * waits, MOVE_FAIL moves nothing and exits 1; MOVE_CALLS counts its calls), a zfs that knows no pool (df counts), stand-ins for Unraid's
 * version and schedule, the mover at work, Jack's runs and his list — in $GLOBALS['moverelliHost'] (moverelliHost()).
 * $v: the values the stand-ins read (by reference).
 */
function moverelliFixture(string $tmp, array &$v): void
{
    foreach (["$tmp/data", "$tmp/shares", "$tmp/bin", "$tmp/run", "$tmp/tuning", "$tmp/us/scripts", "$tmp/plugins/dynamix", "$tmp/mnt/cache/Filme/A",
              "$tmp/mnt/cache/Docs", "$tmp/mnt/disk1/Back"] as $d) {
        @mkdir($d, 0700, true);
    }
    // the shares as Unraid shows them (a cfg alone is no share — officeShareExists()): /mnt/user/<share>, the array started
    foreach (['Back', 'Docs', 'Filme', 'Arr', 'GLOBAL', '2024'] as $d) {
        @mkdir("$tmp/mnt/user/$d", 0700, true);
    }
    file_put_contents("$tmp/var.ini", "fsState=\"Started\"\n");
    file_put_contents("$tmp/shares.ini", '');
    file_put_contents("$tmp/shares/Back.cfg", "shareUseCache=\"prefer\"\nshareCachePool=\"cache\"\n");
    file_put_contents("$tmp/shares/Docs.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\nshareCachePool2=\"\"\n");
    file_put_contents("$tmp/shares/Filme.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\n");
    file_put_contents("$tmp/shares/Arr.cfg", "shareUseCache=\"no\"\n");
    file_put_contents("$tmp/mnt/cache/Filme/A/a.mkv", str_repeat('a', 300));
    file_put_contents("$tmp/mnt/cache/Filme/A/a.nfo", 'nfo');
    file_put_contents("$tmp/mnt/cache/Docs/c.txt", 'doc');
    file_put_contents("$tmp/mnt/disk1/Back/d.txt", 'back');
    file_put_contents("$tmp/bin/move", <<<'SH'
#!/bin/bash
# the tests' move binary: one path per line on stdin
[[ -n "${MOVE_SLEEP:-}" ]] && sleep "$MOVE_SLEEP"
[[ -n "${MOVE_CALLS:-}" ]] && echo x >> "$MOVE_CALLS"
[[ -n "${MOVE_FAIL:-}" ]] && { while IFS= read -r _; do :; done; echo "move: refused"; exit 1; }
# MOVE_SNAP: the live status as Smart Mover left it before this call (its first call only)
[[ -n "${MOVE_SNAP:-}" && ! -e "$MOVE_SNAP" && -n "${CUSTOMMOVER_STATUS:-}" ]] && cp "$CUSTOMMOVER_STATUS" "$MOVE_SNAP"
while IFS= read -r f; do
    case "$f" in
        "$MOVE_ROOT"/cache/*) rel=${f#"$MOVE_ROOT"/cache/}; to="$MOVE_ROOT/disk1/$rel" ;;
        "$MOVE_ROOT"/disk[0-9]*/*) rel=${f#"$MOVE_ROOT"/disk*/}; to="$MOVE_ROOT/cache/$rel" ;;
        *) echo "move: $f No such file or directory"; continue ;;
    esac
    [[ -n "${MOVE_LOG:-}" ]] && printf '%s\n' "$f" >> "$MOVE_LOG"
    if [[ -d "$f" && ! -L "$f" ]]; then mkdir -p "$to" && rmdir "$f" 2>/dev/null; continue; fi
    mkdir -p "$(dirname "$to")" && mv "$f" "$to"
done
[[ -n "${MOVE_STOP:-}" && ! -e "$MOVE_STOP" ]] && printf '{"why":"user"}' > "$MOVE_STOP"
exit 0
SH);
    file_put_contents("$tmp/bin/zfs", "#!/bin/bash\nexit 1\n");
    file_put_contents("$tmp/bin/notify", "#!/bin/bash\nprintf '%s\\n' \"\$*\" >> " . escapeshellarg("$tmp/notified") . "\n");
    foreach (['move', 'zfs', 'notify'] as $b) {
        chmod("$tmp/bin/$b", 0755);
    }
    $v += ['version' => '7.3.2', 'own' => ['set' => '', 'cron' => null], 'mover' => false, 'mover_self' => false, 'busy' => false, 'jack_desk' => null,
           'tuning' => false, 'env' => [], 'hired' => true, 'jack_lists' => [], 'jack_ran' => true];
    $GLOBALS['moverelliHost'] = [
        'dir' => "$tmp/data", 'shares_dir' => "$tmp/shares", 'shares_ini' => "$tmp/shares.ini", 'var_ini' => "$tmp/var.ini",
        'mnt' => "$tmp/mnt", 'waitdir' => "$tmp/run", 'write_state' => false, 'look_every' => 0,
        'env' => ['CUSTOMMOVER_MOVER_BIN' => "$tmp/bin/move", 'CUSTOMMOVER_ZFS' => "$tmp/bin/zfs", 'MOVE_ROOT' => "$tmp/mnt"],
        'version' => function () use (&$v) { return $v['version']; },
        'unraid' => function () use (&$v) { return $v['own']; },
        'mover_running' => function (?int $self = null) use (&$v) { return $self === null ? $v['mover'] : $v['mover_self']; },
        'jack_busy' => function () use (&$v) { return $v['busy']; },
        'jack_desk' => function () use (&$v) { return $v['jack_desk']; },
        'scheduled' => fn () => true, 'lock_wait' => 1, 'next_run' => fn () => null, 'jack_next' => fn () => null,
        'hired' => function () use (&$v) { return $v['hired']; },
        'tuning' => function () use (&$v) { return $v['tuning']; },
        'tuning_dir' => "$tmp/tuning", 'us_dir' => "$tmp/us", 'cron_glob' => "$tmp/plugins/*/*.cron", 'unraid_cron' => "$tmp/plugins/dynamix/mover.cron",
        'jack_lists' => function () use (&$v) { return $v['jack_lists']; }, 'jack_ran' => function () use (&$v) { return $v['jack_ran']; },
        'import_look' => ["$tmp/flash/*/smart_mover.ini"],      // never the server's flash
        'cron_d' => "$tmp/cron.d/*", 'root_crontab' => "$tmp/crontab.root",
        'plugin_installed' => function (string $name) use (&$v) { return in_array($name, $v['plugins'] ?? [], true); },
    ];
}

/**
 * Ms. Moverelli and Unraid's own mover (agent/desks/moverelli-unraid.php, 2026-10-12): her save (and the import's apply)
 * refused while Unraid's schedule is on unless the page's consent comes along, nothing written then; with it Unraid's
 * form «Disabled» (an emcmd stand-in — never Unraid's own), the schedule it had noted once; her let-go refused while
 * Jack Emby is hired, else her schedule off and Unraid's schedule back exactly as noted (URL-encoded as the form sends
 * it, looked at afterwards), one set by hand meanwhile kept, a noted value of another shape never sent, a failure said;
 * EmbyCache's list before its first run (D1: no real run, said, a Team Lead hint; his traces); the share's path quoted
 * in an exclude entry and the sleeping array disks named in her log (Smart Mover); her page's consent and let-go under node.
 */
function testMoverelliUnraid(): void
{
    $tmp = hardeningTmp('moverelli-unraid');
    $v = [];
    moverelliFixture($tmp, $v);
    $GLOBALS['moverelliHost']['cron_file'] = "$tmp/office.cron";
    $GLOBALS['moverelliHost']['cron_apply'] = false;
    $h = moverelliHost();
    $dir = "$tmp/data";
    @mkdir("$tmp/dynamix", 0700, true);
    $waited = [];
    $GLOBALS['jackMoverHost'] = ['share_cfg' => "$tmp/share.cfg", 'mover_cron' => "$tmp/dynamix/mover.cron", 'var_ini' => "$tmp/ui-var.ini", 'emcmd' => "$tmp/emcmd",
        'wait' => function (int $ms) use (&$waited) { $waited[] = $ms; }, 'tuning' => fn () => null, 'moverelli' => fn () => null,
        'note' => fn (string $was, string $logging) => moverelliUnraidNoteKeep($was, $logging, $dir)];
    $calls = function () use ($tmp): array { $c = file_exists("$tmp/emcmd.calls") ? file("$tmp/emcmd.calls", FILE_IGNORE_NEW_LINES) : []; @unlink("$tmp/emcmd.calls"); return $c; };
    // the stand-in does what emhttpd does with Unraid's form: «Disabled» empties the key and deletes mover.cron, a schedule writes both
    $cfgQ = escapeshellarg("$tmp/share.cfg");
    $cronQ = escapeshellarg("$tmp/dynamix/mover.cron");
    $emcmd = function (string $body) use ($tmp) {
        file_put_contents("$tmp/emcmd", "#!/bin/bash\nprintf '%s\\n' \"\$1\" >> " . escapeshellarg("$tmp/emcmd.calls") . "\n$body\n");
        chmod("$tmp/emcmd", 0755);
    };
    $asUnraid = 'case "$1" in shareMoverSchedule=\&*) sed -i \'s/^shareMoverSchedule=.*/shareMoverSchedule=""/\' ' . $cfgQ . '; rm -f ' . $cronQ . ' ;; '
        . 'shareMoverSchedule=40%203%20%2A%20%2A%20%2A\&*) sed -i \'s/^shareMoverSchedule=.*/shareMoverSchedule="40 3 * * *"/\' ' . $cfgQ
        . '; printf \'# Generated mover schedule:\n40 3 * * * /usr/local/sbin/mover start > /dev/null\n\' > ' . $cronQ . ' ;; esac; exit 0';
    $emcmd($asUnraid);
    $daily = function () use ($tmp, &$v) {
        file_put_contents("$tmp/share.cfg", "shareMoverSchedule=\"40 3 * * *\"\nshareMoverLogging=\"yes\"\n");
        file_put_contents("$tmp/dynamix/mover.cron", "40 3 * * * /usr/local/sbin/mover start > /dev/null\n");
        $v['own'] = ['set' => '40 3 * * *', 'cron' => '40 3 * * *'];
    };
    $err = function (callable $f) { try { $f(); return 'ok'; } catch (Problem $p) { return [$p->key, $p->params]; } };

    // the note: the first schedule only, «Disabled» never
    moverelliUnraidNoteKeep('', 'no', $dir);
    $n0 = moverelliUnraidNote($dir);
    moverelliUnraidNoteKeep('0 */4 * * *', 'no', $dir);
    moverelliUnraidNoteKeep('40 3 * * *', 'yes', $dir);
    same('unraid mover: noted once — «Disabled» never, the first schedule stays', [null, '0 */4 * * *', 'no'], [$n0, moverelliUnraidNote($dir)['was'] ?? null, moverelliUnraidNote($dir)['logging'] ?? null]);
    @unlink("$dir/" . MOVERELLI_UNRAID_NOTE);

    // her save: Unraid's schedule on — refused without the consent, nothing written, nothing sent
    $daily();
    $set = moverelliTestSettings(['patterns' => ['*.nfo']]);
    same('unraid mover: her save while Unraid\'s schedule is on, no consent — refused with its schedule, nothing written, emcmd not run',
        [['moverelli_mover_consent', ['schedule' => '40 3 * * *']], false, []], [$err(fn () => moverelliSave($set, $h)), file_exists("$dir/smart_mover.ini"), $calls()]);
    $r = moverelliSave($set, $h, null, true);
    same('unraid mover: with the consent — Unraid\'s form «Disabled» once (logging kept), then her settings written; said so',
        [['shareMoverSchedule=&shareMoverLogging=yes&changeMover=Apply'], true, true, ['set' => '', 'cron' => null]],
        [$calls(), file_exists("$dir/smart_mover.ini"), $r['mover_off'] ?? null, jackMoverOwn(jackMoverHost())]);
    same('unraid mover: … what it was noted for her let-go', ['40 3 * * *', 'yes'], [moverelliUnraidNote($dir)['was'] ?? null, moverelliUnraidNote($dir)['logging'] ?? null]);
    $v['own'] = ['set' => '', 'cron' => null];
    same('unraid mover: off already — saved without asking, nothing sent', [false, []], [moverelliSave($set, $h)['mover_off'] ?? null, $calls()]);
    $daily();
    $emcmd('exit 0');
    $was = (string) file_get_contents("$dir/smart_mover.ini");
    file_put_contents("$dir/smart_mover.ini", $was . "\n");
    same('unraid mover: emhttpd changed nothing — refused (her words), her settings not written', [['moverelli_mover_off_failed'], "$was\n"],
        [array_slice((array) $err(fn () => moverelliSave(moverelliTestSettings(), $h, null, true)), 0, 1), file_get_contents("$dir/smart_mover.ini")]);
    $calls();
    $emcmd($asUnraid);
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/moverelli.php') . file_get_contents(OFFICE_DIR . '/agent/desks/moverelli-import.php');
    check('unraid mover: the save action and the import\'s apply carry the consent (mover_off exactly true)',
        str_contains($src, "moverelliSave(\$r['settings'] ?? null, null, null, moverelliConsent(\$r))") && str_contains($src, "}, moverelliConsent(\$r));")
        && moverelliConsent(['mover_off' => true]) && !moverelliConsent([]) && $err(fn () => moverelliConsent(['mover_off' => 'yes']))[0] === 'bad_request');
    check('unraid mover: never a hand-written cron line — only Unraid\'s form', !str_contains((string) file_get_contents(OFFICE_DIR . '/agent/desks/moverelli-unraid.php'), 'mover.cron"'));

    // her let-go: refused while Jack is hired — nothing changed
    officeJobSetSchedule('moverelli', '0 4 * * *', "$tmp/office.cron", false);
    file_put_contents("$tmp/share.cfg", "shareMoverSchedule=\"\"\nshareMoverLogging=\"yes\"\n");
    @unlink("$tmp/dynamix/mover.cron");
    $v['own'] = ['set' => '', 'cron' => null];
    $v['jack_desk'] = ['lists' => ['/x/l.txt'], 'shares' => ['Filme']];
    $l = moverelliLetGoLook($h);
    same('unraid mover: her let-go look with Jack hired — he is named, her schedule, Unraid\'s comes back', [true, '0 4 * * *', ['off' => true, 'back' => '40 3 * * *']],
        [$l['jack'], $l['schedule'], $l['unraid']]);
    same('unraid mover: her let-go with Jack hired — refused, her schedule stays, Unraid\'s stays off, nothing sent', [['moverelli_jack_hired', []], '0 4 * * *', '', []],
        [$err(fn () => moverelliLetGo(['confirm' => true], $h)), officeJobSchedule('moverelli', "$tmp/office.cron")['custom'], jackMoverOwn(jackMoverHost())['set'], $calls()]);
    $v['jack_desk'] = null;
    same('unraid mover: without confirm — refused', ['bad_request', []], $err(fn () => moverelliLetGo([], $h)));
    $r = moverelliLetGo(['confirm' => true], $h);
    same('unraid mover: her let-go — her schedule off, Unraid\'s back through its form (the value URL-encoded), looked at, the note gone',
        [true, ['back' => true, 'was' => '40 3 * * *'], ['shareMoverSchedule=40%203%20%2A%20%2A%20%2A&shareMoverLogging=yes&changeMover=Apply'], null, ['set' => '40 3 * * *', 'cron' => '40 3 * * *'], null],
        [$r['schedule_off'], $r['unraid'], $calls(), officeJobSchedule('moverelli', "$tmp/office.cron")['custom'] ?? null, jackMoverOwn(jackMoverHost()), moverelliUnraidNote($dir)]);
    same('unraid mover: let go again — nothing noted, nothing sent', [false, ['none' => true], []], [moverelliLetGo(['confirm' => true], $h)['schedule_off'], moverelliLetGo(['confirm' => true], $h)['unraid'], $calls()]);
    moverelliUnraidNoteKeep('40 3 * * *', 'yes', $dir);
    file_put_contents("$tmp/share.cfg", "shareMoverSchedule=\"0 */6 * * *\"\n");
    file_put_contents("$tmp/dynamix/mover.cron", "0 */6 * * * /usr/local/sbin/mover start > /dev/null\n");
    same('unraid mover: a schedule set by hand meanwhile — kept, the note gone, nothing sent', [['kept' => true, 'schedule' => '0 */6 * * *'], null, []],
        [moverelliUnraidBack(jackMoverHost(), $dir), moverelliUnraidNote($dir), $calls()]);
    file_put_contents("$tmp/share.cfg", "shareMoverSchedule=\"\"\n");
    @unlink("$tmp/dynamix/mover.cron");
    file_put_contents("$dir/" . MOVERELLI_UNRAID_NOTE, json_encode(['v' => 1, 'was' => '40 3 * * *&cmdStartMover=1', 'logging' => 'no', 'at' => 1]));
    $e = $err(fn () => moverelliUnraidBack(jackMoverHost(), $dir));
    same('unraid mover: a noted value of a shape Unraid\'s form never makes — refused, nothing sent', ['moverelli_unraid_back_failed', []], [$e[0] ?? null, $calls()]);
    foreach (['40 3 * * *', '0 */4 * * *', '5 2 * * 0', '0 1 15 * *'] as $ok) {
        check("unraid mover: the form's shape «{$ok}» is sent", (bool) preg_match(MOVERELLI_UNRAID_CRON, $ok));
    }
    file_put_contents("$dir/" . MOVERELLI_UNRAID_NOTE, json_encode(['v' => 1, 'was' => '40 3 * * *', 'logging' => 'yes', 'at' => 1]));
    $emcmd('exit 0');
    $waited = [];
    $r = moverelliLetGo(['confirm' => true], $h);
    same('unraid mover: emhttpd changed nothing — looked again up to 3 s, said, the note kept for another try', ['moverelli_unraid_back_failed', 10, '40 3 * * *'],
        [$r['unraid']['error']['key'] ?? null, count($waited), moverelliUnraidNote($dir)['was'] ?? null]);
    $calls();
    @unlink("$dir/" . MOVERELLI_UNRAID_NOTE);
    unset($GLOBALS['jackMoverHost']);

    // D1: EmbyCache's list in her ini before EmbyCache's first run — no real run (said once, never notified), a Team Lead hint
    $list = "$tmp/emby/mediacache_exclude.txt";
    @mkdir("$tmp/emby", 0700, true);
    $v['jack_lists'] = [$list, '/mnt/user/appdata/x/mediacache_exclude.txt'];
    $v['jack_ran'] = false;
    $v['own'] = ['set' => '', 'cron' => null];
    moverelliSave(moverelliTestSettings(['files' => [$list]]), $h);
