/**
 * The pool, only X (agent/lib/poollevel.php, 2026-10-14 — replaces the halves of 1.62): the numbers (fixed, Jack Emby,
 * the others, what must go, never, jack_over) and the keys older readers still get; her rule from her ini; the look from
 * ZFS; what Jack is told (100 − X, only what was watched); her save (X only), her state, the Team Lead's findings
 * (pool_never_moves against X, pool_snapshots, night_schedule); a fill that missed its target told at once; Smart Mover
 * without the cake's hooks and without a cap from the office; the migrations `pool-simple` and `pool-x`; her setup's
 * sentence, the next night and the warnings under node.
 */
/**
 * The node stand-in for his setup's page (tests of Jack Streamer's «Set up» tab): Office as far as desk.js uses it — the
 * section switcher records its picks, dialogs and posts are kept, an answer per action (globalThis.answers).
 */
function streamerTabHarness(): string
{
    return <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const all = (n, out = []) => { out.push(n); (n.children || []).forEach((c) => c && typeof c === 'object' && all(c, out)); return out; };
const el = (tag, cls, text) => { const n = { tag, className: cls || '', textContent: text == null ? '' : String(text), children: [], dataset: {}, style: {}, hidden: false, attrs: {},
  classList: { add(...c) { n.className += ' ' + c.join(' '); }, toggle() {} }, appendChild(c) { n.children.push(c); return c; }, append(...c) { n.children.push(...c.filter((x) => typeof x === 'object')); },
  replaceChildren() { n.children = []; }, replaceWith() {}, closest: () => null, setAttribute(k, v) { n.attrs[k] = v; }, addEventListener() {}, querySelectorAll: () => [],
  querySelector: (q) => (q === 'input' ? n.children.find((c) => c.tag === 'input') || null : null), focus() {}, options: [] }; return n; };
const posts = [];
const toasts = [];
const dialogs = [];
const picks = [];
let active = '';
globalThis.answers = {};
globalThis.Option = function Option(text, value) { this.text = text; this.value = value; };
globalThis.Office = { scope: () => T, t: T, el, fmt: { size: (b) => Math.round(b / 1073741824) + ' GB', relative: () => 'now', date: (t) => 'D' + t, number: (n) => String(n) },
  desk: () => {}, places: () => {}, placesFrom: () => {}, store: () => null, agent: { running: true }, place: () => {}, stat: (o) => ({ stat: o }),
  sectionHead: (t, s) => el('div', 'section-head', t), pageHelp: () => el('div'), go: () => {},
  sections: () => ({ el: el('div'), places: () => [], mount: () => false, render() {}, row() {}, active: () => active, pick(id, how) { picks.push([id, how]); active = active === id ? '' : id; } }),
  filterBar: () => ({}), subroute: () => {}, toast: (t, bad) => toasts.push([t, !!bad]), errorText: (e) => 'E:' + (e && e.key),
  api: { post: async (a, d) => { posts.push([a, d]); return globalThis.answers[a] || { ok: true }; } },
  dialog: (o) => { const d = { o, closed: false, setTitle() {}, close() { if (d.closed) return; d.closed = true; if (o.onClose) o.onClose(); } }; dialogs.push(d); return d; } };
const [emFile, stateFile, connectFile] = process.argv.slice(2);
(0, eval)(fs.readFileSync(emFile, 'utf8'));
const e = OFFICE_DESK_TESTS.jack;
const st = JSON.parse(fs.readFileSync(stateFile, 'utf8'));
Object.values(st.jobs || {}).forEach((j) => { j.running = false; });      // no run going (the demo shows one)
const con = connectFile ? JSON.parse(fs.readFileSync(connectFile, 'utf8')) : null;
const texts = (n) => all(n).map((x) => x.textContent).filter(Boolean);
/** the form connected to the canned server, every library chosen, its folders mapped as the container has them */
const connect = () => { const f = e.form(); Object.assign(f.instances[0], { url: 'http://x', server: con.server, libraries: con.libraries, users: con.users, connectedAs: `${f.instances[0].type}|http://x|` });
  con.libraries.forEach((l) => { f.chosenLibs.add(l.name); l.locations.forEach((p) => { f.instances[0].mappings[p] = (st.emby[0].mounts || {})[p] || '/mnt/user' + p; }); }); return f; };
JS;
}

/** Run a streamerTabHarness() script under node: its JSON answer, or null with the output in a failed check */
function streamerTabRun(string $name, string $script, array $args): ?array
{
    $node = testsNode();
    if ($node === '') {
        check("$name: node is missing here - skipped", true);
        return null;
    }
    $tmp = hardeningTmp('streamer-tab');
    file_put_contents("$tmp/t.js", streamerTabHarness() . "\n" . $script);
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . implode(' ', array_map('escapeshellarg', $args)) . ' 2>&1');
    hardeningRm($tmp);
    $r = json_decode($raw, true);
    if (!is_array($r)) {
        check("$name: ran under node", false, substr($raw, 0, 2000));
        return null;
    }
    return $r;
}

/**
 * Jack Streamer's «Set up» tab (2026-10-14, the owner: the modal wizard and the pool simulator went — back to the office's
 * standard tab with tiles, budget mode only, clear sentences instead of a simulator). The parts as tiles in order (server,
 * libraries and shares, amount, people, more, and — once set up — the import); the wizard's step routes lead to the tile
 * that holds them now; Emby, Jellyfin and Plex (1.65.0); the import offered in the server's part before he is set
 * up; the amount: a budget in GB (required), no mode, the rule in sentences with Ms. Moverelli's X; «Save» connects a
 * server first when its address or key is new (a failure: no save, the server's part shown); saving writes budget mode
 * only — nothing of the wizard (N days, create_share_root, number_episodes).
 */
/**
 * Jack Streamer's run list names who started a run (`by` in his job info: office, schedule, letgo, night) — every one has
 * its words in all five languages (1.65.1: «jack.by.night» showed raw on a real server since the joint night run).
 */
function testJackByWords(): void
{
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/jack.php');
    preg_match_all("/'(night|letgo|office|schedule)'/", (string) (preg_match('/\$by = in_array\(.*?;/s', $src, $m) ? $m[0] : ''), $b);
    $bys = array_values(array_unique($b[1]));
    same('jack by-words: the writers of `by` found', ['night', 'letgo', 'office', 'schedule'], $bys);
    $miss = [];
    foreach (['de', 'en', 'fr', 'it', 'es'] as $l) {
        $words = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/jack/lang/$l.json"), true) ?: [];
        foreach ($bys as $by) {
            if (!isset($words["by.$by"])) $miss[] = "$l:by.$by";
        }
    }
    same('jack by-words: every «by» of the run list has its words in all five languages', [], $miss);
}

/**
 * No run happens «at night» (the owner, 2026-10-16: a run is on schedule or started by hand — «night» is wrong, above all
 * for Jack Streamer): the texts of the desks that run things or talk about runs carry no night word in any language. Only
 * the Night Watchman keeps the night — his name inside another desk's text is taken out first, and his night shift's own
 * key is excepted by name; placeholders ({night}, {nights}) are code names.
 */
function testNoNightWords(): void
{
    $words = ['de' => '/nacht|nächtlich/iu', 'en' => '/night/iu', 'fr' => '/nuit|nocturne/iu', 'it' => '/notte|nottur/iu', 'es' => '/noche|nocturn|madrugada/iu'];
    $except = ['caretaker' => ['partner.night']];     // «night shift»: the Night Watchman's while the array is stopped
    $hits = [];
    foreach (['moverelli', 'jack', 'advisor', 'restore', 'caretaker', 'cleanup', 'backup', 'snapshot', 'logs'] as $desk) {
        foreach ($words as $l => $re) {
            $name = mb_strtolower((string) (langFile(OFFICE_WEB . "/desks/watchman/lang/$l.json")['name'] ?? ''));
            $name = preg_replace('/^(der|the|le|il|el)\s+/u', '', $name);
            foreach (langFile(OFFICE_WEB . "/desks/$desk/lang/$l.json") as $k => $v) {
                foreach ((array) $v as $text) {
                    $text = str_replace($name, '', mb_strtolower(preg_replace('/\{[a-z_]+\}/', '', (string) $text)));
                    if (!in_array($k, $except[$desk] ?? [], true) && preg_match($re, $text)) {
                        $hits[] = "$desk/$l $k";
                    }
                }
            }
        }
    }
    same('texts: no run happens «at night» — on schedule or started here; only the Night Watchman keeps the night', [], $hits);
    check('texts: … his name was found in all five languages (else nothing of him would be taken out)',
        count(array_filter(array_keys($words), fn ($l) => mb_strlen((string) (langFile(OFFICE_WEB . "/desks/watchman/lang/$l.json")['name'] ?? '')) > 4)) === 5);
}

