    $j = json_decode(trim((string) $out), true) ?? [];
    same('level page: the same numbers as the agent — fixed 300, Jack 250, the others 350, 100 must go', [300, 250, 350, 100, false, false], $j['math'] ?? $err);
    same('level page: the next night in her words — about 100 of the oldest; nothing but the age', ['setup.level_night_goes {"pool":"cache","goes":"100 GiB"}',
        'setup.level_night_none {"pool":"cache"}'], $j['night'] ?? null);
    same('level page: her rule with X (Jack Emby hired: his unwatched stays), the pool, the next night; a pool not looked at said', [
        'setup.level_rule_jack {"x":80}', 'setup.level_pool {"pool":"cache","used":"900 GiB","size":"1000 GiB","nm":"300 GiB"} setup.level_night_goes {"pool":"cache","goes":"100 GiB"}',
        'setup.level_unseen {"pool":"fast"}'], $j['section'] ?? null);
    check('level page: X 30 — what never moves above X: said, red', in_array('setup.level_never {"pool":"cache","nm":30,"x":30}', $j['never'] ?? [], true), json_encode($j['never'] ?? null));
    check('level page: X 50 — what never moves and Jack Emby\'s 250 over it: his budget too big, said', in_array('setup.level_jack_over {"pool":"cache","jack":"250 GiB","x":50}', $j['jackOver'] ?? [], true),
        json_encode($j['jackOver'] ?? null));
    same('level page: no limit — by age only; Jack not hired — her rule without him', [['setup.level_off'], 'setup.level_rule {"x":80}'], [$j['off'] ?? null, $j['alone'][0] ?? null]);
    hardeningRm($tmp);
}

/**
 * Jack Emby yields (2026-10-13, the pool simply; office blocks in EmbyCache): free space on ZFS is the whole pool (the path's
 * dataset from /proc/mounts, the pool's used + avail, the dataset's avail — a quota counts). A stand-in Emby — Mutter
 * resumes «Serie» S01E01 (E02–E05 follow, 1–4 ahead), Vater has S01E03 next up (E04, E05 follow: shared with Mutter, each
 * counted once at its nearest rank), the Kids resume «Brazil»; 1000 bytes each, the pool 10000 (a ZFS stand-in that
 * counts what lies on it). The office tells him 100 − Y free and his half (MEDIACACHE_KEEP_BYTES): he fills round-robin
 * by everyone's next up to Y (borrowing), the rest waits; over Y he gives back the farthest ahead first, what is started
 * last, what plays never — never below his half; under Y nothing; what was watched first; standalone as before; the
 * words in the log, the status, the live panel and his page.
 */
function testJackYield(): void
{
    [$exit] = run(['python3', '--version'], 10);
    if ($exit !== 0) {
        check('emby yield: python3 is missing here - skipped', true);
        return;
    }
    $tmp = hardeningTmp('jack-zfs');
    // ZFS: the pool master 7000 + 3000, the share's dataset sees refer 500 + the pool's avail; a quota'd dataset 100 avail
    @mkdir("$tmp/z/pool/Filme", 0700, true);
    @mkdir("$tmp/z/plain", 0700, true);
    file_put_contents("$tmp/z/mounts", "master $tmp/z/pool zfs rw 0 0\nmaster/Filme $tmp/z/pool/Filme zfs rw 0 0\nmaster/Quota $tmp/z/pool/Quota zfs rw 0 0\n/dev/x $tmp/z/plain ext4 rw 0 0\n");
    @mkdir("$tmp/z/pool/Quota", 0700, true);
    file_put_contents("$tmp/z/zfs", "#!/bin/bash\ncase \"\${@: -1}\" in master) echo '7000 3000';; master/Filme) echo '500 3000';; master/Quota) echo '50 100';; *) exit 1;; esac\n");
    chmod("$tmp/z/zfs", 0755);
    $py = 'import sys; sys.path.insert(0, sys.argv[1]); import mediacache_lib as l; '
        . 'print(round(l.free_percent_after(sys.argv[2] + "/pool/Filme", 0), 1), round(l.free_percent_after(sys.argv[2] + "/pool", 1000), 1), '
        . 'round(l.free_percent_after(sys.argv[2] + "/pool/Quota", 0), 1), l.pool_usage(sys.argv[2] + "/plain")[0] > 0)';
    [, $out, $err] = runEnv(['python3', '-c', $py, OFFICE_DIR . '/mediacache', "$tmp/z"], ['MEDIACACHE_ZFS' => "$tmp/z/zfs", 'MEDIACACHE_MOUNTS' => "$tmp/z/mounts",
        'MEDIACACHE_DIR' => "$tmp/z", 'PYTHONDONTWRITEBYTECODE' => '1', 'PATH' => getenv('PATH')], 30);
    same('emby zfs: a share\'s dataset — the whole pool 30 % free (not refer+avail: 86 %); 1000 bytes more → 20 %; a quota\'d dataset 1 %; not ZFS — statvfs',
        '30.0 20.0 1.0 True', trim((string) $out), $err);

    hardeningRm($tmp);

    $tmp = hardeningTmp('jack-rank');
    $p = "$tmp/py";
    // the shares' folders on the pool there already (MediaCache makes a missing one itself only on a real ZFS pool the share may use)
    foreach (["$p/data", "$p/pool/Filme", "$p/pool/Serien", "$p/user0/Filme/Brazil", "$p/user0/Serien/Serie", "$p/user/Filme", "$p/user/Serien", "$p/shares"] as $d) {
        @mkdir($d, 0700, true);
    }
    for ($e = 1; $e <= 5; $e++) {
        file_put_contents("$p/user0/Serien/Serie/S01E0$e.mkv", str_repeat((string) $e, 1000));
    }
    file_put_contents("$p/user0/Filme/Brazil/Brazil.mkv", str_repeat('b', 1000));
    file_put_contents("$p/playing", '');
    file_put_contents("$p/emby.py", <<<'PY'
import http.server, json, sys, urllib.parse
NAMES = ["Eins", "Zwei", "Drei", "Vier", "Fünf"]
EPS = [{"Type": "Episode", "Id": f"e{i}", "Name": NAMES[i - 1], "SeriesId": "s1", "SeriesName": "Serie", "ParentIndexNumber": 1,
        "IndexNumber": i, "Path": f"/media/tv/Serie/S01E0{i}.mkv"} for i in range(1, 6)]
BRAZIL = {"Type": "Movie", "Id": "m2", "Name": "Brazil", "Path": "/media/movies/Brazil/Brazil.mkv"}
class H(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        u = urllib.parse.urlparse(self.path)
        q = urllib.parse.parse_qs(u.query)
        kind = (q.get("IncludeItemTypes") or [""])[0]
        if u.path == "/Users":
            body = [{"Id": "u1", "Name": "Mutter"}, {"Id": "u2", "Name": "Vater"}, {"Id": "u3", "Name": "Kids"}]
        elif u.path == "/Sessions":
            playing = open(sys.argv[2]).read().strip()
            body = [{"UserName": "Kids", "NowPlayingItem": {"Path": playing}}] if playing else []
        elif u.path.endswith("/Items/Resume"):
            uid = u.path.split("/")[2]
            body = {"Items": ([EPS[0]] if uid == "u1" and kind == "Episode" else [BRAZIL] if uid == "u3" and kind == "Movie" else [])}
        elif u.path == "/Shows/NextUp":
            body = {"Items": [EPS[2]] if q.get("UserId") == ["u2"] else []}
        elif q.get("ParentId") == ["s1"]:
            body = {"Items": EPS}
        else:
            body = {"Items": []}
        b = json.dumps(body).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)
    def log_message(self, *a):
        pass
s = http.server.HTTPServer(("127.0.0.1", 0), H)
open(sys.argv[1] + ".tmp", "w").write(str(s.server_address[1]))
import os; os.replace(sys.argv[1] + ".tmp", sys.argv[1])
s.serve_forever()
PY);
    $emby = proc_open(['python3', "$p/emby.py", "$p/port", "$p/playing"], [0 => ['file', '/dev/null', 'r'], 1 => ['file', '/dev/null', 'w'], 2 => ['file', "$p/emby.err", 'w']], $pipes);
    for ($i = 0; $i < 50 && !is_file("$p/port"); $i++) {
        usleep(100000);
    }
    $port = (int) @file_get_contents("$p/port");
    $settings = fn (int $minFree) => file_put_contents("$p/data/mediacache_settings.json", json_encode(['cache_path' => "$p/pool", 'array_path' => "$p/user0",
        'user_path' => "$p/user", 'array_disks_glob' => "$p/disk[0-9]*", 'cleanup_tool' => 'rsync', 'fill_tool' => 'rsync', 'return_to_origin' => true,
        'shares_cfg_dir' => "$p/shares", 'create_share_root' => true, 'api_timeout' => 3, 'min_free_percent' => $minFree, 'max_resume_movies' => 10,
        'max_resume_series' => 10, 'max_favorite_series' => 0, 'use_next_up' => true, 'number_episodes' => 4,
        'instances' => [['servername' => 'Test', 'url' => "http://127.0.0.1:$port", 'api_key' => 'k',
                         'path_mappings' => ['/media/movies' => "$p/user/Filme", '/media/tv' => "$p/user/Serien"]]]], JSON_UNESCAPED_SLASHES));
    // the ZFS stand-in: the pool «master» at $p/pool, 10000 bytes; used = a base (appdata & co., downloads) + what lies on it
    file_put_contents("$p/mounts", "master $p/pool zfs rw 0 0\n");
    file_put_contents("$p/zfs", "#!/bin/bash\nu=\$(( \$(cat " . escapeshellarg("$p/base") . ") + \$(find " . escapeshellarg("$p/pool") . " -type f -printf '%s\\n' | awk '{s+=\$1} END {print s+0}') ))\necho \"\$u \$(( 10000 - u ))\"\n");
    chmod("$p/zfs", 0755);
    // a run as the office starts it: Ms. Moverelli's Y as 100 − Y free, his half as the floor (null: none); $office false: standalone
    $go = function (int $y, int $base, ?string $keep = null, bool $office = true, bool $noFill = false, bool $watched = false) use ($p, $settings): array {
        $settings(100 - $y);
        file_put_contents("$p/base", (string) $base);
        @unlink("$p/data/status.json");
        $cmd = ['env', 'PATH=' . getenv('PATH'), "MEDIACACHE_DIR=$p/data", "MEDIACACHE_RESULT=$p/data/status.json", 'MEDIACACHE_FILL_TOOL=rsync',
                'MEDIACACHE_CLEANUP_TOOL=rsync', 'PYTHONDONTWRITEBYTECODE=1', "MEDIACACHE_PROGRESS=$p/data/progress.json", "MEDIACACHE_MOUNTS=$p/mounts", "MEDIACACHE_ZFS=$p/zfs"];
        if ($office) {
            $cmd[] = 'MEDIACACHE_GIVE_BACK_FREE=1';
        }
        if ($keep !== null) {
            $cmd[] = "MEDIACACHE_KEEP_BYTES=$keep";
        }
        if ($noFill) {
            $cmd[] = 'MEDIACACHE_NO_FILL=1';
        }
        if ($watched) {
            $cmd[] = 'MEDIACACHE_WATCHED_ONLY=1';
        }
        [$exit, $out, $err] = run(array_merge($cmd, ['python3', OFFICE_DIR . '/mediacache/mediacache_run.py', '--run']), 120);
        $log = (string) @file_get_contents("$p/data/logs/mediacache.log");
        @unlink("$p/data/logs/mediacache.log");
        return [$exit, readJson("$p/data/status.json") ?? [], $out . $err . $log];
    };
    $on = function () use ($p): array {
        $l = array_map(fn ($f) => basename($f, '.mkv'), array_merge(glob("$p/pool/Serien/Serie/*.mkv") ?: [], glob("$p/pool/Filme/*/*.mkv") ?: []));
        sort($l);
        return $l;
    };
    $back = function (string $out): array {
        preg_match_all('/\[ZURÜCK: Rang\] \S+\/(\w+)\.mkv/u', $out, $m);
        return array_values(array_unique($m[1]));     // the console and the log file
    };
    $copied = function (string $out): array {
        preg_match_all('/^.*\d+ B\s+\S+\/(\w+)\.mkv$/mu', $out, $m);
        return $m[1];
    };

    // the night run's freeing pass (MEDIACACHE_NO_FILL=1): nothing fetched, what waits counted (all six of everyone's queue)
    [$exit, $st, $out] = $go(50, 2000, null, true, true);
    same('emby no fill: the freeing pass — nothing fetched, the six queued files counted as waiting, said', [0, [], 6, 6000, 0, true],
        [$exit, $on(), $st['pool']['waiting'] ?? null, $st['pool']['waiting_bytes'] ?? null, $st['fill']['planned'] ?? null, str_contains($out, 'MEDIACACHE_NO_FILL')], $out);
    [$exit, $st, $out] = $go(50, 2000);
    same('emby yield: Y 50 %, appdata & co. 2000 — round-robin by everyone\'s next (Mutter E01, Vater E03, Kids Brazil) up to Y, the rest waits (counted)',
        [0, ['Brazil', 'S01E01', 'S01E03'], ['S01E01', 'S01E03', 'Brazil'], 3], [$exit, $on(), array_values(array_unique($copied($out))), $st['pool']['waiting'] ?? null], $out);
    [$exit, $st, $out] = $go(80, 2000);
    same('emby yield: Y 80 % — he borrows the rest, nearest first (E02, E04, E05)', [['Brazil', 'S01E01', 'S01E02', 'S01E03', 'S01E04', 'S01E05'], ['S01E02', 'S01E04', 'S01E05']],
        [$on(), array_values(array_unique($copied($out)))], $out);
    [$exit, $st, $out] = $go(55, 2000);
    same('emby yield: Y down to 55 % (pool at 80 %) — back until 45 % free, the farthest ahead first: E05 (3 ahead for Vater), E04, then Mutter\'s E02 (she has the most) before the shared E03',
        [0, ['S01E05', 'S01E04', 'S01E02'], ['Brazil', 'S01E01', 'S01E03']], [$exit, $back($out), $on()], $out);
    check('emby yield: … said in words (the nearest watcher first) and with the limit', str_contains($out, 'Gebe zurück: Serie – S01E05 Fünf (Folge 3 voraus, Vater, Mutter)')
        && str_contains($out, 'Gebe zurück: Serie – S01E02 Zwei (als Nächstes, Mutter)') && str_contains($out, 'Zu wenig frei auf dem Pool: 20.0 %') && str_contains($out, 'bis 45 % frei'), $out);
    same('emby yield: … the status names them in order, for his page; what he holds and his floor (none)', [3, [['Serie – S01E05 Fünf', 3, 'Vater, Mutter'], ['Serie – S01E04 Vier', 2, 'Vater, Mutter'], ['Serie – S01E02 Zwei', 1, 'Mutter']], 3000, null],
        [$st['give_back']['files'] ?? null, array_map(fn ($w) => [$w['title'], $w['ahead'], $w['who']], $st['give_back']['items'] ?? []), $st['pool']['held'] ?? null, array_key_exists('keep', $st['pool'] ?? []) ? $st['pool']['keep'] : 'x']);
    [$exit, $st, $out] = $go(51, 2000);
    same('emby yield: only above Y — Y 51 %, the pool at 50 %: nothing goes back, nothing more fills', [0, [], ['Brazil', 'S01E01', 'S01E03']], [$exit, $back($out), $on()], $out);
    // what was watched always goes back first (the owner): old.mkv (400, no one's any more) on the pool and the list — 54 % full,
    // but the cleanup frees 400 → 50 % free: no ranked give-back, only old.mkv goes
    @mkdir("$p/pool/Filme/Old", 0700, true);
    file_put_contents("$p/pool/Filme/Old/old.mkv", str_repeat('o', 400));
    file_put_contents("$p/data/mediacache_exclude.txt", "$p/pool/Filme/Old/old.mkv\n", FILE_APPEND);
    [$exit, $st, $out] = $go(50, 2000);
    same('emby yield: watched files alone bring the pool under Y — no ranked give-back, the watched one back on the array',
        [0, [], ['Brazil', 'S01E01', 'S01E03'], false, true], [$exit, $back($out), $on(), is_file("$p/pool/Filme/Old/old.mkv"), is_file("$p/user0/Filme/Old/old.mkv")], $out);
    [$exit, $st, $out] = $go(45, 2000, null, false);
    same('emby yield: standalone (no MEDIACACHE_GIVE_BACK_FREE) over its limit — nothing goes back, min_free only stops filling (as before)',
        [0, [], ['Brazil', 'S01E01', 'S01E03'], false, false], [$exit, $back($out), $on(), isset($st['give_back']), isset($st['pool'])], $out);
    [$exit, $st, $out] = $go(45, 2000, '3000');
    same('emby yield: his half 3000, he holds 3000 — over Y, but nothing goes back (said)', [0, [], ['Brazil', 'S01E01', 'S01E03'], 3000],
        [$exit, $back($out), $on(), $st['pool']['keep'] ?? null], $out);
    check('emby yield: … said: my half stays', str_contains($out, 'meine Hälfte ist') && str_contains($out, 'nichts geht zurück'), $out);
    [$exit, $st, $out] = $go(30, 2000, '2500');
    same('emby yield: Y 30 % (2000 short), his half 2500 — back only down to it: the next up E03 (500 over his half) before what is started',
        [0, ['S01E03'], ['Brazil', 'S01E01'], 2000], [$exit, $back($out), $on(), $st['pool']['held'] ?? null], $out);
    check('emby yield: … said with the floor', str_contains($out, 'meine Hälfte (2.4 KiB) bleibt') || str_contains($out, 'meine Hälfte ('), $out);
    // only X (2026-10-14): MEDIACACHE_WATCHED_ONLY — over the limit, nothing goes back by rank (GIVE_BACK_FREE set or not); what
    // he holds and what waits still in the status; the progress file keeps the files done (`recent`)
    [$exit, $st, $out] = $go(30, 2000, null, true, true, true);
    same('emby watched only: over the limit (Y 30 %), nothing back by rank, nothing fetched; his pool status written all the same', [0, [], ['Brazil', 'S01E01'], 2000, true],
        [$exit, $back($out), $on(), $st['pool']['held'] ?? null, isset($st['pool']['waiting_bytes'])], $out);
    same('emby watched only: … the progress keeps `recent` (a list)', true, is_array((readJson("$p/data/progress.json") ?? [])['recent'] ?? null));
    file_put_contents("$p/playing", '/media/movies/Brazil/Brazil.mkv');
    [$exit, $st, $out] = $go(10, 2000);
    same('emby yield: Y 10 %, no floor — both started ones would go, Brazil plays and stays', [0, ['S01E01'], ['Brazil']], [$exit, $back($out), $on()], $out);
    check('emby yield: … the one playing said', str_contains($out, '[BLEIBT: läuft gerade] Filme/Brazil/Brazil.mkv'), $out);
    [$exit, $out, $err] = run(['env', 'PATH=' . getenv('PATH'), "MEDIACACHE_DIR=$p/data", 'MEDIACACHE_KEEP_BYTES=12T', 'PYTHONDONTWRITEBYTECODE=1', 'python3', OFFICE_DIR . '/mediacache/mediacache_run.py'], 60);
    check('emby yield: a floor that is no number — refused, nothing done', $exit !== 0 && str_contains($out . $err, 'MEDIACACHE_KEEP_BYTES'), $out . $err);
    proc_terminate($emby);
    proc_close($emby);

    same('emby yield: the office launches EmbyCache with the free-% give-back on', '1', jackPyEnv()['MEDIACACHE_GIVE_BACK_FREE'] ?? null);
    // the live panel's file going back and his page's words — in their shape
    file_put_contents("$tmp/progress.json", json_encode(['v' => 1, 'phase' => 'back', 'started' => 1, 'updated' => 2, 'back' => ['files' => 1, 'bytes' => 9],
        'users' => [], 'current' => ['phase' => 'back', 'rel' => 'Serien/S/E10.mkv', 'size' => 9, 'target' => '/x', 'since' => 2,
        'why' => ['title' => "S – S01E10\x01", 'ahead' => 10, 'who' => 'Mutter']]]));
    $pr = jackProgressRead("$tmp/progress.json");
    same('emby yield: the progress file — why it goes back, in its shape', ['title' => 'S – S01E10 ', 'ahead' => 10, 'who' => 'Mutter'], $pr['current']['why'] ?? null);
    same('emby yield: … the view passes it on; nonsense is none', [10, null, null],
        [jackProgressView($pr, [], 3)['current']['why']['ahead'] ?? null, jackGiveBackWhy(['title' => 'x', 'ahead' => -1]), jackGiveBackWhy(['ahead' => 2])]);
    same('emby yield: the status list for his page', ['files' => 4, 'items' => [['title' => 'A', 'ahead' => 0, 'who' => '']]],
        jackGiveBackList(['give_back' => ['files' => 4, 'items' => [['title' => 'A', 'ahead' => 0], 'junk']]]));
    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('emby yield: page - node is missing here - skipped', true);
        hardeningRm($tmp);
        return;
    }
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const mk = (tag, cls, text) => ({ tag, cls, text, textContent: text == null ? '' : String(text), children: [], hidden: false, disabled: false, dataset: {}, style: {},
  append(...c) { this.children.push(...c); }, appendChild(c) { this.children.push(c); return c; }, setAttribute() {}, scrollIntoView() {} });
globalThis.document = { createTextNode: (t) => t };
globalThis.Office = { sections: (o) => ({ spec: o, el: {}, active: () => '', note: () => ({ tile: '' }), places: () => [], mount: () => false, pick() {}, render() {}, clear() {} }), scope: () => T, t: T, el: mk, fmt: { size: (b) => b + ' B', duration: (s) => 'dur' + s, time: (t) => 'T' + t, date: (t) => 'D' + t, number: (n) => String(n) },
  desk: () => {}, places: () => {}, placesFrom: () => {}, store: () => null, agent: { running: true }, place: (k, n) => n, go: () => {} };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const e = OFFICE_DESK_TESTS.jack;
const texts = (n) => (typeof n === 'string' ? [n] : [n.textContent, ...n.children.flatMap(texts)].filter(Boolean));
const out = {};
out.items = [{ title: 'S – E10', ahead: 10, who: 'Mutter' }, { title: 'S – E2', ahead: 1, who: 'Vater' }, { title: 'Brazil', ahead: 0, who: '' }].map(e.rankItem);
out.file = texts(e.progFile({ phase: 'back', rel: 'Serien/S/E10.mkv', size: 9, done: 0, why: { title: 'S – E10', ahead: 10, who: 'Mutter' } }));
const items = [1, 2, 3, 4].map((n) => ({ title: 'T' + n, ahead: n, who: 'M' }));
e.setState({ pool: { keep: 100, held: 50, waiting: 0, back: 0, moverelli: { x: 80, y: 70 }, min_free: 30, given_back: { files: 4, items } } });
out.more = e.roomWords();
e.setState({ pool: { keep: 100, held: 50, waiting: 0, back: 0, moverelli: { x: 80, y: 70 }, min_free: 30, given_back: { files: 1, items: items.slice(0, 1) } } });
out.one = e.roomWords();
console.log(JSON.stringify(out));
JS);
    [, $out, $err] = run([$node, "$tmp/t.js", OFFICE_WEB . '/desks/jack/desk.js'], 30);
    $j = json_decode(trim((string) $out), true) ?? [];
    same('emby yield: the words — n ahead, next up, started (no one named: just that)', [
        'rank.item {"title":"S – E10","why":"rank.who {\"what\":\"rank.ahead {\\\\\"n\\\\\":10}\",\"who\":\"Mutter\"}"}',
        'rank.item {"title":"S – E2","why":"rank.who {\"what\":\"rank.next\",\"who\":\"Vater\"}"}',
        'rank.item {"title":"Brazil","why":"rank.started"}'], $j['items'] ?? $err);
    check('emby yield: the live panel — «Giving back: …» under the file', (bool) preg_grep('/^progress\.giveback .*S – E10/', $j['file'] ?? []), json_encode($j['file'] ?? null));
    check('emby yield: his page — the last run\'s give-back, three named and «and 1 more»; one alone', str_starts_with(end($j['more']) ?: '', 'room.gave_back_more')
        && str_ends_with(end($j['more']), '"n":1}') && str_starts_with(end($j['one']) ?: '', 'room.gave_back {'), json_encode($j));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $lang = readJson(OFFICE_WEB . "/desks/jack/lang/$l.json") ?? [];
        check("emby yield: lang $l has the words", count(array_intersect_key($lang, array_flip(['progress.giveback', 'rank.started', 'rank.next', 'rank.ahead', 'rank.who', 'rank.item', 'room.gave_back', 'room.gave_back_more']))) === 8);
    }
    hardeningRm($tmp);
}

/**
 * Ms. Moverelli's stops and her run card (2026-10-12): with CUSTOMMOVER_STOP Smart Mover hands Unraid's move binary one
 * file at a time — «Stop after this file»: the next file never starts; «Stop at once» (the stop file with now, the move
 * binary TERMed like Unraid's own «mover stop»): the file in flight stays at its source, the partial copy it left at its
 * destination is removed, never one that was there before, nothing when the source is gone; Unraid's mover starting
 * while she runs: always at once (the owner's decision), by hand or by its schedule; the live status's fields; the
 * kill tree; her card under node (steps, bar, file, time left from two readings, the buttons).
 */
function testMoverelliStop(): void
{
    $tmp = hardeningTmp('moverelli-stop');
    $v = [];
    moverelliFixture($tmp, $v);
    $h = moverelliHost();
    $dir = "$tmp/data";
    moverelliSave(moverelliTestSettings(), $h);
    foreach (['c2.txt', 'c3.txt'] as $f) {
        file_put_contents("$tmp/mnt/cache/Docs/$f", "docs-$f");
    }
    $hist = fn () => moverelliHistory($dir)[0] ?? [];
    // stop after this file: the stand-in asks to stop after its first file — the next file never starts
    $GLOBALS['moverelliHost']['env']['MOVE_STOP'] = "$dir/office-stop.json";
    $GLOBALS['moverelliHost']['env']['MOVE_SNAP'] = "$tmp/snap.json";
    $exit = moverelliJob(['run', '--office'], moverelliHost());
    unset($GLOBALS['moverelliHost']['env']['MOVE_STOP'], $GLOBALS['moverelliHost']['env']['MOVE_SNAP']);
    $st = readJson("$dir/status.json") ?? [];
    same('stop after this file: exit 3, stopped after Back\'s one file (Docs and Filme never started), why user, the file named',
        [3, 'stopped', 'Docs', true, 3, true, 'user', "$tmp/mnt/disk1/Back/d.txt"],
        [$exit, $st['result'] ?? null, $st['stop_share'] ?? null, is_file("$tmp/mnt/cache/Back/d.txt"), count(glob("$tmp/mnt/cache/Docs/*")), is_file("$tmp/mnt/cache/Filme/A/a.mkv"),
         $hist()['why'] ?? null, $hist()['stop_file'] ?? null]);
    $snap = readJson("$tmp/snap.json") ?? [];
    same('live status: while the run goes — running, the plan, the phase, the share and file in flight, its counts, the run\'s counts', [
        'running', ['Back', 'Docs', 'Filme'], 'share', 'Back', "$tmp/mnt/disk1/Back/d.txt", 1, 4, 0, 0, 0, 0],
        [$snap['result'] ?? null, $snap['plan'] ?? null, $snap['phase'] ?? null, $snap['share'] ?? null, $snap['file'] ?? null, $snap['share_files'] ?? null,
         $snap['share_bytes'] ?? null, $snap['share_done_files'] ?? null, $snap['share_done_bytes'] ?? null, $snap['done_files'] ?? null, $snap['done_bytes'] ?? null]);

    // the same share, a stop after the second of three files: two moved, the third never handed over (nothing «left») —
    // the stand-in counts the paths it is given and asks to stop while the second moves (2026-10-18: one move binary for
    // the share's files, as Unraid's own mover feeds it)
    file_put_contents("$tmp/mnt/cache/Docs/c1.txt", 'docs-c1');
    $calls = "$tmp/calls";
    file_put_contents("$tmp/bin/move2", "#!/bin/bash\nwhile IFS= read -r f; do\n  n=\$(( \$(cat " . escapeshellarg($calls) . " 2>/dev/null || echo 0) + 1 )); echo \$n > " . escapeshellarg($calls)
        . "\n  [[ \$n -eq 2 ]] && printf '{\"why\":\"user\"}' > " . escapeshellarg("$dir/office-stop.json") . "\n  printf '%s\\n' \"\$f\" | " . escapeshellarg("$tmp/bin/move") . "\ndone\nexit 0\n");
    chmod("$tmp/bin/move2", 0755);
    $GLOBALS['moverelliHost']['env']['CUSTOMMOVER_MOVER_BIN'] = "$tmp/bin/move2";
    $exit = moverelliJob(['run', '--office'], moverelliHost());
    $st = readJson("$dir/status.json") ?? [];
    $docs = array_values(array_filter($st['shares'] ?? [], fn ($x) => $x['share'] === 'Docs'))[0] ?? [];
    same('stop after this file: Docs\' second of four files the last — 2 handed over and moved, the other two never started: «left» (stopped)',
        [3, 'Docs', 2, 2, 2, 2], [$exit, $st['stop_share'] ?? null, (int) trim((string) @file_get_contents($calls)), count(glob("$tmp/mnt/cache/Docs/*")), $docs['left'] ?? null, $docs['moved'] ?? null]);
    $GLOBALS['moverelliHost']['env']['CUSTOMMOVER_MOVER_BIN'] = "$tmp/bin/move";

    // a leftover .partial (a power cut during Unraid's move) is removed at the start of a real run — only while its source
    // still exists, only on an awake disk of the share, never a file under its final name (disk1 awake, disk2 asleep in
    // the tests' own disks.ini)
    file_put_contents("$tmp/disks.ini", "[\"disk1\"]\nname=\"disk1\"\nspundown=\"0\"\n[\"disk2\"]\nname=\"disk2\"\nspundown=\"1\"\n");
    $GLOBALS['disksIni'] = "$tmp/disks.ini";
    $last = basename(glob("$tmp/mnt/cache/Docs/*.txt")[0]);
    @mkdir("$tmp/mnt/disk1/Docs", 0700, true);
    @mkdir("$tmp/mnt/disk2/Docs", 0700, true);
    file_put_contents("$tmp/mnt/disk1/Docs/$last.partial", 'par');
    file_put_contents("$tmp/mnt/disk1/Docs/gone.txt.partial", 'par');          // its source is gone: not ours to judge
    file_put_contents("$tmp/mnt/disk2/Docs/$last.partial", 'par');            // a sleeping disk: never looked at
    file_put_contents("$tmp/mnt/disk1/Docs/keep.txt", 'final');               // a final name: never touched
    $GLOBALS['moverelliHost']['env']['MOVE_FAIL'] = '1';                       // nothing moves: the cleanup alone is seen
    moverelliJob(['run', '--office'], moverelliHost());
    unset($GLOBALS['moverelliHost']['env']['MOVE_FAIL']);
    $log = (string) file_get_contents("$dir/smart_mover.log");
    same('leftover .partial: removed on the awake disk while its source is there; the one without a source, the sleeping disk\'s and a final name kept',
        [false, true, true, true], [file_exists("$tmp/mnt/disk1/Docs/$last.partial"), is_file("$tmp/mnt/disk1/Docs/gone.txt.partial"),
         is_file("$tmp/mnt/disk2/Docs/$last.partial"), is_file("$tmp/mnt/disk1/Docs/keep.txt")]);
    check('leftover .partial: said in her log, no word of a stop at once', str_contains($log, "removed a leftover partial copy $tmp/mnt/disk1/Docs/$last.partial – its file is still at $tmp/mnt/cache/Docs/$last")
        && !str_contains($log, 'stopped at once') && !str_contains($log, 'nothing removed'), $log);
    foreach (["disk1/Docs/gone.txt.partial", "disk2/Docs/$last.partial", 'disk1/Docs/keep.txt'] as $f) {
        @unlink("$tmp/mnt/$f");
    }
    // R2 2026-10-15: inside the night a stop asked while her job starts (the job takes her old stop file away) still holds —
    // the night's stop file asks again: nothing moved, stopped
    $before = count(glob("$tmp/mnt/cache/Docs/*"));
    writeAtomic("$dir/night-stop.json", jsonEncode(['time' => time(), 'why' => 'user']), 0600, 0, 0);
    $exit = moverelliJob(['run', '--night', '--solo'], moverelliHost());
    @unlink("$dir/night-stop.json");
    same('night stop at her start: the night\'s stop file holds for her job — stopped (3), nothing of Docs moved', [3, 'stopped', $before],
        [$exit, (readJson("$dir/status.json") ?? [])['result'] ?? null, count(glob("$tmp/mnt/cache/Docs/*"))]);
    // Tower 7.4 lab (2026-10-16): her fill's cap became the night's target ($room) but one line still asked for $cap — a PHP
    // warning after every real run, and inside a measured night her own «target missed» beside the night's
    $warned = [];
    set_error_handler(function (int $no, string $msg) use (&$warned): bool { $warned[] = $msg; return true; }, E_WARNING);
    $GLOBALS['moverelliHost']['env']['MOVE_FAIL'] = '1';
    moverelliJob(['run', '--office'], moverelliHost());
    moverelliJob(['run', '--night', '--solo', '--fill-until=1', '--fill-pool=cache'], moverelliHost());
    unset($GLOBALS['moverelliHost']['env']['MOVE_FAIL']);
    restore_error_handler();
    same('her real run (by the office, inside the night with a target): no undefined variable', [],
        array_values(array_filter($warned, fn ($m) => str_contains($m, 'Undefined variable'))));
    unset($GLOBALS['disksIni']);
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/moverelli.php');
    check('no harder stop (Unraid\'s move catches TERM and finishes its file): no stop_now action, no kill', !str_contains($src, "'stop_now'") && !str_contains($src, 'moverelliKillMove')
        && !str_contains($src, 'moverelliStopNow'));
    same('her poll: no run — not real, nothing', [false, null, null], [moverelliProgressState($h)['real'], moverelliProgressState($h)['stopping'], moverelliProgressState($h)['progress']]);
    // the file in flight measured by its growing .partial (Unraid's move goes through shfs: nothing in /proc io) — its
    // ALLOCATED size, only on the share's awake destinations, the path strictly from the source's
    file_put_contents("$tmp/mnt/cache/Docs/big.bin", str_repeat('b', 300000));
    @mkdir("$tmp/mnt/disk2/Docs", 0700, true);
    file_put_contents("$tmp/mnt/disk2/Docs/big.bin.partial", str_repeat('p', 50000));
    $hf = ['asleep' => ['disk2' => true]] + moverelliHost();
    $p0 = ['phase' => 'share', 'share' => 'Docs', 'file' => "$tmp/mnt/cache/Docs/big.bin"];
    same('in flight: the partial only on a sleeping disk — not looked at; the source\'s own size known; the move waits for the disk', ['file_bytes' => 0, 'file_size' => 300000, 'waking' => true], moverelliInFlight($p0, $hf));
    $hf['asleep'] = [];
    $alloc = (int) (stat("$tmp/mnt/disk2/Docs/big.bin.partial")['blocks'] * 512);
    same('in flight: … awake — its allocated bytes (never above the source), the source\'s size', ['file_bytes' => min($alloc, 300000), 'file_size' => 300000], moverelliInFlight($p0, $hf));
    same('in flight: a path outside the share, «..» in it, not moving — nothing', array_fill(0, 3, ['file_bytes' => 0, 'file_size' => null]),
        [moverelliInFlight(['file' => "/etc/passwd"] + $p0, $hf), moverelliInFlight(['file' => "$tmp/mnt/cache/Docs/../Docs/big.bin"] + $p0, $hf), moverelliInFlight(['phase' => 'look'] + $p0, $hf)]);
    @unlink("$tmp/mnt/disk2/Docs/big.bin.partial");
    @unlink("$tmp/mnt/cache/Docs/big.bin");

    // Unraid's mover starts while she runs: after the file in flight — the stop file with why and by what, no kill
    $stop = "$tmp/watch-stop.json";
    $null = [0 => ['file', '/dev/null', 'r'], 1 => ['file', '/dev/null', 'w'], 2 => ['file', '/dev/null', 'w']];
    foreach ([[true, 'hand'], [false, 'schedule']] as [$off, $by]) {
        @unlink($stop);
        $p = proc_open(['bash', '-c', 'while [ ! -e "$1" ]; do sleep 0.1; done; exit 3', 'x', $stop], $null, $pipes);
        $r = moverelliRunWatch($p, $stop, fn () => true, 0, fn () => $off);
        same("mover started ($by): stopped after the file — why mover, by $by, the stop file without now", [3, 'mover', $by, false, $by],
            [$r['exit'], $r['why'], $r['by'], isset((readJson($stop) ?? [])['now']), (readJson($stop) ?? [])['by'] ?? null]);
    }
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/moverelli.php');
    check('mover started: «by hand» = Unraid\'s own schedule off', str_contains($src, "(int) \$h['look_every'],\n            fn (): bool => jackMoverScheduleOff((\$h['unraid'])()), \$arrayStopping);"));
    $sh = (string) file_get_contents(OFFICE_DIR . '/smartmover/custommover_run.sh');
    check('smart mover: one file at a time only with CUSTOMMOVER_STOP (the office); without it the share\'s list at once, as upstream',
        str_contains($sh, "if [[ -n \"\$STOP_FILE\" ]]; then\n        # office: one file at a time") && str_contains($sh, "printf '%s\\n' \"\${FILES[@]}\" | \"\${MOVER_CMD[@]}\" >\"\$mover_out\" 2>&1"));

    // her card under node: the steps, the bar by bytes, the file, the time left from two readings, the end on the last share
    $node = testsNode();
    if ($node === '') {
        check('run card: node is missing here - skipped', true);
    } else {
        file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const mk = (tag, cls, text) => ({ tag, cls, className: cls, text, textContent: text == null ? '' : String(text), children: [], hidden: false, disabled: false, dataset: {}, style: {},
  append(...c) { this.children.push(...c); }, appendChild(c) { this.children.push(c); return c; }, insertBefore(c) { this.children.unshift(c); }, setAttribute() {} });
globalThis.document = { createTextNode: (t) => t };
const dialogs = [];
const posts = [];
globalThis.Office = { sections: () => ({ el: {}, render() {}, mount: () => false, places: () => [], active: () => '' }), scope: () => T, t: T, el: mk,
  fmt: { cron: (c) => c, size: (b) => b + ' B', date: (t) => 'D' + t, time: (t) => 'T' + t, duration: (s) => Math.round(s) + 's', relative: (t) => 'R' + t },
  desk: () => {}, places: () => {}, placesFrom: () => {}, store: () => null, agent: { running: true }, place: (k, n) => n, go: () => {}, errorText: (e) => 'err:' + e.key,
  dialog: (o) => { dialogs.push(o); return { buttons: [] }; }, toast: () => {}, selbar: () => null,
  api: { post: async (a, b) => { posts.push([a, b]); return { ok: true }; } } };
(0, eval)(fs.readFileSync(process.argv[3], 'utf8'));
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const m = OFFICE_DESK_TESTS.moverelli;
const texts = (n) => (typeof n === 'string' ? [n] : [n.text, ...n.children.flatMap(texts)].filter(Boolean));
const p = (done) => ({ result: 'running', started: 1000, plan: ['Back', 'Docs'], phase: 'share', share: 'Docs', file: '/mnt/cache/Docs/c2.txt',
  share_files: 4, share_bytes: 1000, share_done_files: 1, share_done_bytes: done, done_files: 3, done_bytes: done + 300, shares: [{ share: 'Back' }] });
const out = {};
const d0 = m.runCardData(p(200), 2000);
out.steps = d0.steps.map((s) => [s.name, s.state]);
out.first = [d0.at, d0.percent, d0.left, d0.end, d0.estimating];
const fl = m.runCardData({ ...p(200), file_bytes: 300, file_size: 500, started: 7 }, 2000);
m.runCardData({ ...p(200), file_bytes: 400, file_size: 500, started: 7 }, 2010);
const fl2 = m.runCardData({ ...p(200), file_bytes: 500, file_size: 500, started: 7 }, 2020);
out.flight = [fl.dBytes, fl.percent, fl2.dBytes, fl2.fileBytes, fl2.fileSize, fl2.fileRate];
out.waking = texts(m.runCard({ ...p(200), file_bytes: 0, file_size: 500, waking: true, started: 8 }, 2040)).filter((x) => /^rc\.(waking|file|on_way)/.test(x));
out.flightCard = texts(m.runCard({ ...p(200), file_bytes: 500, file_size: 500, started: 7 }, 2030));
const d2 = m.runCardData(p(400), 2060);
out.rate = [d2.percent, d2.rate, d2.left, d2.end];
const look = m.runCardData({ result: 'running', started: 5, plan: ['Back'], phase: 'look', shares: [] }, 2020);
out.look = [look.at, look.percent, look.steps.map((s) => s.state)];
m.setProgress(p(400), null);
const card = m.runCard(p(400), 2030);
out.card = texts(card);
out.cls = card.cls;
const foot = card.children[card.children.length - 1];
const right = foot.children[1];
out.foot = [foot.cls, foot.children[0].text, right.cls, right.children.map((b) => [b.tag, b.cls, b.text, b.disabled])];
out.head = m.headActions().map((b) => b.text);
m.setProgress(p(400), 'user');
const c2 = m.runCard(p(400), 2030);
const f2 = c2.children[c2.children.length - 1];
out.stopping = [texts(c2.children[0]), f2.children[1].children[1].disabled];
(async () => {
  right.children[1].onclick();
  await new Promise((r) => setTimeout(r, 0));
  out.posts = posts.map((x) => x[0]);
  console.log(JSON.stringify(out));
})();
JS);
        $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/moverelli/desk.js') . ' ' . escapeshellarg(testsRunHelpersJs($tmp)) . ' 2>&1');
        $o = json_decode($raw, true);
        check('run card: ran under node', is_array($o), $raw);
        $o = is_array($o) ? $o : [];
        same('run card: the steps — Looking around, a step per share of the run, Tidying up; Back done, Docs running', [['rc.look', 'done'], ['Back', 'done'], ['Docs', 'running'], ['Docs' === '' ? '' : 'rc.tidy', 'pending']],
            $o['steps'] ?? null);
        same('run card: the first reading — the time left still estimated (Back moved before: since this page saw Docs): the bar as far as the further of files (1 of 4: 25 %) and bytes (20 %), no end', [2, 25, null, null, true], $o['first'] ?? null);
        same('run card: the file in flight counts with its .partial — 200 + 300 = 50 %; the file\'s own 10 B/s from the readings', [500, 50, 700, 500, 500, 10], $o['flight'] ?? null);
        same('run card: no .partial yet, the target disk asleep — «The target disk is waking up …» under the file', ['rc.on_way {"file":"c2.txt (rc.file_bytes {\\"done\\":\\"0 B\\",\\"size\\":\\"500 B\\"})","from":"pic.pool_name {\\"pool\\":\\"cache\\"}","to":"pic.array"}', 'rc.waking'],
            $o['waking'] ?? null);
        check('run card: … the rate in the bar\'s words like Mr. Backupsy\'s partner line, the file\'s bytes beside it',
            (bool) preg_grep('/^\d+ % · rc\.rate_avg \{"rate":"[0-9.]+ B"\}/', $o['flightCard'] ?? []) && (bool) preg_grep('/^rc\.on_way \{"file":"c2\.txt \(rc\.file_bytes \{\\\\"done\\\\":\\\\"500 B\\\\",\\\\"size\\\\":\\\\"500 B\\\\"\}\)",.* · rc\.rate \{"rate":"10 B"\}$/', $o['flightCard'] ?? []), json_encode($o['flightCard'] ?? null));
        // the percent: the share's time done by the same model — 1 × 0.06 + 400 ÷ 3.33 = 120.06 s of 120.06 + 180.18: 39 %
        same('run card: a minute after this page first saw Docs, 200 B more — Ø 200/60 B/s; files × time per file + bytes ÷ bandwidth: no file done yet — 3 × 0.06 s (the prior) + 600 B ÷ 3.33 B/s = 180.18 s, the end at 2240.18; 39 % of the time done', [39, 200 / 60, 180.18, 2240.18],
            [$o['rate'][0] ?? null, $o['rate'][1] ?? null, isset($o['rate'][2]) ? round($o['rate'][2], 6) : null, isset($o['rate'][3]) ? round($o['rate'][3], 6) : null]);
        same('run card: looking around — the first step, no bar', [0, null, ['running', 'pending', 'pending']], $o['look'] ?? null);
        check('run card: its title, the steps, «39 % · about … left», the share\'s counts, the file in flight, the end',
            in_array('rc.title', $o['card'] ?? [], true) && (bool) preg_grep('/^39 % · rc\.rate_avg \{"rate":"[0-9.]+ B"\} · rc\.left/', $o['card'] ?? []) && (bool) preg_grep('/^rc\.share \{"share":"Docs","done":1/', $o['card'] ?? [])
            && in_array('rc.on_way {"file":"c2.txt","from":"pic.pool_name {\\"pool\\":\\"cache\\"}","to":"pic.array"}', $o['card'] ?? [], true) && (bool) preg_grep('/^rc\.end/', $o['card'] ?? []), json_encode($o['card'] ?? null));
        same('run card: the foot — «N errors, N warnings» left (as Mr. Backupsy\'s); right, in Jack Emby\'s order and style: «Log» as a quiet link, «Stop after this file»; no harder stop',
            ['card-foot mo-run-foot', 'rc.counts {"errors":"count.errors {\\"n\\":0}","warnings":"count.warnings {\\"n\\":0}"}', 'mo-run-right',
             [['button', 'mo-link', 'rc.show_log', false], ['button', 'btn small plain', 'stop', false]]], $o['foot'] ?? null);
        same('run card: … the head keeps no stop of its own', true, !in_array('stop', $o['head'] ?? ['stop'], true) && !in_array('stop_now', $o['head'] ?? [], true));
        same('run card: stopping after the file — said, «Stop after this file» off', [['rc.title', 'stopping'], true],
            [array_slice($o['stopping'][0] ?? [], 0, 2), $o['stopping'][1] ?? null]);
        same('run card: «Stop after this file» asks moverelli.stop', ['moverelli.stop'], $o['posts'] ?? null);
    }
    unset($GLOBALS['moverelliHost']);
    hardeningRm($tmp);
}

/**
 * D-F8 (scenario M6, 2026-10-19): Unraid's ⟦Stop⟧ while her real run moves — the run cut short (1079 of 3000 moved) read
 * «ok» in her history. Now: she looks at var.ini's fsState (every 2 s at most) while she runs and stops after the file in
 * flight once the array is being stopped (her stop file, why array — as Unraid stops its own mover at ⟦Stop⟧); a run that
 * ends otherwise while the array goes (Smart Mover killed, its move binary refused) is «stopped», why array, never «ok»;
 * Smart Mover killed by TERM says so (exit 143, «failed») instead of its EXIT trap's «ok» ($? of the last command).
 */
function testMoverelliArrayStop(): void
{
    $tmp = hardeningTmp('moverelli-arraystop');
    $v = [];
    moverelliFixture($tmp, $v);
    $h = moverelliHost();
    $dir = "$tmp/data";
    moverelliSave(moverelliTestSettings(), $h);
    foreach (['c2.txt', 'c3.txt', 'c4.txt'] as $f) {
        file_put_contents("$tmp/mnt/cache/Docs/$f", "docs-$f");
    }
    $hist = fn () => moverelliHistory($dir)[0] ?? [];
    $var = "$tmp/var.ini";
    // the array goes while she moves: the stand-in sets fsState «Stopping» at its first file, takes ~0.6 s per file
    file_put_contents("$tmp/bin/move-stopping", "#!/bin/bash\nwhile IFS= read -r f; do\n  printf 'fsState=\"Stopping\"\\n' > " . escapeshellarg($var)
        . "\n  printf '%s\\n' \"\$f\" | " . escapeshellarg("$tmp/bin/move") . "\n  sleep 0.6\ndone\nexit 0\n");
    chmod("$tmp/bin/move-stopping", 0755);
    $GLOBALS['moverelliHost']['env']['CUSTOMMOVER_MOVER_BIN'] = "$tmp/bin/move-stopping";
    $exit = moverelliJob(['run', '--office'], moverelliHost());
    $st = readJson("$dir/status.json") ?? [];
    same('array stop: she stops after the file in flight — exit 3, stopped, why array, some of Docs still on cache',
        [3, 'stopped', 'stopped', 'array', true], [$exit, $st['result'] ?? null, $hist()['result'] ?? null, $hist()['why'] ?? null, count(glob("$tmp/mnt/cache/Docs/*")) > 0]);
    check('array stop: said in the office\'s log', str_contains((string) @file_get_contents(AGENT_LOG), "Ms. Moverelli: the array is being stopped — she stops after the file in flight"));
    // Smart Mover killed by TERM (its EXIT trap saw $? = 0 and wrote «ok»): the array still started — failed, never ok
    file_put_contents($var, "fsState=\"Started\"\n");
    file_put_contents("$tmp/bin/move-term", "#!/bin/bash\nkill -TERM \$PPID\nsleep 0.3\nexit 0\n");
    chmod("$tmp/bin/move-term", 0755);
    $GLOBALS['moverelliHost']['env']['CUSTOMMOVER_MOVER_BIN'] = "$tmp/bin/move-term";
    $exit = moverelliJob(['run', '--office'], moverelliHost());
    usleep(600000);                                          // the move binary in flight (holding Smart Mover's lock) ends
    $st = readJson("$dir/status.json") ?? [];
    same('TERM: Smart Mover says it — exit 143, failed (its status and her history), never ok', [143, 'failed', 143, 'failed'],
        [$exit, $st['result'] ?? null, $st['exit'] ?? null, $hist()['result'] ?? null]);
    // … killed while the array is being stopped: stopped, why array
    file_put_contents("$tmp/bin/move-term", "#!/bin/bash\nprintf 'fsState=\"Stopping\"\\n' > " . escapeshellarg($var) . "\nkill -TERM \$PPID\nsleep 0.3\nexit 0\n");
    moverelliJob(['run', '--office'], moverelliHost());
    usleep(600000);
    same('TERM while the array is being stopped: stopped, why array', ['stopped', 'array'], [$hist()['result'] ?? null, $hist()['why'] ?? null]);
    // a run that ended «ok» with files left while the array goes (the move binary refused them, shfs gone): stopped, array
    file_put_contents($var, "fsState=\"Started\"\n");
    file_put_contents("$tmp/bin/move-gone", "#!/bin/bash\nprintf 'fsState=\"Stopping\"\\n' > " . escapeshellarg($var) . "\nwhile IFS= read -r f; do echo \"move: \$f No such file or directory\"; done\nexit 0\n");
