/** Her settings as the page sends them: Smart Mover's defaults, files and own lines per scope */
function moverelliTestSettings(array $global = [], array $shares = []): array
{
    return ['global' => $global + ['min_age' => 0, 'age_stat' => 'ctime', 'move_when_used_above' => 0, 'move_prefer_shares' => true, 'mover_debug' => 0,
                                   'max_list' => 50, 'files' => [], 'patterns' => []], 'shares' => $shares];
}

/** Unraid 7.3.2 and newer: fit below not, a pre-release of 7.3.2 not, a beta of a newer one yes; Unraid's schedule on → dry runs only */
/**
 * Smart Mover, a prefer share from the array (2026-10-18, seen on a real server: 436 GB that never moved): Unraid's move
 * binary moves nothing given as /mnt/user0/<share>/… (it says «No such file or directory» and exits 0), so the array side
 * is scanned and handed over per disk, /mnt/diskN/<share>, as Unraid's mover does — only the disks the share may use;
 * an exclude written as /mnt/user/<share>/… holds on every disk; ONE move binary for a share's files (not one per file),
 * a file done once its source is gone, «stop after this file» still after the file in flight; the folders left on the
 * array side go as with Unraid's mover (empty ones to the pool, the share's folder on a disk too); pool → array as before.
 */
function testMoverelliPreferDisks(): void
{
    $t = hardeningTmp('moverelli-prefer');
    $mk = function (string $rel, string $body = 'x') use ($t): void {
        @mkdir(dirname("$t/$rel"), 0700, true);
        file_put_contents("$t/$rel", $body);
    };
    $reset = function () use ($t, $mk): void {
        exec('rm -rf ' . escapeshellarg("$t/mnt") . ' ' . escapeshellarg("$t/log") . ' ' . escapeshellarg("$t/moved") . ' ' . escapeshellarg("$t/calls")
            . ' ' . escapeshellarg("$t/stop"));
        foreach (['mnt/cache/Pics', 'mnt/user/Pics', 'mnt/user/Docs', 'mnt/cache/Docs', 'mnt/disk1/Pics/emptydir/inner', 'shares', 'bin'] as $d) {
            @mkdir("$t/$d", 0700, true);
        }
        for ($i = 1; $i <= 40; $i++) {
            $mk(sprintf('mnt/disk1/Pics/a/%02d.jpg', $i), str_repeat('p', $i));
        }
        $mk('mnt/disk2/Pics/b/x.jpg');
        $mk('mnt/disk1/Pics/keep/k1.jpg');           // excluded as /mnt/user/Pics/keep: on every disk
        $mk('mnt/disk2/Pics/keep/k2.jpg');
        $mk('mnt/disk3/Pics/c.jpg');                  // disk3 is not the share's (shareExclude): never looked at
        $mk('mnt/user0/Pics/u.jpg');                  // what /mnt/user0 shows: never handed over
        $mk('mnt/cache/Docs/d.txt');                  // a yes share: pool → array, as before
    };
    $reset();
    file_put_contents("$t/shares/Pics.cfg", "shareUseCache=\"prefer\"\nshareCachePool=\"cache\"\nshareExclude=\"disk3\"\n");
    file_put_contents("$t/shares/Docs.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\n");
    file_put_contents("$t/excl.txt", "$t/mnt/user/Pics/keep\n");
    file_put_contents("$t/ini", "[GLOBAL]\nmin_age=0\nglobal_excludes=$t/excl.txt\n");
    file_put_contents("$t/bin/move", <<<'SH'
#!/bin/bash
# a stand-in for Unraid's move binary: a data disk → the pool, the pool → disk1; a folder created there, removed here
# when empty; anything else (/mnt/user0) «No such file or directory»; every start counted, every path noted
echo x >> "$MOVE_CALLS"
n=0
while IFS= read -r f; do
    printf '%s\n' "$f" >> "$MOVE_LOG"
    case "$f" in
        "$MOVE_ROOT"/cache/*) to="$MOVE_ROOT/disk1/${f#"$MOVE_ROOT"/cache/}" ;;
        "$MOVE_ROOT"/disk[0-9]*/*) r=${f#"$MOVE_ROOT"/disk}; to="$MOVE_ROOT/cache/${r#*/}" ;;
        *) echo "move: $f No such file or directory"; continue ;;
    esac
    if [[ -d "$f" && ! -L "$f" ]]; then mkdir -p "$to" && rmdir "$f" 2>/dev/null; continue; fi
    (( ++n == ${MOVE_STOP_AT:-0} )) && printf '{"why":"user"}' > "$CUSTOMMOVER_STOP"
    mkdir -p "$(dirname "$to")" && mv "$f" "$to" && echo "move: $f Success"
done
exit 0
SH);
    chmod("$t/bin/move", 0755);
    $env = ['CUSTOMMOVER_INI' => "$t/ini", 'CUSTOMMOVER_SHARES_DIR' => "$t/shares", 'CUSTOMMOVER_MNT' => "$t/mnt", 'CUSTOMMOVER_LOG' => "$t/log",
            'CUSTOMMOVER_LOCK' => "$t/lock", 'CUSTOMMOVER_STATUS' => "$t/st.json", 'CUSTOMMOVER_ZFS' => '/nonexistent-zfs', 'CUSTOMMOVER_MOVER_BIN' => "$t/bin/move",
            'CUSTOMMOVER_STOP' => "$t/stop", 'CUSTOMMOVER_IGNORE_MOVER' => '1', 'MOVE_ROOT' => "$t/mnt", 'MOVE_LOG' => "$t/moved", 'MOVE_CALLS' => "$t/calls"];
    $sm = OFFICE_DIR . '/smartmover/custommover_run.sh';
    $handed = fn () => file_exists("$t/moved") ? file("$t/moved", FILE_IGNORE_NEW_LINES) : [];
    $calls = fn () => file_exists("$t/calls") ? count(file("$t/calls")) : 0;
    $share = fn (array $st, string $n) => array_values(array_filter($st['shares'] ?? [], fn ($x) => $x['share'] === $n))[0] ?? [];
    $on = fn (string $where) => count(glob("$t/mnt/$where") ?: []);

    // the dry run: the disks' paths, the excluded folder on neither disk, disk3 and /mnt/user0 never
    runEnv(['bash', $sm], $env, 60);
    $log = (string) file_get_contents("$t/log");
    same('prefer per disk: the dry run — 41 files from disk1 and disk2 (keep/ on neither), nothing handed over, nothing of disk3 or /mnt/user0',
        [41, 41, false, false, false, 0],
        [$share(readJson("$t/st.json") ?? [], 'Pics')['files'] ?? null, substr_count($log, "[DRY-RUN]     $t/mnt/disk1/Pics/") + substr_count($log, "[DRY-RUN]     $t/mnt/disk2/Pics/"),
         str_contains($log, '/keep/'), str_contains($log, "$t/mnt/disk3"), str_contains($log, '/user0/'), $calls()]);
    check('prefer per disk: … its source line names both disks', str_contains($log, "[Pics] array -> cache  (source: $t/mnt/disk1/Pics, $t/mnt/disk2/Pics)"), $log);

    // the real run
    [$exit] = runEnv(['bash', $sm, '--run'], $env, 60);
    $st = readJson("$t/st.json") ?? [];
    $pics = array_values(array_filter($handed(), fn ($l) => str_contains($l, '/Pics')));
    same('prefer per disk: the real run — exit 0, ok; Pics 41 moved, 0 left; all on the pool, keep/ on both disks; disk3 untouched',
        [0, 'ok', 'moved', 41, 0, 40, 1, 2, true, true],
        [$exit, $st['result'] ?? null, $share($st, 'Pics')['state'] ?? null, $share($st, 'Pics')['moved'] ?? null, $share($st, 'Pics')['left'] ?? null,
         $on('cache/Pics/a/*.jpg'), $on('cache/Pics/b/x.jpg'), $on('disk[12]/Pics/keep/*.jpg'), is_file("$t/mnt/disk3/Pics/c.jpg"), is_file("$t/mnt/user0/Pics/u.jpg")]);
    same('prefer per disk: … every path handed over is a disk\'s (never /mnt/user0, never disk3), none of keep/',
        [true, false, false, false],
        [count($pics) > 41 && count(array_filter($pics, fn ($l) => preg_match('#^' . preg_quote("$t/mnt/disk", '#') . '[12]/Pics(/|$)#', $l))) === count($pics),
         (bool) array_filter($handed(), fn ($l) => str_contains($l, '/user0/')), (bool) array_filter($handed(), fn ($l) => str_contains($l, '/disk3/')),
         (bool) array_filter($pics, fn ($l) => str_contains($l, '/keep'))]);
    same('prefer per disk: ONE move binary for the share\'s 41 files, one for its folders, two for Docs (its file, its emptied folder) — 4 in all (was one per file)', 4, $calls());
    same('prefer per disk: the folders as Unraid\'s mover leaves them — a/ and the empty ones gone from disk1, created on the pool; disk1/Pics (keep/) stays, disk2/Pics too',
        [false, false, true, true, true, true],
        [is_dir("$t/mnt/disk1/Pics/a"), is_dir("$t/mnt/disk1/Pics/emptydir"), is_dir("$t/mnt/cache/Pics/emptydir/inner"), is_dir("$t/mnt/disk1/Pics/keep"),
         is_dir("$t/mnt/disk1/Pics"), is_dir("$t/mnt/disk2/Pics")]);
    same('pool → array as before: Docs\' file handed over by its pool path, now on disk1; the share\'s emptied folder on the pool handed over too (gone), as with Unraid\'s mover',
        [true, true, true, false], [in_array("$t/mnt/cache/Docs/d.txt", $handed(), true), is_file("$t/mnt/disk1/Docs/d.txt"), in_array("$t/mnt/cache/Docs", $handed(), true), is_dir("$t/mnt/cache/Docs")]);
    $recent = array_column($st['recent'] ?? [], 'name');
    check('prefer per disk: the last files done named by share and the path below the disk', in_array('Pics/a/40.jpg', $recent, true) && in_array('Docs/d.txt', $recent, true),
        json_encode($recent));

    // stop after this file: asked while the 3rd file of Pics moves (Docs before it, alphabetically) — 3 moved, the 38 others never
    // handed over (left)
    $reset();
    [$exit] = runEnv(['bash', $sm, '--run'], $env + ['MOVE_STOP_AT' => '3'], 60);
    $st = readJson("$t/st.json") ?? [];
    same('prefer per disk: stop after the 3rd file — exit 3, stopped in Pics, 3 moved, 38 left, one move binary for Pics (and Docs\' two before), the last file named',
        [3, 'stopped', 'Pics', 3, 38, 3, 3, true, true],
        [$exit, $st['result'] ?? null, $st['stop_share'] ?? null, $share($st, 'Pics')['moved'] ?? null, $share($st, 'Pics')['left'] ?? null, $on('cache/Pics/a/*.jpg'), $calls(),
         is_file("$t/mnt/disk1/Docs/d.txt"), ($f = (string) ($st['stop_file'] ?? '')) !== '' && !file_exists($f) && is_file(str_replace("$t/mnt/disk1/", "$t/mnt/cache/", $f))]);
    same('prefer per disk: … after a stop no folder pass (only the empty parents of what moved), the rest stays on disk1', [true, 37],
        [is_dir("$t/mnt/disk1/Pics/emptydir"), $on('disk1/Pics/a/*.jpg')]);
    $picsHanded = array_values(array_filter($handed(), fn ($l) => str_contains($l, '/Pics/')));
    same('prefer per disk: … stop asked while file 3 is in flight — file 3 finishes (the last named), file 4 is never handed over: 3 paths of Pics given to the binary, all three moved',
        [3, ($st['stop_file'] ?? null), [true, true, true]],
        [count($picsHanded), $picsHanded[2] ?? null, array_map(fn ($l) => !file_exists($l), $picsHanded)]);

    // a share whose disks have no folder of it: nothing on the source side
    $reset();
    exec('rm -rf ' . escapeshellarg("$t/mnt/disk1/Pics") . ' ' . escapeshellarg("$t/mnt/disk2/Pics"));
    runEnv(['bash', $sm, '--run'], $env, 60);
    same('prefer per disk: no folder of the share on its disks — no_source, nothing handed over for it', ['no_source', []],
        [$share(readJson("$t/st.json") ?? [], 'Pics')['state'] ?? null, array_values(array_filter($handed(), fn ($l) => str_contains($l, '/Pics')))]);
    // the list never looks at a disk
    $reset();
    file_put_contents("$t/shares/Pics.cfg", "shareUseCache=\"prefer\"\nshareCachePool=\"cache\"\nshareInclude=\"disk2\"\n");
    [, $out] = runEnv(['bash', $sm, '--list-shares'], $env, 30);
    runEnv(['bash', $sm], $env, 60);
    $log = (string) file_get_contents("$t/log");
    same('prefer per disk: shareInclude=disk2 — only disk2 scanned (1 file), the list unchanged', [1, false, true],
        [$share(readJson("$t/st.json") ?? [], 'Pics')['files'] ?? null, str_contains($log, "$t/mnt/disk1/Pics"), str_contains($out, 'array -> cache')]);
    hardeningRm($t);
}

/**
 * Smart Mover, emptied folders (2026-10-19, scenarios on Tower): a yes run left the emptied parent uso-yes/m3 on the pool
 * once m3/a-small and m3/z-big were gone (upstream gave up on a parent the first time a sibling still held files), and a
 * stopped prefer run left the emptied disk1/uso-prefer on the array (no folder pass after a stop). Now every folder above
 * a moved file is looked at deepest first; never the share's root on the pool; a prefer share's folder on a disk only
 * when its copy is on the pool; a folder still holding something always stays. And folders empty BEFORE the run (a real
 * server: .tmp/, shares/counters/ left on the pool) go to the target as Unraid's mover takes them — in every direction,
 * never one an exclude keeps.
 */
function testMoverelliTidy(): void
{
    $t = hardeningTmp('moverelli-tidy');
    $mk = function (string $rel, string $body = 'x') use ($t): void {
        @mkdir(dirname("$t/$rel"), 0700, true);
        file_put_contents("$t/$rel", $body);
    };
    $reset = function () use ($t): void {
        exec('rm -rf ' . escapeshellarg("$t/mnt") . ' ' . escapeshellarg("$t/log") . ' ' . escapeshellarg("$t/stop") . ' ' . escapeshellarg("$t/dirs"));
        foreach (['mnt/user/Pics', 'mnt/user/Yes', 'mnt/cache/Pics', 'mnt/cache/Yes', 'shares', 'bin'] as $d) {
            @mkdir("$t/$d", 0700, true);
        }
    };
    $reset();
    file_put_contents("$t/bin/move", <<<'SH'
#!/bin/bash
# a stand-in for Unraid's move binary: a data disk → the pool, the pool → disk1, the second pool fast → the pool (the
# parents made there); a folder created there, removed here when empty; every folder handed over noted; the stop file written while the n-th file of a binary moves
n=0
while IFS= read -r f; do
    case "$f" in
        "$MOVE_ROOT"/cache/*) to="$MOVE_ROOT/disk1/${f#"$MOVE_ROOT"/cache/}" ;;
        "$MOVE_ROOT"/fast/*) to="$MOVE_ROOT/cache/${f#"$MOVE_ROOT"/fast/}" ;;
        "$MOVE_ROOT"/disk[0-9]*/*) r=${f#"$MOVE_ROOT"/disk}; to="$MOVE_ROOT/cache/${r#*/}" ;;
        *) continue ;;
    esac
    if [[ -d "$f" && ! -L "$f" ]]; then printf '%s\n' "$f" >> "$MOVE_DIRS"; mkdir -p "$to" && rmdir "$f" 2>/dev/null; continue; fi
    (( ++n == ${MOVE_STOP_AT:-0} )) && printf '{"why":"user"}' > "$CUSTOMMOVER_STOP"
    mkdir -p "$(dirname "$to")" && mv "$f" "$to"
done
exit 0
SH);
    chmod("$t/bin/move", 0755);
    file_put_contents("$t/excl.txt", "$t/mnt/user/Yes/m3/kept/k.bin\n");
    file_put_contents("$t/ini", "[GLOBAL]\nmin_age=0\n[Yes]\nexcludes=$t/excl.txt\n");
    $env = ['CUSTOMMOVER_INI' => "$t/ini", 'CUSTOMMOVER_SHARES_DIR' => "$t/shares", 'CUSTOMMOVER_MNT' => "$t/mnt", 'CUSTOMMOVER_LOG' => "$t/log",
            'CUSTOMMOVER_LOCK' => "$t/lock", 'CUSTOMMOVER_STATUS' => "$t/st.json", 'CUSTOMMOVER_ZFS' => '/nonexistent-zfs', 'CUSTOMMOVER_MOVER_BIN' => "$t/bin/move",
            'CUSTOMMOVER_STOP' => "$t/stop", 'CUSTOMMOVER_IGNORE_MOVER' => '1', 'MOVE_ROOT' => "$t/mnt", 'MOVE_DIRS' => "$t/dirs"];
    $sm = OFFICE_DIR . '/smartmover/custommover_run.sh';
    $share = fn (array $st, string $n) => array_values(array_filter($st['shares'] ?? [], fn ($x) => $x['share'] === $n))[0] ?? [];

    // a yes share: m3/a-small/… and m3/z-big/… go to the array — m3 emptied goes too, the share's folder on the pool stays;
    // m3/deep/1/2/f.bin: the whole chain; m4/kept holds an excluded file: m4/kept and m4 stay, m4/gone goes
    $reset();
    file_put_contents("$t/shares/Yes.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\n");
    foreach (['m3/a-small/1.bin', 'm3/a-small/2.bin', 'm3/z-big/1.bin', 'm3/deep/1/2/f.bin', 'm4/gone/g.bin', 'm4/kept/k.bin'] as $f) {
        $mk("mnt/cache/Yes/$f");
    }
    // folders empty before the run (a real server: .tmp/, shares/counters/ left on the pool): e1, e2/e3 to the array;
    // keepdir (her exclude) stays, so does the share's folder
    foreach (['e1', 'e2/e3', 'keepdir'] as $d) {
        @mkdir("$t/mnt/cache/Yes/$d", 0700, true);
    }
    file_put_contents("$t/excl.txt", "$t/mnt/user/Yes/m4/kept/k.bin\n$t/mnt/user/Yes/keepdir\n");
    [$exit] = runEnv(['bash', $sm, '--run'], $env, 60);
    $st = readJson("$t/st.json") ?? [];
    same('tidy, a yes run: exit 0, 5 moved — the emptied m3 (and m3/deep/1/2 up to it) gone from the pool, the share\'s folder kept',
        [0, 5, false, false, true, 5],
        [$exit, $share($st, 'Yes')['moved'] ?? null, is_dir("$t/mnt/cache/Yes/m3"), is_dir("$t/mnt/cache/Yes/m3/deep"), is_dir("$t/mnt/cache/Yes"),
         count(glob("$t/mnt/disk1/Yes/m3/*/*.bin") ?: []) + count(glob("$t/mnt/disk1/Yes/m3/deep/1/2/*.bin") ?: []) + count(glob("$t/mnt/disk1/Yes/m4/gone/*.bin") ?: [])]);
    same('tidy, a yes run: … a folder still holding something stays (m4/kept with its excluded file, so m4), its emptied sibling goes',
        [true, true, false], [is_file("$t/mnt/cache/Yes/m4/kept/k.bin"), is_dir("$t/mnt/cache/Yes/m4"), is_dir("$t/mnt/cache/Yes/m4/gone")]);
    $dirs = file_exists("$t/dirs") ? file("$t/dirs", FILE_IGNORE_NEW_LINES) : [];
    same('tidy, a yes run: … folders empty before the run (e1, e2/e3) moved to the array; the excluded empty keepdir stays on the pool; never the share\'s folder or one holding a file handed over',
        [false, false, true, true, true, false, false, false],
        [is_dir("$t/mnt/cache/Yes/e1"), is_dir("$t/mnt/cache/Yes/e2"), is_dir("$t/mnt/disk1/Yes/e1"), is_dir("$t/mnt/disk1/Yes/e2/e3"), is_dir("$t/mnt/cache/Yes/keepdir"),
         in_array("$t/mnt/cache/Yes", $dirs, true), in_array("$t/mnt/cache/Yes/m4", $dirs, true), in_array("$t/mnt/cache/Yes/keepdir", $dirs, true)]);
    // everything moved: the share's folder on the pool goes too, as Unraid's mover hands it over (USO «share root»)
    $reset();
    $mk('mnt/cache/Yes/m3/a/1.bin');
    file_put_contents("$t/excl.txt", "");
    runEnv(['bash', $sm, '--run'], $env, 60);
    same('tidy, a yes run: all of the share moved — m3 gone, the share\'s emptied folder on the pool too (to the array)', [false, false, true],
        [is_dir("$t/mnt/cache/Yes/m3"), is_dir("$t/mnt/cache/Yes"), is_file("$t/mnt/disk1/Yes/m3/a/1.bin")]);

    // as Unraid's mover, every run, whatever her rules: a yes share with an age rule, only an empty folder (an app's .tmp)
    // and no file to move — the folder goes to the array
    $reset();
    @mkdir("$t/mnt/cache/Yes/.tmp", 0700, true);
    file_put_contents("$t/ini", "[GLOBAL]\nmin_age=0\n[Yes]\nmin_age=30\nexcludes=$t/excl.txt\n");
    [$exit] = runEnv(['bash', $sm, '--run'], $env, 60);
    file_put_contents("$t/ini", "[GLOBAL]\nmin_age=0\n[Yes]\nexcludes=$t/excl.txt\n");
    same('tidy, a yes share with an age rule and nothing to move: its empty folder goes to the array, the share\'s folder too (empty is empty, whatever the age), as with Unraid\'s mover',
        [0, false, true, false], [$exit, is_dir("$t/mnt/cache/Yes/.tmp"), is_dir("$t/mnt/disk1/Yes/.tmp"), is_dir("$t/mnt/cache/Yes")]);

    // a prefer share from a second pool (fast → cache): its emptied and its empty folders go to the pool, its folder on fast stays
    $reset();
    unlink("$t/shares/Yes.cfg");
    file_put_contents("$t/shares/Pics.cfg", "shareUseCache=\"prefer\"\nshareCachePool=\"cache\"\nshareCachePool2=\"fast\"\n");
    $mk('mnt/fast/Pics/a/1.jpg');
    @mkdir("$t/mnt/fast/Pics/empty/inner", 0700, true);
    [$exit] = runEnv(['bash', $sm, '--run'], $env, 60);
    same('tidy, prefer from a second pool: exit 0 — a/ (emptied) and empty/inner (empty before) gone from fast, on the pool; fast/Pics emptied: gone too',
        [0, false, false, true, true, false], [$exit, is_dir("$t/mnt/fast/Pics/a"), is_dir("$t/mnt/fast/Pics/empty"), is_file("$t/mnt/cache/Pics/a/1.jpg"),
         is_dir("$t/mnt/cache/Pics/empty/inner"), is_dir("$t/mnt/fast/Pics")]);

    // a prefer share, stopped while its 3rd file moves: disk1's two files and disk2's first on the pool — disk1/Pics/d1 and
    // disk1/Pics emptied: gone (their copies on the pool), disk2/Pics/d2 still holds two: stays
    $reset();
    file_put_contents("$t/shares/Pics.cfg", "shareUseCache=\"prefer\"\nshareCachePool=\"cache\"\n");
    foreach (['disk1/Pics/d1/1.jpg', 'disk1/Pics/d1/2.jpg', 'disk2/Pics/d2/1.jpg', 'disk2/Pics/d2/2.jpg', 'disk2/Pics/d2/3.jpg'] as $f) {
        $mk("mnt/$f");
    }
    [$exit] = runEnv(['bash', $sm, '--run'], $env + ['MOVE_STOP_AT' => '3'], 60);
    $st = readJson("$t/st.json") ?? [];
    same('tidy, a stopped prefer run: exit 3, 3 moved, 2 left — disk1/Pics/d1 and disk1/Pics emptied: gone; disk2/Pics/d2 (2 files) stays; the pool has them',
        [3, 'stopped', 3, 2, false, false, true, 2, 3],
        [$exit, $st['result'] ?? null, $share($st, 'Pics')['moved'] ?? null, $share($st, 'Pics')['left'] ?? null, is_dir("$t/mnt/disk1/Pics/d1"), is_dir("$t/mnt/disk1/Pics"),
         is_dir("$t/mnt/disk2/Pics/d2"), count(glob("$t/mnt/disk2/Pics/d2/*.jpg") ?: []), count(glob("$t/mnt/cache/Pics/d*/*.jpg") ?: [])]);
    // a stopped prefer run never removes a folder on a disk whose copy is not on the pool
    $reset();
    foreach (['disk1/Pics/d1/1.jpg', 'disk1/Pics/d1/2.jpg', 'disk2/Pics/d2/1.jpg'] as $f) {
        $mk("mnt/$f");
    }
    file_put_contents("$t/bin/move.real", (string) file_get_contents("$t/bin/move"));
    chmod("$t/bin/move.real", 0755);
    // the pool's copy of d1 vanishes before the tidy (someone removed it): disk1/Pics/d1 stays, so does disk1/Pics
    file_put_contents("$t/bin/move", "#!/bin/bash\n\"\$(dirname \"\$0\")/move.real\"; rc=\$?\n[[ -e \"\$CUSTOMMOVER_STOP\" ]] && rm -rf \"\$MOVE_ROOT/cache/Pics/d1\"\nexit \$rc\n");
    [$exit] = runEnv(['bash', $sm, '--run'], $env + ['MOVE_STOP_AT' => '2'], 60);
    same('tidy, a stopped prefer run: a folder whose copy is not on the pool stays (disk1/Pics/d1, so disk1/Pics)', [3, true, true],
        [$exit, is_dir("$t/mnt/disk1/Pics/d1"), is_dir("$t/mnt/disk1/Pics")]);
    hardeningRm($t);
}

/**
 * Smart Mover, the share's own folder (USO «share root», 2026-10-19, seen on a real server: a prefer share's dataset on
 * its second pool stayed, empty and without snapshots — Unraid's mover removes it). As Unraid's mover, the share's
 * folder on the source side goes to the move binary once nothing below it is held, in every direction — a pool's (yes,
 * prefer from a second pool) as well as a disk's (prefer per disk); never one holding a file or an entry an exclude
 * keeps, never in a dry run, never after a stop; a dataset with snapshots the binary leaves is said in one line.
 */
function testMoverelliShareRoot(): void
{
    $t = hardeningTmp('moverelli-root');
    $mk = function (string $rel, string $body = 'x') use ($t): void {
        @mkdir(dirname("$t/$rel"), 0700, true);
        file_put_contents("$t/$rel", $body);
    };
    $reset = function () use ($t): void {
        exec('rm -rf ' . escapeshellarg("$t/mnt") . ' ' . escapeshellarg("$t/log") . ' ' . escapeshellarg("$t/stop") . ' ' . escapeshellarg("$t/dirs")
            . ' ' . escapeshellarg("$t/shares"));
        foreach (['mnt/user/Yes', 'mnt/user/Zed', 'mnt/user/Pics', 'mnt/cache', 'mnt/disk1', 'shares', 'bin'] as $d) {
            @mkdir("$t/$d", 0700, true);
        }
        file_put_contents("$t/excl.txt", '');
    };
    $reset();
    file_put_contents("$t/bin/move", <<<'SH'
#!/bin/bash
# a stand-in for Unraid's move binary: the pool → disk1, a data disk or the second pool fast → the pool; a folder made
# there and removed here when empty — never $MOVE_KEEP (a dataset with snapshots); every folder handed over noted; the
# stop file written while the n-th file moves
n=0
while IFS= read -r f; do
    case "$f" in
        "$MOVE_ROOT"/cache/*) to="$MOVE_ROOT/disk1/${f#"$MOVE_ROOT"/cache/}" ;;
        "$MOVE_ROOT"/fast/*) to="$MOVE_ROOT/cache/${f#"$MOVE_ROOT"/fast/}" ;;
        "$MOVE_ROOT"/disk[0-9]*/*) r=${f#"$MOVE_ROOT"/disk}; to="$MOVE_ROOT/cache/${r#*/}" ;;
        *) continue ;;
    esac
    if [[ -d "$f" && ! -L "$f" ]]; then
        printf '%s\n' "$f" >> "$MOVE_DIRS"; mkdir -p "$to"; [[ "$f" == "${MOVE_KEEP:-}" ]] || rmdir "$f" 2>/dev/null; continue
    fi
    (( ++n == ${MOVE_STOP_AT:-0} )) && printf '{"why":"user"}' > "$CUSTOMMOVER_STOP"
    mkdir -p "$(dirname "$to")" && mv "$f" "$to"
done
exit 0
SH);
    // a zfs that knows one dataset, cache/Yes mounted on the share's folder, with a snapshot
    file_put_contents("$t/bin/zfs", "#!/bin/bash\ncase \"\$*\" in\n  'list -H -o name,mountpoint '*) [[ \"\${@: -1}\" == \"\$MOVE_ROOT/cache/Yes\" ]] && printf 'cache/Yes\\t%s\\n' \"\$MOVE_ROOT/cache/Yes\" && exit 0; exit 1 ;;\n"
        . "  'list -H -t snapshot -o name -d 1 cache/Yes') echo 'cache/Yes@uso-plan-x'; exit 0 ;;\nesac\nexit 1\n");
    chmod("$t/bin/move", 0755);
    chmod("$t/bin/zfs", 0755);
    file_put_contents("$t/ini", "[GLOBAL]\nmin_age=0\nglobal_excludes=$t/excl.txt\n");
    $env = ['CUSTOMMOVER_INI' => "$t/ini", 'CUSTOMMOVER_SHARES_DIR' => "$t/shares", 'CUSTOMMOVER_MNT' => "$t/mnt", 'CUSTOMMOVER_LOG' => "$t/log",
            'CUSTOMMOVER_LOCK' => "$t/lock", 'CUSTOMMOVER_STATUS' => "$t/st.json", 'CUSTOMMOVER_ZFS' => "$t/bin/zfs", 'CUSTOMMOVER_MOVER_BIN' => "$t/bin/move",
            'CUSTOMMOVER_STOP' => "$t/stop", 'CUSTOMMOVER_IGNORE_MOVER' => '1', 'MOVE_ROOT' => "$t/mnt", 'MOVE_DIRS' => "$t/dirs"];
    $sm = OFFICE_DIR . '/smartmover/custommover_run.sh';
    $dirs = fn () => file_exists("$t/dirs") ? file("$t/dirs", FILE_IGNORE_NEW_LINES) : [];
    $log = fn () => (string) @file_get_contents("$t/log");
    $yes = fn () => file_put_contents("$t/shares/Yes.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\n");

    // a yes share, pool → array: its only file goes, then its emptied folder on the pool (the share's root) — said
    $reset(); $yes();
    $mk('mnt/cache/Yes/sub/a.bin');
    [$exit] = runEnv(['bash', $sm, '--run'], $env, 60);
    same('share root, yes pool → array: exit 0 — the file on disk1, the share\'s folder on the pool handed to the move binary and gone, said',
        [0, true, true, false, true], [$exit, is_file("$t/mnt/disk1/Yes/sub/a.bin"), in_array("$t/mnt/cache/Yes", $dirs(), true), is_dir("$t/mnt/cache/Yes"),
         str_contains($log(), "share folder $t/mnt/cache/Yes removed (empty)")]);

    // the same, the folder a dataset with a snapshot: the binary leaves it — said in one line, no warning
    $reset(); $yes();
    $mk('mnt/cache/Yes/a.bin');
    [$exit] = runEnv(['bash', $sm, '--run'], $env + ['MOVE_KEEP' => "$t/mnt/cache/Yes"], 60);
    same('share root, a dataset with snapshots: handed over, the binary leaves it — «kept: cache/Yes has snapshots» once, no WARN, exit 0',
        [0, true, true, 1, false], [$exit, in_array("$t/mnt/cache/Yes", $dirs(), true), is_dir("$t/mnt/cache/Yes"), substr_count($log(), 'kept: cache/Yes has snapshots'),
         str_contains($log(), '[WARN]')]);

    // a prefer share from a second pool (the owner's server: fast → cache): its emptied folder on fast goes
    $reset();
    file_put_contents("$t/shares/Pics.cfg", "shareUseCache=\"prefer\"\nshareCachePool=\"cache\"\nshareCachePool2=\"fast\"\n");
    $mk('mnt/fast/Pics/a/1.jpg');
    [$exit] = runEnv(['bash', $sm, '--run'], $env, 60);
    same('share root, prefer second pool → pool: exit 0 — the file on the pool, fast/Pics handed over and gone, said',
        [0, true, true, false, true], [$exit, is_file("$t/mnt/cache/Pics/a/1.jpg"), in_array("$t/mnt/fast/Pics", $dirs(), true), is_dir("$t/mnt/fast/Pics"),
         str_contains($log(), "share folder $t/mnt/fast/Pics removed (empty)")]);

    // a prefer share per disk (array → pool): each disk's emptied folder goes, as before
    $reset();
    file_put_contents("$t/shares/Pics.cfg", "shareUseCache=\"prefer\"\nshareCachePool=\"cache\"\n");
    $mk('mnt/disk1/Pics/1.jpg');
    $mk('mnt/disk2/Pics/d/2.jpg');
    [$exit] = runEnv(['bash', $sm, '--run'], $env, 60);
    same('share root, prefer per disk: exit 0 — both files on the pool, disk1/Pics and disk2/Pics gone',
        [0, true, true, false, false], [$exit, is_file("$t/mnt/cache/Pics/1.jpg"), is_file("$t/mnt/cache/Pics/d/2.jpg"), is_dir("$t/mnt/disk1/Pics"), is_dir("$t/mnt/disk2/Pics")]);

    // held: an excluded file, or an excluded empty folder, keeps the share's folder — never handed over
    foreach (['file' => 'mnt/cache/Yes/keep/k.bin', 'folder' => 'mnt/cache/Yes/keepdir'] as $what => $kept) {
        $reset(); $yes();
        $mk('mnt/cache/Yes/a.bin');
        $what === 'file' ? $mk($kept) : @mkdir("$t/$kept", 0700, true);
        file_put_contents("$t/excl.txt", "$t/" . $kept . "\n");
        [$exit] = runEnv(['bash', $sm, '--run'], $env, 60);
        same("share root, an excluded $what keeps it: exit 0 — a.bin moved, $kept and the share's folder stay, never handed over",
            [0, true, true, true, false], [$exit, is_file("$t/mnt/disk1/Yes/a.bin"), file_exists("$t/$kept"), is_dir("$t/mnt/cache/Yes"), in_array("$t/mnt/cache/Yes", $dirs(), true)]);
    }

    // a dry run: nothing handed over, the folder stays
    $reset(); $yes();
    @mkdir("$t/mnt/cache/Yes/empty", 0700, true);
    $mk('mnt/cache/Yes/a.bin');
    [$exit] = runEnv(['bash', $sm], $env, 60);
    same('share root, a dry run: exit 0 — the file, its empty folder and the share\'s folder stay, nothing handed over',
        [0, true, true, []], [$exit, is_file("$t/mnt/cache/Yes/a.bin"), is_dir("$t/mnt/cache/Yes/empty"), $dirs()]);

    // an empty share with nothing to move goes too (the «no files match» path) — not after a stop: Yes' file stops the run,
    // Zed (after it) keeps its empty folder; without the stop it goes
    foreach ([true, false] as $stop) {
        $reset(); $yes();
        file_put_contents("$t/shares/Zed.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\n");
        $mk('mnt/cache/Yes/a.bin');
        @mkdir("$t/mnt/cache/Zed", 0700, true);
        [$exit] = runEnv(['bash', $sm, '--run'], $env + ($stop ? ['MOVE_STOP_AT' => '1'] : []), 60);
        same($stop ? 'share root, a stop during Yes: exit 3 — Zed\'s empty folder stays, never handed over'
                   : 'share root, no stop: exit 0 — Zed\'s empty folder (nothing to move) handed over and gone',
            $stop ? [3, true, false] : [0, false, true], [$exit, is_dir("$t/mnt/cache/Zed"), in_array("$t/mnt/cache/Zed", $dirs(), true)]);
    }
    hardeningRm($t);
}

/**
 * Smart Mover, names ending in a space or tab (2026-10-18, seen on a real server: 51 312 files of a prefer share on the
 * pool, 57 empty folders left on the disk, every leaf like «06 Juni »): Unraid's move binary drops the whitespace at the
 * end of each path it reads — such a name never goes to it (given «foo » it would move «foo»); a file to the pool is moved
 * by the script (owner, mode, times; never over something there), one to the array stays; after the folder pass an
 * empty folder whose copy is on the pool is removed (an empty one ending in a space made there first), never one holding
 * anything; a share whose files all moved in an earlier run gets its folder pass too.
 */
function testMoverelliTrailingSpace(): void
{
    $t = hardeningTmp('moverelli-ws');
    $mk = function (string $rel, string $body = 'x') use ($t): void {
        @mkdir(dirname("$t/$rel"), 0700, true);
        file_put_contents("$t/$rel", $body);
    };
    $reset = function () use ($t): void {
        exec('rm -rf ' . escapeshellarg("$t/mnt") . ' ' . escapeshellarg("$t/log") . ' ' . escapeshellarg("$t/moved") . ' ' . escapeshellarg("$t/calls"));
        foreach (['mnt/cache/Pics', 'mnt/user/Pics', 'mnt/user/Docs', 'mnt/cache/Docs', 'mnt/disk1', 'shares', 'bin'] as $d) {
            @mkdir("$t/$d", 0700, true);
        }
    };
    $reset();
    file_put_contents("$t/shares/Pics.cfg", "shareUseCache=\"prefer\"\nshareCachePool=\"cache\"\n");
    file_put_contents("$t/shares/Docs.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\n");
    file_put_contents("$t/excl.txt", "$t/mnt/user/Docs/note\n$t/mnt/user/Pics/2019/keep\n");
    file_put_contents("$t/ini", "[GLOBAL]\nmin_age=0\nglobal_excludes=$t/excl.txt\n");
    file_put_contents("$t/bin/move", <<<'SH'
#!/bin/bash
# a stand-in for Unraid's move binary as it is (7.4.0-rc.1): the whitespace at the end of a line dropped; a data disk →
# the pool, the pool → disk1; a folder created there, removed here when empty; a «busy» file skipped (in use); every
# line noted as read
echo x >> "$MOVE_CALLS"
while IFS= read -r line; do
    printf '%s\n' "$line" >> "$MOVE_LOG"
    f="${line%"${line##*[![:space:]]}"}"
    [[ -e "$f" || -L "$f" ]] || { echo "error: move: No such file or directory (2): lstat: $f"; continue; }
    case "$f" in
        "$MOVE_ROOT"/cache/*) to="$MOVE_ROOT/disk1/${f#"$MOVE_ROOT"/cache/}" ;;
        "$MOVE_ROOT"/disk[0-9]*/*) r=${f#"$MOVE_ROOT"/disk}; to="$MOVE_ROOT/cache/${r#*/}" ;;
        *) continue ;;
    esac
    if [[ -d "$f" && ! -L "$f" ]]; then mkdir -p "$to" && rmdir "$f" 2>/dev/null; continue; fi
    [[ "$f" == *busy* ]] && continue
    mkdir -p "$(dirname "$to")" && mv "$f" "$to" && echo "move: $f Success"
done
exit 0
SH);
    chmod("$t/bin/move", 0755);
    $env = ['CUSTOMMOVER_INI' => "$t/ini", 'CUSTOMMOVER_SHARES_DIR' => "$t/shares", 'CUSTOMMOVER_MNT' => "$t/mnt", 'CUSTOMMOVER_LOG' => "$t/log",
            'CUSTOMMOVER_LOCK' => "$t/lock", 'CUSTOMMOVER_STATUS' => "$t/st.json", 'CUSTOMMOVER_ZFS' => '/nonexistent-zfs', 'CUSTOMMOVER_MOVER_BIN' => "$t/bin/move",
            'CUSTOMMOVER_STOP' => "$t/stop", 'CUSTOMMOVER_IGNORE_MOVER' => '1', 'MOVE_ROOT' => "$t/mnt", 'MOVE_LOG' => "$t/moved", 'MOVE_CALLS' => "$t/calls"];
    $sm = OFFICE_DIR . '/smartmover/custommover_run.sh';
    $handed = fn () => file_exists("$t/moved") ? file("$t/moved", FILE_IGNORE_NEW_LINES) : [];
    $share = fn (array $st, string $n) => array_values(array_filter($st['shares'] ?? [], fn ($x) => $x['share'] === $n))[0] ?? [];
    $d1 = "$t/mnt/disk1/Pics";
    $c = "$t/mnt/cache/Pics";
    $old = strtotime('2020-01-01 12:00:00');

    // a prefer share: a folder ending in a space with its file, one still holding a file the binary skips, an empty one,
    // files ending in a space or tab (one beside its twin without), one whose copy is on the pool already
    $mk('mnt/disk1/Pics/06 Juni /a.jpg', 'a');
    $mk('mnt/disk1/Pics/07 Juli /x.jpg', 'x');
    $mk('mnt/disk1/Pics/07 Juli /busy.jpg', 'b');
    @mkdir("$d1/leer ", 0750);
    touch("$d1/leer ", $old);
    $mk('mnt/disk1/Pics/plain/file end ', 'ws');
    chmod("$d1/plain/file end ", 0640);
    touch("$d1/plain/file end ", $old);
    $mk("mnt/disk1/Pics/plain/tab\t", 'tab');
    $mk('mnt/disk1/Pics/plain/foo', 'twin');
    $mk('mnt/disk1/Pics/plain/foo ', 'space');
    $mk('mnt/disk1/Pics/dup ', 'new');
    $mk('mnt/cache/Pics/dup ', 'there');
    // a yes share: «note» is excluded, «note » beside it — the binary given «note » would move «note»
    $mk('mnt/cache/Docs/note', 'excluded');
    $mk('mnt/cache/Docs/note ', 'ws');
    $mk('mnt/disk1/Pics/open /held ', 'h');          // in use: never copied
    $holder = proc_open(['tail', '-f', "$d1/open /held "], [1 => ['file', '/dev/null', 'w'], 2 => ['file', '/dev/null', 'w']], $pipes);
    usleep(300000);
    [$exit] = runEnv(['bash', $sm, '--run'], $env, 60);
    proc_terminate($holder);
    proc_close($holder);
    $st = readJson("$t/st.json") ?? [];
    $log = (string) file_get_contents("$t/log");
    same('trailing space: no path ending in whitespace ever reaches the move binary', [],
        array_values(array_filter($handed(), fn ($l) => preg_match('/\s$/', $l))));
    same('trailing space: exit 0; Pics 9 files — 6 moved, busy.jpg, «dup » and «held » (in use) left; Docs 1 file («note » to the array), left',
        [0, 9, 6, 3, 1, 0, 1],
        [$exit, $share($st, 'Pics')['files'] ?? null, $share($st, 'Pics')['moved'] ?? null, $share($st, 'Pics')['left'] ?? null,
         $share($st, 'Docs')['files'] ?? null, $share($st, 'Docs')['moved'] ?? null, $share($st, 'Docs')['left'] ?? null]);
    same('trailing space: the files ending in a space or tab on the pool, by the script — content, mode, mtime kept; the twin «foo» its own',
        ['ws', '640', $old, 'tab', 'space', 'twin', false, false, false, false],
        [@file_get_contents("$c/plain/file end "), sprintf('%o', @fileperms("$c/plain/file end ") & 0777), @filemtime("$c/plain/file end "),
         @file_get_contents("$c/plain/tab\t"), @file_get_contents("$c/plain/foo "), @file_get_contents("$c/plain/foo"),
         file_exists("$d1/plain/file end "), file_exists("$d1/plain/foo "), file_exists("$d1/plain/foo"), file_exists("$c/plain/file end .partial")]);
    same('trailing space: a file whose copy is on the pool already stays on the disk, the pool\'s untouched, named in a WARN',
        ['new', 'there', true], [@file_get_contents("$d1/dup "), @file_get_contents("$c/dup "), str_contains($log, "left: $d1/dup  – already at the destination")]);
    same('trailing space: a file in use stays where it is, named in a WARN, nothing of it on the pool',
        [true, false, true], [is_file("$d1/open /held "), file_exists("$c/open /held "), str_contains($log, "left: $d1/open /held  – in use")]);
    same('trailing space: «06 Juni » and «plain» gone from the disk (their copies on the pool); «leer » made on the pool (mode, mtime) and gone; «07 Juli » (busy.jpg) and the share\'s folder stay',
        [false, true, false, false, true, '750', $old, true, true, true],
        [is_dir("$d1/06 Juni "), is_file("$c/06 Juni /a.jpg"), is_dir("$d1/plain"), is_dir("$d1/leer "), is_dir("$c/leer "),
         sprintf('%o', @fileperms("$c/leer ") & 0777), @filemtime("$c/leer "), is_file("$d1/07 Juli /busy.jpg"), is_file("$c/07 Juli /x.jpg"), is_dir($d1)]);
    check('trailing space: one INFO line counts the folders removed (and the one made)',
        str_contains($log, 'empty folders the move binary left on the array removed – they are on cache (1 made there first'), $log);
    same('trailing space: pool → array — «note » stays (WARN: rename it), the excluded «note» was never moved',
        [true, 'excluded', false, false, true],
        [is_file("$t/mnt/cache/Docs/note "), @file_get_contents("$t/mnt/cache/Docs/note"), file_exists("$t/mnt/disk1/Docs/note"), file_exists("$t/mnt/disk1/Docs/note "),
         str_contains($log, "left: $t/mnt/cache/Docs/note  – its name ends in a space or tab")]);

    // the owner's state: every file moved in an earlier run, empty folders ending in a space left on the disk (their copies on
    // the pool); an excluded folder with its file never touched
    $reset();
    foreach (['2019/06 Juni ', '2019/07 Juli ', '2020/01 Jan '] as $dir) {
        @mkdir("$d1/$dir", 0700, true);
        @mkdir("$c/$dir", 0700, true);
    }
    $mk('mnt/disk1/Pics/2019/keep/k.jpg', 'k');
    [$exit] = runEnv(['bash', $sm, '--run'], $env, 60);
    $st = readJson("$t/st.json") ?? [];
    $log = (string) file_get_contents("$t/log");
    same('trailing space: only empty folders left from an earlier run — exit 0, state none; the empty ones and 2020/ (emptied by them) gone, 2019/ (keep/, excluded) and the share\'s folder stay',
        [0, 'none', false, false, false, true, true, true],
        [$exit, $share($st, 'Pics')['state'] ?? null, is_dir("$d1/2019/06 Juni "), is_dir("$d1/2019/07 Juli "), is_dir("$d1/2020"), is_file("$d1/2019/keep/k.jpg"),
         is_dir("$d1/2019"), is_dir("$c/2019/06 Juni ")]);
    check('trailing space: … said in one line', str_contains($log, '4 empty folders the move binary left on the array removed – they are on cache'), $log);
    // C-M4 (scenario M4, 2026-10-19): the yes direction — a folder ending in a space whose files went to the array goes from
    // the pool too (there is no /mnt/array: its copy on any data disk counts); an empty one without a copy on the array
    // stays (which disk would be the binary's choice), as Unraid's mover leaves it
    $reset();
    $mk('mnt/cache/Docs/06 Juni /a.txt', 'a');
    $mk('mnt/cache/Docs/2024 /05 Mai /b.txt', 'b');
    @mkdir("$t/mnt/cache/Docs/leer ", 0700, true);
    [$exit] = runEnv(['bash', $sm, '--run'], $env, 60);
    $log = (string) file_get_contents("$t/log");
    same('trailing space, yes share: «06 Juni » and «2024 /05 Mai » gone from the pool (their files on the array), «leer » (no copy on the array) stays',
        [0, false, true, false, true, true, false],
        [$exit, is_dir("$t/mnt/cache/Docs/06 Juni "), is_file("$t/mnt/disk1/Docs/06 Juni /a.txt"), is_dir("$t/mnt/cache/Docs/2024 "),
         is_file("$t/mnt/disk1/Docs/2024 /05 Mai /b.txt"), is_dir("$t/mnt/cache/Docs/leer "), is_dir("$t/mnt/disk1/Docs/leer ")]);
    check('trailing space, yes share: … said in one line', str_contains($log, '3 empty folders the move binary left removed – they are on the array'), $log);
    // a dry run touches nothing
    $reset();
    @mkdir("$d1/2019/06 Juni ", 0700, true);
    @mkdir("$c/2019/06 Juni ", 0700, true);
    runEnv(['bash', $sm], $env, 60);
    check('trailing space: a dry run leaves the folders', is_dir("$d1/2019/06 Juni "));
    hardeningRm($t);
}

/**
 * A share with nothing to move any more but rules of its own (2026-10-18, the owner: a prefer share set to its pool only
 * after the move): her setup row says they don't apply and what they are, «Remove rules» takes them out of the form (the
 * bar counts it, «Save» makes it so) — never removed by her. A share gone from Unraid: the same, its rules kept on every
 * other save exactly as they are (a changed rule for it still refused).
 */
function testMoverelliIdleRules(): void
{
    $tmp = hardeningTmp('moverelli-idle');
    $v = [];
    moverelliFixture($tmp, $v);
    $h = moverelliHost();
    $dir = "$tmp/data";
    file_put_contents("$tmp/shares/Arr.cfg", "shareUseCache=\"only\"\nshareCachePool=\"cache\"\n");   // nothing to move
    file_put_contents("$tmp/shares/Alt.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\n");
    @mkdir("$tmp/mnt/user/Alt", 0700, true);
    $alt = ['skip' => true, 'min_age' => null, 'move_when_used_above' => null, 'files' => [], 'patterns' => []];
    $arr = ['skip' => false, 'min_age' => 30, 'move_when_used_above' => null, 'files' => [], 'patterns' => ['*.tmp']];
    moverelliSave(moverelliTestSettings([], ['Alt' => $alt, 'Arr' => $arr]), $h);
    rmdir("$tmp/mnt/user/Alt");                                        // Alt removed in Unraid (its cfg left behind)
    $st = moverelliScan($h);
    $row = array_values(array_filter($st['shares'], fn ($x) => $x['share'] === 'Arr'))[0] ?? [];
    same('idle rules: Arr (pool only) — mode none, its own rules still known; Alt gone — named apart, not a row of her overview',
        ['none', true, ['Alt'], false], [$row['mode'] ?? null, $row['own'] ?? null, $st['shares_gone'] ?? null, in_array('Alt', array_column($st['shares'], 'share'), true)]);
    $names = moverelliShareNames($h['shares_dir'], $h);
    $set = moverelliSettings($dir);
    $kept = moverelliCheck(['global' => $set['global'], 'shares' => $set['shares']], $names, $dir);
    same('idle rules: another save keeps the gone share\'s rules exactly as they are', [$alt, $arr], [$kept['shares']['Alt'] ?? null, $kept['shares']['Arr'] ?? null]);
    $changed = $set['shares'];
    $changed['Alt']['min_age'] = 5;
    try {
        moverelliCheck(['global' => $set['global'], 'shares' => $changed], $names, $dir);
        check('idle rules: a changed rule for a gone share is refused', false);
    } catch (Problem $e) {
        same('idle rules: a changed rule for a gone share is refused', 'moverelli_bad_share', $e->key);
    }
    try {
        moverelliCheck(['global' => $set['global'], 'shares' => ['Neu' => $alt]], $names, $dir);
        check('idle rules: rules for a share never there are refused', false);
    } catch (Problem $e) {
        same('idle rules: rules for a share never there are refused', 'moverelli_bad_share', $e->key);
    }
    $removed = moverelliCheck(['global' => $set['global'], 'shares' => array_diff_key($set['shares'], ['Alt' => 1, 'Arr' => 1])], $names, $dir);
    moverelliSave($removed, $h);
    same('idle rules: «Remove rules» saved — both sections gone, nothing gone left to show', [[], []],
        [array_keys(moverelliSettings($dir)['shares'] ?? []), moverelliScan($h)['shares_gone'] ?? null]);

    $node = testsNode();
    if ($node === '') {
        check('idle rules: page - node is missing here - skipped', true);
        hardeningRm($tmp);
        return;
    }
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const mk = (tag, cls, text) => ({ tag, cls, text, textContent: text == null ? '' : String(text), children: [], hidden: false, disabled: false, dataset: {}, style: {},
  set innerHTML(v) { this.children = []; }, append(...c) { this.children.push(...c); }, appendChild(c) { this.children.push(c); return c; }, setAttribute() {}, addEventListener() {} });
globalThis.document = { createTextNode: (t) => t };
let bar = null;
globalThis.Office = { sections: () => ({ el: {}, active: () => '', note: () => ({ tile: '' }), places: () => [], mount: () => false, pick() {}, render() {}, clear() {} }),
  scope: () => T, t: T, el: mk, fmt: { size: (b) => b + ' B' }, desk: () => {}, places: () => {}, placesFrom: () => {}, store: () => null, agent: { running: true },
  place: (k, n) => n, selbar: (s) => { bar = s; }, toast: () => {}, api: { post: async () => ({ ok: true }) } };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const m = OFFICE_DESK_TESTS.moverelli;
const texts = (n) => (typeof n === 'string' ? [n] : [n.text, ...n.children.flatMap(texts)].filter(Boolean));
const find = (n, pred) => (typeof n === 'string' ? null : pred(n) ? n : n.children.map((c) => find(c, pred)).find(Boolean) || null);
const g = { min_age: 0, move_when_used_above: 0, move_prefer_shares: true, mover_debug: 0, max_list: 50, files: [], patterns: [] };
m.setState({ configured: true, settings: { global: g, shares: {
    nc: { skip: false, min_age: 0, move_when_used_above: null, files: ['/mnt/user/appdata/x.txt'], patterns: ['*.tmp', 'cache'] },
    Alt: { skip: true, min_age: null, move_when_used_above: 80, files: [], patterns: [] } } },
  shares: [{ share: 'Filme', mode: 'yes', from: 'cache', to: 'array', own: false, state: 'moves' }, { share: 'nc', mode: 'none', own: true, state: 'none' }],
  shares_gone: ['Alt'], mover: { off: true }, jack: { hired: false } });
m.setPage('setup');
m.setForm(null);
m.initForm();
const out = {};
out.parts = [m.ownRulesText(m.form().shares.nc), m.ownRulesText(m.form().shares.Alt), m.ownRulesText(m.form().shares.Filme)];
const box = mk('div');
m.fillSetupShares(box);
out.rows = box.children.map((d) => d.children[0].text);
out.nc = texts(box.children.find((d) => d.children[0].text === 'nc'));
out.alt = texts(box.children.find((d) => d.children[0].text === 'Alt'));
out.filme = texts(box.children.find((d) => d.children[0].text === 'Filme'));
out.noBar = m.setupBarSpec() === null;
// «Remove rules» on nc: out of the form, the row says so, the bar counts one change (− rules of its own)
const btn = find(box.children.find((d) => d.children[0].text === 'nc'), (n) => n.tag === 'button');
btn.onclick();
out.after = texts(box.children.find((d) => d.children[0].text === 'nc'));
out.bar = bar && bar.title;
out.sent = Object.keys(m.formSettings(m.form()).shares);
out.change = m.setupChangeRows(m.formSettings({ global: g, shares: { nc: m.formSettings({ global: g, shares: { nc: { skip: false, min_age: 0, move_when_used_above: null, files: ['/mnt/user/appdata/x.txt'], patterns: ['*.tmp', 'cache'] } } }).shares.nc, Alt: m.form().shares.Alt } }), m.formSettings(m.form()))
  .map((r) => [r.mark, r.label, r.what]);
console.log(JSON.stringify(out));
JS);
    [, $out, $err] = run([$node, "$tmp/t.js", OFFICE_WEB . '/desks/moverelli/desk.js'], 30);
    $j = json_decode(trim((string) $out), true) ?? [];
    check('idle rules: page runs', $j !== [], $out . $err);
    same('idle rules: what they are in words — age 0 days, a list, 2 lines; left out, at most 80 %; none',
        ['setup.own_part.age {"days":"setup.tile.days {\"n\":0}"}, count.lists {"n":1}, count.lines {"n":2}', 'setup.own_part.skip, setup.own_part.limit {"pct":80}', ''], $j['parts'] ?? null);
    same('idle rules: the rows — Alt (gone) among the others, by name', ['Alt', 'Filme', 'nc'], $j['rows'] ?? null);
    check('idle rules: nc — nothing to move, its rules don\'t apply and what they are, «Remove rules»; Alt — gone, the same; Filme — none of it',
