    $in = moverelliTestSettings(['min_age' => 30, 'move_when_used_above' => 80, 'move_until_used_below' => 70, 'files' => ['/mnt/user/appdata/emby/mediacache_exclude.txt'], 'patterns' => ['# metadata', '*.nfo', '']],
