        [glob("$dir/excludes/*.txt"), str_contains((string) file_get_contents("$dir/smart_mover.ini"), 'global_excludes')]);
    // never while a run of hers goes (her job's lock held)
    $lock = fopen("$dir/office-run.lock", 'c');
