    // for Jack Emby's rule: what her ini keeps out
    moverelliSave(moverelliTestSettings(['files' => ['/x/mediacache_exclude.txt']], $share([]) + ['Back' => ['skip' => true, 'min_age' => null, 'age_stat' => null,
