/**
 * The night run's plan (agent/lib/nightrun.php, pure): the concept's 1 TB SSD (NM 300, X 80, Y 70: H 200 each) — night 1
 * (used 770, Jack Emby 320, 60 GB waiting: he gives back 70 first, she only by age, nothing fetched), night 2 (the
 * downloads grew: her age rule 50 before his 30), a download burst over X (she first, only down to the downloads' half,
 * he down to his), both full (nothing goes, nothing comes), «nearly reached» (1 % of the pool, at least 1 GiB), NM ≥ Y,
 * not measured; the words for the pages.
 */
function testNightPlan(): void
{
    $G = 1 << 30;
    $gib = fn (?int $b): ?float => $b === null ? null : round($b / $G, 1);
    // only X, Jack Emby's GB first (2026-10-14): 1 TB, X 80 (800)
    $lv = fn (int $used, int $jack, int $movable, int $x = 80) => poolLevelMath(1000 * $G, $used * $G, $movable * $G, $x, $jack * $G) + ['pool' => 'cache'];
    $p = nightPlan($lv(850, 400, 550), 60 * $G);
    same('night plan: fixed 300, Jack Emby 400 (his watched unknown yet), 60 wait — he gets them (room under X), the others give 110 so the pool ends at X; until 740',
        [null, 60.0, 0.0, 110.0, 740.0, 110.0, 40.0, false, null], [$p['jack_back'], $gib($p['jack_fetch']), $gib($p['wait']), $gib($p['others_back']), $gib($p['until']),
         $gib($p['need_room']), $gib($p['others_room']), $p['over'], $p['why']]);
    $p = nightPlan($lv(850, 400, 550), 60 * $G, 70 * $G);
    same('night plan: Jack Emby gave back 70 watched — he still gets his 60, the others give only 40', [70.0, 60.0, 40.0], [$gib($p['jack_back']), $gib($p['jack_fetch']), $gib($p['others_back'])]);
    same('night plan: the picture — before {size, fixed, others, jack, free, jack_watched} and the forecast after the moves (at X, nothing watched left)', [
        ['size' => 1000.0, 'fixed' => 300.0, 'snapshots' => null, 'others' => 150.0, 'jack' => 400.0, 'free' => 150.0, 'jack_watched' => 70.0],
        ['size' => 1000.0, 'fixed' => 300.0, 'snapshots' => null, 'others' => 110.0, 'jack' => 390.0, 'free' => 200.0, 'jack_watched' => 0.0]],
        [array_map($gib, $p['before']), array_map($gib, $p['forecast'])]);
    $p = nightPlan($lv(600, 200, 300), 300 * $G, 0);
    same('night plan: his budget crowds the others out — 300 fetched, the others (100) all pushed under X: crowded', [300.0, 100.0, 500.0, 'crowded', false],
        [$gib($p['jack_fetch']), $gib($p['others_back']), $gib($p['until']), $p['why'], $p['over']]);
    $p = nightPlan(poolLevelMath(1000 * $G, 850 * $G, 350 * $G, 80, 300 * $G) + ['pool' => 'cache'], 100 * $G, 0);
    same('night plan: appdata & co. 500 + what Jack Emby keeps 300 reach X — nothing new for him (the fixed never pushed), the others go: full', [0.0, 100.0, 50.0, 'full'],
        [$gib($p['jack_fetch']), $gib($p['wait']), $gib($p['others_back']), $p['why']]);
    $p = nightPlan($lv(920, 520, 620), 0, 0);
    same('night plan: the others (100) all go, still over X — only what Jack Emby keeps', [100.0, true, 'jack'], [$gib($p['others_back']), $p['over'], $p['why']]);
    $p = nightPlan($lv(900, 50, 100), 0, 0);
    same('night plan: what never moves (800) at X — never', [true, 'never'], [$p['never'], $p['why']]);
    $p = nightPlan(null, 5 * $G);
    same('night plan: not measured — no numbers, what waits stays', [false, 5.0, null, null], [$p['measured'], $gib($p['wait']), $p['before'], $p['until']]);
    same('night words: for the pages', ['measured' => true, 'back' => 70 * $G, 'goes' => 40 * $G, 'fill' => 60 * $G, 'wait' => 0, 'over' => false, 'why' => null],
        nightWords(nightPlan($lv(850, 400, 550), 60 * $G, 70 * $G)));
}

/**
 * The night run itself (nightRun(), stand-ins for both tools and the pool): the concept's night 1 with a download burst while
 * they free — Jack Emby frees, she by age, the pool measured anew and a second pass for Jack Emby, he fetches last; one lock
 * (the runs inside pass, others are refused); a stop in «free» ends it (stopped, nothing after); «Stop after this file»
 * from the page (the tool at work and the night); the target missed — told at once; only she; no limit; the dry run;
 * the schedule (one line, his own goes), the Team Lead, the migration `night-run` (four cases), Jack Emby's side, the pages.
 */
function testNightRun(): void
{
    $G = 1 << 30;
    $tmp = hardeningTmp('night-run');
    $v = [];
    moverelliFixture($tmp, $v);
    $GLOBALS['moverelliHost'] += ['cron_file' => "$tmp/office.cron", 'cron_apply' => false, 'jack_scheduled' => fn () => (officeCronLines("$tmp/office.cron")['embycache'] ?? null) !== null];
    $h = moverelliHost();
    $dir = "$tmp/data";
    moverelliSave(moverelliTestSettings(['move_when_used_above' => 80]), $h);
    // the pool in GiB (1 TB, X 80 = 800): used = nm + j + d; w of Jack Emby's j is watched; the stand-ins move as the tools would
    $p = [];
    $calls = [];
    $notified = [];
    $inside = [];
    $level = function () use (&$p, $G): array {
        $used = $p['nm'] + $p['j'] + $p['d'];
        return poolLevelMath(1000 * $G, $used * $G, ($p['j'] + $p['d']) * $G, 80, $p['j'] * $G) + ['pool' => 'cache'];
    };
    $runs = [];
    // where night.json says the work is at every measure and every tool's call (the card's highlight, 2026-10-15)
    $trace = [];
    $at = function (string $what) use (&$trace, $dir): void {
        $nj = readJson("$dir/night.json") ?? [];
        $trace[] = $what . ' ' . ($nj['phase'] ?? '-') . '/' . ($nj['who'] ?? '-');
    };
    // Unraid's bookkeeping: two data disks (4 TB, 1 TB used each — KB), parity and a pool not counted
    file_put_contents("$tmp/disks.ini", "[\"parity\"]\nname=\"parity\"\ntype=\"Parity\"\nfsSize=\"9\"\nfsUsed=\"9\"\n"
        . "[\"disk1\"]\nname=\"disk1\"\ntype=\"Data\"\nfsSize=\"4000000000\"\nfsUsed=\"1000000000\"\n"
        . "[\"disk2\"]\nname=\"disk2\"\ntype=\"Data\"\nfsSize=\"4000000000\"\nfsUsed=\"1000000000\"\n"
        . "[\"cache\"]\nname=\"cache\"\ntype=\"Cache\"\nfsSize=\"7\"\nfsUsed=\"7\"\n");
    $GLOBALS['nightHost'] = [
        'settle' => 0,
        'disks_ini' => "$tmp/disks.ini",
        'jack_budget' => fn () => null,
        'jack_on' => fn () => true,
        'level' => function (array $g, array $hh, bool $wake) use ($level, $at) { $at('measure'); return $level(); },
        'jack_status' => function () use (&$p, $G) {
            return ['pool' => ['waiting_bytes' => $p['wait'] * $G], 'cleanup' => ['bytes_done' => ($p['gave'] ?? 0) * $G, 'bytes_planned' => $p['w'] * $G],
                    'fill' => ['bytes_planned' => min($p['wait'], max(0, 800 - $p['nm'] - $p['j'] + $p['w'] - $p['d'])) * $G]];
        },
        'jack_live' => fn () => ['recent' => [['name' => 'Film/a.mkv', 'bytes' => 7, 'from' => 'cache', 'to' => 'array'], ['name' => 1, 'bytes' => 'x']]],
        'jack_runs' => function () use (&$runs) { return $runs; },
        'jack_stop' => "$tmp/jack-stop.json",
        'jack_output' => function () use (&$calls) { return 'his output after: ' . end($calls) . "\n"; },
        'her_output' => function () use (&$calls) { return 'her output after: ' . end($calls) . "\n"; },
        'notify' => function (string $s, string $b) use (&$notified) { $notified[] = $b; return true; },
        'jack_job' => function (array $args) use (&$p, &$calls, &$runs, &$inside, $dir, $at) {
            $at('jack');
            $calls[] = 'jack ' . implode(' ', $args);
            $inside[] = [nightRunning($dir), moverelliBusy($dir), nightInside()];
            $exit = array_shift($p['jack_exit']) ?? 0;
            if ($exit === 0 && in_array('--nofill', $args, true)) {
                $p['gave'] = $p['w'];                       // only what was watched, never by rank
                $p['j'] -= $p['w'];
                $p['w'] = 0;
            } elseif ($exit === 0 && $args[0] === 'run') {
                $fetch = max(0, min($p['wait'], 800 - ($p['nm'] + $p['j'] + $p['d'])));     // up to X, never past it
                $p['j'] += $fetch;
                $p['wait'] -= $fetch;
            }
            array_unshift($runs, ['tool' => 'embycache', 'result' => $exit === 3 ? 'stopped' : ($exit === 1 ? 'refused' : 'ok')]
                + ($exit === 1 ? ['why' => $p['jack_why'] ?? 'jack_gather_first'] : []));
            if (($p['stop_ask'] ?? false) && nightStopAsk()) {
                $p['stop_ask'] = false;
            }
            return $exit;
        },
        'her_job' => function (array $args, array $hh) use (&$p, &$calls, $dir, $G, $at) {
            $at('her');
            $calls[] = 'her ' . implode(' ', array_map(fn ($a) => preg_replace_callback('/^--fill-until=(\d+)$/', fn ($m) => '--fill-until=' . intdiv((int) $m[1], $G) . 'G', $a), $args));
            $p['d'] -= $p['age'] ?? 0;                      // the age rule
            $p['age'] = 0;
            $used = $p['nm'] + $p['j'] + $p['d'];
            $until = null;
            foreach ($args as $a) {
                $until = preg_match('/^--fill-until=(\d+)$/', $a, $m) ? intdiv((int) $m[1], $G) : $until;
            }
            if ($until !== null && $used > $until && !$p['her_stall']) {        // Jack Emby's room: the others' oldest until it is there
                $p['d'] -= min($p['d'], $used - $until);
            } elseif ($until === null && $used >= 800 && !$p['her_stall']) {   // the oldest of the others until below X
                $p['d'] -= min($p['d'], $used - 799);
            }
            $p['d'] += $p['burst'];                         // downloads arrive while she works
            $p['burst'] = 0;
            writeAtomic("$dir/status.json", jsonEncode(['result' => 'ok', 'fill_held' => (bool) ($p['held'] ?? false), 'recent' => [['name' => 'Docs/old.iso', 'bytes' => 5, 'from' => 'cache', 'to' => 'array']]]), 0600, 0, 0);
            moverelliRemember(['mode' => $args[0], 'by' => 'night', 'started' => time(), 'finished' => time(), 'result' => 'ok'], $dir);
            return 0;
        },
    ];
    $night = fn () => nightState($dir) ?? [];
    $fresh = fn (array $x) => $x + ['nm' => 300, 'j' => 0, 'w' => 0, 'd' => 0, 'wait' => 0, 'burst' => 0, 'jack_exit' => [], 'her_stall' => false];

    // (1) 850: Jack Emby gives back his 50 watched; his 60 waiting come first — she pushes the others below X (until 740) so his
    // fetch ends at X; downloads (40) arrive meanwhile: a recheck round, her part again; then he fetches his 60
    $p = $fresh(['j' => 400, 'w' => 50, 'd' => 150, 'wait' => 60, 'burst' => 40]);
    $trace = [];
    $exit = nightRun(['run', '--office']);
    $n = $night();
    same('night run 1: the work where night.json says — «check» while the pool is first measured, his give-back, «recheck» (nobody) while measured after it, her part, the quick recheck, her second pass, his fetch',
        ['measure check/-', 'jack free/jack', 'measure recheck/-', 'her free/her', 'measure recheck/-', 'her free/her', 'measure recheck/-', 'measure recheck/-', 'jack fill/jack', 'measure fill/-'], $trace);
    $her = 'her run --night --office --fill-until=740G --fill-pool=cache';
    same('night run 1 (started here: «--office» goes along to both, their run lists say so): Jack Emby frees (watched only, no fill), she makes his room below X, the pool grew: her part again, then he fetches — last',
        [0, ['jack run --night --office --nofill', $her, $her, 'jack run --night --office']], [$exit, $calls]);
    same('night run 1: … the pool at X (800), Jack Emby 350 + 60 fetched, nothing waits, two rounds, done, nothing told',
        [800, 410, 0, 2, 'ok', 'done', false, []], [$p['nm'] + $p['j'] + $p['d'], $p['j'], $p['wait'], $n['round'] ?? null, $n['result'] ?? null, $n['phase'] ?? null,
         $n['running'] ?? null, $notified]);
    same('night run 1: inside the night the runs pass its lock (night held, not «busy» for them)', [true, false, true], $inside[0] ?? null);
    // 1.65.0: the night's output — every step's, one after the other (each tool writes its own file anew each run); his steps
    // keep their counts (his page sums his give-back and his fetch over the night)
    $out = (string) @file_get_contents("$dir/" . NIGHT_OUTPUT);
    preg_match_all('/^===== (.+) =====$/m', $out, $m);
    same('night run 1: the output of every step in order, each with its tool\'s text', [['Jack Streamer · free · round 1', 'Ms. Moverelli · free · round 1',
        'Ms. Moverelli · free · round 2', 'Jack Streamer · fill · round 2'], true, true],
        [$m[1], str_contains($out, "his output after: jack run --night --office --nofill\n"), str_contains($out, "his output after: jack run --night --office\n")]);
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/jack/desk.js');
    check('night run 1: «Raw output» on both pages shows the whole night when the last run was a step of it; his result box sums his steps',
        str_contains((string) file_get_contents(OFFICE_DIR . '/agent/desks/jack.php'), "(jackJobInfo(\$tool)['by'] ?? '') === 'night' && is_file(\$night)")
        && str_contains((string) file_get_contents(OFFICE_DIR . '/agent/desks/moverelli.php'), "(moverelliJobInfo(\$h['dir'])['by'] ?? '') === 'night' && is_file(\"\$h[dir]/night-output.txt\")")
        && str_contains($js, "const st = nightStatus('last_status' in state ? state.last_status : state.last);"));
    same('night run 1: his steps keep their counts', [true, false, true],
        [isset(($n['steps'][0] ?? [])['cleanup']), isset(($n['steps'][1] ?? [])['cleanup']), isset((end($n['steps']) ?: [])['fill'])]);
    $pic = $n['picture'] ?? [];
    same('night run 1: the picture — X, where she moves to (the array\'s data disks from disks.ini), each phase as it began (before, forecast, planned), the files done by both',
        [80, ['to' => 'array', 'size' => 8000000000 * 1024, 'used' => 2000000000 * 1024], ['check', 'free', 'recheck', 'fill', 'done'], ['before', 'forecast', 'planned'],
         ['jack_back' => 50 * $G, 'others_back' => 60 * $G, 'jack_fetch' => 60 * $G, 'until' => 740 * $G], ['size', 'fixed', 'snapshots', 'others', 'jack', 'free', 'jack_watched', 'jack_reserve'],
         [['Film/a.mkv', 'jack'], ['Docs/old.iso', 'her']]],
        [$pic['x'] ?? null, $pic['dest'] ?? null, array_keys($pic['phases'] ?? []), array_keys($pic['phases']['free'] ?? []), $pic['phases']['free']['planned'] ?? null,
         array_keys($pic['phases']['check']['before'] ?? []), array_slice(array_map(fn ($f) => [$f['name'], $f['who']], $pic['files'] ?? []), 0, 2)]);
    same('night run 1: the check\'s picture — 850 used: fixed 300, others 150, Jack Emby 400, free 150', [300 * $G, 150 * $G, 400 * $G, 150 * $G],
        array_values(array_intersect_key($pic['phases']['check']['before'] ?? [], array_flip(['fixed', 'others', 'jack', 'free']))));
    // Jack Streamer's part in two (2026-10-15): what was watched known once his free step planned it — the check's pool split
    // (before), none of it left after (forecast), the free phase's pool without any (it went back)
    same('night run 1: what was watched in the picture — the check\'s pool 50 of his 400 watched, none in its forecast, its planned give-back 50; the free phase\'s pool none',
        [50 * $G, 0, 50 * $G, 0, 0], [$pic['phases']['check']['before']['jack_watched'] ?? 'x', $pic['phases']['check']['forecast']['jack_watched'] ?? 'x',
         $pic['phases']['check']['planned']['jack_back'] ?? 'x', $pic['phases']['free']['before']['jack_watched'] ?? 'x', $pic['phases']['done']['before']['jack_watched'] ?? 'x']);
    $lv = ['size' => 1000 * $G, 'used' => 850 * $G, 'nm' => 300 * $G, 'others' => 150 * $G, 'jack' => 400 * $G, 'x' => 80, 'used_pct' => 85.0, 'need' => 50 * $G, 'never' => false];
    $unknown = nightPlan($lv, 60 * $G);
    $known = nightPlan($lv, 60 * $G, 500 * $G);
    $pw = ['phases' => ['check' => nightPhasePicture($unknown)]];
    same('night picture: watched unknown — null (no split), the forecast null too; known — never more than his part; set into a picture once, never over a known value',
        [null, null, 400 * $G, 0, 70 * $G, 0, 70 * $G, 70 * $G, ['x' => 1]],
        [$unknown['before']['jack_watched'], $unknown['forecast']['jack_watched'], $known['before']['jack_watched'], $known['forecast']['jack_watched'],
         nightPictureWatched($pw, 70 * $G)['phases']['check']['before']['jack_watched'], nightPictureWatched($pw, 70 * $G)['phases']['check']['forecast']['jack_watched'],
         nightPictureWatched($pw, 70 * $G)['phases']['check']['planned']['jack_back'], nightPictureWatched(nightPictureWatched($pw, 70 * $G), 5 * $G)['phases']['check']['before']['jack_watched'],
         nightPictureWatched(['x' => 1], 5)]);
    // while his free step works: the page's poll splits the check's pool from EmbyCache's plan (its progress in RAM) — only
    // this night's (an older run's file never), only in his free step
    $nj = $night();
    $nj['finished'] = null;
    $nj['phase'] = 'free';
    $nj['who'] = 'jack';
    $nj['started'] = time() - 60;
    $nj['picture'] = ['phases' => ['check' => nightPhasePicture($unknown)], 'files' => []];
    nightWrite($dir, $nj);
    $hold = fopen("$dir/night.lock", 'c');
    flock($hold, LOCK_EX);
    $live = [];
    $liveWas = $GLOBALS['nightHost']['jack_live'];
    $GLOBALS['nightHost']['jack_live'] = function () use (&$live) { return $live; };
    $polled = function (array $l) use (&$live, $h) { $live = $l; $b = moverelliProgressState($h)['night']['picture']['phases']['check']['before'] ?? [];
        return array_key_exists('jack_watched', $b) ? $b['jack_watched'] : 'x'; };
    same('night picture live: his plan of this night — split at once; an older run\'s progress, none, a junk value — not split',
        [30 * $G, null, null, null], [$polled(['started' => time(), 'back' => ['bytes' => 30 * $G], 'recent' => []]), $polled(['started' => time() - 3600, 'back' => ['bytes' => 30 * $G]]),
         $polled([]), $polled(['started' => time(), 'back' => ['bytes' => 'x']])]);
    flock($hold, LOCK_UN);
    fclose($hold);
    $GLOBALS['nightHost']['jack_live'] = $liveWas;
    same('night picture: the array without a word of its size (stopped, no file, junk) — not measured', [[null, null], [null, null]],
        [nightArrayLevel("$tmp/none.ini"), (function () use ($tmp) { file_put_contents("$tmp/junk.ini", "[\"disk1\"]\nname=\"disk1\"\ntype=\"Data\"\nfsSize=\"\"\nfsUsed=\"x\"\n");
            return nightArrayLevel("$tmp/junk.ini"); })()]);
    check('night run: the lock — after the night nobody holds it; another start meanwhile is refused (moverelliBusy outside the night)',
        !nightRunning($dir) && !moverelliBusy($dir));

    // (2) Jack Emby never gives back what isn't watched: 920 with his 520 unwatched — the others' 100 go, still over X: missed, told why
    $calls = [];
    $p = $fresh(['j' => 520, 'd' => 100]);
    $envBefore = getenv('OFFICE_NOTIFY_BIN');
    putenv("OFFICE_NOTIFY_BIN=$tmp/bin/notify");
    nightRun(['run']);
    putenv($envBefore === false ? 'OFFICE_NOTIFY_BIN' : "OFFICE_NOTIFY_BIN=$envBefore");
    $n = $night();
    same('night run unwatched: Jack Emby keeps his 520 (nothing watched), she moves all the others\' 100, nothing more to move — «missed» (jack), told once',
        [520, 0, ['jack run --night --nofill', 'her run --night --fill-until=800G --fill-pool=cache', 'jack run --night'], 'missed', 'jack', true, 1, 82],
        [$p['j'], $p['d'], $calls, $n['result'] ?? null, $n['why'] ?? null, $n['missed'] ?? null, count($notified), $n['end_pct'] ?? null]);
    check('night run unwatched: … the warning says only Jack Emby\'s unwatched is over it (his budget too big)', str_contains($notified[0] ?? '', "Only what Jack Streamer hasn't watched yet is over it"),
        json_encode($notified));

    // (2b) R2 2026-10-15: snapshots keep what she moves — her fill says `fill_held` (moved what was over, the pool as full):
    // no second and third round moving as much again for nothing
    $calls = [];
    $p = $fresh(['j' => 400, 'd' => 150, 'wait' => 60, 'her_stall' => true, 'held' => true]);
    $notified = [];
    nightRun(['run']);
    $n = $night();
    same('night run held: her part once (her fill moved what was over, the pool didn\'t get freer) — no further round, missed',
        [['jack run --night --nofill', 'her run --night --fill-until=740G --fill-pool=cache', 'jack run --night'], true, 1],
        [$calls, $n['missed'] ?? null, $n['round'] ?? null]);
    $notified = [];

    // (3) his budget crowds the others out: 600 used, 300 wait — the others' 100 all pushed under X, he fetches 300 up to X: told
    $calls = [];
    $notified = [];
    $p = $fresh(['j' => 200, 'd' => 100, 'wait' => 300]);
    nightRun(['run']);
    same('night run crowded: she pushes the others (100) out for his 300, he fetches up to X; at X, but told: no room for the others',
        [['jack run --night --nofill', 'her run --night --fill-until=500G --fill-pool=cache', 'jack run --night'], 800, 0, 500, 'ok', 'crowded', 1],
        [$calls, $p['nm'] + $p['j'] + $p['d'], $p['d'], $p['j'], $night()['result'] ?? null, $night()['why'] ?? null, count($notified)]);
    check('night run crowded: … the warning says his budget leaves the others no room', str_contains($notified[0] ?? '', 'leaves the other shares no room below 80 %'), json_encode($notified));
    // the fixed shares are the exception: appdata & co. 500 + his 300 reach X — nothing new for him, the others go, told
    $calls = [];
    $notified = [];
    $p = $fresh(['nm' => 500, 'j' => 300, 'd' => 50, 'wait' => 100]);
    nightRun(['run']);
    same('night run full: what never moves (500) is never pushed for him — he fetches nothing (100 wait), the others (50) go, told «nothing new»',
        [500, 300, 100, 0, 'full', 1], [$p['nm'], $p['j'], $p['wait'], $p['d'], $night()['why'] ?? null, count($notified)]);
    check('night run full: … the warning says appdata & co. fill the pool', str_contains($notified[0] ?? '', "appdata & co. and what Jack Streamer keeps fill the pool cache up to 80 %"), json_encode($notified));

    // (4) stopped in «free»: Jack Emby's first pass ends with 3 — nothing after it, stopped
    $calls = [];
    $p = $fresh(['j' => 400, 'w' => 50, 'd' => 150, 'wait' => 60, 'jack_exit' => [3]]);
    $exit = nightRun(['run']);
    $n = $night();
    same('night run stopped: in «free» (his give-back — whose step said too), nothing after it (no fill), exit 3', [3, ['jack run --night --nofill'], 'stopped', 'free', 'jack'],
        [$exit, $calls, $n['result'] ?? null, $n['stopped_in'] ?? null, $n['stopped_who'] ?? null]);
    // «Stop after this file» from a page while Jack Emby works: his stop file and the night's — the night ends after his step
    $calls = [];
    $p = $fresh(['j' => 400, 'w' => 50, 'd' => 150, 'wait' => 60, 'stop_ask' => true]);
    @unlink("$tmp/jack-stop.json");
    nightRun(['run']);
    same('night run stop asked: the tool at work got its stop file, the night ended after its step, its stop file gone afterwards',
        [true, 1, 'stopped', false, false], [is_file("$tmp/jack-stop.json"), count($calls), $night()['result'] ?? null, is_file("$dir/night-stop.json"), nightStopAsk()]);

    // Jack Emby refuses his first step (live 2026-10-14: «consolidate folders» never ran): the night goes on with her part alone
    // (no room kept for him, no fetch), done — her record and night.json say why
    $calls = [];
    $p = $fresh(['j' => 0, 'd' => 400, 'age' => 20, 'jack_exit' => [1]]);
    $exit = nightRun(['run']);
    $n = $night();
    same('night run, Jack Emby refused (gather first): her part alone ran (solo, with his reason), no fetch, done — exit 0, the reason in night.json',
        [0, ['jack run --night --nofill', 'her run --night --solo --jack-out=jack_gather_first'], 'ok', 'jack_gather_first', 'done', 380],
        [$exit, $calls, $n['result'] ?? null, $n['jack_out'] ?? null, $n['phase'] ?? null, $p['d']]);
    same('night run, Jack Emby refused: the page\'s night carries the reason', 'jack_gather_first', moverelliNightShort($n)['jack_out'] ?? null);
    // … any refusal (here: not set up) — also when it comes at his fill at the end: her part ran already, the night is done
    $calls = [];
    $p = $fresh(['j' => 400, 'w' => 50, 'd' => 150, 'wait' => 60, 'jack_exit' => [0, 1], 'jack_why' => 'jack_not_configured']);
    $exit = nightRun(['run']);
    $n = $night();
    same('night run, Jack Emby refused his fill: her part ran before, done with the reason', [0, 'jack run --night', 'ok', 'jack_not_configured'],
        [$exit, end($calls), $n['result'] ?? null, $n['jack_out'] ?? null]);

    // (5) only she (Jack Emby not taking part): her part alone
    $calls = [];
    $GLOBALS['nightHost']['jack_on'] = fn () => false;
    nightRun(['run']);
    same('night run without Jack Emby: her part alone', ['her run --night --solo'], $calls);
    $n = $night();
    same('night run without Jack Emby: the pool measured all the same (her picture on every night) — the plan with numbers, her part only (nothing fetched)',
        [false, 'cache', true, 0, ['check', 'done']], [$n['jack'] ?? null, $n['picture']['pool'] ?? null, $n['plan']['measured'] ?? null, $n['plan']['fill'] ?? null,
         array_keys($n['picture']['phases'] ?? [])]);
    $GLOBALS['nightHost']['jack_on'] = fn () => true;
    // no limit (the pool not measured): her part, then Jack Emby's whole run (his own minimum free space)
    $calls = [];
    $GLOBALS['nightHost']['level'] = fn () => null;
    nightRun(['run']);
    same('night run without a limit: her part, then Jack Emby\'s whole run', ['her run --night', 'jack run --night'], $calls);
    // the dry run: both dry; the plan from Jack Emby's dry answer (what was watched, what he would fetch)
    $GLOBALS['nightHost']['level'] = fn (array $g, array $hh, bool $wake) => $level();
    $calls = [];
    $p = $fresh(['j' => 400, 'w' => 70, 'd' => 150, 'wait' => 60]);
    nightRun(['dry', '--office']);
    $n = $night();
    same('night dry run: Jack Emby dry, then she dry with his room — no recheck, no fill; the plan: 70 watched back, 20 fetched (from his dry answer)',
        [['jack dry --night --office', 'her dry --night --office --fill-until=780G --fill-pool=cache'], 70 * $G, 0, 20 * $G], [$calls, $n['plan']['back'] ?? null, $n['plan']['goes'] ?? null, $n['plan']['fill'] ?? null]);
    // not hired, a run of hers going: refused
    $v['hired'] = false;
    same('night run: she isn\'t hired — nothing', 1, nightRun(['run']));
    $v['hired'] = true;
    $v['busy'] = true;
    $exit = nightRun(['run']);
    same('night run: one of Jack Emby\'s own runs going — refused, in her list «night»', [1, 'refused', 'moverelli_jack_running', true],
        [$exit, moverelliHistory($dir)[0]['result'] ?? null, moverelliHistory($dir)[0]['why'] ?? null, moverelliHistory($dir)[0]['night'] ?? null]);
    $v['busy'] = false;

    // (6) the job: her line runs the night; her own part (--night) and the list go to Smart Mover directly
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/moverelli.php');
    check('night job: `job moverelli` = the night run; --night and list = Smart Mover', str_contains($src,
        "'moverelli' => fn (array \$args) => in_array('--night', \$args, true) || in_array('list', \$args, true) ? moverelliJob(\$args) : nightRun(\$args),"));
    // her part inside the night: by «night», no cap any more (only X), no gate wait
    unset($GLOBALS['nightHost']);
    $exit = moverelliJob(['run', '--night'], $h);
    same('night her part: ran, «by night», started by her schedule (no «--office»: «from» schedule)', [0, 'night', 'schedule'],
        [$exit, moverelliHistory($dir)[0]['by'] ?? null, moverelliHistory($dir)[0]['from'] ?? null]);
    // 2026-10-16: never «the night run» in her list — a joint run started on her page says «started here»
