    $GLOBALS['moverelliHost'] += ['zfs' => "$tmp/bin/zfs", 'asleep' => ['cache' => false, 'fast' => false], 'jack_list_file' => "$tmp/list.txt",
        'jack_cache' => fn () => "$tmp/mnt/cache", 'cron_file' => "$tmp/office.cron", 'cron_apply' => false];
    $on = false;                                              // … but not set up (no budget)
