/**
 * A share's folder on a ZFS pool (inbox #14; on Tower, 7.3.3: shfs makes <pool>/<share> with `zfs create` on a write through
 * /mnt/user and destroys it when the mover has emptied it; a mkdir straight on the pool is a plain folder in the pool's
 * dataset). Before a real fill Jack Streamer makes a missing one as a dataset, the way shfs does; a plain folder is named.
 */
function testJackShareDataset(): void
{
    $tmp = hardeningTmp('jack-share-dataset');
    @mkdir("$tmp/mnt/maple/Serien", 0700, true);
    @mkdir("$tmp/mnt/maple/Fotos", 0700, true);
    $cache = "$tmp/mnt/maple";
    $mounts = [['mount' => $cache, 'fs' => 'zfs', 'source' => 'maple'], ['mount' => "$cache/Fotos", 'fs' => 'zfs', 'source' => 'maple/Fotos'],
               ['mount' => "$tmp/mnt/bt", 'fs' => 'btrfs', 'source' => '/dev/sdx1']];
    same('share dataset: the pool\'s own dataset from the mounts — none on btrfs or a pool not mounted', ['maple', null, null],
        [jackPoolDataset($cache, $mounts), jackPoolDataset("$tmp/mnt/bt", $mounts), jackPoolDataset("$tmp/mnt/gone", $mounts)]);
    same('share dataset: a dataset mounted at the share\'s folder, or a plain folder', [true, false], [jackIsDataset("$cache/Fotos", $mounts), jackIsDataset("$cache/Serien", $mounts)]);
    same('share dataset: names ZFS takes as they are (a space too) — never a path, a dot or a dash first', [true, true, false, false, false, false],
        array_map('jackDatasetName', ['Filme', 'Home Videos', '../x', '.hidden', '-o', 'Fil/me']));

    // 1.65.0: ONE way the dataset is made — MediaCache's ensure_share_root() (create_share_root, Jack always writes it on),
    // never Jack before the run as well (his jackMakeShareDatasets() went); MediaCache's own tests (mediacache/tests) cover it
    $php = (string) file_get_contents(dirname(__DIR__) . '/agent/desks/jack.php');
    same('share dataset: Jack\'s settings always say create_share_root (MediaCache makes it, like Unraid)', true,
        jackTools(['create_share_root' => false])['create_share_root']);
    check('share dataset: Jack makes no dataset himself any more — one way only', !str_contains($php, 'jackMakeShareDatasets(') && !str_contains($php, "'zfs', 'create'"));
    $lib = (string) file_get_contents(OFFICE_DIR . '/mediacache/mediacache_lib.py');
    check('share dataset: MediaCache\'s ensure_share_root() makes it with zfs create, only where the share may use the pool',
        str_contains($lib, 'def ensure_share_root(') && str_contains($lib, '[ZFS_BIN, "create", name]') && str_contains($lib, 'SHARE_ROOT_OK_MODES'));
    [$exit, $out, $err] = run(['python3', '-I', '-B', '-m', 'unittest', 'discover', '-s', OFFICE_DIR . '/mediacache/tests'], 120);
    check('share dataset: MediaCache\'s own tests pass (share root on ZFS/btrfs/XFS, dry run, cleanup tools)', $exit === 0 && str_contains($out . $err, 'OK'), $out . $err);

    // his page and the Team Lead: «made at the next run» is no fault; a plain folder is a warning with the way to fix it by hand
    $js = (string) file_get_contents(dirname(__DIR__) . '/public/desks/jack/desk.js');
    check('share dataset: his page — «made at the next run» quiet, «not its own dataset» a warning, both counted right',
        str_contains($js, "(x.root === false && !x.auto) || x.dataset === false") && str_contains($js, "T('root_auto'") && str_contains($js, "T('root_plain'"));
    check('share dataset: the check share_dataset (recommended) and share_root without what he makes himself',
        str_contains($php, "finding('share_dataset', 'recommended'") && str_contains($php, "\$s['root'] === false && !\$s['auto']"));
    $mo = (string) file_get_contents(dirname(__DIR__) . '/public/desks/moverelli/desk.js');
    check('share dataset: Ms. Moverelli names the folders she counts as never moving', str_contains($mo, "T('setup.level_folders'"));

    // ZFS array disks: from the gather's numbers and the mount table only — a disk holding files of the share, ZFS, no dataset there
    $sizes = ['shares' => ['Filme' => ['roots' => ['disk1' => ['bytes' => 9, 'files' => 2], 'disk2' => ['bytes' => 9, 'files' => 1], 'disk3' => ['bytes' => 0, 'files' => 0],
              'disk4' => ['bytes' => 5, 'files' => 1], 'maple' => ['bytes' => 1, 'files' => 1]]]]];
    $dm = [['mount' => '/mnt/disk1', 'fs' => 'xfs', 'source' => '/dev/md1p1'], ['mount' => '/mnt/disk2', 'fs' => 'zfs', 'source' => 'disk2'],
           ['mount' => '/mnt/disk3', 'fs' => 'zfs', 'source' => 'disk3'], ['mount' => '/mnt/disk4', 'fs' => 'zfs', 'source' => 'disk4'],
           ['mount' => '/mnt/disk4/Filme', 'fs' => 'zfs', 'source' => 'disk4/Filme'], ['mount' => '/mnt/maple', 'fs' => 'zfs', 'source' => 'maple']];
    same('share dataset: plain folders on ZFS array disks — disk2 (xfs, empty, a dataset and a pool never)', [['disk2'], []],
        [jackPlainDisks('Filme', $sizes, $dm), jackPlainDisks('Serien', $sizes, $dm)]);
    check('share dataset: his page names those disks', str_contains($js, "T('disk_plain'") && str_contains($js, '(x.plain_disks || []).length > 0'));

    // the gather (V11.5): a cache-only folder to the disk with most free space — the share's missing folder on a ZFS disk is its dataset
    foreach (['mnt/disk1/Filme/A', 'mnt/disk2', 'mnt/cache/Filme/C', 'user/Filme', 'bin'] as $d) {
        @mkdir("$tmp/g/$d", 0700, true);
    }
    file_put_contents("$tmp/g/mnt/disk1/Filme/A/a.mkv", 'a');
    file_put_contents("$tmp/g/mnt/cache/Filme/C/c.mkv", str_repeat('c', 100));
    file_put_contents("$tmp/g/bin/df", "#!/bin/bash\necho Avail\ncase \"\$*\" in *disk2*) echo 999999999 ;; *) echo 5000000 ;; esac\n");
    file_put_contents("$tmp/g/bin/zfs", "#!/bin/bash\necho \"\$*\" >> '$tmp/g/zfs.log'\n[[ \$1 == create ]] && mkdir '$tmp/g/mnt/'\"\$2\"\n");
    chmod("$tmp/g/bin/df", 0755);
    chmod("$tmp/g/bin/zfs", 0755);
    file_put_contents("$tmp/g/mounts", "disk2 $tmp/g/mnt/disk2 zfs rw 0 0\n/dev/md1p1 $tmp/g/mnt/disk1 xfs rw 0 0\n");
    file_put_contents("$tmp/g/ex.txt", '');
    $ini = jackGatherIni(['shares' => ['Filme'], 'dup_check' => 'size', 'min_free_gb' => 0, 'move_cache' => true, 'cache_only_target' => 'most-free'], ['/mnt/cache'], "$tmp/g/c.log", "$tmp/g/ex.txt");
    file_put_contents("$tmp/g/c.ini", str_replace(["'/mnt/user/", "'/mnt/"], ["'$tmp/g/user/", "'$tmp/g/mnt/"], $ini));
    $env = ['PATH' => "$tmp/g/bin:/usr/bin:/bin", 'HOME' => $tmp, 'LANG' => 'C.UTF-8', 'CONSOLIDATE_CONFIG' => "$tmp/g/c.ini", 'CONSOLIDATE_STATUS' => "$tmp/g/status.json",
            'CONSOLIDATE_LOCK' => "$tmp/g/gather.lock", 'CONSOLIDATE_USER_ROOT' => "$tmp/g/user", 'CONSOLIDATE_MOUNTS' => "$tmp/g/mounts", 'CONSOLIDATE_ZFS' => "$tmp/g/bin/zfs"];
    $p = proc_open(['bash', OFFICE_DIR . '/gather/consolidate_master.sh', '--run'], [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, $tmp, $env);
    $out = stream_get_contents($pipes[1]) . stream_get_contents($pipes[2]);
    $exit = proc_close($p);
    same('share dataset: the gather makes the share\'s folder on a ZFS disk as its dataset (zfs create disk2/Filme), the file lands in it',
        [0, "create disk2/Filme\n", true], [$exit, (string) @file_get_contents("$tmp/g/zfs.log"), is_file("$tmp/g/mnt/disk2/Filme/C/c.mkv")], $out);
    hardeningRm($tmp);
}

/**
 * Jack Streamer's files outside the movable shares' datasets (a user's report from 1.63.0, 2026-10-15): his media share not
 * movable («no» — or «yes» but its folder on the pool not a dataset of its own, made by his first copy). Before, his bytes
 * were capped at M: «Jack Streamer» only what lay in a movable dataset (11 GB new), his earlier files in «appdata & co.»,
 * the other shares 0. Now all of his list counts as his, taken out of what never moves; the others are M less his part in M.
 */
function testPoolJackOutside(): void
{
    $tmp = hardeningTmp('pool-jack-outside');
    foreach (["$tmp/shares", "$tmp/mnt/cache/Filme/A", "$tmp/mnt/cache/Serien/S", "$tmp/mnt/cache/Downloads"] as $d) {
        @mkdir($d, 0700, true);
    }
    file_put_contents("$tmp/shares/Downloads.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\n");
    file_put_contents("$tmp/shares/appdata.cfg", "shareUseCache=\"only\"\nshareCachePool=\"cache\"\n");
    $list = '';
    foreach (['Filme/A/old1.mkv' => 30000, 'Filme/A/old2.mkv' => 20000, 'Serien/S/new.mkv' => 1100] as $f => $n) {
        file_put_contents("$tmp/mnt/cache/$f", str_repeat('x', $n));
        $list .= "$tmp/mnt/cache/$f\n";
    }
    file_put_contents("$tmp/list.txt", $list);
    $bytes = fn (string $f): int => poolLevelFileBytes((int) filesize("$tmp/mnt/cache/$f"), (int) stat("$tmp/mnt/cache/$f")['blocks']);
    $old = $bytes('Filme/A/old1.mkv') + $bytes('Filme/A/old2.mkv');
    $new = $bytes('Serien/S/new.mkv');
    // the pool: 1 000 000 used; Serien and Downloads datasets (refer 1100 + 5000), Filme a plain folder (in the pool's own refer)
    $zfs = fn (string $sets) => "#!/bin/bash\nprintf 'cache\\t1000000\\t1000000\\t60000\\t0\\ncache/appdata\\t900000\\t1000000\\t900000\\t0\\n$sets'\n";
    file_put_contents("$tmp/zfs", $zfs('cache/Serien\\t1100\\t1000000\\t1100\\t0\\ncache/Downloads\\t5000\\t1000000\\t5000\\t0\\n'));
    chmod("$tmp/zfs", 0700);
    $o = ['x' => 70, 'shares_dir' => "$tmp/shares", 'names' => ['Filme', 'Serien', 'Downloads', 'appdata'], 'zfs' => "$tmp/zfs",
          'mnt' => "$tmp/mnt", 'jack_list' => "$tmp/list.txt", 'asleep' => []];
    $pick = fn (?array $l): array => [$l['jack'] ?? null, $l['others'] ?? null, $l['nm'] ?? null, ($l['nm'] ?? 0) + ($l['jack'] ?? 0) + ($l['others'] ?? 0)];

    // Filme «no» (not movable, a plain folder), Serien «yes» (a dataset): all of his list is his
    file_put_contents("$tmp/shares/Filme.cfg", "shareUseCache=\"no\"\n");
    file_put_contents("$tmp/shares/Serien.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\n");
    $l = poolLevel('cache', $o);
    same('pool jack outside: his media share «no» — his earlier files are his (not «appdata & co.»), the others = M less his part in M, all adds up to used',
        [$old + $new, 6100 - $new, 1000000 - 6100 - $old, 1000000], $pick($l));
    $pic = nightPicture($l);
    same('pool jack outside: the night picture — Jack Streamer all of his list, the other cache shares 5000-ish, never 0',
        [$old + $new, 6100 - $new], [$pic['jack'], $pic['others']]);

    // Filme «yes» but its folder not a dataset of its own (his first copy made it): the same
    file_put_contents("$tmp/shares/Filme.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\n");
    same('pool jack outside: his share movable but its folder no dataset — the same numbers', $pick($l), $pick(poolLevel('cache', $o)));
    same('pool jack outside: her page is told which movable share\'s folder is no dataset of its own (inbox #14)', [['Filme'], ['Downloads', 'Filme', 'Serien']],
        [poolLevel('cache', $o)['folders'] ?? null, poolLevel('cache', $o)['shares'] ?? null]);

    // Filme a dataset of its own (as on a pool Unraid set up): his bytes in M, nothing outside — as before
    file_put_contents("$tmp/zfs", $zfs('cache/Filme\\t' . $old . '\\t1000000\\t' . $old . '\\t0\\ncache/Serien\\t1100\\t1000000\\t1100\\t0\\ncache/Downloads\\t5000\\t1000000\\t5000\\t0\\n'));
    $l = poolLevel('cache', $o);
    same('pool jack outside: his share a movable dataset — all in M, nothing outside, the others the downloads', [$old + $new, 6100 - $new, 0], [$l['jack'], $l['others'], $l['jack_out']]);
    same('pool jack outside: every movable share a dataset — no folder named', [], $l['folders']);

    // the pure math: more of his than M lies outside; never more than what never moves
    $m = poolLevelMath(1000, 900, 100, 70, 150, 0);
    same('pool jack outside (math): his 150 over M 100 — 50 taken out of what never moves; outside never above what never moves',
        [[150, 0, 750], [800, 100, 0]], [[$m['jack'], $m['others'], $m['nm']], [poolLevelMath(1000, 900, 100, 70, 0, 5000)['jack'], poolLevelMath(1000, 900, 100, 70, 0, 5000)['others'], poolLevelMath(1000, 900, 100, 70, 0, 5000)['nm']]]);
    hardeningRm($tmp);
}

/**
 * A btrfs or XFS pool (2026-10-15): poolLevel() measures it too — size/used from statfs as df counts them, M = the du of
 * the movable shares' folders, no snapshots counted, `estimated` with `measured_at`. The du runs only in the night run
 * (measure 'night') and in the background job (at most once an hour, asked by a page or a check finding the stored value
 * missing or older than an hour); pages and checks use the stored value (her data folder). A ZFS pool exactly as before.
 */
function testPoolNonZfs(): void
{
    $tmp = hardeningTmp('pool-nonzfs');
    foreach (["$tmp/shares", "$tmp/bin", "$tmp/mnt/cache/Filme/A", "$tmp/mnt/cache/Downloads", "$tmp/mnt/cache/appdata"] as $d) {
        @mkdir($d, 0700, true);
    }
    file_put_contents("$tmp/shares/Filme.cfg", "shareUseCache=\"yes\"\nshareCachePool=\"cache\"\n");
    file_put_contents("$tmp/shares/Downloads.cfg", "shareUseCache=\"yes\"\n");
    file_put_contents("$tmp/shares/Serien.cfg", "shareUseCache=\"prefer\"\nshareCachePool=\"cache\"\n");
    file_put_contents("$tmp/shares/appdata.cfg", "shareUseCache=\"only\"\nshareCachePool=\"cache\"\n");
    file_put_contents("$tmp/mnt/cache/Filme/A/a.mkv", str_repeat('a', 9000));
    file_put_contents("$tmp/list.txt", "$tmp/mnt/cache/Filme/A/a.mkv\n");
    $his = poolLevelFileBytes(9000, (int) stat("$tmp/mnt/cache/Filme/A/a.mkv")['blocks']);
    // statfs as df: 4096-byte blocks, 1 000 000 of them, 600 000 free, 590 000 available (btrfs/xfs keep some back)
    $stat = fn (string $fs) => file_put_contents("$tmp/bin/stat", "#!/bin/bash\necho stat >> $tmp/asked\necho '$fs 4096 1000000 600000 590000'\n");
    $du = fn (string $body) => file_put_contents("$tmp/bin/du", "#!/bin/bash\necho \"\${@: -1}\" >> $tmp/du-asked\n$body\n");
    $duOk = 'case "${@: -1}" in */Filme) echo "300000000 x";; */Downloads) echo "100000000 x";; *) exit 1;; esac';
    $stat('btrfs');
    $du($duOk);
    chmod("$tmp/bin/stat", 0755);
    chmod("$tmp/bin/du", 0755);
    file_put_contents("$tmp/bin/zfs", "#!/bin/bash\nexit 1\n");
    chmod("$tmp/bin/zfs", 0755);
    $launched = [];
    $store = "$tmp/data/moverelli/pool-du.json";
    $o = ['x' => 80, 'shares_dir' => "$tmp/shares", 'names' => ['Filme', 'Downloads', 'Serien', 'appdata'], 'zfs' => "$tmp/bin/zfs", 'mnt' => "$tmp/mnt",
          'jack_list' => "$tmp/list.txt", 'asleep' => [], 'stat' => "$tmp/bin/stat", 'du' => "$tmp/bin/du", 'du_cache' => $store,
          'du_launch' => function (string $pool) use (&$launched): void { $launched[] = $pool; }];
    $duAsked = function () use ($tmp): int { $n = is_file("$tmp/du-asked") ? count(file("$tmp/du-asked")) : 0; @unlink("$tmp/du-asked"); return $n; };
    $size = 4096 * (400000 + 590000);
    $used = 4096 * 400000;
    $pick = fn (?array $l): array => [$l['size'] ?? null, $l['used'] ?? null, $l['movable'] ?? null, $l['nm'] ?? null, $l['jack'] ?? null, $l['others'] ?? null,
        $l['snapshots'] ?? null, $l['estimated'] ?? null, $l['fs'] ?? null, $l['folders'] ?? null];
    $want = [$size, $used, 400000000, $used - 400000000, $his, 400000000 - $his, 0, true, 'btrfs', []];

    // a page or a check before the first du: not measured yet, du never run there, the background job asked once an hour
    $first = [poolLevel('cache', $o), poolLevelWaiting('cache', $o), poolLevel('cache', $o)];
    same('pool non-zfs: before the first du — not measured (null), waiting; the page runs no du; the background job asked once (not again within the hour)',
        [null, true, null, 0, ['cache']], [...$first, $duAsked(), $launched]);

    // the background job: measured and stored in her data folder
    $job = poolLevelDuJob('cache', $o);
    $launched = [];
    $l = poolLevel('cache', $o);
    same('pool non-zfs (btrfs): the background job measures Filme and Downloads (Serien has no folder: 0, appdata never) and stores them; the page then: size = used + avail, used = blocks − free (as df), Jack Streamer from his list, no snapshots, estimated — no du, no job asked',
        [0, 2, $want, false, [], 0], [$job, $duAsked(), $pick($l), poolLevelWaiting('cache', $o), $launched, $duAsked()]);
    same('pool non-zfs: the stored du\'s time on the level (measured_at), in her data folder', [true, true],
        [abs(($l['measured_at'] ?? 0) - time()) <= 2, is_int((readJson($store)['pools']['cache']['at'] ?? null))]);
    $pic = nightPicture($l);
    same('pool non-zfs: the night picture — no snapshot part (all in fixed), the parts add up to the size', [null, $size],
        [$pic['snapshots'], $pic['fixed'] + $pic['others'] + $pic['jack'] + $pic['free']]);
    $plan = nightPlan($l, 0);
    same('pool non-zfs: the plan is measured, X 80 % — nothing must go', [true, 0, false], [$plan['measured'], $plan['need'], $plan['over']]);

    // older than an hour: the page still shows it (with its age) and asks the job — once an hour
    $d = readJson($store);
    $d['pools']['cache']['at'] = time() - 4000;
    $d['asked']['cache'] = time() - 4000;
    file_put_contents($store, json_encode($d));
    $old = [poolLevel('cache', $o), poolLevel('cache', $o)];
    same('pool non-zfs: a stored du older than an hour — still used (its age on the level), the job asked once, no du on the page',
        [$want, time() - 4000, ['cache'], 0], [$pick($old[1]), $old[0]['measured_at'] ?? null, $launched, $duAsked()]);

    // the night measures now (and stores it)
    $launched = [];
    $n = poolLevel('cache', ['measure' => 'night'] + $o);
    same('pool non-zfs: the night run measures the folders now and stores them', [$want, 2, true, []],
        [$pick($n), $duAsked(), (readJson($store)['pools']['cache']['at'] ?? 0) >= time() - 2, $launched]);

    // a du that fails: the night not measured, the job stores nothing — never a wrong M
    $du('exit 1');
    $before = readJson($store)['pools'] ?? null;
    same('pool non-zfs: a du that fails — the night not measured, the job 1 and nothing stored', [null, 1, true],
        [poolLevel('cache', ['measure' => 'night'] + $o), poolLevelDuJob('cache', $o), (readJson($store)['pools'] ?? 0) === $before]);
    $du($duOk);
    // a stored value from the future, or a share made movable since (a folder not in it): not believed — waiting again
    $d = readJson($store);
    $d['pools']['cache']['at'] = time() + 999;
    file_put_contents($store, json_encode($d));
    $future = poolLevel('cache', $o);
    poolLevelDuJob('cache', $o);
    @mkdir("$tmp/mnt/cache/Serien");
    same('pool non-zfs: a stored du from the future, or a new movable folder not in it — not measured', [null, null, true],
        [$future, poolLevel('cache', $o), poolLevelWaiting('cache', $o)]);
    rmdir("$tmp/mnt/cache/Serien");
    $duAsked();

    // XFS the same; anything else (ZFS seen through statfs, tmpfs, not mounted) — not measured, never waiting
    $stat('xfs');
    $x = poolLevel('cache', ['measure' => 'night'] + $o);
    same('pool non-zfs (xfs): the same numbers, fs xfs', [$size, $used, 400000000, 'xfs'], [$x['size'] ?? null, $x['used'] ?? null, $x['movable'] ?? null, $x['fs'] ?? null]);
    $none = [];
    foreach (['tmpfs', 'zfs'] as $fs) {
        $stat($fs);
        $none[] = [poolLevel('cache', ['measure' => 'night'] + $o), poolLevelWaiting('cache', $o)];
    }
    same('pool non-zfs: tmpfs or zfs by statfs (zfs list said nothing) — not measured, not waiting', [[null, false], [null, false]], $none);
    // asleep: not looked at, statfs not asked, the job does nothing
    $stat('btrfs');
    @unlink("$tmp/asked");
    $duAsked();
    same('pool non-zfs: asleep — not looked at, nothing asked; the job leaves it', [null, false, 1, 0],
        [poolLevel('cache', ['asleep' => ['cache' => true]] + $o), is_file("$tmp/asked"), poolLevelDuJob('cache', ['asleep' => ['cache' => true]] + $o), $duAsked()]);

    // the destination: a btrfs secondary pool's size and use from statfs
    same('pool non-zfs: statfs of a destination pool', ['fs' => 'btrfs', 'size' => $size, 'used' => $used], poolLevelStatfs("$tmp/mnt/cache", "$tmp/bin/stat"));

    // her desk: the du stored in her data folder
    $GLOBALS['moverelliHost'] = ['dir' => "$tmp/data/moverelli"];
    same('pool non-zfs: her host keeps the du in her data folder', $store, moverelliHost()['du_cache']);
    unset($GLOBALS['moverelliHost']);

    // ZFS exactly as before: the same keys, statfs, du and the job never asked
    file_put_contents("$tmp/bin/zfs", "#!/bin/bash\nprintf 'cache\\t60000\\t40000\\t100\\t0\\ncache/Filme\\t9000\\t40000\\t7000\\t2000\\n'\n");
    @unlink("$tmp/asked");
    @unlink($store);
    $launched = [];
    $z = [poolLevel('cache', $o), poolLevel('cache', ['measure' => 'night', 'wake' => true] + $o)];
    same('pool non-zfs: a ZFS pool — no estimated/fs/measured_at key, statfs, du and the job never asked, nothing stored, the numbers from zfs list',
        [false, false, false, false, 0, [], false, 100000, 60000, 7000, 2000, true],
        [isset($z[0]['estimated']), isset($z[0]['fs']), isset($z[0]['measured_at']), is_file("$tmp/asked"), $duAsked(), $launched, is_file($store),
         $z[0]['size'], $z[0]['used'], $z[0]['movable'], $z[0]['snapshots'], $z[0] === $z[1]]);
    same('pool non-zfs: a ZFS pool\'s keys as in 1.64.0', ['pool', 'shares', 'folders', 'snapshots', 'snap_all', 'jack_logical', 'snap_pct', 'size', 'used', 'movable', 'nm', 'x', 'xb', 'jack',
        'jack_out', 'others', 'need', 'used_pct', 'nm_pct', 'never', 'jack_over', 'free', 'y', 'k', 'room', 'half', 'half_d', 'back', 'goes', 'downloads'], array_keys($z[0]));
    hardeningRm($tmp);
}

/**
 * The snapshots apart in her picture (owner, 2026-10-15, release 1.63.1): ZFS's usedbysnapshots of the pool's own dataset
 * and every one directly below it (poolLevelLook()'s snap_all, the same zfs list) as their own black part after «appdata &
 * co.» (fixed less them, never below 0); no figure (btrfs, xfs, an older night.json) — no part, no legend line, all in fixed.
 */
function testNightSnaps(): void
{
    $G = 1 << 30;
    $tmp = hardeningTmp('night-snaps');
    file_put_contents("$tmp/zfs", "#!/bin/bash\nprintf 'cache\\t60000\\t40000\\t100\\t300\\ncache/appdata\\t9000\\t40000\\t7000\\t500\\ncache/Filme\\t3000\\t40000\\t2000\\t1000\\n'\n");
    chmod("$tmp/zfs", 0700);
    $look = poolLevelLook('cache', ['Filme'], "$tmp/zfs");
    same('night snaps: the same zfs list — the shares\' snapshots as before (1000), all of the pool\'s (300 + 500 + 1000)', [1000, 1800], [$look['snapshots'] ?? null, $look['snap_all'] ?? null]);
    $lv = ['size' => 1000 * $G, 'used' => 850 * $G, 'nm' => 300 * $G, 'others' => 150 * $G, 'jack' => 400 * $G, 'x' => 80, 'used_pct' => 85.0, 'need' => 50 * $G, 'never' => false];
    $p = nightPicture(['snap_all' => 40 * $G] + $lv);
    $plan = nightPlan(['snap_all' => 40 * $G] + $lv, 60 * $G);
    same('night snaps: the picture — appdata & co. 260, snapshots 40 (before and forecast); the plan\'s numbers as without; his reserve against both (X − 300)',
        [260 * $G, 40 * $G, 260 * $G, 40 * $G, nightPlan($lv, 60 * $G)['until'], nightPictureReserve(nightPlan($lv, 60 * $G), 450 * $G)['before']['jack_reserve']],
        [$p['fixed'], $p['snapshots'], $plan['forecast']['fixed'], $plan['forecast']['snapshots'], $plan['until'], nightPictureReserve($plan, 450 * $G)['before']['jack_reserve']]);
    same('night snaps: more snapshots than what never moves — capped (fixed 0); none (non-ZFS) or junk — null, all in fixed',
        [[0, 300 * $G], [300 * $G, null], [300 * $G, null]],
        array_map(fn ($x) => [nightPicture($x + $lv)['fixed'], nightPicture($x + $lv)['snapshots']], [['snap_all' => 900 * $G], [], ['snap_all' => 'x']]));
    $css = (string) file_get_contents(OFFICE_WEB . '/desks/moverelli/desk.css');
    check('night snaps: their part black with a fine light edge (seen on a dark theme, apart from the other shares on a light one), no colour of its own beyond the theme\'s',
        (bool) preg_match('/\.mo-seg-snaps\{background:color-mix\(in srgb, var\(--black, #000\) \d+%, var\(--text-color\)\); box-shadow:inset 0 0 0 1px color-mix\(in srgb, var\(--on-fill\)/', $css));

    $node = testsNode();
    if ($node === '') {
        check('night snaps (page): node is missing here - skipped', true);
        hardeningRm($tmp);
        return;
    }
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const mk = (tag, cls, text) => ({ tag, cls, text, textContent: text == null ? '' : String(text), children: [], hidden: false, disabled: false, dataset: {}, style: {}, attrs: {},
  set innerHTML(v) { this.children = []; }, append(...c) { this.children.push(...c); }, appendChild(c) { this.children.push(c); return c; },
  setAttribute(k, v) { this.attrs[k] = v; }, querySelector: () => null, querySelectorAll: () => [] });
globalThis.document = { createTextNode: (t) => t };
globalThis.Office = { sections: () => ({}), scope: () => T, t: T, el: mk, fmt: { size: (b) => Math.round(b / 1073741824) + ' GiB', number: (n, d) => n.toFixed(d), relative: (t) => 'R' + t, cron: (c) => c, time: (t) => t, duration: (s) => s },
  desk: () => {}, places: () => {}, placesFrom: () => {}, store: () => null, agent: { running: true }, place: (k, n) => n, go: () => {}, sectionHead: () => mk('h'),
  runSteps: () => mk('div'), runBar: () => mk('div'), runRate: () => null, nightSteps: () => [], nightCard: () => mk('div', 'card') };
for (const f of process.argv.slice(2)) (0, eval)(fs.readFileSync(f, 'utf8'));
const m = OFFICE_DESK_TESTS.moverelli;
const texts = (n) => (typeof n === 'string' ? [n] : [n.textContent, ...n.children.flatMap(texts)].filter(Boolean));
const G = 1073741824;
const B = (fixed, snaps, others, jack, free) => ({ size: 1000 * G, fixed: fixed * G, snapshots: snaps == null ? snaps : snaps * G, others: others * G, jack: jack * G, free: free * G });
const pic = (before, forecast) => ({ pool: 'cache', x: 80, dest: { to: 'array', size: 8000 * G, used: 2000 * G }, phases: { check: { before, forecast } }, files: [] });
const sum = (b) => Math.round(b.segs.reduce((a, s) => a + s.w, 0) * 1e9) / 1e9;
const out = {};
const d = m.pictureBars(pic(B(260, 40, 150, 400, 150), B(260, 40, 90, 410, 200)), 800, false);
out.bars = [d.before.segs.map((s) => [s.k, s.bytes / G]), d.after.segs.map((s) => s.bytes / G), d.before.used / G, sum(d.before), sum(d.after)];
const thin = m.pictureBars(pic(B(299.8, 0.2, 150, 400, 150)), 800, false);
out.thin = [thin.before.segs[0].w >= 10 / 800 - 1e-12, sum(thin.before)];
const none = m.pictureBars(pic(B(300, null, 150, 400, 150)), 800, false);
out.none = [none.before.snaps, none.before.segs[0].bytes, none.before.segs[0].w];
const legend = (p) => texts(m.nightPicture({ running: true, jack: true, started: Math.random(), picture: p })).filter((t) => /^pic\.seg\.(snaps|fixed)/.test(t));
out.legend = legend(pic(B(260, 40, 150, 400, 150), B(260, 40, 90, 410, 200)));
out.legendNone = legend(pic(B(300, null, 150, 400, 150), B(300, null, 90, 410, 200)));
out.undef = /undefined|NaN/.test(JSON.stringify(out));
console.log(JSON.stringify(out));
JS);
    [, $out, $err] = run([$node, "$tmp/t.js", testsNightHelpersJs($tmp), OFFICE_WEB . '/desks/moverelli/desk.js'], 30);
    $j = json_decode(trim((string) $out), true) ?? [];
    check('night snaps (page): it runs', $j !== [], $out . $err);
    same('night snaps (page): snapshots | appdata & co. | other shares | Jack Streamer … — both bars, the used part with them, each sums to 1',
        [[['snaps', 40], ['fixed', 260], ['others', 150], ['jack', 400], ['watched', 0], ['reserve', 0], ['free', 150]], [40, 260, 90, 410, 0, 0, 200], 850, 1, 1], $j['bars'] ?? null);
    same('night snaps (page): a tiny snapshot part keeps 10 px, still 1', [true, 1], $j['thin'] ?? null);
    same('night snaps (page): no figure (not ZFS) — no part', [null, 0, 0], $j['none'] ?? null);
    same('night snaps (page): the legend — «appdata & co.» and «Snapshots 40 GiB» apart; without a figure no snapshots line',
        [['pic.seg.snaps pic.change {"before":"40 GiB","after":"40 GiB"}', 'pic.seg.fixed pic.change {"before":"260 GiB","after":"260 GiB"}'], ['pic.seg.fixed pic.change {"before":"300 GiB","after":"300 GiB"}']],
        [$j['legend'] ?? null, $j['legendNone'] ?? null]);
    check('night snaps (page): no «undefined» or NaN', ($j['undef'] ?? true) === false, (string) $out);
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $lang = readJson(OFFICE_WEB . "/desks/moverelli/lang/$l.json") ?? [];
        check("night snaps lang $l: «appdata & co.» without the snapshots, the snapshots' own name",
            str_starts_with($lang['pic.seg.fixed'] ?? '', 'appdata') && !preg_match('/snap|instant/i', $lang['pic.seg.fixed'] ?? '') && ($lang['pic.seg.snaps'] ?? '') !== '');
    }
    hardeningRm($tmp);
}

/**
 * His reserved room in her picture (owner + helmi1987, 2026-10-15): jack_reserve = min(his budget, X − fixed) − his part
 * in both bars, hatched after his part (drawn out of the free part, 10 px kept), legend «Jack Streamer reserves … (his
 * budget)»; no budget — no reserve; what waits unknown (no run of his yet) — the forecast fills his reserve, «forecast
 * without his last run»; the plan's own numbers never change for it.
 */
function testNightReserve(): void
{
    $G = 1 << 30;
    $lv = ['size' => 1000 * $G, 'used' => 850 * $G, 'nm' => 300 * $G, 'others' => 150 * $G, 'jack' => 400 * $G, 'x' => 80, 'used_pct' => 85.0, 'need' => 50 * $G, 'never' => false];
    $plan = nightPlan($lv, 60 * $G);
    $r = nightPictureReserve($plan, 450 * $G);
    same('night reserve: budget 450 under X (room 500) — before 450 − 400 = 50, after his fetch of 60 none left; the plan\'s numbers as they were',
        [50 * $G, 0, 460 * $G, false, $plan['jack_fetch'], $plan['until']],
        [$r['before']['jack_reserve'], $r['forecast']['jack_reserve'], $r['forecast']['jack'], $r['forecast']['assumed'] ?? false, $r['jack_fetch'], $r['until']]);
    $big = nightPictureReserve($plan, 900 * $G);
    same('night reserve: a budget bigger than the room under X — capped at X − fixed (500): before 100, after 40', [100 * $G, 40 * $G],
        [$big['before']['jack_reserve'], $big['forecast']['jack_reserve']]);
    $none = nightPictureReserve($plan, null);
    same('night reserve: no budget — no reserve (null), no forecast assumed', [null, null, false], [$none['before']['jack_reserve'], $none['forecast']['jack_reserve'], $none['forecast']['assumed'] ?? false]);
    $plan0 = nightPlan($lv, 0);
    $as = nightPictureReserve($plan0, 450 * $G, false);
    same('night reserve: what waits unknown — the forecast fills his reserve (400 + 50), the others down to the room left (50), free what is left, marked assumed; the plan keeps 0 fetch',
        [450 * $G, 50 * $G, 200 * $G, true, 0, 0],
        [$as['forecast']['jack'], $as['forecast']['others'], $as['forecast']['free'], $as['forecast']['assumed'] ?? false, $as['forecast']['jack_reserve'], $as['jack_fetch']]);
    same('night reserve: unknown but no budget — nothing assumed (the forecast as reckoned)', [false, $plan0['forecast']['jack']],
        [nightPictureReserve($plan0, null, false)['forecast']['assumed'] ?? false, nightPictureReserve($plan0, null, false)['forecast']['jack']]);
    same('night reserve: no X — the room is the pool less fixed (700), less his 400', 300 * $G, nightPictureReserve(nightPlan(['x' => 0] + $lv, 0), 900 * $G)['before']['jack_reserve']);
    same('night reserve: a plan not measured — as it was', nightPlan(null), nightPictureReserve(nightPlan(null), 450 * $G, false));
    $known = fn ($st) => nightWaitKnown(['jack_status' => fn () => $st]);
    same('night reserve: what waits known only from his last status\'s number', [true, false, false, false],
        [$known(['pool' => ['waiting_bytes' => 0]]), $known(['pool' => []]), $known([]), $known(['pool' => ['waiting_bytes' => '5']])]);
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/lib/nightrun.php');
    check('night reserve: every phase\'s picture goes through it (the check, the phases, done never assumed)',
        str_contains($src, "'phases' => ['check' => \$pic(\$plan)]") && str_contains($src, "\$pic(\$p, \$ph === 'done')"));

    $node = testsNode();
    if ($node === '') {
        check('night reserve (page): node is missing here - skipped', true);
        return;
    }
    $tmp = hardeningTmp('night-reserve');
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const mk = (tag, cls, text) => ({ tag, cls, text, textContent: text == null ? '' : String(text), children: [], hidden: false, disabled: false, dataset: {}, style: {}, attrs: {},
  set innerHTML(v) { this.children = []; }, append(...c) { this.children.push(...c); }, appendChild(c) { this.children.push(c); return c; },
  setAttribute(k, v) { this.attrs[k] = v; }, querySelector: () => null, querySelectorAll: () => [] });
globalThis.document = { createTextNode: (t) => t };
globalThis.Office = { sections: () => ({}), scope: () => T, t: T, el: mk, fmt: { size: (b) => Math.round(b / 1073741824) + ' GiB', number: (n, d) => n.toFixed(d), relative: (t) => 'R' + t, cron: (c) => c, time: (t) => t, duration: (s) => s },
  desk: () => {}, places: () => {}, placesFrom: () => {}, store: () => null, agent: { running: true }, place: (k, n) => n, go: () => {}, sectionHead: () => mk('h'),
  runSteps: () => mk('div'), runBar: () => mk('div'), runRate: () => null, nightSteps: () => [], nightCard: () => mk('div', 'card') };
for (const f of process.argv.slice(2)) (0, eval)(fs.readFileSync(f, 'utf8'));
const m = OFFICE_DESK_TESTS.moverelli;
const texts = (n) => (typeof n === 'string' ? [n] : [n.textContent, ...n.children.flatMap(texts)].filter(Boolean));
const G = 1073741824;
const B = (fixed, others, jack, free, reserve) => ({ size: 1000 * G, fixed: fixed * G, others: others * G, jack: jack * G, free: free * G, jack_reserve: reserve == null ? reserve : reserve * G });
const pic = (before, forecast) => ({ pool: 'cache', x: 80, dest: { to: 'array', size: 8000 * G, used: 2000 * G }, phases: { check: { before, forecast } }, files: [] });
const sum = (b) => Math.round(b.segs.reduce((a, s) => a + s.w, 0) * 1e9) / 1e9;
const out = {};
const d = m.pictureBars(pic(B(300, 150, 400, 150, 50), B(300, 90, 410, 200, 40)), 800, false);
out.bars = [d.before.segs.map((s) => [s.k, s.bytes / G]), d.after.segs.map((s) => s.bytes / G), d.before.reserve / G, sum(d.before), sum(d.after)];
const wide = m.pictureBars(pic(B(300, 150, 400, 150, 300)), 800, false);
out.wide = [wide.before.segs.map((s) => s.bytes / G), wide.before.reserve / G, sum(wide.before)];
const thin = m.pictureBars(pic(B(300, 150, 400, 150, 0.2)), 375, false);
out.thin = [thin.before.segs[5].w >= 10 / 375 - 1e-12, sum(thin.before)];
const none = m.pictureBars(pic(B(300, 150, 400, 150, null), B(300, 90, 410, 200, null)), 800, false);
const junk = m.pictureBars(pic({ ...B(300, 150, 400, 150), jack_reserve: 'x' }), 800, false);
out.none = [none.before.reserve, none.before.segs[5].bytes, none.before.segs[5].w, junk.before.reserve];
const legend = (p) => texts(m.nightPicture({ running: true, jack: true, started: Math.random(), picture: p })).filter((t) => /^pic\.(reserve|assumed)/.test(t));
out.legend = legend(pic(B(300, 150, 400, 150, 50), B(300, 90, 410, 200, 40)));
out.legendSame = legend(pic(B(300, 150, 400, 150, 50), B(300, 90, 410, 200, 50)));
out.legendNone = legend(pic(B(300, 150, 400, 150, null), B(300, 90, 410, 200, null)));
out.assumed = legend(pic(B(300, 150, 400, 150, 50), { ...B(300, 50, 450, 200, 0), assumed: true }));
out.undef = JSON.stringify(out).includes('undefined') || JSON.stringify(out).includes('NaN');
console.log(JSON.stringify(out));
