        [$j['legend'] ?? null, $j['legendSame'] ?? null, $j['legendNone'] ?? null, $j['assumed'] ?? null]);
    check('night reserve (page): no «undefined» or NaN', ($j['undef'] ?? true) === false, (string) $out);
