    file_put_contents("$dir/status.json", json_encode(['result' => 'running', 'phase' => 'share', 'share' => 'Downloads', 'share_files' => 12, 'share_done_files' => 5, 'pid' => 1]));
    $a = jackNightNow($dir, true);
