const left = (p) => (p.eta === null ? null : Math.round(p.eta - now));
const out = {};
const plan = (more) => ({ planned: [{ id: 'p1', unit: 'place' }, { id: 'p1', unit: 'vm:win' }], done: [], skipped: [], failed: [], current: null, ...more });
b.setState(st('snapshots', plan()));
let p = b.progress();
out.snapshots = [left(p), p.percent];
b.setState(st('snapshots', null));
out.noPartner = left(b.progress());
b.setState(st('snapshots', plan({ planned: [{ id: 'p1', unit: 'place' }, { id: 'p1', unit: 'share:new' }] })));
p = b.progress();
out.never = [p.eta, p.percent, p.restEta === null ? null : Math.round(p.restEta - now)];
b.setState(st('inventory', plan({ planned: [], partners: [{ id: 'p1', name: 'Office B' }] })));
out.inventory = left(b.progress());
b.setState(st('inventory', plan({ planned: [], partners: [{ id: 'p9', name: 'New office' }] })));
p = b.progress();
out.inventoryNew = [p.eta, p.restEta === null ? null : Math.round(p.restEta - now)];
b.setState(st('partner', plan({ done: [{ id: 'p1', unit: 'place' }], current: { id: 'p1', unit: 'vm:win', since: now - 200, bytes: 1 } })));
out.partnerNoRate = left(b.progress());
b.setState(st('partner', plan({ done: [{ id: 'p1', unit: 'place' }], current: { id: 'p1', unit: 'vm:win', since: now - 900, bytes: 1 } })));
p = b.progress();
out.partnerLate = [left(p), p.overdue];
b.setState(st('partner', plan({ planned: [{ id: 'p1', unit: 'share:new' }], current: { id: 'p1', unit: 'share:new', since: now - 30, bytes: 1 } })));
p = b.progress();
out.partnerFirst = [p.eta, p.percent, p.restEta === null ? null : Math.round(p.restEta - now)];
b.setState(st('snapshots', plan({ planned: [{ id: 'p1', unit: 'share:new' }] })));
out.bubble = b.bubbleText('main').filter((x) => x.startsWith('bubble.eta'));
b.setState(st('partner', plan({ current: { id: 'p1', unit: 'place', since: now - 10, bytes: 1 } }),
  { partners: [{ id: 'p1', current: { unit: 'place', rate: 1000, eta: 40 } }] }));
out.partnerRate = left(b.progress());
console.log(JSON.stringify(out));
JS;
    file_put_contents("$tmp/eta.js", $js);
    $r = json_decode((string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/eta.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/backup/desk.js') . ' 2>&1'), true);
    same('partner eta (page): in the step Snapshots the partner units count — 270 before + 30 + 500 + Kopia 100, 10 %', [900, 10], $r['snapshots'] ?? null);
    same('partner eta (page): a run without partners — before + Kopia as ever', 370, $r['noPartner'] ?? null);
    same('partner eta (page): a unit never sent — no whole time, no percent (never 99 %); the rest\'s end (270 + 30 + Kopia 100) «plus the partner step»',
        [null, null, 400], $r['never'] ?? null);
    same('partner eta (page): the inventory, no plan yet — the units the partner got last time (270 + 30 + 500 + 100)', 900, $r['inventory'] ?? null);
    same('partner eta (page): the inventory, a partner that never got anything — the rest only', [null, 370], $r['inventoryNew'] ?? null);
    same('partner eta (page): on the way without a rate yet — its last time less 200 s, then Kopia', 400, $r['partnerNoRate'] ?? null);
    same('partner eta (page): past its last time without a rate — «longer than usual», Kopia still counted', [100, true], $r['partnerLate'] ?? null);
    same('partner eta (page): its first transfer on the way, no rate yet — unknown, the rest (Kopia) known', [null, null, 100], $r['partnerFirst'] ?? null);
    same('partner eta (page): the bubble says the rest\'s end «plus the partner step»', ['bubble.eta_partner_unknown {"time":"time(' . '<t>' . ')"}'],
        array_map(fn ($x) => preg_replace('/time\(\d+(\.\d+)?\)/', 'time(<t>)', $x), $r['bubble'] ?? []));
    same('partner eta (page): with the rate — 40 s of this one, 500 for the next unit, Kopia 100', 640, $r['partnerRate'] ?? null);
    hardeningRm($tmp);
}

function testBackupTiles(): void
{
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    // 390 px (2026-10-11): the run card's step names ran into each other — a grid of whole cells there, a long name in «…»
    // with its title
    $css = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.css');
    check('backup tiles: the run card\'s steps never overlap (ellipsis, a grid of two at a phone\'s width, the name in the title)',
        str_contains($css, 'white-space:nowrap; overflow:hidden; text-overflow:ellipsis;')
        && str_contains($css, '@media (max-width:640px){.bk-steps{display:grid; grid-template-columns:repeat(auto-fill, minmax(140px, 1fr))} .bk-steps li{min-width:0}}')
        && str_contains($js, "if (!li.dataset.tip) li.title = T('step.' + name);"));
    // 1.60.1 (a user: «the little Unraid wave would be cool here»): the wave wherever a run or a restore goes - always inside .running
    check('backup tiles: the run card is .running whole - the wave in its title before the name, none on the highlighted step',
        str_contains($js, "const card = el('div', 'card bk-run running');") && str_contains($js, "top.append(el('span', 'spin'), el('span', 'card-name',")
        && str_contains($js, "const li = el('li', i < p.step ? 'done' : i === p.step ? 'current' : '', T('step.' + name));") && !str_contains($js, "card.classList.add('running');"));
    check('backup tiles: the last backup\'s tile carries the wave while a run goes', substr_count($js, "label: T('stat.last'), running: live(),") === 2
        && str_contains($js, "label: d.running ? waveLabel(d.label) : d.label,"));
    // Mr. Restori's (and Ms. Moverelli's) card draws its steps with core.js's Office.runSteps (1.61) — same slide, office.css
    $core = (string) file_get_contents(OFFICE_WEB . '/assets/core.js');
    $ocss0 = (string) file_get_contents(OFFICE_WEB . '/assets/office.css');
    check("run card (restore, moverelli) 1.61: the shared steps' highlight slides - one element behind the list, an ease-in-out of 0.7 s, no move on the first drawing or while the step stays",
        str_contains($core, 'Office.runSteps = function runSteps(steps, at, key)') && str_contains($core, 'const from = runHlLast.key === key && runHlLast.at !== at && runHlLast.box ? runHlLast.box : null;')
        && str_contains($ocss0, '.run-steps-hl{position:absolute; z-index:0; background:var(--accent-soft)') && str_contains($ocss0, 'transition:left .7s ease-in-out')
        && str_contains((string) file_get_contents(OFFICE_WEB . '/desks/restore/desk.js'), 'card.appendChild(Office.runSteps(d.steps, d.at, j.id));'));
    foreach (['backup' => 'bk'] as $desk => $pre) {
        $djs = (string) file_get_contents(OFFICE_WEB . "/desks/$desk/desk.js");
        $dcss = (string) file_get_contents(OFFICE_WEB . "/desks/$desk/desk.css");
        check("run card ($desk) 1.60.1: the current step's highlight slides - one element behind the list, an ease-in-out of 0.7 s, no move on the first drawing or while the step stays",
            str_contains($djs, "function {$pre}_slideMark(wrap, ol, key, at)") && str_contains($djs, "const from = {$pre}HlLast.key === key && {$pre}HlLast.at !== at && {$pre}HlLast.box ? {$pre}HlLast.box : null;")
            && str_contains($dcss, ".$pre-steps-hl{position:absolute; z-index:0; background:var(--accent-soft)") && str_contains($dcss, 'transition:left .7s ease-in-out')
            && str_contains($dcss, ".$pre-steps li{transition:color .7s ease-in-out}") && !str_contains($dcss, 'font-weight:650; background:var(--accent-soft)}'));
    }
    $rjs = (string) file_get_contents(OFFICE_WEB . '/desks/restore/desk.js');
    check('restore: the wave on the journal\'s «running» chip, the running step, the run card and the tile\'s step while a restore runs',
        str_contains($rjs, "const waving = (x) => { const w = el('span', 'running'); w.append(el('span', 'spin'), ' ', ...[].concat(x)); return w; };")
        && str_contains($rjs, "meta.appendChild(r.result === 'running' ? waving(head) : head);") && str_contains($rjs, "li.append(s.state === 'running' ? waving(sc) : sc, ' ', stepText(s));")
        && str_contains($rjs, "top.append(el('span', 'spin'), el('span', 'card-name', d.title), chip(T('jr.running'), 'accent'));") && str_contains($rjs, "lines: [[line, going && right ? waving(right) : right]]")
        && str_contains($core, "st.state === 'failed' ? 'done failed' : 'done', st.name);"));
    $ocss = (string) file_get_contents(OFFICE_WEB . '/assets/office.css');
    preg_match('/--wave:url\("data:image\/svg\+xml,([^"]+)"\);/', $ocss, $w);
    $svg = rawurldecode($w[1] ?? '');
    check('the wave: one SVG that moves itself - Unraid\'s nine bars at their places, its gradient, 2-4 up and 6-8 down to the mirror, 2.5 s ease-in-out, its own reduced-motion; 12 px high',
        substr_count($svg, '<rect ') === 9 && str_contains($svg, "viewBox='0 0 133.52 76.97'") && str_contains($svg, "<stop offset='0' stop-color='#e32929'/><stop offset='1' stop-color='#ff8d30'/>")
        && substr_count($svg, "class='u'") === 2 && substr_count($svg, "class='d'") === 2 && substr_count($svg, "class='v'") === 1 && substr_count($svg, "class='e'") === 1
        && str_contains($svg, '@keyframes u{50%{transform:translateY(-38.49px)}}') && str_contains($svg, '@keyframes e{50%{transform:translateY(62.27px)}}')
        && str_contains($svg, 'animation:2.5s ease-in-out infinite') && str_contains($svg, '@media (prefers-reduced-motion:reduce){*{animation:none}}')
        && str_contains($ocss, '.spin{display:none; width:20.8px; height:12px;') && substr_count($ocss, 'background:var(--wave) center / contain no-repeat') === 2
        && !str_contains($ocss, '--wave-rest'), $svg);
    same('backup tiles: no scrollIntoView left (a tile filters, the search reveals)', 0, substr_count($js, 'scrollIntoView'));
    preg_match_all("/setAttribute\\('role', 'button'\\)/", $js, $m, PREG_OFFSET_CAPTURE);
    $roles = array_map(fn ($x) => preg_match_all('/\nfunction (\w+)\(/', substr($js, 0, $x[1]), $f) ? end($f[1]) : '?', $m[0]);
    same('backup tiles: no hand-made role=button tile — the only one is a setup row\'s name (CLAUDE.md «Rows»)', ['setupUnfold'], $roles);
    check('backup tiles: no tabindex/onkeydown tiles, the old clickable() and the desk\'s own stat() gone',
        !str_contains($js, 'bk-clickable') && !preg_match('/\nfunction stat\(/', $js) && !str_contains($js, 'const clickable ='));
    preg_match_all("/Office\\.store\\('(backup\\.[a-z_.]+)'/", $js, $m);
    same('backup tiles: Office.store only for what was kept before (no tile filter, word or switch)', ['backup.proposals_dismissed'], array_values(array_unique($m[1])));
    preg_match_all('/Office\.filterBar\(\{(.*?)\}\);?\n/s', $js, $m);
    same('backup tiles: three bars (the table, the backups, the setup), none with a select (nothing of a bar is kept)',
        [3, 0], [count($m[1]), count(array_filter($m[1], fn ($b) => str_contains($b, 'select:')))]);
    // tiles v2 (a tile is a section): the row on Office.sections(), the tabs, the setup's head line
    check('backup tiles: the row is the switcher (Office.sections(), grid stats bk-stats, no start tile, the table shared as `prot`)',
        str_contains($js, "sw = Office.sections({\n    id: ID,") && str_contains($js, "grid: 'stats bk-stats',") && str_contains($js, "default: '',")
        && str_contains($js, "tiles: () => tileList(),") && str_contains($js, "sections: { prot: () => protection() },"));
    check('backup tiles: the tile builder spreads the switcher\'s attributes into Office.stat (no click, aria-pressed or place of its own)',
        str_contains($js, "return Office.stat({ label: d.running ? waveLabel(d.label) : d.label, value: d.value, sub: d.sub, alert: d.alert, tip: d.tip, cls: d.cls, ...a, place: `tile.\${d.key}` });")
        && !str_contains($js, 'protTileClick') && !str_contains($js, 'protRedraw') && !preg_match('/\nfunction summary\(/', $js));
    check('backup tiles: a new visit drops the bars; #/backup/<tile> picks the tile like a click (the switcher, the address back to #/backup)',
        str_contains($js, "protBar = null;\n      histBar = null;\n      switcher().mount(sub);"));
    check('backup tiles: the table\'s filter is the active filter tile, its note line the switcher\'s (its × and «Show all» = nothing active)',
        str_contains($js, "const f = { ...bar.read(), tile: protFilter() };")
        && str_contains($js, "bar.done(v.n, v.total, { ...switcher().note('prot'), onlyAvail: v.off > 0 });"));
    check('backup tiles: both bars draw through the switcher (no section replaced by hand)', substr_count($js, 'onChange: () => switcher().render()') === 2);
    check('backup tiles 1.60.1: a run going on — its card above the tiles, whatever tile is open; the tiles stay',
        str_contains($js, 'if (live()) root.appendChild(runningCard());') && !str_contains($js, 's.grid.hidden = live();'));
    check('backup tiles: every tile a place of the search (kind tile, its anchor tile.<id>, #/backup/<tile>), the rows and sections through their tile',
        str_contains($js, "...TILES.map(([id, key]) => ({ kind: 'tile', key, anchor: `tile.\${id}`, route: tileRoute(id),")
        && !str_contains($js, 'ITEM_ROUTE') && substr_count($js, 'route: prot }') === 3);
    check('backup tiles: two tabs «Overview» / «Set up» on both pages, no crumb, «← Back» or head button «Set up…»',
        str_contains($js, "pages: { list: PAGES(), current } }).head;") && substr_count($js, 'deskHeadOf(') === 3
        && !str_contains($js, "T('setup.back')") && !str_contains($js, "page: T('setup.page')")
        && !str_contains($js, "actions.push(button(T('setup_open'), 'plain', () => Office.go(`#/\${ID}/setup`)));"));
    check('backup tiles: the setup\'s page actions in its own head line under the tabs',
        str_contains($js, "pa.append(again, measure, preset, forget);"));
    $places = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/places.json'), true);
    same('backup tiles: places.json lists every tile, the new sections and the help term', [], array_values(array_diff(
        ['stat.last', 'stat.schedule', 'tile.apps', 'tile.dumps', 'tile.flash', 'tile.kopia', 'tile.vms', 'tile.prot', 'partner.tile', 'tile.drift', 'tile.restore',
            'schedule.title', 'partner.section', 'help.tiles'], $places['keys'] ?? [])));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $code) {
        $l = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/backup/lang/$code.json"), true);
        $miss = array_values(array_filter(['stat.next', 'tile.kopia', 'tile.dumps', 'tile.apps', 'tile.vms', 'tile.flash', 'tile.prot', 'tile.drift', 'tile.restore',
            'stat.prot_ok', 'stat.prot_off', 'stat.drift_n', 'stat.tour_line', 'stat.drill_passed', 'stat.drill_failed', 'stat.restore_where',
            'schedule.change', 'schedule.section_sub', 'partner.section', 'partner.section_sub', 'partner.units_line', 'protect.filter_label', 'protect.only_off',
            'protect.only_off_hint', 'history_filter_label', 'filter_none', 'partner.short_now', 'partner.short_never', 'partner.short_sent', 'partner.short_failed',
            'partner.short_skipped', 'help.tiles', 'help.tiles_text'], fn ($k) => !isset($l[$k])));
        same("backup tiles: the texts in $code", [], $miss);
        same("backup tiles: «← Back» and the overview's sub line gone in $code", [], array_values(array_filter(['setup.back', 'overview_sub'], fn ($k) => isset($l[$k]))));
    }
    $sc = backupSchedule();
    check('backup tiles: the agent hands the page the schedule\'s next run (officeJobSchedule() through backupSchedule())',
        array_key_exists('next', $sc) && array_key_exists('script', $sc) && ($sc['enabled'] ? is_int($sc['next']) : $sc['next'] === null));
    $node = testsNode();
    if ($node === '') {
        check('backup tiles: node is missing here - skipped', true);
        return;
    }
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg(OFFICE_DIR . '/tests/backuptiles.js') . ' '
        . escapeshellarg(OFFICE_WEB . '/desks/backup/desk.js') . ' ' . escapeshellarg(OFFICE_WEB . '/assets/core.js') . ' 2>&1');
    $lines = array_values(array_filter(explode("\n", trim($raw))));
    $r = json_decode((string) end($lines), true);
    if (!is_array($r) || !isset($r['pass'], $r['fail'])) {
        check('backup tiles: ran under node', false, $raw);
        return;
    }
    check("backup tiles: the overview and the table under node ({$r['pass']} checks)", $r['pass'] >= 40 && !$r['fail']);
    foreach ($r['fail'] as $f) {
        check('backup tiles: ' . ($f[0] ?? '?'), false, 'got ' . json_encode($f[1] ?? null) . ', want ' . json_encode($f[2] ?? null));
    }
}

/**
 * Jack's «Last run» while EmbyCache runs (the tiles rebuild, 2026-10-11): every start removed status.json and the tile
 * read it — «never» while a run went, a report shown as the last run. Now jackLastRun() and the page's lastRuns() read
 * his list of runs: the newest real run (run, release) is it, else the newest of any mode; refused and skipped starts
 * didn't run; status.json only for the result box (last_status). Under node (stand-ins for the office): the tiles of
 * «How I work» — «Last run» with how long it took and a newer report under it, «running since» while one goes, a div
 * when nothing ran; «Schedules» (2 active · next, off), «Ready on the pool»; the «Emby» tile gone; a click on «Last run»
 * filters «Recent runs» to EmbyCache's (the bar's note line names it), a second shows all.
 */
function testJackLastRunDuringRun(): void
{
    $tmp = hardeningTmp('jacklast');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    $real = ['tool' => 'embycache', 'mode' => 'run', 'by' => 'schedule', 'started' => 1000, 'finished' => 1720, 'exit' => 0, 'result' => 'ok',
             'status' => ['errors' => 0, 'warnings' => 1]];
    jackRemember($real, $tmp);
    jackRemember(['tool' => 'gather', 'mode' => 'run', 'by' => 'schedule', 'started' => 1800, 'finished' => 1900, 'exit' => 0, 'result' => 'ok'], $tmp);
    jackRemember(['tool' => 'embycache', 'mode' => 'report', 'by' => 'office', 'started' => 2000, 'finished' => 2010, 'exit' => 0, 'result' => 'ok'], $tmp);
    jackRemember(['tool' => 'embycache', 'mode' => 'run', 'by' => 'schedule', 'started' => 2100, 'finished' => 2100, 'result' => 'refused', 'why' => 'jack_mover_schedule'], $tmp);
    check('last run: no status.json (a run just started) — his list still knows the last run', !is_file("$tmp/status.json") && jackLastRun(jackHistory($tmp)) !== null);
    same('last run: a report and a refused start after a real run — the real run is it', [1000, 'run'],
        [jackLastRun(jackHistory($tmp))['started'] ?? null, jackLastRun(jackHistory($tmp))['mode'] ?? null]);
    same('last run: only a dry run — that one; only refused and skipped starts, or none — null', [1500, null, null], [
        jackLastRun([['tool' => 'gather', 'mode' => 'run', 'started' => 1600, 'result' => 'ok'], ['tool' => 'embycache', 'mode' => 'dry', 'started' => 1500, 'result' => 'ok']])['started'] ?? null,
        jackLastRun([['tool' => 'embycache', 'mode' => 'run', 'started' => 1, 'result' => 'refused'], ['tool' => 'embycache', 'mode' => 'run', 'started' => 2, 'result' => 'skipped']]),
        jackLastRun([])]);
    same('last run: a release (his let-go) counts as real', 'release', jackLastRun([['tool' => 'embycache', 'mode' => 'dry', 'started' => 9, 'result' => 'ok'],
        ['tool' => 'embycache', 'mode' => 'release', 'started' => 5, 'result' => 'ok']])['mode'] ?? null);
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/jack.php');
    $fn = substr($src, (int) strpos($src, 'function jackLastRun('), 900);
    check('last run: his state takes it from his list; status.json only for the result box (last_status)',
        str_contains($src, "'last'       => jackLastRun(\$history = jackHistory())") && str_contains($src, "'last_status' => readJson(JACK_DATA . '/status.json')")
        && str_contains($src, "'history'    => array_slice(\$history, 0, 20)") && !str_contains(substr($fn, 0, (int) strpos($fn, "\n}\n")), 'status.json'));

    $node = testsNode();
    if ($node === '') {
        check('last run on his page: node is missing here - skipped', true);
        hardeningRm($tmp);
        return;
    }
    $state = ['configured' => true, 'settings' => ['libraries' => ['Filme'], 'max_resume_movies' => 10, 'number_episodes' => 3, 'instances' => [['servername' => 'Wohnzimmer', 'url' => 'http://x']]],
        'jobs' => ['embycache' => ['running' => false], 'gather' => ['running' => false]], 'pool' => ['path' => '/mnt/cache', 'free' => 700, 'free_percent' => 41.25, 'min_free' => 20],
        'cache' => ['files' => 12, 'bytes' => 4000, 'listed_at' => 1700, 'groups' => []],
        'shares' => [['share' => 'Filme', 'fit' => 'ok'], ['share' => 'Serien', 'fit' => 'other_pool']],
        'gather' => ['ready' => true, 'last' => ['finished' => 1600, 'moved' => 14, 'conflicts' => 0, 'errors' => 0, 'full' => 0, 'duplicates' => 2, 'dirs_deleted' => 6, 'dirs_kept' => 0]],
        'schedules' => ['embycache' => ['enabled' => true, 'frequency' => 'custom', 'custom' => '30 4 * * *', 'next' => 4000],
                        'gather' => ['enabled' => true, 'frequency' => 'custom', 'custom' => '0 3 * * 0', 'next' => 5000]],
        'history' => jackHistory($tmp)];
    file_put_contents("$tmp/state.json", json_encode($state));
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const el = (tag, cls, text) => { const n = { tag, className: cls || '', textContent: text == null ? '' : String(text), title: '', children: [], dataset: {}, style: {},
  disabled: false, value: '', isConnected: true, appendChild(c) { this.children.push(c); return c; }, append(...c) { this.children.push(...c); }, setAttribute() {} };
  Object.defineProperty(n, 'innerHTML', { set() { n.children = []; } }); return n; };
const stored = {};
const bars = [];
// the section switcher as a stand-in: its spec kept, the active tile set by the test, the note as core's sw.note()
let spec = null;
let active = '';
const list = () => (typeof spec.tiles === 'function' ? spec.tiles() : spec.tiles);
globalThis.Office = { scope: () => T, t: T, el, fmt: { size: (b) => `${b}B`, date: (t) => `D${t}`, relative: (t) => `R${t}`, time: (t) => `H${t}`, number: (n, d) => (d ? n.toFixed(d) : String(n)),
  duration: (s) => `${s}s`, cron: (c) => `C(${c})` }, desk: () => {}, places: () => {}, placesFrom: () => {}, placesTook: () => {}, storeJson: () => null,
  agent: { running: true }, keepInPlace: (a, f) => f(), place: (k, n) => { n.dataset.place = k; return n; },
  sectionHead: (title) => el('div', 'section-head', title), fits: (w) => !w.length, errorText: (x) => x.key,
  stat: (o) => ({ tag: o.on ? 'button' : 'div', o, children: [] }),
  sections: (o) => { spec = o; return { el: el('div', 'sections'), active: () => active, places: () => [], mount: () => false, pick() {}, render() {},
