        str_contains($snap, "lines.push(T('snaps_tile.hidden', { what: what.join(', ') }));") && str_contains($snap, "view.bar.done(n, state ? listed().length : 0, sw.note('list'));")
        && str_contains($snap, "T('empty.switched', { n: hid.backup + hid.partner })"));
    check('snapshot page: the search field is Office.filterBar — words folded (Office.fits), the source its select, the switches beside; deleting sees only the rows shown',
        str_contains($snap, "Office.filterBar({ key: 'snapshot.list'") && str_contains($snap, 'Office.fits(f.words, snapHay(s))')
        && str_contains($snap, "extra: [v.foldBtn, v.backupShow.label, v.partnerShow.label, v.dockerSwitch]")
        && str_contains($snap, "for (const id of [...selection]) if (!ids.has(id)) selection.delete(id);"));
    check('snapshot page: #/snapshot/datasets shows her list alone, grouped by dataset, no pool, no source', str_contains($snap, "sw.mount(sub === 'datasets' ? 'snapshots' : sub);")
        && str_contains($snap, "if (sub === 'datasets') view.bar.set({ pick: '' });"));
    $css = (string) file_get_contents(OFFICE_WEB . '/desks/snapshot/desk.css');
    check('snapshot page: a disk row\'s mark on a line of its own', str_contains($css, '.minirow .tile-mark{position:static; grid-column:1 / -1; justify-self:start}'));
}


/**
 * Ms. Dustdevil clears away what nobody uses — what something still needs can't be chosen at all (2026-10-12, Benj's
 * finding: a VM's disk in use could be ticked, «In die Abstellkammer…» offered the red «Trotzdem…»). A template whose
 * container exists, an appdata folder, a VM's folder or disk image in use: no checkbox to tick, a title saying what to do,
 * and the agent refuses them even when a stale page sends `force`. A stack in use («let go») and Mr. Restori's way back
 * keep the warning and «anyway».
 */
function testCleanupOrphanDatasets(): void
{
    // what the office keeps in appdata and domains is never hers to put away, whoever names it (2026-10-15)
    $settings = ['general' => ['dumps_share' => ['appdata']],
                 'app|nextcloud' => ['kopia' => ['yes'], 'folder' => ['appdata/nextcloud'], 'partner' => ['0a1b2c3d']],
                 'app|immich' => ['kopia' => ['yes'], 'folder' => ['appdata/immich']],
                 'vm|Win11' => ['partner' => ['0a1b2c3d']]];
    $f = fn (string $n, ?string $ds = null): array => ['name' => $n, 'parts' => [['dataset' => $ds]]];
    $folders = [$f('old-app', 'tank/appdata/old-app'), $f('nextcloud', 'tank/appdata/nextcloud'), $f('immich'), $f('unraid-backup'),
                $f('UnraidSecretaryOffice'), $f('uso-data'), $f('copies', 'tank/UnraidSecretaryOffice-partners/0a1b2c3d/app:x')];
    same('orphan datasets: the office\'s data folder and own names, the backup place, an app sent to a partner and a partner\'s dataset are kept',
        ['uso-data' => 'office', 'unraid-backup' => 'backup_place', 'nextcloud' => 'partner_held', 'UnraidSecretaryOffice' => 'office', 'copies' => 'partner_held'],
        clKeepNames('appdata', $folders, $settings, '/mnt/user/appdata/uso-data'));
    same('orphan datasets: in the office\'s share the backup place is its backup folder; a VM sent to a partner keeps its domains folder',
        [['backup' => 'backup_place'], ['Win11' => 'partner_held']],
        [clKeepNames('UnraidSecretaryOffice', [$f('backup'), $f('other')], ['general' => ['dumps_share' => ['UnraidSecretaryOffice']]], '/mnt/user/system/x'),
         clKeepNames('domains', [$f('Win11', 'tank/domains/Win11'), $f('Old')], $settings, '/mnt/cache/uso')]);
    same('orphan datasets: nothing set up — nothing kept but the office\'s own names', ['unraid-secretary-office-old' => 'office'],
        clKeepNames('appdata', [$f('old-app'), $f('unraid-secretary-office-old')], [], '/mnt/user/UnraidSecretaryOffice'));
    $entries = [['name' => 'old-app', 'why' => null], ['name' => 'nextcloud', 'why' => null], ['name' => 'unraid-backup', 'why' => 'docker_down'], ['name' => 'uso-data', 'why' => 'measure_first']];
    same('orphan datasets: kept entries carry whose and why (a stopped Docker still says so first)',
        [[null, null], ['partner_held', 'partner_held'], ['backup_place', 'docker_down'], ['office', 'office']],
        array_map(fn ($e) => [$e['kept'], $e['why']], clKeep($entries, ['nextcloud' => 'partner_held', 'unraid-backup' => 'backup_place', 'uso-data' => 'office'])));
    $refused = function (array $e): ?string { try { clParkCheck($e + ['kind' => 'appdata', 'name' => 'x', 'force' => false], true); return null; } catch (Problem $p) { return $p->key; } };
    same('orphan datasets: kept ones are refused, with force too', ['cleanup_kept_office', 'cleanup_kept_backup_place', 'cleanup_kept_partner_held'],
        [$refused(['why' => 'office']), $refused(['why' => 'backup_place']), $refused(['why' => 'partner_held'])]);

    // whose a snapshot is, by its name
    $p = ['uso-backup-', 'unraidbackup-'];
    same('orphan datasets: snapshot owners — her plans, his runs (exactly the engine\'s shape), a partner\'s copy, anything else manual',
        ['plan', 'backup', 'backup', 'manual', 'manual', 'partner', 'backup'],
        [clSnapOwner('tank/appdata/x@uso-plan-daily-20261014-0100', $p), clSnapOwner('tank/appdata/x@uso-backup-20261014-0300', $p),
         clSnapOwner('tank/appdata/x@unraidbackup-20250101-0300', $p), clSnapOwner('tank/appdata/x@uso-backup-20261014', $p),
         clSnapOwner('tank/appdata/x@before-update', $p), clSnapOwner('tank/UnraidSecretaryOffice-partners/0a1b2c3d/app:x@uso-backup-20261014-0300', $p),
         clSnapOwner('tank/appdata/UnraidSecretaryOffice-partners@uso-backup-20261014-0300', $p)]);

    // the preview: exactly what zfs rename does, read only
    $calls = [];
    $zfs = function (array $cmd) use (&$calls): array {
        $calls[] = $cmd;
        return [0, "tank/appdata/old-app\t5000\t1200\t100\ntank/appdata/old-app@uso-plan-hourly-20261014-0100\t300\t0\t200\n"
                 . "tank/appdata/old-app/db\t800\t0\t150\ntank/appdata/old-app/db@manual-1\t100\t0\t300\n"
                 . "tank/appdata/old-app@uso-backup-20261014-0300\t900\t0\t400\ntank/appdata/old-apps\t1\t0\t1\nbad line\n", ''];
    };
    $e = ['parts' => [['path' => '/mnt/tank/appdata/old-app', 'dataset' => 'tank/appdata/old-app'], ['path' => '/mnt/disk1/appdata/old-app', 'dataset' => null]]];
    $plan = clZfsPlan($e, $zfs, $p, '20261015-101010');
    same('orphan datasets: the preview reads each dataset once, recursively, snapshots by age', [['zfs', 'list', '-Hp', '-r', '-t', 'filesystem,volume,snapshot', '-o', 'name,used,usedbysnapshots,creation', '-s', 'creation', 'tank/appdata/old-app']], $calls);
    same('orphan datasets: the new name next to the storeroom, size, what goes along — never a neighbour of a similar name',
        [1, 'tank/appdata/' . CL_TRASH . '-20261015-101010-old-app', 5000, 1200, ['tank/appdata/old-app/db'], 3, ['plan' => 1, 'backup' => 1, 'partner' => 0, 'manual' => 1]],
        [count($plan), $plan[0]['to'], $plan[0]['used'], $plan[0]['snaps_bytes'], $plan[0]['inside'], $plan[0]['count'], $plan[0]['owners']]);
    same('orphan datasets: every snapshot with whose it is, the inner datasets\' too', [['tank/appdata/old-app@uso-plan-hourly-20261014-0100', 300, 200, 'plan'], ['tank/appdata/old-app/db@manual-1', 100, 300, 'manual']],
        array_map(fn ($s) => array_values($s), array_slice($plan[0]['snapshots'], 0, 2)));
    same('orphan datasets: zfs failing — nothing made up', [null, 0, []],
        (function () use ($e, $p) { $x = clZfsPlan($e, fn () => [1, '', 'cannot open'], $p, 's')[0]; return [$x['used'], $x['count'], $x['snapshots']]; })());

    // putting a dataset of appdata away needs the page's preview ticked; without it nothing is touched
    $GLOBALS['clScanStub'] = fn (): array => ['templates' => ['list' => []], 'stacks' => ['list' => [], 'root' => '/nonexistent'], 'scripts' => ['list' => []],
        'appdata' => ['list' => [['id' => 'appdata:old-app', 'kind' => 'appdata', 'name' => 'old-app', 'why' => null, 'force' => false, 'category' => 'unused',
                                  'parts' => [['root' => 'tank', 'path' => '/nonexistent/old-app', 'dataset' => 'tank/appdata/old-app', 'zfs' => true, 'bytes' => 1]]]]],
        'vms' => ['list' => []], 'leftovers' => ['list' => []], 'partners' => ['list' => []], 'backup_running' => false, 'restore_running' => false, 'trash' => ['runs' => []]];
    $GLOBALS['clZfsStub'] = $zfs;
    $key = function (callable $f): ?string { try { $f(); return null; } catch (Problem $p) { return $p->key; } };
    same('orphan datasets: «Into the storeroom» without the ticked preview is refused', 'cleanup_zfs_confirm', $key(fn () => clPark(['appdata:old-app'], false)));
    $pre = clZfsPreview(['appdata:old-app']);
    same('orphan datasets: the preview action — one plan per chosen dataset entry', ['appdata:old-app', 'tank/appdata/old-app', 3],
        [$pre['plans'][0]['id'] ?? null, $pre['plans'][0]['datasets'][0]['dataset'] ?? null, $pre['plans'][0]['datasets'][0]['count'] ?? null]);
    unset($GLOBALS['clScanStub'], $GLOBALS['clZfsStub']);
    same('orphan datasets: the page sends zfs_ok as a real boolean (never cast)', 'bad_request', $key(fn () => (function () { boolField(['zfs_ok' => 'yes'], 'zfs_ok'); })()));
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/cleanup.php');
    check('orphan datasets: the park action reads zfs_ok with boolField()', str_contains($src, "array_key_exists('zfs_ok', \$r) && boolField(\$r, 'zfs_ok')"));
    $js = (string) file_get_contents(OFFICE_WEB . '/desks/cleanup/desk.js');
    check('orphan datasets: the page asks for the preview and sends the tick', str_contains($js, '.zfs_preview`') && str_contains($js, 'zfs_ok: !!(zfsOk && zfsOk.checked)'));
    $en = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/cleanup/lang/en.json'), true);
    foreach (['why.office', 'why.office_text', 'why.backup_place', 'why.backup_place_text', 'why.partner_held', 'why.partner_held_text', 'errors.cleanup_zfs_confirm',
              'errors.cleanup_kept_office', 'errors.cleanup_kept_backup_place', 'errors.cleanup_kept_partner_held', 'zp.head', 'zp.confirm', 'zp.time', 'zp.retention'] as $k) {
        check("orphan datasets: words for $k", isset($en[$k]));
    }
    foreach (['plan', 'backup', 'partner', 'manual'] as $o) {
        check("orphan datasets: words for the owner $o", isset($en["zp.owner.$o"], $en["zp.owner.{$o}_text"]));
    }
}

function testCleanupInUseLocked(): void
{
    $refused = function (array $e, bool $force): ?string {
        try {
            clParkCheck($e + ['why' => null, 'name' => 'x', 'file' => 'my-x.xml', 'folder' => 'x'], $force);
            return null;
        } catch (Problem $p) {
            return $p->key;
        }
    };
    $locked = [['kind' => 'template', 'category' => 'in_use', 'force' => true], ['kind' => 'appdata', 'category' => 'used', 'force' => true],
               ['kind' => 'domain', 'category' => 'used', 'force' => true], ['kind' => 'iso', 'category' => 'used', 'force' => true]];
    same('in use locked: a template, appdata folder, VM folder or disk image in use is refused — with and without force',
        array_fill(0, 8, 'cleanup_in_use'), array_merge(array_map(fn ($e) => $refused($e, true), $locked), array_map(fn ($e) => $refused($e, false), $locked)));
    same('in use locked: a stack in use and Mr. Restori\'s way back park with force (the «anyway»), are refused without it',
        [null, null, 'cleanup_in_use', 'cleanup_in_use'],
        [$refused(['kind' => 'stack', 'category' => 'in_use', 'force' => true], true), $refused(['kind' => 'leftover', 'category' => 'leftover', 'force' => true], true),
         $refused(['kind' => 'stack', 'category' => 'in_use', 'force' => true], false), $refused(['kind' => 'leftover', 'category' => 'leftover', 'force' => true], false)]);
    same('in use locked: what nobody uses parks as before (force or not)', [null, null],
        [$refused(['kind' => 'appdata', 'category' => 'unused', 'force' => false], false), $refused(['kind' => 'domain', 'category' => 'unused', 'force' => false], true)]);
    same('in use locked: a reason not to (why) still comes first', 'cleanup_docker_down',
        (function () { try { clParkCheck(['kind' => 'template', 'why' => 'docker_down', 'force' => true, 'file' => 'a.xml'], true); return null; } catch (Problem $p) { return $p->key; } })());
    $src = (string) file_get_contents(OFFICE_DIR . '/agent/desks/cleanup.php');
    check('in use locked: clPark() asks clParkCheck() for every entry', str_contains($src, "        clParkCheck(\$e, \$force);\n        \$todo[] = \$e;"));

    $js = (string) file_get_contents(OFFICE_WEB . '/desks/cleanup/desk.js');
    check('in use locked: the page names the same kinds as the agent', str_contains($js, "const IN_USE_LOCKED = ['" . implode("', '", CL_IN_USE_LOCKED) . "'];"));
    check('in use locked: not selectable — the row\'s checkbox disabled with the why as its title and the row\'s, the group\'s says it too',
        str_contains($js, "&& !(removable(e) && e.category === 'used') && !inUseLocked(e)") && str_contains($js, "cb.title = lockedText(e);\n    r.title = cb.title;")
        && str_contains($js, "cb.title = !can.length && items.some(inUseLocked) ? T('in_use_locked.group') : T('select_group');"));
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $t = json_decode((string) file_get_contents(OFFICE_WEB . "/desks/cleanup/lang/$l.json"), true) ?: [];
        check("in use locked ($l): a why per kind and the group's; the dead «anyway» callouts of the three rooms gone, the stacks' and the leftovers' kept",
            isset($t['in_use_locked.template'], $t['in_use_locked.appdata'], $t['in_use_locked.domain'], $t['in_use_locked.iso'], $t['in_use_locked.group'], $t['park.in_use_stacks'], $t['park.in_use_leftovers'])
            && str_contains($t['in_use_locked.template'], '{unused}') && str_contains($t['in_use_locked.appdata'], '{group}')
            && !isset($t['park.in_use_templates']) && !isset($t['park.in_use_appdata']) && !isset($t['park.in_use_vms']));
    }
}

/**
 * A deleted share's .cfg is no share (2026-10-12, helmi1987's finding: Ms. Dustdevil advised «2 shares write straight to
 * the array: docker, domains2» — both long gone, only their /boot/config/shares/*.cfg left; Ms. Moverelli listed them
 * too). One truth, officeShareExists(): shares.ini, else /mnt/user/<name> (FUSE, never a disk), true while the array is
 * stopped. waShares() flags a cfg-only name `stale_cfg` + `storage.missing` (the write-method tip names only real shares),
 * Ms. Moverelli's list and Smart Mover's loop skip it, and her room «On the flash» offers the file: into the flash's
 * storeroom as shares/<name>.cfg and back — never while Unraid knows the share or can't tell.
 */
/**
 * An empty share whose snapshots still hold space (2026-10-17): her tour lists a share's dataset `<pool>/<share>` on an awake
 * pool whose live folder holds nothing but empty folders (or isn't mounted) while its snapshots hold ≥ 100 MB — never the
 * office's own share, the partners' copies, a backup place, a dataset that is no share, a sleeping pool (never asked).
 * The Team Lead's hint (recommended) says how much and where and links to Ms. Snapshotini's list by dataset; she
 * deletes nothing.
 */
function testCleanupSnapOnly(): void
{
    $tmp = hardeningTmp('snaponly');
    $mb = 1024 * 1024;
    foreach (['Familienfilme/2019/Sommer', 'Fotos', 'Dokumente', 'Archiv', 'UnraidSecretaryOffice', 'backup-alt', 'Kleinkram', 'Viel'] as $d) {
        @mkdir("$tmp/cache/$d", 0700, true);
    }
    file_put_contents("$tmp/cache/Dokumente/brief.txt", 'x');                 // a file: not empty
    @symlink('/etc', "$tmp/cache/Archiv/link");                                 // a link: not empty (never followed)
    for ($i = 0; $i < CL_SNAPONLY_WALK + 1; $i++) {
        @mkdir("$tmp/cache/Viel/d$i");                                          // more than she looks at: not empty
    }
    $asked = [];
    $zfs = function (array $args) use (&$asked, $tmp, $mb): array {
        $asked[] = $args;
        $row = fn (string $n, int $refer, int $snaps, string $mounted = 'yes') => implode("\t", [$n, $refer, $snaps, $mounted, "$tmp/$n"]);
        return [0, implode("\n", [
            $row('cache', 200000, 0),
            $row('cache/Familienfilme', 150000, 12 * 1024 * $mb),               // empty but for folders: 12 GB held
            $row('cache/Fotos', 100000, 300 * $mb),
            $row('cache/Dokumente', 100000, 2048 * $mb),                        // a file in it
            $row('cache/Archiv', 100000, 2048 * $mb),
            $row('cache/Zu', 100000, 900 * $mb, 'no'),                          // not mounted: its folder gone, the snapshots hold
            $row('cache/Gross', 40 * $mb, 9000 * $mb),                          // its live data counts: not empty
            $row('cache/Kleinkram', 100000, 50 * $mb),                          // too little held to say
            $row('cache/UnraidSecretaryOffice', 100000, 5000 * $mb),            // the office's own
            $row('cache/backup-alt', 100000, 5000 * $mb),                       // a backup place
            $row('cache/' . PARTNER_PARENT, 100000, 5000 * $mb),                 // the partners' copies
            $row('cache/Viel', 100000, 5000 * $mb),
            $row('cache/nichtshare', 100000, 5000 * $mb),                       // a dataset that is no share
            $row('cache/Familienfilme/sub', 100000, 5000 * $mb),                // below a share: never
            "garbage line",
        ])];
    };
    $shares = ['Familienfilme', 'Fotos', 'Dokumente', 'Archiv', 'Zu', 'Gross', 'Kleinkram', 'UnraidSecretaryOffice', 'backup-alt', PARTNER_PARENT, 'Viel'];
    $r = clSnapOnlyShares(['pools' => [['cache'], ['hdd']], 'zfs' => $zfs, 'shares' => $shares, 'known' => true]);
    same('snap only: the empty shares (folders only, not mounted) whose snapshots hold ≥ 100 MB, most held first',
        [['Familienfilme', 'cache', 12 * 1024 * $mb, true], ['Zu', 'cache', 900 * $mb, false], ['Fotos', 'cache', 300 * $mb, true]],
        array_map(fn ($x) => [$x['share'], $x['pool'], $x['snaps'], $x['mounted']], $r['list']));
    same('snap only: one zfs list -d 1 of the awake pools only (the sleeping one never asked), listed as asleep',
        [[['list', '-Hp', '-t', 'filesystem', '-o', 'name,refer,usedbysnapshots,mounted,mountpoint', '-d', '1', 'cache']], ['hdd']], [$asked, $r['asleep']]);
    $asked = [];
    same('snap only: every pool asleep, or the array stopped — nothing asked, nothing said',
        [[], [], []], [clSnapOnlyShares(['pools' => [[], ['cache']], 'zfs' => $zfs, 'shares' => $shares, 'known' => true])['list'],
                       clSnapOnlyShares(['pools' => [['cache'], []], 'zfs' => $zfs, 'shares' => $shares, 'known' => false])['list'], $asked]);
    $c = clSnapOnlyChecks($r);
    same('snap only: the Team Lead\'s hint — recommended, how much and where, the link to Ms. Snapshotini\'s datasets',
        [['snap_only', 'recommended', false, '#/snapshot/datasets'], ['n' => 3, 'shares' => 'Familienfilme (cache, 12.0 GB), Zu (cache, 900.0 MB), Fotos (cache, 300.0 MB)', 'size' => '13.2 GB']],
        [[$c[0]['id'], $c[0]['level'], $c[0]['ok'], $c[0]['link']], $c[0]['params']]);
    same('snap only: none — in place (also with a pool asleep); her tour before this look — nothing',
        [[true], []], [array_column(clSnapOnlyChecks(['list' => [], 'asleep' => ['hdd']]), 'ok'), clSnapOnlyChecks(null)]);
    check('snap only: she only looked — every folder and file still there', is_file("$tmp/cache/Dokumente/brief.txt") && is_dir("$tmp/cache/Familienfilme/2019/Sommer"));
    $ct = (string) file_get_contents(OFFICE_WEB . '/desks/caretaker/desk.js');
    check('snap only: the Team Lead\'s button says the desk\'s own words (check.<id>_link) where it has them',
        str_contains($ct, "text(f, '_link') || T('open.office')"));
    hardeningRm($tmp);
}

function testStaleShares(): void
{
    $tmp = hardeningTmp('stale-shares');
    exec('rm -rf ' . escapeshellarg($tmp) . '/*');
    foreach (["$tmp/boot/config/shares", "$tmp/mnt/user/media", "$tmp/mnt/user/docs"] as $d) {
        @mkdir($d, 0700, true);
    }
    $cfgs = "$tmp/boot/config/shares";
    file_put_contents("$tmp/var.ini", "fsState=\"Started\"\n");
    file_put_contents("$tmp/stopped.ini", "fsState=\"Stopped\"\n");
    file_put_contents("$tmp/shares.ini", "[\"docs\"]\nname=\"docs\"\nuseCache=\"no\"\nexclusive=\"no\"\n");
    file_put_contents("$cfgs/docs.cfg", "shareUseCache=\"no\"\nshareComment=\"\"\n");             // a real share on the array
    file_put_contents("$cfgs/docker.cfg", "shareUseCache=\"no\"\n");                              // gone: only its cfg is left
    file_put_contents("$cfgs/domains2.cfg", "shareUseCache=\"prefer\"\nshareCachePool=\"cache\"\n");  // gone too
    $ini = "$tmp/shares.ini";
    $var = "$tmp/var.ini";

    // --- the one truth
    same('stale shares: exists — in shares.ini, a folder under /mnt/user (not listed yet), gone; never an empty, «..» or slashed name',
        [true, true, false, false, false, false],
        [officeShareExists('docs', $ini, "$tmp/mnt", $var), officeShareExists('media', $ini, "$tmp/mnt", $var), officeShareExists('docker', $ini, "$tmp/mnt", $var),
         officeShareExists('', $ini, "$tmp/mnt", $var), officeShareExists('..', $ini, "$tmp/mnt", $var), officeShareExists('a/b', $ini, "$tmp/mnt", $var)]);
    same('stale shares: … the array stopped (no var.ini «Started»): Unraid can\'t tell — nothing is called gone', [true, true, false, true],
        [officeShareExists('docker', $ini, "$tmp/mnt", "$tmp/stopped.ini"), officeShareExists('docker', $ini, "$tmp/mnt", "$tmp/none.ini"),
         officeSharesKnown("$tmp/stopped.ini"), officeSharesKnown($var)]);

    // --- Ms. Dustdevil's shares and her write-method tip
    $shares = waShares([], [], [], [], $ini, $cfgs, "$tmp/mnt", $var);
    $by = array_column($shares, null, 'name');
    same('stale shares: waShares — every name, the cfg-only ones flagged stale and missing, the real one not',
        [['docker', 'docs', 'domains2'], [true, true], [true, true], [false, false]],
        [array_keys($by), [!empty($by['docker']['stale_cfg']), $by['docker']['storage']['missing']], [!empty($by['domains2']['stale_cfg']), $by['domains2']['storage']['missing']],
         [!empty($by['docs']['stale_cfg']), $by['docs']['storage']['missing']]]);
    $disks = ['parity' => ['name' => 'parity', 'type' => 'Parity', 'device' => 'sdb'], 'disk1' => ['name' => 'disk1', 'type' => 'Data', 'device' => 'sdc'],
              'disk2' => ['name' => 'disk2', 'type' => 'Data', 'device' => 'sdd']];
    $wm = waWriteMethod(['md_write_method' => 'auto', 'spindownDelay' => '0'], $disks, $shares, null);
    same('stale shares: «n shares write straight to the array» names only the real one (helmi1987: docker, domains2 were gone)',
        [['docs'], 0, 'turbo'], [$wm['direct'], $wm['pooled'], $wm['tip']]);
