    'jack' => [],                       // his setup is a wizard card (no section heads); his main page keeps the switcher
    'snapshot' => [],
    'caretaker' => [],
    'moverelli' => [],
];

/**
 * The faults of one desk script against the v2 rule (testTilesConvention): a desk of SECTIONS_DESKS uses Office.sections()
 * (its desk.js), has no renderTiles+renderSection pair of its own, never sets hidden on a section (a section not chosen
 * isn't drawn), and every function of its desk.js that makes a section head (Office.sectionHead, or a helper of its own
 * around it) is reached from the switcher's spec — the tiles' sections and `sections` — or named in $elsewhere.
 * ["desks/<desk>/<file>:<line> …"]
 */
function sectionsConventionFaults(string $desk, string $file, string $js, array $elsewhere): array
{
    $lines = explode("\n", $js);
    $faults = [];
    $fault = function (int $i, string $what) use (&$faults, $desk, $file): void {
        $faults[] = "desks/$desk/$file:" . ($i + 1) . " $what";
    };
    // the top-level functions: name -> [line, body]
    $fns = [];
    $cur = '';
    foreach ($lines as $i => $l) {
        if (preg_match('/^(?:async\s+)?function\s+(\w+)\s*\(|^(?:const|let)\s+(\w+)\s*=\s*(?:async\s*)?(?:function\b|\([^)]*\)\s*=>|\w+\s*=>)/', $l, $m)) {
            $cur = $m[1] !== '' ? $m[1] : $m[2];
            $fns[$cur] = [$i, ''];
        }
        if ($cur !== '') {
            $fns[$cur][1] .= $l . "\n";
        }
        if (preg_match('/^\}/', $l) || ($cur !== '' && preg_match('/^(?:async\s+)?function\s+\w+\s*\(.*\}\s*$|^(?:const|let)\s+\w+\s*=.*;\s*(\/\/.*)?$/', $l))) {
            $cur = '';
        }
    }
    $at = strpos($js, 'Office.sections(');
    if ($file === 'desk.js' && $at === false) {
        $fault(0, 'no Office.sections() — a desk of SECTIONS_DESKS draws its tiles and sections through the switcher (CLAUDE.md «Tiles»)');
    }
    if (isset($fns['renderTiles'], $fns['renderSection'])) {
        $fault($fns['renderSection'][0], 'a renderTiles()+renderSection() pair of its own — Office.sections() is the switcher');
    }
    foreach ($lines as $i => $l) {
        if (preg_match('/\b\w*[sS]ection\w*\.hidden\s*=(?!=)/', $l) || (str_contains($l, "el('section'") && str_contains($l, 'hidden'))) {
            $fault($i, 'hidden on a section — a section not chosen is not drawn (Office.sections())');
        }
    }
    if ($file !== 'desk.js' || $at === false) {
        return $faults;
    }
    // the switchers' specs: every Office.sections( … ) up to its closing parenthesis (a desk with two pages may have a
    // switcher per page — Ms. Dustdevil's, Mr. Backupsy's and Jack Emby's setup steps)
    $spec = '';
    for ($from = $at; $from !== false; $from = strpos($js, 'Office.sections(', $from + 1)) {
        $depth = 0;
        $end = strlen($js);
        for ($k = $from + strlen('Office.sections'); $k < strlen($js); $k++) {
            $c = $js[$k];
            if ($c === '(') {
                $depth++;
            } elseif ($c === ')' && --$depth === 0) {
                $end = $k;
                break;
            }
        }
        $spec .= substr($js, $from, $end - $from) . "\n";
    }
    $names = fn (string $text) => array_values(array_filter(array_keys($fns), fn ($n) => preg_match('/(?<![\w.])' . preg_quote($n, '/') . '\b/', $text)));
    $reached = array_fill_keys($names($spec), true);
    for ($todo = array_keys($reached); $todo;) {
        $n = array_pop($todo);
        foreach ($names($fns[$n][1]) as $m) {
            if (!isset($reached[$m])) {
                $reached[$m] = true;
                $todo[] = $m;
            }
        }
    }
    // what makes a section head: Office.sectionHead, and a helper of the desk's own around it
    $makers = array_keys(array_filter($fns, fn ($f) => str_contains($f[1], 'Office.sectionHead(')));
    foreach ($fns as $n => [$line, $bodyText]) {
        $makes = str_contains($bodyText, 'Office.sectionHead(') || (bool) array_filter($makers, fn ($w) => $w !== $n && preg_match('/(?<![\w.])' . preg_quote($w, '/') . '\(/', $bodyText));
        if ($makes && !isset($reached[$n]) && !in_array($n, $elsewhere, true)) {
            $fault($line, "$n() makes a section head the switcher doesn't draw — a section hangs on Office.sections() (a tile's section or `sections`); one on another page goes into SECTIONS_DESKS");
        }
    }
    return $faults;
}

/**
 * The faults of one desk script against the tiles rule (testTilesConvention): {faults: ["desks/<desk>/<file>:<line> …"],
 * sites: the tiles that filter it saw}. $tiles: the desk's places of kind tile [{key, anchor, route}] (null: not
 * known — the place check is left out); $hasKey(key): that key in all five languages of the desk.
 */
function tilesConventionFaults(string $desk, string $file, string $js, ?array $tiles, callable $hasKey): array
{
    $lines = explode("\n", $js);
    $faults = [];
    $fault = function (int $i, string $what) use (&$faults, $desk, $file): void {
        $faults[] = "desks/$desk/$file:" . ($i + 1) . " $what";
    };
    // the function each line is in (top level: «function x(», «const x = (…) =>», «const x = function»), and the helpers
    // that set aria-pressed or data-filters on the node they are handed
    $fnOf = [];
    $body = [];
    $cur = '';
    foreach ($lines as $i => $l) {
        $def = (bool) preg_match('/^(?:async\s+)?function\s+(\w+)\s*\(|^(?:const|let)\s+(\w+)\s*=\s*(?:async\s*)?(?:function\b|\([^)]*\)\s*=>|\w+\s*=>)/', $l, $m);
        if ($def) {
            $cur = $m[1] !== '' ? $m[1] : $m[2];
        }
        $fnOf[$i] = $cur;
        if ($cur !== '') {
            $body[$cur] = ($body[$cur] ?? '') . $l . "\n";
        }
        if (preg_match('/^\}/', $l) || ($def && preg_match('/;\s*(\/\/.*)?$/', $l))) {
            $cur = '';          // the end of a function, or a helper on one line
        }
    }
    $pressHelpers = array_keys(array_filter($body, fn ($b) => str_contains($b, "'aria-pressed'")));
    $filterHelpers = array_keys(array_filter($body, fn ($b) => (bool) preg_match('/\.dataset\.filters\s*=/', $b)));
    preg_match_all('/anchor:\s*`([a-z]+:)\$\{/', $js, $m);
    $itemPrefixes = array_values(array_unique($m[1]));
    $calls = fn (array $names, string $l) => (bool) array_filter($names, fn ($n) => preg_match('/(?<![\w.])' . preg_quote($n, '/') . '\(/', $l)
        && !preg_match('/function\s+' . preg_quote($n, '/') . '\(|(?:const|let)\s+' . preg_quote($n, '/') . '\s*=/', $l));
    $window = fn (int $i, int $before, int $after) => implode("\n", array_slice($lines, max(0, $i - $before), $before + $after + 1 - max(0, $before - $i)));

    $sites = [];          // [line, the lines around it where its place mark is]
    foreach ($lines as $i => $l) {
        // a tile is a <button>: no role="button" in markup, none on a .stat / .card
        if (preg_match("/role=\\\\?[\"']button/", $l)) {
            $fault($i, 'role="button" in markup — a tile is a real <button> (Office.stat / Office.tile with on)');
        }
        if (preg_match("/(\\w+)\\.setAttribute\\('role', 'button'\\)|(\\w+)\\.role\\s*=\\s*'button'/", $l, $m)) {
            $var = $m[1] !== '' ? $m[1] : $m[2];
            for ($j = $i; $j >= max(0, $i - 15); $j--) {
                if (preg_match('/\b(?:const|let|var)\s+' . preg_quote($var, '/') . "\\s*=.*?el\\('\\w+', '([^']*)'/", $lines[$j], $e)) {
                    if (preg_match('/(^|\s)(stat|card)(\s|$)/', $e[1])) {
                        $fault($i, "role=button on a .{$e[1]} — a tile is a real <button> (Office.stat / Office.tile with on)");
                    }
                    break;
                }
            }
        }
        // nothing jumps: a tile click keeps the page in place; a jump a link asked for says so
        if (str_contains($l, 'scrollIntoView(') && !str_contains($l, '/* reveal */')) {
            $fault($i, 'scrollIntoView — a tile click keeps the page in place (Office.keepInPlace); a jump a link asked for carries /* reveal */');
        }
        // the words of a filter are folded by core
        if (preg_match('/\.normalize\(\s*[\'"]NFK?D[\'"]|\.replace\(\/ß\//u', $l)) {
            $fault($i, 'word folding of its own — Office.fold / Office.filterWords / Office.fits');
        }
        // a card built by hand that does something says whether it is pressed
        if (preg_match("/el\\('button', '([^']*)'/", $l, $m) && preg_match('/(^|\s)card(\s|$)/', $m[1])) {
            if (!str_contains($window($i, 0, 12), 'aria-pressed') && !$calls($pressHelpers, $l)) {
                $fault($i, 'a button.card without aria-pressed — Office.tile({…, active, on}) sets it');
            }
        }
        // a filter is never kept
        if (preg_match('/Office\.store(?:Json)?\(\s*([^,)]*)/', $l, $m) && preg_match('/filter|words|only|query/i', $m[1])) {
            $fault($i, "Office.store({$m[1]}) — filter words, «only …» switches and tile filters are never kept (mount() empties them: bar.reset())");
        }
        // the tiles that filter: Office.stat / Office.tile with filters (beside controls), data-filters set by hand or a helper
        // (… or a filter tile of the section switcher: filters: beside section: in Office.sections()' tiles)
        if (preg_match('/\bfilters:\s*(?!null\b)\S/', $l) && (str_contains($window($i, 3, 3), 'controls:') || preg_match('/\bsection:\s*\S/', $l))) {
            $sites[] = [$i, $window($i, 8, 8)];
        } elseif (preg_match('/\.dataset\.filters\s*=/', $l) && !in_array($fnOf[$i], $filterHelpers, true)) {
            $sites[] = [$i, $window($i, 8, 8)];
        } elseif ($calls($filterHelpers, $l)) {
            $sites[] = [$i, $window($i, 1, 1)];
        }
    }
    if ($tiles !== null) {
        foreach ($sites as [$i, $around]) {
            preg_match_all('/(?:place:\s*|Office\.place\(\s*)([\'`])((?:(?!\1).)+)\1/', $around, $m);
            if (!$m[2]) {
                $fault($i, 'a tile that filters has no place (place: … on Office.stat / Office.tile, or Office.place) — a tile is a place with a sub-route');
                continue;
            }
            $met = false;
            foreach ($m[2] as $anchor) {
                $re = '/^' . implode('.+', array_map(fn ($p) => preg_quote($p, '/'), preg_split('/\$\{[^}]*\}/', $anchor))) . '$/';
                foreach ($tiles as $t) {
                    if (preg_match($re, (string) $t['anchor']) && preg_match('~^#/' . preg_quote($desk, '~') . '/.+~', (string) $t['route']) && $hasKey((string) $t['key'])) {
                        $met = true;
                    }
                }
                if (preg_match('/^([a-z]+:)/', $anchor, $p) && in_array($p[1], $itemPrefixes, true)) {
                    $met = true;          // a tile per thing of the state (a pool): found as its item
                }
            }
            if (!$met) {
                $fault($i, 'a tile that filters, place ' . implode(' / ', $m[2]) . " — no place of kind 'tile' in Office.places() meets it with a sub-route #/$desk/… and its key in all five languages");
            }
        }
    }
    // tiles first (owner 2026-10-15): on a desk's main page nothing stands between its help and the row — hints, banners,
    // a run's card go under the row, over the sections (`sw.el.insertBefore(n, sw.body)`); the desks named are not moved yet
    if ($file === 'desk.js' && !in_array($desk, TILES_FIRST_LATER, true)) {
        $in = false;
        foreach ($lines as $i => $l) {
            if (preg_match('/Office\.pageHelp\(ID, \[/', $l)) {
                $in = true;
                continue;
            }
            if (!$in || preg_match('/^\s*(\/\/|\*)/', $l)) {
                continue;
            }
            if (preg_match('/root\.(appendChild|append)\(.*\b\w+\.el\b/', $l)) {
                break;          // the row: what follows is under it
            }
            if (preg_match('/root\.(appendChild|append)\(/', $l) && !preg_match("/deskHead|'empty'|missing\(\)|Office\.pageHelp/", $l)) {
                $fault($i, 'something over the row of tiles — the tiles come first under the head; put it under the row (sw.el.insertBefore(n, sw.body))');
            }
        }
    }
    return ['faults' => $faults, 'sites' => count($sites)];
}
/** Desks whose main page still has hints over the row (tiles first, 2026-10-15): moved one by one, then taken off */
const TILES_FIRST_LATER = ['advisor', 'backup', 'cleanup', 'restore'];


// ===================================================================== run

/**
 * Unraid's standard shares on a fresh server (agent/lib/firsthome.php, 2026-10-16): Unraid makes appdata and system only
 * once Docker is turned on. The look tells «never there» (not in shares.ini, no .cfg, neither Docker's nor the VMs'
 * paths in it) from «gone»; only a click (the web side's officeHomeAsk(): the RAM inbox, never the mailbox; the Team
 * Lead's shares_make while the office runs) makes the agent create them — Unraid's «Add Share» through a stand-in for
 * emcmd: on the pool cache (only) when there is one, else the array; domains/isos only named. The web side in a process
 * of its own (its RAM folder, var.ini of the test's own).
 */
function testFirstHome(): void
{
    $tmp = hardeningTmp('firsthome');
    $run = "$tmp/run";
    foreach (['user', 'shares', 'pools'] as $d) {
        @mkdir("$tmp/$d", 0755, true);
    }
    @mkdir($run, 0700, true);
    $data = "$tmp/user/appdata/UnraidSecretaryOffice/data";
    // emcmd's stand-in: notes what it was sent, makes the share (its folder) unless told to fail or to make nothing
    file_put_contents("$tmp/emcmd", "#!/bin/bash\necho \"\$1\" >> " . escapeshellarg("$tmp/sent") . "\n"
        . '[ -e ' . escapeshellarg("$tmp/fail") . " ] && { echo 'Share name is reserved'; exit 1; }\n"
        . '[ -e ' . escapeshellarg("$tmp/lazy") . " ] && exit 0\n"
        . 'n=$(sed -n "s/.*shareName=\([^&]*\).*/\1/p" <<<"$1"); mkdir -p ' . escapeshellarg("$tmp/user") . "/\"\$n\"\n");
    chmod("$tmp/emcmd", 0755);
    $h = ['shares_dir' => "$tmp/shares", 'shares_ini' => "$tmp/shares.ini", 'docker_cfg' => "$tmp/docker.cfg", 'domain_cfg' => "$tmp/domain.cfg",
          'pools_dir' => "$tmp/pools", 'mnt_user' => "$tmp/user", 'emcmd' => "$tmp/emcmd", 'wait' => 1];
    $sent = function () use ($tmp): array {
        $s = array_values(array_filter(explode("\n", (string) @file_get_contents("$tmp/sent"))));
        @unlink("$tmp/sent");
        return $s;
    };
    $names = fn (array $sent) => array_map(fn ($l) => preg_match('/shareName=([^&]*)/', $l, $m) ? $m[1] : '?', $sent);
    $clean = function () use ($tmp): void {
        foreach (['appdata', 'system'] as $s) {
            @rmdir("$tmp/user/$s");
        }
        unset($GLOBALS['homeAnswer']);
    };

    same('home: the share of the data folder', ['appdata', 'my.apps', null, null, null, null],
        [homeShareOf('/mnt/user/appdata/UnraidSecretaryOffice/data'), homeShareOf('/mnt/user/my.apps/UnraidSecretaryOffice/data/'),
         homeShareOf('/mnt/cache/appdata/UnraidSecretaryOffice/data'), homeShareOf('/mnt/user/.hidden/UnraidSecretaryOffice/data'),
         homeShareOf('/mnt/user/apps./UnraidSecretaryOffice/data'), homeShareOf('/mnt/user/appdata/elsewhere/data')]);

    // a fresh server: Docker and VMs never on, no share settings, two pools — cache first
    file_put_contents("$tmp/docker.cfg", "DOCKER_ENABLED=\"no\"\nDOCKER_APP_CONFIG_PATH=\"/mnt/user/appdata/\"\n");
    file_put_contents("$tmp/domain.cfg", "SERVICE=\"disable\"\n");
    file_put_contents("$tmp/shares.ini", "[\"media\"]\nname=\"media\"\n");
    touch("$tmp/pools/alpha.cfg");
    touch("$tmp/pools/cache.cfg");
    $both = [['share' => 'appdata', 'fresh' => true], ['share' => 'system', 'fresh' => true]];
    same('home: never there — appdata and system, both new, on the pool cache; the VMs\' shares named',
        ['share' => 'appdata', 'fresh' => true, 'missing' => $both, 'optional' => ['domains', 'isos'], 'pool' => 'cache'], homeLook($data, $h));
    unlink("$tmp/pools/cache.cfg");
    same('home: … without cache the first pool', 'alpha', homeLook($data, $h)['pool'] ?? '?');
    unlink("$tmp/pools/alpha.cfg");
    same('home: … no pool — the array', ['pool' => null], array_intersect_key(homeLook($data, $h) ?? [], ['pool' => 1]));
    touch("$tmp/pools/cache.cfg");
    // gone: Unraid knew it
    file_put_contents("$tmp/shares/AppData.cfg", "shareUseCache=\"only\"\n");
    same('home: its settings on the flash (any case) — gone, not fresh; system still new', [false, [['share' => 'appdata', 'fresh' => false], ['share' => 'system', 'fresh' => true]]],
        [homeLook($data, $h)['fresh'] ?? '?', homeLook($data, $h)['missing'] ?? '?']);
    unlink("$tmp/shares/AppData.cfg");
    file_put_contents("$tmp/shares.ini", "[\"appdata\"]\nname=\"appdata\"\n");
    same('home: listed by emhttp — there (never looked at under /mnt/user)', [null, [['share' => 'system', 'fresh' => true]]],
        [homeLook($data, $h), homeMissing(null, $h)['missing']]);
    file_put_contents("$tmp/shares.ini", '');
    file_put_contents("$tmp/docker.cfg", "DOCKER_ENABLED=\"yes\"\nDOCKER_APP_CONFIG_PATH=\"$tmp/user/appdata/\"\nDOCKER_IMAGE_FILE=\"$tmp/user/system/docker/\"\n");
    same('home: Docker on with its apps and its image in them — both gone', [false, false], array_column(homeLook($data, $h)['missing'] ?? [], 'fresh'));
    file_put_contents("$tmp/docker.cfg", "DOCKER_ENABLED=\"yes\"\nDOCKER_APP_CONFIG_PATH=\"$tmp/user/containers/\"\nDOCKER_IMAGE_FILE=\"$tmp/user/other/docker/\"\n");
    same('home: Docker on, its things in other shares — new', [true, true], array_column(homeLook($data, $h)['missing'] ?? [], 'fresh'));
    file_put_contents("$tmp/docker.cfg", "DOCKER_ENABLED=\"no\"\n");
    file_put_contents("$tmp/domain.cfg", "SERVICE=\"enable\"\nIMAGE_FILE=\"$tmp/user/system/libvirt/libvirt.img\"\n");
    same('home: the VMs on with libvirt\'s image in system — system gone', [true, false], array_column(homeLook($data, $h)['missing'] ?? [], 'fresh'));
    file_put_contents("$tmp/domain.cfg", "SERVICE=\"disable\"\n");

    // Unraid's «Add Share»: exactly the form its Shares page sends
    $r = homeMake('appdata', 'cache', $h);
    $s = $sent();
    same('home: made — on the pool cache only, Unraid\'s form', [true, 1, true],
        [$r['ok'], count($s), str_contains($s[0] ?? '', 'shareNameOrig=&shareName=appdata&') && str_contains($s[0], '&shareUseCache=only&shareCachePool=cache&')
            && str_contains($s[0], '&cmdEditShare=Add%20Share') && is_dir("$tmp/user/appdata")]);
    $clean();
    homeMake('appdata', null, $h);
    same('home: … without a pool on the array', true, str_contains($sent()[0] ?? '', '&shareUseCache=no&shareCachePool=&'));
    $clean();
    touch("$tmp/fail");
    $r = homeMake('appdata', 'cache', $h);
    same('home: emcmd refused — said with its words', ['home_failed', 'Share name is reserved'], [$r['error']['key'] ?? null, $r['error']['params']['detail'] ?? null]);
    unlink("$tmp/fail");
    touch("$tmp/lazy");
    same('home: Unraid said yes but no share came — said', 'home_not_there', homeMake('appdata', 'cache', $h)['error']['key'] ?? null);
    unlink("$tmp/lazy");
    $sent();
    same('home: several at once — each checked again first: one already there, nothing made', [false, 'home_stale', []],
        (function () use ($h, $tmp, $sent) { mkdir("$tmp/user/system"); $r = homeMakeAll(['system', 'appdata'], $h); rmdir("$tmp/user/system"); return [$r['ok'], $r['error']['key'] ?? null, $sent()]; })());

    // the agent's round: the look in RAM, a click carried out only for exactly the new ones, new enough, a plain file
    $look = "$run/home.json";
    $req = "$run/inbox/home.request";
    @mkdir("$run/inbox", 0700, true);
    $t = homeTick($data, $look, $req, $h);
    same('home: a round without a click — the look in RAM, nothing sent', [true, true, false, []], [$t['fresh'] ?? null, is_file($look), isset($t['answer']), $sent()]);
    file_put_contents($req, json_encode(['shares' => ['appdata', 'other']]));
    $t = homeTick($data, $look, $req, $h);
    same('home: a click naming a share that is not missing — refused (stale), nothing sent', [false, 'home_stale', []], [file_exists($req), $t['answer']['error']['key'] ?? null, $sent()]);
    file_put_contents($req, json_encode(['shares' => ['system']]));
    same('home: … one without the data folder\'s share — refused', ['home_stale', []], [homeTick($data, $look, $req, $h)['answer']['error']['key'] ?? null, $sent()]);
    unset($GLOBALS['homeAnswer']);
    file_put_contents($req, json_encode(['shares' => ['appdata', 'system']]));
    touch($req, time() - 600);
    $t = homeTick($data, $look, $req, $h);
    same('home: a click ten minutes old — taken, nothing sent', [false, false, []], [file_exists($req), isset($t['answer']), $sent()]);
    symlink("$tmp/elsewhere.json", $req);
    file_put_contents("$tmp/elsewhere.json", json_encode(['shares' => ['appdata', 'system']]));
    homeTick($data, $look, $req, $h);
    same('home: a link in its place — nothing sent, the link gone, its target kept', [false, true, []], [is_link($req), is_file("$tmp/elsewhere.json"), $sent()]);

    // the web side: the look read back in its shape, the click into the RAM inbox
    file_put_contents("$tmp/var.ini", "fsState=\"Started\"\n");
    $web = function (string $code) use ($run, $tmp): array {
        $p = proc_open([PHP_BINARY, '-r', 'require ' . var_export(OFFICE_DIR . '/src/bootstrap.php', true) . '; require_once '
            . var_export(OFFICE_DIR . '/src/api.php', true) . "; $code"], [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']],
            $pipes, null, ['OFFICE_DATA_DIR' => "$tmp/user/appdata/UnraidSecretaryOffice/data", 'OFFICE_RUN_DIR' => $run, 'PATH' => getenv('PATH')]);
        $out = (string) stream_get_contents($pipes[1]) . (string) stream_get_contents($pipes[2]);
        proc_close($p);
        return json_decode(substr($out, (int) strpos($out, '{')), true) ?: ['raw' => $out];
    };
    $ask = fn (array $shares, string $ini = 'var.ini') => $web('try { $r = officeHomeAsk(["shares" => ' . var_export($shares, true) . '], '
        . var_export("$tmp/$ini", true) . '); unset($r["agent"]); } catch (OfficeProblem $e) { $r = ["problem" => $e->key]; } echo json_encode($r);');
    same('home: the page reads the look', ['share' => 'appdata', 'fresh' => true, 'pool' => 'cache', 'missing' => $both, 'optional' => ['domains', 'isos'], 'answer' => null],
        $web('echo json_encode(officeHomeLook());'));
    same('home: a click for only some of the new ones — refused (stale)', 'home_stale', $ask(['appdata'])['error']['key'] ?? null);
    same('home: a click that isn\'t a list of names — bad request', 'bad_request', $web('try { officeHomeAsk(["shares" => "appdata"]); } catch (OfficeProblem $e) { echo json_encode(["k" => $e->key]); }')['k'] ?? null);
    file_put_contents("$tmp/stopped.ini", "fsState=\"Stopped\"\n");
    same('home: the array stopped — refused', false, $ask(['appdata', 'system'], 'stopped.ini')['ok'] ?? null);
    same('home: the click — into the RAM inbox, 0600', [true, true, 0600], [$ask(['system', 'appdata'])['ok'] ?? null, is_file($req), @fileperms($req) & 0777]);
    $t = homeTick($data, $look, $req, $h);
    same('home: … the agent sends Unraid\'s «Add Share» for both, the data folder\'s last, «made»', [['system', 'appdata'], true, true, true, false],
        [$names($sent()), is_dir("$tmp/user/appdata"), is_dir("$tmp/user/system"), $t['answer']['made'] ?? null, file_exists($req)]);
    same('home: … its log lines for later (the data folder comes only now)', true, str_contains(implode("\n", $t['answer']['log'] ?? []), 'Created the share system on the user\'s click'));
    same('home: … once it is there the look goes', [null, false], [homeTick($data, $look, $req, $h), file_exists($look)]);
    $clean();
    // gone, not new: the click refused by the page, and by the agent too when it comes anyway
    file_put_contents("$tmp/shares/appdata.cfg", "shareUseCache=\"only\"\n");
    homeTick($data, $look, $req, $h);
    same('home: gone — the page reads «not fresh» and refuses the click', [false, 'home_stale'],
        [$web('echo json_encode(officeHomeLook());')['fresh'] ?? null, $ask(['system'])['error']['key'] ?? null]);
    file_put_contents($req, json_encode(['shares' => ['appdata', 'system']]));
    $t = homeTick($data, $look, $req, $h);
    same('home: … and the agent never creates it', ['home_stale', []], [$t['answer']['error']['key'] ?? null, $sent()]);
    unlink("$tmp/shares/appdata.cfg");
    // the page's reader: only its shape, only while new
    file_put_contents($look, json_encode(['share' => 'app data', 'fresh' => true, 'pool' => null]));
    same('home: a look not in its shape — nothing offered', ['l' => null], $web('echo json_encode(["l" => officeHomeLook()]);'));
    file_put_contents($look, json_encode(['share' => 'appdata', 'fresh' => true, 'pool' => null, 'missing' => [['share' => 'sys tem', 'fresh' => true], 'x']]));
    same('home: … a wrong entry in the list left out, the data folder\'s share always in it', [['share' => 'appdata', 'fresh' => true]], $web('echo json_encode(officeHomeLook());')['missing'] ?? null);
    touch($look, time() - 120);
    same('home: a look two minutes old (the agent away) — nothing offered', ['l' => null], $web('echo json_encode(["l" => officeHomeLook()]);'));

    // the office at work, system missing: the Team Lead's card and his click (the stand-ins through $GLOBALS['homeHost'])
    $GLOBALS['homeHost'] = $h;
    mkdir("$tmp/user/appdata");
    $card = fn () => array_values(array_filter(caretakerChecks(), fn ($f) => str_starts_with($f['id'], 'std_shares')));
    same('home: the Team Lead — system new: his card with it, not in place', [['std_shares', false, 'system']],
        array_map(fn ($f) => [$f['id'], $f['ok'], $f['params']['shares']], $card()));
    $e = null;
    try {
        caretakerSharesMake(['system', 'domains']);
    } catch (Problem $x) {
        $e = $x->key;
    }
    same('home: … his click for more than is missing — refused, nothing sent', ['home_stale', []], [$e, $sent()]);
    $made = homeMakeAll(['system']);
    same('home: … the shares he makes (homeMakeAll), then his card in place', [true, ['system'], [['std_shares', true, '']]],
        [$made['ok'], $names($sent()), array_map(fn ($f) => [$f['id'], $f['ok'], $f['params']['shares']], $card())]);
    rmdir("$tmp/user/system");
    file_put_contents("$tmp/shares/system.cfg", "shareUseCache=\"only\"\n");
    same('home: … system gone: the careful card, nothing offered', [['std_shares_gone', false, 'system']],
        array_map(fn ($f) => [$f['id'], $f['ok'], $f['params']['shares']], $card()));
    unset($GLOBALS['homeHost'], $GLOBALS['homeAnswer']);
    hardeningRm($tmp);
}

/**
 * A settings.ini line the setup doesn't know (2026-10-17: `note = …` written by hand into a share's section showed as the raw
 * key «backup.setup.key.note» in the apply dialog). setup.sh's settings_render() writes only the keys it knows, so Apply drops
 * the line - every branch of changeLabel() says so in words, never a raw key; no «proposal»/«leave out» for it
 */
function testSetupUnknownKey(): void
{
    $setup = (string) file_get_contents(OFFICE_DIR . '/backup/setup.sh');
    $render = substr($setup, (int) strpos($setup, 'settings_render() {'), 20000);
    check('unknown key: settings_render() writes known keys only (no pass-through of what settings.ini had) - «goes» is true',
        str_contains($render, 'w_kv mode "$(pget "share|$s|mode")"') && !preg_match('/\$\{!OLD\[@\]\}|\$\{OLD\[/', substr($render, 0, (int) strpos($render, "\n}\n"))));
    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('unknown key: node is missing here - skipped', true);
        return;
    }
    $tmp = hardeningTmp('setup-unknown-key');
    $general = ['general|dumps_share' => 'UnraidSecretaryOffice', 'kopia|enabled' => 'no', 'share|Mediathek|mode' => 'snapshot', 'share|UnraidSecretaryOffice|mode' => 'snapshot'];
    file_put_contents("$tmp/plan.json", json_encode(['time' => 1000, 'have_settings' => true,
        'P' => $general + ['docker|no_stop' => [], 'docker|skip' => [], 'docker|known' => []],
        'O' => $general + ['share|Mediathek|note' => 'from hand', 'general|note' => 'x', 'kopia|colour' => 'blue', 'share|Mediathek|mode' => 'snapshot'],
        'shares' => [['name' => 'Mediathek', 'exists' => true, 'folders' => [], 'waiting' => []], ['name' => 'UnraidSecretaryOffice', 'exists' => true, 'folders' => [], 'waiting' => []]],
        'containers' => [], 'vms' => [], 'databases' => [], 'nextcloud' => [], 'missing_databases' => [], 'bases' => []]));
    $js = <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const en = JSON.parse(fs.readFileSync(process.argv[3], 'utf8'));
const T = (k, p) => String(en[k] ?? k).replace(/\{(\w+)\}/g, (m, n) => (p && n in p ? p[n] : m));
globalThis.Office = { scope: () => T, t: T, el: () => ({}), fmt: { size: (b) => b + ' B', relative: () => 'now' }, desk: () => {}, places: () => {}, placesFrom: () => {}, placesTook: () => {}, selbar: () => {},
  has: (k) => k.replace(/^backup\./, '') in en };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const b = OFFICE_DESK_TESTS.backup;
b.setup.draft = null; b.setup.base = null; b.setup.plan = JSON.parse(fs.readFileSync(process.argv[4], 'utf8')); b.setupDraftKeep();
const saved = b.setupSaved();
const { keys } = b.setupApplyChanges(saved);
const out = { keys, labels: {} };
['share|Mediathek|note', 'general|note', 'kopia|colour', 'app|immich|note', 'vm|Win11|note', 'dump|db|note', 'share|Mediathek|mode', 'share|Mediathek|retention'].forEach((k) => {
  if (!(k in b.setup.plan.O) && !k.endsWith('mode') && !k.endsWith('retention')) b.setup.plan.O[k] = 'x';
  out.labels[k] = b.changeLabel(k);
});
console.log(JSON.stringify(out));
JS;
    file_put_contents("$tmp/t.js", $js);
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/backup/desk.js') . ' '
        . escapeshellarg(OFFICE_WEB . '/desks/backup/lang/en.json') . ' ' . escapeshellarg("$tmp/plan.json") . ' 2>&1');
    $r = json_decode($raw, true);
    hardeningRm($tmp);
    if (!is_array($r)) {
        check('unknown key: page ran under node', false, $raw);
        return;
    }
    same('unknown key: the hand-written lines are in the apply dialog\'s list (Apply drops them)', ['general|note', 'kopia|colour', 'share|Mediathek|note'],
        array_values(array_intersect($r['keys'], ['general|note', 'kopia|colour', 'share|Mediathek|note'])));
    same('unknown key: each in words, the share\'s as the owner saw it', [
        'share|Mediathek|note' => "Share Mediathek: the entry «note», which Mr. Backupsy doesn't know, goes",
        'general|note' => "Section [general]: the entry «note», which Mr. Backupsy doesn't know, goes",
        'kopia|colour' => "Section [kopia]: the entry «colour», which Mr. Backupsy doesn't know, goes",
        'app|immich|note' => "App immich: the entry «note», which Mr. Backupsy doesn't know, goes",
        'vm|Win11|note' => "VM Win11: the entry «note», which Mr. Backupsy doesn't know, goes",
        'dump|db|note' => "Section [dump db]: the entry «note», which Mr. Backupsy doesn't know, goes",
        'share|Mediathek|mode' => 'Share Mediathek: protection', 'share|Mediathek|retention' => 'Share Mediathek: local retention'], $r['labels']);
    check('unknown key: never a raw key on screen', !preg_grep('/backup\.|setup\.key|\|/', array_values($r['labels'])), implode(' / ', $r['labels']));
    $desk = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('unknown key: no «proposal» chip or «leave out» for it, its tip says why it goes',
        str_contains($desk, "!/\\|kopia_known$/.test(k) && !droppedKey(k)) {") && str_contains($desk, "if (unknownKey(k)) li.title = T('setup.key_unknown_tip');"));
}

/**
 * A Docker volume that is only a cache is not lost data (2026-10-17: immich's `model-cache:/cache` made the app row's chip
 * red «Docker volumes … NOT in the backup», the owner feared for his photos). The agent tags each plan container's cache
 * volumes (`backupPlanVolumeCaches()`, the one rule `backupVolumeIsCache()`, a volume's name from the docker_volumes
 * message), the page shows those in a grey chip «Cache only, fills itself again», red only what may hold data; the
 * setup's message for a cache is a hint, never a warning
 */
function testBackupVolumeCache(): void
{
    $plan = ['containers' => [
        ['name' => 'immich', 'volumes' => ['/cache'], 'project' => ''],
        ['name' => 'mixed', 'volumes' => ['/var/lib/postgresql/data', '/models', '/tmp'], 'project' => ''],
        ['name' => 'plain', 'volumes' => [], 'project' => ''],
        ['name' => 'old', 'project' => ''],
        'junk'],
        'messages' => [
            ['level' => 'warn', 'code' => 'docker_volumes', 'params' => ['app' => 'immich', 'volumes' => [['name' => 'model-cache', 'target' => '/cache']]]],
            ['level' => 'warn', 'code' => 'docker_volumes', 'params' => ['app' => 'mixed', 'volumes' => [['name' => 'pgdata', 'target' => '/var/lib/postgresql/data'],
                ['name' => 'ml-cache', 'target' => '/models'], ['name' => '', 'target' => '/tmp']]]],
            ['level' => 'warn', 'code' => 'docker_volumes', 'params' => ['app' => 'x', 'volumes' => 'odd']]]];
    $out = backupPlanVolumeCaches($plan);
    same('volume cache: per container the cache paths - by path (/cache, /tmp) or by the volume\'s name (ml-cache at /models); data stays out',
        [['/cache'], ['/models', '/tmp'], [], []], array_map(fn ($c) => $c['volumes_cache'], array_slice($out['containers'], 0, 4)));
    same('volume cache: a plan without containers or messages is left as it is', [['x' => 1], ['containers' => []]],
        [backupPlanVolumeCaches(['x' => 1]), backupPlanVolumeCaches(['containers' => []])]);
    $notes = backupSetupNotes($plan['messages']);
    same('volume cache: the setup\'s messages - the cache ones a hint, the data one a warning',
        [['hint', 'volumes_cache'], ['warn', 'volumes_data'], ['warn', 'docker_volumes']], array_map(fn ($g) => [$g['level'], $g['code']], $notes));
    $agent = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    check('volume cache: the page\'s plan carries the tags', str_contains($agent, '$plan = backupPlanVolumeCaches($plan);'));

    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('volume cache: page - node is missing here - skipped', true);
        return;
    }
    $tmp = hardeningTmp('volume-cache');
    $ct = fn ($name, $vols, $cache) => ['name' => $name, 'image' => "$name:1", 'running' => true, 'stop' => true, 'why' => 'volumes', 'binds' => [], 'volumes' => $vols]
        + ($cache === null ? [] : ['volumes_cache' => $cache]);
    file_put_contents("$tmp/plan.json", json_encode(['time' => 1, 'have_settings' => true, 'P' => [], 'O' => [], 'shares' => [],
        'containers' => [$ct('immich', ['/cache'], ['/cache']), $ct('mixed', ['/data', '/tmp'], ['/tmp']), $ct('older', ['/cache'], null)],
        'vms' => [], 'databases' => [], 'nextcloud' => [], 'missing_databases' => [], 'bases' => []]));
    $js = <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
globalThis.Office = { scope: () => T, t: T, el: () => ({}), fmt: { size: (b) => b + ' B', relative: () => 'now' }, desk: () => {}, places: () => {}, placesFrom: () => {}, placesTook: () => {}, selbar: () => {}, has: () => true };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const b = OFFICE_DESK_TESTS.backup;
const m = b.setupModel(JSON.parse(fs.readFileSync(process.argv[3], 'utf8')));
console.log(JSON.stringify(Object.fromEntries(m.apps.map((a) => [a.name, [a.volumes, a.volumesCache]]))));
JS;
    file_put_contents("$tmp/t.js", $js);
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/backup/desk.js') . ' ' . escapeshellarg("$tmp/plan.json") . ' 2>&1');
    hardeningRm($tmp);
    $r = json_decode($raw, true);
    same('volume cache: the app row - immich grey only, a mixed app red for its data and grey for its cache; an older agent\'s plan (no tags): red as before',
        ['immich' => [[], ['/cache']], 'mixed' => [['/data'], ['/tmp']], 'older' => [['/cache'], []]], $r);
    $desk = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('volume cache: the grey chip beside the red one', str_contains($desk, "chip(T('setup.ct_volumes_cache', { list: a.volumesCache.join(', ') }), '', T('setup.ct_volumes_cache_hint'))")
        && str_contains($desk, "chip(T('setup.ct_volumes', { list: a.volumes.join(', ') }), 'danger'"));
}

/**
 * A package of an app or VM that no longer exists (2026-10-17: two such packages made Mr. Restori's drill say «image
 * missing» on every run; agent/desks/backup-gone.php). Gone: an app none of whose containers (a stopped one is there)
 * and none of whose images is left; a VM libvirt doesn't know; Docker or libvirt silent — none. Only a package the
 * engine wrote. «Into the storeroom» moves it as the let-go does (backupLetGoMovePackage()), put back by clPackageHome();
 * refused while busy or when it isn't gone (any more)
 */
function testBackupGonePackage(): void
{
    $tmp = hardeningTmp('gone-package');
    $mnt = "$tmp/mnt";
    $place = '/mnt/user/UnraidSecretaryOffice/backup';
    $pool = "$mnt/pool/UnraidSecretaryOffice/backup";
    $man = fn (string $kind, string $folder, array $more = []) => $more + ['interface' => 1, 'engine' => '2.60', 'kind' => $kind, 'name' => $folder, 'folder' => $folder,
        'run' => '20261001-0200', 'time' => 1, 'result' => 'ok', 'files' => []];
    $ct = fn (string $name, string $image, string $id) => ['name' => $name, 'image' => $image, 'image_id' => $id, 'digests' => []];
    $packs = [
        'apps/immich'   => $man('app', 'immich', ['containers' => [$ct('immich_server', 'ghcr.io/immich-app/immich-server:release', 'sha256:aaa')]]),
        'apps/oldapp'   => $man('app', 'oldapp', ['containers' => [$ct('oldapp', 'postgres:16', 'sha256:bbb')]]),
        'apps/redisapp' => $man('app', 'redisapp', ['containers' => [$ct('redisapp', 'docker.io/library/redis', 'sha256:ddd')]]),
        'apps/zz-uso-test-db' => $man('app', 'zz-uso-test-db', ['containers' => [$ct('zz-uso-test-db', 'mariadb:11', 'sha256:ccc')]]),
        'apps/foreign'  => ['name' => 'foreign', 'containers' => [$ct('foreign', 'x:1', 'sha256:eee')]],      // not the engine's shape
        'apps/noct'     => $man('app', 'noct', ['containers' => []]),
        'vms/win11'     => $man('vm', 'win11'),
        'vms/oldvm'     => $man('vm', 'oldvm'),
    ];
    foreach ($packs as $d => $m) {
        mkdir("$pool/$d/db", 0700, true);
        file_put_contents("$pool/$d/manifest.json", json_encode($m));
    }
    file_put_contents("$pool/apps/zz-uso-test-db/db/mariadb.sql.gz", 'x');
    mkdir("$pool/server", 0700);
    file_put_contents("$pool/server/run.json", json_encode(['run' => '20261001-0200']));
    $pk = backupPackagesRead($pool);
    same('gone package: the engine\'s own by its manifest\'s shape (interface 1, kind, folder) - not a folder of another shape',
        ['foreign' => false, 'immich' => true, 'noct' => true, 'oldapp' => true, 'redisapp' => true, 'zz-uso-test-db' => true],
        array_column(array_map(fn ($a) => [$a['folder'], $a['engine_written']], $pk['apps']), 1, 0));
    $containers = ['immich_server', 'plex'];                       // immich_server stopped: docker ps -a lists it
    $images = ['sha256:aaa', 'ghcr.io/immich-app/immich-server:release', 'sha256:bbb', 'postgres:16', 'sha256:ddd', 'redis:latest'];
    $gone = backupGonePackages($pk, $containers, $images, ['win11']);
    same('gone package: only the app with neither a container nor an image, and the VM libvirt doesn\'t know - a stopped container and an image alone are not gone',
        [['app', 'zz-uso-test-db'], ['vm', 'oldvm']], array_map(fn ($g) => [$g['kind'], $g['folder']], $gone));
    same('gone package: an image named the long way (docker.io/library/redis) is the same as Docker\'s redis:latest', ['redis:latest', 'postgres:16', 'ghcr.io/a/b:1', 'redis:latest'],
        [backupGoneImageRef('docker.io/library/redis'), backupGoneImageRef('postgres:16'), backupGoneImageRef('ghcr.io/a/b:1'), backupGoneImageRef('redis')]);
    same('gone package: Docker not answering - no app gone; libvirt not answering - no VM gone; the place asleep - nothing at all',
        [[['vm', 'oldvm']], [['app', 'zz-uso-test-db']], []],
        [array_map(fn ($g) => [$g['kind'], $g['folder']], backupGonePackages($pk, null, null, ['win11'])),
         array_map(fn ($g) => [$g['kind'], $g['folder']], backupGonePackages($pk, $containers, $images, null)),
         backupGonePackages(['asleep' => true] + $pk, $containers, $images, [])]);
    $asked = [];
    $GLOBALS['goneHost'] = ['containers' => function () use (&$asked, $containers) { $asked[] = 'containers'; return $containers; },
                            'images' => function () use (&$asked, $images) { $asked[] = 'images'; return $images; },
                            'vms' => function () use (&$asked) { $asked[] = 'vms'; return ['win11']; }];
    $list = backupGoneList($pk);
    same('gone package: the look asks Docker for its images only when an app has none of its containers left', [2, ['containers', 'images', 'vms']], [count($list), $asked]);
    $asked = [];
    backupGoneList(['found' => true, 'apps' => [$pk['apps'][1]], 'vms' => []]);
    same('gone package: … every container there - the images not asked, libvirt not asked without VM packages', ['containers'], $asked);

    // the finding: a hint, never a must
    $GLOBALS['backup'] = ['packages_gone' => $list];
    $f = array_values(array_filter(backupChecks(), fn ($x) => $x['id'] === 'package_gone'));
    $GLOBALS['backup'] = ['packages_gone' => []];
    $f2 = array_values(array_filter(backupChecks(), fn ($x) => $x['id'] === 'package_gone'));
    unset($GLOBALS['backup']);
    same('gone package: the Team Lead\'s hint (only with settings.ini) - names, count, the link; none gone - ok',
        is_file(BACKUP_DATA_DIR . '/settings.ini') ? [['hint', false, 'zz-uso-test-db, oldvm', 2, '#/backup/prot'], true] : [null, null],
        is_file(BACKUP_DATA_DIR . '/settings.ini') ? [[$f[0]['level'] ?? null, $f[0]['ok'] ?? null, $f[0]['params']['names'] ?? null, $f[0]['params']['n'] ?? null, $f[0]['link'] ?? null], $f2[0]['ok'] ?? null]
            : [$f[0] ?? null, $f2[0] ?? null]);

    // «Into the storeroom»
    $ub = "$tmp/ub";
    mkdir("$ub/state", 0700, true);
    mkdir("$tmp/data", 0700);
    $GLOBALS['letgoUbData'] = $ub;
    $GLOBALS['letgoDir'] = "$tmp/data/backup";
    $GLOBALS['goneplace'] = $place;
    $GLOBALS['gonePackages'] = $pk;
    $GLOBALS['goneRoots'] = ['pool' => ['fs' => 'zfs', 'kind' => 'pool']];
    $GLOBALS['disksIni'] = "$tmp/disks.ini";
    file_put_contents($GLOBALS['disksIni'], '');
    $err = function (array $r) use ($mnt): ?string {
        try {
            backupPackageAside($r, $mnt);
            return null;
        } catch (Problem $p) {
            return $p->key;
        }
    };
    same('gone package: refused - a package that isn\'t gone (a stopped app, an image alone, not the engine\'s), an odd kind or name',
        ['package_aside_gone', 'package_aside_gone', 'package_aside_gone', 'package_aside_gone', 'bad_request', 'bad_request', 'missing_field'],
        [$err(['kind' => 'app', 'folder' => 'immich']), $err(['kind' => 'app', 'folder' => 'oldapp']), $err(['kind' => 'app', 'folder' => 'foreign']),
         $err(['kind' => 'vm', 'folder' => 'zz-uso-test-db']), $err(['kind' => 'share', 'folder' => 'x']), $err(['kind' => 'app', 'folder' => '../x']), $err(['kind' => 'app'])]);
    $other = fopen("$ub/state/lock", 'a');
    flock($other, LOCK_EX);
    file_put_contents("$ub/state/lock-holder.json", json_encode(['holder' => 'restore', 'mode' => 'drill', 'what' => 'drill', 'pid' => getmypid(), 'started' => time()]));
    same('gone package: refused while the engine\'s lock is held (a drill, a restore) - nothing moved', ['restore_running', true], [$err(['kind' => 'app', 'folder' => 'zz-uso-test-db']), is_dir("$pool/apps/zz-uso-test-db")]);
    unlink("$ub/state/lock-holder.json");
    flock($other, LOCK_UN);
    fclose($other);
    $GLOBALS['drill']['job_file'] = "$tmp/drill-job.json";
    file_put_contents($GLOBALS['drill']['job_file'], json_encode(['id' => '20261017-020000', 'result' => 'queued', 'created' => time()]));
    same('gone package: refused while a drill is going on', 'package_aside_drill', $err(['kind' => 'app', 'folder' => 'zz-uso-test-db']));
    unlink($GLOBALS['drill']['job_file']);

    $during = null;
    $GLOBALS['letgoHost'] = ['move' => function (string $from, string $to) use (&$during, $ub): void {
        $during ??= [flockHeld("$ub/state/lock"), readJson("$ub/state/lock-holder.json")['mode'] ?? null];
        clMove($from, $to);
    }];
    $r = backupPackageAside(['kind' => 'app', 'folder' => 'zz-uso-test-db'], $mnt);
    $trash = "$mnt/pool/UnraidSecretaryOffice/" . CL_TRASH;
    $runs = glob("$trash/*", GLOB_ONLYDIR) ?: [];
    $m = readJson(($runs[0] ?? '') . '/manifest.json') ?? [];
    $it = $m['items'][0] ?? [];
    same('gone package: moved under the engine\'s lock - one package, gone from the place, the others stay',
        [true, 1, 0, false, true, true], [$during[0] ?? null, $r['moved'], $r['failed'], is_dir("$pool/apps/zz-uso-test-db"), is_dir("$pool/apps/immich"), is_dir("$pool/vms/oldvm")]);
    same('gone package: in Ms. Dustdevil\'s storeroom at the share\'s top - kind package, from where it lay, its contents along, her shape check takes it',
        [1, 'package', 'apps/zz-uso-test-db', "$pool/apps/zz-uso-test-db", true, true],
        [count($runs), $it['kind'] ?? null, $it['name'] ?? null, $it['from'] ?? null, is_file(($runs[0] ?? '') . '/' . ($it['as'] ?? 'x') . '/db/mariadb.sql.gz'),
         clTrashAsOk((string) ($it['as'] ?? ''), 'package', basename($runs[0] ?? ''))]);
    same('gone package: put back only into the backup place\'s folder', "$pool/apps", clPackageHome("$pool/apps/zz-uso-test-db", $trash));
    $jf = glob("$tmp/data/backup/letgo-*.json") ?: [];
    $j = readJson($jf[0] ?? '') ?? [];
    same('gone package: a journal of his let-go\'s kind (mode aside) names the storeroom - Ms. Dustdevil finds it there too; the lock given back',
        [1, 'aside', 'done', [$trash], 1, false],
        [count($jf), $j['mode'] ?? null, $j['result'] ?? null, $j['trash'] ?? null, preg_match(LETGO_JOURNAL, basename($jf[0] ?? '')), flockHeld("$ub/state/lock")]);
    // Mr. Restori's drill reads the folder only: the package is no longer among them
    same('gone package: the drill\'s list of packages no longer has it', false,
        in_array('zz-uso-test-db', array_column(backupPackagesRead($pool)['apps'], 'folder'), true));
    $GLOBALS['gonePackages'] = backupPackagesRead($pool);
    same('gone package: a second time - not there any more, refused', 'package_aside_gone', $err(['kind' => 'app', 'folder' => 'zz-uso-test-db']));
    $GLOBALS['gonePackages'] = $pk;
    // the VM's package too
    $r = backupPackageAside(['kind' => 'vm', 'folder' => 'oldvm'], $mnt);
    same('gone package: a gone VM\'s package the same way', [1, false], [$r['moved'], is_dir("$pool/vms/oldvm")]);

    // the page: a line each with «Into the storeroom», the app row's chip; the action registered
    $desk = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    $agent = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    check('gone package: the page shows each with «Into the storeroom» on a fresh look, the action asked with kind and folder',
        str_contains($desk, "Office.api.post(`\${ID}.package_aside`, { kind: g.kind, folder: g.folder })") && str_contains($desk, "if (!(await Office.freshState(ID))) return;\n  const g = goneOf(g0.kind, g0.folder);")
        && str_contains($agent, "'package_aside' => fn (array \$r) => backupPackageAside(\$r),") && str_contains($agent, "'packages_gone' => backupGoneList(\$pk),"));
    unset($GLOBALS['goneHost'], $GLOBALS['goneplace'], $GLOBALS['gonePackages'], $GLOBALS['goneRoots'], $GLOBALS['disksIni'], $GLOBALS['letgoUbData'], $GLOBALS['letgoDir'],
        $GLOBALS['letgoHost'], $GLOBALS['drill']['job_file']);
    hardeningRm($tmp);
}

/**
 * A stale package whose app is now backed up under another name (owner 2026-10-17: the Compose stack «drop» removed and
 * made again as «dropnook» with the same containers; apps/drop stayed «stale» and «Into the storeroom» wasn't offered,
 * containers named drop being there). Offered when another app's package written by the last run holds all its
 * containers (same containers) or all its own folders inside a share (same folder) - never a whole share's folder alone,
 * never against a stale package, never when only part of it moved; the hint says which. The Team Lead's «gone» hint
 * leaves it out; the page says it in its own words.
 */
/**
 * Mr. Backupsy's Apply says the truth (2026-10-19, scenarios backup-sh-add-share-nc-0777-run and
 * moverelli-mo-own-rules-idle-setup): a share added in Unraid is proposed local, never Kopia unasked - unasked, the backup
 * place followed it to Kopia too (setupDerive(): «whatever goes to Kopia, the backup share follows»), a change nobody
 * chose; a new share's method «auto» is nothing Apply writes (the engine writes only live); a gone or renamed share's
 * section, which Apply drops, is said in the dialog (one row each, never declined). Run with the scenarios' own
 * plan-changes.mjs on the UI stub's plan, the list Apply's dialog makes.
 */
function testSetupApplyHonest(): void
{
    $node = testsNode();
    if ($node === '') {
        check('apply honest: node is there', false, 'no node');
        return;
    }
    $tmp = hardeningTmp('apply-honest');
    $plan = json_decode((string) file_get_contents(OFFICE_DIR . '/tests/ui/states/post/backup.setup_get.json'), true)['plan'];
    $plan['P']['kopia|enabled'] = 'yes';
    $plan['O']['kopia|enabled'] = 'yes';
    $row = fn (string $name, array $more) => $more + ['name' => $name, 'mode' => 'snapshot', 'why' => 'previous', 'why_arg' => '', 'why_text' => '', 'locations' => 'cache',
        'where' => 'cache', 'method' => 'snap', 'layout' => 'zfs', 'gb' => 1, 'notes' => [], 'exists' => true, 'children' => [], 'folders' => [], 'syslog' => false,
        'waiting' => [], 'partner' => [], 'partner_ok' => false, 'partner_why' => 'no_dataset', 'place' => false, 'asleep_bases' => [], 'pool_asleep' => false];
    // a share added in Unraid: not in settings.ini, the engine proposes «new» = kopia (share_propose())
    $added = $plan;
    $added['shares'][] = $row('uso-added', ['mode' => 'kopia', 'why' => 'new']);
    $added['P'] += ['share|uso-added|mode' => 'kopia', 'share|uso-added|method' => 'auto', 'share|uso-added|kopia_ignore' => [], 'share|uso-added|exclude_dataset' => []];
    $kopiaNew = $added;
    $kopiaNew['preset_new'] = 'kopia';
    $kopiaNew['P']['general|preset_new'] = 'kopia';
    $kopiaNew['O']['general|preset_new'] = 'kopia';
    // a share that is gone, one renamed (its settings went to the new name): settings.ini still has both sections
    $gone = $plan;
    $gone['shares'][] = $row('uso-gone', ['exists' => false, 'why' => 'gone', 'method' => '', 'gb' => null]);
    $gone['shares'][] = $row('uso-before', ['exists' => false, 'why' => 'renamed_to', 'why_arg' => 'uso-after', 'method' => '', 'gb' => null]);
    $gone['shares'][] = $row('uso-after', ['why' => 'renamed_from', 'why_arg' => 'uso-before']);
    $gone['P'] += ['share|uso-gone|mode' => 'snapshot', 'share|uso-gone|method' => 'auto', 'share|uso-before|mode' => 'snapshot', 'share|uso-before|method' => 'auto',
        'share|uso-after|mode' => 'snapshot', 'share|uso-after|method' => 'auto'];
    $gone['O'] += ['share|uso-gone|mode' => 'snapshot', 'share|uso-gone|id' => 'ino:cache:7', 'share|uso-before|mode' => 'snapshot', 'share|uso-before|id' => 'ino:cache:8'];
    $out = [];
    foreach (['plain' => $plan, 'added' => $added, 'kopianew' => $kopiaNew, 'gone' => $gone] as $n => $p) {
        file_put_contents("$tmp/$n.json", json_encode($p));
        $out[$n] = json_decode((string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg(OFFICE_DIR . '/tools/scenarios/plan-changes.mjs') . ' '
            . escapeshellarg("$tmp/$n.json") . ($n === 'gone' ? ' --items' : '') . ' 2>&1'), true);
    }
    // the stub's own differences (a gone app's section, the syslog share's first record) are the baseline
    $base = array_map(fn ($c) => $c['key'] . ': ' . json_encode($c['was']) . ' → ' . json_encode($c['is']), $out['plain'] ?? []);
    $keys = fn (?array $l) => array_values(array_diff(array_map(fn ($c) => $c['key'] . ': ' . json_encode($c['was']) . ' → ' . json_encode($c['is']), $l ?? []), $base));
    check('apply honest: the stub\'s plan with Kopia on - no share\'s mode or method among its changes',
        is_array($out['plain']) && !preg_grep('/^share\|[^|]+\|(mode|method):/', array_filter($base, fn ($k) => !str_starts_with($k, 'share|syslog|mode'))), json_encode($base));
    same('apply honest: a share added in Unraid - its mode, local (never Kopia unasked); the backup place stays local, the method «auto» is no change',
        ['share|uso-added|mode: null → "snapshot"'], $keys($out['added']));
    same('apply honest: … with the default «local + Kopia» for new things it goes to Kopia, and the backup place follows - said in the list',
        ['share|UnraidSecretaryOffice|mode: "snapshot" → "kopia"', 'share|uso-added|mode: null → "kopia"'], $keys($out['kopianew']));
    same('apply honest: a gone and a renamed share\'s sections - one row each in the dialog (kind share_gone), the new name\'s settings as keys',
        [['share|uso-after|mode', 'key'], ['share|uso-before|', 'share_gone'], ['share|uso-gone|', 'share_gone']],
        array_values(array_filter(array_map(fn ($i) => [$i['id'], $i['kind']], $out['gone'] ?? []), fn ($x) => str_starts_with($x[0], 'share|uso-'))));
    $desk = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('apply honest: the dialog says each gone share with its why (gone, or renamed to …), with the − mark',
        str_contains($desk, "T('setup.ch_share_gone', { name: sh.name })") && str_contains($desk, "T('setup.ch_share_renamed', { name: sh.why_arg })")
        && str_contains($desk, "T('setup.ch_share_gone_why')"));
    $bad = [];
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $s = langFile(OFFICE_WEB . "/desks/backup/lang/$l.json");
        foreach (['setup.ch_share_gone' => '{name}', 'setup.ch_share_renamed' => '{name}', 'setup.ch_share_gone_why' => ''] as $k => $ph) {
            if (!is_string($s[$k] ?? null) || ($ph !== '' && !str_contains($s[$k], $ph))) {
                $bad[] = "$l $k";
            }
        }
    }
    same('apply honest: the gone share\'s words in five languages', [], $bad);
    hardeningRm($tmp);
}

/**
 * Nextcloud's data folder readable by others (engine 2.62's warning nc_datadir_readable, 2026-10-19): listed while still
 * open (one stat, never a sleeping disk), only a folder the engine named in exactly its shape; «Close the folder»
 * changes its root only - Nextcloud's user, group users, 0770 - after checking it is that Nextcloud's data folder now,
 * looks again, and the folder is no longer listed. Nobody as the owner: said that Unraid opens it again.
 */
function testBackupNcOpen(): void
{
    $tmp = hardeningTmp('nc-open');
    $mnt = "$tmp/mnt";
    mkdir("$mnt/cache/nextcloud/admin/files", 0777, true);
    mkdir("$mnt/user", 0777, true);
    symlink("$mnt/cache/nextcloud", "$mnt/user/nextcloud");           // an exclusive share: /mnt/user/<share> a link to its pool
    mkdir("$mnt/cache/lsio", 0777, true);
    mkdir("$mnt/cache/closed", 0770, true);
    chmod("$mnt/cache/nextcloud", 0777);
    chmod("$mnt/cache/lsio", 0777);
    file_put_contents("$mnt/cache/nextcloud/admin/files/a.txt", 'x');
    chmod("$mnt/cache/nextcloud/admin/files/a.txt", 0644);
    $inner = fn () => [sprintf('%o', fileperms("$mnt/cache/nextcloud/admin") & 0777), fileowner("$mnt/cache/nextcloud/admin"),
        sprintf('%o', fileperms("$mnt/cache/nextcloud/admin/files/a.txt") & 0777), fileowner("$mnt/cache/nextcloud/admin/files/a.txt")];
    $innerBefore = $inner();
    $w = fn (string $name, string $path, string $uid) => ['code' => 'nc_datadir_readable', 'params' => ['name' => $name, 'path' => $path, 'uid' => $uid]];
    $run = ['warning_items' => [
        $w('nextcloud', "$mnt/user/nextcloud", '33'),
        $w('nextcloud-cron', "$mnt/user/nextcloud/", '33'),       // its sibling (the same folder): once
        $w('lsio', "$mnt/cache/lsio", '99'),
        $w('closed', "$mnt/cache/closed", '33'),                  // closed since: not listed
        $w('bad1', "$mnt/cache/../cache/lsio", '33'), $w('bad2', '/etc', '33'), $w('bad3', "$mnt/cache/lsio", '0'), $w('bad name', "$mnt/cache/lsio", '33'),
        ['code' => 'vm_late_paused', 'params' => ['name' => 'x']],
    ]];
    $list = backupNcOpenList($run, fn (string $p) => false, $mnt);
    same('nc open: the folders the last run named and still open - each once, nothing the engine didn\'t write in its shape, a closed one not',
        [['nextcloud', "$mnt/user/nextcloud", 33, '777', '770', 'users', false, true], ['lsio', "$mnt/cache/lsio", 99, '777', '770', 'users', true, true]],
        array_map(fn ($o) => [$o['name'], $o['path'], $o['uid'], $o['now']['mode'], $o['after']['mode'], $o['after']['group'], $o['comes_back'], $o['share_root']], $list));
    same('nc open: a folder whose disk sleeps is never looked at', [], backupNcOpenList($run, fn (string $p) => true, $mnt));
    same('nc open: no run, a run without the warning - nothing', [[], []], [backupNcOpenList(null, fn ($p) => false, $mnt), backupNcOpenList(['warning_items' => []], fn ($p) => false, $mnt)]);

    $GLOBALS['ncOpenList'] = $list;
    $GLOBALS['ncOpenMnt'] = $mnt;
    $GLOBALS['ncOpenDataDir'] = fn (string $c) => $c === 'nextcloud' ? "$mnt/user/nextcloud" : null;
    $refused = function (array $r): ?array {
        try {
            backupNcClose($r);
            return null;
        } catch (Problem $p) {
            return [$p->key, $p->params];
        }
    };
    same('nc open: refused - a name not listed, a folder that isn\'t that Nextcloud\'s data folder now, a sleeping disk, no name',
        [['nc_open_gone', ['name' => 'other']], ['nc_open_not_data', ['name' => 'lsio', 'path' => "$mnt/cache/lsio"]], ['nc_open_asleep', ['name' => 'nextcloud']], ['missing_field', ['field' => 'name']]],
        [$refused(['name' => 'other']), $refused(['name' => 'lsio']), (function () use ($refused) { $GLOBALS['ncOpenAsleep'] = true; $x = $refused(['name' => 'nextcloud']);
            unset($GLOBALS['ncOpenAsleep']); return $x; })(), $refused([])]);
    same('nc open: nothing changed by a refusal', '777', sprintf('%o', fileperms("$mnt/cache/nextcloud") & 0777));
    $j = backupNcClose(['name' => 'nextcloud']);
    clearstatcache();
    same('nc open: closed - the root (on the pool) Nextcloud\'s user, group users, 0770; looked at again', [true, 33, backupUsersGid(), '770', '777', '770'],
        [$j['ok'], fileowner("$mnt/cache/nextcloud"), filegroup("$mnt/cache/nextcloud"), sprintf('%o', fileperms("$mnt/cache/nextcloud") & 0777), $j['before']['mode'], $j['after']['mode']]);
    same('nc open: only the root - nothing inside it changed, the link stays a link', [$innerBefore, true], [$inner(), is_link("$mnt/user/nextcloud")]);
    same('nc open: closed, the warning goes - only lsio is still listed', ['lsio'], array_column(backupNcOpenList($run, fn ($p) => false, $mnt), 'name'));
    unset($GLOBALS['ncOpenList'], $GLOBALS['ncOpenMnt'], $GLOBALS['ncOpenDataDir']);

    $php = (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php');
    $desk = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('nc open: the desk\'s action and state (nc_open_close, nc_open), the page\'s callout and dialog on a fresh look, the bubble without the command while it is listed',
        str_contains($php, "'nc_open_close' => fn (array \$r) => backupNcClose(\$r)") && str_contains($php, "'nc_open'    => backupNcOpen(\$history, \$settings)")
        && str_contains($desk, "Office.api.post(`\${ID}.nc_open_close`, { name: o.name })") && str_contains($desk, 'if (!(await Office.freshState(ID))) return;
  const o = ncOpen().find((x) => x.name === name);') && str_contains($desk, "w.code === 'nc_datadir_readable' && state && Array.isArray(state.nc_open)"));
    $bad = [];
    foreach (['en', 'de', 'it', 'fr', 'es'] as $l) {
        $s = langFile(OFFICE_WEB . "/desks/backup/lang/$l.json");
        foreach (['nc_open.callout' => ['{name}', '{path}'], 'nc_open.close' => [], 'nc_open.title' => ['{name}'], 'nc_open.text' => ['{name}'], 'nc_open.folder' => [],
                  'nc_open.owner' => [], 'nc_open.mode' => [], 'nc_open.stays' => [], 'nc_open.comes_back' => ['{owner}'], 'nc_open.go' => [],
                  'nc_open.done' => ['{path}', '{owner}', '{mode}'], 'errors.nc_open_gone' => ['{name}'], 'errors.nc_open_asleep' => ['{name}'],
                  'errors.nc_open_not_data' => ['{name}', '{path}'], 'errors.nc_open_failed' => ['{name}', '{path}']] as $k => $need) {
            if (!is_string($s[$k] ?? null) || array_filter($need, fn ($x) => !str_contains($s[$k], $x))) {
                $bad[] = "$l $k";
            }
        }
    }
    same('nc open: the words in five languages, with their placeholders', [], $bad);
    hardeningRm($tmp);
}

/**
 * Engine 2.64 (scenario batch B, 2026-10-19): apps the user paused or stopped. backup.sh on a fixture server like
 * testBackupVmOrder (no VMs, no Kopia): stand-ins for docker (the containers' states in $FAKE/ct: running, paused or
 * stopped; exec refused for a paused or stopped one, as Docker does; Nextcloud's occ), zfs and notify.
 * B7: a paused container is left exactly as it is - never stopped, never started, so it is paused afterwards (up to 2.63
 * docker's State.Running, true for a paused one, had it stopped and started: it ran after the run); a paused database
 * gets no dump (dump_paused), a paused Nextcloud no maintenance mode; the package's manifest says «paused».
 * Batch B (R6, R11): a running Nextcloud whose database is stopped - occ answers nothing (Nextcloud connects to its
 * database first), up to 2.63 the run died at the maintenance mode and nothing was backed up. Now that app's problem only:
 * no maintenance mode (occ not even asked when config.php's dbhost names a stopped container), Nextcloud stopped with the
 * apps, everything else backed up, a warning db_unreachable and a notification in the office's language; a database the
 * engine can't name (an address): occ asked once, db_unreachable_occ. Any other occ refusal still ends the run - coded.
 */
function testBackupPausedStopped(): void
{
    if (posix_getuid() !== 0) {
        check('paused/stopped: backup.sh runs as root only — not run here', true);
        return;
    }
    $tmp = sys_get_temp_dir() . '/office-tests-pausedstopped-' . getmypid();
    exec('rm -rf ' . escapeshellarg($tmp));
    $mnt = "$tmp/mnt";
    $pool = "$mnt/maple";
    $fake = "$tmp/fake";
    $data = "$tmp/data/unraid-backup";
    $cts = ['c1' => 'nginx', 'c2' => 'nginx', 'db1' => 'mariadb:11', 'nc' => 'nextcloud:30', 'ncdb' => 'mariadb:11'];
    foreach (["$tmp/bin", "$fake/ct", "$data/state", "$tmp/boot/config/shares", "$mnt/user/UnraidSecretaryOffice", "$pool/UnraidSecretaryOffice/backup", "$tmp/stage"] as $d) {
        @mkdir($d, 0700, true);
    }
    foreach (array_keys($cts) as $c) {
        @mkdir("$pool/appdata/$c", 0700, true);
    }
    foreach (['appdata', 'UnraidSecretaryOffice'] as $n) {
        touch("$tmp/boot/config/shares/$n.cfg");
    }
    file_put_contents("$fake/mounts", "maple $pool zfs rw 0 0\nmaple/appdata $pool/appdata zfs rw 0 0\nmaple/UnraidSecretaryOffice $pool/UnraidSecretaryOffice zfs rw 0 0\n"
        . "shfs $mnt/user fuse.shfs rw 0 0\n");
    $z = fn ($n, $mp) => "$n\t$mp\ton\t" . crc32($n) . "\t1000\t-\n";
    file_put_contents("$fake/zfs.txt", $z('maple', $pool) . $z('maple/appdata', "$pool/appdata") . $z('maple/UnraidSecretaryOffice', "$pool/UnraidSecretaryOffice"));
    file_put_contents("$fake/inspect.json", json_encode(array_map(fn ($c, $img) => ['Name' => "/$c", 'Id' => "id-$c",
        'Config' => ['Image' => $img, 'Env' => [], 'Labels' => new stdClass()], 'State' => ['Running' => true, 'Paused' => false], 'HostConfig' => ['NetworkMode' => 'bridge'],
        'Mounts' => [['Type' => 'bind', 'Source' => "$mnt/user/appdata/$c", 'Destination' => $c === 'nc' ? '/var/www/html' : '/config', 'RW' => true]]],
        array_keys($cts), array_values($cts))));
    // docker: each container's state in $FAKE/ct/<name> (running when missing); exec refused unless running; Nextcloud's occ
    // ($FAKE/nc.dbdown: its database unreachable - occ fails as Nextcloud does then)
    file_put_contents("$tmp/bin/docker", <<<'SH'
#!/bin/bash
ev() { echo "$*" >>"$FAKE/events"; }
st() { cat "$FAKE/ct/$1" 2>/dev/null || echo running; }
states() { for f in "$FAKE"/ct/*; do [[ -f "$f" ]] && printf '%s %s\n' "${f##*/}" "$(cat "$f")"; done | jq -Rn '[inputs | split(" ") | {key: .[0], value: .[1]}] | from_entries'; }
case "$1" in
  info|version) exit 0 ;;
  ps) [[ "$*" == *q* ]] && jq -r '.[].Id' "$FAKE/inspect.json" || jq -r '.[] | "\(.Name[1:])\t\(.Config.Image)\tUp"' "$FAKE/inspect.json"; exit 0 ;;
  compose) exit 1 ;;
  inspect)
    shift
    if [[ "$1" == -f ]]; then
      s="$(st "$3")"
      case "$2" in
        *Health*) [[ "$s" != stopped ]] && echo "true " || echo "false " ;;
        *State.Paused*) case "$s" in stopped) echo "false false" ;; paused) echo "true true" ;; *) echo "true false" ;; esac ;;
        *State.Running*) [[ "$s" != stopped ]] && echo true || echo false ;;
      esac
      exit 0
    fi
    [[ "$1" == --format ]] && exit 0
    jq --argjson st "$(states)" '[.[] | . as $c | (.Name | ltrimstr("/")) as $n | select(($ARGS.positional | length) == 0 or ($ARGS.positional | index($n)) or ($ARGS.positional | index($c.Id)))
        | .State = {Running: (($st[$n] // "running") != "stopped"), Paused: (($st[$n] // "running") == "paused")}]' "$FAKE/inspect.json" --args "$@"
    exit 0 ;;
  image) echo '[]'; exit 0 ;;
  stop) shift; while [[ "$1" == -* ]]; do shift 2; done
        for c in "$@"; do echo stopped >"$FAKE/ct/$c"; ev "docker stop $c"; done; exit 0 ;;
  start) shift; for c in "$@"; do echo running >"$FAKE/ct/$c"; ev "docker start $c"; done; exit 0 ;;
  pause|unpause) ev "docker $*"; exit 0 ;;
  exec)
    shift
    while [[ "$1" == -* ]]; do case "$1" in -u|-e) shift 2 ;; *) shift ;; esac; done
    c="$1"; shift
    case "$(st "$c")" in
      paused) echo "Error response from daemon: container $c is paused, unpause the container before exec" >&2; exit 1 ;;
      stopped) echo "Error response from daemon: container $c is not running" >&2; exit 1 ;;
    esac
    ev "exec $c $*"
    [[ "$c" == nc ]] || exit 1
    case "$1" in
      test) [[ "${3:-}" == /var/www/html/occ ]] && exit 0; exit 1 ;;
      stat) echo www-data; exit 0 ;;
      id) echo 33; exit 0 ;;
      cat) [[ -e "$FAKE/nc.config" ]] && cat "$FAKE/nc.config"; exit 0 ;;
      php)
        shift 2
        [[ -e "$FAKE/nc.broken" && "$*" == "maintenance:mode --on" ]] && { ev "occ refused $*"; echo 'Something else went wrong'; exit 1; }
        if [[ -e "$FAKE/nc.dbdown" ]]; then
          ev "occ refused $*"
          printf '%s\n' 'An unhandled exception has been thrown:' "Doctrine\\DBAL\\Exception: Failed to connect to the database: An exception occurred in the driver: SQLSTATE[HY000] [2002] $(cat "$FAKE/nc.dbdown") in /var/www/html/lib/private/DB/Connection.php:236"
          exit 1
        fi
        case "$*" in
          "config:system:get instanceid") echo inst1 ;;
          "config:system:get maintenance") cat "$FAKE/nc.maint" 2>/dev/null || echo false ;;
          "maintenance:mode --on") echo true >"$FAKE/nc.maint"; ev "occ maintenance on" ;;
          "maintenance:mode --off") echo false >"$FAKE/nc.maint"; ev "occ maintenance off" ;;
        esac
        exit 0 ;;
    esac
    exit 1 ;;
esac
exit 1
SH);
    file_put_contents("$tmp/bin/virsh", "#!/bin/bash\nexit 0\n");          // the VM service on, no VMs (never the host's own)
    file_put_contents("$tmp/bin/zfs", "#!/bin/bash\ncase \"\$*\" in *'-t filesystem'*) cat \"\$FAKE/zfs.txt\" ;; snapshot*) echo \"zfs snapshot\" >>\"\$FAKE/events\" ;; esac\nexit 0\n");
    foreach (['zpool', 'btrfs', 'umount'] as $b) {
        file_put_contents("$tmp/bin/$b", "#!/bin/bash\nexit 0\n");
    }
    file_put_contents("$tmp/bin/mount", "#!/bin/bash\nexit 1\n");
    file_put_contents("$tmp/bin/mountpoint", "#!/bin/bash\n[[ \"\${@: -1}\" == */user ]]\n");
    file_put_contents("$tmp/bin/notify", "#!/bin/bash\necho \"\$*\" >>\"\$FAKE/notify.log\"\n");
    foreach (glob("$tmp/bin/*") as $f) {
        chmod($f, 0755);
    }
    $clock = "$fake/clock";
    testsClock("$tmp/bin", $clock);
    $env = "export PATH=$tmp/bin:\$PATH UB_DATA=$data UB_MNT=$mnt UB_BOOT=$tmp/boot UB_SHARES_CFG=$tmp/boot/config/shares UB_STAGE=$tmp/stage"
         . " UB_DISKS_INI=$fake/disks.ini UB_MOUNTS_FILE=$fake/mounts UB_NOTIFY_BIN=$tmp/bin/notify FAKE=$fake MNT=$mnt UB_NC_SETTLE=0";
    file_put_contents("$data/settings.ini", "[general]\nserver = Test\nmount_root = $mnt/addons/UnraidSecretaryOffice/snapshots\n"
        . "view_root = $mnt/addons/UnraidSecretaryOffice/btrfs-snap\nsnap_prefix = uso-backup-\ndumps_share = UnraidSecretaryOffice\nmin_free_gb = 0\n"
        . "[docker]\nstop = all\n" . implode('', array_map(fn ($c) => "known = $c\n", array_keys($cts))) . "[flash]\nmode = off\n[libvirt]\nmode = off\n"
        . "[kopia]\nenabled = no\n[nextcloud \"nc\"]\npreexisting_maintenance = abort\n[dump \"db1\"]\ntype = mariadb\n"
        . "[share \"appdata\"]\nmode = snapshot\n[share \"UnraidSecretaryOffice\"]\nmode = snapshot\n");
    $night = function (array $states) use ($fake, $data): void {
        exec('rm -rf ' . escapeshellarg("$fake/ct") . ' ' . escapeshellarg("$fake/events") . ' ' . escapeshellarg("$fake/notify.log"));
        @mkdir("$fake/ct", 0700, true);
        foreach ($states as $c => $s) {
            file_put_contents("$fake/ct/$c", "$s\n");
        }
        @unlink("$data/state/status.json");
    };
    $run = function () use (&$env, $clock): string {
        testsClockRun($clock);
        return testsClockRan('paused/stopped', (string) shell_exec('bash -c ' . escapeshellarg("$env; bash " . escapeshellarg(OFFICE_DIR . '/backup/backup.sh') . ' </dev/null') . ' 2>&1'));
    };
    $events = fn () => file("$fake/events", FILE_IGNORE_NEW_LINES) ?: [];
    $state = fn (string $c) => trim((string) @file_get_contents("$fake/ct/$c")) ?: 'running';
    $status = fn () => json_decode((string) @file_get_contents("$data/state/status.json"), true) ?: [];
    $log = fn () => (string) @file_get_contents("$data/logs/latest.log");

    // --- B7: c2, the database db1 and Nextcloud paused by the user; c1 and ncdb running
    $night(['c2' => 'paused', 'db1' => 'paused', 'nc' => 'paused']);
    $out = $run();
    $ev = $events();
    $s = $status();
    $touched = array_values(array_filter($ev, fn ($e) => (bool) preg_match('/^(docker (stop|start|pause|unpause)|exec) .*\b(c2|db1|nc)\b/', $e)));
    same('paused (B7): the run went through with a warning; c1 and ncdb stopped and started as always', ['warnings', true, true],
        [$s['result'] ?? null, in_array('docker stop c1', $ev, true) && in_array('docker start c1', $ev, true), in_array('docker stop ncdb', $ev, true) && in_array('docker start ncdb', $ev, true)],
        $out . $log());
    same('paused (B7): the paused ones are never stopped, started or asked anything - still paused afterwards', [[], 'paused', 'paused', 'paused'],
        [$touched, $state('c2'), $state('db1'), $state('nc')], json_encode($ev));
    same('paused (B7): the paused database\'s dump skipped, in the office\'s words (dump_paused); no maintenance mode for the paused Nextcloud',
        [[['code' => 'dump_paused', 'params' => ['container' => 'db1']]], false],
        [$s['warning_items'] ?? null, in_array('occ maintenance on', $ev, true)]);
    $l = $log();
    check('paused (B7): the log says it - left as they are, Nextcloud stays paused',
        str_contains($l, 'Paused by you:    c2 db1 nc (left as they are') && str_contains($l, "Nextcloud 'nc' is paused (by you) - no maintenance mode, it stays paused")
        && str_contains($l, "WARNING: Database container 'db1' is paused - no dump"), $l);
    $man = json_decode((string) @file_get_contents("$mnt/user/UnraidSecretaryOffice/backup/apps/c2/manifest.json"), true) ?: [];
    same('paused (B7): the package\'s manifest says the container was paused', [['c2', true, true]],
        array_map(fn ($c) => [$c['name'] ?? null, $c['running'] ?? null, $c['paused'] ?? null], $man['containers'] ?? []));

    // --- the same server, nothing paused: everything stopped and started, Nextcloud in maintenance mode, the dump made
    $night([]);
    $run();
    $ev = $events();
    check('paused (B7): nothing paused - every container stopped and started again, Nextcloud\'s maintenance mode on and off',
        !array_diff(['docker stop c2', 'docker start c2', 'docker stop nc', 'docker start nc', 'occ maintenance on', 'occ maintenance off'], $ev)
        && !preg_grep('/^docker (un)?pause/', $ev), json_encode($ev));

    // --- Nextcloud running, its database ncdb stopped (config.php: dbhost 'ncdb:3306'); ncdb has the dump now; the office speaks German
    $ini = (string) file_get_contents("$data/settings.ini");
    file_put_contents("$data/settings.ini", str_replace("[dump \"db1\"]\n", "[dump \"ncdb\"]\n", $ini));
    file_put_contents("$fake/lang.json", '{"lang":"de"}');
    $env .= " UB_NOTIFY_LANG_FILE=$fake/lang.json";
    $nc = function (string $dbhost) use ($fake): void {
        file_put_contents("$fake/nc.config", "<?php\n\$CONFIG = array (\n  'instanceid' => 'inst1',\n  'dbtype' => 'mysql',\n  'dbhost' => '$dbhost',\n  'maintenance' => false,\n);\n");
        file_put_contents("$fake/nc.dbdown", "php_network_getaddresses: getaddrinfo for ncdb failed: Temporary failure in name resolution");
    };
    $night(['ncdb' => 'stopped']);
    $nc('ncdb:3306');
    $out = $run();
    $ev = $events();
    $s = $status();
    $l = $log();
    same('db stopped: the run goes on and ends with warnings - Nextcloud\'s database unreachable, its dump skipped, both in the office\'s words', [
            'warnings', [['code' => 'db_unreachable', 'params' => ['app' => 'nc', 'container' => 'ncdb']], ['code' => 'dump_stopped', 'params' => ['container' => 'ncdb']]]],
        [$s['result'] ?? null, array_values(array_filter($s['warning_items'] ?? [], fn ($w) => str_starts_with($w['code'] ?? '', 'd')))], $out . $l);
    same('db stopped: occ never asked (config.php names the stopped container), no maintenance mode; Nextcloud stopped and started with the apps, '
        . 'the database left stopped, the others backed up', [[], false, true, [], true, true],
        [array_values(preg_grep('/^(exec nc php|occ )/', $ev)), file_exists("$fake/nc.maint") && trim((string) file_get_contents("$fake/nc.maint")) === 'true',
         in_array('docker stop nc', $ev, true) && in_array('docker start nc', $ev, true), array_values(preg_grep('/^docker (stop|start) ncdb$/', $ev)),
         in_array('docker stop c1', $ev, true) && in_array('zfs snapshot', $ev, true), str_contains($l, "WARNING: Nextcloud 'nc': its database 'ncdb' is not running - no maintenance mode")], json_encode($ev));
    $note = (string) @file_get_contents("$fake/notify.log");
    check('db stopped: a warning notification in the office\'s language (German), naming Nextcloud and its database; the run\'s end a warning, no alert',
        str_contains($note, 'Herr Backupsi: Die Datenbank von Nextcloud läuft nicht') && str_contains($note, 'Nextcloud «nc» wurde ohne Wartungsmodus gesichert: Seine Datenbank «ncdb» läuft nicht')
        && !str_contains($note, '-i alert'), $note);
    same('db stopped: the package keeps Nextcloud\'s config.php, no occ lists (occ answers nothing)', [true, []],
        [is_file("$mnt/user/UnraidSecretaryOffice/backup/apps/nc/nextcloud/nc_config.php"),
         array_map('basename', glob("$mnt/user/UnraidSecretaryOffice/backup/apps/nc/nextcloud/nc_occ-*") ?: [])]);

    // --- the database at an address the engine can't name: occ asked once (its database error ends the tries), the same warning without a name
    $night(['ncdb' => 'stopped']);
    $nc('192.168.7.9:3306');
    $out = $run();
    $ev = $events();
    $s = $status();
    same('db unreachable (an address): occ asked once, no retries; the run ends with warnings, db_unreachable_occ', [
            1, 'warnings', [['code' => 'db_unreachable_occ', 'params' => ['app' => 'nc']]], false],
        [count(preg_grep('/^occ refused maintenance:mode --on$/', $ev)), $s['result'] ?? null,
         array_values(array_filter($s['warning_items'] ?? [], fn ($w) => str_starts_with($w['code'] ?? '', 'db_'))), file_exists("$data/state/maintenance")], $out . $log());

    // --- occ refusing for any other reason: the run still ends there - with a code the office translates (up to 2.63 a plain English sentence)
    $night([]);
    @unlink("$fake/nc.dbdown");
    touch("$fake/nc.broken");
    $out = $run();
    $s = $status();
    same('occ refusing otherwise: the run fails, coded nc_maintenance_failed; the German notification says it in German', ['failed', 'nc_maintenance_failed', true],
        [$s['result'] ?? null, $s['message'] ?? null, str_contains((string) @file_get_contents("$fake/notify.log"), 'Nextcloud ging nicht in den Wartungsmodus')], $out . $log());
    exec('rm -rf ' . escapeshellarg($tmp));
}

function testBackupMovedPackage(): void
{
    $tmp = hardeningTmp('moved-package');
    $pool = "$tmp/backup";
    $man = fn (string $folder, string $run, array $cts, array $dirs) => ['interface' => 1, 'engine' => '2.59', 'kind' => 'app', 'name' => $folder, 'folder' => $folder,
        'run' => $run, 'result' => 'ok', 'files' => [], 'dirs' => $dirs,
        'containers' => array_map(fn ($c) => ['name' => $c, 'image' => "$c:1", 'image_id' => "sha256:$c", 'digests' => []], $cts)];
    $old = '20261006-0200';
    $now = '20261017-0200';
    $packs = [
        'drop'      => $man('drop', $old, ['drop', 'drop-share'], ['appdata/drop', 'drop']),
        'dropnook'  => $man('dropnook', $now, ['drop', 'drop-share'], ['appdata/drop', 'drop']),           // moved: same containers
        'half'      => $man('half', $old, ['half-a', 'half-b'], []),
        'halfnew'   => $man('halfnew', $now, ['half-a'], []),                                             // only part of it
        'oldsrc'    => $man('oldsrc', $old, ['src'], ['appdata/src']),
        'oldsrc2'   => $man('oldsrc2', $old, ['src'], ['appdata/src']),                                    // the other one stale too
        'renamed'   => $man('renamed', $old, ['r-old'], ['appdata/renamed', 'media']),
        'renamed2'  => $man('renamed2', $now, ['r-new'], ['appdata/renamed', 'media', 'appdata/more']),    // moved: same folder
        'shareonly' => $man('shareonly', $old, ['s-old'], ['drop2']),
        'sharenew'  => $man('sharenew', $now, ['s-new'], ['drop2']),                                       // a whole share alone: no
    ];
    foreach ($packs as $d => $m) {
        mkdir("$pool/apps/$d", 0700, true);
        file_put_contents("$pool/apps/$d/manifest.json", json_encode($m));
    }
    mkdir("$pool/server", 0700);
    file_put_contents("$pool/server/run.json", json_encode(['run' => $now]));
    $pk = backupPackagesRead($pool);
    same('moved package: the manifest\'s folders read (dirs)', ['appdata/drop', 'drop'], array_values(array_filter($pk['apps'], fn ($a) => $a['folder'] === 'drop'))[0]['dirs'] ?? null);
    $all = ['drop', 'drop-share', 'half-a', 'half-b', 'src', 'r-old', 'r-new', 's-old', 's-new'];             // every container there: none gone
    $got = backupGonePackages($pk, $all, [], []);
    same('moved package: offered - the same containers in a current package (drop → dropnook), the same own folder (renamed → renamed2); '
        . 'never when only part moved, against a stale package, by a whole share\'s folder alone',
        [['drop', 'dropnook', 'containers'], ['renamed', 'renamed2', 'folders']],
        array_map(fn ($g) => [$g['folder'], $g['moved_to'] ?? null, $g['signal'] ?? null], $got));
    same('moved package: … each as a gone package\'s row (kind, folder, name, path) plus where to and why', ['app', 'drop', 'drop', "$pool/apps/drop"],
        [$got[0]['kind'] ?? null, $got[0]['folder'] ?? null, $got[0]['name'] ?? null, $got[0]['path'] ?? null]);
    same('moved package: Docker not answering - still said (the manifests alone); old containers gone (a reinstall under new names) - moved, not gone; '
        . 'a current package that is gone itself takes nothing (drop and dropnook both gone)',
        [['drop', 'renamed'], [['drop', null], ['dropnook', null], ['renamed', 'renamed2']]],
        [array_column(backupGonePackages($pk, null, null, null), 'folder'),
         array_map(fn ($g) => [$g['folder'], $g['moved_to'] ?? null], backupGonePackages($pk, ['half-a', 'half-b', 'src', 's-old', 's-new', 'r-new'], [], []))]);
    // the Team Lead's hint names only what is gone
    $GLOBALS['backup'] = ['packages_gone' => $got];
    $f = array_values(array_filter(backupChecks(), fn ($x) => $x['id'] === 'package_gone'));
    unset($GLOBALS['backup']);
    same('moved package: the Team Lead\'s «gone» hint leaves a moved one out', is_file(BACKUP_DATA_DIR . '/settings.ini') ? [true, ''] : [null, null],
        [$f[0]['ok'] ?? null, $f[0]['params']['names'] ?? null]);
    hardeningRm($tmp);

    $de = json_decode((string) file_get_contents(OFFICE_WEB . '/desks/backup/lang/de.json'), true) ?: [];
    check('moved package: German words as the owner wrote them - which signal matched',
        str_contains($de['pk.moved_line.containers'] ?? '', 'seine Container werden jetzt als {other} gesichert') && str_contains($de['pk.moved_line.containers'] ?? '', 'das alte Paket kann in die Abstellkammer')
        && ($de['pk.signal.containers'] ?? '') === 'gleiche Container' && ($de['pk.signal.folders'] ?? '') === 'gleicher Ordner');
    $node = testsNode();
    if ($node === '') {
        check('moved package: node is missing here - skipped', true);
        return;
    }
    $tmp = hardeningTmp('moved-page');
    file_put_contents("$tmp/t.js", <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
const el = (tag, cls, text) => ({ tag, className: cls || '', textContent: text == null ? '' : String(text), children: [], dataset: {}, style: {},
  appendChild(c) { this.children.push(c); return c; }, append(...c) { this.children.push(...c); }, setAttribute() {}, focus() {} });
globalThis.Office = { scope: () => T, t: T, el, fmt: { size: (b) => b + ' B', date: (t) => 'D' + t }, desk: () => {}, places: () => {}, placesFrom: () => {},
  has: () => false, store: () => null, storeJson: () => null, agent: { running: true } };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const b = OFFICE_DESK_TESTS.backup;
const g = (folder, more) => ({ kind: 'app', folder, name: folder, path: '/x/' + folder, time: 1, ...more });
b.setState({ running: false, packages_gone: [g('paperless'), g('drop', { moved_to: 'dropnook', signal: 'containers' }), g('renamed', { moved_to: 'renamed2', signal: 'folders' })] });
const box = b.goneCallout();
console.log(JSON.stringify(box.children.map((n) => (n.tag === 'ul' ? n.children.map((li) => li.textContent) : n.textContent))));
JS);
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/backup/desk.js') . ' 2>&1');
    hardeningRm($tmp);
    same('moved package: the page - the gone ones, then the moved ones with their own intro, each line naming the other app and the signal',
        ['pk.gone_intro {"n":1}', ['pk.gone_line.app {"name":"paperless"}'], 'pk.moved_intro {"n":2}',
         ['pk.moved_line.containers {"name":"drop","other":"dropnook"}', 'pk.moved_line.folders {"name":"renamed","other":"renamed2"}']],
        json_decode($raw, true) ?? $raw);
}

/**
 * The office's search finds Mr. Backupsy's setup rows (2026-10-17: «immich», «Mediathek» found the main page's rows only):
 * the plan the page loaded is handed to his one provider (Office.placesTook(ID, plan, 'setup')), which names every share,
 * VM and app of it with its step's tile and its row's place - no request of its own, nothing per keystroke
 */
function testSetupSearch(): void
{
    $desk = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('setup search: the plan as the page loads it goes to the search, once per plan',
        str_contains($desk, "setupDraftKeep();\n    Office.placesTook(ID, j.plan, 'setup');") && substr_count($desk, 'Office.placesTook(ID, j.plan') === 1
        && substr_count($desk, 'Office.placesFrom(ID, ') === 1 && str_contains($desk, "if (part === 'setup') return setupSearchItems(s);"));
    check('setup search: no new call to the agent for it', !preg_match('/function setupSearchItems[\s\S]{0,1500}Office\.api/', $desk));
    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('setup search: node is missing here - skipped', true);
        return;
    }
    $tmp = hardeningTmp('setup-search');
    $plan = json_decode((string) file_get_contents(OFFICE_DIR . '/tests/ui/states/post/backup.setup_get.json'), true)['plan'];
    $plan['vms'] = [['name' => 'Windows 11', 'disks' => [], 'own' => [], 'running' => false]];
    file_put_contents("$tmp/plan.json", json_encode($plan));
    $js = <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
let provider = null;
const T = (k, p) => k + (p ? ' ' + JSON.stringify(p) : '');
globalThis.Office = { scope: () => T, t: T, el: () => ({}), fmt: { size: (b) => b + ' B', relative: () => 'now' }, desk: () => {}, places: () => {},
  placesFrom: (d, f) => { provider = f; }, placesTook: () => {}, selbar: () => {}, has: () => true };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const plan = JSON.parse(fs.readFileSync(process.argv[3], 'utf8'));
console.log(JSON.stringify({ setup: provider(plan, 'setup'), main: provider({ found: false }, null).length }));
JS;
    file_put_contents("$tmp/t.js", $js);
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/backup/desk.js') . ' ' . escapeshellarg("$tmp/plan.json") . ' 2>&1');
    hardeningRm($tmp);
    $r = json_decode($raw, true);
    if (!is_array($r)) {
        check('setup search: page ran under node', false, $raw);
        return;
    }
    $by = array_column($r['setup'], null, 'text');
    same('setup search: a share, a VM and an app (a stack) - each to its step\'s tile and its row, said as «Set up · <step>»', [
        ['setup.page · setup.shares', 'setup:share:media', '#/backup/setup/shares'],
        ['setup.page · setup.vms', 'setup:vm:Windows 11', '#/backup/setup/vms'],
        ['setup.page · setup.apps', 'setup:app:stack:immich', '#/backup/setup/apps', 'immich_server immich_redis immich_postgres']],
        [array_values(array_intersect_key($by['media'] ?? [], ['sub' => 1, 'anchor' => 1, 'route' => 1])), array_values(array_intersect_key($by['Windows 11'] ?? [], ['sub' => 1, 'anchor' => 1, 'route' => 1])),
         array_values(array_intersect_key($by['immich'] ?? [], ['sub' => 1, 'anchor' => 1, 'route' => 1, 'words' => 1]))]);
    same('setup search: every share that exists, every app; the main state\'s items unchanged (the provider\'s other part)',
        [10, true, 0], [count(array_filter($r['setup'], fn ($x) => str_starts_with($x['anchor'], 'setup:share:'))), isset($by['Grafana']), $r['main']]);
    // the rows carry those places
    check('setup search: the rows are marked with the places the items name',
        str_contains($desk, "Office.place('setup:share:' + sh.name, el('tr'))") && str_contains($desk, "Office.place('setup:vm:' + v.name,") && str_contains($desk, "Office.place('setup:app:' + a.id,"));
}

/**
 * The backup place's warnings: one question decides (owner 2026-10-17). A copy of the packages goes off-site (the place's
 * share to Kopia, or the place to a partner) - same pool, no mirror, no snapshots are one grey line «just so you know»;
 * not - one yellow line adding up the reasons that apply and what helps (none apply: a short «only local»). A secondary
 * storage stays a warning either way. It follows the draft, and the engine's place_not_kopia / place_no_history give way
 * to it in the setup's messages. Only in the setup: no new finding
 */
function testBackupPlaceVerdict(): void
{
    $node = trim((string) shell_exec('command -v node 2>/dev/null')) ?: (is_executable('/usr/local/bin/node') ? '/usr/local/bin/node' : '');
    if ($node === '') {
        check('place verdict: node is missing here - skipped', true);
        return;
    }
    $tmp = hardeningTmp('place-verdict');
    $js = <<<'JS'
const fs = require('fs');
globalThis.OFFICE_DESK_TESTS = {};
const T = (k, p) => (p ? `${k}(${Object.values(p).join('|')})` : k);
globalThis.Office = { scope: () => T, t: T, el: () => ({}), fmt: { size: (b) => b + ' B', relative: () => 'now' }, desk: () => {}, places: () => {}, placesFrom: () => {}, placesTook: () => {}, selbar: () => {}, has: () => true };
(0, eval)(fs.readFileSync(process.argv[2], 'utf8'));
const b = OFFICE_DESK_TESTS.backup;
const some = { name: 'Backups', partner_ok: true, place: [{ code: 'same_pool', where: 'cache' }, { code: 'no_redundancy', where: 'cache' }, { code: 'odd', where: 'x' }] };
const none = { name: 'Backups', partner_ok: true, place: [] };
const sec = { name: 'Backups', place: [{ code: 'secondary', where: '' }, { code: 'no_history', where: 'disk1' }] };
const out = {
  offsiteSome: b.placeVerdict(some, 'kopia'), offsiteNone: b.placeVerdict(none, 'kopia'), partnerSome: b.placeVerdict(some, { partner: 'Grosseltern' }),
  localSome: b.placeVerdict(some, null), localNone: b.placeVerdict(none, null),
  secLocal: b.placeVerdict(sec, null), secOffsite: b.placeVerdict(sec, 'kopia'),
  array: b.placeVerdict({ place: [{ code: 'no_redundancy', where: '' }] }, null), live: b.placeVerdict({ method: 'live' }, null), nothing: b.placeVerdict(null, null),
};
// the draft decides: Kopia on and the place's share at «local + offsite», or a partner for the place
b.setup.plan = { shares: [some], partners: [{ id: 'a1b2c3d4', name: 'Grosseltern' }], messages: [] };
b.setup.draft = { 'general|dumps_share': 'Backups', 'share|Backups|mode': 'snapshot', 'kopia|enabled': 'yes' };
out.draftLocal = b.placeOffsite(some);
b.setup.draft['share|Backups|mode'] = 'kopia';
out.draftKopia = b.placeOffsite(some);
b.setup.draft['kopia|enabled'] = 'no';
out.draftKopiaOff = b.placeOffsite(some);
b.setup.draft['share|Backups|mode'] = 'snapshot';
b.setup.draft['general|partner_place'] = ['a1b2c3d4'];
out.draftPartner = b.placeOffsite(some);
out.draftPartnerNotOk = b.placeOffsite({ ...some, partner_ok: false });
// the setup's messages: the engine's two place words give way to the verdict, where the first stood
delete b.setup.draft['general|partner_place'];
out.notes = b.placeNotes([{ level: 'ok', step: 'general', code: 'backup_place', items: [] }, { level: 'warn', step: 'general', code: 'place_not_kopia', items: [] },
  { level: 'warn', step: 'general', code: 'place_no_history', items: [] }, { level: 'hint', step: 'kopia', code: 'kopia_config', items: [] }])
  .map((g) => [g.level, g.code, g.items.map((i) => i.text).join('')]);
out.notesNone = b.placeNotes([{ level: 'ok', code: 'x', items: [] }]).length;
console.log(JSON.stringify(out));
JS;
    file_put_contents("$tmp/t.js", $js);
    $raw = (string) shell_exec(escapeshellarg($node) . ' ' . escapeshellarg("$tmp/t.js") . ' ' . escapeshellarg(OFFICE_WEB . '/desks/backup/desk.js') . ' 2>&1');
    hardeningRm($tmp);
    $r = json_decode($raw, true);
    if (!is_array($r)) {
        check('place verdict: page ran under node', false, $raw);
        return;
    }
    $reasons = 'setup.place_why.same_pool(cache), setup.place_why.no_redundancy(cache)';
    same('place verdict: off-site, reasons - one grey line «just so you know», the reasons named (Kopia, a partner)',
        [[['warn' => false, 'text' => "setup.place_info_kopia setup.place_info_reasons($reasons)"]],
         [['warn' => false, 'text' => "setup.place_info_partner(Grosseltern) setup.place_info_reasons($reasons)"]]], [$r['offsiteSome'], $r['partnerSome']]);
    same('place verdict: off-site, no reasons - nothing to say', [], $r['offsiteNone']);
    same('place verdict: only local, reasons - ONE yellow line: the reasons, the worst risk (the same pool), what helps',
        [['warn' => true, 'text' => "setup.place_only_here($reasons) setup.place_risk.same_pool setup.place_help"]], $r['localSome']);
    same('place verdict: only local, no reasons - a short yellow «only local»', [['warn' => true, 'text' => 'setup.place_local_only']], $r['localNone']);
    same('place verdict: a secondary storage stays a warning, off-site or not; the array without parity and a live share in words',
        [[['warn' => true, 'text' => 'setup.place_only_here(setup.place_why.no_history(disk1)) setup.place_help'], ['warn' => true, 'text' => 'setup.place_secondary(setup.place_array)']],
         [['warn' => false, 'text' => 'setup.place_info_kopia setup.place_info_reasons(setup.place_why.no_history(disk1))'], ['warn' => true, 'text' => 'setup.place_secondary(setup.place_array)']],
         [['warn' => true, 'text' => 'setup.place_only_here(setup.place_why.no_parity) setup.place_risk.no_redundancy setup.place_help']],
         [['warn' => true, 'text' => 'setup.place_only_here(setup.place_why.no_snapshots) setup.place_help']], []],
        [$r['secLocal'], $r['secOffsite'], $r['array'], $r['live'], $r['nothing']]);
    same('place verdict: it follows the draft - local; the share at «local + offsite» with Kopia on; Kopia off; a partner for the place (only a share that can travel)',
        [null, 'kopia', null, ['partner' => 'Grosseltern'], null], [$r['draftLocal'], $r['draftKopia'], $r['draftKopiaOff'], $r['draftPartner'], $r['draftPartnerNotOk']]);
    same('place verdict: the setup\'s messages - the engine\'s two place words give way to the verdict, where the first stood; without them nothing changes',
        [[['ok', 'backup_place', ''], ['warn', 'place_verdict', "setup.place_only_here($reasons) setup.place_risk.same_pool setup.place_help"], ['hint', 'kopia_config', '']], 1],
        [$r['notes'], $r['notesNone']]);
    $desk = (string) file_get_contents(OFFICE_WEB . '/desks/backup/desk.js');
    check('place verdict: on the place card (yellow or grey, never red), in the apply dialog, in the messages and their count, after an apply',
        str_contains($desk, "l.warn ? 'bk-place-warn' : 'bk-place-info', l.text") && str_contains($desk, "placeLines(placeRow()).forEach((l) => box.appendChild(el('p', l.warn ? 'callout warn' : 'role', l.text)));")
        && str_contains($desk, 'setupMessages(placeNotes(setupNotes(plan)))') && str_contains($desk, 'placeNotes(setupNotes(plan)).forEach') && str_contains($desk, 'placeNotes(setupNotes(run))'));
    check('place verdict: only in the setup - no finding of it', !preg_match("/finding\\('place_/", (string) file_get_contents(OFFICE_DIR . '/agent/desks/backup.php')));
}

